param(
    [string]$CloneBaseDir,
    [string]$WorkspaceRoot = '',
    [string[]]$Profile = @(),
    [string[]]$Component = @(),
    [string[]]$Exclude = @(),
    [ValidateSet('Auto', 'LCD', 'OLED')][string]$SteamDeckVersion = 'Auto',
    [string]$HostHealth,
    [string]$AppTuning,
    [string[]]$App = @(),
    [string[]]$AppTuningCategory = @(),
    [string[]]$AppTuningItem = @(),
    [string[]]$ExcludeAppTuningItem = @(),
    [string]$LogPath,
    [string]$ResultPath,
    [string]$SecretsImportPath,
    [string]$SecretsActivateProvider,
    [string]$SecretsActivateCredential,
    [switch]$ClaudeCodeProjectMcps,
    [switch]$Interactive,
    [switch]$ListProfiles,
    [switch]$ListHostHealthModes,
    [switch]$ListAppTuningCatalog,
    [switch]$ListApps,
    [switch]$ListComponents,
    [switch]$Doctor,
    [string[]]$DoctorScope = @('all'),
    [switch]$DriftCheck,
    [switch]$SupportBundle,
    [switch]$AiConfigDoctor,
    [switch]$AiConfigSync,
    [switch]$RepairPlan,
    [switch]$PartitionLabels,
    [switch]$ApplyPartitionLabels,
    [switch]$ReleasePack,
    [string]$ReleaseVersion = '',
    [string]$ReleaseOutputDir = '',
    [string]$ExecuteRepairPlan = '',
    [switch]$UiContractJson,
    [switch]$BootstrapUiLibraryMode,
    [switch]$SecretsList,
    [switch]$SecretsValidateAll,
    [switch]$RotateSecrets,
    [string]$RotateSecretsProvider = '',
    [int]$RotateSecretsMaxItems = 10,
    [int]$RotateSecretsTimeoutSeconds = 120,
    [ValidateSet('none', 'daily', 'weekly')][string]$RotateSecretsSchedule = '',
    [switch]$DryRun,
    [switch]$NonInteractive,
    [switch]$SkipManualRequirements,
    [switch]$IgnoreManualRequirements,
    [switch]$RequireNoPendingReboot,
    [switch]$AllowPendingReboot,
    [switch]$Resume,
    [switch]$Rollback,
    [string]$ChangesPath,
    [switch]$AggressiveRollback,
    [switch]$Offline,
    [string]$CacheDir = '',
    [switch]$Audit,
    [switch]$AutoRollback,
    [switch]$Repair,
    [ValidateRange(1, 3600)][int]$AuditTimeoutSeconds = 180,
    [ValidateRange(1, 600)][int]$AuditComponentTimeoutSeconds = 30
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
Set-StrictMode -Version Latest
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$OutputEncoding = [Console]::OutputEncoding

$script:StartTime = Get-Date
$script:RunId = ('{0:yyyyMMdd_HHmmss}_{1}_{2}' -f $script:StartTime, $PID, ([Guid]::NewGuid().ToString('N').Substring(0, 8)))
try {
    $tempRoot = $env:TEMP
    if ([string]::IsNullOrWhiteSpace($tempRoot)) { $tempRoot = $env:TMP }
    if ([string]::IsNullOrWhiteSpace($tempRoot)) { $tempRoot = [Environment]::GetFolderPath('LocalApplicationData') }
    if ([string]::IsNullOrWhiteSpace($tempRoot)) { $tempRoot = (Get-Location).Path }

    $script:LogPath = if ([string]::IsNullOrWhiteSpace($LogPath)) { Join-Path $tempRoot ("bootstrap-tools_{0}.log" -f $script:RunId) } else { $LogPath }
    $script:ResultPath = if ([string]::IsNullOrWhiteSpace($ResultPath) -and -not [bool]$BootstrapUiLibraryMode) { Join-Path $tempRoot ("bootstrap-tools_{0}.result.json" -f $script:RunId) } else { $ResultPath }
    $script:LogParent = Split-Path -Path $script:LogPath -Parent
    if ($script:LogParent) { $null = New-Item -Path $script:LogParent -ItemType Directory -Force -ErrorAction Stop }
} catch {
    $script:LogPath = $LogPath
    $script:ResultPath = $ResultPath
    $script:LogParent = $null
}
$script:SkipManualRequirements = $SkipManualRequirements
$script:IgnoreManualRequirements = $IgnoreManualRequirements
$script:RequireNoPendingReboot = [bool]$RequireNoPendingReboot
$script:AllowPendingReboot = [bool]$AllowPendingReboot
$script:SuppressConsoleLog = [bool]$BootstrapUiLibraryMode
$script:BootstrapSecretsProviderCatalogCache = $null
$script:BootstrapAppCapabilityCatalogCache = $null
$script:BootstrapManagedMcpCatalogCache = $null

try {
    $sp = [Net.ServicePointManager]::SecurityProtocol
    [Net.ServicePointManager]::SecurityProtocol = $sp -bor [Net.SecurityProtocolType]::Tls12
} catch {
}

function Normalize-BootstrapPathSegment {
    <#
    .SYNOPSIS
        Reduz caminho ou segmento a uma unica string escalar para Join-Path/Split-Path.
        Evita erro PS 5.1: ChildPath como Object[] quando um ramo anterior devolveu coleção.
    #>
    param([AllowNull()][object]$Value)
    if ($null -eq $Value) { return '' }
    $arr = @($Value)
    if ($arr.Count -eq 0) { return '' }
    $first = $arr[0]
    if ($null -eq $first) { return '' }
    return ([string]$first).Trim()
}

function Get-BootstrapSpecialFolderEnv {
    param([Parameter(Mandatory = $true)][string]$EnvironmentName)
    $v = [Environment]::GetEnvironmentVariable($EnvironmentName, 'Machine')
    if ([string]::IsNullOrWhiteSpace($v)) { $v = [Environment]::GetEnvironmentVariable($EnvironmentName, 'Process') }
    if ([string]::IsNullOrWhiteSpace($v)) { $v = [Environment]::GetEnvironmentVariable($EnvironmentName, 'User') }
    return (Normalize-BootstrapPathSegment -Value $v)
}

function Write-BootstrapExceptionStackTrace {
    param([Parameter(Mandatory = $true)]$ErrorRecord)
    try {
        $stk = [string]$ErrorRecord.ScriptStackTrace
        if ([string]::IsNullOrWhiteSpace($stk)) { return }
        if ($stk.Length -gt 3500) { $stk = $stk.Substring(0, 3497) + '...' }
        Write-Log ("StackTrace: {0}" -f $stk) 'ERROR'
    } catch {
    }
}

function Get-BootstrapErrorRecordStackTraceText {
    param([AllowNull()]$ErrorRecord)
    if ($null -eq $ErrorRecord) { return '' }
    try {
        $stk = [string]$ErrorRecord.ScriptStackTrace
        if ([string]::IsNullOrWhiteSpace($stk)) { return '' }
        if ($stk.Length -gt 8000) { $stk = $stk.Substring(0, 7997) + '...' }
        return $stk
    } catch {
        return ''
    }
}

function Write-BootstrapExecutionErrorResultFromRecord {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [AllowNull()]$ErrorRecord,
        [hashtable]$Extra = @{}
    )

    if ([string]::IsNullOrWhiteSpace($Path)) { return }
    $msg = if ($ErrorRecord -and $ErrorRecord.Exception) { [string]$ErrorRecord.Exception.Message } else { 'unknown error' }
    $stk = Get-BootstrapErrorRecordStackTraceText -ErrorRecord $ErrorRecord
    $blockedInfo = Get-BootstrapBlockedErrorInfo -ErrorRecord $ErrorRecord
    $status = if ($blockedInfo.IsBlocked) { 'blocked' } else { 'error' }
    $payload = [ordered]@{
        status = $status
        generatedAt = (Get-Date).ToString('o')
        logPath = $script:LogPath
        resultPath = $Path
        error = $msg
        scriptStackTrace = $stk
    }
    if ($blockedInfo.IsBlocked) {
        $payload.blockerKind = [string]$blockedInfo.Kind
        $payload.action = [string]$blockedInfo.Action
        $payload.blockerReasons = @($blockedInfo.Reasons)
        if (-not $Extra.ContainsKey('howToFix')) {
            $fix = ''
            if ([string]$blockedInfo.Kind -eq 'pending-reboot-msi' -or [string]$blockedInfo.Action -eq 'restart-required') {
                $fix = 'Reinicie o Windows e execute novamente.'
            } elseif ([string]$blockedInfo.Kind -eq 'winget-post-install-unverified') {
                $fix = 'Abra o log. Se o pacote instalou fora do escopo do usuário, execute elevado e tente novamente. Se ProbePaths/Appx estiverem errados, ajuste o componente ou instale manualmente.'
            } elseif ([string]$blockedInfo.Kind -eq 'winget-ghost-unresolved') {
                $fix = 'Remova/repare o pacote manualmente (Apps e Recursos/winget uninstall) e execute novamente.'
            } elseif ([string]$blockedInfo.Kind -eq 'winget-msi-busy') {
                $fix = 'Feche instaladores pendentes (msiexec/winget) ou reinicie o Windows e execute novamente.'
            } elseif ([string]$blockedInfo.Kind -eq 'git-global-config-locked') {
                $fix = 'Feche Git Bash, shells, VS Code e outros processos Git que possam usar ~/.gitconfig; confirme permissao de escrita no arquivo e execute novamente.'
            } else {
                $fix = 'Revise o erro no log/result, aplique a ação indicada e execute novamente.'
            }
            $payload.howToFix = $fix
        }
    }
    foreach ($k in $Extra.Keys) {
        $payload[$k] = $Extra[$k]
    }
    try {
        Write-BootstrapExecutionResultFile -Path $Path -Value $payload
    } catch {
        try {
            Write-Log ("Falha ao gravar result.json de erro: {0}" -f $_.Exception.Message) 'ERROR'
        } catch {
        }
    }
    if ($ErrorRecord -and -not $blockedInfo.IsBlocked) {
        Write-BootstrapExceptionStackTrace -ErrorRecord $ErrorRecord
    }
}

function Write-Log {
    param(
        [Parameter(Mandatory = $true)][string]$Message,
        [ValidateSet('INFO', 'WARN', 'ERROR')][string]$Level = 'INFO'
    )
    $line = "[{0:yyyy-MM-dd HH:mm:ss}] [{1}] {2}" -f (Get-Date), $Level, $Message
    $logFile = Normalize-BootstrapPathSegment -Value $script:LogPath
    if (-not [string]::IsNullOrWhiteSpace($logFile)) {
        try {
            $logParent = Split-Path -Path $logFile -Parent
            if ($logParent -and -not (Test-Path $logParent)) { $null = New-Item -Path $logParent -ItemType Directory -Force }
            # Cross-process mutex protects against torn lines when child PS processes
            # (e.g., dry-run probes, parallel jobs) write to the same log concurrently.
            $mutexName = 'Global\PhaseZeroBootstrapLog_' + ([System.IO.Path]::GetFileName($logFile))
            $mutex = $null
            $haveLock = $false
            try {
                $mutex = New-Object System.Threading.Mutex($false, $mutexName)
                $haveLock = $mutex.WaitOne(2000)
                Add-Content -Path $logFile -Value $line -Encoding utf8 -ErrorAction SilentlyContinue
            } catch [System.Threading.AbandonedMutexException] {
                $haveLock = $true
                Add-Content -Path $logFile -Value $line -Encoding utf8 -ErrorAction SilentlyContinue
            } finally {
                if ($mutex) {
                    if ($haveLock) { try { $mutex.ReleaseMutex() } catch { } }
                    try { $mutex.Dispose() } catch { }
                }
            }
        } catch { }
    }
    if (-not [bool]$script:SuppressConsoleLog) {
        Write-Host $line
    }
}

function Get-BootstrapFreeSpace {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return 0 }
    try {
        # Resolve relative paths first so we don't substring "."
        try {
            $resolved = (Resolve-Path -LiteralPath $Path -ErrorAction SilentlyContinue).Path
            if ($resolved) { $Path = $resolved }
        } catch { }

        # UNC paths (\\server\share\...): use DirectoryInfo + DriveInfo bypass via WMI
        if ($Path.StartsWith('\\')) {
            try {
                $diskInfo = New-Object System.IO.DriveInfo($Path)
                if ($diskInfo -and $diskInfo.IsReady) {
                    return [Math]::Round($diskInfo.AvailableFreeSpace / 1GB, 2)
                }
            } catch { }
            return 0
        }

        # Local paths: take the leading drive letter (handles "C:", "C:\", "C:\foo")
        if ($Path.Length -lt 2 -or $Path[1] -ne ':') { return 0 }
        $driveLetter = $Path.Substring(0, 1)
        $drive = Get-PSDrive -Name $driveLetter -ErrorAction SilentlyContinue
        if ($drive -and ($drive.Free -or $drive.Free -eq 0)) {
            return [Math]::Round(($drive.Free / 1GB), 2)
        }
        # Fallback to System.IO.DriveInfo when PSDrive lacks Free (mapped drives, etc.)
        try {
            $diskInfo = New-Object System.IO.DriveInfo($driveLetter + ':\')
            if ($diskInfo -and $diskInfo.IsReady) {
                return [Math]::Round($diskInfo.AvailableFreeSpace / 1GB, 2)
            }
        } catch { }
    } catch { }
    return 0
}

function Test-BootstrapDiskSpace {
    param(
        [object]$Selection,
        [string[]]$ResolvedComponents,
        [string]$ResolvedWorkspaceRoot
    )
    $minSystemGB = 2.0
    $minWorkspaceGB = 1.0
    $componentCount = @($ResolvedComponents).Count
    $profileCount = 0
    $selectionComponentCount = 0
    $appTuningSelectionCount = 0
    try { $profileCount = @($Selection.Profiles).Count } catch { $profileCount = 0 }
    try { $selectionComponentCount = @($Selection.Components).Count } catch { $selectionComponentCount = 0 }
    try { $appTuningSelectionCount += @($Selection.AppTuningItems).Count } catch { }
    try { $appTuningSelectionCount += @($Selection.AppTuningCategories).Count } catch { }
    $configOnlyAppTuning = ($componentCount -eq 0 -and $profileCount -eq 0 -and $selectionComponentCount -eq 0 -and $appTuningSelectionCount -gt 0)

    if (@($Selection.Profiles) -contains 'full') {
        $minSystemGB = 15.0
        $minWorkspaceGB = 5.0
    } elseif ($ResolvedComponents.Count -gt 50) {
        $minSystemGB = 10.0
    } elseif ($configOnlyAppTuning) {
        $minSystemGB = 0.1
        $minWorkspaceGB = 0.1
        Write-Log 'Preflight: ajuste/configuração sem instalação detectado; usando limite mínimo de disco reduzido.'
    }

    $systemFree = Get-BootstrapFreeSpace -Path $env:SystemDrive
    if ($systemFree -lt $minSystemGB) {
        Write-Log ("Espaco em disco insuficiente no sistema (C:). Disponivel: {0}GB, Necessario: {1}GB" -f $systemFree, $minSystemGB) 'WARN'
        if (-not $script:DryRun) { throw "Espaco em disco insuficiente no sistema (C:). Limpe o disco e tente novamente." }
    } else {
        Write-Log ("Espaco em disco OK no sistema (C:): {0}GB disponivel." -f $systemFree)
    }

    if (-not [string]::IsNullOrWhiteSpace($ResolvedWorkspaceRoot) -and (Test-Path $ResolvedWorkspaceRoot)) {
        $workspaceFree = Get-BootstrapFreeSpace -Path $ResolvedWorkspaceRoot
        if ($workspaceFree -lt $minWorkspaceGB) {
            Write-Log ("Espaco em disco insuficiente no WorkspaceRoot ({0}). Disponivel: {1}GB, Necessario: {2}GB" -f $ResolvedWorkspaceRoot, $workspaceFree, $minWorkspaceGB) 'WARN'
        }
    }
}

function Assert-BootstrapDiskSpace {
    param(
        [double]$RequiredGB,
        [string]$Path = $env:SystemDrive
    )
    if ($RequiredGB -le 0) { return }
    $safetyBuffer = 1.0
    $totalRequired = $RequiredGB + $safetyBuffer
    $free = Get-BootstrapFreeSpace -Path $Path
    if ($free -lt $totalRequired) {
        throw ("Espaco em disco insuficiente para continuar operacao. Necessario: {0}GB (incluindo buffer), Disponivel: {1}GB em {2}" -f $totalRequired, $free, $Path)
    }
}

function Get-BootstrapCheckpointPath {
    $dataRoot = Normalize-BootstrapPathSegment -Value (Get-BootstrapDataRoot)
    return (Join-Path -Path $dataRoot -ChildPath 'checkpoint.json')
}

function Save-BootstrapCheckpoint {
    param(
        [object]$Selection,
        [string[]]$CompletedComponents,
        [object[]]$AppTuningResults = @(),
        [object[]]$HostHealthResults = @()
    )
    try {
        $path = Get-BootstrapCheckpointPath
        $parent = Split-Path $path -Parent
        if (-not (Test-Path $parent)) { $null = New-Item -Path $parent -ItemType Directory -Force }

        $checkpoint = [ordered]@{
            ProfileSelection = $Selection.Profiles
            ComponentSelection = $Selection.Components
            CompletedComponents = @($CompletedComponents)
            AppTuningResults = @($AppTuningResults)
            HostHealthResults = @($HostHealthResults)
            Timestamp = (Get-Date).ToString('o')
        }
        $json = $checkpoint | ConvertTo-Json -Depth 12
        Write-BootstrapAtomicText -Path $path -Content $json
    } catch {
        Write-Log ("Falha ao salvar checkpoint: {0}" -f $_.Exception.Message) 'WARN'
    }
}

function Load-BootstrapCheckpoint {
    $path = Get-BootstrapCheckpointPath
    if (Test-Path $path) {
        try {
            return Get-Content $path -Raw | ConvertFrom-Json
        } catch { }
    }
    return $null
}

function Invoke-BootstrapRollback {
    param(
        [string]$ChangesPath = '',
        [switch]$AggressiveRollback,
        [switch]$DryRun
    )

    $plannedActions = New-Object System.Collections.Generic.List[object]

    if (-not [string]::IsNullOrWhiteSpace($ChangesPath) -and (Test-Path -LiteralPath $ChangesPath)) {
        Write-Log ("Iniciando Rollback por manifesto: {0}" -f $ChangesPath) 'WARN'
        $manifest = Read-BootstrapJsonFile -Path $ChangesPath
        $changes = @($manifest.changes)
        if ($changes.Count -gt 1) { $changes = $changes[($changes.Count - 1)..0] }
        foreach ($change in $changes) {
            $type = [string]$change.Type
            $target = [string]$change.Target
            $name = [string]$change.Name
            try {
                if ($DryRun) {
                    $plannedActions.Add([ordered]@{
                        type = $type
                        target = $target
                        name = $name
                        rollbackAction = if ($change.PSObject.Properties.Name -contains 'RollbackAction') { [string]$change.RollbackAction } else { '' }
                        component = if ($change.PSObject.Properties.Name -contains 'Component') { [string]$change.Component } else { '' }
                    })
                    Write-Log ("DRY-RUN Rollback manifest {0}: {1}" -f $type, $target)
                    continue
                }
                switch ($type) {
                    'Registry' {
                        if ([string]::IsNullOrWhiteSpace($target) -or [string]::IsNullOrWhiteSpace($name)) { continue }
                        if ($null -eq $change.OldValue) {
                            # Idempotent: silently no-op if the property was already removed.
                            Remove-ItemProperty -Path $target -Name $name -ErrorAction SilentlyContinue
                        } else {
                            if (-not (Test-Path $target)) {
                                try { $null = New-Item -Path $target -Force -ErrorAction Stop } catch {
                                    Write-Log ("Rollback manifest Registry: nao foi possivel criar a chave {0}: {1}" -f $target, $_.Exception.Message) 'WARN'
                                    continue
                                }
                            }
                            # Use SilentlyContinue so a hive-level access denial doesn't break later changes.
                            Set-ItemProperty -Path $target -Name $name -Value $change.OldValue -Force -ErrorAction SilentlyContinue
                        }
                        Write-Log ("Rollback manifest Registry: {0}\{1}" -f $target, $name)
                    }
                    'EnvVar' {
                        [Environment]::SetEnvironmentVariable($target, $change.OldValue, 'User')
                        Write-Log ("Rollback manifest EnvVar: {0}" -f $target)
                    }
                    'Path' {
                        if (-not [string]::IsNullOrWhiteSpace([string]$change.OldValue)) {
                            [Environment]::SetEnvironmentVariable('Path', [string]$change.OldValue, 'User')
                            Write-Log 'Rollback manifest PATH restaurado.'
                        }
                    }
                    'File' {
                        $backup = [string]$change.OldValue
                        if (-not [string]::IsNullOrWhiteSpace($backup) -and (Test-Path -LiteralPath $backup)) {
                            Copy-Item -LiteralPath $backup -Destination $target -Force
                            Write-Log ("Rollback manifest File restaurado: {0}" -f $target)
                        } elseif (Test-Path -LiteralPath $target) {
                            Remove-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue
                            Write-Log ("Rollback manifest File removido: {0}" -f $target)
                        }
                    }
                    'Directory' {
                        if (Test-Path -LiteralPath $target) {
                            $items = @(Get-ChildItem -LiteralPath $target -Force -ErrorAction SilentlyContinue)
                            if ($items.Count -eq 0) {
                                Remove-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue
                                Write-Log ("Rollback manifest Directory vazio removido: {0}" -f $target)
                            } else {
                                Write-Log ("Rollback manifest Directory nao vazio; remocao manual: {0}" -f $target) 'WARN'
                            }
                        }
                    }
                    'Service' {
                        if ([string]::IsNullOrWhiteSpace($target)) { continue }
                        $oldState = ConvertTo-BootstrapHashtable -InputObject $change.OldValue
                        $oldStartType = if ($oldState -is [hashtable] -and $oldState.ContainsKey('StartType')) { [string]$oldState['StartType'] } else { [string]$change.OldValue }
                        $oldStatus = if ($oldState -is [hashtable] -and $oldState.ContainsKey('Status')) { [string]$oldState['Status'] } else { '' }
                        if (-not [string]::IsNullOrWhiteSpace($oldStartType)) {
                            Set-Service -Name $target -StartupType $oldStartType -ErrorAction SilentlyContinue
                            Write-Log ("Rollback manifest Service: {0} StartupType={1}" -f $target, $oldStartType)
                        }
                        if ($oldStatus -eq 'Running') {
                            Start-Service -Name $target -ErrorAction SilentlyContinue
                            Write-Log ("Rollback manifest Service started: {0}" -f $target)
                        } elseif ($oldStatus -eq 'Stopped') {
                            Stop-Service -Name $target -ErrorAction SilentlyContinue
                            Write-Log ("Rollback manifest Service stopped: {0}" -f $target)
                        }
                    }
                    'DefenderExclusion' {
                        if ([string]::IsNullOrWhiteSpace($target)) { continue }
                        $kind = if ([string]::IsNullOrWhiteSpace($name)) { 'ExclusionPath' } else { $name }
                        if ($kind -eq 'ExclusionProcess') {
                            Remove-MpPreference -ExclusionProcess $target -ErrorAction SilentlyContinue
                        } else {
                            Remove-MpPreference -ExclusionPath $target -ErrorAction SilentlyContinue
                        }
                        Write-Log ("Rollback manifest DefenderExclusion: {0} {1}" -f $kind, $target)
                    }
                    'Package' {
                        $action = ''
                        if ($change.PSObject.Properties.Name -contains 'RollbackAction') { $action = [string]$change.RollbackAction }
                        if ($action -ne 'winget-uninstall') {
                            Write-Log ("Rollback manifest Package: acao '{0}' nao automatizada para {1}; remova manualmente." -f $action, $target) 'WARN'
                            continue
                        }
                        if ([string]::IsNullOrWhiteSpace($target)) {
                            Write-Log 'Rollback manifest Package: Target vazio; pulando.' 'WARN'
                            continue
                        }
                        $winget = $null
                        try { $winget = Get-Winget } catch { $winget = $null }
                        if (-not $winget) {
                            Write-Log ("Rollback manifest Package: winget indisponivel; nao foi possivel desinstalar {0}." -f $target) 'WARN'
                            continue
                        }
                        $uninstallArgs = @('uninstall', '-e', '--id', $target, '--purge', '--disable-interactivity')
                        try {
                            $exit = Invoke-NativeWithLog -Exe $winget -Args $uninstallArgs
                            if ($exit -eq 0 -or ($script:WingetUninstallSoftSuccessExitCodes -contains $exit)) {
                                Write-Log ("Rollback manifest Package removido: {0}" -f $target)
                            } else {
                                Write-Log ("Rollback manifest Package: winget uninstall {0} retornou exit={1}." -f $target, $exit) 'WARN'
                            }
                        } catch {
                            Write-Log ("Rollback manifest Package: excecao ao desinstalar {0}: {1}" -f $target, $_.Exception.Message) 'WARN'
                        }
                    }
                    default {
                        if ($AggressiveRollback) {
                            Write-Log ("Rollback agressivo ainda nao implementado para {0}: {1}" -f $type, $target) 'WARN'
                        } else {
                            Write-Log ("Rollback manual recomendado para {0}: {1}" -f $type, $target) 'WARN'
                        }
                    }
                }
            } catch {
                Write-Log ("Falha no rollback manifest ({0} {1}): {2}" -f $type, $target, $_.Exception.Message) 'WARN'
            }
        }
        if ($DryRun) {
            Write-Log 'DRY-RUN Rollback por manifesto planejado.'
            return [ordered]@{
                status = 'planned'
                dryRun = $true
                changesPath = $ChangesPath
                plannedActions = @($plannedActions.ToArray())
            }
        } else {
            Write-Log 'Rollback por manifesto concluido.'
            return [ordered]@{
                status = 'success'
                dryRun = $false
                changesPath = $ChangesPath
                plannedActions = @()
            }
        }
    }

    Write-Log 'Iniciando Rollback das alteracoes de sistema...' 'WARN'

    if ($DryRun) {
        foreach ($item in @(
            [ordered]@{ type = 'Registry'; target = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager'; name = 'SystemPaneSuggestionsEnabled' },
            [ordered]@{ type = 'Registry'; target = 'HKCU:\Software\Microsoft\Edge\Main'; name = 'AllowPrelaunch' },
            [ordered]@{ type = 'Registry'; target = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameGPT'; name = 'GameModeEnabled' },
            [ordered]@{ type = 'Registry'; target = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'; name = 'MimoModeWatcher' },
            [ordered]@{ type = 'Registry'; target = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'; name = 'OpenCodeDesktop' }
        )) {
            $plannedActions.Add($item)
        }
        Write-Log 'DRY-RUN Rollback legado planejado.'
        return [ordered]@{
            status = 'planned'
            dryRun = $true
            changesPath = $ChangesPath
            plannedActions = @($plannedActions.ToArray())
        }
    }

    # 1. Reverter Tweaks de Registro
    Write-Log 'Revertendo tweaks de registro (ContentDeliveryManager, Edge, GameMode)...'
    $registryTweaks = @(
        @{ Path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager'; Name = 'SystemPaneSuggestionsEnabled'; Value = 1 }
        @{ Path = 'HKCU:\Software\Microsoft\Edge\Main'; Name = 'AllowPrelaunch'; Value = 1 }
        @{ Path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameGPT'; Name = 'GameModeEnabled'; Value = 0 }
    )

    foreach ($t in $registryTweaks) {
        if (Test-Path $t.Path) {
            Set-ItemProperty -Path $t.Path -Name $t.Name -Value $t.Value -ErrorAction SilentlyContinue
        }
    }

    # 2. Remover Autostarts conhecidos (Mimo, OpenCode)
    Write-Log 'Removendo entradas de inicializacao automatica criadas pelo script...'
    $runPath = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
    foreach ($name in @('MimoModeWatcher', 'OpenCodeDesktop')) {
        Remove-ItemProperty -Path $runPath -Name $name -ErrorAction SilentlyContinue
    }

    Write-Log 'Rollback concluido. Algumas alteracoes (como instalacoes de apps) devem ser removidas manualmente via Painel de Controle/winget.'
    return [ordered]@{
        status = 'success'
        dryRun = $false
        changesPath = $ChangesPath
        plannedActions = @()
    }
}

function Register-BootstrapChange {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][ValidateSet('Registry', 'File', 'Directory', 'Path', 'EnvVar', 'Package', 'NpmGlobal', 'UvTool', 'ChocolateyPackage', 'Shortcut', 'Task', 'Service', 'DefenderExclusion', 'Clone', 'SecretsRotation', 'WindowsFeature', 'WindowsCapability', 'FirewallRule', 'VolumeLabel')][string]$Type,
        [Parameter(Mandatory = $true)][string]$Target,
        [AllowNull()]$OldValue,
        [string]$Name,
        [AllowNull()]$NewValue = $null,
        [string]$Operation = '',
        [string]$RollbackAction = '',
        [string]$Reversible = '',
        [string]$Component = ''
    )
    if ([string]::IsNullOrWhiteSpace($Component) -and $State.ContainsKey('CurrentComponent')) {
        $Component = [string]$State.CurrentComponent
    }
    if ([string]::IsNullOrWhiteSpace($Operation)) { $Operation = $Type }
    if ([string]::IsNullOrWhiteSpace($RollbackAction)) {
        $RollbackAction = switch ($Type) {
            'Registry' { 'restore-registry-value' }
            'File' { 'restore-or-remove-file' }
            'Directory' { 'remove-created-directory-if-safe' }
            'Path' { 'restore-path-string' }
            'EnvVar' { 'restore-env-var' }
            'Service' { 'restore-service-state' }
            'DefenderExclusion' { 'remove-defender-exclusion' }
            'SecretsRotation' { 'restore-active-credential' }
            'FirewallRule' { 'remove-firewall-rule' }
            'VolumeLabel' { 'restore-volume-label' }
            default { 'manual-review' }
        }
    }
    if ([string]::IsNullOrWhiteSpace($Reversible)) {
        $Reversible = if ($Type -in @('Registry', 'File', 'Directory', 'Path', 'EnvVar', 'Shortcut', 'Task', 'Service', 'Clone', 'SecretsRotation', 'VolumeLabel')) { 'partial' } else { 'manual' }
    }
    $change = [ordered]@{
        Type = $Type
        Component = $Component
        Operation = $Operation
        Target = $Target
        OldValue = $OldValue
        NewValue = $NewValue
        Name = $Name
        RollbackAction = $RollbackAction
        Reversible = $Reversible
        Timestamp = (Get-Date).ToString('o')
    }
    $State.Changes.Add($change)
    Save-BootstrapChangeManifest -State $State
}

function Register-BootstrapFileChange {
    # Registra uma mutacao de arquivo com BACKUP do conteudo atual ANTES da escrita. Deve ser
    # chamada antes de gravar/sobrescrever o alvo para que o rollback restaure o original (e nao
    # apague um config pre-existente). Se o arquivo nao existir, o rollback apenas remove o criado.
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][string]$Target,
        [string]$Operation = 'file-update',
        [string]$Component = '',
        [AllowNull()]$NewValue = $null
    )

    $oldValue = $null
    if (Test-Path -LiteralPath $Target) {
        $manifestPath = Get-BootstrapChangeManifestPath -State $State
        $backupRoot = Join-Path (Split-Path -Path $manifestPath -Parent) 'file-backups'
        $null = New-Item -Path $backupRoot -ItemType Directory -Force
        $leaf = Split-Path -Path $Target -Leaf
        if ([string]::IsNullOrWhiteSpace($leaf)) { $leaf = 'file' }
        $backupPath = Join-Path $backupRoot ("{0}-{1}.bak" -f ([Guid]::NewGuid().ToString('N')), $leaf)
        Copy-Item -LiteralPath $Target -Destination $backupPath -Force -ErrorAction Stop
        $oldValue = $backupPath
    }

    $rollbackAction = if ($oldValue) { 'restore-file-backup' } else { 'remove-created-file' }
    Register-BootstrapChange -State $State -Type File -Target $Target -OldValue $oldValue -NewValue $NewValue -Operation $Operation -Component $Component -RollbackAction $rollbackAction -Reversible 'partial'
}

function Get-BootstrapChangeManifestPath {
    param([Parameter(Mandatory = $true)][hashtable]$State)
    if (-not [string]::IsNullOrWhiteSpace([string]$State.ChangeManifestPath)) { return [string]$State.ChangeManifestPath }
    $root = Normalize-BootstrapPathSegment -Value (Get-BootstrapDataRoot)
    if ([string]::IsNullOrWhiteSpace($root)) {
        throw 'Get-BootstrapChangeManifestPath: DataRoot vazio apos normalizacao; defina BOOTSTRAP_DATA_ROOT ou verifique permissoes.'
    }
    $runId = Normalize-BootstrapPathSegment -Value $State.RunId
    if ([string]::IsNullOrWhiteSpace($runId)) { $runId = $script:RunId }
    $runsDir = Join-Path -Path $root -ChildPath 'runs'
    $path = Join-Path -Path $runsDir -ChildPath (Join-Path -Path $runId -ChildPath 'changes.json')
    $State.ChangeManifestPath = $path
    return $path
}

function Get-BootstrapChangesSummary {
    param([Parameter(Mandatory = $true)][hashtable]$State)
    $changes = @($State.Changes.ToArray())
    $byType = [ordered]@{}
    foreach ($change in $changes) {
        $type = [string]$change.Type
        if ([string]::IsNullOrWhiteSpace($type)) { $type = 'Unknown' }
        if (-not $byType.Contains($type)) { $byType[$type] = 0 }
        $byType[$type]++
    }
    $reversible = @($changes | Where-Object { [string]$_['Reversible'] -in @('full', 'partial') }).Count
    $manual = @($changes | Where-Object { [string]$_['Reversible'] -in @('manual', 'none', '') }).Count
    return [ordered]@{
        total = $changes.Count
        reversible = $reversible
        manual = $manual
        byType = $byType
    }
}

function Save-BootstrapChangeManifest {
    param([Parameter(Mandatory = $true)][hashtable]$State)
    try {
        $path = Get-BootstrapChangeManifestPath -State $State
        Write-BootstrapJsonFile -Path $path -Value ([ordered]@{
            generatedAt = (Get-Date).ToString('o')
            runId = [string]$State.RunId
            workspaceRoot = [string]$State.WorkspaceRoot
            cloneBaseDir = [string]$State.CloneBaseDir
            summary = Get-BootstrapChangesSummary -State $State
            changes = @($State.Changes.ToArray())
        })
    } catch {
        try { Write-Log ("Falha ao salvar manifesto de mudancas: {0}" -f $_.Exception.Message) 'WARN' } catch { }
    }
}

function Invoke-BootstrapAutoRollback {
    param([Parameter(Mandatory = $true)]$State)

    if (-not $State.Changes -or $State.Changes.Count -eq 0) {
        Write-Log 'Nenhuma alteracao registrada para rollback automatico.'
        return
    }

    $count = $State.Changes.Count
    Write-Log "Iniciando Rollback Automatico de $count alteracoes..." 'WARN'

    # Inverter ordem das mudancas
    $changes = $State.Changes.ToArray()
    if ($changes.Count -gt 1) {
        $changes = $changes[($changes.Count - 1)..0]
    }

    foreach ($change in $changes) {
        try {
            switch ($change.Type) {
                'Registry' {
                    $target = $change.Target
                    $name = $change.Name
                    Write-Log "Rollback Registro: $target\$name"
                    if ($null -eq $change.OldValue) {
                        Remove-ItemProperty -Path $target -Name $name -ErrorAction SilentlyContinue
                    } else {
                        Set-ItemProperty -Path $target -Name $name -Value $change.OldValue -ErrorAction SilentlyContinue
                    }
                }
                'File' {
                    $target = $change.Target
                    Write-Log "Rollback Arquivo: $target"
                    if (Test-Path $target) {
                        Remove-Item -Path $target -Force -ErrorAction SilentlyContinue
                    }
                }
                'Path' {
                    # Path e mais complexo, mas por agora logamos
                    $target = $change.Target
                    Write-Log "Rollback PATH (manual recomendado): $target" 'WARN'
                }
            }
        } catch {
            $msg = $_.Exception.Message
            Write-Log "Falha ao reverter alteracao: $msg" 'WARN'
        }
    }
    Write-Log 'Rollback automatico concluido.'
}

function New-BootstrapAuditRow {
    param(
        [Parameter(Mandatory = $true)][string]$Component,
        [Parameter(Mandatory = $true)][string]$Status,
        [string]$Detail = '',
        [string]$HowToFix = '',
        [AllowNull()]$ComponentDef = $null,
        [long]$DurationMs = 0,
        [bool]$TimedOut = $false,
        [string]$ProbeSource = ''
    )

    $severityInfo = Convert-BootstrapAuditStatusToSeverity -Status $Status -ComponentDef $ComponentDef
    return [pscustomobject]@{
        Component = $Component
        Status = $Status
        Severity = [string]$severityInfo.Severity
        Critical = [bool]$severityInfo.Critical
        Detail = $Detail
        HowToFix = $HowToFix
        DurationMs = [long]([Math]::Max(0, $DurationMs))
        TimedOut = [bool]$TimedOut
        ProbeSource = [string]$ProbeSource
    }
}

function Convert-BootstrapAuditStatusToSeverity {
    param(
        [Parameter(Mandatory = $true)][string]$Status,
        [AllowNull()]$ComponentDef = $null
    )

    $statusValue = ([string]$Status).Trim()
    $isOptional = $false
    if ($ComponentDef) {
        try {
            if ($ComponentDef.PSObject.Properties.Name -contains 'Optional') {
                $isOptional = [bool]$ComponentDef.Optional
            }
        } catch {
            $isOptional = $false
        }
    }

    $severity = switch ($statusValue) {
        'Healthy' { 'Ready' }
        'Repaired' { 'Ready' }
        'Missing' { if ($isOptional) { 'OptionalMissing' } else { 'NeedsInstall' } }
        'GhostInstall' { 'NeedsRepair' }
        'Unhealthy' { 'NeedsRepair' }
        'AliasOnly' { 'NeedsRepair' }
        'InstalledButNotInPath' { 'NeedsRepair' }
        'RuntimeOnly' { 'NeedsRepair' }
        'RequiresRestart' { 'RequiresRestart' }
        'Blocked' { 'ManualAction' }
        'UnsupportedAudit' { 'UnsupportedAudit' }
        'Skipped' { 'UnsupportedAudit' }
        'Unknown' { 'UnsupportedAudit' }
        default { 'UnsupportedAudit' }
    }

    $critical = ($severity -in @('NeedsInstall', 'NeedsRepair', 'RequiresRestart', 'ManualAction'))
    return [pscustomobject]@{
        Severity = $severity
        Critical = [bool]$critical
    }
}

function Add-BootstrapAuditSeverity {
    param(
        [Parameter(Mandatory = $true)]$Row,
        [AllowNull()]$ComponentDef = $null
    )

    $rowTable = ConvertTo-BootstrapHashtable -InputObject $Row
    $severityInfo = Convert-BootstrapAuditStatusToSeverity -Status ([string]$rowTable['Status']) -ComponentDef $ComponentDef
    $rowTable['Severity'] = [string]$severityInfo.Severity
    $rowTable['Critical'] = [bool]$severityInfo.Critical
    return [pscustomobject]$rowTable
}

function New-BootstrapAuditSeveritySummary {
    param([AllowNull()][object[]]$Rows = @())

    $summary = [ordered]@{
        total = @($Rows).Count
        critical = 0
        durationMs = 0
        timedOut = 0
        Ready = 0
        NeedsInstall = 0
        NeedsRepair = 0
        RequiresRestart = 0
        ManualAction = 0
        OptionalMissing = 0
        UnsupportedAudit = 0
    }

    foreach ($row in @($Rows)) {
        $sev = ''
        if ($row -is [System.Collections.IDictionary]) {
            if ($row.Contains('Severity')) { $sev = [string]$row['Severity'] }
            elseif ($row.Contains('severity')) { $sev = [string]$row['severity'] }
        } elseif ($row.PSObject.Properties['Severity']) {
            $sev = [string]$row.Severity
        } elseif ($row.PSObject.Properties['severity']) {
            $sev = [string]$row.severity
        }
        if ([string]::IsNullOrWhiteSpace($sev)) { $sev = 'UnsupportedAudit' }
        if (-not $summary.Contains($sev)) { $sev = 'UnsupportedAudit' }
        $summary[$sev] = [int]$summary[$sev] + 1
        if ($sev -in @('NeedsInstall', 'NeedsRepair', 'RequiresRestart', 'ManualAction')) {
            $summary['critical'] = [int]$summary['critical'] + 1
        }
        $durationMs = 0
        if ($row -is [System.Collections.IDictionary]) {
            if ($row.Contains('DurationMs')) { $durationMs = [long]$row['DurationMs'] }
            elseif ($row.Contains('durationMs')) { $durationMs = [long]$row['durationMs'] }
            if (($row.Contains('TimedOut') -and [bool]$row['TimedOut']) -or ($row.Contains('timedOut') -and [bool]$row['timedOut'])) {
                $summary['timedOut'] = [int]$summary['timedOut'] + 1
            }
        } else {
            if ($row.PSObject.Properties['DurationMs']) { $durationMs = [long]$row.DurationMs }
            elseif ($row.PSObject.Properties['durationMs']) { $durationMs = [long]$row.durationMs }
            if (($row.PSObject.Properties['TimedOut'] -and [bool]$row.TimedOut) -or ($row.PSObject.Properties['timedOut'] -and [bool]$row.timedOut)) {
                $summary['timedOut'] = [int]$summary['timedOut'] + 1
            }
        }
        if ($durationMs -gt 0) {
            $summary['durationMs'] = [long]$summary['durationMs'] + [long]$durationMs
        }
    }

    return [pscustomobject]$summary
}

function Get-AuditFirstExistingPathGlobal {
    param([string[]]$Candidates)
    foreach ($candidate in @($Candidates)) {
        if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
        $expanded = [Environment]::ExpandEnvironmentVariables($candidate)
        $match = @(Get-Item -Path $expanded -ErrorAction SilentlyContinue | Select-Object -First 1)
        if ($match.Count -gt 0) { return [string]$match[0].FullName }
    }
    return ''
}

function Test-AuditWingetInstalledGlobal {
    param(
        [string]$WingetPath,
        [string]$Id
    )

    if ([string]::IsNullOrWhiteSpace($WingetPath) -or [string]::IsNullOrWhiteSpace($Id)) { return $false }
    try {
        $cap = Invoke-WingetListIdProbe -WingetPath $WingetPath -Id $Id -TimeoutMs 8000
        $combined = ([string]$cap.stdout + "`n" + [string]$cap.stderr).Trim()
        return ((-not [bool]$cap.timedOut) -and ($combined -match [regex]::Escape($Id)))
    } catch {
        return $false
    }
}

function Get-BootstrapJavaJdkAuditRow {
    param(
        [string]$ComponentName = 'java-core',
        [string]$WingetPath = ''
    )

    $fix = 'Instale Temurin JDK 17 via winget: winget install -e --id EclipseAdoptium.Temurin.17.JDK; reabra a UI para atualizar PATH.'
    $javacPath = Resolve-CommandPath -Name 'javac'
    if ($javacPath -and ($javacPath -match '\\Microsoft\\WindowsApps\\')) {
        return (New-BootstrapAuditRow -Component $ComponentName -Status 'AliasOnly' -Detail ("Alias da Microsoft Store encontrado para javac em PATH: {0}" -f $javacPath) -HowToFix $fix)
    }
    if ($javacPath) {
        try {
            $output = (& $javacPath @('-version') 2>&1 | ForEach-Object { [string]$_ }) -join ' '
            $output = $output.Trim()
            if ([string]::IsNullOrWhiteSpace($output)) { $output = 'javac executado sem saida' }
            return (New-BootstrapAuditRow -Component $ComponentName -Status 'Healthy' -Detail ("JDK: {0} ({1})" -f $output, $javacPath) -HowToFix '')
        } catch {
            return (New-BootstrapAuditRow -Component $ComponentName -Status 'Unhealthy' -Detail ("javac encontrado, mas falhou: {0} ({1})" -f $_.Exception.Message, $javacPath) -HowToFix $fix)
        }
    }

    $installedJavac = Get-AuditFirstExistingPathGlobal -Candidates @('%ProgramFiles%\Eclipse Adoptium\jdk-17*\bin\javac.exe', '%ProgramFiles%\Java\jdk-17*\bin\javac.exe', '%ProgramFiles%\Eclipse Adoptium\jdk-*\bin\javac.exe', '%ProgramFiles%\Java\jdk-*\bin\javac.exe')
    if (-not [string]::IsNullOrWhiteSpace($installedJavac)) {
        return (New-BootstrapAuditRow -Component $ComponentName -Status 'InstalledButNotInPath' -Detail ("javac.exe encontrado fora do PATH: {0}" -f $installedJavac) -HowToFix $fix)
    }

    $javaPath = Resolve-CommandPath -Name 'java'
    if ($javaPath) {
        return (New-BootstrapAuditRow -Component $ComponentName -Status 'Missing' -Detail ("java.exe encontrado, mas javac.exe/JDK nao encontrado. Runtime JRE nao satisfaz java-core: {0}" -f $javaPath) -HowToFix $fix)
    }

    if (Test-AuditWingetInstalledGlobal -WingetPath $WingetPath -Id 'EclipseAdoptium.Temurin.17.JDK') {
        return (New-BootstrapAuditRow -Component $ComponentName -Status 'InstalledButNotInPath' -Detail 'winget lista Temurin JDK 17 como instalado, mas javac.exe nao esta no PATH.' -HowToFix $fix)
    }

    return (New-BootstrapAuditRow -Component $ComponentName -Status 'Missing' -Detail 'javac.exe/JDK ausente.' -HowToFix $fix)
}

function Invoke-BootstrapAuditMode {
    param(
        [Parameter(Mandatory = $true)]$Resolution,
        [object]$State = $null,
        [switch]$Repair,
        [int]$TimeoutSeconds = 180,
        [int]$ComponentTimeoutSeconds = 30
    )
    Write-Log 'Iniciando Auditoria de Integridade (Audit Mode)...'
    $results = New-Object System.Collections.Generic.List[object]
    $catalog = Get-BootstrapComponentCatalog
    $wingetExe = Get-Winget
    $wingetPresenceCache = @{}
    $auditStartedAt = Get-Date
    $auditDeadline = $auditStartedAt.AddSeconds([Math]::Max(1, $TimeoutSeconds))
    $auditComponentTimeoutSeconds = [Math]::Max(1, $ComponentTimeoutSeconds)

    function New-AuditRow {
        param(
            [Parameter(Mandatory = $true)][string]$Component,
            [Parameter(Mandatory = $true)][string]$Status,
            [string]$Detail = '',
            [string]$HowToFix = ''
        )

        return (New-BootstrapAuditRow -Component $Component -Status $Status -Detail $Detail -HowToFix $HowToFix)
    }

    function Get-AuditKnownFix {
        param([string]$ComponentName)

        switch ($ComponentName) {
            'system-core' { return 'Instale ou repare App Installer/winget, confirme diretorio de dados gravavel e reabra a UI.' }
            'git-core' { return 'Instale Git for Windows via winget: winget install -e --id Git.Git; reabra a UI para atualizar PATH.' }
            'git-lfs' { return 'Instale Git LFS apos Git: winget install -e --id GitHub.GitLFS; depois rode git lfs install.' }
            'node-core' { return 'Instale Node.js LTS via winget: winget install -e --id OpenJS.NodeJS.LTS; reabra a UI para atualizar PATH.' }
            'python-core' { return 'Instale Python real via winget: winget install -e --id Python.Python.3.13; desative aliases python.exe/python3.exe da Microsoft Store se necessario.' }
            'java-core' { return 'Instale Temurin JDK 17 via winget: winget install -e --id EclipseAdoptium.Temurin.17.JDK; reabra a UI para atualizar PATH.' }
            'dotnet-core' { return 'Instale .NET SDK 8 via winget: winget install -e --id Microsoft.DotNet.SDK.8; confirme `dotnet --list-sdks` nao vazio e reabra a UI para atualizar PATH.' }
            'codex-cli' { return 'Instale Codex CLI via npm -g: npm install -g @openai/codex; confirme codex --version.' }
            'codex-installer' { return 'Rode AppTuning codex-desktop-repair; se continuar, atualize/reinstale OpenAI.Codex via winget ou Microsoft Store e reabra o app.' }
            default { return 'Execute a instalacao do perfil correspondente ou instale o componente indicado; depois reabra a UI para atualizar PATH.' }
        }
    }

    function Test-AuditPathIsWindowsStoreAlias {
        param([string]$Path)
        return (-not [string]::IsNullOrWhiteSpace($Path) -and $Path -match '\\Microsoft\\WindowsApps\\')
    }

    function Get-AuditFirstExistingPath {
        param([string[]]$Candidates)
        foreach ($candidate in @($Candidates)) {
            if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
            $expanded = [Environment]::ExpandEnvironmentVariables($candidate)
            $match = @(Get-Item -Path $expanded -ErrorAction SilentlyContinue | Select-Object -First 1)
            if ($match.Count -gt 0) { return [string]$match[0].FullName }
        }
        return ''
    }

    function Invoke-AuditWingetPresence {
        param([string]$Id)
        if ([string]::IsNullOrWhiteSpace($Id) -or -not $wingetExe) {
            return [ordered]@{ Installed = $false; TimedOut = $false; ProbeSource = ''; Detail = 'winget indisponivel.' }
        }
        if (-not $wingetPresenceCache.ContainsKey($Id)) {
            $installed = $false
            $timedOut = $false
            $detail = ''
            try {
                $probeTimeoutMs = [Math]::Min(8000, [Math]::Max(1000, ($auditComponentTimeoutSeconds * 1000)))
                $cap = Invoke-WingetListIdProbe -WingetPath $wingetExe -Id $Id -TimeoutMs $probeTimeoutMs
                $combined = ([string]$cap.stdout + "`n" + [string]$cap.stderr).Trim()
                if ([bool]$cap.timedOut) {
                    Write-Log ("Audit: winget list timeout para {0}; tratando como nao confirmado." -f $Id) 'WARN'
                    $installed = $false
                    $timedOut = $true
                    $detail = ("winget list timeout para {0} em {1}ms." -f $Id, $probeTimeoutMs)
                } else {
                    $installed = ($combined -match [regex]::Escape($Id))
                    $detail = if ($installed) { "winget lista $Id como instalado." } else { "winget nao lista $Id como instalado." }
                }
            } catch {
                Write-Log ("Audit: falha ao consultar winget para {0}: {1}" -f $Id, $_.Exception.Message) 'WARN'
                $installed = $false
                $detail = "winget falhou para ${Id}: $($_.Exception.Message)"
            }
            $wingetPresenceCache[$Id] = [ordered]@{
                Installed = [bool]$installed
                TimedOut = [bool]$timedOut
                ProbeSource = 'winget-list-id'
                Detail = [string]$detail
            }
        }
        return $wingetPresenceCache[$Id]
    }

    function Test-AuditWingetInstalled {
        param([string]$Id)
        $presence = Invoke-AuditWingetPresence -Id $Id
        return [bool]$presence.Installed
    }

    function Invoke-AuditVersionCommand {
        param(
            [Parameter(Mandatory = $true)][string]$ComponentName,
            [Parameter(Mandatory = $true)][string]$CommandName,
            [string[]]$Args = @('--version'),
            [string[]]$InstalledPathCandidates = @(),
            [string]$WingetId = ''
        )

        $fix = Get-AuditKnownFix -ComponentName $ComponentName
        $cmdPath = Resolve-CommandPath -Name $CommandName
        if ($cmdPath -and (Test-AuditPathIsWindowsStoreAlias -Path $cmdPath)) {
            return (New-AuditRow -Component $ComponentName -Status 'AliasOnly' -Detail ("Alias da Microsoft Store encontrado em PATH: {0}" -f $cmdPath) -HowToFix $fix)
        }

        if ($ComponentName -eq 'node-core' -and $cmdPath -and $cmdPath -match '\\resources\\app\\resources\\helpers\\node\.exe$') {
            return (New-AuditRow -Component $ComponentName -Status 'RuntimeOnly' -Detail ("Node embutido de aplicativo detectado, nao Node.js LTS do sistema: {0}" -f $cmdPath) -HowToFix $fix)
        }

        if ($cmdPath) {
            try {
                $output = (& $cmdPath @Args 2>&1 | ForEach-Object { [string]$_ }) -join ' '
                $output = $output.Trim()
                if ([string]::IsNullOrWhiteSpace($output)) { $output = 'comando executado sem saida' }
                return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ("Versao: {0} ({1})" -f $output, $cmdPath) -HowToFix '')
            } catch {
                return (New-AuditRow -Component $ComponentName -Status 'Unhealthy' -Detail ("Comando encontrado, mas falhou: {0} ({1})" -f $_.Exception.Message, $cmdPath) -HowToFix $fix)
            }
        }

        $installedPath = Get-AuditFirstExistingPath -Candidates $InstalledPathCandidates
        if (-not [string]::IsNullOrWhiteSpace($installedPath)) {
            return (New-AuditRow -Component $ComponentName -Status 'InstalledButNotInPath' -Detail ("Binario encontrado fora do PATH: {0}" -f $installedPath) -HowToFix $fix)
        }

        if (-not [string]::IsNullOrWhiteSpace($WingetId) -and (Test-AuditWingetInstalled -Id $WingetId)) {
            return (New-AuditRow -Component $ComponentName -Status 'InstalledButNotInPath' -Detail ("winget lista {0} como instalado, mas {1} nao esta no PATH." -f $WingetId, $CommandName) -HowToFix $fix)
        }

        return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail ("Comando ausente: {0}" -f $CommandName) -HowToFix $fix)
    }

    function Invoke-AuditPythonCore {
        param([Parameter(Mandatory = $true)][string]$ComponentName)

        $fix = Get-AuditKnownFix -ComponentName $ComponentName
        $pythonExe = Resolve-BootstrapPythonExecutable
        if ($pythonExe) {
            try {
                $output = (& $pythonExe @('--version') 2>&1 | ForEach-Object { [string]$_ }) -join ' '
                $output = $output.Trim()
                if ([string]::IsNullOrWhiteSpace($output)) { $output = 'comando executado sem saida' }
                return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ("Versao: {0} ({1})" -f $output, $pythonExe) -HowToFix '')
            } catch {
                return (New-AuditRow -Component $ComponentName -Status 'Unhealthy' -Detail ("Python real encontrado, mas falhou: {0} ({1})" -f $_.Exception.Message, $pythonExe) -HowToFix $fix)
            }
        }

        $installedPath = Get-AuditFirstExistingPath -Candidates @('%LocalAppData%\Programs\Python\Python313\python.exe', '%ProgramFiles%\Python313\python.exe')
        if (-not [string]::IsNullOrWhiteSpace($installedPath)) {
            return (New-AuditRow -Component $ComponentName -Status 'InstalledButNotInPath' -Detail ("Binario encontrado fora do PATH: {0}" -f $installedPath) -HowToFix $fix)
        }

        if (Test-AuditWingetInstalled -Id 'Python.Python.3.13') {
            return (New-AuditRow -Component $ComponentName -Status 'InstalledButNotInPath' -Detail 'winget lista Python.Python.3.13 como instalado, mas python real nao esta no PATH.' -HowToFix $fix)
        }

        return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail 'Comando ausente: python real' -HowToFix $fix)
    }

    function Invoke-AuditSystemCore {
        param([string]$ComponentName)

        $issues = New-Object System.Collections.Generic.List[string]
        if ($wingetExe) {
            $issues.Add("winget OK: $wingetExe")
        } else {
            $issues.Add('winget ausente.')
        }

        $dataRoot = Get-BootstrapDataRoot
        if (Test-BootstrapDirectoryWritable -Path $dataRoot) {
            $issues.Add("DataRoot gravavel: $dataRoot")
        } else {
            $issues.Add("DataRoot nao gravavel: $dataRoot")
        }

        try {
            [void][Net.ServicePointManager]::SecurityProtocol
            $issues.Add('TLS/ServicePointManager acessivel.')
        } catch {
            $issues.Add("TLS indisponível: $($_.Exception.Message)")
        }

        $healthy = ($wingetExe -and (Test-BootstrapDirectoryWritable -Path $dataRoot))
        $status = if ($healthy) { 'Healthy' } else { 'Unhealthy' }
        $fix = if ($healthy) { '' } else { Get-AuditKnownFix -ComponentName $ComponentName }
        return (New-AuditRow -Component $ComponentName -Status $status -Detail ($issues -join ' ') -HowToFix $fix)
    }

    function Invoke-AuditDeclaredCommands {
        param(
            [Parameter(Mandatory = $true)][string]$ComponentName,
            [Parameter(Mandatory = $true)]$ComponentDef
        )

        $names = @()
        if ($ComponentDef.PSObject.Properties.Name -contains 'CommandNames') {
            $names = @($ComponentDef.CommandNames | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
        } elseif ($ComponentDef.PSObject.Properties.Name -contains 'CommandName') {
            $names = @($ComponentDef.CommandName | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
        }
        if ($names.Count -eq 0) { return $null }

        foreach ($name in @($names)) {
            $cmdPath = Resolve-CommandPath -Name ([string]$name)
            if ($cmdPath -and (Test-AuditPathIsWindowsStoreAlias -Path $cmdPath)) {
                return (New-AuditRow -Component $ComponentName -Status 'AliasOnly' -Detail ("Alias da Microsoft Store encontrado para {0}: {1}" -f [string]$name, $cmdPath) -HowToFix (Get-AuditKnownFix -ComponentName $ComponentName))
            }
            if ($cmdPath) {
                return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ("Comando disponivel: {0} ({1})" -f [string]$name, $cmdPath) -HowToFix '')
            }
        }

        $package = if ($ComponentDef.PSObject.Properties.Name -contains 'Package') { [string]$ComponentDef.Package } else { '' }
        $fix = if (-not [string]::IsNullOrWhiteSpace($package)) {
            "Instale/repare via npm: npm install -g $package; reabra a UI para atualizar PATH."
        } else {
            Get-AuditKnownFix -ComponentName $ComponentName
        }
        return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail ("Comandos ausentes: {0}" -f ($names -join ', ')) -HowToFix $fix)
    }

    function Invoke-AuditRepoClone {
        param(
            [Parameter(Mandatory = $true)][string]$ComponentName,
            [Parameter(Mandatory = $true)]$ComponentDef
        )

        $targetNames = @($ComponentDef.TargetName | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
        if ($targetNames.Count -ne 1) {
            return (New-AuditRow -Component $ComponentName -Status 'UnsupportedAudit' -Detail 'repo-clone sem TargetName unico no catalogo.' -HowToFix 'Corrija TargetName no catalogo antes de auditar este repo.')
        }
        $cloneRoot = ''
        if ($State -is [hashtable] -and $State.ContainsKey('CloneBaseDir')) { $cloneRoot = [string]$State.CloneBaseDir }
        elseif ($State -and $State.PSObject.Properties['CloneBaseDir']) { $cloneRoot = [string]$State.CloneBaseDir }
        if ([string]::IsNullOrWhiteSpace($cloneRoot)) { $cloneRoot = (Get-Location).Path }

        $target = Join-Path $cloneRoot ([string]$targetNames[0])
        if (Test-Path -LiteralPath (Join-Path $target '.git')) {
            return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ("Repositorio presente: {0}" -f $target) -HowToFix '')
        }
        if (Test-Path -LiteralPath $target) {
            return (New-AuditRow -Component $ComponentName -Status 'Unhealthy' -Detail ("Diretorio existe mas nao parece clone git: {0}" -f $target) -HowToFix 'Remova/corrija o diretorio alvo ou execute o componente repo-clone novamente.')
        }
        return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail ("Repositorio ausente: {0}" -f $target) -HowToFix 'Execute o componente repo-clone correspondente apos git-core estar saudavel.')
    }

    function Invoke-AuditManualRequired {
        param(
            [Parameter(Mandatory = $true)][string]$ComponentName,
            [Parameter(Mandatory = $true)]$ComponentDef
        )

        $display = if ($ComponentDef.PSObject.Properties.Name -contains 'DisplayName') { [string]$ComponentDef.DisplayName } else { $ComponentName }
        $instructions = if ($ComponentDef.PSObject.Properties.Name -contains 'Instructions') { [string]$ComponentDef.Instructions } else { "Instale $display manualmente e rode a auditoria novamente." }
        if (Test-BootstrapManualRequirementInstalled -ComponentDef $ComponentDef) {
            return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ("Requisito manual presente: {0}" -f $display) -HowToFix '')
        }
        $status = if ([bool]$ComponentDef.Optional) { 'Missing' } else { 'Blocked' }
        return (New-AuditRow -Component $ComponentName -Status $status -Detail ("Requisito manual ausente: {0}" -f $display) -HowToFix $instructions)
    }

    function Invoke-AuditWslCore {
        param([string]$ComponentName)

        $fix = 'Habilite WSL com administrador: wsl --install; reinicie o Windows quando solicitado.'
        $wslPath = Resolve-CommandPath -Name 'wsl.exe'
        if (-not $wslPath) {
            $candidate = Join-Path $env:SystemRoot 'System32\wsl.exe'
            if (Test-Path -LiteralPath $candidate) { $wslPath = $candidate }
        }
        if (-not $wslPath) {
            return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail 'wsl.exe ausente.' -HowToFix $fix)
        }

        $details = New-Object System.Collections.Generic.List[string]
        $details.Add(("wsl.exe: {0}" -f $wslPath))

        $appxPresent = $false
        try { $appxPresent = [bool](Test-BootstrapAppxPackageInstalled -Names @('MicrosoftCorporationII.WindowsSubsystemForLinux')) } catch { $appxPresent = $false }
        $details.Add(("AppX WSL: {0}" -f $appxPresent))

        $servicePresent = $false
        $serviceStatus = ''
        try {
            $svc = Get-Service -Name 'LxssManager' -ErrorAction Stop
            $servicePresent = $true
            $serviceStatus = [string]$svc.Status
        } catch {
            $servicePresent = $false
            $serviceStatus = 'ausente'
        }
        $details.Add(("LxssManager: {0}" -f $serviceStatus))

        $featureStates = New-Object System.Collections.Generic.List[string]
        foreach ($featureName in @('Microsoft-Windows-Subsystem-Linux', 'VirtualMachinePlatform')) {
            try {
                $feature = Get-WindowsOptionalFeature -Online -FeatureName $featureName -ErrorAction Stop
                $featureStates.Add(("{0}={1}" -f $featureName, [string]$feature.State))
            } catch {
                $featureStates.Add(("{0}=unknown" -f $featureName))
            }
        }
        $details.Add(("Features: {0}" -f ($featureStates.ToArray() -join '; ')))

        $detail = ($details.ToArray() -join ' | ')
        $statusProbe = $null
        try {
            $wslTimeoutMs = [Math]::Min(15000, [Math]::Max(1000, ($auditComponentTimeoutSeconds * 1000)))
            $statusProbe = Get-BootstrapWslStatusProbe -WslExe $wslPath -TimeoutMs $wslTimeoutMs
        } catch { $statusProbe = $null }
        if ($statusProbe) {
            $statusText = [string]($statusProbe.stdout + "`n" + $statusProbe.stderr)
            if (Test-WslCorruptionText -Text $statusText) {
                $cleanStatusText = ($statusText -replace "`0", '' -replace "`r", ' ' -replace "`n", ' ').Trim()
                return (New-AuditRow -Component $ComponentName -Status 'Unhealthy' -Detail ("WSL MSI/AppX corrompido: {0}. {1}" -f $cleanStatusText, $detail) -HowToFix 'Abra PowerShell como administrador e rode o componente wsl-core; ele tentara re-registrar/reinstalar Microsoft.WSL. Depois reinicie e execute wsl --update.')
            }
        }
        if ($appxPresent -and $servicePresent) {
            return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ("WSL artefatos presentes. {0}" -f $detail) -HowToFix '')
        }
        if ($appxPresent -and -not $servicePresent) {
            return (New-AuditRow -Component $ComponentName -Status 'RequiresRestart' -Detail ("Pacote WSL presente, mas servico LxssManager indisponivel. {0}" -f $detail) -HowToFix 'Reinicie o Windows ou faca logoff/logon; depois rode nova auditoria. Se persistir, execute wsl --update em terminal manual.')
        }
        return (New-AuditRow -Component $ComponentName -Status 'Unhealthy' -Detail ("wsl.exe encontrado, mas artefatos WSL incompletos. {0}" -f $detail) -HowToFix $fix)
    }

    function Invoke-AuditWslUi {
        param([string]$ComponentName)

        if (Test-AuditWingetInstalled -Id 'OctasoftLtd.WSLUI') {
            return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail 'winget lista OctasoftLtd.WSLUI como instalado.' -HowToFix '')
        }
        return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail 'WSL UI nao encontrado via winget.' -HowToFix 'Instale via winget install -e --id OctasoftLtd.WSLUI quando WSL estiver saudavel.')
    }

    function Invoke-AuditVsCodeExtensions {
        param([string]$ComponentName)

        $codePath = Resolve-CommandPath -Name 'code'
        $insidersPath = Resolve-CommandPath -Name 'code-insiders'
        if (-not $codePath) {
            $codePath = Get-AuditFirstExistingPath -Candidates @('%ProgramFiles%\Microsoft VS Code\Code.exe', '%LocalAppData%\Programs\Microsoft VS Code\Code.exe')
        }
        if (-not $insidersPath) {
            $insidersPath = Get-AuditFirstExistingPath -Candidates @('%ProgramFiles%\Microsoft VS Code Insiders\Code - Insiders.exe', '%LocalAppData%\Programs\Microsoft VS Code Insiders\Code - Insiders.exe')
        }
        $found = @($codePath, $insidersPath | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
        if ($found.Count -gt 0) {
            return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ("VS Code alvo presente para extensoes: {0}" -f ($found -join '; ')) -HowToFix '')
        }
        return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail 'Nenhum VS Code/Insiders encontrado para aplicar extensoes.' -HowToFix 'Instale vscode ou vscode-insiders antes de aplicar vscode-extensions.')
    }

    function Get-AuditSpecializedRow {
        param([string]$ComponentName)

        switch ($ComponentName) {
            'system-core' {
                return (Invoke-AuditSystemCore -ComponentName $ComponentName)
            }
            'git-core' {
                return (Invoke-AuditVersionCommand -ComponentName $ComponentName -CommandName 'git' -Args @('--version') -WingetId 'Git.Git' -InstalledPathCandidates @('%ProgramFiles%\Git\cmd\git.exe', '%ProgramFiles%\Git\bin\git.exe', '%LocalAppData%\Programs\Git\cmd\git.exe'))
            }
            'git-lfs' {
                $gitRow = @($results.ToArray() | Where-Object { [string]$_.Component -eq 'git-core' } | Select-Object -First 1)
                if ($gitRow -and ([string]$gitRow.Status -ne 'Healthy')) {
                    return (New-AuditRow -Component $ComponentName -Status 'Blocked' -Detail ("Bloqueado por git-core: {0}" -f [string]$gitRow.Status) -HowToFix (Get-AuditKnownFix -ComponentName $ComponentName))
                }
                return (Invoke-AuditVersionCommand -ComponentName $ComponentName -CommandName 'git-lfs' -Args @('--version') -WingetId 'GitHub.GitLFS' -InstalledPathCandidates @('%ProgramFiles%\Git LFS\git-lfs.exe', '%ProgramFiles%\Git\mingw64\bin\git-lfs.exe'))
            }
            'node-core' {
                return (Invoke-AuditVersionCommand -ComponentName $ComponentName -CommandName 'node' -Args @('-v') -WingetId 'OpenJS.NodeJS.LTS' -InstalledPathCandidates @('%ProgramFiles%\nodejs\node.exe'))
            }
            'claude-code' {
                return (Invoke-AuditVersionCommand -ComponentName $ComponentName -CommandName 'claude' -Args @('--version') -InstalledPathCandidates @('%APPDATA%\npm\claude.cmd', '%APPDATA%\npm\claude.ps1'))
            }
            'opencode' {
                return (Invoke-AuditVersionCommand -ComponentName $ComponentName -CommandName 'opencode' -Args @('--version') -InstalledPathCandidates @('%USERPROFILE%\.opencode\bin\opencode.exe'))
            }
            'ai-usagebar' {
                return (Invoke-AuditVersionCommand -ComponentName $ComponentName -CommandName 'ai-usagebar' -Args @('--help') -InstalledPathCandidates @('%LOCALAPPDATA%\PhaseZero\ai-tools\bin\ai-usagebar.exe'))
            }
            'ai-memory' {
                return (Invoke-AuditVersionCommand -ComponentName $ComponentName -CommandName 'ai-memory' -Args @('--version') -InstalledPathCandidates @('%LOCALAPPDATA%\PhaseZero\ai-tools\ai-memory\ai-memory.exe', '%USERPROFILE%\.cargo\bin\ai-memory.exe'))
            }
            'openclaw' {
                return (Invoke-AuditVersionCommand -ComponentName $ComponentName -CommandName 'openclaw' -Args @('--version') -InstalledPathCandidates @('%APPDATA%\npm\openclaw.cmd', '%APPDATA%\npm\openclaw.ps1'))
            }
            'goose' {
                return (Invoke-AuditVersionCommand -ComponentName $ComponentName -CommandName 'goose' -Args @('--version') -InstalledPathCandidates @('%USERPROFILE%\.local\bin\goose.exe'))
            }
            'python-core' {
                return (Invoke-AuditPythonCore -ComponentName $ComponentName)
            }
            'java-core' {
                return (Get-BootstrapJavaJdkAuditRow -ComponentName $ComponentName -WingetPath $wingetExe)
            }
            'dotnet-core' {
                $fix = Get-AuditKnownFix -ComponentName $ComponentName
                $cmdPath = Resolve-CommandPath -Name 'dotnet'
                if ($cmdPath -and (Test-AuditPathIsWindowsStoreAlias -Path $cmdPath)) {
                    return (New-AuditRow -Component $ComponentName -Status 'AliasOnly' -Detail ("Alias da Microsoft Store encontrado em PATH: {0}" -f $cmdPath) -HowToFix $fix)
                }
                if ($cmdPath) {
                    try {
                        $raw = (& $cmdPath @('--list-sdks') 2>&1 | ForEach-Object { [string]$_ }) -join [Environment]::NewLine
                        if (Test-BootstrapDotNetSdkListHasMajorBand -ListSdksOutput $raw -Major 8) {
                            $detail = ($raw.Trim() -replace "`r?`n", '; ')
                            if ($detail.Length -gt 240) { $detail = $detail.Substring(0, 237) + '...' }
                            return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ("SDKs: {0} ({1})" -f $detail, $cmdPath) -HowToFix '')
                        }
                        if (Test-BootstrapDotNetSdkListHasEntry -ListSdksOutput $raw) {
                            return (New-AuditRow -Component $ComponentName -Status 'Unhealthy' -Detail ("dotnet com SDKs, mas nenhum na banda 8.x (dotnet-core requer .NET 8 SDK): {0}" -f $cmdPath) -HowToFix $fix)
                        }
                        return (New-AuditRow -Component $ComponentName -Status 'Unhealthy' -Detail ("dotnet encontrado mas sem SDK instalado (list-sdks vazio ou invalido): {0}" -f $cmdPath) -HowToFix $fix)
                    } catch {
                        return (New-AuditRow -Component $ComponentName -Status 'Unhealthy' -Detail ("dotnet encontrado mas falhou ao listar SDKs: {0} ({1})" -f $_.Exception.Message, $cmdPath) -HowToFix $fix)
                    }
                }
                $installedPath = Get-AuditFirstExistingPath -Candidates @('%ProgramFiles%\dotnet\dotnet.exe')
                if (-not [string]::IsNullOrWhiteSpace($installedPath)) {
                    return (New-AuditRow -Component $ComponentName -Status 'InstalledButNotInPath' -Detail ("Binario encontrado fora do PATH: {0}" -f $installedPath) -HowToFix $fix)
                }
                if (Test-AuditWingetInstalled -Id 'Microsoft.DotNet.SDK.8') {
                    return (New-AuditRow -Component $ComponentName -Status 'InstalledButNotInPath' -Detail 'winget lista Microsoft.DotNet.SDK.8 como instalado, mas dotnet nao esta no PATH.' -HowToFix $fix)
                }
                return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail 'Comando ausente: dotnet' -HowToFix $fix)
            }
            'codex-cli' {
                return (Invoke-AuditVersionCommand -ComponentName $ComponentName -CommandName 'codex' -Args @('--version') -InstalledPathCandidates @('%APPDATA%\npm\codex.cmd', '%LocalAppData%\Microsoft\WindowsApps\codex.exe'))
            }
            'codex-installer' {
                $fix = Get-AuditKnownFix -ComponentName $ComponentName
                $diag = Get-BootstrapCodexDesktopDiagnostics
                $pkg = ConvertTo-BootstrapHashtable -InputObject $diag['package']
                $latestLog = ConvertTo-BootstrapHashtable -InputObject $diag['latestLog']
                $runtime = ConvertTo-BootstrapHashtable -InputObject $diag['runtime']
                if (-not [bool]$pkg['installed']) {
                    return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail 'OpenAI.Codex MSIX ausente.' -HowToFix $fix)
                }

                $detailParts = New-Object System.Collections.Generic.List[string]
                $detailParts.Add(("MSIX {0}" -f [string]$pkg['version']))
                if (-not [bool]$runtime['present']) {
                    $detailParts.Add(("VC++ runtime ausente: {0}" -f (@($runtime['missing']) -join ', ')))
                }
                if (-not [string]::IsNullOrWhiteSpace([string]$latestLog['exitCode'])) {
                    $detailParts.Add(("ultimo app-server exit={0} {1}" -f [string]$latestLog['exitCode'], [string]$latestLog['exitCodeHex']))
                }
                if ([bool]$latestLog['staleSpawnedPackage']) {
                    $detailParts.Add(("ultimo log usou pacote antigo {0}" -f [string]$latestLog['spawnedVersion']))
                }
                if (@($diag['issues']).Count -gt 0) {
                    return (New-AuditRow -Component $ComponentName -Status 'Unhealthy' -Detail ($detailParts.ToArray() -join '; ') -HowToFix $fix)
                }
                return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ($detailParts.ToArray() -join '; ') -HowToFix '')
            }
            'notepadpp' {
                $info = $null
                try { $info = Get-BootstrapNotepadPlusPlusInstallInfo } catch { $info = $null }
                if ($info -and [bool]$info.GhostState) {
                    $hive = [string]$info.GhostHive
                    if ([string]::IsNullOrWhiteSpace($hive)) { $hive = 'desconhecido' }
                    return (New-AuditRow -Component $ComponentName -Status 'GhostInstall' -Detail ("Registro ({0}) declara Notepad++ instalado, mas binario ausente/corrompido em disco." -f $hive) -HowToFix 'Execute bootstrap-tools.ps1 -Audit -Repair para limpar a entrada fantasma (HKCU/HKLM/WOW6432Node) e reinstalar via winget.')
                }
                if ($info -and [bool]$info.Installed) {
                    $exe = Join-Path ([string]$info.InstallRoot) 'notepad++.exe'
                    $ver = [string]$info.RegistryDisplayVersion
                    $detail = if ([string]::IsNullOrWhiteSpace($ver)) { "Notepad++ ({0}) em {1}" -f $info.Architecture, $exe } else { "Notepad++ {0} ({1}) em {2}" -f $ver, $info.Architecture, $exe }
                    return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail $detail -HowToFix '')
                }
                return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail 'Notepad++ ausente em disco e nenhuma entrada de registro reconhecida.' -HowToFix 'Instale via winget: winget install -e --id Notepad++.Notepad++')
            }
            'powertoys' {
                # PowerToys instala tanto como MSI (Program Files\PowerToys) quanto MSIX
                # (WindowsApps\Microsoft.PowerToys_*). Validar disco + checar winget evita ghost.
                $candidates = @(
                    (Join-Path $env:ProgramFiles 'PowerToys\PowerToys.exe')
                    $(if ([Environment]::GetEnvironmentVariable('ProgramFiles(x86)')) { Join-Path ([Environment]::GetEnvironmentVariable('ProgramFiles(x86)')) 'PowerToys\PowerToys.exe' } else { $null })
                    (Join-Path $env:LOCALAPPDATA 'PowerToys\PowerToys.exe')
                ) | Where-Object { $_ }
                $exePath = ''
                foreach ($c in $candidates) {
                    if (Test-Path -LiteralPath $c) { $exePath = $c; break }
                }
                if ([string]::IsNullOrWhiteSpace($exePath)) {
                    $msixMatches = @(Get-ChildItem -Path (Join-Path $env:ProgramFiles 'WindowsApps\Microsoft.PowerToys_*\PowerToys.exe') -ErrorAction SilentlyContinue)
                    if ($msixMatches.Count -gt 0) { $exePath = [string]$msixMatches[0].FullName }
                }
                if (-not [string]::IsNullOrWhiteSpace($exePath)) {
                    $ver = ''
                    try { $ver = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($exePath).FileVersion } catch { $ver = '' }
                    return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ("PowerToys em {0} (v{1})" -f $exePath, $ver) -HowToFix '')
                }
                if (Test-AuditWingetInstalled -Id 'Microsoft.PowerToys') {
                    return (New-AuditRow -Component $ComponentName -Status 'GhostInstall' -Detail 'winget lista Microsoft.PowerToys como instalado, mas PowerToys.exe ausente em ProgramFiles/LOCALAPPDATA/WindowsApps.' -HowToFix 'Execute bootstrap-tools.ps1 -Audit -Repair para limpar entrada fantasma e reinstalar.')
                }
                return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail 'PowerToys.exe nao encontrado.' -HowToFix 'Instale via winget install -e --id Microsoft.PowerToys')
            }
            'terminal' {
                # Windows Terminal e MSIX: o alias wt.exe vive em WindowsApps mas o pacote real
                # em WindowsApps\Microsoft.WindowsTerminal_*. Confiar so no alias deixa passar ghost.
                $aliasPath = Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\wt.exe'
                $hasAlias = Test-Path -LiteralPath $aliasPath
                $hasPackage = Test-BootstrapAppxPackageInstalled -Names @('Microsoft.WindowsTerminal')
                $msixMatches = @(Get-ChildItem -Path (Join-Path $env:ProgramFiles 'WindowsApps\Microsoft.WindowsTerminal_*\wt.exe') -ErrorAction SilentlyContinue)
                $msixPath = if ($msixMatches.Count -gt 0) { [string]$msixMatches[0].FullName } else { '' }
                if ($hasAlias -and $hasPackage) {
                    $detailPath = if ([string]::IsNullOrWhiteSpace($msixPath)) { 'Get-AppxPackage: Microsoft.WindowsTerminal' } else { $msixPath }
                    return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ("Windows Terminal MSIX em {0}; alias {1}" -f $detailPath, $aliasPath) -HowToFix '')
                }
                if ($hasAlias -and -not $hasPackage) {
                    return (New-AuditRow -Component $ComponentName -Status 'GhostInstall' -Detail ("Alias wt.exe presente em {0}, mas pacote Appx Microsoft.WindowsTerminal ausente." -f $aliasPath) -HowToFix 'Execute bootstrap-tools.ps1 -Audit -Repair para reinstalar; ou Get-AppxPackage Microsoft.WindowsTerminal | Remove-AppxPackage seguido de winget install.')
                }
                if ($hasPackage) {
                    $detailPath = if ([string]::IsNullOrWhiteSpace($msixPath)) { 'Get-AppxPackage: Microsoft.WindowsTerminal' } else { $msixPath }
                    return (New-AuditRow -Component $ComponentName -Status 'InstalledButNotInPath' -Detail ("MSIX presente em {0} mas alias wt.exe ausente no PATH do usuario." -f $detailPath) -HowToFix 'Verifique Settings > Apps > Aliases de execucao para reabilitar wt.exe.')
                }
                if (Test-AuditWingetInstalled -Id 'Microsoft.WindowsTerminal') {
                    return (New-AuditRow -Component $ComponentName -Status 'GhostInstall' -Detail 'winget lista Microsoft.WindowsTerminal como instalado, mas nem alias nem pacote MSIX foram encontrados.' -HowToFix 'Execute bootstrap-tools.ps1 -Audit -Repair.')
                }
                return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail 'Windows Terminal nao encontrado.' -HowToFix 'Instale via winget install -e --id Microsoft.WindowsTerminal')
            }
            'docker' {
                $info = $null
                try { $info = Get-BootstrapDockerInstallInfo } catch { $info = $null }
                if ($info -and [bool]$info.GhostState) {
                    $reason = [string]$info.GhostReason
                    if ([string]::IsNullOrWhiteSpace($reason)) { $reason = 'binario ausente apos winget reportar presente' }
                    return (New-AuditRow -Component $ComponentName -Status 'GhostInstall' -Detail ("Docker Desktop ghost: {0}" -f $reason) -HowToFix 'Execute bootstrap-tools.ps1 -Audit -Repair para limpar entrada fantasma e reinstalar Docker Desktop.')
                }
                if ($info -and [bool]$info.Installed) {
                    $detail = ("Docker Desktop em {0} (v{1}); WSL2={2}; servico={3}" -f $info.InstallRoot, $info.FileVersion, $info.WslDistroPresent, $info.ServiceState)
                    if ([bool]$info.HealthIssues) {
                        return (New-AuditRow -Component $ComponentName -Status 'Unhealthy' -Detail $detail -HowToFix 'Abra Docker Desktop manualmente, aguarde a engine subir, e revise Settings > Resources > WSL Integration.')
                    }
                    return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail $detail -HowToFix '')
                }
                return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail 'Docker Desktop ausente.' -HowToFix 'Instale via winget install -e --id Docker.DockerDesktop apos habilitar WSL.')
            }
            'wsl-core' {
                return (Invoke-AuditWslCore -ComponentName $ComponentName)
            }
            'wsl-ui' {
                return (Invoke-AuditWslUi -ComponentName $ComponentName)
            }
            'hyper-v' {
                $states = @($catalog[$ComponentName].FeatureNames | ForEach-Object { "{0}={1}" -f [string]$_, (Get-WindowsOptionalFeatureState -FeatureName ([string]$_)) })
                $allEnabled = $true
                foreach ($feature in @($catalog[$ComponentName].FeatureNames)) {
                    if ((Get-WindowsOptionalFeatureState -FeatureName ([string]$feature)) -ne 'Enabled') { $allEnabled = $false }
                }
                if ($allEnabled) { return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ($states -join '; ') -HowToFix '') }
                return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail ($states -join '; ') -HowToFix 'Execute elevado: bootstrap-tools.ps1 -Component hyper-v -NonInteractive')
            }
            'hyper-v-tools' {
                $states = @($catalog[$ComponentName].FeatureNames | ForEach-Object { "{0}={1}" -f [string]$_, (Get-WindowsOptionalFeatureState -FeatureName ([string]$_)) })
                $allEnabled = $true
                foreach ($feature in @($catalog[$ComponentName].FeatureNames)) {
                    if ((Get-WindowsOptionalFeatureState -FeatureName ([string]$feature)) -ne 'Enabled') { $allEnabled = $false }
                }
                if ($allEnabled) { return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ($states -join '; ') -HowToFix '') }
                return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail ($states -join '; ') -HowToFix 'Execute elevado: bootstrap-tools.ps1 -Component hyper-v-tools -NonInteractive')
            }
            'windows-hypervisor-platform' {
                $states = @($catalog[$ComponentName].FeatureNames | ForEach-Object { "{0}={1}" -f [string]$_, (Get-WindowsOptionalFeatureState -FeatureName ([string]$_)) })
                $allEnabled = $true
                foreach ($feature in @($catalog[$ComponentName].FeatureNames)) {
                    if ((Get-WindowsOptionalFeatureState -FeatureName ([string]$feature)) -ne 'Enabled') { $allEnabled = $false }
                }
                if ($allEnabled) { return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ($states -join '; ') -HowToFix '') }
                return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail ($states -join '; ') -HowToFix 'Execute elevado: bootstrap-tools.ps1 -Component windows-hypervisor-platform -NonInteractive')
            }
            'openssh-client' {
                $stateText = Get-BootstrapWindowsCapabilityState -CapabilityName 'OpenSSH.Client~~~~0.0.1.0'
                $sshPath = Resolve-CommandPath -Name 'ssh'
                if ($stateText -eq 'Installed' -or $sshPath) { return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ("capability={0}; ssh={1}" -f $stateText, $sshPath) -HowToFix '') }
                return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail ("capability={0}; ssh ausente" -f $stateText) -HowToFix 'Execute elevado: bootstrap-tools.ps1 -Component openssh-client -NonInteractive')
            }
            'openssh-server' {
                $stateText = Get-BootstrapWindowsCapabilityState -CapabilityName 'OpenSSH.Server~~~~0.0.1.0'
                $svc = Get-Service -Name 'sshd' -ErrorAction SilentlyContinue
                $rule = Get-NetFirewallRule -DisplayName 'PhaseZero OpenSSH Server Domain Private' -ErrorAction SilentlyContinue
                $ruleProfile = ''
                if ($rule) { $ruleProfile = (($rule | Select-Object -First 1).Profile).ToString() }
                if ($stateText -eq 'Installed' -and $svc -and $rule -and ($ruleProfile -notmatch 'Public')) {
                    return (New-AuditRow -Component $ComponentName -Status 'Healthy' -Detail ("capability={0}; service={1}; firewall={2}" -f $stateText, [string]$svc.Status, $ruleProfile) -HowToFix '')
                }
                return (New-AuditRow -Component $ComponentName -Status 'Missing' -Detail ("capability={0}; service={1}; firewall={2}" -f $stateText, $(if ($svc) { [string]$svc.Status } else { 'absent' }), $(if ($rule) { $ruleProfile } else { 'absent' })) -HowToFix 'Execute elevado: bootstrap-tools.ps1 -Component openssh-server -NonInteractive')
            }
            'vscode-extensions' {
                return (Invoke-AuditVsCodeExtensions -ComponentName $ComponentName)
            }
            default {
                return $null
            }
        }
    }

    foreach ($comp in @($Resolution.ResolvedComponents)) {
        $remainingMs = [int]([Math]::Max(0, ($auditDeadline - (Get-Date)).TotalMilliseconds))
        if ($remainingMs -le 0) {
            Write-Log ("Audit: timeout global atingido antes de {0}; encerrando restante." -f $comp) 'WARN'
            $results.Add((New-BootstrapAuditRow -Component $comp -Status 'Unknown' -Detail ("Audit timeout global apos {0}s antes de auditar componente." -f $TimeoutSeconds) -HowToFix 'Rode novamente com -AuditTimeoutSeconds maior ou audite menos componentes.' -DurationMs 0 -TimedOut $true -ProbeSource 'audit-timeout'))
            continue
        }
        $componentStopwatch = [Diagnostics.Stopwatch]::StartNew()
        $def = $catalog[$comp]
        if (-not $def) {
            Write-Log ("Audit: Componente {0} -> Unknown (sem entrada no catalogo)" -f $comp) 'WARN'
            $componentStopwatch.Stop()
            $results.Add((New-BootstrapAuditRow -Component $comp -Status 'Unknown' -Detail 'Sem definicao no catalogo de componentes.' -HowToFix 'Revise o catalogo de componentes do bootstrap.' -DurationMs $componentStopwatch.ElapsedMilliseconds -ProbeSource 'catalog'))
            continue
        }

        $status = 'Unknown'
        $detail = ''
        $howToFix = ''
        $probeSource = ''
        $probeTimedOut = $false

        $specializedRow = Get-AuditSpecializedRow -ComponentName $comp
        if ($specializedRow) {
            $status = [string]$specializedRow.Status
            $detail = [string]$specializedRow.Detail
            $howToFix = [string]$specializedRow.HowToFix
            if ($specializedRow.PSObject.Properties['ProbeSource']) { $probeSource = [string]$specializedRow.ProbeSource }
            if ($specializedRow.PSObject.Properties['TimedOut']) { $probeTimedOut = [bool]$specializedRow.TimedOut }
        }

        if ($status -eq 'Unknown' -and $def.VersionCheckCommand) {
            try {
                $actualVersion = Invoke-Expression $def.VersionCheckCommand -ErrorAction Stop 2>&1
                $verText = if ($null -eq $actualVersion) { '' } elseif ($actualVersion -is [System.Collections.ICollection] -and -not ($actualVersion -is [string])) {
                    (($actualVersion | ForEach-Object { [string]$_ }) -join ' ').Trim()
                } else {
                    [string]$actualVersion
                }
                if ($def.ExpectedVersion -and $verText -notmatch $def.ExpectedVersion) {
                    $status = 'Unhealthy'
                    $detail = "Versao atual: $verText, Esperada: $($def.ExpectedVersion)"
                    $howToFix = Get-AuditKnownFix -ComponentName $comp
                } else {
                    $status = 'Healthy'
                    $detail = "Versao: $verText"
                }
            } catch {
                $status = 'Missing'
                $detail = "Falha ao verificar versao: $($_.Exception.Message)"
                $howToFix = Get-AuditKnownFix -ComponentName $comp
            }
        }

        if ($status -eq 'Unknown') {
            $probeScript = $def | Select-Object -ExpandProperty ProbePaths -ErrorAction SilentlyContinue
            $probeList = @()
            if ($probeScript) { $probeList = @($probeScript) }
            if ($probeList.Count -gt 0) {
                $wingetId = [string]($def | Select-Object -ExpandProperty Id -ErrorAction SilentlyContinue)
                $found = Test-BootstrapPackageArtifactsPresent -ProbePaths $probeList -WingetId $wingetId
                if ($found) {
                    $status = 'Healthy'
                    $detail = 'ProbePaths encontrado.'
                } else {
                    if (-not [string]::IsNullOrWhiteSpace($wingetId) -and $wingetExe) {
                        $presence = Invoke-AuditWingetPresence -Id $wingetId
                        $probeSource = [string]$presence.ProbeSource
                        $probeTimedOut = [bool]$presence.TimedOut
                    }
                    if (-not [string]::IsNullOrWhiteSpace($wingetId) -and $wingetExe -and -not $probeTimedOut -and [bool]$presence.Installed) {
                        $status = 'GhostInstall'
                        $detail = ('ProbePaths ausente em disco, mas winget lista {0} como instalado. Possivel ghost install.' -f $wingetId)
                        $howToFix = 'Reinstale o pacote via winget ou remova o registro fantasma com winget uninstall.'
                    } elseif ($probeTimedOut) {
                        $status = 'Unknown'
                        $detail = [string]$presence.Detail
                        $howToFix = 'Rode novamente ou use -AuditComponentTimeoutSeconds maior se o winget estiver lento.'
                    } else {
                        $status = 'Missing'
                        $detail = 'Nenhum ProbePaths encontrado.'
                        $howToFix = Get-AuditKnownFix -ComponentName $comp
                    }
                }
            }
        }

        if ($status -eq 'Unknown') {
            $cmdProbe = [string]($def | Select-Object -ExpandProperty CommandName -ErrorAction SilentlyContinue)
            if (-not [string]::IsNullOrWhiteSpace($cmdProbe)) {
                $cmdPath = Resolve-CommandPath -Name $cmdProbe
                if ($cmdPath -and (Test-AuditPathIsWindowsStoreAlias -Path $cmdPath)) {
                    $status = 'AliasOnly'
                    $detail = "Alias da Microsoft Store encontrado: $cmdPath"
                    $howToFix = Get-AuditKnownFix -ComponentName $comp
                } elseif ($cmdPath) {
                    $status = 'Healthy'
                    $detail = "Comando disponivel: $cmdProbe ($cmdPath)"
                } else {
                    $status = 'Missing'
                    $detail = "Comando ausente: $cmdProbe"
                    $howToFix = Get-AuditKnownFix -ComponentName $comp
                }
            }
        }

        if ($status -eq 'Unknown' -and (($def.PSObject.Properties.Name -contains 'CommandNames') -or ([string]$def.Kind -eq 'npm'))) {
            $commandRow = Invoke-AuditDeclaredCommands -ComponentName $comp -ComponentDef $def
            if ($commandRow) {
                $status = [string]$commandRow.Status
                $detail = [string]$commandRow.Detail
                $howToFix = [string]$commandRow.HowToFix
            }
        }

        if ($status -eq 'Unknown' -and [string]$def.Kind -eq 'repo-clone') {
            $repoRow = Invoke-AuditRepoClone -ComponentName $comp -ComponentDef $def
            $status = [string]$repoRow.Status
            $detail = [string]$repoRow.Detail
            $howToFix = [string]$repoRow.HowToFix
        }

        if ($status -eq 'Unknown' -and [string]$def.Kind -eq 'ai-proxy-repo') {
            $toolName = if ($def.PSObject.Properties.Name -contains 'ToolName') { [string]$def.ToolName } else { [string]$comp }
            $proxyRow = Get-BootstrapAiProxyToolDoctorReport -ToolName $toolName
            if ($proxyRow -and [string]$proxyRow['status'] -eq 'configured') {
                $status = 'Healthy'
                $detail = ("Proxy local operacional: {0} ({1}); /v1/models={2}" -f [string]$proxyRow['id'], [string]$proxyRow['baseUrl'], [string]$proxyRow['modelsStatus'])
            } elseif ($proxyRow -and [string]$proxyRow['status'] -eq 'start-required') {
                $status = 'Unhealthy'
                $detail = ("Proxy local instalado, mas API nao esta ouvindo/respondendo: {0} ({1})" -f [string]$proxyRow['id'], [string]$proxyRow['baseUrl'])
                $howToFix = ("Execute install-cli.ps1 --tool {0} --start --yes --no-admin e valide /v1/models." -f [string]$proxyRow['id'])
            } elseif ($proxyRow -and [string]$proxyRow['status'] -eq 'auth-failed') {
                $status = 'Unhealthy'
                $detail = ("Proxy local iniciou, mas /v1/models rejeitou autenticacao redigida: {0}" -f [string]$proxyRow['id'])
                $howToFix = [string]$proxyRow['recommendedAction']
            } elseif ($proxyRow -and [string]$proxyRow['status'] -eq 'unhealthy') {
                $status = 'Unhealthy'
                $detail = ("Proxy local ouvindo, mas /v1/models falhou: {0} ({1})" -f [string]$proxyRow['id'], [string]$proxyRow['modelsStatus'])
                $howToFix = [string]$proxyRow['recommendedAction']
            } elseif ($proxyRow -and [string]$proxyRow['status'] -eq 'warning') {
                $status = 'Unhealthy'
                $detail = ("Proxy local parcial: {0}" -f [string]$proxyRow['sourceRoot'])
                $howToFix = "Execute componente $comp novamente para concluir clone/deps/.env."
            } else {
                $status = 'Missing'
                $detail = ("Proxy local ausente: {0}" -f $toolName)
                $howToFix = "Execute componente $comp para clonar, configurar .env e instalar deps."
            }
        }

        if ($status -eq 'Unknown' -and [string]$def.Kind -eq 'ai-proxy-suite') {
            $suiteRow = New-BootstrapAiProxySuiteDoctorReport
            $configuredCount = [int]$suiteRow['configuredProviders']
            if ([string]$suiteRow['status'] -eq 'ready') {
                $status = 'Healthy'
                $detail = ("Suite de proxies local operacional: {0} provider(s); default Kimi {1}" -f $configuredCount, [string]$suiteRow['defaultBaseUrl'])
            } elseif ([string]$suiteRow['status'] -eq 'degraded') {
                $status = 'Unhealthy'
                $detail = ("Suite de proxies degradada: {0} provider(s) com /v1/models falhando." -f [int]$suiteRow['unhealthyProviders'])
                $howToFix = 'Verifique upstream/login dos providers degradados e rode install-cli.ps1 --tool ai-proxy-suite --start --yes --no-admin.'
            } elseif ([string]$suiteRow['status'] -eq 'start-required') {
                $status = 'Unhealthy'
                $detail = ("Suite de proxies instalada, mas {0} provider(s) exigem start/health." -f [int]$suiteRow['startRequiredProviders'])
                $howToFix = 'Execute install-cli.ps1 --tool ai-proxy-suite --start --yes --no-admin.'
            } else {
                $status = 'Missing'
                $detail = 'Suite de proxies local ainda nao configurada.'
                $howToFix = 'Execute componente ai-proxy-suite ou perfil ai.'
            }
        }

        if ($status -eq 'Unknown' -and [string]$def.Kind -eq 'manual-required') {
            $manualRow = Invoke-AuditManualRequired -ComponentName $comp -ComponentDef $def
            $status = [string]$manualRow.Status
            $detail = [string]$manualRow.Detail
            $howToFix = [string]$manualRow.HowToFix
        }

        if ($status -eq 'Unknown' -and [string]$def.Kind -eq 'winget' -and -not [string]::IsNullOrWhiteSpace([string]$def.Id) -and $wingetExe) {
            try {
                $wid = [string]$def.Id
                $presence = Invoke-AuditWingetPresence -Id $wid
                $probeSource = [string]$presence.ProbeSource
                $probeTimedOut = [bool]$presence.TimedOut
                if ($probeTimedOut) {
                    $status = 'Unknown'
                    $detail = [string]$presence.Detail
                    $howToFix = 'Rode novamente ou use -AuditComponentTimeoutSeconds maior se o winget estiver lento.'
                } elseif ([bool]$presence.Installed) {
                    $probeScript = $def | Select-Object -ExpandProperty ProbePaths -ErrorAction SilentlyContinue
                    $probeList = @()
                    if ($probeScript) { $probeList = @($probeScript) }
                    if ($probeList.Count -gt 0) {
                        $diskFound = Test-BootstrapPackageArtifactsPresent -ProbePaths $probeList -WingetId $wid
                        if ($diskFound) {
                            $status = 'Healthy'
                            $detail = "winget: pacote $wid presente; binario verificado em disco."
                        } else {
                            $status = 'GhostInstall'
                            $detail = ('winget: pacote {0} presente, mas nenhum binario encontrado em ProbePaths. Ghost install.' -f $wid)
                            $howToFix = 'Reinstale o pacote via winget ou remova o registro fantasma com winget uninstall.'
                        }
                    } else {
                        $status = 'Healthy'
                        $detail = "winget: pacote $wid presente."
                    }
                } else {
                    $status = 'Missing'
                    $detail = "winget: pacote $wid nao listado como instalado."
                    $howToFix = Get-AuditKnownFix -ComponentName $comp
                }
            } catch {
                $detail = "winget: erro ao consultar $($def.Id): $($_.Exception.Message)"
                $status = 'Unknown'
                $howToFix = Get-AuditKnownFix -ComponentName $comp
            }
        }

        if ($status -eq 'Unknown' -and -not $probeTimedOut) {
            $status = 'UnsupportedAudit'
            $detail = ('Sem heuristica de auditoria para Kind={0}.' -f [string]$def.Kind)
            $howToFix = 'Nenhuma correcao automatica sugerida para este tipo de componente; valide manualmente ou adicione heuristica de auditoria ao catalogo.'
        }

        $logDetail = if ([string]::IsNullOrWhiteSpace($howToFix)) { $detail } else { "$detail | Como corrigir: $howToFix" }
        Write-Log ("Audit: Componente {0} -> {1} ({2})" -f $comp, $status, $logDetail)

        if ($Repair -and $status -ne 'Healthy' -and $State) {
            Write-Log ("Repair: Tentando reinstalar {0}..." -f $comp) 'WARN'
            try {
                Invoke-BootstrapComponent -Name $comp -State $State
                $status = 'Repaired'
            } catch {
                Write-Log ("Repair: Falha ao reparar {0}: {1}" -f $comp, $_.Exception.Message) 'ERROR'
            }
        }

        $componentStopwatch.Stop()
        $durationMs = [long]$componentStopwatch.ElapsedMilliseconds
        if ($durationMs -gt ($auditComponentTimeoutSeconds * 1000)) {
            $probeTimedOut = $true
            if ([string]::IsNullOrWhiteSpace($probeSource)) { $probeSource = 'component-timeout' }
        }
        $results.Add((New-BootstrapAuditRow -Component $comp -Status $status -Detail $detail -HowToFix $howToFix -ComponentDef $def -DurationMs $durationMs -TimedOut:$probeTimedOut -ProbeSource $probeSource))
    }

    return $results
}


function Reset-BootstrapFileCmdlets {
    $names = @(
        'Remove-Item',
        'Set-Content',
        'Add-Content',
        'Get-Content',
        'New-Item',
        'Copy-Item',
        'Move-Item',
        'Out-File'
    )

    foreach ($name in $names) {
        $fnPath = "function:$name"
        if (Microsoft.PowerShell.Management\Test-Path $fnPath) {
            Microsoft.PowerShell.Management\Remove-Item $fnPath -Force -ErrorAction SilentlyContinue
        }
        $aliasPath = "alias:$name"
        if (Microsoft.PowerShell.Management\Test-Path $aliasPath) {
            Microsoft.PowerShell.Management\Remove-Item $aliasPath -Force -ErrorAction SilentlyContinue
        }
    }

    Microsoft.PowerShell.Core\Import-Module Microsoft.PowerShell.Management -Force | Out-Null
    Microsoft.PowerShell.Core\Import-Module Microsoft.PowerShell.Utility -Force | Out-Null
}

function Refresh-SessionPath {
    $machinePath = [Environment]::GetEnvironmentVariable('Path', 'Machine')
    $userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
    $env:Path = @($machinePath, $userPath) -join ';'
}

function Test-BootstrapSensitiveEnvName {
    param([string]$Name)

    if ([string]::IsNullOrWhiteSpace($Name)) {
        return $false
    }

    return ($Name -match '(^|_)(API_KEY|KEY|TOKEN|SECRET|PASSWORD|PASS|PAT|ORG|ORGANIZATION|PROJECT)($|_)')
}

function Get-BootstrapEnvValueForLog {
    param(
        [string]$Name,
        [string]$Value
    )

    if (Test-BootstrapSensitiveEnvName -Name $Name) {
        return '[redacted]'
    }

    return $Value
}

function Notify-BootstrapEnvironmentChanged {
    try {
        if (-not ('BootstrapNativeMethods' -as [type])) {
            Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;

public static class BootstrapNativeMethods {
    [DllImport("user32.dll", SetLastError = true, CharSet = CharSet.Auto)]
    public static extern IntPtr SendMessageTimeout(
        IntPtr hWnd,
        uint Msg,
        IntPtr wParam,
        string lParam,
        uint fuFlags,
        uint uTimeout,
        out IntPtr lpdwResult
    );
}
"@
        }

        $result = [IntPtr]::Zero
        $null = [BootstrapNativeMethods]::SendMessageTimeout(
            [IntPtr]0xffff,
            0x001A,
            [IntPtr]::Zero,
            'Environment',
            0x0002,
            5000,
            [ref]$result
        )
    } catch {
    }
}

function Stop-BootstrapProcessTree {
    <#
    .SYNOPSIS
        Encerra um processo E TODA a sua arvore de descendentes. Process.Kill() sozinho mata
        apenas o processo direto; helpers que ele gerou (git-remote-https, credential managers,
        daemons de postinstall do npm) sobrevivem como orfaos e continuam segurando a ponta de
        escrita dos pipes redirecionados de stdout/stderr - o que faz ReadToEndAsync().Result
        bloquear indefinidamente. taskkill /T /F derruba a arvore inteira.
    #>
    param([Parameter(Mandatory = $true)][int]$ProcessId)
    if ($ProcessId -le 0) { return }
    try {
        $taskkill = Join-Path $env:SystemRoot 'System32\taskkill.exe'
        if (-not (Test-Path -LiteralPath $taskkill)) { $taskkill = 'taskkill.exe' }
        & $taskkill '/PID' $ProcessId '/T' '/F' 2>$null | Out-Null
    } catch { }
    # Best-effort: kill direto caso taskkill nao esteja disponivel.
    try { (Get-Process -Id $ProcessId -ErrorAction Stop).Kill() } catch { }
}

function Test-BootstrapPlaywrightInstallProcessActive {
    try {
        $rows = @(Get-CimInstance -ClassName Win32_Process -ErrorAction Stop |
            Where-Object {
                [string]$_.CommandLine -match '(?i)(npx|playwright).*playwright.*install|playwright\s+install'
            })
        return ($rows.Count -gt 0)
    } catch {
        return $false
    }
}

function Clear-BootstrapPlaywrightStaleLock {
    <#
    .SYNOPSIS
        Remove o __dirlock orfao do Playwright se nenhum processo de install estiver ativo.
        O Playwright cria esse lock durante `playwright install` e o remove ao terminar; se o
        processo for morto no meio (timeout/kill), o lock sobra e bloqueia TODO install futuro
        com "active lockfile found". Como o bootstrap instala um proxy por vez, removemos o lock
        quando nao ha node/playwright ativo segurando-o.
    #>
    param([string]$CacheRoot = '')
    if ([string]::IsNullOrWhiteSpace($CacheRoot)) {
        $CacheRoot = Join-Path $env:LOCALAPPDATA 'ms-playwright'
    }
    $lock = Join-Path $CacheRoot '__dirlock'
    if (-not (Test-Path -LiteralPath $lock)) { return }
    if (Test-BootstrapPlaywrightInstallProcessActive) {
        try { Write-Log ("Playwright: __dirlock preservado; install ativo detectado em {0}" -f $lock) 'WARN' } catch { }
        return
    }
    try {
        Remove-Item -LiteralPath $lock -Recurse -Force -ErrorAction Stop
        try { Write-Log ("Playwright: removido __dirlock orfao em {0}" -f $lock) 'WARN' } catch { }
    } catch {
        # Se ainda estiver em uso por um processo vivo, deixamos o playwright lidar com isso.
        try { Write-Log ("Playwright: __dirlock presente mas nao removivel (possivel install ativo): {0}" -f $_.Exception.Message) 'WARN' } catch { }
    }
}

function Get-BootstrapAsyncReadResult {
    <#
    .SYNOPSIS
        Le o resultado de uma Task de leitura async (ReadToEndAsync) com prazo maximo. Acessar
        Task.Result diretamente bloqueia ate a leitura completar, o que so ocorre quando TODOS
        os handles da ponta de escrita do pipe fecham. Um neto orfao que herdou o handle nunca
        fecha - travando o processo para sempre (observado: hang de 4h em git clone). Aqui
        esperamos com deadline e abandonamos a leitura se nao concluir, garantindo nao-travamento.
    #>
    param(
        [Parameter(Mandatory = $true)]$Task,
        [int]$TimeoutMs = 15000
    )
    try { if ($Task.Wait($TimeoutMs)) { return [string]$Task.Result } } catch { }
    return ''
}

function Invoke-NativeWithLog {
    <#
    .SYNOPSIS
        Executa binario nativo com captura de saida via tarefas async e timeout configuravel.
        Evita `& $Exe @Args 2>&1` e pipes async, que podem deixar exit code nativo vazar
        para o processo PowerShell antes do bootstrap escrever result.json.
    #>
    param(
        [Parameter(Mandatory = $true)][string]$Exe,
        [string[]]$Args = @(),
        [int]$TimeoutMs = 600000
    )

    $argumentString = (($Args | ForEach-Object {
                $v = [string]$_
                if ($v -match '[\s"]') { '"' + ($v -replace '"', '\"') + '"' } else { $v }
            }) -join ' ')
    $exitCode = -1
    $proc = $null

    try {
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = $Exe
        $psi.Arguments = $argumentString
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $psi.RedirectStandardInput = $false
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true

        $proc = New-Object System.Diagnostics.Process
        $proc.StartInfo = $psi
        [void]$proc.Start()
        $procId = $proc.Id
        $stdoutTask = $proc.StandardOutput.ReadToEndAsync()
        $stderrTask = $proc.StandardError.ReadToEndAsync()

        $timedOut = $false
        if (-not $proc.WaitForExit($TimeoutMs)) {
            Write-Log ("Comando nativo excedeu timeout ({0}ms): {1} {2}. Encerrando processo." -f $TimeoutMs, $Exe, $argumentString) 'WARN'
            Stop-BootstrapProcessTree -ProcessId $procId
            try { $null = $proc.WaitForExit(5000) } catch { }
            $exitCode = 124
            $timedOut = $true
        } else {
            try { $proc.WaitForExit() } catch { }
            $exitCode = [int]$proc.ExitCode
        }

        # Leitura limitada: apos timeout damos prazo curto (a arvore ja foi derrubada); em saida
        # normal, prazo generoso para drenar o buffer. Nunca bloqueamos indefinidamente.
        $readDeadlineMs = if ($timedOut) { 8000 } else { 20000 }
        foreach ($textTask in @($stdoutTask, $stderrTask)) {
            $text = Get-BootstrapAsyncReadResult -Task $textTask -TimeoutMs $readDeadlineMs
            if ([string]::IsNullOrWhiteSpace($text)) { continue }
            $lines = ($text -replace "`0", '' -replace "`r", "`n") -split "`n"
            foreach ($lineValue in @($lines)) {
                $line = [string]$lineValue
                if ([string]::IsNullOrWhiteSpace($line)) { continue }
                try { Add-Content -Path $script:LogPath -Value $line -Encoding utf8 -ErrorAction SilentlyContinue } catch { }
                Write-Host $line
            }
        }
    } finally {
        try { if ($proc) { $proc.Dispose() } } catch { }
        try { $global:LASTEXITCODE = 0 } catch { }
    }

    return $exitCode
}

function Test-WslCorruptionText {
    param([AllowNull()][string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text)) { return $false }
    $normalized = [string]$Text -replace "`0", ''
    return (
        ($normalized -match '(?i)REGDB_E_CLASSNOTREG') -or
        ($normalized -match '(?i)Wsl/CallMsi/Install') -or
        ($normalized -match '(?i)instala(c|ç)(a|ã)o do WSL parece estar corrompida') -or
        ($normalized -match '(?i)Pressione qualquer tecla para reparar o WSL')
    )
}

function Get-BootstrapWslStatusProbe {
    param(
        [Parameter(Mandatory = $true)][string]$WslExe,
        [int]$TimeoutMs = 120000
    )

    $stdoutPath = Join-Path $env:TEMP ('phasezero-wsl-status-out-' + [Guid]::NewGuid().ToString('N') + '.txt')
    $stderrPath = Join-Path $env:TEMP ('phasezero-wsl-status-err-' + [Guid]::NewGuid().ToString('N') + '.txt')
    $proc = $null
    try {
        $proc = Start-Process -FilePath $WslExe -ArgumentList @('--status') -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath -WindowStyle Hidden -PassThru -ErrorAction Stop
        $timedOut = -not $proc.WaitForExit($TimeoutMs)
        if ($timedOut) {
            try { $proc.Kill() } catch { }
            try { $null = $proc.WaitForExit(5000) } catch { }
        }
        $stdout = ''
        $stderr = ''
        try { if (Test-Path -LiteralPath $stdoutPath) { $stdout = [System.IO.File]::ReadAllText($stdoutPath) } } catch { $stdout = '' }
        try { if (Test-Path -LiteralPath $stderrPath) { $stderr = [System.IO.File]::ReadAllText($stderrPath) } } catch { $stderr = '' }
        return [ordered]@{
            exitCode = if ($timedOut) { 124 } else { [int]$proc.ExitCode }
            timedOut = $timedOut
            stdout = $stdout
            stderr = $stderr
            firstLine = (($stdout + "`n" + $stderr) -replace "`0", '' -replace "`r", "`n" -split "`n" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1)
        }
    } catch {
        return [ordered]@{
            exitCode = 1
            timedOut = $false
            stdout = ''
            stderr = $_.Exception.Message
            firstLine = $_.Exception.Message
        }
    } finally {
        try { if ($proc) { $proc.Dispose() } } catch { }
        try { Remove-Item -LiteralPath $stdoutPath,$stderrPath -Force -ErrorAction SilentlyContinue } catch { }
    }
}

function Assert-BootstrapWslNotCorrupt {
    param(
        [Parameter(Mandatory = $true)][string]$WslExe,
        [int]$TimeoutMs = 120000
    )

    $probe = Get-BootstrapWslStatusProbe -WslExe $WslExe -TimeoutMs $TimeoutMs
    $text = [string]($probe.stdout + "`n" + $probe.stderr)
    if (Test-WslCorruptionText -Text $text) {
        throw (New-BootstrapBlockedException -Message 'WSL host corrompido: Wsl/CallMsi/Install/REGDB_E_CLASSNOTREG. Reparo exige administrador para re-registrar/reinstalar Microsoft.WSL.' -Kind 'wsl-msi-registration-broken' -Action 'rerun-elevated-or-repair-wsl' -Reasons @('REGDB_E_CLASSNOTREG','Microsoft.WSL'))
    }
    return $probe
}

function Invoke-NativeCaptureWithLog {
    <#
    .NOTES
        Evitar para saidas muito grandes (ex.: winget list em tabelas longas): use Invoke-WingetListIdProbe
        ou redirecionamento para ficheiro; este caminho espelha cada linha para o log e usa pipes assincronos.
    #>
    param(
        [Parameter(Mandatory = $true)][string]$Exe,
        [string[]]$Args = @(),
        [int]$TimeoutMs = 600000,
        [AllowNull()][string]$InputText = $null
    )

    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $Exe
    $psi.Arguments = (($Args | ForEach-Object {
                $v = [string]$_
                if ($v -match '\s') { '"' + ($v -replace '"', '\"') + '"' } else { $v }
            }) -join ' ')
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    # So redirecionar stdin quando houver dados a enviar: com RedirectStandardInput=true e pipe aberto,
    # alguns EXEs (winget list, etc.) bloqueiam a espera de EOF e o audit/UI nunca chegam a result.json.
    $psi.RedirectStandardInput = ($null -ne $InputText)
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true

    $proc = New-Object System.Diagnostics.Process
    $proc.StartInfo = $psi

    $null = $proc.Start()
    # Captura via ReadToEndAsync (tasks .NET puras). NUNCA usar add_OutputDataReceived com
    # scriptblock aqui: o handler roda em thread do pool SEM runspace e derruba o processo
    # inteiro com PSInvalidOperation/ScriptBlock.GetContext — crash real observado em
    # instalacao full quando o filho emite output assincrono no momento errado.
    $stdoutTask = $proc.StandardOutput.ReadToEndAsync()
    $stderrTask = $proc.StandardError.ReadToEndAsync()

    if ($null -ne $InputText) {
        try { $proc.StandardInput.Write($InputText) } catch { }
        try { $proc.StandardInput.Close() } catch { }
    }

    $timedOut = -not $proc.WaitForExit($TimeoutMs)
    if ($timedOut) {
        try { $proc.Kill() } catch { }
        try { $null = $proc.WaitForExit(5000) } catch { }
    }

    $exitCode = if ($timedOut) { 124 } else { [int]$proc.ExitCode }
    # Apos exit/kill os pipes fecham e as tasks completam; o limite de 15s cobre o caso de um
    # processo-neto herdar o handle do pipe e segurar o EOF indefinidamente.
    $stdout = ''
    $stderr = ''
    try {
        if ([System.Threading.Tasks.Task]::WaitAll(@($stdoutTask, $stderrTask), 15000)) {
            $stdout = [string]$stdoutTask.Result
            $stderr = [string]$stderrTask.Result
        } else {
            Write-Log ("Invoke-NativeCaptureWithLog: streams de {0} nao fecharam em 15s apos exit; capturando saida parcial indisponivel." -f $Exe) 'WARN'
        }
    } catch {
        Write-Log ("Invoke-NativeCaptureWithLog: falha ao ler streams de {0}: {1}" -f $Exe, $_.Exception.Message) 'WARN'
    }
    try { $proc.Dispose() } catch { }

    foreach ($line in ((($stdout + "`n" + $stderr) -replace "`r", '') -split "`n")) {
        $text = [string]$line
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        Add-Content -Path $script:LogPath -Value $text -Encoding utf8
        Write-Host $text
    }

    return [ordered]@{
        exitCode = $exitCode
        timedOut = $timedOut
        stdout   = $stdout
        stderr   = $stderr
    }
}

function Ensure-PathUserContains {
    param([Parameter(Mandatory = $true)][string]$Dir)
    if (-not $Dir) { return }
    $Dir = $Dir.Trim().TrimEnd('\')
    if (-not (Test-Path $Dir)) { return }
    $userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
    if (-not $userPath) { $userPath = '' }
    $parts = $userPath -split ';' | ForEach-Object { $_.Trim().TrimEnd('\') } | Where-Object { $_ -ne '' }
    $exists = $parts | Where-Object { $_ -ieq $Dir } | Select-Object -First 1
    if (-not $exists) {
        $newUserPath = ($userPath.TrimEnd(';') + ';' + $Dir).Trim(';')
        [Environment]::SetEnvironmentVariable('Path', $newUserPath, 'User')
        Write-Log "Adicionado ao PATH (Usuário): $Dir"
    } else {
        Write-Log "Já está no PATH (Usuário): $Dir"
    }
    Refresh-SessionPath
    if (($env:Path -split ';' | ForEach-Object { $_.Trim().TrimEnd('\') }) -inotcontains $Dir) {
        $env:Path = ($env:Path.TrimEnd(';') + ';' + $Dir).Trim(';')
    }
}

function Remove-PathUserEntry {
    param([Parameter(Mandatory = $true)][string]$Dir)
    if ([string]::IsNullOrWhiteSpace($Dir)) { return $false }
    $normalizedDir = $Dir.Trim().TrimEnd('\')
    $userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
    if ([string]::IsNullOrWhiteSpace($userPath)) { return $false }

    $removed = $false
    $kept = New-Object System.Collections.Generic.List[string]
    foreach ($part in @($userPath -split ';')) {
        $text = ([string]$part).Trim()
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        if ($text.TrimEnd('\') -ieq $normalizedDir) {
            $removed = $true
            continue
        }
        $kept.Add($text) | Out-Null
    }

    if ($removed) {
        [Environment]::SetEnvironmentVariable('Path', (($kept.ToArray()) -join ';'), 'User')
        $env:Path = (@(($env:Path -split ';') | Where-Object { ([string]$_).Trim().TrimEnd('\') -ine $normalizedDir }) -join ';')
        Refresh-SessionPath
        try { Write-Log "Removido do PATH (Usuário): $normalizedDir" } catch { }
    }
    return $removed
}

function Ensure-PathUserContainsFirst {
    param([Parameter(Mandatory = $true)][string]$Dir)
    if (-not $Dir) { return }
    $Dir = $Dir.Trim().TrimEnd('\')
    if (-not (Test-Path $Dir)) { return }

    $userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
    if (-not $userPath) { $userPath = '' }
    $parts = $userPath -split ';' | ForEach-Object { $_.Trim().TrimEnd('\') } | Where-Object { $_ -ne '' }
    $parts = @($parts | Where-Object { $_ -ine $Dir })

    $newUserPath = (@($Dir) + $parts) -join ';'
    [Environment]::SetEnvironmentVariable('Path', $newUserPath, 'User')
    Write-Log "Priorizado no PATH (Usuário): $Dir"

    Refresh-SessionPath
}

function Ensure-PathUserPrioritize {
    param([Parameter(Mandatory = $true)][string[]]$Dirs)
    $clean = @()
    foreach ($d in $Dirs) {
        if (-not $d) { continue }
        $dd = $d.Trim().TrimEnd('\')
        if (-not $dd) { continue }
        if (-not (Test-Path $dd)) { continue }
        if ($clean -inotcontains $dd) { $clean += $dd }
    }
    if (-not $clean -or $clean.Count -eq 0) { return }

    $userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
    if (-not $userPath) { $userPath = '' }
    $parts = $userPath -split ';' | ForEach-Object { $_.Trim().TrimEnd('\') } | Where-Object { $_ -ne '' }
    foreach ($d in $clean) { $parts = @($parts | Where-Object { $_ -ine $d }) }

    $newUserPath = ($clean + $parts) -join ';'
    [Environment]::SetEnvironmentVariable('Path', $newUserPath, 'User')
    Write-Log ("Python PATH priorizado (Usuário): " + ($clean -join '; '))
    Refresh-SessionPath
}

function Ensure-PythonPathHealthy {
    param([Parameter(Mandatory = $true)][string]$PythonExe)
    if (-not $PythonExe) { return }
    if (-not (Test-Path $PythonExe)) { return }
    if ($PythonExe -match '\\Microsoft\\WindowsApps\\') { return }

    $pythonDir = Split-Path $PythonExe -Parent
    $scriptsDir = Join-Path $pythonDir 'Scripts'
    Ensure-PathUserPrioritize -Dirs @($scriptsDir, $pythonDir)

    $resolved = Resolve-CommandPath -Name 'python'
    if ($resolved -and ($resolved -match '\\Microsoft\\WindowsApps\\')) {
        Write-Log "python ainda resolve para WindowsApps apos priorização: $resolved" 'WARN'
    }
}

function Set-UserEnvVar {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [Parameter(Mandatory = $true)][object]$Value
    )
    $valueString = if ($null -eq $Value) {
        ''
    } elseif ($Value -is [string]) {
        $Value.Trim()
    } elseif ($Value -is [System.Collections.IEnumerable]) {
        $picked = $null
        foreach ($piece in @($Value)) {
            if ($null -eq $piece) { continue }
            $s = [string]$piece
            if (-not [string]::IsNullOrWhiteSpace($s)) { $picked = $s.Trim(); break }
        }
        if ($null -eq $picked) { '' } else { $picked }
    } else {
        ([string]$Value).Trim()
    }

    $current = [Environment]::GetEnvironmentVariable($Name, 'User')
    $logValue = Get-BootstrapEnvValueForLog -Name $Name -Value $valueString
    if ($current -ne $valueString) {
        [Environment]::SetEnvironmentVariable($Name, $valueString, 'User')
        [Environment]::SetEnvironmentVariable($Name, $valueString, 'Process')
        Notify-BootstrapEnvironmentChanged
        Write-Log "Definido $Name (Usuário) = $logValue"
    } else {
        [Environment]::SetEnvironmentVariable($Name, $valueString, 'Process')
        Write-Log "Já definido $Name (Usuário) = $logValue"
    }
}

function Test-IsAdmin {
    try {
        $id = [Security.Principal.WindowsIdentity]::GetCurrent()
        $p = New-Object Security.Principal.WindowsPrincipal($id)
        return $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    } catch {
        return $false
    }
}

function Test-BootstrapElevatedOrSystem {
    try {
        $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
        if ($null -eq $identity) { return $false }
        if ([string]$identity.User -eq 'S-1-5-18') { return $true }
        $principal = New-Object Security.Principal.WindowsPrincipal($identity)
        return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    } catch {
        return $false
    }
}

function Test-BootstrapAutomatedTestMode {
    if ($BootstrapUiLibraryMode) { return $true }
    if (-not [string]::IsNullOrWhiteSpace([string]$env:PESTER_RUN_PATH)) { return $true }
    if (-not [string]::IsNullOrWhiteSpace([string]$env:BOOTSTRAP_TEST_MODE) -and [string]$env:BOOTSTRAP_TEST_MODE -eq '1') { return $true }
    return $false
}

function Get-BootstrapSteamDeckMaintenanceAssetsRoot {
    return (Join-Path $PSScriptRoot 'assets\steamdeck\maintenance')
}

function Get-BootstrapSteamDeckShellMenuSpec {
    $maintenanceRoot = Get-BootstrapSteamDeckMaintenanceRoot
    if (-not (Test-Path $maintenanceRoot)) {
        $maintenanceRoot = Get-BootstrapSteamDeckMaintenanceAssetsRoot
    }
    $powershellExe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    if (-not (Test-Path $powershellExe)) { $powershellExe = 'powershell.exe' }

    $commands = @(
        [ordered]@{ Id = 'power-save'; Verb = 'Plano Energia: Economia'; Script = (Join-Path $maintenanceRoot 'Set-PowerPlan.ps1'); Args = @('-Plan', 'SCHEME_MIN') }
        [ordered]@{ Id = 'power-balanced'; Verb = 'Plano Energia: Balanceado'; Script = (Join-Path $maintenanceRoot 'Set-PowerPlan.ps1'); Args = @('-Plan', 'SCHEME_BALANCED') }
        [ordered]@{ Id = 'power-performance'; Verb = 'Plano Energia: Alto desempenho'; Script = (Join-Path $maintenanceRoot 'Set-PowerPlan.ps1'); Args = @('-Plan', 'SCHEME_MAX') }
        [ordered]@{ Id = 'windows-update-now'; Verb = 'Windows Update agora'; Script = (Join-Path $maintenanceRoot 'Invoke-WindowsUpdateNow.ps1'); Args = @() }
        [ordered]@{ Id = 'compact-os'; Verb = 'Compactar Sistema (CompactOS)'; Script = (Join-Path $maintenanceRoot 'Enable-CompactOS.ps1'); Args = @() }
        [ordered]@{ Id = 'restore-point'; Verb = 'Criar ponto de restauração'; Script = (Join-Path $maintenanceRoot 'New-SystemRestorePoint.ps1'); Args = @() }
        [ordered]@{ Id = 'clear-caches'; Verb = 'Limpeza rápida de caches'; Script = (Join-Path $maintenanceRoot 'Clear-SteamDeckCaches.ps1'); Args = @() }
        [ordered]@{ Id = 'clear-standby-memory'; Verb = 'Limpar memória standby'; Script = (Join-Path $maintenanceRoot 'Clear-StandbyMemory.ps1'); Args = @() }
        [ordered]@{ Id = 'apply-sharedvram-launch-options'; Verb = 'Aplicar -sharedvram (allowlist)'; Script = (Join-Path $maintenanceRoot 'Apply-SharedVramLaunchOptions.ps1'); Args = @() }
    )

    $rendered = @()
    foreach ($command in @($commands)) {
        $argString = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', ('"{0}"' -f [string]$command.Script)) + @($command.Args)
        $rendered += @([ordered]@{
            Id = [string]$command.Id
            Verb = [string]$command.Verb
            Script = [string]$command.Script
            Command = ('"{0}" {1}' -f $powershellExe, ($argString -join ' '))
        })
    }

    return [ordered]@{
        RootPath = 'HKLM:\SOFTWARE\Classes\DesktopBackground\Shell\ZBootstrapSteamDeck'
        RootVerb = 'Z Bootstrap Steam Deck'
        RootIcon = $powershellExe
        Commands = @($rendered)
    }
}

function Install-BootstrapSteamDeckShellMenu {
    param([switch]$DryRun)

    $spec = Get-BootstrapSteamDeckShellMenuSpec
    if ($DryRun) {
        return [ordered]@{
            DryRun = $true
            Changed = $false
            RegistryPath = [string]$spec.RootPath
            Commands = @($spec.Commands)
        }
    }

    if (-not (Test-BootstrapElevatedOrSystem)) {
        throw 'Install-BootstrapSteamDeckShellMenu requer contexto Administrador ou SYSTEM.'
    }

    $rootPath = [string]$spec.RootPath
    $null = New-Item -Path $rootPath -Force
    Set-ItemProperty -Path $rootPath -Name 'MUIVerb' -Value ([string]$spec.RootVerb) -Force
    Set-ItemProperty -Path $rootPath -Name 'Icon' -Value ([string]$spec.RootIcon) -Force

    $shellPath = Join-Path $rootPath 'shell'
    $null = New-Item -Path $shellPath -Force
    foreach ($command in @($spec.Commands)) {
        $entryPath = Join-Path $shellPath ([string]$command.Id)
        $commandPath = Join-Path $entryPath 'command'
        $null = New-Item -Path $entryPath -Force
        Set-ItemProperty -Path $entryPath -Name 'MUIVerb' -Value ([string]$command.Verb) -Force
        $null = New-Item -Path $commandPath -Force
        Set-Item -Path $commandPath -Value ([string]$command.Command) -Force
    }

    if (-not (Test-BootstrapAutomatedTestMode)) {
        try {
            Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue
            Start-Process explorer.exe | Out-Null
        } catch {
            Write-Log "Falha ao reiniciar explorer apos shell menu: $($_.Exception.Message)" 'WARN'
        }
    }

    return [ordered]@{
        DryRun = $false
        Changed = $true
        RegistryPath = $rootPath
        Commands = @($spec.Commands)
    }
}

function Ensure-ProxyEnvFromWinHttp {
    $raw = $null
    try {
        $raw = & netsh winhttp show proxy 2>&1
    } catch {
        $raw = $null
    }
    if (-not $raw) { return }

    $text = ($raw | Out-String)
    if ($text -match 'Direct access') { return }

    $proxyLine = ($raw | Where-Object { $_ -match 'Proxy Server\\(s\\)' } | Select-Object -First 1)
    if (-not $proxyLine) { return }

    $proxy = ($proxyLine -replace '^.*Proxy Server\\(s\\)\\s*:\\s*', '').Trim()
    if (-not $proxy) { return }

    $httpProxy = $null
    $httpsProxy = $null
    if ($proxy -match 'http\\s*=\\s*([^;\\s]+)') { $httpProxy = $Matches[1] }
    if ($proxy -match 'https\\s*=\\s*([^;\\s]+)') { $httpsProxy = $Matches[1] }
    if (-not $httpProxy -and -not $httpsProxy) {
        $httpProxy = $proxy
        $httpsProxy = $proxy
    }

    if (-not $env:HTTP_PROXY -and $httpProxy) {
        $env:HTTP_PROXY = $httpProxy
        Write-Log "Detectado proxy (WinHTTP) -> HTTP_PROXY=$httpProxy"
    }
    if (-not $env:HTTPS_PROXY -and $httpsProxy) {
        $env:HTTPS_PROXY = $httpsProxy
        Write-Log "Detectado proxy (WinHTTP) -> HTTPS_PROXY=$httpsProxy"
    }

    $bypassLine = ($raw | Where-Object { $_ -match 'Bypass List' } | Select-Object -First 1)
    if ($bypassLine -and -not $env:NO_PROXY) {
        $bypass = ($bypassLine -replace '^.*Bypass List\\s*:\\s*', '').Trim()
        if ($bypass -and ($bypass -notmatch 'None')) {
            $env:NO_PROXY = ($bypass -replace ';', ',')
            Write-Log "Detectado proxy bypass (WinHTTP) -> NO_PROXY=$($env:NO_PROXY)"
        }
    }
}

function Get-BootstrapAppInstallerPackage {
    try {
        return Get-AppxPackage -Name 'Microsoft.DesktopAppInstaller' -ErrorAction SilentlyContinue | Select-Object -First 1
    } catch {
        return $null
    }
}

function Get-BootstrapPendingRebootReasons {
    $reasons = New-Object System.Collections.Generic.List[string]

    try {
        if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') {
            $reasons.Add('Component Based Servicing')
        }
    } catch {
    }

    try {
        if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') {
            $reasons.Add('Windows Update')
        }
    } catch {
    }

    try {
        $sessionManager = Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -ErrorAction SilentlyContinue
        if ($sessionManager -and $sessionManager.PendingFileRenameOperations) {
            $reasons.Add('PendingFileRenameOperations')
        }
    } catch {
    }

    try {
        $updateExeVolatile = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Updates' -Name 'UpdateExeVolatile' -ErrorAction SilentlyContinue
        if ($updateExeVolatile -and ($updateExeVolatile.UpdateExeVolatile -as [int]) -gt 0) {
            $reasons.Add('UpdateExeVolatile')
        }
    } catch {
    }

    return @($reasons | Select-Object -Unique)
}

function Normalize-BootstrapPendingFileRenamePath {
    param([AllowNull()][string]$Path)

    $text = ([string]$Path).Trim()
    if ([string]::IsNullOrWhiteSpace($text)) { return '' }
    $text = $text -replace '^\*\d+', ''
    $text = $text -replace '^\\\?\?\\', ''
    return $text
}

function Get-BootstrapPendingFileRenameOperationCategory {
    param(
        [AllowNull()][string]$Source,
        [AllowNull()][string]$Destination
    )

    $joined = ((@($Source, $Destination) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }) -join ' ').ToLowerInvariant()
    if ($joined -match '\\system32\\spool\\drivers\\') { return 'print-driver' }
    if ($joined -match 'gamingservices|gameinput') { return 'gaming-services' }
    if ($joined -match '\\windows\\installer\\|\\programdata\\package cache\\|\\installer\\|\.msi(\s|$)|\.msp(\s|$)|msiexec|desktopappinstaller|appinstaller|winget') { return 'installer' }
    if ($joined -match '\\windows\\softwaredistribution\\|\\winsxs\\|\\servicing\\') { return 'windows-update' }
    if ($joined -match '\\windows\\system32\\drivers\\|\\driverstore\\') { return 'driver' }
    if ($joined -match '\\windows\\system32\\') { return 'system-file' }
    return 'unknown'
}

function Test-BootstrapPendingFileRenameOperationMsiHostile {
    param(
        [AllowNull()][string]$Source,
        [AllowNull()][string]$Destination
    )

    $category = Get-BootstrapPendingFileRenameOperationCategory -Source $Source -Destination $Destination
    return (@('installer', 'windows-update') -contains $category)
}

function Get-BootstrapPendingFileRenameOperationRecords {
    param([AllowNull()][string[]]$Operations = $null)

    if ($null -eq $Operations) {
        try {
            $sessionManager = Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -ErrorAction SilentlyContinue
            if ($sessionManager -and $sessionManager.PendingFileRenameOperations) {
                $Operations = @($sessionManager.PendingFileRenameOperations)
            } else {
                $Operations = @()
            }
        } catch {
            $Operations = @()
        }
    }

    $records = New-Object System.Collections.Generic.List[object]
    $items = @($Operations)
    for ($i = 0; $i -lt $items.Count; $i += 2) {
        $source = Normalize-BootstrapPendingFileRenamePath -Path ([string]$items[$i])
        $destination = ''
        if (($i + 1) -lt $items.Count) {
            $destination = Normalize-BootstrapPendingFileRenamePath -Path ([string]$items[$i + 1])
        }
        if ([string]::IsNullOrWhiteSpace($source) -and [string]::IsNullOrWhiteSpace($destination)) { continue }

        $category = Get-BootstrapPendingFileRenameOperationCategory -Source $source -Destination $destination
        $records.Add([pscustomobject]@{
                source = $source
                destination = $destination
                action = $(if ([string]::IsNullOrWhiteSpace($destination)) { 'delete' } else { 'rename' })
                category = $category
                msiHostile = [bool](Test-BootstrapPendingFileRenameOperationMsiHostile -Source $source -Destination $destination)
            })
    }

    return @($records.ToArray())
}

function Get-BootstrapPendingRebootDetails {
    param([AllowNull()][string[]]$Reasons = $null)

    if ($null -eq $Reasons) {
        try { $Reasons = @(Get-BootstrapPendingRebootReasons) } catch { $Reasons = @() }
    }

    $details = New-Object System.Collections.Generic.List[object]
    foreach ($reason in @($Reasons)) {
        $r = [string]$reason
        if ($r -eq 'PendingFileRenameOperations') {
            $records = @(Get-BootstrapPendingFileRenameOperationRecords)
            if ($records.Count -eq 0) {
                $details.Add([pscustomobject]@{
                        reason = $r
                        category = 'unreadable'
                        msiHostile = $true
                        count = 0
                        source = ''
                        destination = ''
                    })
                continue
            }
            foreach ($record in $records) {
                $details.Add([pscustomobject]@{
                        reason = $r
                        category = [string]$record.category
                        msiHostile = [bool]$record.msiHostile
                        count = 1
                        source = [string]$record.source
                        destination = [string]$record.destination
                    })
            }
            continue
        }

        $details.Add([pscustomobject]@{
                reason = $r
                category = $(if ($r -eq 'UpdateExeVolatile') { 'installer' } elseif ($r -match 'Windows Update|Component Based Servicing') { 'windows-update' } else { 'system' })
                msiHostile = [bool]($r -eq 'UpdateExeVolatile')
                count = 1
                source = ''
                destination = ''
            })
    }

    return @($details.ToArray())
}

function Get-BootstrapMsiHostilePendingRebootReasons {
    param([AllowNull()][string[]]$Reasons = $null)

    if ($null -eq $Reasons) {
        try { $Reasons = @(Get-BootstrapPendingRebootReasons) } catch { $Reasons = @() }
    }

    $blockers = New-Object System.Collections.Generic.List[string]
    foreach ($reason in @($Reasons)) {
        $r = [string]$reason
        if ($r -eq 'UpdateExeVolatile') {
            $blockers.Add($r)
            continue
        }
        if ($r -eq 'PendingFileRenameOperations') {
            $records = @(Get-BootstrapPendingFileRenameOperationRecords)
            if ($records.Count -eq 0 -or @($records | Where-Object { [bool]$_.msiHostile }).Count -gt 0) {
                $blockers.Add($r)
            }
        }
    }
    return @($blockers | Select-Object -Unique)
}

function New-BootstrapBlockedException {
    param(
        [Parameter(Mandatory = $true)][string]$Message,
        [Parameter(Mandatory = $true)][string]$Kind,
        [Parameter(Mandatory = $true)][string]$Action,
        [string[]]$Reasons = @()
    )

    $ex = New-Object System.InvalidOperationException($Message)
    $ex.Data['BootstrapStatus'] = 'blocked'
    $ex.Data['BootstrapBlockerKind'] = $Kind
    $ex.Data['BootstrapAction'] = $Action
    $ex.Data['BootstrapReasons'] = @($Reasons)
    return $ex
}

function Register-BootstrapComponentSkip {
    param(
        [AllowNull()][hashtable]$State = $null,
        [string]$ComponentName = '',
        [string]$Reason = 'skipped',
        [string]$Message = '',
        [string]$Action = '',
        [string]$PackageId = '',
        [string]$DisplayName = '',
        [AllowNull()][object]$ExitCode = $null
    )

    if (-not $State) { return }
    if (-not $State.ContainsKey('SkippedComponents')) {
        $State.SkippedComponents = New-Object System.Collections.Generic.List[object]
    }
    if (-not $State.ContainsKey('Warnings')) {
        $State.Warnings = New-Object System.Collections.Generic.List[string]
    }

    $record = [ordered]@{
        component = $ComponentName
        reason = $Reason
        message = $Message
        action = $Action
        packageId = $PackageId
        displayName = $DisplayName
        exitCode = $ExitCode
        timestamp = (Get-Date).ToString('o')
    }
    $State.SkippedComponents.Add($record)
    if (-not [string]::IsNullOrWhiteSpace($Message)) {
        $State.Warnings.Add($Message)
    }
    if (-not [string]::IsNullOrWhiteSpace($ComponentName)) {
        $State.ComponentStatus[$ComponentName] = [ordered]@{
            status = 'skipped'
            timestamp = $record.timestamp
            reason = $Reason
            warning = $Message
            action = $Action
            packageId = $PackageId
            exitCode = $ExitCode
        }
    }
}

function Test-BootstrapComponentSkipped {
    param(
        [AllowNull()][hashtable]$State = $null,
        [Parameter(Mandatory = $true)][string]$ComponentName
    )

    if (-not $State -or -not $State.ContainsKey('SkippedComponents')) { return $false }
    foreach ($item in @($State.SkippedComponents.ToArray())) {
        if ([string]$item.component -eq $ComponentName) { return $true }
    }
    return $false
}

function Get-BootstrapBlockedErrorInfo {
    param([AllowNull()]$ErrorRecord)

    $info = [ordered]@{
        IsBlocked = $false
        Kind = ''
        Action = ''
        Reasons = @()
    }

    if (-not $ErrorRecord -or -not $ErrorRecord.Exception) { return $info }

    try {
        if ([string]$ErrorRecord.Exception.Data['BootstrapStatus'] -eq 'blocked') {
            $info.IsBlocked = $true
            $info.Kind = [string]$ErrorRecord.Exception.Data['BootstrapBlockerKind']
            $info.Action = [string]$ErrorRecord.Exception.Data['BootstrapAction']
            $info.Reasons = @($ErrorRecord.Exception.Data['BootstrapReasons'])
        }
    } catch {
    }
    return $info
}

function Get-BootstrapProcessesByName {
    param([Parameter(Mandatory = $true)][string]$Name)

    $exeName = if ($Name -match '(?i)\.exe$') { $Name } else { "$Name.exe" }
    try {
        return @(
            Get-CimInstance Win32_Process -Filter ("Name='{0}'" -f ($exeName -replace "'", "''")) -ErrorAction Stop |
                ForEach-Object {
                    [pscustomobject]@{
                        ProcessName = ([string]$_.Name -replace '(?i)\.exe$', '')
                        Id = [int]$_.ProcessId
                        StartTime = $_.CreationDate
                        Path = [string]$_.ExecutablePath
                        CommandLine = [string]$_.CommandLine
                    }
                }
        )
    } catch {
        return @(Get-Process -Name $Name -ErrorAction SilentlyContinue)
    }
}

function Test-BootstrapInstallerProcessIsBusy {
    param(
        [Parameter(Mandatory = $true)]$Process,
        [Parameter(Mandatory = $true)][datetime]$WaitStarted
    )

    $name = ([string]$Process.ProcessName).Trim()
    $start = $null
    try {
        if ($Process.PSObject.Properties.Name -contains 'StartTime' -and $null -ne $Process.StartTime) {
            $start = [datetime]$Process.StartTime
        }
    } catch {
        $start = $null
    }
    $path = ''
    if ($Process.PSObject.Properties.Name -contains 'Path') { $path = [string]$Process.Path }
    $commandLine = ''
    if ($Process.PSObject.Properties.Name -contains 'CommandLine') { $commandLine = [string]$Process.CommandLine }

    if ($name -ieq 'WindowsPackageManagerServer') {
        if ($start -and $start -lt $WaitStarted.AddMinutes(-2)) { return $false }
        return $true
    }

    if ($name -ieq 'msiexec') {
        if ([string]::IsNullOrWhiteSpace($path) -and [string]::IsNullOrWhiteSpace($commandLine) -and $start -and $start -lt $WaitStarted.AddMinutes(-2)) {
            return $false
        }
        if ($start -and $start -lt $WaitStarted.AddMinutes(-30)) { return $false }
        return $true
    }

    return $true
}

function Wait-BootstrapWingetMsiIdle {
    param(
        [int]$TimeoutSeconds = 60,
        [int]$HeartbeatSeconds = 30
    )

    $timeout = [Math]::Max(1, $TimeoutSeconds)
    $heartbeat = [Math]::Max(1, $HeartbeatSeconds)
    $processNames = @('msiexec', 'WindowsPackageManagerServer', 'winget')
    $lastHeartbeat = -1

    for ($elapsed = 0; $elapsed -lt $timeout; $elapsed++) {
        $referenceTime = Get-Date
        $active = @(
            foreach ($name in $processNames) {
                Get-BootstrapProcessesByName -Name $name | Where-Object { Test-BootstrapInstallerProcessIsBusy -Process $_ -WaitStarted $referenceTime }
            }
        )
        if (@($active).Count -eq 0) { return $true }

        if ($lastHeartbeat -lt 0 -or (($elapsed - $lastHeartbeat) -ge $heartbeat)) {
            $summary = @($active | Select-Object -First 6 | ForEach-Object { '{0}:{1}' -f $_.ProcessName, $_.Id }) -join ', '
            Write-Log ("winget/msi: aguardando processos ficarem ociosos ({0}s/{1}s): {2}" -f $elapsed, $timeout, $summary) 'WARN'
            $lastHeartbeat = $elapsed
        }
        Start-Sleep -Seconds 1
    }

    $referenceTime = Get-Date
    $remaining = @(
        foreach ($name in $processNames) {
            Get-BootstrapProcessesByName -Name $name | Where-Object { Test-BootstrapInstallerProcessIsBusy -Process $_ -WaitStarted $referenceTime }
        }
    )
    if (@($remaining).Count -eq 0) { return $true }

    $remainingSummary = @($remaining | Select-Object -First 6 | ForEach-Object { '{0}:{1}' -f $_.ProcessName, $_.Id }) -join ', '
    Write-Log ("winget/msi: timeout aguardando ociosidade apos {0}s: {1}" -f $timeout, $remainingSummary) 'WARN'
    return $false
}

function Test-BootstrapTcpEndpoint {
    param(
        [Parameter(Mandatory = $true)][string]$HostName,
        [int]$Port = 443,
        [int]$TimeoutMilliseconds = 4000
    )

    $client = $null
    try {
        [void][Net.Dns]::GetHostAddresses($HostName)
        $client = New-Object Net.Sockets.TcpClient
        $async = $client.BeginConnect($HostName, $Port, $null, $null)
        if (-not $async.AsyncWaitHandle.WaitOne($TimeoutMilliseconds, $false)) {
            return $false
        }
        $client.EndConnect($async)
        return $true
    } catch {
        return $false
    } finally {
        if ($client) {
            $client.Dispose()
        }
    }
}

function Get-BootstrapPreflightRequirements {
    param([string[]]$ResolvedComponents)

    $catalog = Get-BootstrapComponentCatalog
    $requiresNetwork = $false
    $requiresWinget = $false
    $needsGithub = $false
    $needsMicrosoft = $false
    $needsOpenCode = $false
    $needsChocolatey = $false

    foreach ($componentName in @($ResolvedComponents)) {
        $componentDef = $catalog[$componentName]
        if (-not $componentDef) { continue }

        switch ($componentDef.Kind) {
            'system-core' {
                $requiresNetwork = $true
                $requiresWinget = $true
                $needsMicrosoft = $true
            }
            'git-core' {
                $requiresNetwork = $true
                $requiresWinget = $true
                $needsMicrosoft = $true
            }
            'node-core' {
                $requiresNetwork = $true
                $requiresWinget = $true
                $needsMicrosoft = $true
            }
            'dotnet-core' {
                $requiresNetwork = $true
                $requiresWinget = $true
                $needsMicrosoft = $true
            }
            'python-core' {
                $requiresNetwork = $true
                $requiresWinget = $true
                $needsMicrosoft = $true
            }
            'vscode-extension' {
                $requiresNetwork = $true
            }
            'sevenzip' {
                $requiresNetwork = $true
                $requiresWinget = $true
                $needsMicrosoft = $true
            }
            'winget' {
                $requiresNetwork = $true
                $requiresWinget = $true
                $needsMicrosoft = $true
            }
            'wsl-core' {
                $requiresNetwork = $true
                $requiresWinget = $true
                $needsMicrosoft = $true
            }
            'wsl-ui' {
                $requiresNetwork = $true
                $requiresWinget = $true
                $needsMicrosoft = $true
            }
            'claude-code' {
                $requiresNetwork = $true
                $requiresWinget = $true
                $needsMicrosoft = $true
            }
            'vscode-extensions' {
                $requiresNetwork = $true
            }
            'bootstrap-mcps' {
                $requiresNetwork = $true
            }
            'codex-installer' {
                $requiresNetwork = $true
                $requiresWinget = $true
                $needsMicrosoft = $true
            }
            'npm' {
                $requiresNetwork = $true
            }
            'uvtool' {
                $requiresNetwork = $true
            }
            'goose' {
                $requiresNetwork = $true
                $needsGithub = $true
            }
            'opencode' {
                $requiresNetwork = $true
                $needsOpenCode = $true
            }
            'openclaw' {
                $requiresNetwork = $true
            }
            'repo-clone' {
                $requiresNetwork = $true
                $needsGithub = $true
            }
            'ai-proxy-repo' {
                $requiresNetwork = $true
                $needsGithub = $true
            }
            'ai-proxy-suite' {
                $requiresNetwork = $true
                $needsGithub = $true
            }
            'steamdeck-tools' {
                $requiresNetwork = $true
                $needsGithub = $true
            }
            'amd-nebula-driver' {
                $requiresNetwork = $true
            }
            'steamdeck-zip-driver' {
                $requiresNetwork = $true
            }
            'chocolatey' {
                $requiresNetwork = $true
                $needsChocolatey = $true
            }
        }
    }

    $connectivityGroups = New-Object System.Collections.Generic.List[object]
    if ($needsMicrosoft) {
        $connectivityGroups.Add([pscustomobject]@{
            Name = 'winget-store'
            Hosts = @('cdn.winget.microsoft.com', 'storeedgefd.dsx.mp.microsoft.com')
        })
    }
    if ($needsGithub) {
        $connectivityGroups.Add([pscustomobject]@{
            Name = 'github'
            Hosts = @('github.com', 'api.github.com', 'objects.githubusercontent.com')
        })
    }
    if ($needsOpenCode) {
        $connectivityGroups.Add([pscustomobject]@{
            Name = 'opencode'
            Hosts = @('opencode.ai')
        })
    }
    if ($needsChocolatey) {
        $connectivityGroups.Add([pscustomobject]@{
            Name = 'chocolatey'
            Hosts = @('community.chocolatey.org', 'packages.chocolatey.org')
        })
    }

    return [ordered]@{
        RequiresNetwork = $requiresNetwork
        RequiresWinget = $requiresWinget
        ConnectivityGroups = $(if ($connectivityGroups.Count -gt 0) { $connectivityGroups.ToArray() } else { @() })
    }
}

function Invoke-BootstrapExecutionPreflight {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [AllowEmptyCollection()]
        [Parameter(Mandatory = $true)][string[]]$ResolvedComponents
    )

    if ($State.PreflightDone) { return }

    Write-Log 'Executando preflight operacional...'
    Write-Log "PowerShell: $($PSVersionTable.PSVersion) ($($PSVersionTable.PSEdition))"
    Write-Log "LanguageMode: $($ExecutionContext.SessionState.LanguageMode)"
    Ensure-ProxyEnvFromWinHttp

    # Calcular espaco total estimado
    $totalEstimatedGB = 0.0
    $catalog = Get-BootstrapComponentCatalog
    foreach ($comp in $ResolvedComponents) {
        $def = $catalog[$comp]
        if ($def -and $def.EstimatedSizeGB) { $totalEstimatedGB += $def.EstimatedSizeGB }
    }
    if ($totalEstimatedGB -gt 0) {
        Write-Log ("Preflight: Espaco total estimado para instalacao: {0}GB" -f $totalEstimatedGB)
    }

    Test-BootstrapDiskSpace -Selection $State.Selection -ResolvedComponents $ResolvedComponents -ResolvedWorkspaceRoot $State.WorkspaceRoot

    if ($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage') {
        throw "Bootstrap requer FullLanguage. Modo atual: $($ExecutionContext.SessionState.LanguageMode)"
    }

    $requirements = Get-BootstrapPreflightRequirements -ResolvedComponents $ResolvedComponents
    $pendingRebootReasons = @(Get-BootstrapPendingRebootReasons)
    $pendingRebootDetails = @(Get-BootstrapPendingRebootDetails -Reasons $pendingRebootReasons)
    $pendingRebootMsiBlockers = @(Get-BootstrapMsiHostilePendingRebootReasons -Reasons $pendingRebootReasons)
    $blocksInstallForPendingReboot = (
        $pendingRebootReasons.Count -gt 0 -and
        (-not [bool]$State.DryRun) -and
        (-not [bool]$script:AllowPendingReboot) -and
        [bool]$requirements.RequiresWinget
    )
    $pendingRebootSeverity = if ($blocksInstallForPendingReboot) { 'blocked-for-install' } elseif ($pendingRebootMsiBlockers.Count -gt 0) { 'blocker-for-msi-ghost' } else { 'warning' }
    if ($pendingRebootReasons.Count -gt 0) {
        Write-Log ("Reinicio pendente detectado: {0}. Instalacoes podem falhar (Store/winget/WSL). Recomendo reiniciar antes de prosseguir." -f ($pendingRebootReasons -join ', ')) 'WARN'
        $renameDetails = @($pendingRebootDetails | Where-Object { [string]$_.reason -eq 'PendingFileRenameOperations' })
        if ($renameDetails.Count -gt 0) {
            $categorySummary = @($renameDetails | Group-Object category | ForEach-Object { "{0}={1}" -f $_.Name, $_.Count })
            $hostileCount = @($renameDetails | Where-Object { [bool]$_.msiHostile }).Count
            Write-Log ("PendingFileRenameOperations: {0} operacao(oes), categorias: {1}, msiHostile={2}" -f $renameDetails.Count, ($categorySummary -join ', '), $hostileCount) 'WARN'
        }
        if ($script:RequireNoPendingReboot) {
            throw ("Preflight: reinicio pendente e flag -RequireNoPendingReboot ativa. Motivos: {0}. Reinicie o Windows e execute novamente." -f ($pendingRebootReasons -join ', '))
        }
        if ($blocksInstallForPendingReboot) {
            $message = "Preflight: reinicio pendente antes de instalacao winget/MSI. Motivos: {0}. Reinicie o Windows e execute novamente ou use -AllowPendingReboot conscientemente." -f ($pendingRebootReasons -join ', ')
            Write-Log $message 'WARN'
            throw (New-BootstrapBlockedException -Message $message -Kind 'pending-reboot-before-install' -Action 'restart-required' -Reasons $pendingRebootReasons)
        }
        if ($pendingRebootMsiBlockers.Count -gt 0) {
            Write-Log ("Preflight: reinicio pendente classificado como bloqueio para recuperacao de ghost MSI ({0}); componentes afetados retornarao status=blocked antes de instalar." -f ($pendingRebootMsiBlockers -join ', ')) 'WARN'
        } else {
            Write-Log 'Continuando apesar do reinicio pendente (use -RequireNoPendingReboot para bloquear).' 'WARN'
        }
    } else {
        Write-Log 'Nenhum reinicio pendente detectado.'
    }

    $catalogForManual = Get-BootstrapComponentCatalog
    $manualPlanRows = New-Object System.Collections.Generic.List[object]
    foreach ($compName in @($ResolvedComponents)) {
        $def = $catalogForManual[$compName]
        if (-not $def) { continue }
        if ([string]$def.Kind -ne 'manual-required') { continue }
        $optional = $false
        if ($def.PSObject.Properties.Name -contains 'Optional') { $optional = [bool]$def.Optional }
        $displayName = if ($def.PSObject.Properties.Name -contains 'DisplayName') { [string]$def.DisplayName } else { $compName }
        $instructions = if ($def.PSObject.Properties.Name -contains 'Instructions') { [string]$def.Instructions } else { '' }
        $installed = $false
        try { $installed = [bool](Test-BootstrapManualRequirementInstalled -ComponentDef $def) } catch { $installed = $false }
        $wouldBlock = (-not $optional) -and (-not $script:SkipManualRequirements) -and (-not $script:IgnoreManualRequirements) -and (-not $installed)
        $manualPlanRows.Add([ordered]@{
            component = [string]$compName
            displayName = $displayName
            optional = $optional
            installedProbe = $installed
            wouldBlockWithoutSkipOrIgnore = $wouldBlock
            instructionsPreview = if ($instructions.Length -gt 220) { $instructions.Substring(0, 217) + '...' } else { $instructions }
        }) | Out-Null
    }
    if ($manualPlanRows.Count -gt 0) {
        Write-Log ("Preflight: {0} componente(s) manual-required no plano resolvido (ver result.preflight.manualRequiredInPlan)." -f $manualPlanRows.Count)
        foreach ($row in @($manualPlanRows.ToArray())) {
            $blk = [string]$row['wouldBlockWithoutSkipOrIgnore']
            Write-Log ("Preflight manual-required: {0} ({1}) optional={2} installedProbe={3} bloqueariaSemFlags={4}" -f [string]$row['component'], [string]$row['displayName'], [string]$row['optional'], [string]$row['installedProbe'], $blk)
        }
    }

    $wingetPath = $null
    $appInstaller = $null
    if ($requirements.RequiresWinget) {
        $appInstaller = Get-BootstrapAppInstallerPackage
        if ($appInstaller) {
            Write-Log ("App Installer detectado: {0} ({1})" -f $appInstaller.Name, $appInstaller.Version)
        } else {
            Write-Log 'App Installer nao detectado via Get-AppxPackage.' 'WARN'
        }

        $wingetPath = Get-Winget
        if (-not $wingetPath) {
            if ($appInstaller) {
                Refresh-SessionPath
                $wingetPath = Get-Winget
            } else {
                $wingetPath = Install-BootstrapAppInstaller
                $appInstaller = Get-BootstrapAppInstallerPackage
            }
        }
        if (-not $wingetPath) {
            throw 'Preflight: winget/App Installer indisponivel mesmo apos tentativa automatica. Instale Microsoft.DesktopAppInstaller e execute novamente.'
        }
        Write-Log "Preflight: winget acessivel em $wingetPath"
    }

    $connectivitySummary = New-Object System.Collections.Generic.List[object]
    if ($requirements.RequiresNetwork -and -not $Offline) {
        foreach ($group in @($requirements.ConnectivityGroups)) {
            $groupReachable = $false
            $hostResults = New-Object System.Collections.Generic.List[object]

            foreach ($hostName in @($group.Hosts)) {
                $reachable = Test-BootstrapTcpEndpoint -HostName $hostName
                $hostResults.Add([ordered]@{
                    host = $hostName
                    reachable = $reachable
                })

                if ($reachable) {
                    $groupReachable = $true
                    Write-Log ("Conectividade OK: {0}:443" -f $hostName)
                } else {
                    Write-Log ("Conectividade indisponivel: {0}:443" -f $hostName) 'WARN'
                }
            }

            $connectivitySummary.Add([ordered]@{
                group = $group.Name
                reachable = $groupReachable
                hosts = $(if ($hostResults.Count -gt 0) { $hostResults.ToArray() } else { @() })
            })

            if (-not $groupReachable) {
                throw "Preflight: conectividade minima ausente para '$($group.Name)'. Hosts testados: $(@($group.Hosts) -join ', ')."
            }
        }
    } else {
        Write-Log 'Preflight: execucao atual nao requer downloads externos.'
    }

    if ($wingetPath) {
        $State.Winget = $wingetPath
    }

    $State.PreflightSummary = [ordered]@{
        generatedAt = (Get-Date).ToString('o')
        requiresNetwork = $requirements.RequiresNetwork
        requiresWinget = $requirements.RequiresWinget
        pendingRebootReasons = @($pendingRebootReasons)
        pendingRebootDetails = @($pendingRebootDetails)
        pendingRebootSeverity = $pendingRebootSeverity
        pendingRebootMsiBlockers = @($pendingRebootMsiBlockers)
        requireNoPendingReboot = [bool]$script:RequireNoPendingReboot
        manualRequiredInPlan = $(if ($manualPlanRows.Count -gt 0) { @($manualPlanRows.ToArray()) } else { @() })
        wingetPath = $wingetPath
        appInstallerPresent = ($null -ne $appInstaller)
        connectivity = $(if ($connectivitySummary.Count -gt 0) { $connectivitySummary.ToArray() } else { @() })
    }
    $State.PreflightDone = $true
    Write-Log 'Preflight operacional concluido.'
}

# Exit codes de operacoes winget de pacote que NAO indicam falha real e nao devem disparar retry-loop.
# Documentacao: https://learn.microsoft.com/en-us/windows/package-manager/winget/returnCodes
# - -1978335189 (0x8A15002B) APPINSTALLER_CLI_ERROR_UPDATE_NOT_APPLICABLE: pacote ja instalado, nada a atualizar.
# - -1978335215 (0x8A150011) APPINSTALLER_CLI_ERROR_PACKAGE_ALREADY_INSTALLED.
# Nao incluir -1978335212 aqui: em winget list significa "nao instalado", mas em winget install
# significa pacote indisponivel para o criterio informado.
# Em PowerShell 5.1 esses codigos sao truncados para o int32 nativo; quando o LASTEXITCODE retorna
# como -1 cru, vem de Win32 (API saida sem traduzir o HRESULT). Tratamos ambos.
$script:WingetSoftSuccessExitCodes = @(
    -1978335189,
    -1978335215
)

# Codigos de saida do winget em que "list" sem correspondencia significa pacote nao instalado
# (comportamento normal, nao falha operacional).
$script:WingetListExitCodesNotInstalled = @(
    -1978335212
)

$script:WingetUninstallSoftSuccessExitCodes = @(
    @($script:WingetSoftSuccessExitCodes) + @($script:WingetListExitCodesNotInstalled)
)

$script:WingetNonRetryableInstallExitCodes = @(
    -1978335231,
    -1978335230,
    -1978335207,
    -1978335212,
    -1978335216
)

# Pacotes de RUNTIME do sistema que NUNCA devem entrar em ghost-recovery (uninstall+reinstall),
# mesmo se as ProbePaths falharem. Erro de ProbePath em um destes desinstala um runtime crítico do
# Windows e o run fica preso esperando msiexec liberar lock. Em vez disso, logamos WARN e tratamos
# como já instalado para o resto do componente decidir o que fazer (Audit/Repair existem para isso).
$script:WingetGhostRecoveryBlocklist = @(
    'Microsoft.VCRedist.2015+.x64',
    'Microsoft.VCRedist.2015+.x86',
    'Microsoft.DirectX',
    'ViGEm.ViGEmBus'
)

function Test-WingetSoftSuccessExit {
    param([int]$ExitCode)
    return ($script:WingetSoftSuccessExitCodes -contains $ExitCode)
}

function Invoke-NativeWithRetry {
    param(
        [Parameter(Mandatory = $true)][string]$Exe,
        [Parameter(Mandatory = $true)][string[]]$Args,
        [Parameter(Mandatory = $true)][string]$OperationName,
        [int]$MaxAttempts = 2,
        [int]$InitialDelaySeconds = 3,
        [int]$TimeoutMs = 600000,
        [int[]]$SoftSuccessExitCodes = @(),
        [int[]]$NonRetryableExitCodes = @()
    )

    $attempt = 0
    $delaySeconds = [Math]::Max(1, $InitialDelaySeconds)
    $lastExitCode = -1

    while ($attempt -lt $MaxAttempts) {
        $attempt++
        if ($attempt -gt 1) {
            Write-Log ("Repetindo operacao: {0} (tentativa {1}/{2})" -f $OperationName, $attempt, $MaxAttempts) 'WARN'
        }

        $lastExitCode = Invoke-NativeWithLog -Exe $Exe -Args $Args -TimeoutMs $TimeoutMs
        if ($lastExitCode -eq 0) {
            return 0
        }

        if ($SoftSuccessExitCodes -and ($SoftSuccessExitCodes -contains $lastExitCode)) {
            Write-Log ("{0}: exit={1} reconhecido como sucesso (no-op). Nao vai retentar." -f $OperationName, $lastExitCode)
            return 0
        }

        if ($NonRetryableExitCodes -and ($NonRetryableExitCodes -contains $lastExitCode)) {
            Write-Log ("{0}: exit={1} reconhecido como falha nao retentavel. Nao vai retentar." -f $OperationName, $lastExitCode) 'WARN'
            return $lastExitCode
        }

        if ($attempt -lt $MaxAttempts) {
            Write-Log ("Falha em {0} (exit={1}). Nova tentativa em {2}s." -f $OperationName, $lastExitCode, $delaySeconds) 'WARN'
            Start-Sleep -Seconds $delaySeconds
            $delaySeconds = [Math]::Min(15, $delaySeconds * 2)
        }
    }

    return $lastExitCode
}

function Get-BootstrapCacheDir {
    if (-not [string]::IsNullOrWhiteSpace($script:CacheDir)) { return $script:CacheDir }
    $dataRoot = Normalize-BootstrapPathSegment -Value (Get-BootstrapDataRoot)
    return (Join-Path -Path $dataRoot -ChildPath 'cache')
}

function Invoke-WebRequestWithRetry {
    param(
        [Parameter(Mandatory = $true)][string]$Uri,
        [Parameter(Mandatory = $true)][string]$OutFile,
        [string]$OperationName = 'download',
        [int]$MaxAttempts = 3,
        [int]$InitialDelaySeconds = 3
    )

    # Lógica de Cache
    $cacheDir = Get-BootstrapCacheDir
    $fileName = Split-Path $OutFile -Leaf
    $cachedPath = Join-Path $cacheDir $fileName

    if (Test-Path $cachedPath) {
        Write-Log ("Usando arquivo do cache: {0}" -f $fileName)
        if ($OutFile -ne $cachedPath) {
            $parent = Split-Path $OutFile -Parent
            if ($parent -and -not (Test-Path $parent)) { $null = New-Item -Path $parent -ItemType Directory -Force }
            Copy-Item -Path $cachedPath -Destination $OutFile -Force
        }
        return
    }

    $offlineActive = [bool]$script:Offline
    if (-not $offlineActive -and (Get-Variable -Name 'BootstrapOfflineOverride' -Scope Global -ErrorAction SilentlyContinue)) {
        $offlineActive = [bool]$Global:BootstrapOfflineOverride
    }
    if ($offlineActive) {
        throw ("Modo OFFLINE ativo e arquivo nao encontrado no cache: {0}. Uri: {1}" -f $fileName, $Uri)
    }

    $attempt = 0
    $delaySeconds = [Math]::Max(1, $InitialDelaySeconds)
    while ($attempt -lt $MaxAttempts) {
        $attempt++
        try {
            if ($attempt -gt 1) {
                Write-Log ("Repetindo download: {0} (tentativa {1}/{2})" -f $OperationName, $attempt, $MaxAttempts) 'WARN'
            }
            Invoke-WebRequest -UseBasicParsing -Uri $Uri -OutFile $OutFile | Out-Null

            # Salvar no cache apos sucesso
            if (-not (Test-Path $cacheDir)) { $null = New-Item -Path $cacheDir -ItemType Directory -Force }
            Copy-Item -Path $OutFile -Destination $cachedPath -Force -ErrorAction SilentlyContinue

            return
        } catch {
            if ($attempt -ge $MaxAttempts) {
                throw
            }
            Write-Log ("Falha em {0}: {1}. Nova tentativa em {2}s." -f $OperationName, $_.Exception.Message, $delaySeconds) 'WARN'
            Start-Sleep -Seconds $delaySeconds
            $delaySeconds = [Math]::Min(15, $delaySeconds * 2)
        }
    }
}

function Get-ClaudeHookConfigCandidatePaths {
    $candidates = @()
    $userHome = Get-BootstrapUserHomePath
    $appDataPath = Get-BootstrapAppDataPath
    $localAppDataPath = Get-BootstrapLocalAppDataPath

    if ($appDataPath) {
        $candidates += (Join-Path $appDataPath 'Claude\claude_desktop_config.json')
    }
    if ($localAppDataPath) {
        $candidates += (Join-Path $localAppDataPath 'Claude\claude_desktop_config.json')
    }

    if ($userHome) {
        $candidates += (Join-Path $userHome '.claude\settings.json')
    }
    if ($PSScriptRoot) {
        $candidates += (Join-Path $PSScriptRoot '.claude\settings.json')
    }

    $projectRoots = @()
    if ($userHome) {
        $projectRoots += (Join-Path $userHome 'Documents')
        $projectRoots += (Join-Path $userHome 'Projects')
        $projectRoots += (Join-Path $userHome 'Work')
        $projectRoots += (Join-Path $userHome 'Workspace')
        $projectRoots += (Join-Path $userHome 'Source')
    }
    try {
        $drives = Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue
        foreach ($d in $drives) {
            if ($d -and $d.Root) {
                $projectRoots += (Join-Path $d.Root 'Projects')
                $projectRoots += (Join-Path $d.Root 'Work')
                $projectRoots += (Join-Path $d.Root 'Workspace')
                $projectRoots += (Join-Path $d.Root 'Source')
            }
        }
    } catch {
    }

    foreach ($root in ($projectRoots | Select-Object -Unique)) {
        if (-not $root) { continue }
        if (-not (Test-Path $root)) { continue }

        $level1 = @()
        try {
            $level1 = Get-ChildItem -Path $root -Directory -ErrorAction SilentlyContinue | Select-Object -First 200
        } catch {
            $level1 = @()
        }
        foreach ($d1 in $level1) {
            $p1 = Join-Path $d1.FullName '.claude\settings.json'
            if (Test-Path $p1) { $candidates += $p1 }

            $level2 = @()
            try {
                $level2 = Get-ChildItem -Path $d1.FullName -Directory -ErrorAction SilentlyContinue | Select-Object -First 50
            } catch {
                $level2 = @()
            }
            foreach ($d2 in $level2) {
                $p2 = Join-Path $d2.FullName '.claude\settings.json'
                if (Test-Path $p2) { $candidates += $p2 }
            }
        }
    }

    $existing = @()
    foreach ($p in ($candidates | Where-Object { $_ } | Select-Object -Unique)) {
        if (Test-Path $p) { $existing += (Get-Item $p).FullName }
    }
    return @($existing | Select-Object -Unique)
}

function Backup-FileWithTimestamp {
    param([Parameter(Mandatory = $true)][string]$Path)
    $stamp = (Get-Date).ToString('yyyyMMdd_HHmmss')
    $bak = "$Path.bak_$stamp"
    Copy-Item -Path $Path -Destination $bak -Force
    return $bak
}

