function Get-BootstrapNotepadPlusPlusDesiredState {
    param([string]$Architecture = 'x64')

    $pluginFolders = @((Get-BootstrapNotepadPlusPlusDesiredPlugins -Architecture $Architecture -UseFallbackOnly) | ForEach-Object { [string]$_.folderName })
    $requiredRelativePaths = @()
    foreach ($asset in @(Get-BootstrapNotepadPlusPlusOfficialAssetDefinitions)) {
        $requiredRelativePaths += @([string]$asset.relativeDestination)
    }
    foreach ($asset in @(Get-BootstrapNotepadPlusPlusCustomAssetDefinitions)) {
        $requiredRelativePaths += @([string]$asset.relativeDestination)
    }
    $requiredRelativePaths += @('plugins\Config\NppOpenAI.ini')

    return [ordered]@{
        curatedVersion = Get-BootstrapNotepadPlusPlusCuratedVersion
        architecture = [string]$Architecture
        pluginFolders = @($pluginFolders | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique)
        requiredRelativePaths = @($requiredRelativePaths | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique)
        deferred = @(Get-BootstrapNotepadPlusPlusDeferredCapabilities -Architecture $Architecture)
    }
}

function Test-BootstrapNotepadPlusPlusBinary {
    # Valida que `notepad++.exe` no caminho dado e um binario real e nao um stub de uninstall
    # parcial (arquivo zerado, marcado-para-delete, ou MUI ResX restante). Sem isso, Test-Path
    # cru aceita qualquer fantasma e bloqueia a curadoria de plugins/UDL.
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $false }
    try {
        $item = Get-Item -LiteralPath $Path -ErrorAction Stop
    } catch {
        return $false
    }
    if ([int64]$item.Length -lt 102400) { return $false }  # 100 KB: Notepad++ real tem ~4 MB; stubs ficam <10 KB
    try {
        $info = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($item.FullName)
        if ([string]::IsNullOrWhiteSpace($info.FileVersion)) { return $false }
    } catch {
        return $false
    }
    return $true
}

function Get-BootstrapNotepadPlusPlusProbePaths {
    $programFiles = [Environment]::GetEnvironmentVariable('ProgramFiles')
    $programFilesX86 = [Environment]::GetEnvironmentVariable('ProgramFiles(x86)')
    $programW6432 = [Environment]::GetEnvironmentVariable('ProgramW6432')
    $localAppData = [Environment]::GetEnvironmentVariable('LOCALAPPDATA')
    $publicProfile = [Environment]::GetEnvironmentVariable('PUBLIC')

    $paths = @(
        $(if ($programFiles) { Join-Path $programFiles 'Notepad++\notepad++.exe' } else { $null })
        $(if ($programW6432 -and ($programFiles -ne $programW6432)) { Join-Path $programW6432 'Notepad++\notepad++.exe' } else { $null })
        $(if ($programFilesX86 -and ($programFiles -ne $programFilesX86)) { Join-Path $programFilesX86 'Notepad++\notepad++.exe' } else { $null })
        $(if ($localAppData) { Join-Path $localAppData 'Programs\Notepad++\notepad++.exe' } else { $null })
        $(if ($localAppData) { Join-Path $localAppData 'Microsoft\WinGet\Packages\Notepad++.Notepad++_*\notepad++.exe' } else { $null })
        $(if ($programFiles) { Join-Path $programFiles 'WinGet\Packages\Notepad++.Notepad++_*\notepad++.exe' } else { $null })
        $(if ($programW6432 -and ($programFiles -ne $programW6432)) { Join-Path $programW6432 'WinGet\Packages\Notepad++.Notepad++_*\notepad++.exe' } else { $null })
        $(if ($publicProfile) { Join-Path $publicProfile 'Notepad++\notepad++.exe' } else { $null })
    )

    return @($paths | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | Select-Object -Unique)
}

function Get-BootstrapNotepadPlusPlusUninstallRegistry {
    # Varre HKCU/HKLM/WOW6432Node\...\Uninstall procurando entradas Notepad++.
    # Retorna 0..N hashtables com Hive marcado (HKCU/HKLM/HKLM-WOW64) para diagnostico
    # de ghost por arquitetura. Padronizado com Get-BootstrapInstalledAppInventory.
    $roots = @(
        @{ Path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*'; Hive = 'HKCU' }
        @{ Path = 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*'; Hive = 'HKLM' }
        @{ Path = 'HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'; Hive = 'HKLM-WOW64' }
    )
    $results = New-Object System.Collections.Generic.List[object]
    foreach ($root in $roots) {
        $entries = @()
        try {
            $entries = @(Get-ItemProperty -Path $root.Path -ErrorAction SilentlyContinue)
        } catch {
            $entries = @()
        }
        foreach ($entry in $entries) {
            $displayName = ''
            if ($entry.PSObject.Properties.Name -contains 'DisplayName') {
                $displayName = [string]$entry.DisplayName
            }
            if ([string]::IsNullOrWhiteSpace($displayName)) { continue }
            # $matches e variavel automatica do PowerShell (captura de regex). Nao reusar.
            if ($displayName -notmatch '^Notepad\+\+(\s*\(.*\))?$') { continue }
            $hive = [string]$root.Hive
            $keyPath = ''
            if ($entry.PSObject.Properties.Name -contains 'PSPath') { $keyPath = [string]$entry.PSPath }
            $installLocation = ''
            if ($entry.PSObject.Properties.Name -contains 'InstallLocation') { $installLocation = [string]$entry.InstallLocation }
            $uninstallString = ''
            if ($entry.PSObject.Properties.Name -contains 'UninstallString') { $uninstallString = [string]$entry.UninstallString }
            $quietUninstallString = ''
            if ($entry.PSObject.Properties.Name -contains 'QuietUninstallString') { $quietUninstallString = [string]$entry.QuietUninstallString }
            $displayVersion = ''
            if ($entry.PSObject.Properties.Name -contains 'DisplayVersion') { $displayVersion = [string]$entry.DisplayVersion }
            $results.Add([ordered]@{
                Hive = $hive
                KeyPath = $keyPath
                DisplayName = $displayName
                DisplayVersion = $displayVersion
                InstallLocation = $installLocation
                UninstallString = $uninstallString
                QuietUninstallString = $quietUninstallString
            })
        }
    }
    return @($results.ToArray())
}

function Get-BootstrapNotepadPlusPlusInstallInfo {
    # Decisor autoritativo de presenca do Notepad++. Tres fases:
    #   1) Disco: itera candidatos de install path e valida o .exe (tamanho + FileVersion).
    #   2) Registry: consulta Uninstall em HKCU/HKLM/WOW6432Node; usa InstallLocation
    #      como pista adicional para o probe de disco.
    #   3) Divergencia: registry diz presente mas nada de binario valido em disco -> GhostState.
    # Mantem compatibilidade com consumidores existentes (campos antigos preservados).
    $programFilesX86 = [Environment]::GetEnvironmentVariable('ProgramFiles(x86)')
    $programW6432 = [Environment]::GetEnvironmentVariable('ProgramW6432')
    $publicProfile = [Environment]::GetEnvironmentVariable('PUBLIC')
    $candidates = @(
        (Join-BootstrapKnownFolderPath -Base $env:ProgramFiles -ChildPath 'Notepad++')
        $(if ($programW6432 -and ($env:ProgramFiles -ne $programW6432)) { Join-Path $programW6432 'Notepad++' } else { $null })
        $(if ($programFilesX86 -and ($env:ProgramFiles -ne $programFilesX86)) { Join-Path $programFilesX86 'Notepad++' } else { $null })
        (Join-BootstrapKnownFolderPath -Base $env:LOCALAPPDATA -ChildPath 'Programs\Notepad++')
        $(if ($publicProfile) { Join-Path $publicProfile 'Notepad++' } else { $null })
    ) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | Select-Object -Unique

    $installRoot = $null
    foreach ($path in @($candidates)) {
        $exePath = Join-Path $path 'notepad++.exe'
        if (Test-BootstrapNotepadPlusPlusBinary -Path $exePath) {
            $installRoot = $path
            break
        }
    }

    $registryEntries = @()
    try { $registryEntries = @(Get-BootstrapNotepadPlusPlusUninstallRegistry) } catch { $registryEntries = @() }

    if (-not $installRoot -and $registryEntries.Count -gt 0) {
        foreach ($entry in $registryEntries) {
            $hintLocation = [string]$entry.InstallLocation
            if ([string]::IsNullOrWhiteSpace($hintLocation)) { continue }
            $hintExe = Join-Path $hintLocation 'notepad++.exe'
            if (Test-BootstrapNotepadPlusPlusBinary -Path $hintExe) {
                $installRoot = $hintLocation
                break
            }
        }
    }

    if (-not $installRoot) {
        $ghostState = $false
        $ghostHive = ''
        $ghostUninstallString = ''
        $ghostQuietUninstallString = ''
        $registryDisplayVersion = ''
        if ($registryEntries.Count -gt 0) {
            $ghostState = $true
            $primary = $registryEntries[0]
            $ghostHive = [string]$primary.Hive
            $ghostUninstallString = [string]$primary.UninstallString
            $ghostQuietUninstallString = [string]$primary.QuietUninstallString
            $registryDisplayVersion = [string]$primary.DisplayVersion
            Write-Log ("Notepad++ ghost install detectado: registro em {0} declara presente, mas nenhum binario valido em disco." -f $ghostHive) 'WARN'
        } else {
            $wingetExe = $null
            try { $wingetExe = Get-Winget } catch { $wingetExe = $null }
            if ($wingetExe) {
                $wingetInstalled = $false
                try { $wingetInstalled = Test-WingetPackageInstalled -WingetPath $wingetExe -Id 'Notepad++.Notepad++' } catch { $wingetInstalled = $false }
                if ($wingetInstalled) {
                    $ghostState = $true
                    $ghostHive = 'winget'
                    Write-Log 'Notepad++ ghost install — winget registry diz presente, mas nenhum binario encontrado em disco.' 'WARN'
                }
            }
        }
        return [ordered]@{
            Installed = $false
            Architecture = 'x64'
            InstallRoot = ''
            PluginsRoot = ''
            ConfigRoot = ''
            PluginConfigRoot = ''
            GhostState = $ghostState
            GhostHive = $ghostHive
            GhostUninstallString = $ghostUninstallString
            GhostQuietUninstallString = $ghostQuietUninstallString
            RegistryDisplayVersion = $registryDisplayVersion
        }
    }

    $architecture = 'x64'
    if ($installRoot -like '*Program Files (x86)*') {
        $architecture = 'x86'
    } elseif ($registryEntries.Count -gt 0 -and [string]$registryEntries[0].Hive -eq 'HKLM-WOW64') {
        $architecture = 'x86'
    }

    $configRoot = if (Test-Path (Join-Path $installRoot 'doLocalConf.xml')) { $installRoot } else { Join-Path $env:APPDATA 'Notepad++' }
    $registryDisplayVersion = ''
    if ($registryEntries.Count -gt 0) { $registryDisplayVersion = [string]$registryEntries[0].DisplayVersion }
    return [ordered]@{
        Installed = $true
        Architecture = $architecture
        InstallRoot = $installRoot
        PluginsRoot = (Join-Path $installRoot 'plugins')
        ConfigRoot = $configRoot
        PluginConfigRoot = (Join-Path $configRoot 'plugins\Config')
        GhostState = $false
        GhostHive = ''
        GhostUninstallString = ''
        GhostQuietUninstallString = ''
        RegistryDisplayVersion = $registryDisplayVersion
    }
}

function Get-BootstrapDockerInstallInfo {
    # Detector autoritativo para Docker Desktop. Cobre:
    #   - Paths user-scope (LOCALAPPDATA\Docker\Docker.exe) e per-machine (ProgramFiles\Docker\Docker\Docker Desktop.exe).
    #   - Validacao de binario (FileVersion).
    #   - Estado do servico com.docker.service e presenca de distro WSL docker-desktop.
    #   - Divergencia winget <-> disco => GhostState.
    # Retorna hashtable estavel mesmo em falha (campos sempre presentes).
    $candidates = @(
        (Join-Path $env:ProgramFiles 'Docker\Docker\Docker Desktop.exe')
        (Join-Path $env:ProgramFiles 'Docker\Docker.exe')
        (Join-Path $env:LOCALAPPDATA 'Docker\Docker Desktop.exe')
        (Join-Path $env:LOCALAPPDATA 'Docker\Docker.exe')
    ) | Where-Object { $_ } | Select-Object -Unique

    $installRoot = ''
    $exePath = ''
    foreach ($c in $candidates) {
        if (-not (Test-Path -LiteralPath $c -PathType Leaf)) { continue }
        try {
            $item = Get-Item -LiteralPath $c -ErrorAction Stop
        } catch {
            continue
        }
        if ([int64]$item.Length -lt 102400) { continue }  # stub guard
        $exePath = $item.FullName
        $installRoot = Split-Path -Parent $exePath
        break
    }

    $fileVersion = ''
    if (-not [string]::IsNullOrWhiteSpace($exePath)) {
        try { $fileVersion = [string][System.Diagnostics.FileVersionInfo]::GetVersionInfo($exePath).FileVersion } catch { $fileVersion = '' }
    }

    # Servico Docker (com.docker.service) - opcional, ausente em instalacoes que so usam WSL2.
    $serviceState = 'absent'
    try {
        $svc = Get-Service -Name 'com.docker.service' -ErrorAction SilentlyContinue
        if ($svc) { $serviceState = [string]$svc.Status }
    } catch {
        $serviceState = 'absent'
    }

    # Distro WSL docker-desktop - melhor sinal de integracao WSL2 saudavel.
    # `wsl --list` pode travar quando WSL nao esta configurado; rodamos com timeout curto.
    $wslDistroPresent = $false
    try {
        $wslExe = Join-Path $env:WINDIR 'System32\wsl.exe'
        if ((Test-Path -LiteralPath $wslExe) -and -not [string]::IsNullOrWhiteSpace($exePath)) {
            $stdoutPath = Join-Path $env:TEMP ('phasezero-wsl-list-' + [Guid]::NewGuid().ToString('N') + '.txt')
            try {
                $proc = Start-Process -FilePath $wslExe -ArgumentList @('--list','--quiet') -RedirectStandardOutput $stdoutPath -RedirectStandardError ([System.IO.Path]::GetTempFileName()) -WindowStyle Hidden -PassThru -ErrorAction SilentlyContinue
                if ($proc) {
                    if ($proc.WaitForExit(5000)) {
                        if (Test-Path -LiteralPath $stdoutPath) {
                            $listOut = [System.IO.File]::ReadAllText($stdoutPath)
                            if ($listOut -and $listOut -match 'docker-desktop') { $wslDistroPresent = $true }
                        }
                    } else {
                        try { Stop-Process -Id $proc.Id -Force -ErrorAction SilentlyContinue } catch { }
                    }
                }
            } finally {
                if (Test-Path -LiteralPath $stdoutPath) { Remove-Item -LiteralPath $stdoutPath -Force -ErrorAction SilentlyContinue }
            }
        }
    } catch {
        $wslDistroPresent = $false
    }

    if ([string]::IsNullOrWhiteSpace($exePath)) {
        $ghostState = $false
        $ghostReason = ''
        $wingetExe = $null
        try { $wingetExe = Get-Winget } catch { $wingetExe = $null }
        if ($wingetExe) {
            $wingetInstalled = $false
            try { $wingetInstalled = Test-WingetPackageInstalled -WingetPath $wingetExe -Id 'Docker.DockerDesktop' } catch { $wingetInstalled = $false }
            if ($wingetInstalled) {
                $ghostState = $true
                $ghostReason = 'winget reporta Docker.DockerDesktop instalado, mas nenhum binario valido encontrado em ProgramFiles\Docker ou LOCALAPPDATA\Docker'
                Write-Log ('Docker Desktop ghost install detectado: ' + $ghostReason) 'WARN'
            }
        }
        return [ordered]@{
            Installed = $false
            InstallRoot = ''
            ExePath = ''
            FileVersion = ''
            ServiceState = $serviceState
            WslDistroPresent = $wslDistroPresent
            HealthIssues = $false
            GhostState = $ghostState
            GhostReason = $ghostReason
        }
    }

    # Issues de saude: servico parado quando deveria rodar, ou WSL distro ausente (instalacao parcial).
    $healthIssues = $false
    if ($serviceState -eq 'Stopped') { $healthIssues = $true }
    if (-not $wslDistroPresent -and $serviceState -eq 'absent') { $healthIssues = $true }

    return [ordered]@{
        Installed = $true
        InstallRoot = $installRoot
        ExePath = $exePath
        FileVersion = $fileVersion
        ServiceState = $serviceState
        WslDistroPresent = $wslDistroPresent
        HealthIssues = $healthIssues
        GhostState = $false
        GhostReason = ''
    }
}

function Get-BootstrapNotepadPlusPlusMarkerPath {
    param([Parameter(Mandatory = $true)]$InstallInfo)
    return (Join-Path ([string]$InstallInfo.PluginConfigRoot) 'bootstrap-notepadpp.json')
}

function Test-BootstrapNotepadPlusPlusConfigured {
    param(
        [Parameter(Mandatory = $true)]$InstallInfo,
        [AllowNull()]$DesiredState = $null
    )

    if (-not [bool]$InstallInfo.Installed) { return $false }
    $desired = if ($DesiredState) { $DesiredState } else { Get-BootstrapNotepadPlusPlusDesiredState -Architecture ([string]$InstallInfo.Architecture) }
    $markerPath = Get-BootstrapNotepadPlusPlusMarkerPath -InstallInfo $InstallInfo
    $marker = Read-BootstrapJsonFile -Path $markerPath
    if (-not $marker) { return $false }
    if ([string]$marker.curatedVersion -ne [string]$desired.curatedVersion) { return $false }
    if ([string]$marker.architecture -ne [string]$desired.architecture) { return $false }
    if ([string]$marker.status -ne 'applied') { return $false }

    foreach ($folder in @($desired.pluginFolders)) {
        $pluginDir = Join-Path ([string]$InstallInfo.PluginsRoot) ([string]$folder)
        if (-not (Test-Path $pluginDir)) { return $false }
    }

    foreach ($relativePath in @($desired.requiredRelativePaths)) {
        $targetPath = Join-Path ([string]$InstallInfo.ConfigRoot) ([string]$relativePath)
        if (-not (Test-Path $targetPath)) { return $false }
    }

    return $true
}

function Copy-BootstrapDirectoryItems {
    param(
        [Parameter(Mandatory = $true)][string]$SourceDir,
        [Parameter(Mandatory = $true)][string]$DestinationDir
    )

    $null = New-Item -Path $DestinationDir -ItemType Directory -Force
    foreach ($entry in @(Get-ChildItem -LiteralPath $SourceDir -Force -ErrorAction SilentlyContinue)) {
        Copy-Item -LiteralPath $entry.FullName -Destination (Join-Path $DestinationDir $entry.Name) -Force -Recurse
    }
}

function Get-BootstrapNotepadPlusPlusPluginSourceDirectory {
    param(
        [Parameter(Mandatory = $true)][string]$ExtractRoot,
        [Parameter(Mandatory = $true)]$Plugin
    )

    $preferred = Join-Path $ExtractRoot ([string]$Plugin.folderName)
    if (Test-Path $preferred) { return $preferred }

    $dll = Get-ChildItem -Path $ExtractRoot -Filter '*.dll' -File -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($dll) { return $dll.Directory.FullName }

    $topLevel = @(Get-ChildItem -Path $ExtractRoot -Directory -ErrorAction SilentlyContinue)
    if ($topLevel.Count -eq 1) { return $topLevel[0].FullName }

    return $ExtractRoot
}

function Get-BootstrapFileSha256 {
    param([Parameter(Mandatory = $true)][string]$Path)

    $resolvedPath = [System.IO.Path]::GetFullPath($Path)
    $stream = [System.IO.File]::OpenRead($resolvedPath)
    $sha256 = [System.Security.Cryptography.SHA256]::Create()
    try {
        $bytes = $sha256.ComputeHash($stream)
        return (($bytes | ForEach-Object { $_.ToString('x2') }) -join '')
    } finally {
        $sha256.Dispose()
        $stream.Dispose()
    }
}

function Install-BootstrapNotepadPlusPlusPlugin {
    param(
        [Parameter(Mandatory = $true)]$InstallInfo,
        [Parameter(Mandatory = $true)]$Plugin
    )

    $pluginRoot = [string]$InstallInfo.PluginsRoot
    if (-not (Test-BootstrapDirectoryWritable -Path $pluginRoot)) {
        return [ordered]@{ name = [string]$Plugin.displayName; status = 'failed'; error = "Sem permissao de escrita em $pluginRoot" }
    }

    $tempRoot = Join-Path $env:TEMP ('bootstrap-npp-plugin-' + [guid]::NewGuid().ToString('N'))
    $pluginArchiveName = 'notepadpp-plugin-{0}.zip' -f (([string]$Plugin.folderName) -replace '[^A-Za-z0-9._-]', '_')
    $zipPath = Join-Path $tempRoot $pluginArchiveName
    $extractRoot = Join-Path $tempRoot 'extract'
    $targetDir = Join-Path $pluginRoot ([string]$Plugin.folderName)

    try {
        $null = New-Item -Path $extractRoot -ItemType Directory -Force
        Invoke-WebRequestWithRetry -Uri ([string]$Plugin.repository) -OutFile $zipPath -OperationName ("Notepad++ plugin {0}" -f [string]$Plugin.displayName)
        if (-not [string]::IsNullOrWhiteSpace([string]$Plugin.id)) {
            $hash = Get-BootstrapFileSha256 -Path $zipPath
            $expected = ([string]$Plugin.id).ToLowerInvariant()
            if ($hash -ne $expected) {
                throw "Checksum invalido para $([string]$Plugin.displayName): $hash"
            }
        }
        Expand-Archive -LiteralPath $zipPath -DestinationPath $extractRoot -Force
        $sourceDir = Get-BootstrapNotepadPlusPlusPluginSourceDirectory -ExtractRoot $extractRoot -Plugin $Plugin
        Copy-BootstrapDirectoryItems -SourceDir $sourceDir -DestinationDir $targetDir
        return [ordered]@{ name = [string]$Plugin.displayName; status = 'installed'; folder = [string]$Plugin.folderName; version = [string]$Plugin.version; source = [string]$Plugin.source }
    } catch {
        return [ordered]@{ name = [string]$Plugin.displayName; status = 'failed'; folder = [string]$Plugin.folderName; error = $_.Exception.Message }
    } finally {
        if (Test-Path $tempRoot) {
            Remove-Item -Path $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
        }
    }
}

function Install-BootstrapNotepadPlusPlusRemoteAsset {
    param(
        [Parameter(Mandatory = $true)]$InstallInfo,
        [Parameter(Mandatory = $true)]$Asset
    )

    $targetPath = Join-Path ([string]$InstallInfo.ConfigRoot) ([string]$Asset.relativeDestination)
    $parent = Split-Path -Parent $targetPath
    try {
        if (-not [string]::IsNullOrWhiteSpace($parent)) {
            $null = New-Item -Path $parent -ItemType Directory -Force
        }
        Invoke-WebRequestWithRetry -Uri ([string]$Asset.sourceUri) -OutFile $targetPath -OperationName ("Notepad++ asset {0}" -f [string]$Asset.name)
        return [ordered]@{ name = [string]$Asset.name; status = 'installed'; path = $targetPath }
    } catch {
        return [ordered]@{ name = [string]$Asset.name; status = 'failed'; path = $targetPath; error = $_.Exception.Message }
    }
}

function Install-BootstrapNotepadPlusPlusLocalAsset {
    param(
        [Parameter(Mandatory = $true)]$InstallInfo,
        [Parameter(Mandatory = $true)]$Asset
    )

    $targetPath = Join-Path ([string]$InstallInfo.ConfigRoot) ([string]$Asset.relativeDestination)
    $parent = Split-Path -Parent $targetPath
    try {
        if (-not (Test-Path ([string]$Asset.sourcePath))) {
            throw "Asset ausente: $([string]$Asset.sourcePath)"
        }
        if (-not [string]::IsNullOrWhiteSpace($parent)) {
            $null = New-Item -Path $parent -ItemType Directory -Force
        }
        Copy-Item -Path ([string]$Asset.sourcePath) -Destination $targetPath -Force
        return [ordered]@{ name = [string]$Asset.name; status = 'installed'; path = $targetPath }
    } catch {
        return [ordered]@{ name = [string]$Asset.name; status = 'failed'; path = $targetPath; error = $_.Exception.Message }
    }
}

function Ensure-BootstrapNotepadPlusPlusOpenAiConfig {
    param([Parameter(Mandatory = $true)]$InstallInfo)

    $targetPath = Join-Path ([string]$InstallInfo.ConfigRoot) 'plugins\Config\NppOpenAI.ini'
    $parent = Split-Path -Parent $targetPath
    try {
        if (-not [string]::IsNullOrWhiteSpace($parent)) {
            $null = New-Item -Path $parent -ItemType Directory -Force
        }

        if (-not (Test-Path $targetPath)) {
            @(
                '; Managed by bootstrap-tools.'
                '; Fill secret_key manually or point plugin to your provider endpoint.'
                '[API]'
                'secret_key='
                'api_url=https://api.openai.com/v1/'
                'route_chat_completions=chat/completions'
                'response_type=openai'
                'model=gpt-4o-mini'
                'temperature=0.2'
                'show_reasoning=0'
                'streaming=0'
                ''
                '[PLUGIN]'
                'keep_question=0'
            ) | Set-Content -Path $targetPath -Encoding utf8
        }

        return [ordered]@{ name = 'NppOpenAI config'; status = 'installed'; path = $targetPath }
    } catch {
        return [ordered]@{ name = 'NppOpenAI config'; status = 'failed'; path = $targetPath; error = $_.Exception.Message }
    }
}

function Ensure-BootstrapNotepadPlusPlusDefaults {
    $installInfo = Get-BootstrapNotepadPlusPlusInstallInfo
    if (-not [bool]$installInfo.Installed) {
        Write-Log 'Notepad++ defaults: app ausente. Pulando curadoria.' 'WARN'
        return [ordered]@{ status = 'skipped'; reason = 'not-installed' }
    }

    Write-Log ("Notepad++ defaults: curadoria em {0}" -f [string]$installInfo.InstallRoot)
    $null = New-Item -Path ([string]$installInfo.PluginsRoot) -ItemType Directory -Force
    $null = New-Item -Path ([string]$installInfo.PluginConfigRoot) -ItemType Directory -Force

    $desiredPlugins = @(Get-BootstrapNotepadPlusPlusDesiredPlugins -Architecture ([string]$installInfo.Architecture))
    $officialAssets = @(Get-BootstrapNotepadPlusPlusOfficialAssetDefinitions)
    $customAssets = @(Get-BootstrapNotepadPlusPlusCustomAssetDefinitions)
    $desiredState = Get-BootstrapNotepadPlusPlusDesiredState -Architecture ([string]$installInfo.Architecture)

    $pluginResults = @()
    foreach ($plugin in @($desiredPlugins)) {
        $result = Install-BootstrapNotepadPlusPlusPlugin -InstallInfo $installInfo -Plugin $plugin
        $pluginResults += @($result)
        Write-Log ("Notepad++ plugin {0}: {1}" -f [string]$plugin.displayName, [string]$result.status)
    }

    $assetResults = @()
    foreach ($asset in @($officialAssets)) {
        $result = Install-BootstrapNotepadPlusPlusRemoteAsset -InstallInfo $installInfo -Asset $asset
        $assetResults += @($result)
        Write-Log ("Notepad++ asset {0}: {1}" -f [string]$asset.name, [string]$result.status)
    }
    foreach ($asset in @($customAssets)) {
        $result = Install-BootstrapNotepadPlusPlusLocalAsset -InstallInfo $installInfo -Asset $asset
        $assetResults += @($result)
        Write-Log ("Notepad++ asset {0}: {1}" -f [string]$asset.name, [string]$result.status)
    }

    $openAiConfig = Ensure-BootstrapNotepadPlusPlusOpenAiConfig -InstallInfo $installInfo
    Write-Log ("Notepad++ asset {0}: {1}" -f [string]$openAiConfig.name, [string]$openAiConfig.status)

    $failed = @($pluginResults + $assetResults + @($openAiConfig) | Where-Object { [string]$_.status -eq 'failed' })
    $manifest = [ordered]@{
        curatedVersion = [string]$desiredState.curatedVersion
        architecture = [string]$installInfo.Architecture
        status = $(if ($failed.Count -gt 0) { 'partial' } else { 'applied' })
        appliedAt = (Get-Date).ToString('o')
        installRoot = [string]$installInfo.InstallRoot
        configRoot = [string]$installInfo.ConfigRoot
        plugins = @($desiredPlugins | ForEach-Object {
            [ordered]@{
                displayName = [string]$_.displayName
                folderName = [string]$_.folderName
                version = [string]$_.version
                homepage = [string]$_.homepage
                source = [string]$_.source
            }
        })
        requiredRelativePaths = @($desiredState.requiredRelativePaths)
        deferred = @($desiredState.deferred)
        results = [ordered]@{
            plugins = @($pluginResults)
            assets = @($assetResults + @($openAiConfig))
        }
    }

    $markerPath = Get-BootstrapNotepadPlusPlusMarkerPath -InstallInfo $installInfo
    Write-BootstrapJsonFile -Path $markerPath -Value $manifest
    return $manifest
}

function Quote-WindowsPathTokensInString {
    param([Parameter(Mandatory = $true)][string]$Text)
    $pattern = '(?<!["''])([A-Za-z]:\\[^"'']*?\.(?:exe|cmd|bat|ps1))(?!["''])'
    try {
        return [regex]::Replace($Text, $pattern, { param($m) '"' + $m.Groups[1].Value + '"' })
    } catch {
        return $Text
    }
}

function ConvertTo-GitBashPathToken {
    param([Parameter(Mandatory = $true)][string]$Path)

    $value = [string]$Path
    if ($value -notmatch '^([A-Za-z]):\\(.+)$') { return $value }

    $drive = $matches[1].ToLowerInvariant()
    $tail = $matches[2] -replace '\\', '/'
    return ("/{0}/{1}" -f $drive, $tail)
}

function Quote-GitBashArgument {
    param([Parameter(Mandatory = $true)][string]$Value)

    $escaped = ([string]$Value).Replace('\', '\\').Replace('"', '\"').Replace('$', '\$').Replace('`', '\`')
    return ('"{0}"' -f $escaped)
}

function Convert-WindowsPathTokensToGitBashCommand {
    param([Parameter(Mandatory = $true)][string]$Text)

    $pathPattern = '([A-Za-z]:\\[^"'']*?\.(?:exe|cmd|bat|ps1|js))'
    try {
        $converted = [regex]::Replace($Text, '(["''])' + $pathPattern + '\1', {
            param($m)
            Quote-GitBashArgument -Value (ConvertTo-GitBashPathToken -Path $m.Groups[2].Value)
        })
        $converted = [regex]::Replace($converted, '(?<!["''])' + $pathPattern + '(?!["''])', {
            param($m)
            Quote-GitBashArgument -Value (ConvertTo-GitBashPathToken -Path $m.Groups[1].Value)
        })
        return $converted
    } catch {
        return $Text
    }
}

function Convert-HookItemIfNeeded {
    param(
        [Parameter(Mandatory = $true)]$Item,
        [string]$GitBashPath
    )

    if ($Item -is [string]) {
        $s = [string]$Item
        if ($s -match '[A-Za-z]:\\') {
            return (Convert-WindowsPathTokensToGitBashCommand -Text $s)
        }
        if ($s -match '(?i)(^|\\s)/usr/bin/bash(\\s|$)' -or $s -match '(?i)(^|\\s)/bin/bash(\\s|$)' -or $s -match '(?i)\\bbash\\b') {
            return $null
        }
        if ($s -match '(?i)C:\\\\Program Files\\\\' -and ($s -notmatch '(?i)\"C:\\\\Program Files\\\\')) {
            return $null
        }
        return $Item
    }

    $cmd = $null
    $args = $null
    try { $cmd = $Item.command } catch { $cmd = $null }
    try { $args = $Item.args } catch { $args = $null }

    if ($cmd -and ($cmd -match '(?i)^/usr/bin/bash(\\s|$)' -or $cmd -match '(?i)^/bin/bash(\\s|$)')) {
        if (-not $GitBashPath -or -not (Test-Path $GitBashPath)) { return $null }

        $scriptText = $null
        $m = [regex]::Match($cmd, '(?i)^(?:/usr/bin/bash|/bin/bash)\\s+-(?:l?c)\\s+(.+)$')
        if ($m.Success) {
            $scriptText = $m.Groups[1].Value.Trim()
        } elseif ($args -and ($args -is [System.Collections.IEnumerable])) {
            $arr = @($args)
            if ($arr.Count -ge 2 -and ($arr[0] -match '^-l?c$')) {
                $scriptText = [string]$arr[1]
            }
        }

        if (-not $scriptText) { return $null }
        $scriptText = Quote-WindowsPathTokensInString -Text $scriptText

        $Item.command = $GitBashPath
        $Item.args = @('-lc', $scriptText)
        return $Item
    }

    if ($args -and ($args -is [System.Collections.IEnumerable])) {
        $arr = @()
        foreach ($a in @($args)) {
            if ($a -is [string]) { $arr += (Quote-WindowsPathTokensInString -Text ([string]$a)) } else { $arr += $a }
        }
        try { $Item.args = $arr } catch { }
    }

    $cmdStr = $null
    if ($cmd -is [string]) { $cmdStr = [string]$cmd }
    if ($cmdStr -and ($cmdStr -match '[A-Za-z]:\\')) {
        try { $Item.command = (Convert-WindowsPathTokensToGitBashCommand -Text $cmdStr) } catch { }
    }
    if ($cmdStr -and ($cmdStr -match '(?i)\\bbash\\b') -and ($cmdStr -match '(?i)C:\\\\Program Files\\\\') -and ($cmdStr -notmatch '(?i)\"C:\\\\Program Files\\\\')) {
        return $null
    }
    return $Item
}

function Get-BootstrapBonsaiCliDistPath {
    param([string]$BonsaiCommandPath)

    $candidates = @()
    if ($BonsaiCommandPath) { $candidates += $BonsaiCommandPath }

    try {
        $cmd = Get-Command bonsai -ErrorAction SilentlyContinue
        if ($cmd) { $candidates += $cmd.Source }
    } catch { }

    if ($env:APPDATA) {
        $candidates += (Join-Path $env:APPDATA 'npm\bonsai.ps1')
        $candidates += (Join-Path $env:APPDATA 'npm\bonsai.cmd')
    }

    foreach ($cmdPath in @($candidates | Where-Object { $_ } | Select-Object -Unique)) {
        if (-not (Test-Path -LiteralPath $cmdPath)) { continue }
        $dir = Split-Path -Parent $cmdPath
        if (-not $dir) { continue }
        $candidate = Join-Path $dir 'node_modules\@bonsai-ai\cli\dist\cli.js'
        if (Test-Path -LiteralPath $candidate) {
            try { return (Resolve-Path -LiteralPath $candidate).Path } catch { return $candidate }
        }
    }

    return $null
}

function Repair-BootstrapBonsaiCliSnapshotHooks {
    param(
        [string]$CliPath,
        [string]$BonsaiCommandPath
    )

    if (-not $CliPath) {
        $CliPath = Get-BootstrapBonsaiCliDistPath -BonsaiCommandPath $BonsaiCommandPath
    }
    if (-not $CliPath -or -not (Test-Path -LiteralPath $CliPath)) {
        return [pscustomobject]@{ Status = 'missing'; Path = $CliPath; BackupPath = $null; Changed = $false }
    }

    $raw = Get-Content -LiteralPath $CliPath -Raw -Encoding utf8
    $original = 'let D=`${process.argv[0]} ${process.argv[1]} internal snapshot`;return JSON.stringify'
    $patchedMarker = 'JSON.stringify(C)}).join(" ");return JSON.stringify'
    if ($raw.Contains($patchedMarker)) {
        return [pscustomobject]@{ Status = 'already-patched'; Path = $CliPath; BackupPath = $null; Changed = $false }
    }
    if (-not $raw.Contains($original)) {
        return [pscustomobject]@{ Status = 'unsupported'; Path = $CliPath; BackupPath = $null; Changed = $false }
    }

    $replacement = 'let D=[process.argv[0],process.argv[1],"internal","snapshot"].map(z=>{let C=String(z);if(process.platform==="win32"&&/^[A-Za-z]:\\/.test(C))C="/"+C[0].toLowerCase()+C.slice(2).replace(/\\/g,"/");return JSON.stringify(C)}).join(" ");return JSON.stringify'
    $updated = $raw.Replace($original, $replacement)
    if ($updated -eq $raw) {
        return [pscustomobject]@{ Status = 'unchanged'; Path = $CliPath; BackupPath = $null; Changed = $false }
    }

    $backupPath = ('{0}.{1}.bak' -f $CliPath, (Get-Date -Format 'yyyyMMdd_HHmmss'))
    Copy-Item -LiteralPath $CliPath -Destination $backupPath -Force
    Write-BootstrapAtomicText -Path $CliPath -Content $updated

    return [pscustomobject]@{ Status = 'patched'; Path = $CliPath; BackupPath = $backupPath; Changed = $true }
}

function Ensure-ClaudeHookConfigsHealthy {
    param([string]$GitBashPath)

    $paths = @(Get-ClaudeHookConfigCandidatePaths)
    if ($paths.Count -eq 0) {
        Write-Log 'Nenhum arquivo de configuração de hooks do Claude encontrado para validar.' 'INFO'
        return
    }

    foreach ($path in $paths) {
        $raw = $null
        try {
            $raw = Get-Content -Path $path -Raw -Encoding utf8
        } catch {
            Write-Log "Falha ao ler config de hooks: $path" 'WARN'
            continue
        }

        $obj = $null
        try {
            $obj = $raw | ConvertFrom-Json -ErrorAction Stop
        } catch {
            Write-Log "Config de hooks nao é JSON válido: $path" 'WARN'
            continue
        }

        $hooks = $null
        try { $hooks = $obj.hooks } catch { $hooks = $null }
        if (-not $hooks) { continue }

        $changed = $false
        foreach ($k in @('SessionStart', 'UserPromptSubmit', 'Stop', 'StopFailure', 'PostToolUseFailure')) {
            $arr = $null
            try { $arr = $hooks.$k } catch { $arr = $null }
            if (-not $arr) { continue }

            $newArr = @()
            foreach ($item in @($arr)) {
                $beforeItem = ''
                try { $beforeItem = (($item | ConvertTo-Json -Depth 30 -Compress) -as [string]) } catch { $beforeItem = '' }
                $fixed = Convert-HookItemIfNeeded -Item $item -GitBashPath $GitBashPath
                if ($null -ne $fixed) {
                    $afterItem = ''
                    try { $afterItem = (($fixed | ConvertTo-Json -Depth 30 -Compress) -as [string]) } catch { $afterItem = '' }
                    if ($beforeItem -ne $afterItem) { $changed = $true }
                    $newArr += $fixed
                } else {
                    $changed = $true
                    Write-Log "Hook inválido removido ($k) em $path" 'WARN'
                }
            }

            if ($newArr.Count -ne @($arr).Count) {
                try { $hooks.$k = $newArr } catch { }
            }
        }

        if ($changed) {
            $bak = Backup-FileWithTimestamp -Path $path
            Write-Log "Backup criado: $bak"
            try {
                $json = $obj | ConvertTo-Json -Depth 50
                Set-Content -Path $path -Value $json -Encoding utf8
                Write-Log "Config de hooks corrigida: $path"
            } catch {
                Write-Log "Falha ao salvar config de hooks corrigida: $path" 'ERROR'
            }
        } else {
            Write-Log "Config de hooks OK: $path"
        }
    }
}

function Ensure-ClaudeCodeDefaults {
    param([string]$GitBashPath)

    $userHome = Get-BootstrapUserHomePath
    if ([string]::IsNullOrWhiteSpace($userHome)) { return }
    $settingsDir = Join-Path $userHome '.claude'
    $settingsPath = Join-Path $settingsDir 'settings.json'
    $null = New-Item -Path $settingsDir -ItemType Directory -Force

    $raw = $null
    $obj = $null
    if (Test-Path $settingsPath) {
        try {
            $raw = Get-Content -Path $settingsPath -Raw -Encoding utf8
        } catch {
            $raw = $null
        }
        if ($raw) {
            try {
                $obj = $raw | ConvertFrom-Json -ErrorAction Stop
            } catch {
                $bak = Backup-FileWithTimestamp -Path $settingsPath
                Write-Log "settings.json inválido; backup criado: $bak" 'WARN'
                $obj = $null
            }
        }
    }
    if (-not $obj) { $obj = [pscustomobject]@{} }
    if (($obj -isnot [pscustomobject]) -and ($obj -isnot [hashtable])) {
        if (Test-Path $settingsPath) {
            $bak = Backup-FileWithTimestamp -Path $settingsPath
            Write-Log "settings.json com formato inválido; backup criado: $bak" 'WARN'
        }
        $obj = [pscustomobject]@{}
    }

    $changed = $false
    function Get-TargetPropertyState {
        param(
            [Parameter(Mandatory = $true)]$Target,
            [Parameter(Mandatory = $true)][string]$Name
        )

        if ($Target -is [System.Collections.IDictionary]) {
            foreach ($key in @($Target.Keys)) {
                if ([string]::Equals([string]$key, $Name, [System.StringComparison]::OrdinalIgnoreCase)) {
                    return [pscustomobject]@{
                        Exists = $true
                        Key = $key
                        Value = $Target[$key]
                    }
                }
            }

            return [pscustomobject]@{
                Exists = $false
                Key = $Name
                Value = $null
            }
        }

        $prop = $null
        try { $prop = [System.Management.Automation.PSObject]::AsPSObject($Target).Properties[$Name] } catch { $prop = $null }
        if ($null -ne $prop) {
            $value = $null
            try { $value = $prop.Value } catch { $value = $null }
            return [pscustomobject]@{
                Exists = $true
                Key = $Name
                Value = $value
            }
        }

        return [pscustomobject]@{
            Exists = $false
            Key = $Name
            Value = $null
        }
    }
    function Set-TargetPropertyValue {
        param(
            [Parameter(Mandatory = $true)]$Target,
            [Parameter(Mandatory = $true)][string]$Name,
            [Parameter(Mandatory = $true)]$Value
        )

        $state = Get-TargetPropertyState -Target $Target -Name $Name
        if ($Target -is [System.Collections.IDictionary]) {
            $Target[$state.Key] = $Value
            return
        }

        $Target | Add-Member -NotePropertyName $Name -NotePropertyValue $Value -Force
    }
    function Ensure-PropValue {
        param(
            [Parameter(Mandatory = $true)]$Target,
            [Parameter(Mandatory = $true)][string]$Name,
            [Parameter(Mandatory = $true)]$Value
        )
        $state = Get-TargetPropertyState -Target $Target -Name $Name
        if ((-not $state.Exists) -or ($state.Value -ne $Value)) {
            Set-TargetPropertyValue -Target $Target -Name $Name -Value $Value
            Set-Variable -Name changed -Value $true -Scope 1
        }
    }
    function Ensure-ObjectProp {
        param(
            [Parameter(Mandatory = $true)]$Target,
            [Parameter(Mandatory = $true)][string]$Name
        )
        $state = Get-TargetPropertyState -Target $Target -Name $Name
        $v = $state.Value
        if ((-not $v) -or (($v -isnot [pscustomobject]) -and ($v -isnot [System.Collections.IDictionary]))) {
            $v = [ordered]@{}
            Set-TargetPropertyValue -Target $Target -Name $Name -Value $v
            Set-Variable -Name changed -Value $true -Scope 1
        }
        return $v
    }
    function Ensure-StringArrayProp {
        param(
            [Parameter(Mandatory = $true)]$Target,
            [Parameter(Mandatory = $true)][string]$Name
        )
        $state = Get-TargetPropertyState -Target $Target -Name $Name
        $v = $state.Value
        if ($v -is [string]) {
            $v = @([string]$v)
            Set-TargetPropertyValue -Target $Target -Name $Name -Value $v
            Set-Variable -Name changed -Value $true -Scope 1
        } elseif (($null -eq $v) -or ($v -is [System.Collections.IDictionary]) -or (-not ($v -is [System.Collections.IEnumerable]))) {
            $v = @()
            Set-TargetPropertyValue -Target $Target -Name $Name -Value $v
            Set-Variable -Name changed -Value $true -Scope 1
        }
        return @($v)
    }
    function Merge-StringArrayUniqueCI {
        param(
            [string[]]$Existing,
            [string[]]$Add
        )
        $set = @{}
        $out = @()
        foreach ($x in @($Existing)) {
            if (-not $x) { continue }
            $k = $x.ToLowerInvariant()
            if (-not $set.ContainsKey($k)) { $set[$k] = $true; $out += $x }
        }
        foreach ($x in @($Add)) {
            if (-not $x) { continue }
            $k = $x.ToLowerInvariant()
            if (-not $set.ContainsKey($k)) { $set[$k] = $true; $out += $x }
        }
        return $out
    }

    Ensure-PropValue -Target $obj -Name '$schema' -Value 'https://json.schemastore.org/claude-code-settings.json'

    $envObj = Ensure-ObjectProp -Target $obj -Name 'env'
    Ensure-PropValue -Target $envObj -Name 'CLAUDE_CODE_USE_POWERSHELL_TOOL' -Value '1'
    Ensure-PropValue -Target $envObj -Name 'CLAUDE_CODE_EFFORT_LEVEL' -Value 'low'
    Ensure-PropValue -Target $envObj -Name 'CAVEMAN_DEFAULT_MODE' -Value 'ultra'

    $permObj = Ensure-ObjectProp -Target $obj -Name 'permissions'
    Ensure-PropValue -Target $permObj -Name 'defaultMode' -Value 'acceptEdits'

    $pluginsObj = Ensure-ObjectProp -Target $obj -Name 'enabledPlugins'
    foreach ($pluginId in @(Get-ClaudeCodeDesiredPlugins)) {
        if ([string]::IsNullOrWhiteSpace($pluginId)) { continue }
        Ensure-PropValue -Target $pluginsObj -Name $pluginId -Value $true
    }

    $allow = Ensure-StringArrayProp -Target $permObj -Name 'allow'
    $deny = Ensure-StringArrayProp -Target $permObj -Name 'deny'

    $allowWanted = @(
        'Bash'
    )

    $denyWanted = @(
        'Read(.env)',
        'Read(.env.*)',
        'Read(secrets/**)',
        'Read(**/.env)',
        'Read(**/.env.*)',
        'Read(**/secrets/**)'
    )

    $newAllow = Merge-StringArrayUniqueCI -Existing $allow -Add $allowWanted
    $allowNeedsUpdate = ($allow -is [string]) -or (@($newAllow).Count -ne @($allow).Count)
    if ($allowNeedsUpdate) {
        Set-TargetPropertyValue -Target $permObj -Name 'allow' -Value @($newAllow)
        $changed = $true
    }

    $newDeny = Merge-StringArrayUniqueCI -Existing $deny -Add $denyWanted
    if (@($newDeny).Count -ne @($deny).Count) {
        Set-TargetPropertyValue -Target $permObj -Name 'deny' -Value $newDeny
        $changed = $true
    }

    if ($changed) {
        if (Test-Path $settingsPath) {
            $bak = Backup-FileWithTimestamp -Path $settingsPath
            Write-Log "Backup criado: $bak"
        }
        try {
            $json = $obj | ConvertTo-Json -Depth 50
            Set-Content -Path $settingsPath -Value $json -Encoding utf8
            Write-Log "Claude Code defaults aplicados: $settingsPath"
        } catch {
            Write-Log "Falha ao aplicar defaults do Claude Code em: $settingsPath" 'WARN'
        }
    } else {
        Write-Log "Claude Code defaults já configurados: $settingsPath"
    }
}

function Get-ClaudeCodeDesiredPlugins {
    return @(
        'caveman@caveman',
        'typescript-lsp@claude-plugins-official',
        'clangd-lsp@claude-plugins-official',
        'claude-md-management@claude-plugins-official',
        'code-review@claude-plugins-official'
    )
}

function Get-ClaudeCodeInstalledPlugins {
    param([Parameter(Mandatory = $true)][string]$ClaudeExe)

    if ([string]::IsNullOrWhiteSpace($ClaudeExe) -or -not (Test-Path $ClaudeExe)) {
        return @{}
    }

    $result = Invoke-BootstrapCommandCapture -Exe $ClaudeExe -Args @('plugin', 'list')
    if ($result.ExitCode -ne 0) {
        return @{}
    }

    $installed = @{}
    foreach ($line in @($result.Output)) {
        $text = [string]$line
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        $trimmed = $text.Trim()
        if ($trimmed -match '^\s*[❯>\-*]\s*([A-Za-z0-9_.\-]+@[A-Za-z0-9_.\-]+)\s*$') {
            $installed[[string]$matches[1]] = $true
        }
    }

    return $installed
}

function Ensure-ClaudeCodePlugins {
    param([hashtable]$State)

    $claudeExe = Resolve-CommandPath -Name 'claude'
    if (-not $claudeExe) {
        Write-Log 'Claude Code plugins: runtime "claude" ausente; pulando.' 'WARN'
        return [ordered]@{
            ok = $false
            installed = @()
            skipped = @('runtime-ausente')
            failed = @()
        }
    }

    $installedMap = Get-ClaudeCodeInstalledPlugins -ClaudeExe ([string]$claudeExe)
    $installed = @()
    $skipped = @()
    $failed = @()

    foreach ($pluginId in @(Get-ClaudeCodeDesiredPlugins)) {
        if ([string]::IsNullOrWhiteSpace($pluginId)) { continue }
        if ($installedMap.ContainsKey($pluginId)) {
            $skipped += @($pluginId)
            continue
        }

        $exitCode = Invoke-NativeWithLog -Exe ([string]$claudeExe) -Args @('plugin', 'install', $pluginId)
        if ($exitCode -eq 0) {
            $installed += @($pluginId)
        } else {
            $failed += @($pluginId)
            Write-Log ("Claude Code plugins: falha ao instalar {0} (exit={1})." -f $pluginId, $exitCode) 'WARN'
        }
    }

    return [ordered]@{
        ok = ($failed.Count -eq 0)
        installed = @($installed)
        skipped = @($skipped)
        failed = @($failed)
    }
}

function Get-ClaudeCodeDesiredProjectMcps {
    param([Parameter(Mandatory = $true)][hashtable]$ManagedProviders)

    $out = New-Object System.Collections.Generic.List[hashtable]
    $out.Add([ordered]@{
        name = 'sentry'
        url = 'https://mcp.sentry.dev/mcp'
        headers = @()
    })

    $bonsaiProvider = $null
    if ($ManagedProviders.Contains('bonsai') -and ($ManagedProviders['bonsai'] -is [System.Collections.IDictionary])) {
        $bonsaiProvider = ConvertTo-BootstrapHashtable -InputObject $ManagedProviders['bonsai']
    }
    if ($bonsaiProvider -is [hashtable] -and -not [string]::IsNullOrWhiteSpace([string]$bonsaiProvider['token'])) {
        $bonsaiBaseUrl = if (-not [string]::IsNullOrWhiteSpace([string]$bonsaiProvider['baseUrl'])) { [string]$bonsaiProvider['baseUrl'] } else { 'https://mcp.bonsai-rx.org/mcp' }
        $out.Add([ordered]@{
            name = 'bonsai'
            url = $bonsaiBaseUrl
            headers = @(
                ('Authorization: Bearer {0}' -f [string]$bonsaiProvider['token'])
            )
        })
    }

    return @($out.ToArray())
}

function Get-ClaudeCodeProjectMcpNames {
    param([Parameter(Mandatory = $true)][string]$ClaudeExe)

    $result = Invoke-BootstrapCommandCapture -Exe $ClaudeExe -Args @('mcp', 'list')
    if ($result.ExitCode -ne 0) {
        return @{}
    }

    $names = @{}
    foreach ($line in @($result.Output)) {
        $text = [string]$line
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        $trimmed = $text.Trim()
        if ($trimmed -match '^([A-Za-z0-9_.\-]+)\s*:') {
            $names[[string]$matches[1]] = $true
        }
    }
    return $names
}

function Ensure-ClaudeCodeProjectMcps {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][hashtable]$ManagedProviders
    )

    $claudeExe = Resolve-CommandPath -Name 'claude'
    if (-not $claudeExe) {
        Write-Log 'Claude Code MCPs: runtime "claude" ausente; pulando.' 'WARN'
        return
    }

    $cwd = if (-not [string]::IsNullOrWhiteSpace([string]$State.CloneBaseDir) -and (Test-Path ([string]$State.CloneBaseDir))) { [string]$State.CloneBaseDir } else { (Get-Location).Path }

    Push-Location $cwd
    try {
        $existing = Get-ClaudeCodeProjectMcpNames -ClaudeExe ([string]$claudeExe)
        foreach ($spec in @(Get-ClaudeCodeDesiredProjectMcps -ManagedProviders $ManagedProviders)) {
            $name = [string]$spec['name']
            $url = [string]$spec['url']
            if ([string]::IsNullOrWhiteSpace($name) -or [string]::IsNullOrWhiteSpace($url)) { continue }
            if ($existing.ContainsKey($name)) { continue }

            $args = @('mcp', 'add', '-s', 'project', '--transport', 'http', $name, $url)
            foreach ($header in @($spec['headers'])) {
                if ([string]::IsNullOrWhiteSpace([string]$header)) { continue }
                $args += @('-H', [string]$header)
            }

            $exitCode = Invoke-NativeWithLog -Exe ([string]$claudeExe) -Args $args
            if ($exitCode -ne 0) {
                Write-Log ("Claude Code MCPs: falha ao adicionar {0} (exit={1})." -f $name, $exitCode) 'WARN'
            }
        }
    } finally {
        Pop-Location
    }
}

function Test-DockerReady {
    $dockerExe = Resolve-CommandPath -Name 'docker'
    if (-not $dockerExe) { return $false }

    $result = Invoke-BootstrapCommandCapture -Exe ([string]$dockerExe) -Args @('version')
    return ($result.ExitCode -eq 0)
}

function Ensure-OpenWebUI {
    param([hashtable]$State)

    if (-not (Test-DockerReady)) {
        Write-Log 'Open WebUI: Docker indisponível (instale/abra Docker Desktop). Pulando.' 'WARN'
        return
    }

    $dockerExe = [string](Resolve-CommandPath -Name 'docker')
    $containerName = 'open-webui'
    $image = 'ghcr.io/open-webui/open-webui:main'

    $list = Invoke-BootstrapCommandCapture -Exe $dockerExe -Args @('ps', '-a', '--format', '{{.Names}}')
    if ($list.ExitCode -ne 0) {
        Write-Log 'Open WebUI: falha ao listar containers Docker.' 'WARN'
        return
    }

    $exists = $false
    foreach ($line in @($list.Output)) {
        if ([string]::Equals(([string]$line).Trim(), $containerName, [System.StringComparison]::OrdinalIgnoreCase)) {
            $exists = $true
            break
        }
    }

    if ($exists) {
        $inspect = Invoke-BootstrapCommandCapture -Exe $dockerExe -Args @('inspect', '-f', '{{.State.Running}}', $containerName)
        $running = $false
        if ($inspect.ExitCode -eq 0 -and @($inspect.Output).Count -gt 0) {
            $running = [string]::Equals(([string]$inspect.Output[0]).Trim(), 'true', [System.StringComparison]::OrdinalIgnoreCase)
        }
        if ($running) {
            Write-Log 'Open WebUI: container já em execução.'
            return
        }

        $exitCode = Invoke-NativeWithLog -Exe $dockerExe -Args @('start', $containerName)
        if ($exitCode -ne 0) {
            Write-Log ("Open WebUI: falha ao iniciar container (exit={0})." -f $exitCode) 'WARN'
        }
        return
    }

    $exitCode = Invoke-NativeWithLog -Exe $dockerExe -Args @(
        'run',
        '-d',
        '--name', $containerName,
        '-p', '3000:8080',
        '-v', 'open-webui:/app/backend/data',
        '--restart', 'unless-stopped',
        $image
    )
    if ($exitCode -ne 0) {
        Write-Log ("Open WebUI: falha ao criar container (exit={0})." -f $exitCode) 'WARN'
    } else {
        Write-Log 'Open WebUI: container criado e iniciado (http://localhost:3000).'
    }
}

function Get-WindowsOptionalFeatureState {
    param([Parameter(Mandatory = $true)][string]$FeatureName)
    try {
        $out = & dism.exe /online /Get-FeatureInfo /FeatureName:$FeatureName 2>&1
        if (-not $out) { return 'Unknown' }
        $text = ($out | Out-String)
        if ($text -match '(?im)^\\s*State\\s*:\\s*Enabled\\s*$') { return 'Enabled' }
        if ($text -match '(?im)^\\s*Estado\\s*:\\s*Habilitado\\s*$') { return 'Enabled' }
        if ($text -match '(?im)^\\s*State\\s*:\\s*Enable Pending\\s*$') { return 'EnablePending' }
        if ($text -match '(?im)^\\s*Estado\\s*:\\s*Habilita(ç|c)ão Pendente\\s*$') { return 'EnablePending' }
        if ($text -match '(?im)^\\s*State\\s*:\\s*Disabled\\s*$') { return 'Disabled' }
        if ($text -match '(?im)^\\s*Estado\\s*:\\s*Desabilitado\\s*$') { return 'Disabled' }
        return 'Unknown'
    } catch {
        return 'Unknown'
    }
}

function Ensure-WindowsOptionalFeatureEnabled {
    param(
        [Parameter(Mandatory = $true)][string]$FeatureName,
        [string]$DisplayName = $FeatureName
    )

    $state = Get-WindowsOptionalFeatureState -FeatureName $FeatureName
    if ($state -eq 'Enabled') {
        Write-Log "$DisplayName já habilitado."
        return [ordered]@{ featureName = $FeatureName; displayName = $DisplayName; previousState = $state; status = 'enabled'; changed = $false; restartRequired = $false; exitCode = 0 }
    }

    if ($state -eq 'EnablePending') {
        Write-Log "$DisplayName ja esta pendente de reinicio." 'WARN'
        return [ordered]@{ featureName = $FeatureName; displayName = $DisplayName; previousState = $state; status = 'requires-reboot'; changed = $false; restartRequired = $true; exitCode = 3010 }
    }

    if (-not (Test-IsAdmin)) {
        Write-Log "$DisplayName requer privilégios de administrador para habilitar. Pulando." 'WARN'
        return [ordered]@{ featureName = $FeatureName; displayName = $DisplayName; previousState = $state; status = 'skipped'; changed = $false; restartRequired = $false; exitCode = $null }
    }

    Write-Log "Habilitando recurso do Windows: $DisplayName ($FeatureName)..."
    $exitCode = Invoke-NativeWithLog -Exe 'dism.exe' -Args @(
        '/online',
        '/Enable-Feature',
        "/FeatureName:$FeatureName",
        '/All',
        '/NoRestart'
    )
    if (($exitCode -ne 0) -and ($exitCode -ne 3010)) { throw "Falha ao habilitar recurso do Windows: $DisplayName (exit=$exitCode)." }
    Write-Log "$DisplayName habilitado. Pode ser necessario reiniciar o Windows." 'WARN'
    return [ordered]@{ featureName = $FeatureName; displayName = $DisplayName; previousState = $state; status = 'requires-reboot'; changed = $true; restartRequired = $true; exitCode = $exitCode }
}

function Test-BootstrapWindowsFeatureResultsRequireReboot {
    param([AllowNull()][object[]]$Results)

    foreach ($result in @($Results)) {
        $row = ConvertTo-BootstrapHashtable -InputObject $result
        if ($row -is [hashtable] -and (Test-BootstrapMapContainsKey -Map $row -Key 'restartRequired') -and [bool]$row['restartRequired']) {
            return $true
        }
    }
    return $false
}

function New-BootstrapWslRestartRequiredException {
    param([AllowNull()][object[]]$FeatureResults)

    $features = @()
    foreach ($result in @($FeatureResults)) {
        $row = ConvertTo-BootstrapHashtable -InputObject $result
        if ($row -is [hashtable] -and (Test-BootstrapMapContainsKey -Map $row -Key 'restartRequired') -and [bool]$row['restartRequired']) {
            $name = if (Test-BootstrapMapContainsKey -Map $row -Key 'displayName') { [string]$row['displayName'] } else { [string]$row['featureName'] }
            if (-not [string]::IsNullOrWhiteSpace($name)) { $features += @($name) }
        }
    }
    if ($features.Count -eq 0) { $features = @('WSL/VirtualMachinePlatform') }
    $message = "WSL habilitou recurso(s) do Windows ou encontrou feature em estado pendente ({0}). Reinicie o Windows e rode novamente com -Resume antes de tentar reparar Microsoft.WSL." -f ($features -join ', ')
    return (New-BootstrapBlockedException -Message $message -Kind 'wsl-requires-reboot' -Action 'restart-and-resume' -Reasons (@('wsl-feature-requires-reboot') + $features))
}

function Get-BootstrapWindowsCapabilityState {
    param([Parameter(Mandatory = $true)][string]$CapabilityName)
    try {
        $cap = Get-WindowsCapability -Online -Name $CapabilityName -ErrorAction Stop | Select-Object -First 1
        if ($cap -and $cap.State) { return [string]$cap.State }
    } catch {
        try {
            $out = & dism.exe /online /Get-CapabilityInfo /CapabilityName:$CapabilityName 2>&1
            $text = ($out | Out-String)
            if ($text -match '(?im)^\s*State\s*:\s*Installed\s*$') { return 'Installed' }
            if ($text -match '(?im)^\s*Estado\s*:\s*Instalado\s*$') { return 'Installed' }
            if ($text -match '(?im)^\s*State\s*:\s*Not Present\s*$') { return 'NotPresent' }
            if ($text -match '(?im)^\s*Estado\s*:\s*N.o Presente\s*$') { return 'NotPresent' }
        } catch {
            return 'Unknown'
        }
    }
    return 'Unknown'
}

function Ensure-BootstrapWindowsFeatureComponent {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseApprovedVerbs', '')]
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][string]$ComponentName,
        [Parameter(Mandatory = $true)]$ComponentDef
    )

    $features = @($ComponentDef.FeatureNames | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    $dryRun = [bool]$State.DryRun
    if ($dryRun) {
        Write-Log ("DryRun: planejado habilitar recurso(s) Windows para {0}: {1}" -f $ComponentName, ($features -join ', '))
        return [ordered]@{ status = 'planned'; dryRun = $true; component = $ComponentName; featureNames = @($features) }
    }

    if (-not (Test-IsAdmin)) {
        $message = ("{0} requer PowerShell elevado para habilitar recurso(s) Windows: {1}" -f $ComponentName, ($features -join ', '))
        Write-Log $message 'WARN'
        Register-BootstrapComponentSkip -State $State -ComponentName $ComponentName -Reason 'admin-required' -Message $message -Action 'rerun-elevated'
        return [ordered]@{ status = 'blocked'; dryRun = $false; component = $ComponentName; featureNames = @($features); requiresAdmin = $true }
    }

    $changed = New-Object System.Collections.Generic.List[string]
    foreach ($feature in $features) {
        $oldState = Get-WindowsOptionalFeatureState -FeatureName $feature
        if ($oldState -eq 'Enabled') { continue }
        $null = Ensure-WindowsOptionalFeatureEnabled -FeatureName $feature -DisplayName $feature
        Register-BootstrapChange -State $State -Type WindowsFeature -Target $feature -OldValue $oldState -NewValue 'Enabled' -Operation 'enable-windows-feature' -Component $ComponentName
        $changed.Add($feature)
    }
    $status = if ($changed.Count -gt 0) { 'changed' } else { 'healthy' }
    return [ordered]@{ status = $status; dryRun = $false; component = $ComponentName; featureNames = @($features); changed = @($changed.ToArray()) }
}

function Ensure-BootstrapOpenSshServerPostInstall {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseApprovedVerbs', '')]
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$ComponentDef,
        [Parameter(Mandatory = $true)][string]$ComponentName
    )

    $serviceName = [string]$ComponentDef.ServiceName
    if (-not [string]::IsNullOrWhiteSpace($serviceName)) {
        $svc = Get-Service -Name $serviceName -ErrorAction SilentlyContinue
        if ($svc) {
            $oldStartType = ''
            Set-Service -Name $serviceName -StartupType Automatic -ErrorAction Stop
            if ($svc.Status -ne 'Running') { Start-Service -Name $serviceName -ErrorAction Stop }
            Register-BootstrapChange -State $State -Type Service -Target $serviceName -OldValue $oldStartType -NewValue 'Automatic/Running' -Operation 'enable-service' -Component $ComponentName
        }
    }

    $profiles = @($ComponentDef.FirewallProfiles | Where-Object { $_ -in @('Domain','Private') })
    if (($profiles -contains 'Public') -or $profiles.Count -eq 0) { $profiles = @('Domain','Private') }
    $ruleName = [string]$ComponentDef.FirewallRuleName
    if ([string]::IsNullOrWhiteSpace($ruleName)) { $ruleName = 'PhaseZero OpenSSH Server Domain Private' }
    $existing = Get-NetFirewallRule -DisplayName $ruleName -ErrorAction SilentlyContinue
    if (-not $existing) {
        New-NetFirewallRule -DisplayName $ruleName -Direction Inbound -Action Allow -Protocol TCP -LocalPort 22 -Profile ($profiles -join ',') | Out-Null
        Register-BootstrapChange -State $State -Type FirewallRule -Target $ruleName -OldValue $null -NewValue ($profiles -join ',') -Operation 'create-firewall-rule' -Component $ComponentName
    }
}

function Ensure-BootstrapWindowsCapabilityComponent {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseApprovedVerbs', '')]
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][string]$ComponentName,
        [Parameter(Mandatory = $true)]$ComponentDef
    )

    $capabilities = @($ComponentDef.CapabilityNames | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    $firewallProfiles = @()
    if ($ComponentDef.PSObject.Properties.Name -contains 'FirewallProfiles') {
        $firewallProfiles = @($ComponentDef.FirewallProfiles | Where-Object { $_ -in @('Domain','Private') })
    }
    $dryRun = [bool]$State.DryRun
    if ($dryRun) {
        Write-Log ("DryRun: planejado habilitar capability(s) Windows para {0}: {1}" -f $ComponentName, ($capabilities -join ', '))
        return [ordered]@{ status = 'planned'; dryRun = $true; component = $ComponentName; capabilityNames = @($capabilities); firewallProfiles = @($firewallProfiles) }
    }

    if (-not (Test-IsAdmin)) {
        $message = ("{0} requer PowerShell elevado para habilitar capability(s) Windows: {1}" -f $ComponentName, ($capabilities -join ', '))
        Write-Log $message 'WARN'
        Register-BootstrapComponentSkip -State $State -ComponentName $ComponentName -Reason 'admin-required' -Message $message -Action 'rerun-elevated'
        return [ordered]@{ status = 'blocked'; dryRun = $false; component = $ComponentName; capabilityNames = @($capabilities); requiresAdmin = $true; firewallProfiles = @($firewallProfiles) }
    }

    $changed = New-Object System.Collections.Generic.List[string]
    foreach ($capability in $capabilities) {
        $oldState = Get-BootstrapWindowsCapabilityState -CapabilityName $capability
        if ($oldState -eq 'Installed') { continue }
        Write-Log ("Habilitando capability Windows: {0}" -f $capability)
        Add-WindowsCapability -Online -Name $capability -ErrorAction Stop | Out-Null
        Register-BootstrapChange -State $State -Type WindowsCapability -Target $capability -OldValue $oldState -NewValue 'Installed' -Operation 'add-windows-capability' -Component $ComponentName
        $changed.Add($capability)
    }

    if ($ComponentName -eq 'openssh-server') {
        Ensure-BootstrapOpenSshServerPostInstall -State $State -ComponentDef $ComponentDef -ComponentName $ComponentName
    }

    $status = if ($changed.Count -gt 0) { 'changed' } else { 'healthy' }
    return [ordered]@{ status = $status; dryRun = $false; component = $ComponentName; capabilityNames = @($capabilities); changed = @($changed.ToArray()); firewallProfiles = @($firewallProfiles) }
}

function Test-BootstrapWinhanceInstalled {
    param([Parameter(Mandatory = $true)]$ComponentDef)

    $probePaths = @()
    if ($ComponentDef.PSObject.Properties.Name -contains 'ProbePaths') { $probePaths = @($ComponentDef.ProbePaths) }
    if ($probePaths.Count -gt 0 -and (Test-WingetProbePathsOnDisk -ProbePaths $probePaths)) { return $true }
    return $false
}

function Install-BootstrapWinhanceComponent {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$ComponentDef
    )

    $sourceUrl = [string]$ComponentDef.SourceUrl
    $installCommand = [string]$ComponentDef.InstallCommand
    if ([string]::IsNullOrWhiteSpace($sourceUrl)) { $sourceUrl = 'https://get.winhance.net/' }
    if ([string]::IsNullOrWhiteSpace($installCommand)) { $installCommand = 'download-validate-execute https://get.winhance.net/' }

    if ([bool]$State.DryRun) {
        Write-Log ("DryRun: planejado instalar Winhance via fonte oficial: {0}; nenhuma otimizacao/tweak sera aplicada." -f $sourceUrl)
        return [ordered]@{ status = 'planned'; dryRun = $true; sourceUrl = $sourceUrl; installCommand = $installCommand; tweaksApplied = $false }
    }

    if (Test-BootstrapWinhanceInstalled -ComponentDef $ComponentDef) {
        Write-Log 'Winhance ja instalado (artefato validado em disco).'
        return [ordered]@{ status = 'healthy'; dryRun = [bool]$State.DryRun; sourceUrl = $sourceUrl; tweaksApplied = $false }
    }

    if (-not (Test-IsAdmin)) {
        $message = 'Winhance installer oficial requer PowerShell elevado. Bloqueado sem aplicar tweaks.'
        Write-Log $message 'WARN'
        Register-BootstrapComponentSkip -State $State -ComponentName 'winhance' -Reason 'admin-required' -Message $message -Action 'rerun-elevated-or-install-manually'
        return [ordered]@{ status = 'blocked'; dryRun = $false; sourceUrl = $sourceUrl; requiresAdmin = $true; tweaksApplied = $false }
    }

    $powershellExe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $tempRoot = [System.IO.Path]::GetTempPath()
    $scriptPath = Join-Path $tempRoot ("phasezero-winhance-{0}.ps1" -f ([Guid]::NewGuid().ToString('N')))
    Write-Log 'Instalando Winhance via instalador oficial. Nenhuma configuracao/tweak sera aplicado pelo PhaseZero.'
    try {
        Invoke-WebRequestWithRetry -Uri $sourceUrl -OutFile $scriptPath -OperationName 'download do instalador Winhance'
        $scriptInfo = Get-Item -LiteralPath $scriptPath -ErrorAction Stop
        if ($scriptInfo.Length -lt 256 -or $scriptInfo.Length -gt 2097152) {
            throw ("Instalador Winhance falhou validacao de tamanho: {0} bytes." -f $scriptInfo.Length)
        }
        $scriptText = Get-Content -LiteralPath $scriptPath -Raw -ErrorAction Stop
        if ([string]::IsNullOrWhiteSpace($scriptText) -or $scriptText -match '(?is)<\s*!?doctype\s+html|<\s*html\b') {
            throw 'Instalador Winhance falhou validacao de conteudo.'
        }
        $exitCode = Invoke-NativeWithLog -Exe $powershellExe -Args @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $scriptPath) -TimeoutMs 300000
    } finally {
        Remove-Item -LiteralPath $scriptPath -Force -ErrorAction SilentlyContinue
    }
    if ($exitCode -ne 0) {
        throw ("Winhance installer oficial falhou (exit={0})." -f $exitCode)
    }
    Register-BootstrapChange -State $State -Type Package -Target 'Winhance' -OldValue $null -NewValue $sourceUrl -Operation 'install-official-installer' -Component 'winhance'
    return [ordered]@{ status = 'installed'; dryRun = $false; sourceUrl = $sourceUrl; tweaksApplied = $false }
}

function Test-BootstrapAmdGpuPresent {
    try {
        $video = @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop |
            Where-Object { $_.Name -match '(?i)AMD|Radeon|Van\s*Gogh|Custom\s*GPU' })
        return ($video.Count -gt 0)
    } catch {
        return $false
    }
}

function Test-BootstrapArchiveHash {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [string]$Sha1 = '',
        [string]$Md5 = ''
    )

    $details = New-Object System.Collections.Generic.List[string]
    $ok = $true
    if (-not [string]::IsNullOrWhiteSpace($Sha1)) {
        $actual = (Get-FileHash -Path $Path -Algorithm SHA1).Hash
        if ($actual -ne $Sha1.Trim().ToUpperInvariant()) {
            $ok = $false
            $details.Add(("SHA1 esperado {0}, obtido {1}" -f $Sha1.Trim().ToUpperInvariant(), $actual)) | Out-Null
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($Md5)) {
        $actual = (Get-FileHash -Path $Path -Algorithm MD5).Hash
        if ($actual -ne $Md5.Trim().ToUpperInvariant()) {
            $ok = $false
            $details.Add(("MD5 esperado {0}, obtido {1}" -f $Md5.Trim().ToUpperInvariant(), $actual)) | Out-Null
        }
    }
    return [pscustomobject]@{ Ok = $ok; Verified = (-not [string]::IsNullOrWhiteSpace($Sha1) -or -not [string]::IsNullOrWhiteSpace($Md5)); Details = ($details -join '; ') }
}

function Install-BootstrapAmdDriverRelease {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Release,
        [Parameter(Mandatory = $true)][string]$SevenZip,
        [Parameter(Mandatory = $true)][string]$DownloadDir,
        [Parameter(Mandatory = $true)][string]$DisplayName
    )

    $version = [string]$Release.Version
    $sourceUrl = [string]$Release.SourceUrl
    $archiveName = [string]$Release.ArchiveName
    $sha1 = if ($Release.PSObject.Properties.Name -contains 'Sha1') { [string]$Release.Sha1 } else { '' }
    $md5 = if ($Release.PSObject.Properties.Name -contains 'Md5') { [string]$Release.Md5 } else { '' }
    if ([string]::IsNullOrWhiteSpace($sourceUrl) -or [string]::IsNullOrWhiteSpace($archiveName)) {
        return [pscustomobject]@{ Ok = $false; Version = $version; Reason = 'release sem SourceUrl/ArchiveName' }
    }

    $archivePath = Join-Path $DownloadDir $archiveName
    Write-Log ("Baixando {0} v{1}: {2}" -f $DisplayName, $version, $sourceUrl)
    try {
        Invoke-WebRequestWithRetry -Uri $sourceUrl -OutFile $archivePath -OperationName ("{0} {1}" -f $DisplayName, $version)
    } catch {
        return [pscustomobject]@{ Ok = $false; Version = $version; Reason = ("download falhou: {0}" -f $_.Exception.Message) }
    }
    Unblock-File -Path $archivePath -ErrorAction SilentlyContinue

    if (-not [string]::IsNullOrWhiteSpace($sha1) -or -not [string]::IsNullOrWhiteSpace($md5)) {
        $hash = Test-BootstrapArchiveHash -Path $archivePath -Sha1 $sha1 -Md5 $md5
        if (-not $hash.Ok) {
            Write-Log ("Integridade FALHOU para {0} v{1}: {2}. Descartando download (e cache)." -f $DisplayName, $version, $hash.Details) 'WARN'
            Remove-Item -Path $archivePath -Force -ErrorAction SilentlyContinue
            try { Remove-Item -Path (Join-Path (Get-BootstrapCacheDir) $archiveName) -Force -ErrorAction SilentlyContinue } catch { }
            return [pscustomobject]@{ Ok = $false; Version = $version; Reason = ("hash mismatch: {0}" -f $hash.Details) }
        }
        Write-Log ("Integridade verificada para {0} v{1} (SHA1/MD5)." -f $DisplayName, $version)
    } else {
        Write-Log ("AVISO: {0} v{1} sem hash informado; integridade nao verificada." -f $DisplayName, $version) 'WARN'
    }

    $extractDir = Join-Path $DownloadDir ("amd-driver-{0}" -f $version)
    if (Test-Path $extractDir) { Remove-Item -Path $extractDir -Recurse -Force -ErrorAction SilentlyContinue }
    $null = New-Item -Path $extractDir -ItemType Directory -Force

    Write-Log ("Extraindo {0} com 7-Zip..." -f $archiveName)
    $extractExit = Invoke-NativeWithLog -Exe $SevenZip -Args @('x', $archivePath, ('-o' + $extractDir), '-y') -TimeoutMs 600000
    if ($extractExit -ne 0) {
        return [pscustomobject]@{ Ok = $false; Version = $version; Reason = ("7-Zip exit={0}" -f $extractExit) }
    }

    $setup = Get-ChildItem -Path $extractDir -Filter 'Setup.exe' -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
    if (-not $setup) {
        return [pscustomobject]@{ Ok = $false; Version = $version; Reason = ("Setup.exe ausente em {0}" -f $extractDir) }
    }

    Write-Log ("Instalando {0} v{1} silenciosamente: {2} -INSTALL" -f $DisplayName, $version, $setup.FullName)
    $installExit = Invoke-NativeWithLog -Exe $setup.FullName -Args @('-INSTALL') -TimeoutMs 1800000
    if ($installExit -notin @(0, 3010, 1641)) {
        return [pscustomobject]@{ Ok = $false; Version = $version; Reason = ("Setup exit={0}" -f $installExit) }
    }
    return [pscustomobject]@{ Ok = $true; Version = $version; RebootPending = ($installExit -in @(3010, 1641)); Setup = $setup.FullName }
}

function Get-BootstrapSevenZipExe {
    $candidates = @(
        (Join-Path $env:ProgramFiles '7-Zip\7z.exe'),
        (Join-Path ${env:ProgramFiles(x86)} '7-Zip\7z.exe')
    )
    foreach ($candidate in $candidates) {
        if ($candidate -and (Test-Path $candidate)) { return $candidate }
    }
    $cmd = Get-Command '7z.exe' -ErrorAction SilentlyContinue
    if ($cmd) { return [string]$cmd.Source }
    return $null
}

function Optimize-BootstrapAmdNebulaDriver {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$ComponentDef
    )

    $componentName = [string]$ComponentDef.Name
    $applied = New-Object System.Collections.Generic.List[string]
    $classRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
    # Tweaks conservadores e reversiveis para o painel Adrenalin/driver no Deck.
    $tweaks = @(
        @{ Name = 'EnableUlps'; Value = 0; Reason = 'Desativa ULPS para reduzir microstutter e black screen na GPU do Deck.' }
    )

    try {
        $subKeys = @(Get-ChildItem -Path $classRoot -ErrorAction Stop | Where-Object { $_.PSChildName -match '^\d{4}$' })
    } catch {
        Write-Log ("Tuning Adrenalin ignorado: nao foi possivel ler {0}. {1}" -f $classRoot, $_.Exception.Message) 'WARN'
        return [ordered]@{ applied = $false; tweaks = @() }
    }

    foreach ($key in $subKeys) {
        $props = $null
        try { $props = Get-ItemProperty -Path $key.PSPath -ErrorAction Stop } catch { continue }
        $desc = [string]$props.DriverDesc
        if ($desc -notmatch '(?i)AMD|Radeon|Van\s*Gogh') { continue }
        foreach ($tweak in $tweaks) {
            $name = [string]$tweak.Name
            $old = $null
            if ($props.PSObject.Properties.Name -contains $name) { $old = $props.$name }
            if ([bool]$State.DryRun) { continue }
            try {
                New-ItemProperty -Path $key.PSPath -Name $name -Value ([int]$tweak.Value) -PropertyType DWord -Force | Out-Null
                Register-BootstrapChange -State $State -Type Registry -Target ("{0}\{1}" -f $key.PSPath, $name) -OldValue $old -NewValue ([int]$tweak.Value) -Operation 'amd-nebula-tuning' -Component $componentName
                $applied.Add(("{0}={1}@{2}" -f $name, [int]$tweak.Value, $key.PSChildName)) | Out-Null
                Write-Log ("Tuning Adrenalin: {0}={1} em {2} ({3})" -f $name, [int]$tweak.Value, $key.PSChildName, $tweak.Reason)
            } catch {
                Write-Log ("Falha ao aplicar tuning {0} em {1}: {2}" -f $name, $key.PSChildName, $_.Exception.Message) 'WARN'
            }
        }
    }

    return [ordered]@{ applied = ($applied.Count -gt 0); tweaks = @($applied.ToArray()) }
}

function Install-BootstrapAmdNebulaDriverComponent {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$ComponentDef
    )

    $componentName = [string]$ComponentDef.Name
    $displayName = [string]$ComponentDef.DisplayName
    if ([string]::IsNullOrWhiteSpace($displayName)) { $displayName = $componentName }

    # Lista ordenada de releases candidatos: o primeiro que instalar vence; os demais sao fallback.
    $releases = @()
    if (($ComponentDef.PSObject.Properties.Name -contains 'Releases') -and $ComponentDef.Releases) {
        $releases = @($ComponentDef.Releases)
    } else {
        # Compatibilidade: catalogo antigo com campos simples.
        $releases = @([pscustomobject]@{ Version = [string]$ComponentDef.DriverVersion; SourceUrl = [string]$ComponentDef.SourceUrl; ArchiveName = [string]$ComponentDef.ArchiveName })
    }
    $primaryVersion = if ($releases.Count -gt 0) { [string]$releases[0].Version } else { '' }

    if ([bool]$State.DryRun) {
        $plan = ($releases | ForEach-Object { [string]$_.Version }) -join ' -> '
        Write-Log ("DryRun: planejado instalar {0} (primaria; fallback: {1}); hash validado quando disponivel; tuning Adrenalin reversivel apos instalacao." -f $displayName, $plan)
        return [ordered]@{ status = 'planned'; dryRun = $true; releases = @($releases | ForEach-Object { [string]$_.Version }) }
    }

    if (-not (Test-BootstrapAmdGpuPresent)) {
        $message = ("{0} ignorado: nenhuma GPU AMD/Radeon detectada neste host." -f $displayName)
        Write-Log $message 'WARN'
        Register-BootstrapComponentSkip -State $State -ComponentName $componentName -Reason 'hardware-mismatch' -Message $message -Action 'skip-non-amd-host'
        return [ordered]@{ status = 'skipped'; reason = 'no-amd-gpu' }
    }

    $marker = Get-BootstrapDriverMarkerPath -ComponentName $componentName
    if (Test-Path $marker) {
        $installedVersion = (Get-Content -Path $marker -ErrorAction SilentlyContinue | Select-Object -First 1)
        Write-Log ("{0} ja instalado anteriormente (marcador presente; versao {1})." -f $displayName, $installedVersion)
        return [ordered]@{ status = 'healthy'; version = $installedVersion }
    }

    if (-not (Test-IsAdmin)) {
        $message = ("{0} requer PowerShell elevado para instalar driver de GPU. Bloqueado sem aplicar mudancas." -f $displayName)
        Write-Log $message 'WARN'
        Register-BootstrapComponentSkip -State $State -ComponentName $componentName -Reason 'admin-required' -Message $message -Action 'rerun-elevated'
        return [ordered]@{ status = 'blocked'; requiresAdmin = $true }
    }

    $sevenZip = Get-BootstrapSevenZipExe
    if (-not $sevenZip) {
        throw ("{0}: 7-Zip (7z.exe) nao encontrado. Instale o componente 'sevenzip' antes de prosseguir." -f $displayName)
    }

    $downloadDir = Join-Path (Get-BootstrapDataRoot) 'downloads'
    if (-not (Test-Path $downloadDir)) { $null = New-Item -Path $downloadDir -ItemType Directory -Force }

    $attempts = New-Object System.Collections.Generic.List[string]
    $success = $null
    foreach ($release in $releases) {
        $result = Install-BootstrapAmdDriverRelease -State $State -Release $release -SevenZip $sevenZip -DownloadDir $downloadDir -DisplayName $displayName
        if ($result.Ok) { $success = $result; break }
        $attempts.Add(("v{0}: {1}" -f $result.Version, $result.Reason)) | Out-Null
        Write-Log ("{0} v{1} falhou ({2}); tentando proxima versao se houver." -f $displayName, $result.Version, $result.Reason) 'WARN'
    }

    if (-not $success) {
        throw ("{0}: nenhuma versao instalou. Tentativas: {1}" -f $displayName, ($attempts -join ' | '))
    }

    Register-BootstrapChange -State $State -Type Package -Target $displayName -OldValue $null -NewValue ([string]$success.Version) -Operation 'install-amd-hybrid-driver' -Component $componentName
    Set-Content -Path $marker -Value ([string]$success.Version) -Encoding ASCII

    if ([bool]$success.RebootPending) {
        Write-Log ("{0} v{1} instalado; reinicializacao pendente." -f $displayName, $success.Version) 'WARN'
    }
    if ($attempts.Count -gt 0) {
        Write-Log ("{0}: usada versao de fallback v{1} (primaria v{2} indisponivel)." -f $displayName, $success.Version, $primaryVersion) 'WARN'
    }

    $tuning = Optimize-BootstrapAmdNebulaDriver -State $State -ComponentDef $ComponentDef

    return [ordered]@{ status = 'installed'; version = [string]$success.Version; usedFallback = ($attempts.Count -gt 0); rebootPending = [bool]$success.RebootPending; tuningApplied = [bool]$tuning.applied; setup = [string]$success.Setup }
}

function Get-BootstrapDriverMarkerPath {
    param([Parameter(Mandatory = $true)][string]$ComponentName)

    $dir = Join-Path (Get-BootstrapDataRoot) 'driver-markers'
    if (-not (Test-Path $dir)) { $null = New-Item -Path $dir -ItemType Directory -Force }
    return (Join-Path $dir ($ComponentName + '.installed'))
}

function Install-BootstrapSteamDeckZipDriverComponent {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$ComponentDef
    )

    $componentName = [string]$ComponentDef.Name
    $displayName = [string]$ComponentDef.DisplayName
    if ([string]::IsNullOrWhiteSpace($displayName)) { $displayName = $componentName }
    $sourceUrl = [string]$ComponentDef.SourceUrl
    $archiveName = [string]$ComponentDef.ArchiveName

    if ([bool]$State.DryRun) {
        Write-Log ("DryRun: planejado baixar e instalar driver {0} de {1} via pnputil (fallback Setup.exe)." -f $displayName, $sourceUrl)
        return [ordered]@{ status = 'planned'; dryRun = $true; sourceUrl = $sourceUrl }
    }

    $marker = Get-BootstrapDriverMarkerPath -ComponentName $componentName
    if (Test-Path $marker) {
        Write-Log ("{0} ja instalado anteriormente (marcador presente)." -f $displayName)
        return [ordered]@{ status = 'healthy'; marker = $marker }
    }

    if (-not (Test-IsAdmin)) {
        $message = ("{0} requer PowerShell elevado para instalar driver. Bloqueado sem aplicar mudancas." -f $displayName)
        Write-Log $message 'WARN'
        Register-BootstrapComponentSkip -State $State -ComponentName $componentName -Reason 'admin-required' -Message $message -Action 'rerun-elevated'
        return [ordered]@{ status = 'blocked'; requiresAdmin = $true }
    }

    if ([string]::IsNullOrWhiteSpace($sourceUrl) -or [string]::IsNullOrWhiteSpace($archiveName)) {
        throw ("{0}: SourceUrl/ArchiveName ausentes no catalogo." -f $displayName)
    }

    $downloadDir = Join-Path (Get-BootstrapDataRoot) 'downloads'
    if (-not (Test-Path $downloadDir)) { $null = New-Item -Path $downloadDir -ItemType Directory -Force }
    $archivePath = Join-Path $downloadDir $archiveName

    Write-Log ("Baixando driver {0}: {1}" -f $displayName, $sourceUrl)
    Invoke-WebRequestWithRetry -Uri $sourceUrl -OutFile $archivePath -OperationName $displayName
    Unblock-File -Path $archivePath -ErrorAction SilentlyContinue

    $extractDir = Join-Path $downloadDir ([System.IO.Path]::GetFileNameWithoutExtension($archiveName))
    if (Test-Path $extractDir) { Remove-Item -Path $extractDir -Recurse -Force -ErrorAction SilentlyContinue }
    $null = New-Item -Path $extractDir -ItemType Directory -Force

    Write-Log ("Extraindo {0}..." -f $archiveName)
    try {
        Expand-Archive -Path $archivePath -DestinationPath $extractDir -Force
    } catch {
        throw ("Falha ao extrair {0}: {1}" -f $archiveName, $_.Exception.Message)
    }

    $infs = @(Get-ChildItem -Path $extractDir -Filter '*.inf' -Recurse -ErrorAction SilentlyContinue)
    $method = ''
    $exit = -1
    if ($infs.Count -gt 0) {
        $method = 'pnputil'
        $pnputil = Join-Path $env:SystemRoot 'System32\pnputil.exe'
        $wildcard = Join-Path $extractDir '*.inf'
        Write-Log ("Instalando {0} pacote(s) INF de {1} via pnputil." -f $infs.Count, $displayName)
        $exit = Invoke-NativeWithLog -Exe $pnputil -Args @('/add-driver', $wildcard, '/subdirs', '/install') -TimeoutMs 600000
    } else {
        $method = 'setup'
        $setup = Get-ChildItem -Path $extractDir -Include 'Setup.exe', 'Install.exe' -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
        if (-not $setup) {
            $message = ("{0}: nenhum .inf nem Setup.exe encontrado em {1}; driver nao instalado." -f $displayName, $extractDir)
            Write-Log $message 'WARN'
            Register-BootstrapComponentSkip -State $State -ComponentName $componentName -Reason 'driver-payload-unrecognized' -Message $message -Action 'inspect-driver-package'
            return [ordered]@{ status = 'warning'; reason = 'no-inf-or-setup' }
        }
        Write-Log ("Instalando {0} via {1} (silent /s)." -f $displayName, $setup.Name)
        $exit = Invoke-NativeWithLog -Exe $setup.FullName -Args @('/s') -TimeoutMs 900000
    }

    # 0 = sucesso; 3010/1641 = sucesso com reboot pendente/iniciado.
    if ($exit -notin @(0, 3010, 1641)) {
        $message = ("{0} nao instalou de forma limpa ({1} exit={2}); marcado como nao-bloqueante para revisao." -f $displayName, $method, $exit)
        Write-Log $message 'WARN'
        Register-BootstrapComponentSkip -State $State -ComponentName $componentName -Reason 'driver-install-incomplete' -Message $message -Action 'rerun-or-install-manually'
        return [ordered]@{ status = 'warning'; method = $method; exit = $exit }
    }

    $rebootPending = ($exit -in @(3010, 1641))
    if ($rebootPending) {
        Write-Log ("{0} instalado; reinicializacao pendente (exit {1})." -f $displayName, $exit) 'WARN'
    }

    Set-Content -Path $marker -Value ((Get-Date).ToString('o')) -Encoding ASCII
    Register-BootstrapChange -State $State -Type Package -Target $displayName -OldValue $null -NewValue $sourceUrl -Operation 'install-steamdeck-zip-driver' -Component $componentName
    return [ordered]@{ status = 'installed'; method = $method; rebootPending = $rebootPending }
}

function Ensure-WslUi {
    param([Parameter(Mandatory = $true)][string]$WingetPath)

    $id = 'OctasoftLtd.WSLUI'
    $name = 'WSL UI'
    if (Test-WingetPackageInstalled -WingetPath $WingetPath -Id $id) {
        Write-Log "$name já instalado (winget)."
        return
    }

    if (-not (Test-IsAdmin)) {
        Write-Log "$name requer privilégios de administrador (e dependências). Pulando instalação." 'WARN'
        return
    }

    $null = Ensure-WindowsOptionalFeatureEnabled -FeatureName 'Microsoft-Windows-Subsystem-Linux' -DisplayName 'Microsoft-Windows-Subsystem-Linux (WSL)'
    Ensure-WingetPackage -WingetPath $WingetPath -Id 'Microsoft.EdgeWebView2Runtime' -DisplayName 'Microsoft Edge WebView2 Runtime'

    try {
        Ensure-WingetPackage -WingetPath $WingetPath -Id $id -DisplayName $name -PreferUserScope $false
    } catch {
        Write-Log ("Falha ao instalar $name via winget. Verifique WSL/WebView2 e privilégios. " + $_.Exception.Message) 'WARN'
    }
}

function Get-Winget {
    $cmd = Get-Command winget -ErrorAction SilentlyContinue
    if ($cmd) { return $cmd.Source }
    $candidate = Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\winget.exe'
    if (Test-Path $candidate) { return $candidate }
    $windowsAppsRoot = Join-Path $env:ProgramFiles 'WindowsApps'
    if (Test-Path $windowsAppsRoot) {
        $packaged = Get-ChildItem -Path $windowsAppsRoot -Filter 'winget.exe' -Recurse -ErrorAction SilentlyContinue |
            Where-Object { $_.FullName -match 'Microsoft\.DesktopAppInstaller_' } |
            Sort-Object FullName -Descending |
            Select-Object -First 1
        if ($packaged) { return $packaged.FullName }
    }
    return $null
}

function Install-BootstrapAppInstaller {
    $downloadUrl = 'https://aka.ms/getwinget'
    $targetDir = Join-Path (Get-BootstrapDataRoot) 'downloads'
    if (-not (Test-Path $targetDir)) {
        New-Item -Path $targetDir -ItemType Directory -Force | Out-Null
    }

    $bundlePath = Join-Path $targetDir 'Microsoft.DesktopAppInstaller.msixbundle'
    Write-Log "winget ausente. Baixando App Installer oficial: $downloadUrl"
    try {
        Invoke-WebRequest -Uri $downloadUrl -OutFile $bundlePath -UseBasicParsing -ErrorAction Stop
        Unblock-File -Path $bundlePath -ErrorAction SilentlyContinue
        Add-AppxPackage -Path $bundlePath -ErrorAction Stop
        Refresh-SessionPath
    } catch {
        throw "Falha ao instalar App Installer/winget automaticamente. Instale Microsoft.DesktopAppInstaller pela Microsoft Store ou baixe $downloadUrl. Erro: $($_.Exception.Message)"
    }

    $winget = Get-Winget
    if (-not $winget) {
        throw 'App Installer foi instalado, mas winget ainda nao apareceu nesta sessao. Feche e reabra o terminal/Explorer ou reinicie a sessao.'
    }
    return $winget
}

function Ensure-Winget {
    $winget = Get-Winget
    if (-not $winget) {
        $appInstaller = Get-BootstrapAppInstallerPackage

        if ($appInstaller) {
            Write-Log 'App Installer presente, mas winget nao esta no PATH. Tentando localizar pacote e atualizar sessao.' 'WARN'
            Refresh-SessionPath
            $winget = Get-Winget
            if (-not $winget) {
                throw 'winget nao esta acessivel, embora o App Installer esteja presente. Feche e reabra o terminal/Explorer, faca logoff ou reinicie a sessao e tente novamente.'
            }
        } else {
            $winget = Install-BootstrapAppInstaller
        }
    }
    $version = & $winget --version
    Write-Log "winget: $version"
    return $winget
}

function Test-WingetProbePathsOnDisk {
    param([string[]]$ProbePaths)
    if (-not $ProbePaths -or $ProbePaths.Count -eq 0) { return $false }
    foreach ($probe in $ProbePaths) {
        if ([string]::IsNullOrWhiteSpace($probe)) { continue }
        $expanded = ConvertTo-BootstrapExpandedPath -Path ([string]$probe)
        if ([string]::IsNullOrWhiteSpace($expanded)) { continue }
        # Suportar globs simples (ex: "...\jdk-17*\bin\java.exe").
        if ($expanded -match '[\*\?]') {
            $matches = @(Get-ChildItem -Path $expanded -ErrorAction SilentlyContinue)
            if ($matches.Count -gt 0) { return $true }
        } elseif (Test-Path -LiteralPath $expanded) {
            return $true
        }
    }
    return $false
}

function Test-BootstrapWingetPortableArtifact {
    # Fallback para pacotes winget instalados como "portable"/zip: ficam em
    # %LOCALAPPDATA%\Microsoft\WinGet\Packages\<Id>_<source>\... e nao nos ProbePaths padrao
    # (Program Files), gerando falso "ghost install". Procura qualquer .exe sob a pasta do pacote.
    param([string]$Id)

    if ([string]::IsNullOrWhiteSpace($Id) -or [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) { return $false }
    $root = Join-Path $env:LOCALAPPDATA 'Microsoft\WinGet\Packages'
    if (-not (Test-Path -LiteralPath $root)) { return $false }
    foreach ($dir in @(Get-ChildItem -Path $root -Directory -Filter ("{0}_*" -f $Id) -ErrorAction SilentlyContinue)) {
        $exe = @(Get-ChildItem -Path $dir.FullName -Recurse -File -Filter '*.exe' -ErrorAction SilentlyContinue | Select-Object -First 1)
        if ($exe.Count -gt 0) { return $true }
    }
    return $false
}

function ConvertTo-BootstrapArtifactComparableText {
    param([AllowNull()][string]$Value)

    if ([string]::IsNullOrWhiteSpace($Value)) { return '' }
    return [regex]::Replace(([string]$Value).ToLowerInvariant(), '[^a-z0-9]+', '')
}

function Get-BootstrapRegistryArtifactSearchTerms {
    param([string]$Id)

    if ([string]::IsNullOrWhiteSpace($Id)) { return @() }
    $ignored = @{
        app = $true
        com = $true
        desktop = $true
        inc = $true
        installer = $true
        llc = $true
        ltd = $true
        microsoft = $true
        net = $true
        org = $true
        setup = $true
        team = $true
        windows = $true
    }
    $terms = New-Object System.Collections.Generic.List[string]
    foreach ($part in @(([string]$Id) -split '[\.\-_\s]+')) {
        $term = ConvertTo-BootstrapArtifactComparableText -Value $part
        if ($term.Length -lt 3) { continue }
        if ($ignored.ContainsKey($term)) { continue }
        if (-not $terms.Contains($term)) { $terms.Add($term) }
    }
    return @($terms.ToArray())
}

function ConvertFrom-BootstrapRegistryExecutableReference {
    param([AllowNull()][string]$Value)

    if ([string]::IsNullOrWhiteSpace($Value)) { return '' }
    $text = ([string]$Value).Trim()
    if ($text -match '^\s*"([^"]+?\.exe)"') { return [string]$matches[1] }
    if ($text -match '^\s*([^,"]+?\.exe)(?:,.*)?\s*$') { return ([string]$matches[1]).Trim() }
    if ($text -match '([A-Za-z]:\\[^,"]+?\.exe)') { return ([string]$matches[1]).Trim() }
    return ''
}

function Test-BootstrapRegistryArtifactExecutableName {
    param([AllowNull()][string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    $leaf = Split-Path -Path ([string]$Path) -Leaf
    if ([string]::IsNullOrWhiteSpace($leaf)) { return $false }
    return ($leaf -notmatch '(?i)^(unins\d*|uninstall|setup|install|installer|update|updater|elevate|elevator|vc_redist|vcredist|dotnet).*\.exe$')
}

function Test-BootstrapRegistryArtifactPathMatchesTerms {
    param(
        [AllowNull()][string]$Path,
        [string[]]$Terms = @()
    )

    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    $text = ConvertTo-BootstrapArtifactComparableText -Value $Path
    foreach ($term in @(Get-BootstrapNonEmptyStringArray -Values $Terms)) {
        if ($text.Contains($term)) { return $true }
    }
    return $false
}

function Test-BootstrapRegistryArtifactPath {
    param(
        [AllowNull()][string]$Path,
        [string[]]$Terms = @()
    )

    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    $expanded = ConvertTo-BootstrapExpandedPath -Path ([string]$Path)
    if ([string]::IsNullOrWhiteSpace($expanded)) { return $false }
    $expanded = $expanded.Trim('"')

    $item = $null
    try { $item = Get-Item -LiteralPath $expanded -ErrorAction SilentlyContinue } catch { $item = $null }
    if (-not $item) { return $false }

    if (-not $item.PSIsContainer) {
        return ((Test-BootstrapRegistryArtifactExecutableName -Path $item.FullName) -and (Test-BootstrapRegistryArtifactPathMatchesTerms -Path $item.FullName -Terms $Terms))
    }

    $executables = @()
    try {
        $executables = @(Get-ChildItem -LiteralPath $item.FullName -Recurse -File -Filter '*.exe' -ErrorAction SilentlyContinue | Select-Object -First 50)
    } catch {
        $executables = @()
    }
    foreach ($exe in @($executables)) {
        if ((Test-BootstrapRegistryArtifactExecutableName -Path $exe.FullName) -and (Test-BootstrapRegistryArtifactPathMatchesTerms -Path $exe.FullName -Terms $Terms)) {
            return $true
        }
    }
    return $false
}

function Test-BootstrapRegistryArtifactRows {
    param(
        [string]$Id,
        [object[]]$Rows = @()
    )

    $terms = @(Get-BootstrapRegistryArtifactSearchTerms -Id $Id)
    if ($terms.Count -eq 0) { return $false }

    foreach ($row in @($Rows)) {
        if ($null -eq $row) { continue }
        $textFields = @(
            (Get-BootstrapHintField -Hint $row -Name 'DisplayName')
            (Get-BootstrapHintField -Hint $row -Name 'Publisher')
            (Get-BootstrapHintField -Hint $row -Name 'InstallLocation')
            (Get-BootstrapHintField -Hint $row -Name 'DisplayIcon')
            (Get-BootstrapHintField -Hint $row -Name 'URLInfoAbout')
            (Get-BootstrapHintField -Hint $row -Name 'PSChildName')
            (Get-BootstrapHintField -Hint $row -Name 'PSPath')
        )
        $rowText = ConvertTo-BootstrapArtifactComparableText -Value (($textFields | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }) -join ' ')
        $rowMatchesId = $false
        foreach ($term in @($terms)) {
            if ($rowText.Contains($term)) { $rowMatchesId = $true; break }
        }
        if (-not $rowMatchesId) { continue }

        $iconPath = ConvertFrom-BootstrapRegistryExecutableReference -Value (Get-BootstrapHintField -Hint $row -Name 'DisplayIcon')
        if ((Test-BootstrapRegistryArtifactPath -Path $iconPath -Terms $terms)) { return $true }

        $installLocation = Get-BootstrapHintField -Hint $row -Name 'InstallLocation'
        if ((Test-BootstrapRegistryArtifactPath -Path $installLocation -Terms $terms)) { return $true }
    }
    return $false
}

function Get-BootstrapWingetRegistryArtifactRows {
    $roots = @(
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*'
        'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*'
        'HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($entry in @(Get-ItemProperty -Path $roots -ErrorAction SilentlyContinue)) {
        $rows.Add([ordered]@{
            DisplayName = (Get-BootstrapHintField -Hint $entry -Name 'DisplayName')
            Publisher = (Get-BootstrapHintField -Hint $entry -Name 'Publisher')
            InstallLocation = (Get-BootstrapHintField -Hint $entry -Name 'InstallLocation')
            DisplayIcon = (Get-BootstrapHintField -Hint $entry -Name 'DisplayIcon')
            URLInfoAbout = (Get-BootstrapHintField -Hint $entry -Name 'URLInfoAbout')
            PSChildName = (Get-BootstrapHintField -Hint $entry -Name 'PSChildName')
            PSPath = (Get-BootstrapHintField -Hint $entry -Name 'PSPath')
        })
    }
    return @($rows.ToArray())
}

function Test-BootstrapWingetRegistryArtifact {
    param([string]$Id)

    if ([string]::IsNullOrWhiteSpace($Id)) { return $false }
    $rows = @()
    try { $rows = @(Get-BootstrapWingetRegistryArtifactRows) } catch { $rows = @() }
    if ($rows.Count -eq 0) { return $false }
    return (Test-BootstrapRegistryArtifactRows -Id $Id -Rows $rows)
}

function Get-BootstrapItemStatusInfo {
    # Modelo unico de 5 estados usado por CLI e UI. Ordem = legenda.
    return @(
        [ordered]@{ status = 'error';                  color = 'Red';    label = 'erro' }
        [ordered]@{ status = 'not-installed';          color = 'White';  label = 'nao instalado' }
        [ordered]@{ status = 'installed-unconfigured'; color = 'Yellow'; label = 'instalado, nao configurado' }
        [ordered]@{ status = 'configured';             color = 'Blue';   label = 'instalado e configurado' }
        [ordered]@{ status = 'optimized-tested';       color = 'Green';  label = 'instalado, configurado, otimizado e testado' }
    )
}

function Get-BootstrapItemStatusColor {
    param([Parameter(Mandatory = $true)][string]$Status)
    foreach ($info in (Get-BootstrapItemStatusInfo)) {
        if ([string]$info.status -eq $Status) { return [string]$info.color }
    }
    return 'Gray'
}

function Get-BootstrapItemStatusRank {
    # Ordena por "quao avancado" o estado e (erro fica fora desta escala).
    param([Parameter(Mandatory = $true)][AllowEmptyString()][string]$Status)
    switch ($Status) {
        'not-installed'          { return 0 }
        'installed-unconfigured' { return 1 }
        'configured'             { return 2 }
        'optimized-tested'       { return 3 }
        default                  { return -1 }
    }
}

function Get-BootstrapItemStatusCachePath {
    return (Join-Path (Get-BootstrapDataRoot) 'item-status.json')
}

function Read-BootstrapItemStatusCache {
    $path = Get-BootstrapItemStatusCachePath
    if (-not (Test-Path -LiteralPath $path)) { return @{} }
    try {
        $data = ConvertTo-BootstrapHashtable -InputObject (Read-BootstrapJsonFile -Path $path)
        if (-not ($data -is [hashtable])) { return @{} }
        return $data
    } catch {
        return @{}
    }
}

function Set-BootstrapItemStatus {
    # Persiste o estado conhecido de um item (chamado pelos fluxos de install/configure/validate/optimize).
    param(
        [Parameter(Mandatory = $true)][ValidateSet('app', 'config', 'tool')][string]$Kind,
        [Parameter(Mandatory = $true)][string]$Id,
        [Parameter(Mandatory = $true)][ValidateSet('error', 'not-installed', 'installed-unconfigured', 'configured', 'optimized-tested')][string]$Status
    )
    if ([string]::IsNullOrWhiteSpace($Id)) { return }
    $cache = Read-BootstrapItemStatusCache
    $key = "{0}:{1}" -f $Kind, $Id
    $cache[$key] = [ordered]@{ status = $Status; updatedAt = (Get-Date).ToString('o') }
    try { Write-BootstrapJsonFile -Path (Get-BootstrapItemStatusCachePath) -Value $cache } catch { }
}

function Get-BootstrapItemStatus {
    # Resolve um dos 5 estados combinando probe barato (ao vivo) + estado persistido (cache).
    # Nunca roda doctors/comandos externos pesados.
    param(
        [Parameter(Mandatory = $true)][ValidateSet('app', 'config', 'tool')][string]$Kind,
        [Parameter(Mandatory = $true)][string]$Id,
        [string[]]$ProbePaths = @(),
        [string[]]$CommandNames = @(),
        [string]$WingetId = '',
        [switch]$ErrorFlag,
        [hashtable]$Cache
    )

    if (-not $Cache) { $Cache = Read-BootstrapItemStatusCache }
    $key = "{0}:{1}" -f $Kind, $Id
    $cachedStatus = ''
    if ($Cache.ContainsKey($key)) {
        $entry = ConvertTo-BootstrapHashtable -InputObject $Cache[$key]
        if ($entry.ContainsKey('status')) { $cachedStatus = [string]$entry['status'] }
    }

    # Erro tem prioridade (vale mesmo se o binario sumiu).
    if ($ErrorFlag -or $cachedStatus -eq 'error') { return 'error' }

    # Probe de instalacao ao vivo.
    $installed = $false
    if (@($ProbePaths).Count -gt 0 -and (Test-WingetProbePathsOnDisk -ProbePaths @($ProbePaths))) { $installed = $true }
    if (-not $installed) {
        foreach ($cmd in @($CommandNames)) {
            if (-not [string]::IsNullOrWhiteSpace([string]$cmd) -and (Get-Command -Name ([string]$cmd) -ErrorAction SilentlyContinue)) { $installed = $true; break }
        }
    }
    # Fallback barato p/ pacotes winget instalados como portable/zip (ex.: OBS) fora dos ProbePaths.
    if (-not $installed -and -not [string]::IsNullOrWhiteSpace($WingetId) -and (Test-BootstrapWingetPortableArtifact -Id $WingetId)) {
        $installed = $true
    }

    if (-not $installed) { return 'not-installed' }

    # Instalado: nunca regredir abaixo de "installed-unconfigured"; usar o cache para subir.
    $cachedRank = Get-BootstrapItemStatusRank -Status $cachedStatus
    if ($cachedRank -ge (Get-BootstrapItemStatusRank -Status 'configured')) { return $cachedStatus }
    return 'installed-unconfigured'
}

function Get-BootstrapComponentStatusMap {
    # Mapa name->status (5 estados) recomputado ao vivo para todos os componentes, com cache fresco
    # e deteccao enriquecida (ProbePaths + winget-portable). Usado pelo "Atualizar status" da UI.
    $cache = Read-BootstrapItemStatusCache
    $catalog = Get-BootstrapComponentCatalog
    $map = [ordered]@{}
    foreach ($name in @($catalog.Keys)) {
        $def = $catalog[$name]
        $probe = @()
        if ($def.PSObject.Properties.Name -contains 'ProbePaths') { $probe = @($def.ProbePaths) }
        $wid = if ($def.PSObject.Properties.Name -contains 'Id') { [string]$def.Id } else { '' }
        $map[[string]$name] = Get-BootstrapItemStatus -Kind 'app' -Id ([string]$def.Name) -ProbePaths $probe -WingetId $wid -Cache $cache
    }
    return $map
}

function Test-BootstrapAppxPackageInstalled {
    param([string[]]$Names = @())

    $packageNames = @(Get-BootstrapNonEmptyStringArray -Values $Names)
    if ($packageNames.Count -eq 0) { return $false }
    if (-not (Get-Command -Name Get-AppxPackage -ErrorAction SilentlyContinue)) { return $false }

    foreach ($name in @($packageNames)) {
        try {
            $pkg = @(Get-AppxPackage -Name $name -ErrorAction SilentlyContinue | Select-Object -First 1)
            if ($pkg.Count -gt 0) { return $true }
            if (Test-IsAdmin) {
                $pkg = @(Get-AppxPackage -AllUsers -Name $name -ErrorAction SilentlyContinue | Select-Object -First 1)
                if ($pkg.Count -gt 0) { return $true }
            }
        } catch {
        }
    }
    return $false
}

function Test-BootstrapPackageArtifactsPresent {
    param(
        [string[]]$ProbePaths = @(),
        [string[]]$AppxPackageNames = @(),
        [string]$WingetId = ''
    )

    if (@($AppxPackageNames).Count -gt 0 -and (Test-BootstrapAppxPackageInstalled -Names $AppxPackageNames)) {
        return $true
    }
    if (@($ProbePaths).Count -gt 0 -and (Test-WingetProbePathsOnDisk -ProbePaths $ProbePaths)) {
        return $true
    }
    if (-not [string]::IsNullOrWhiteSpace($WingetId) -and (Test-BootstrapWingetPortableArtifact -Id $WingetId)) {
        return $true
    }
    if (-not [string]::IsNullOrWhiteSpace($WingetId) -and (Test-BootstrapWingetRegistryArtifact -Id $WingetId)) {
        return $true
    }
    return $false
}

function Get-BootstrapHintField {
    # Acesso defensivo a campos em hashtable, OrderedDictionary, ou PSCustomObject.
    # Get-ItemProperty retorna PSCustomObject; testes podem passar [ordered]@{...}.
    param(
        [Parameter(Mandatory = $true)]$Hint,
        [Parameter(Mandatory = $true)][string]$Name
    )
    if ($null -eq $Hint) { return '' }
    if ($Hint -is [System.Collections.IDictionary]) {
        if ($Hint.Contains($Name)) { return [string]$Hint[$Name] }
        return ''
    }
    try {
        $props = $Hint.PSObject.Properties
        if ($props -and ($props.Name -contains $Name)) {
            return [string]$Hint.$Name
        }
    } catch { }
    return ''
}

function Invoke-BootstrapGhostPackageRecovery {
    <#
    .SYNOPSIS
        Limpa estado fantasma de um pacote (registry diz instalado, disco vazio/stub) por niveis:
          1. winget uninstall --purge (com --force se necessario)
          2. Fallback NSIS: executa UninstallString do registro com /S quando winget falha
          3. Limpa chave Uninstall orfa em WOW6432Node se o resto sobreviveu
        Retorna $true se acreditar ter limpado o ghost.
    .PARAMETER UninstallStringHints
        Lista opcional de objetos do registro (Hive/KeyPath/UninstallString/QuietUninstallString)
        obtidos previamente. Quando vazia, o helper opera so via winget.
    #>
    param(
        [Parameter(Mandatory = $true)][string]$WingetPath,
        [Parameter(Mandatory = $true)][string]$Id,
        [string]$DisplayName = $Id,
        [object[]]$UninstallStringHints = @(),
        [hashtable]$State = $null,
        [string]$ComponentName = ''
    )

    $cleaned = $false

    # 1. winget uninstall (com retry/backoff)
    $uninstallArgs = @('uninstall', '-e', '--id', $Id, '--purge', '--disable-interactivity')
    try {
        $exit = Invoke-NativeWithRetry -Exe $WingetPath -Args $uninstallArgs -OperationName ("Ghost-recovery: winget uninstall {0}" -f $DisplayName) -MaxAttempts 2 -InitialDelaySeconds 2 -SoftSuccessExitCodes $script:WingetUninstallSoftSuccessExitCodes
        if ($exit -eq 0) { $cleaned = $true }
    } catch {
        Write-Log ("Ghost-recovery: excecao em winget uninstall de {0}: {1}" -f $DisplayName, $_.Exception.Message) 'WARN'
    }

    if (-not $cleaned) {
        $forceArgs = @('uninstall', '-e', '--id', $Id, '--purge', '--force', '--disable-interactivity')
        try {
            $exit = Invoke-NativeWithRetry -Exe $WingetPath -Args $forceArgs -OperationName ("Ghost-recovery: winget uninstall --force {0}" -f $DisplayName) -MaxAttempts 2 -InitialDelaySeconds 2 -SoftSuccessExitCodes $script:WingetUninstallSoftSuccessExitCodes
            if ($exit -eq 0) { $cleaned = $true }
        } catch {
            Write-Log ("Ghost-recovery: excecao em winget --force de {0}: {1}" -f $DisplayName, $_.Exception.Message) 'WARN'
        }
    }

    if (-not $cleaned) {
        $allVersionsArgs = @('uninstall', '-e', '--id', $Id, '--all-versions', '--purge', '--force', '--disable-interactivity')
        try {
            $exit = Invoke-NativeWithRetry -Exe $WingetPath -Args $allVersionsArgs -OperationName ("Ghost-recovery: winget uninstall --all-versions {0}" -f $DisplayName) -MaxAttempts 2 -InitialDelaySeconds 2 -SoftSuccessExitCodes $script:WingetUninstallSoftSuccessExitCodes
            if ($exit -eq 0) { $cleaned = $true }
        } catch {
            Write-Log ("Ghost-recovery: excecao em winget --all-versions de {0}: {1}" -f $DisplayName, $_.Exception.Message) 'WARN'
        }
    }

    # 2. Fallback NSIS: dispara UninstallString do registro com /S
    if (-not $cleaned -and $UninstallStringHints -and @($UninstallStringHints).Count -gt 0) {
        foreach ($hint in @($UninstallStringHints)) {
            # Hints podem vir como PSCustomObject (registry) ou OrderedDictionary/hashtable (testes).
            # Get-BootstrapHintField faz get defensivo nos dois formatos.
            $candidate = Get-BootstrapHintField -Hint $hint -Name 'QuietUninstallString'
            if ([string]::IsNullOrWhiteSpace($candidate)) {
                $candidate = Get-BootstrapHintField -Hint $hint -Name 'UninstallString'
            }
            if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
            # Extrai executavel e args do UninstallString (formato tipico: "C:\path\uninstall.exe" /Args ou "C:\path\uninstall.exe")
            $exePath = ''
            $extraArgs = @()
            if ($candidate -match '^\s*"([^"]+)"\s*(.*)$') {
                $exePath = $matches[1]
                $tail = $matches[2].Trim()
                if (-not [string]::IsNullOrWhiteSpace($tail)) { $extraArgs = @($tail -split '\s+') }
            } elseif ($candidate -match '^\s*(\S+)\s*(.*)$') {
                $exePath = $matches[1]
                $tail = $matches[2].Trim()
                if (-not [string]::IsNullOrWhiteSpace($tail)) { $extraArgs = @($tail -split '\s+') }
            }
            if ([string]::IsNullOrWhiteSpace($exePath) -or -not (Test-Path -LiteralPath $exePath)) {
                Write-Log ("Ghost-recovery: UninstallString do registro ({0}) aponta para {1} inexistente; pulando." -f $hint.Hive, $exePath) 'WARN'
                continue
            }
            if (@($extraArgs).Count -eq 0) { $extraArgs = @('/S') }  # NSIS silent
            try {
                Write-Log ("Ghost-recovery: invocando UninstallString NSIS para {0} ({1})..." -f $DisplayName, $hint.Hive)
                $exit = Invoke-NativeWithLog -Exe $exePath -Args $extraArgs
                if ($exit -eq 0) {
                    $cleaned = $true
                    break
                } else {
                    Write-Log ("Ghost-recovery: UninstallString NSIS retornou exit={0} para {1}." -f $exit, $DisplayName) 'WARN'
                }
            } catch {
                Write-Log ("Ghost-recovery: excecao em UninstallString de {0}: {1}" -f $DisplayName, $_.Exception.Message) 'WARN'
            }
        }
    }

    # 3. Limpeza de chave Uninstall orfa que tenha sobrevivido (registrando para rollback).
    if ($UninstallStringHints -and @($UninstallStringHints).Count -gt 0) {
        foreach ($hint in @($UninstallStringHints)) {
            $keyPath = Get-BootstrapHintField -Hint $hint -Name 'KeyPath'
            if ([string]::IsNullOrWhiteSpace($keyPath)) { continue }
            if (-not (Test-Path -LiteralPath $keyPath)) { continue }
            $hive = Get-BootstrapHintField -Hint $hint -Name 'Hive'
            try {
                if ($State) {
                    Register-BootstrapChange -State $State -Type 'Registry' -Target $keyPath -Name '__key__' -OldValue '__present__' -Operation 'remove-ghost-uninstall-key' -RollbackAction 'manual-review' -Reversible 'manual' -Component $ComponentName
                }
                Remove-Item -LiteralPath $keyPath -Recurse -Force -ErrorAction Stop
                Write-Log ("Ghost-recovery: chave Uninstall orfa removida em {0}: {1}" -f $hive, $keyPath)
                $cleaned = $true
            } catch {
                Write-Log ("Ghost-recovery: falha ao remover chave orfa {0}: {1}" -f $keyPath, $_.Exception.Message) 'WARN'
            }
        }
    }

    return $cleaned
}

function Ensure-WingetPackage {
    param(
        [Parameter(Mandatory = $true)][string]$WingetPath,
        [Parameter(Mandatory = $true)][string]$Id,
        [string]$DisplayName = $Id,
        [bool]$PreferUserScope = $true,
        [bool]$AllowFailureWhenNotAdmin = $false,
        [string[]]$ProbePaths = @(),
        [string[]]$AppxPackageNames = @(),
        [hashtable]$State = $null,
        [string]$ComponentName = '',
        [object[]]$UninstallStringHints = @()
    )

    # Curto-circuito: se ProbePaths apontam para binario real em disco, considerar instalado
    # sem invocar winget. Evita 100% dos retry-loops causados por reportes inconsistentes.
    $hasArtifactValidators = (($ProbePaths -and $ProbePaths.Count -gt 0) -or ($AppxPackageNames -and $AppxPackageNames.Count -gt 0))
    if ($hasArtifactValidators -and (Test-BootstrapPackageArtifactsPresent -ProbePaths $ProbePaths -AppxPackageNames $AppxPackageNames)) {
        Write-Log ("{0} ja instalado (artefato validado em disco/Appx)." -f $DisplayName)
        return
    }

    Write-Log ("winget: verificando instalacao de {0} (id={1})..." -f $DisplayName, $Id)
    $isInstalled = Test-WingetPackageInstalled -WingetPath $WingetPath -Id $Id
    Write-Log ("winget list: verificacao concluida para id={0}; jaInstalado={1}" -f $Id, $isInstalled)

    if ($isInstalled -and $hasArtifactValidators) {
        $diskVerified = Test-BootstrapPackageArtifactsPresent -ProbePaths $ProbePaths -AppxPackageNames $AppxPackageNames
        if (-not $diskVerified) {
            # Gate de blocklist: runtimes do sistema NUNCA devem ser desinstalados automaticamente
            # por um ProbePath errado. Se cair aqui para um Id da blocklist, registrar WARN claro
            # (incluindo qual ProbePath falhou) e tratar como instalado. Audit/Repair existem para
            # cenarios em que o runtime realmente esta quebrado.
            if ($script:WingetGhostRecoveryBlocklist -contains $Id) {
                $probeDesc = if ($ProbePaths -and $ProbePaths.Count -gt 0) { ($ProbePaths -join '; ') } else { '<vazio>' }
                Write-Log ("winget: {0} (id={1}) listado como instalado mas ProbePaths nao validaram em disco. Id esta no blocklist de runtimes criticos; NAO disparando ghost-recovery. ProbePaths verificados: {2}" -f $DisplayName, $Id, $probeDesc) 'WARN'
                Write-Log ("winget: tratando {0} como instalado. Use -Audit para diagnostico ou -Audit -Repair para reinstalacao supervisionada." -f $DisplayName) 'WARN'
                return
            }
            # Gate MSI-hostil: ghost-recovery faz uninstall+install de MSI em sequencia.
            # Se Windows tem PendingFileRenameOperations ou UpdateExeVolatile, msiexec trava
            # esperando lock que so libera com reboot. Abortar este componente com mensagem
            # acionavel em vez de pendurar 10min ate o timeout do Invoke-NativeWithLog.
            $msiBlockers = @(Get-BootstrapMsiHostilePendingRebootReasons)
            if ($msiBlockers.Count -gt 0) {
                $blockerList = ($msiBlockers -join ', ')
                $message = "Nao foi possivel reinstalar {0}: ghost entry presente e Windows requer reboot ({1}). Reinicie e execute novamente." -f $DisplayName, $blockerList
                Write-Log ("winget: {0} ghost detectada, mas Windows tem estado MSI-hostil ({1}); bloqueando reinstalacao para evitar hang. Reinicie o Windows e tente novamente." -f $DisplayName, $blockerList) 'WARN'
                throw (New-BootstrapBlockedException -Message $message -Kind 'pending-reboot-msi' -Action 'restart-required' -Reasons $msiBlockers)
            }

            Write-Log ("winget: {0} reportado como instalado, mas nenhum binario encontrado em disco; removendo registro fantasma e tentando reinstalacao..." -f $DisplayName) 'WARN'
            # Coleta hints de registry quando o caller nao passou explicitamente — permite que o
            # caminho generico se beneficie da varredura HKCU/HKLM/WOW6432Node + fallback NSIS.
            $hints = @($UninstallStringHints)
            if ($hints.Count -eq 0 -and $Id -eq 'Notepad++.Notepad++') {
                try { $hints = @(Get-BootstrapNotepadPlusPlusUninstallRegistry) } catch { $hints = @() }
            }
            $ghostRemoved = Invoke-BootstrapGhostPackageRecovery -WingetPath $WingetPath -Id $Id -DisplayName $DisplayName -UninstallStringHints $hints -State $State -ComponentName $ComponentName

            if ($ghostRemoved) {
                Write-Log ("winget: ghost entry removida com sucesso para {0}." -f $DisplayName)
                if (-not (Wait-BootstrapWingetMsiIdle -TimeoutSeconds 60 -HeartbeatSeconds 30)) {
                    $message = "Nao foi possivel reinstalar {0}: winget/msiexec continuou ocupado apos remover ghost entry. Feche instaladores pendentes ou reinicie o Windows." -f $DisplayName
                    throw (New-BootstrapBlockedException -Message $message -Kind 'winget-msi-busy' -Action 'restart-or-close-installers' -Reasons @('winget-msi-busy'))
                }
            } else {
                $message = "Nao foi possivel reinstalar {0}: winget lista instalado, mas o binario nao existe e a limpeza de ghost nao concluiu. Remova/repare o pacote manualmente e execute novamente." -f $DisplayName
                Write-Log ("winget: ghost de {0} nao foi limpo; bloqueando install para evitar estado parcial." -f $DisplayName) 'WARN'
                throw (New-BootstrapBlockedException -Message $message -Kind 'winget-ghost-unresolved' -Action 'manual-ghost-cleanup' -Reasons @('winget-ghost-unresolved', $Id))
            }
            $isInstalled = $false
        }
    }

    if ($isInstalled) {
        Write-Log "$DisplayName já instalado (winget)."
        return
    }

    if (-not [bool]$script:AllowPendingReboot) {
        $msiBlockers = @(Get-BootstrapMsiHostilePendingRebootReasons)
        if ($msiBlockers.Count -gt 0) {
            $blockerList = ($msiBlockers -join ', ')
            $message = "Nao foi possivel instalar {0}: Windows requer reboot antes de fluxos winget/MSI ({1}). Reinicie e execute novamente." -f $DisplayName, $blockerList
            Write-Log ("winget: {0} bloqueado antes de mutacao por reboot pendente hostil a MSI ({1})." -f $DisplayName, $blockerList) 'WARN'
            throw (New-BootstrapBlockedException -Message $message -Kind 'pending-reboot-msi' -Action 'restart-required' -Reasons $msiBlockers)
        }
    }

    Write-Log "Instalando $DisplayName via winget..."
    $commonArgsBase = @(
        'install',
        '-e',
        '--id', $Id,
        '--accept-source-agreements',
        '--accept-package-agreements',
        '--disable-interactivity'
    )
    $commonArgsSilent = @($commonArgsBase + @('--silent'))

    # Tentativas extras com backoff (Invoke-NativeWithRetry) para falhas transitórias de rede/Store.
    $wingetInstallMaxAttempts = 5
    $wingetInitialDelaySeconds = 2

    $exitCode = -1
    $softCodes = $script:WingetSoftSuccessExitCodes
    $isAdmin = Test-IsAdmin
    $isNonAdminSkippable = ($AllowFailureWhenNotAdmin -and (-not $isAdmin))
    $nonRetryableCodes = @($script:WingetNonRetryableInstallExitCodes)
    if ($isNonAdminSkippable) {
        $nonRetryableCodes += @(124, -1978335226)
    }
    # Timeout user-scope: 300s permite downloads legitimos (~300MB) sem matar processos travados em UAC,
    # que tipicamente nao emitem nenhum output e seriam detectaveis muito antes. Em machine scope o
    # timeout amplo (600s) cobre instalacoes MSI maiores.
    $wingetInstallTimeoutMs = if ($isNonAdminSkippable) { 300000 } else { 600000 }
    # Helper para produzir mensagem de skip apropriada ao codigo de saida (UAC/timeout vs. pacote
    # incompativel). exit=-1978335216 (NO_APPLICABLE_INSTALLER) = pacote nao tem instalador para este
    # escopo/arquitetura, nao tem nada a ver com privilegios.
    $resolveSkip = {
        param([int]$Code)
        if ($Code -eq -1978335216) {
            return [pscustomobject]@{
                Message = "$DisplayName nao tem instalador aplicavel para este sistema/escopo (winget exit=$Code, 0x8A150010). Pacote provavelmente exige machine-scope ou nao publica binario para esta arquitetura. Instale manualmente se necessario."
                Reason = 'no-applicable-installer'
                Action = 'install-manually-or-check-package-availability'
            }
        }
        return [pscustomobject]@{
            Message = "$DisplayName falhou em --scope user sem privilegios de administrador (exit=$Code). Nao tentando fallback machine para evitar UAC/winget preso. Execute elevado ou instale o pacote manualmente."
            Reason = 'non-admin-user-scope-failed'
            Action = 'rerun-elevated-or-install-manually'
        }
    }
    $handleMachineScopeWithoutAdmin = {
        param([int]$Code)
        if ($AllowFailureWhenNotAdmin) {
            $skip = & $resolveSkip $Code
            Write-Log $skip.Message 'WARN'
            Register-BootstrapComponentSkip -State $State -ComponentName $ComponentName -Reason $skip.Reason -Message $skip.Message -Action $skip.Action -PackageId $Id -DisplayName $DisplayName -ExitCode $Code
            return $true
        }
        $message = "$DisplayName requer machine-scope ou instalador sem --scope, mas esta execucao nao esta elevada (exit=$Code). Execute como Administrador ou instale manualmente."
        Write-Log $message 'WARN'
        throw (New-BootstrapBlockedException -Message $message -Kind 'winget-machine-scope-requires-admin' -Action 'rerun-elevated-or-install-manually' -Reasons @('not-admin', $Id))
    }
    $handlePackageNotFound = {
        param([int]$Code)
        if ($Code -ne -1978335212) { return $false }
        $message = "{0} indisponivel no winget para o criterio informado (id={1}, exit={2}, 0x8A150014). Verifique Id/source/arquitetura ou instale manualmente." -f $DisplayName, $Id, $Code
        if ($AllowFailureWhenNotAdmin) {
            Write-Log $message 'WARN'
            Register-BootstrapComponentSkip -State $State -ComponentName $ComponentName -Reason 'winget-package-not-found' -Message $message -Action 'check-winget-id-or-source' -PackageId $Id -DisplayName $DisplayName -ExitCode $Code
            return $true
        }
        Write-Log $message 'WARN'
        throw (New-BootstrapBlockedException -Message $message -Kind 'winget-package-not-found' -Action 'check-winget-id-or-source' -Reasons @('NO_APPLICATIONS_FOUND', $Id))
    }
    if ($PreferUserScope) {
        $exitCode = Invoke-NativeWithRetry -Exe $WingetPath -Args (@($commonArgsSilent) + @('--scope', 'user')) -OperationName "$DisplayName via winget --scope user --silent" -MaxAttempts $wingetInstallMaxAttempts -InitialDelaySeconds $wingetInitialDelaySeconds -TimeoutMs $wingetInstallTimeoutMs -SoftSuccessExitCodes $softCodes -NonRetryableExitCodes $nonRetryableCodes
        if (& $handlePackageNotFound $exitCode) { return }
        if ($exitCode -ne 0 -and $isNonAdminSkippable -and (($exitCode -eq 124) -or ($nonRetryableCodes -contains $exitCode))) {
            $skip = & $resolveSkip $exitCode
            Write-Log $skip.Message 'WARN'
            Register-BootstrapComponentSkip -State $State -ComponentName $ComponentName -Reason $skip.Reason -Message $skip.Message -Action $skip.Action -PackageId $Id -DisplayName $DisplayName -ExitCode $exitCode
            return
        }
        if ($exitCode -eq -1978335216) {
            # 0x8A150010 NO_APPLICABLE_INSTALLER e deterministico para o escopo: repetir user-scope
            # (silent ou nao) devolve o mesmo codigo. Pular retries user-scope e ir para sem --scope.
            Write-Log "$DisplayName nao publica instalador user-scope (exit=$exitCode, 0x8A150010); pulando retries user-scope." 'WARN'
        } elseif ($exitCode -ne 0) {
            Write-Log "Falha ao instalar $DisplayName com --scope user --silent (winget). Tentando novamente em modo nao-silent..." 'WARN'
            $exitCode = Invoke-NativeWithRetry -Exe $WingetPath -Args (@($commonArgsBase) + @('--scope', 'user')) -OperationName "$DisplayName via winget --scope user" -MaxAttempts $wingetInstallMaxAttempts -InitialDelaySeconds $wingetInitialDelaySeconds -TimeoutMs $wingetInstallTimeoutMs -SoftSuccessExitCodes $softCodes -NonRetryableExitCodes $nonRetryableCodes
            if (& $handlePackageNotFound $exitCode) { return }
        }
        if ($exitCode -ne 0 -and $isNonAdminSkippable) {
            $skip = & $resolveSkip $exitCode
            Write-Log $skip.Message 'WARN'
            Register-BootstrapComponentSkip -State $State -ComponentName $ComponentName -Reason $skip.Reason -Message $skip.Message -Action $skip.Action -PackageId $Id -DisplayName $DisplayName -ExitCode $exitCode
            return
        }
        if ($exitCode -ne 0 -and -not $isAdmin) {
            if (& $handleMachineScopeWithoutAdmin $exitCode) { return }
        }
        if ($exitCode -ne 0) {
            Write-Log "Falha ao instalar $DisplayName com --scope user (winget). Tentando novamente sem --scope..." 'WARN'
        }
    }
    if ($exitCode -ne 0) {
        if (-not $isAdmin) {
            if (& $handleMachineScopeWithoutAdmin $exitCode) { return }
        }
        $exitCode = Invoke-NativeWithRetry -Exe $WingetPath -Args $commonArgsSilent -OperationName "$DisplayName via winget --silent" -MaxAttempts $wingetInstallMaxAttempts -InitialDelaySeconds $wingetInitialDelaySeconds -TimeoutMs $wingetInstallTimeoutMs -SoftSuccessExitCodes $softCodes -NonRetryableExitCodes $nonRetryableCodes
        if (& $handlePackageNotFound $exitCode) { return }
        if ($exitCode -ne 0) {
            Write-Log "Falha ao instalar $DisplayName com --silent (winget). Tentando novamente em modo nao-silent..." 'WARN'
            $exitCode = Invoke-NativeWithRetry -Exe $WingetPath -Args $commonArgsBase -OperationName "$DisplayName via winget" -MaxAttempts $wingetInstallMaxAttempts -InitialDelaySeconds $wingetInitialDelaySeconds -TimeoutMs $wingetInstallTimeoutMs -SoftSuccessExitCodes $softCodes -NonRetryableExitCodes $nonRetryableCodes
            if (& $handlePackageNotFound $exitCode) { return }
        }
    }
    if ($exitCode -ne 0) {
        if ($AllowFailureWhenNotAdmin -and (-not (Test-IsAdmin))) {
            Write-Log "$DisplayName falhou via winget sem privilégios de administrador (exit=$exitCode). Pulando." 'WARN'
            return
        }
        throw "Falha ao instalar $DisplayName via winget (exit=$exitCode)."
    }
    Refresh-SessionPath

    if ($hasArtifactValidators) {
        $diskVerified = $false
        $retryCount = 2
        while ($retryCount -gt 0 -and -not $diskVerified) {
            $diskVerified = Test-BootstrapPackageArtifactsPresent -ProbePaths $ProbePaths -AppxPackageNames $AppxPackageNames -WingetId $Id
            if (-not $diskVerified) {
                if ($retryCount -gt 1) {
                    Write-Log ("winget: {0} pos-instalacao; aguardando binario em disco..." -f $DisplayName) 'WARN'
                    Start-Sleep -Seconds 3
                }
                $retryCount--
            }
        }
        if (-not $diskVerified) {
            Write-Log ("winget: {0} instalado (exit 0), mas nenhum artefato esperado foi encontrado. Possivel ghost install." -f $DisplayName) 'ERROR'
            $message = "Instalacao de {0} retornou sucesso, mas nenhum artefato esperado apareceu (ProbePaths/Appx). Pacote nao sera marcado como concluido." -f $DisplayName
            throw (New-BootstrapBlockedException -Message $message -Kind 'winget-post-install-unverified' -Action 'inspect-or-reinstall' -Reasons @('artifact-missing', $Id))
        } else {
            Write-Log ("winget: verificado binario em disco para {0}." -f $DisplayName)
            if ($State) {
                try {
                    Register-BootstrapChange -State $State -Type 'Package' -Target $Id -Name $DisplayName -OldValue $null -NewValue @{ Source = 'winget'; Id = $Id } -Operation 'winget-install' -RollbackAction 'winget-uninstall' -Reversible 'partial' -Component $ComponentName
                } catch {
                    Write-Log ("winget: falha ao registrar mudanca de pacote {0} no manifest: {1}" -f $Id, $_.Exception.Message) 'WARN'
                }
            }
        }
    } elseif ($State) {
        # Sem ProbePaths para validar — registramos mesmo assim (Reversible=partial), assumindo exit 0.
        try {
            Register-BootstrapChange -State $State -Type 'Package' -Target $Id -Name $DisplayName -OldValue $null -NewValue @{ Source = 'winget'; Id = $Id } -Operation 'winget-install' -RollbackAction 'winget-uninstall' -Reversible 'partial' -Component $ComponentName
        } catch {
            Write-Log ("winget: falha ao registrar mudanca de pacote {0} no manifest: {1}" -f $Id, $_.Exception.Message) 'WARN'
        }
    }

    Write-Log "Instalação concluída: $DisplayName"
}

function Invoke-WingetListIdProbe {
    <#
    .SYNOPSIS
        Executa winget list -e --id com redirecionamento para ficheiros temporarios (evita deadlock de pipes
        e espelhamento linha-a-linha do Invoke-NativeCaptureWithLog em saidas muito grandes).
    #>
    param(
        [Parameter(Mandatory = $true)][string]$WingetPath,
        [Parameter(Mandatory = $true)][string]$Id,
        [int]$TimeoutMs = 120000
    )

    $guid = [Guid]::NewGuid().ToString('N')
    $tempRoot = Normalize-BootstrapPathSegment -Value $env:TEMP
    if ([string]::IsNullOrWhiteSpace($tempRoot)) {
        throw 'Invoke-WingetListIdProbe: TEMP indisponivel; nao e possivel criar ficheiros de captura winget.'
    }
    $stdoutPath = Join-Path -Path $tempRoot -ChildPath ("phasezero-winget-probe-{0}.out" -f $guid)
    $stderrPath = Join-Path -Path $tempRoot -ChildPath ("phasezero-winget-probe-{0}.err" -f $guid)
    $timedOut = $false
    $exitCode = -1
    $stdoutText = ''
    $stderrText = ''
    try {
        $argList = @(
            'list', '-e', '--id', $Id,
            '--accept-source-agreements',
            '--disable-interactivity'
        )
        $proc = Start-Process -FilePath $WingetPath -ArgumentList $argList -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath -WindowStyle Hidden -PassThru
        if (-not $proc.WaitForExit($TimeoutMs)) {
            $timedOut = $true
            try { Stop-Process -Id $proc.Id -Force -ErrorAction SilentlyContinue } catch { }
            try { $null = $proc.WaitForExit(5000) } catch { }
            $exitCode = 124
        } else {
            $exitCode = [int]$proc.ExitCode
        }
        if (Test-Path -LiteralPath $stdoutPath) {
            try { $stdoutText = [System.IO.File]::ReadAllText($stdoutPath) } catch { $stdoutText = '' }
        }
        if (Test-Path -LiteralPath $stderrPath) {
            try { $stderrText = [System.IO.File]::ReadAllText($stderrPath) } catch { $stderrText = '' }
        }
    } catch {
        throw
    } finally {
        try { if (Test-Path -LiteralPath $stdoutPath) { Remove-Item -LiteralPath $stdoutPath -Force -ErrorAction SilentlyContinue } } catch { }
        try { if (Test-Path -LiteralPath $stderrPath) { Remove-Item -LiteralPath $stderrPath -Force -ErrorAction SilentlyContinue } } catch { }
    }

    return [ordered]@{
        exitCode = $exitCode
        timedOut = $timedOut
        stdout   = $stdoutText
        stderr   = $stderrText
    }
}

function Test-WingetPackageInstalled {
    param(
        [Parameter(Mandatory = $true)][string]$WingetPath,
        [Parameter(Mandatory = $true)][string]$Id
    )
    try {
        $timeoutMs = 120000
        $timeoutSec = [int]([Math]::Max(1, $timeoutMs / 1000))
        Write-Log ("winget list: iniciando (timeout {0}s) id={1}" -f $timeoutSec, $Id)
        $cap = Invoke-WingetListIdProbe -WingetPath $WingetPath -Id $Id -TimeoutMs $timeoutMs
        $combined = ([string]$cap.stdout + "`n" + [string]$cap.stderr).Trim()
        if ([bool]$cap.timedOut) {
            Write-Log ("winget list: timeout ({0}s) ao verificar id={1}; assume-se nao instalado para permitir tentativa de install." -f $timeoutSec, $Id) 'WARN'
            return $false
        }
        if ([int]$cap.exitCode -ne 0) {
            $exit = [int]$cap.exitCode
            if ($script:WingetListExitCodesNotInstalled -contains $exit) {
                Write-Log ("winget list: id={0} nao consta como instalado (exit {1}, NO_APPLICATIONS_FOUND / 0x8A150014; esperado quando o pacote ainda nao esta instalado)." -f $Id, $exit)
                return $false
            }
            $hint = ''
            if (-not [string]::IsNullOrWhiteSpace($combined)) {
                $lines = ($combined -replace "`r", '') -split "`n" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
                if ($lines.Count -gt 0) {
                    $firstLine = [string]$lines[0]
                    if ($firstLine.Length -gt 200) { $firstLine = $firstLine.Substring(0, 200) + '...' }
                    $hint = (' Saida: {0}' -f $firstLine)
                }
            }
            Write-Log ("winget list: exitCode={0} id={1}; assume-se nao instalado.{2}" -f $exit, $Id, $hint) 'WARN'
            return $false
        }
        if ([string]::IsNullOrWhiteSpace($combined)) { return $false }
        return (Test-WingetListOutputContainsId -Output $combined -Id $Id)
    } catch {
        Write-Log ("winget list: excecao ao verificar id={0}: {1}" -f $Id, $_.Exception.Message) 'WARN'
        return $false
    }
}

function Test-WingetListOutputContainsId {
    <#
    .SYNOPSIS
        Decide se a saida tabular de `winget list -e --id <id>` contem uma linha de pacote
        instalado para o Id pedido. Faz match em linha-a-linha, ignorando cabecalho/separador
        e exigindo que o token coincida com o Id em uma das colunas. Evita falso-positivo
        quando o Id aparece em mensagens como "Foi encontrado um pacote existente ja instalado".
    #>
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Output,
        [Parameter(Mandatory = $true)][string]$Id
    )
    if ([string]::IsNullOrWhiteSpace($Output)) { return $false }
    $idTrim = $Id.Trim()
    if ([string]::IsNullOrWhiteSpace($idTrim)) { return $false }

    $lines = ($Output -replace "`r", '') -split "`n"
    $idEsc = [regex]::Escape($idTrim)
    foreach ($raw in $lines) {
        $line = [string]$raw
        if ([string]::IsNullOrWhiteSpace($line)) { continue }
        $trimmed = $line.Trim()

        # Pular linhas separadoras tabulares.
        if ($trimmed -match '^[-=\s]+$') { continue }
        # Pular cabecalho `Name  Id  Version  Available  Source` (ou variantes localizadas).
        if ($trimmed -match '^\s*Name\s+Id\s+Vers' -or $trimmed -match '^\s*Nome\s+Id\s+Vers') { continue }

        # Linhas de mensagem narrativa (winget escreve frases informativas em portugues/ingles).
        # Match real exige que o Id apareca como TOKEN delimitado por whitespace (coluna) e nao
        # como parte de uma frase pontuada por ":" ou ".".
        if ($trimmed -match (('(^|\s)' + $idEsc + '($|\s)'))) {
            # Confirma que a linha tambem possui pelo menos uma coluna apos o Id (Version).
            # Linhas de log do tipo "winget: verificando id=Foo.Bar" tambem casariam, mas vem
            # do nosso proprio Write-Log; sao filtradas porque o caller passa apenas $cap.stdout/stderr
            # do processo winget, nunca do log local.
            return $true
        }
    }
    return $false
}

function Ensure-Python {
    param(
        [Parameter(Mandatory = $true)][string]$WingetPath
    )

    $pythonExe = Resolve-CommandPath -Name 'python'
    if ($pythonExe -and ($pythonExe -match '\\Microsoft\\WindowsApps\\')) {
        Write-Log 'python.exe e alias da Microsoft Store — instalando Python real via winget.' 'WARN'
    }
    if ($pythonExe -and ($pythonExe -notmatch '\\Microsoft\\WindowsApps\\')) {
        $ver = ((& $pythonExe --version) 2>&1 | Select-Object -First 1)
        Write-Log "python já instalado: $ver ($pythonExe)"
        Ensure-PythonPathHealthy -PythonExe $pythonExe
        return
    }

    $pyLauncher = Resolve-CommandPath -Name 'py'
    if ($pyLauncher -and ($pyLauncher -match '\\Microsoft\\WindowsApps\\')) {
        Write-Log 'py.exe e alias da Microsoft Store — ignorando.' 'WARN'
    }
    if ($pyLauncher -and ($pyLauncher -notmatch '\\Microsoft\\WindowsApps\\')) {
        $ver = ((& $pyLauncher -3 --version) 2>&1 | Select-Object -First 1)
        Write-Log "Python já instalado (py launcher): $ver ($pyLauncher)"
        try {
            $out = (& $pyLauncher -3 -c 'import sys; print(sys.executable)' 2>&1) | Select-Object -First 1
            if ($out -and (Test-Path $out)) { Ensure-PythonPathHealthy -PythonExe $out }
        } catch {
        }
        return
    }

    $pythonProbePaths = @(
        "$env:LOCALAPPDATA\Programs\Python\Python313\python.exe",
        "$env:ProgramFiles\Python313\python.exe",
        "${env:ProgramFiles(x86)}\Python313\python.exe"
    )
    Ensure-WingetPackage -WingetPath $WingetPath -Id 'Python.Python.3.13' -DisplayName 'Python 3.13' -ProbePaths $pythonProbePaths
    Refresh-SessionPath

    $pythonExe = Resolve-CommandPath -Name 'python'
    if (-not $pythonExe -or ($pythonExe -match '\\Microsoft\\WindowsApps\\')) {
        $roots = @(
            (Join-Path $env:LOCALAPPDATA 'Programs\Python'),
            (Join-Path $env:ProgramFiles 'Python'),
            $env:ProgramFiles
        ) | Where-Object { $_ -and (Test-Path $_) }

        $realPython = $null
        foreach ($root in $roots) {
            $dirs = Get-ChildItem -Path $root -Directory -ErrorAction SilentlyContinue |
                Where-Object { $_.Name -match '^Python3' } |
                Sort-Object Name -Descending
            foreach ($d in $dirs) {
                $candidate = Join-Path $d.FullName 'python.exe'
                if (Test-Path $candidate) { $realPython = $candidate; break }
            }
            if ($realPython) { break }
        }

        if ($realPython) {
            Ensure-PythonPathHealthy -PythonExe $realPython
            $pythonExe = Resolve-CommandPath -Name 'python'
        }
    }

    if (-not $pythonExe -or ($pythonExe -match '\\Microsoft\\WindowsApps\\')) { throw 'Python instalado via winget, mas o comando python nao foi encontrado no PATH.' }
    $ver = ((& $pythonExe --version) 2>&1 | Select-Object -First 1)
    Write-Log "python instalado: $ver ($pythonExe)"
    Ensure-PythonPathHealthy -PythonExe $pythonExe
}

function Get-GitExe {
    $cmd = Get-Command git -ErrorAction SilentlyContinue
    if ($null -ne $cmd) {
        $cmdCandidates = @($cmd | Select-Object -First 1)
        if ($cmdCandidates.Count -gt 0 -and $null -ne $cmdCandidates[0]) {
            $cmdOne = $cmdCandidates[0]
            $src = [string]$cmdOne.Source
            if (-not [string]::IsNullOrWhiteSpace($src) -and (Test-Path -LiteralPath $src)) {
                return $src
            }
        }
    }
    $pf64 = Get-BootstrapSpecialFolderEnv -EnvironmentName 'ProgramFiles'
    $pf86 = Get-BootstrapSpecialFolderEnv -EnvironmentName 'ProgramFiles(x86)'
    $candidates = @(
        $(if ($pf64) { Join-Path -Path $pf64 -ChildPath 'Git\cmd\git.exe' } else { $null }),
        $(if ($pf64) { Join-Path -Path $pf64 -ChildPath 'Git\bin\git.exe' } else { $null }),
        $(if ($pf86) { Join-Path -Path $pf86 -ChildPath 'Git\cmd\git.exe' } else { $null }),
        $(if ($pf86) { Join-Path -Path $pf86 -ChildPath 'Git\bin\git.exe' } else { $null })
    ) | Where-Object { $_ -and (Test-Path -LiteralPath $_) }
    $firstCandidates = @($candidates | Select-Object -First 1)
    if ($firstCandidates.Count -eq 0 -or [string]::IsNullOrWhiteSpace([string]$firstCandidates[0])) { return $null }
    return [string]$firstCandidates[0]
}

function Get-GitBashExe {
    function Resolve-ClaudeGitBashPathCandidate {
        param([AllowNull()][string]$CandidatePath)
        if ([string]::IsNullOrWhiteSpace($CandidatePath)) { return $null }
        $p = $CandidatePath.Trim()
        try {
            if (Test-Path -LiteralPath $p) {
                $items = @(Get-Item -LiteralPath $p -ErrorAction SilentlyContinue | Select-Object -First 1)
                if ($items.Count -eq 0 -or $null -eq $items[0]) { return $null }
                return [string]$items[0].FullName
            }
        } catch {
            return $null
        }
        try {
            if ([WildcardPattern]::ContainsWildcardCharacters($p)) {
                $items = @(Get-Item -Path $p -ErrorAction SilentlyContinue | Select-Object -First 1)
                if ($items.Count -eq 0 -or $null -eq $items[0]) { return $null }
                return [string]$items[0].FullName
            }
        } catch {
            return $null
        }
        return $null
    }

    $fromUser = Normalize-BootstrapPathSegment -Value ([Environment]::GetEnvironmentVariable('CLAUDE_CODE_GIT_BASH_PATH', 'User'))
    $resolved = Resolve-ClaudeGitBashPathCandidate -CandidatePath $fromUser
    if (-not [string]::IsNullOrWhiteSpace($resolved)) { return $resolved }
    $resolved = Resolve-ClaudeGitBashPathCandidate -CandidatePath (Normalize-BootstrapPathSegment -Value $env:CLAUDE_CODE_GIT_BASH_PATH)
    if (-not [string]::IsNullOrWhiteSpace($resolved)) { return $resolved }

    $pf64 = Get-BootstrapSpecialFolderEnv -EnvironmentName 'ProgramFiles'
    $pf86 = Get-BootstrapSpecialFolderEnv -EnvironmentName 'ProgramFiles(x86)'
    $candidates = @(
        $(if ($pf64) { Join-Path -Path $pf64 -ChildPath 'Git\bin\bash.exe' } else { $null }),
        $(if ($pf64) { Join-Path -Path $pf64 -ChildPath 'Git\usr\bin\bash.exe' } else { $null }),
        $(if ($pf86) { Join-Path -Path $pf86 -ChildPath 'Git\bin\bash.exe' } else { $null }),
        $(if ($pf86) { Join-Path -Path $pf86 -ChildPath 'Git\usr\bin\bash.exe' } else { $null })
    ) | Where-Object { $_ -and (Test-Path -LiteralPath $_) }
    $firstCandidates = @($candidates | Select-Object -First 1)
    if ($firstCandidates.Count -eq 0 -or [string]::IsNullOrWhiteSpace([string]$firstCandidates[0])) { return $null }
    return [string]$firstCandidates[0]
}

function Ensure-GitAndBash {
    param([Parameter(Mandatory = $true)][string]$WingetPath)
    $git = Get-GitExe
    if (-not $git) {
        Ensure-WingetPackage -WingetPath $WingetPath -Id 'Git.Git' -DisplayName 'Git for Windows' -ProbePaths @("$env:ProgramFiles\Git\cmd\git.exe", "${env:ProgramFiles(x86)}\Git\cmd\git.exe")
        $git = Get-GitExe
    }
    if (-not $git) {
        $choco = Get-Command choco -ErrorAction SilentlyContinue
        if ($choco) {
            Write-Log 'Git for Windows nao localizado apos winget; tentando fallback Chocolatey git.install.' 'WARN'
            & $choco.Source install git.install -y --force
            Refresh-SessionPath
            $git = Get-GitExe
        }
    }
    if (-not $git) { throw 'winget e chocolatey falharam. Instale Git for Windows manualmente.' }
    $git = [string](@($git)[0]).Trim()
    $gitVersion = & $git --version
    Write-Log "git: $gitVersion ($git)"

    $bash = Get-GitBashExe
    if (-not $bash) { throw 'bash.exe (Git Bash) nao encontrado apos a instalação do Git.' }
    $bash = [string](@($bash)[0]).Trim()
    Set-UserEnvVar -Name 'CLAUDE_CODE_GIT_BASH_PATH' -Value $bash
    Write-Log "bash: $bash"
    return @{ Git = $git; Bash = $bash }
}

function Get-NodeExe {
    $cmd = Get-Command node -ErrorAction SilentlyContinue
    if ($cmd) { return $cmd.Source }
    $pf = Get-BootstrapSpecialFolderEnv -EnvironmentName 'ProgramFiles'
    if (-not $pf) { return $null }
    $candidate = Join-Path -Path $pf -ChildPath 'nodejs\node.exe'
    if (Test-Path $candidate) { return $candidate }
    return $null
}

function Get-NpmCmd {
    $cmd = Get-Command npm.cmd -ErrorAction SilentlyContinue
    if ($cmd) { return $cmd.Source }
    $pf = Get-BootstrapSpecialFolderEnv -EnvironmentName 'ProgramFiles'
    if (-not $pf) { return $null }
    $candidate = Join-Path -Path $pf -ChildPath 'nodejs\npm.cmd'
    if (Test-Path $candidate) { return $candidate }
    return $null
}

function Test-BootstrapDotNetSdkListHasEntry {
    <#
    .SYNOPSIS
        Indica se a saida de `dotnet --list-sdks` contem pelo menos uma linha de SDK (major.minor.patch).
    #>
    param([string]$ListSdksOutput)
    if ([string]::IsNullOrWhiteSpace($ListSdksOutput)) { return $false }
    foreach ($line in ($ListSdksOutput -split "`r?`n")) {
        $t = $line.Trim()
        if ($t -match '^\d+\.\d+\.\d+') { return $true }
    }
    return $false
}

function Test-BootstrapDotNetSdkListHasMajorBand {
    <#
    .SYNOPSIS
        Indica se a saida de `dotnet --list-sdks` inclui SDK na banda major dada (ex.: 8 para .NET 8).
    #>
    param(
        [string]$ListSdksOutput,
        [int]$Major
    )
    if ([string]::IsNullOrWhiteSpace($ListSdksOutput)) { return $false }
    $pat = '^\s*{0}\.\d+\.\d+' -f $Major
    foreach ($line in ($ListSdksOutput -split "`r?`n")) {
        if (($line.Trim()) -match $pat) { return $true }
    }
    return $false
}

function Get-DotNetExe {
    $candidate = $null
    try {
        $pf = Get-BootstrapSpecialFolderEnv -EnvironmentName 'ProgramFiles'
        if ($pf) { $candidate = Join-Path -Path $pf -ChildPath 'dotnet\dotnet.exe' }
    } catch { $candidate = $null }
    if ($candidate -and (Test-Path -LiteralPath $candidate)) { return $candidate }

    $resolved = Resolve-CommandPath -Name 'dotnet'
    if (-not $resolved) { return $null }
    if ($resolved -match '\\Microsoft\\WindowsApps\\') { return $null }
    return $resolved
}

function Get-DotNetListSdksOutput {
    param([Parameter(Mandatory = $true)][string]$DotnetExe)
    try {
        $lines = & $DotnetExe @('--list-sdks') 2>&1 | ForEach-Object { [string]$_ }
        return ($lines -join [Environment]::NewLine)
    } catch {
        return ''
    }
}

function Ensure-DotNetSdkAndVerify {
    param([Parameter(Mandatory = $true)][string]$WingetPath)

    $dotnetWingetId = 'Microsoft.DotNet.SDK.8'
    $targetMajor = 8
    $dotnet = Get-DotNetExe
    $sdkText = if ($dotnet) { Get-DotNetListSdksOutput -DotnetExe $dotnet } else { '' }
    $hasBand8 = Test-BootstrapDotNetSdkListHasMajorBand -ListSdksOutput $sdkText -Major $targetMajor

    if ($dotnet -and -not $hasBand8 -and (Test-BootstrapDotNetSdkListHasEntry -ListSdksOutput $sdkText)) {
        Write-Log ("dotnet-core: SDK mais recente detectado, mas .NET 8.x requerido pelo bootstrap. Instalando .NET 8 como complemento." -f $targetMajor) 'WARN'
    }

    if (-not $hasBand8) {
        $dotnetSdk8ProbePaths = @(
            "$env:ProgramFiles\dotnet\sdk\8.*\dotnet.dll",
            "${env:ProgramFiles(x86)}\dotnet\sdk\8.*\dotnet.dll"
        )
        Ensure-WingetPackage -WingetPath $WingetPath -Id $dotnetWingetId -DisplayName 'Microsoft .NET SDK 8' -AllowFailureWhenNotAdmin $false -ProbePaths $dotnetSdk8ProbePaths
        Refresh-SessionPath
        $dotnet = Get-DotNetExe
        $sdkText = if ($dotnet) { Get-DotNetListSdksOutput -DotnetExe $dotnet } else { '' }
        $hasBand8 = Test-BootstrapDotNetSdkListHasMajorBand -ListSdksOutput $sdkText -Major $targetMajor
    }

    if (-not $dotnet) {
        throw ('Falha ao localizar dotnet.exe apos instalar/verificar {0}. Confirme PATH (reabra a UI ou a sessao) e que o pacote winget instalou em Program Files.' -f $dotnetWingetId)
    }

    if (-not $hasBand8) {
        throw ('dotnet.exe em {0}, mas `dotnet --list-sdks` nao lista SDK {1}.x (host sem SDK, PATH errado ou instalacao incompleta). Corrija com: winget install -e --id {2}; depois reabra a sessao.' -f $dotnet, $targetMajor, $dotnetWingetId)
    }

    $hostVer = ''
    try {
        $hostVer = ([string](& $dotnet @('--version') 2>&1 | Select-Object -First 1)).Trim()
    } catch {
        $hostVer = ''
    }
    Write-Log ("dotnet host: {0} ({1})" -f $(if ($hostVer) { $hostVer } else { '-' }), $dotnet)
    $sdkPreview = ($sdkText.Trim() -replace "`r?`n", ' | ')
    if ($sdkPreview.Length -gt 400) { $sdkPreview = $sdkPreview.Substring(0, 397) + '...' }
    Write-Log ("dotnet --list-sdks: {0}" -f $sdkPreview)

    return @{
        DotnetExe = $dotnet
        SdkListText = $sdkText
    }
}

function Get-NodeMajor {
    param([Parameter(Mandatory = $true)][string]$NodePath)
    $raw = & $NodePath -v
    if (-not $raw) { return 0 }
    $raw = $raw.Trim()
    if ($raw.StartsWith('v')) { $raw = $raw.Substring(1) }
    $major = 0
    [void][int]::TryParse(($raw.Split('.')[0]), [ref]$major)
    return $major
}

function Ensure-NodeAndNpm {
    param([Parameter(Mandatory = $true)][string]$WingetPath)
    $node = Get-NodeExe
    $needsInstall = $true
    if ($node) {
        $major = Get-NodeMajor -NodePath $node
        if ($major -ge 18) { $needsInstall = $false }
    }

    if ($needsInstall) {
        Ensure-WingetPackage -WingetPath $WingetPath -Id 'OpenJS.NodeJS.LTS' -DisplayName 'Node.js (LTS)' -ProbePaths @("$env:ProgramFiles\nodejs\node.exe", "${env:ProgramFiles(x86)}\nodejs\node.exe")
        Refresh-SessionPath
        $node = Get-NodeExe
    }
    if (-not $node) { throw 'Falha ao localizar node.exe apos a instalação.' }
    $nodeVersion = & $node -v
    Write-Log "node: $nodeVersion ($node)"

    $npmCmd = Get-NpmCmd
    if (-not $npmCmd) { throw 'Falha ao localizar npm.cmd apos a instalação.' }
    $npmVersion = & $npmCmd --version
    Write-Log "npm: $npmVersion ($npmCmd)"

    $defaultNpmBin = Join-Path $env:APPDATA 'npm'
    $npmPrefix = $null
    try {
        $npmPrefix = (& $npmCmd prefix -g 2>$null | Select-Object -First 1)
        if ($npmPrefix) { $npmPrefix = $npmPrefix.Trim() }
    } catch {
        $npmPrefix = $null
    }

    $npmBin = $defaultNpmBin
    Ensure-PathUserContains -Dir $defaultNpmBin
    if ($npmPrefix -and (Test-Path $npmPrefix)) {
        Ensure-PathUserContains -Dir $npmPrefix
        $npmBin = $npmPrefix
    }

    return @{ Node = $node; NpmCmd = $npmCmd; NpmBin = $npmBin }
}

function Invoke-NpmWithLog {
    param(
        [Parameter(Mandatory = $true)][string]$NpmCmd,
        [Parameter(Mandatory = $true)][string[]]$Args
    )
    return (Invoke-NativeWithLog -Exe $NpmCmd -Args $Args)
}

function ConvertTo-BootstrapSafeNativeSummaryLine {
    param([AllowNull()][object]$Value)

    if ($null -eq $Value) { return '' }
    $text = [string]$Value
    $text = $text -replace [string][char]0, ''
    $text = $text -replace ([string][char]0xFFFD), ''
    # Sequencia U+FFFD mal decodificada como CP1252 (0xEF 0xBF 0xBD lidos como tres chars).
    # Construida por char code para nao depender do encoding com que este arquivo e lido:
    # UTF-8 sem BOM vira ANSI no PowerShell 5.1 e um literal aqui seria mangleado de novo.
    $mojibakeFffd = [string]([char]0x00EF) + [string]([char]0x00BF) + [string]([char]0x00BD)
    $text = $text.Replace($mojibakeFffd, '')
    $text = $text -replace '[\u0001-\u0008\u000B\u000C\u000E-\u001F]', ''
    $text = $text.Trim()
    if ($text.Length -gt 500) { $text = $text.Substring(0, 497) + '...' }
    return $text
}

function Invoke-BootstrapScriptBlockWithTimeout {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [Parameter(Mandatory = $true)][scriptblock]$ScriptBlock,
        [ValidateRange(1, 600)][int]$TimeoutSeconds = 5
    )

    $job = $null
    $started = Get-Date
    try {
        $job = Start-Job -ScriptBlock $ScriptBlock
        if (-not (Wait-Job -Job $job -Timeout $TimeoutSeconds)) {
            try { Stop-Job -Job $job -ErrorAction SilentlyContinue } catch { }
            return [ordered]@{
                name = $Name
                status = 'timeout'
                timedOut = $true
                durationMs = [long]((Get-Date) - $started).TotalMilliseconds
                value = $null
                error = ("{0} exceeded timeout of {1}s" -f $Name, $TimeoutSeconds)
            }
        }
        $value = Receive-Job -Job $job -ErrorAction Stop
        return [ordered]@{
            name = $Name
            status = 'ok'
            timedOut = $false
            durationMs = [long]((Get-Date) - $started).TotalMilliseconds
            value = $value
            error = ''
        }
    } catch {
        return [ordered]@{
            name = $Name
            status = 'failed'
            timedOut = $false
            durationMs = [long]((Get-Date) - $started).TotalMilliseconds
            value = $null
            error = $_.Exception.Message
        }
    } finally {
        if ($job) { Remove-Job -Job $job -Force -ErrorAction SilentlyContinue }
    }
}

function Invoke-NativeFirstLine {
    param(
        [Parameter(Mandatory = $true)][string]$Exe,
        [Alias('Args')][string[]]$Arguments = @(),
        # 3000ms era curto demais: em hosts lentos/carregados (Steam Deck, ou logo apos uma
        # instalacao grande com antivirus indexando) o cold-start de powershell.exe/cmd.exe
        # para sondar `--version` de comandos JA resolvidos passa de 3s, fazendo ferramentas
        # saudaveis aparecerem como "timeout"/indisponiveis no inventario e na auditoria.
        # 15s tolera o host lento e continua limitado pelo kill interno em caso de hang real.
        [int]$TimeoutMs = 15000
    )

    if ($Exe -match '\.(ps1|psm1|psd1)$') {
        $scriptFile = $Exe
        $psHost = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
        if (-not (Test-Path -LiteralPath $psHost)) { $psHost = 'powershell.exe' }
        $Exe = $psHost
        $Arguments = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $scriptFile) + @($Arguments)
    }

    $stdoutPath = Join-Path $env:TEMP ('phasezero-native-firstline-out-' + [Guid]::NewGuid().ToString('N') + '.txt')
    $stderrPath = Join-Path $env:TEMP ('phasezero-native-firstline-err-' + [Guid]::NewGuid().ToString('N') + '.txt')
    $proc = $null
    try {
        $proc = Start-Process -FilePath $Exe -ArgumentList $Arguments -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath -WindowStyle Hidden -PassThru -ErrorAction Stop
        if (-not $proc.WaitForExit([Math]::Max(500, $TimeoutMs))) {
            try { $proc.Kill() } catch { }
            return (ConvertTo-BootstrapSafeNativeSummaryLine -Value ("timeout after {0}ms" -f $TimeoutMs))
        }
        $lines = @()
        if (Test-Path -LiteralPath $stdoutPath) { $lines += @(Get-Content -LiteralPath $stdoutPath -ErrorAction SilentlyContinue) }
        if ($lines.Count -eq 0 -and (Test-Path -LiteralPath $stderrPath)) { $lines += @(Get-Content -LiteralPath $stderrPath -ErrorAction SilentlyContinue) }
        return (ConvertTo-BootstrapSafeNativeSummaryLine -Value ($lines | Select-Object -First 1))
    } catch {
        return ''
    } finally {
        Remove-Item -LiteralPath $stdoutPath,$stderrPath -Force -ErrorAction SilentlyContinue
    }
}

function Ensure-NpmGlobalPackage {
    param(
        [Parameter(Mandatory = $true)][string]$NpmCmd,
        [Parameter(Mandatory = $true)][string]$Package,
        [string]$DisplayName = $Package,
        [string]$CheckName,
        [string[]]$CommandNames = @(),
        [string[]]$VersionArgs = @('--version'),
        [string]$NpmBin = ''
    )
    if (-not $CheckName) {
        if ($Package.StartsWith('@')) {
            $CheckName = $Package
        } elseif ($Package -like '*@*') {
            $CheckName = $Package.Split('@')[0]
        } else {
            $CheckName = $Package
        }
    }
    $declaredCommands = @(Get-BootstrapNonEmptyStringArray -Values $CommandNames)
    $versionProbeArgs = @(Get-BootstrapNonEmptyStringArray -Values $VersionArgs)
    if ($versionProbeArgs.Count -eq 0) { $versionProbeArgs = @('--version') }
    if (-not [string]::IsNullOrWhiteSpace($NpmBin)) {
        Ensure-PathUserContains -Dir $NpmBin
        Refresh-SessionPath
    }
    $installed = $false
    try {
        $out = & $NpmCmd list -g --depth=0 2>$null
        if ($out -match [regex]::Escape($CheckName) + '@') { $installed = $true }
    } catch {
        $installed = $false
    }

    if ($installed) {
        if ($declaredCommands.Count -eq 0) {
            Write-Log "$DisplayName já instalado via npm -g."
            return
        }
        foreach ($cmdName in @($declaredCommands)) {
            $cmdPath = Resolve-CommandPath -Name $cmdName
            if ($cmdPath) {
                try {
                    $ver = Invoke-NativeFirstLine -Exe $cmdPath -Args $versionProbeArgs
                    Write-Log "$DisplayName já instalado via npm -g: $ver ($cmdPath)"
                } catch {
                    Write-Log "$DisplayName já instalado via npm -g: comando $cmdName encontrado ($cmdPath)."
                }
                return
            }
        }
        Write-Log ("{0} aparece em npm list -g, mas nenhum comando declarado foi encontrado ({1}); reinstalando." -f $DisplayName, ($declaredCommands -join ', ')) 'WARN'
    }

    Write-Log "Instalando $DisplayName via npm -g..."
    $exitCode = Invoke-NpmWithLog -NpmCmd $NpmCmd -Args @('install', '-g', $Package)
    if ($exitCode -ne 0) { throw "Falha ao instalar $DisplayName via npm (exit=$exitCode)." }
    if (-not [string]::IsNullOrWhiteSpace($NpmBin)) {
        Ensure-PathUserContains -Dir $NpmBin
    }
    Refresh-SessionPath
    if ($declaredCommands.Count -gt 0) {
        foreach ($cmdName in @($declaredCommands)) {
            $cmdPath = Resolve-CommandPath -Name $cmdName
            if ($cmdPath) {
                try {
                    $ver = Invoke-NativeFirstLine -Exe $cmdPath -Args $versionProbeArgs
                    Write-Log "$DisplayName instalado: $ver ($cmdPath)"
                } catch {
                    Write-Log "$DisplayName instalado: comando $cmdName encontrado ($cmdPath)."
                }
                Write-Log "Instalação concluída: $DisplayName"
                return
            }
        }
        $message = "Instalacao npm de {0} retornou sucesso, mas nenhum comando declarado apareceu no PATH ({1}). Repare PATH/npm global bin ou reinstale." -f $DisplayName, ($declaredCommands -join ', ')
        throw (New-BootstrapBlockedException -Message $message -Kind 'npm-command-unverified' -Action 'repair-node-path-or-reinstall' -Reasons @('npm-command-missing', $Package))
    }
    Write-Log "Instalação concluída: $DisplayName"
}

function Ensure-ClaudeCode {
    param([Parameter(Mandatory = $true)][string]$WingetPath)

    $null = $WingetPath
    $claudeExe = Resolve-CommandPath -Name 'claude'
    if ($claudeExe) {
        $ver = ((& $claudeExe --version) 2>&1 | Select-Object -First 1)
        Write-Log "claude já instalado: $ver ($claudeExe)"
        return
    }

    $npmCmd = Get-BootstrapNpmCommandForAiTools
    Ensure-NpmGlobalPackage -NpmCmd $npmCmd -Package '@anthropic-ai/claude-code' -DisplayName 'Claude Code (Anthropic)' -CommandNames @('claude') -VersionArgs @('--version')
    Refresh-SessionPath

    $claudeExe = Resolve-CommandPath -Name 'claude'
    if (-not $claudeExe) { throw 'Claude Code instalado via npm, mas o comando claude nao foi encontrado no PATH.' }
    $ver = ((& $claudeExe --version) 2>&1 | Select-Object -First 1)
    Write-Log "claude instalado: $ver ($claudeExe)"
}

function Ensure-CodexInstaller {
    param([Parameter(Mandatory = $true)][string]$WingetPath)

    $id = 'OpenAI.Codex'
    $codexCmdDefault = Join-Path (Join-Path $env:APPDATA 'npm') 'codex.cmd'
    if (Test-Path $codexCmdDefault) {
        Write-Log "Codex CLI já presente via npm ($codexCmdDefault). Pulando instalação via winget ($id)."
        return
    }
    $npmCmd = Get-NpmCmd
    if ($npmCmd) {
        $npmPrefix = $null
        try {
            $npmPrefix = (& $npmCmd prefix -g 2>$null | Select-Object -First 1)
            if ($npmPrefix) { $npmPrefix = $npmPrefix.Trim() }
        } catch {
            $npmPrefix = $null
        }
        if ($npmPrefix) {
            $codexCmdFromPrefix = Join-Path $npmPrefix 'codex.cmd'
            if (Test-Path $codexCmdFromPrefix) {
                Write-Log "Codex CLI já presente via npm ($codexCmdFromPrefix). Pulando instalação via winget ($id)."
                return
            }
        }
    }

    if (Test-WingetPackageInstalled -WingetPath $WingetPath -Id $id) {
        Write-Log "Codex Installer ($id) já instalado (winget)."
        return
    }

    try {
        Ensure-WingetPackage -WingetPath $WingetPath -Id $id -DisplayName "Codex Installer ($id)" -AllowFailureWhenNotAdmin $true
    } catch {
        Write-Log ("Falha ao instalar Codex Installer via winget. Continuando. " + $_.Exception.Message) 'WARN'
    }
}

function Get-BootstrapUserProfileRoot {
    # $env:USERPROFILE pode vir vazio (perfil incompleto, host nao-Windows). Join-Path lanca com
    # base nula, entao resolvemos por fallback em vez de propagar o erro.
    if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) { return [string]$env:USERPROFILE }
    $profileFolder = ''
    try { $profileFolder = [Environment]::GetFolderPath('UserProfile') } catch { $profileFolder = '' }
    if (-not [string]::IsNullOrWhiteSpace($profileFolder)) { return $profileFolder }
    if (-not [string]::IsNullOrWhiteSpace($env:HOME)) { return [string]$env:HOME }
    return (Get-Location).Path
}

function Get-BootstrapLocalAppDataRoot {
    if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) { return [string]$env:LOCALAPPDATA }
    $folder = ''
    try { $folder = [Environment]::GetFolderPath('LocalApplicationData') } catch { $folder = '' }
    if (-not [string]::IsNullOrWhiteSpace($folder)) { return $folder }
    return (Join-Path (Get-BootstrapUserProfileRoot) '.local')
}

function Get-BootstrapCodexHome {
    $codexHome = [Environment]::GetEnvironmentVariable('CODEX_HOME', 'Process')
    if ([string]::IsNullOrWhiteSpace($codexHome)) {
        $codexHome = [Environment]::GetEnvironmentVariable('CODEX_HOME', 'User')
    }
    if ([string]::IsNullOrWhiteSpace($codexHome)) {
        $codexHome = Join-Path (Get-BootstrapUserProfileRoot) '.codex'
    }
    return $codexHome
}

function Get-BootstrapCodexDesktopPackageDataRoot {
    return (Join-Path (Get-BootstrapLocalAppDataRoot) 'Packages\OpenAI.Codex_2p2nqsd0c76g0')
}

function Get-BootstrapCodexDesktopStatePaths {
    $codexHome = Get-BootstrapCodexHome
    return @(
        (Join-Path $codexHome '.codex-global-state.json'),
        (Join-Path $codexHome 'codex-global-state.json')
    ) | Select-Object -Unique
}

function Test-BootstrapCodexTruthyValue {
    param([AllowNull()]$Value)

    if ($null -eq $Value) { return $false }
    if ($Value -is [bool]) { return [bool]$Value }
    $text = ([string]$Value).Trim().ToLowerInvariant()
    return (@('1', 'true', 'yes', 'y', 'on') -contains $text)
}

function Get-BootstrapCodexDesktopPackageInfo {
    $dataRoot = Get-BootstrapCodexDesktopPackageDataRoot
    $info = [ordered]@{
        installed = $false
        version = ''
        packageFullName = ''
        installLocation = ''
        dataRoot = $dataRoot
        dataRootExists = (Test-Path -LiteralPath $dataRoot)
    }

    if (Get-Command -Name Get-AppxPackage -ErrorAction SilentlyContinue) {
        try {
            $pkg = @(Get-AppxPackage -Name 'OpenAI.Codex' -ErrorAction SilentlyContinue | Sort-Object Version -Descending | Select-Object -First 1)
            if ($pkg.Count -gt 0) {
                $info['installed'] = $true
                $info['version'] = [string]$pkg[0].Version
                $info['packageFullName'] = [string]$pkg[0].PackageFullName
                $info['installLocation'] = [string]$pkg[0].InstallLocation
            }
        } catch {
            $info['queryError'] = $_.Exception.Message
        }
    }

    return $info
}

function Get-BootstrapCodexCommandInfo {
    $pathEntries = @()
    try {
        $pathEntries = @(where.exe codex 2>$null | ForEach-Object { [string]$_ } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    } catch {
        $pathEntries = @()
    }
    $cmdPath = [string]($pathEntries | Where-Object { $_ -match '\.cmd$' } | Select-Object -First 1)
    if ([string]::IsNullOrWhiteSpace($cmdPath)) {
        $cmdPath = Resolve-CommandPath -Name 'codex'
    }

    $version = ''
    if ($cmdPath) {
        try {
            $version = Invoke-NativeFirstLine -Exe $cmdPath -Args @('--version')
        } catch {
            $version = "erro: $($_.Exception.Message)"
        }
    }

    return [ordered]@{
        path = if ($cmdPath) { [string]$cmdPath } else { '' }
        version = $version
        pathEntries = @($pathEntries)
    }
}

function Get-BootstrapCodexDesktopLatestLog {
    $dataRoot = Get-BootstrapCodexDesktopPackageDataRoot
    $logRoot = Join-Path $dataRoot 'LocalCache\Local\Codex\Logs'
    $result = [ordered]@{
        path = ''
        exists = $false
        exitCode = ''
        exitCodeHex = ''
        recentError = ''
        spawnedPath = ''
        spawnedVersion = ''
        staleSpawnedPackage = $false
        lastWriteTime = ''
    }

    if (-not (Test-Path -LiteralPath $logRoot)) { return $result }

    $log = @(Get-ChildItem -LiteralPath $logRoot -File -Filter 'codex-desktop-*.log' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1)
    if ($log.Count -eq 0) { return $result }

    $result['path'] = [string]$log[0].FullName
    $result['exists'] = $true
    $result['lastWriteTime'] = ([datetime]$log[0].LastWriteTime).ToString('o')

    try {
        $text = (Get-Content -LiteralPath $log[0].FullName -Tail 240 -ErrorAction Stop | ForEach-Object { [string]$_ }) -join [Environment]::NewLine
        if ($text -match 'code=(\d+)') {
            $result['exitCode'] = [string]$Matches[1]
            try {
                $result['exitCodeHex'] = ('0x{0:X8}' -f [uint32]([int64]$Matches[1]))
            } catch {
                $result['exitCodeHex'] = ''
            }
        } elseif ($text -match 'closeCode=(\d+)') {
            $result['exitCode'] = [string]$Matches[1]
            try {
                $result['exitCodeHex'] = ('0x{0:X8}' -f [uint32]([int64]$Matches[1]))
            } catch {
                $result['exitCodeHex'] = ''
            }
        }
        if ($text -match 'Most recent error:\s*([^"\r\n]+)') {
            $result['recentError'] = ([string]$Matches[1]).Trim()
        } elseif ($text -match 'message":"([^"]*write EPIPE[^"]*)"') {
            $result['recentError'] = ([string]$Matches[1]).Trim()
        }
        if ($text -match 'executablePath="([^"]*codex\.exe)"') {
            $result['spawnedPath'] = ([string]$Matches[1]) -replace '\\\\', '\'
        }
        if ($text -match 'OpenAI\.Codex_([0-9.]+)_x64__2p2nqsd0c76g0') {
            $result['spawnedVersion'] = [string]$Matches[1]
        }
    } catch {
        $result['readError'] = $_.Exception.Message
    }

    $pkg = Get-BootstrapCodexDesktopPackageInfo
    if (-not [string]::IsNullOrWhiteSpace([string]$result['spawnedVersion']) -and -not [string]::IsNullOrWhiteSpace([string]$pkg['version'])) {
        $result['staleSpawnedPackage'] = ([string]$result['spawnedVersion'] -ne [string]$pkg['version'])
    }

    return $result
}

function Get-BootstrapVcppRuntimeStatus {
    $required = @('vcruntime140.dll', 'vcruntime140_1.dll', 'msvcp140.dll')
    $system32 = Join-BootstrapKnownFolderPath -Base $env:WINDIR -ChildPath 'System32'
    if ([string]::IsNullOrWhiteSpace($system32) -or -not (Test-Path -LiteralPath $system32)) {
        # Sem System32 nao ha o que sondar. Reportar 'present' evita que um probe impossivel vire
        # "runtime ausente" e dispare reinstalacao do VCRedist sem motivo.
        return [ordered]@{
            present = $true
            missing = @()
            found = @()
            probeRoot = $system32
            probeSkipped = $true
            reason = 'system32-unavailable'
            wingetId = 'Microsoft.VCRedist.2015+.x64'
        }
    }

    $missing = @()
    $present = @()
    foreach ($dll in @($required)) {
        $path = Join-Path $system32 $dll
        if (Test-Path -LiteralPath $path) {
            $present += @($dll)
        } else {
            $missing += @($dll)
        }
    }

    return [ordered]@{
        present = ($missing.Count -eq 0)
        missing = @($missing)
        found = @($present)
        probeRoot = $system32
        probeSkipped = $false
        wingetId = 'Microsoft.VCRedist.2015+.x64'
    }
}

function Ensure-BootstrapCodexDesktopVcppRuntime {
    $before = Get-BootstrapVcppRuntimeStatus
    if ([bool]$before['present']) {
        return [ordered]@{ status = 'healthy'; reason = 'vcpp-runtime-present'; before = $before; after = $before }
    }

    $winget = Get-Winget
    if (-not $winget) {
        return [ordered]@{ status = 'failed'; reason = 'winget-ausente'; before = $before; after = $before }
    }

    try {
        Ensure-WingetPackage -WingetPath $winget -Id 'Microsoft.VCRedist.2015+.x64' -DisplayName 'Microsoft Visual C++ Redistributable 2015+ x64' -AllowFailureWhenNotAdmin $true
    } catch {
        $afterFailure = Get-BootstrapVcppRuntimeStatus
        return [ordered]@{ status = 'failed'; reason = $_.Exception.Message; before = $before; after = $afterFailure }
    }

    $after = Get-BootstrapVcppRuntimeStatus
    return [ordered]@{
        status = if ([bool]$after['present']) { 'installed' } else { 'attempted' }
        reason = if ([bool]$after['present']) { 'vcpp-runtime-installed' } else { 'vcpp-runtime-still-missing' }
        before = $before
        after = $after
    }
}

function Get-BootstrapCodexDesktopStateSummary {
    $rows = @()
    foreach ($path in @(Get-BootstrapCodexDesktopStatePaths)) {
        $row = [ordered]@{
            path = [string]$path
            exists = (Test-Path -LiteralPath $path)
            validJson = $false
            wslEnabled = $false
            terminalShell = ''
            issue = ''
        }
        if ([bool]$row['exists']) {
            try {
                $data = ConvertTo-BootstrapHashtable -InputObject ((Get-Content -LiteralPath $path -Raw -ErrorAction Stop) | ConvertFrom-Json -ErrorAction Stop)
                $row['validJson'] = $true
                foreach ($key in @('runCodexInWindowsSubsystemForLinux', 'runcodexinwindowssubsystemforlinux')) {
                    if ((Test-BootstrapMapContainsKey -Map $data -Key $key) -and (Test-BootstrapCodexTruthyValue -Value $data[$key])) {
                        $row['wslEnabled'] = $true
                    }
                }
                foreach ($key in @('integratedTerminalShell', 'terminalShell', 'shell')) {
                    if ((Test-BootstrapMapContainsKey -Map $data -Key $key) -and -not [string]::IsNullOrWhiteSpace([string]$data[$key])) {
                        $row['terminalShell'] = [string]$data[$key]
                        break
                    }
                }
            } catch {
                $row['issue'] = "json-invalido: $($_.Exception.Message)"
            }
        }
        $rows += @($row)
    }
    return @($rows)
}

function Test-BootstrapCodexConfigReadable {
    $pathEntries = @()
    try {
        $pathEntries = @(where.exe codex 2>$null | ForEach-Object { [string]$_ } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    } catch {
        $pathEntries = @()
    }
    $codexCmd = [string]($pathEntries | Where-Object { $_ -match '\.cmd$' } | Select-Object -First 1)
    if ([string]::IsNullOrWhiteSpace($codexCmd)) {
        $codexCmd = Resolve-CommandPath -Name 'codex'
    }
    if (-not $codexCmd) {
        return [ordered]@{ status = 'unknown'; reason = 'codex-cmd-ausente'; output = '' }
    }

    try {
        $output = (& $codexCmd @('debug', 'models') 2>&1 | ForEach-Object { [string]$_ }) -join [Environment]::NewLine
        $exitCode = $LASTEXITCODE
        $captured = $output
        if ($captured.Length -gt 500) { $captured = $captured.Substring(0, 500) + '...' }
        if ($exitCode -eq 0) {
            return [ordered]@{ status = 'valid'; reason = 'debug-models-parsed-config'; output = $captured }
        }
        if ($output -match '(?i)(config|toml|parse|invalid)') {
            return [ordered]@{ status = 'invalid'; reason = 'codex-config-parse-failed'; output = $captured }
        }
        return [ordered]@{ status = 'unknown'; reason = "exit-$exitCode"; output = $captured }
    } catch {
        return [ordered]@{ status = 'unknown'; reason = $_.Exception.Message; output = '' }
    }
}

function Get-BootstrapCodexDesktopDiagnostics {
    $package = Get-BootstrapCodexDesktopPackageInfo
    $cli = Get-BootstrapCodexCommandInfo
    $latestLog = Get-BootstrapCodexDesktopLatestLog
    $runtime = Get-BootstrapVcppRuntimeStatus
    $stateFiles = @(Get-BootstrapCodexDesktopStateSummary)
    $configPath = Join-Path (Get-BootstrapCodexHome) 'config.toml'
    $configStatus = Test-BootstrapCodexConfigReadable

    $issues = New-Object System.Collections.Generic.List[string]
    if (-not [bool]$package['installed']) {
        $issues.Add('codex-desktop-msix-ausente')
    }
    if ([string]$latestLog['exitCode'] -eq '3221225781') {
        $issues.Add('codex-app-server-crash-0xc0000135-epipe')
        if (-not [bool]$runtime['present']) {
            $issues.Add('vcpp-redist-missing-for-codex-desktop')
        }
    }
    if ([bool]$latestLog['staleSpawnedPackage']) {
        $issues.Add('codex-desktop-update-stale-process-or-log')
    }
    foreach ($state in @($stateFiles)) {
        if ([string]$state.issue -ne '') { $issues.Add('codex-global-state-json-invalido') }
        if ([bool]$state.wslEnabled -or ([string]$state.terminalShell).ToLowerInvariant() -eq 'wsl') {
            $issues.Add('codex-desktop-wsl-runtime-enabled')
        }
    }
    if ([string]$configStatus['status'] -eq 'invalid') {
        $issues.Add('codex-config-toml-invalido')
    }

    return [ordered]@{
        status = if ($issues.Count -gt 0) { 'needs-repair' } else { 'healthy' }
        issues = @($issues.ToArray() | Select-Object -Unique)
        package = $package
        cli = $cli
        runtime = $runtime
        latestLog = $latestLog
        stateFiles = @($stateFiles)
        configPath = $configPath
        configExists = (Test-Path -LiteralPath $configPath)
        configStatus = $configStatus
    }
}

function Repair-BootstrapCodexDesktopStateFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [switch]$DisableWslFallback
    )

    if (-not (Test-Path -LiteralPath $Path)) {
        return [ordered]@{ path = $Path; status = 'skipped'; reason = 'state-file-missing'; backup = '' }
    }

    $backup = ''
    $changes = New-Object System.Collections.Generic.List[string]
    try {
        $raw = Get-Content -LiteralPath $Path -Raw -ErrorAction Stop
        $data = $null
        if ([string]::IsNullOrWhiteSpace($raw)) {
            $data = [ordered]@{}
            $changes.Add('empty-state-normalized')
        } else {
            try {
                $data = ConvertTo-BootstrapHashtable -InputObject ($raw | ConvertFrom-Json -ErrorAction Stop)
            } catch {
                $backup = Backup-BootstrapFile -Path $Path
                Write-BootstrapJsonFile -Path $Path -Value ([ordered]@{})
                return [ordered]@{ path = $Path; status = 'repaired'; reason = 'invalid-json-reset'; backup = $backup; changes = @('invalid-json-reset') }
            }
        }

        if (-not ($data -is [hashtable])) { $data = [ordered]@{} }

        foreach ($key in @('runCodexInWindowsSubsystemForLinux', 'runcodexinwindowssubsystemforlinux')) {
            if ((Test-BootstrapMapContainsKey -Map $data -Key $key) -and (Test-BootstrapCodexTruthyValue -Value $data[$key])) {
                $data[$key] = $false
                $changes.Add("$key=false")
            }
        }

        if ($DisableWslFallback) {
            foreach ($key in @('integratedTerminalShell', 'terminalShell', 'shell')) {
                if ((Test-BootstrapMapContainsKey -Map $data -Key $key) -and ([string]$data[$key]).Trim().ToLowerInvariant() -eq 'wsl') {
                    $data[$key] = 'powershell'
                    $changes.Add("$key=powershell")
                }
            }
        }

        if ($changes.Count -eq 0) {
            return [ordered]@{ path = $Path; status = 'healthy'; reason = 'no-change'; backup = ''; changes = @() }
        }

        if ([string]::IsNullOrWhiteSpace($backup)) {
            $backup = Backup-BootstrapFile -Path $Path
        }
        Write-BootstrapJsonFile -Path $Path -Value $data
        return [ordered]@{ path = $Path; status = 'repaired'; reason = 'state-normalized'; backup = $backup; changes = @($changes.ToArray()) }
    } catch {
        return [ordered]@{ path = $Path; status = 'failed'; reason = $_.Exception.Message; backup = $backup; changes = @($changes.ToArray()) }
    }
}

function Repair-BootstrapCodexDesktopProcesses {
    param([string]$CurrentPackageFullName = '')

    $stopped = @()
    try {
        foreach ($proc in @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match '^(Codex|codex)$' })) {
            $path = ''
            try { $path = [string]$proc.Path } catch { $path = '' }
            if ([string]::IsNullOrWhiteSpace($path) -or $path -notmatch '\\WindowsApps\\OpenAI\.Codex_') { continue }
            if (-not [string]::IsNullOrWhiteSpace($CurrentPackageFullName) -and $path -match [regex]::Escape($CurrentPackageFullName)) { continue }
            try {
                Stop-Process -Id $proc.Id -Force -ErrorAction Stop
                $stopped += @([ordered]@{ id = [int]$proc.Id; path = $path; status = 'stopped' })
            } catch {
                $stopped += @([ordered]@{ id = [int]$proc.Id; path = $path; status = 'failed'; error = $_.Exception.Message })
            }
        }
    } catch {
        $stopped += @([ordered]@{ id = 0; path = ''; status = 'failed'; error = $_.Exception.Message })
    }
    return @($stopped)
}

function Repair-BootstrapCodexDesktop {
    $before = Get-BootstrapCodexDesktopDiagnostics
    $beforePkg = ConvertTo-BootstrapHashtable -InputObject $before['package']
    if (-not [bool]$beforePkg['installed'] -and -not [bool]$beforePkg['dataRootExists']) {
        # Sem Codex Desktop instalado nao ha reparo possivel. 'audited' aqui daria a impressao de
        # que o item mutante rodou; 'skipped' com motivo e o que de fato aconteceu.
        return [ordered]@{
            status = 'skipped'
            reason = 'codex-desktop-absent'
            note = 'Codex Desktop nao instalado; nada a reparar.'
            before = $before
            after = $before
        }
    }
    $runtimeResult = [ordered]@{ status = 'skipped'; reason = 'vcpp-runtime-present-or-not-needed' }
    if (@($before['issues']) -contains 'vcpp-redist-missing-for-codex-desktop') {
        $runtimeResult = Ensure-BootstrapCodexDesktopVcppRuntime
    }

    $stateResults = @()
    foreach ($path in @(Get-BootstrapCodexDesktopStatePaths)) {
        $stateResults += @(Repair-BootstrapCodexDesktopStateFile -Path $path -DisableWslFallback)
    }

    $beforePackage = ConvertTo-BootstrapHashtable -InputObject $before['package']
    $processResults = @(Repair-BootstrapCodexDesktopProcesses -CurrentPackageFullName ([string]$beforePackage['packageFullName']))
    $after = Get-BootstrapCodexDesktopDiagnostics

    $repairedCount = @($stateResults | Where-Object { [string]$_.status -eq 'repaired' }).Count
    $stoppedCount = @($processResults | Where-Object { [string]$_.status -eq 'stopped' }).Count
    $runtimeApplied = (@('installed', 'attempted') -contains [string]$runtimeResult['status'])
    $hadStaleUpdate = (@($before['issues']) -contains 'codex-desktop-update-stale-process-or-log')
    $hadCrash0135 = (@($before['issues']) -contains 'codex-app-server-crash-0xc0000135-epipe')

    $status = if ($repairedCount -gt 0 -or $stoppedCount -gt 0 -or $runtimeApplied) {
        'repaired'
    } elseif ($hadStaleUpdate -and -not [string]::IsNullOrWhiteSpace([string]$beforePackage['version'])) {
        'ready-to-reopen'
    } elseif ($hadCrash0135) {
        'action-required'
    } elseif ([string]$after['status'] -eq 'healthy') {
        'healthy'
    } else {
        'audited'
    }

    $note = switch ($status) {
        'repaired' { if ($runtimeApplied) { 'Codex Desktop runtime/state/process repair applied.' } else { 'Codex Desktop state/process repair applied.' } }
        'ready-to-reopen' { 'Ultimo crash usou pacote antigo; pacote atual ja instalado. Reabra Codex Desktop.' }
        'action-required' { 'Codex Desktop ainda registra 0xC0000135/EPIPE; reinstale/atualize OpenAI.Codex se reabrir falhar.' }
        'healthy' { 'Codex Desktop diagnostics healthy.' }
        default { 'Codex Desktop audited.' }
    }

    return [ordered]@{
        status = $status
        note = $note
        before = $before
        after = $after
        runtimeResult = $runtimeResult
        stateResults = @($stateResults)
        processResults = @($processResults)
    }
}

function Resolve-BootstrapPythonExecutable {
    foreach ($pythonExe in @(Get-BootstrapCommandPathCandidates -Name 'python')) {
        if (-not (Test-BootstrapPythonPathIsRuntimeOnly -Path $pythonExe)) { return $pythonExe }
    }

    Refresh-SessionPath
    foreach ($pythonExe in @(Get-BootstrapCommandPathCandidates -Name 'python')) {
        if (-not (Test-BootstrapPythonPathIsRuntimeOnly -Path $pythonExe)) { return $pythonExe }
    }

    $pyLauncher = Resolve-CommandPath -Name 'py'
    if ($pyLauncher -and (-not (Test-BootstrapPythonPathIsRuntimeOnly -Path $pyLauncher))) {
        try {
            $resolved = (& $pyLauncher -3 -c 'import sys; print(sys.executable)' 2>&1) | Select-Object -First 1
            if ($resolved -and (Test-Path $resolved) -and (-not (Test-BootstrapPythonPathIsRuntimeOnly -Path ([string]$resolved)))) { return [string]$resolved }
        } catch { }
    }

    $roots = @(
        (Join-Path $env:LOCALAPPDATA 'Programs\Python'),
        (Join-Path $env:ProgramFiles 'Python'),
        $env:ProgramFiles,
        ${env:ProgramFiles(x86)}
    ) | Where-Object { $_ -and (Test-Path $_) }

    foreach ($root in $roots) {
        $dirs = Get-ChildItem -Path $root -Directory -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -match '^Python3' } |
            Sort-Object Name -Descending
        foreach ($d in $dirs) {
            $candidate = Join-Path $d.FullName 'python.exe'
            if ((Test-Path $candidate) -and (-not (Test-BootstrapPythonPathIsRuntimeOnly -Path $candidate))) { return [string]$candidate }
        }
    }

    return $null
}

function Ensure-Uv {
    $uvExe = Resolve-CommandPath -Name 'uv'
    if (-not $uvExe) {
        Refresh-SessionPath
        $uvExe = Resolve-CommandPath -Name 'uv'
    }
    if ($uvExe) {
        $ver = Invoke-NativeFirstLine -Exe $uvExe -Args @('--version')
        Write-Log "uv já instalado: $ver ($uvExe)"
        return $uvExe
    }

    $pythonExe = Resolve-BootstrapPythonExecutable
    if (-not $pythonExe) { throw 'uv é necessario, mas nenhum python.exe real foi encontrado (PATH, py launcher ou instalações conhecidas). Garanta python-core antes de chamar uvtool.' }

    Write-Log "Instalando uv via pip ($pythonExe)..."
    $exitCode = Invoke-NativeWithRetry -Exe $pythonExe -Args @('-m', 'pip', 'install', '-U', '--upgrade-strategy', 'only-if-needed', 'uv') -OperationName 'instalacao do uv via pip'
    if ($exitCode -ne 0) { throw "Falha ao instalar uv via pip (exit=$exitCode)." }

    Refresh-SessionPath
    $uvExe = Resolve-CommandPath -Name 'uv'
    if (-not $uvExe) {
        $pythonDir = Split-Path -Parent $pythonExe
        $scriptsDir = Join-Path $pythonDir 'Scripts'
        if (Test-Path $scriptsDir) {
            Ensure-PathUserContains -Dir $scriptsDir
            Refresh-SessionPath
            $uvExe = Resolve-CommandPath -Name 'uv'
            if (-not $uvExe) {
                $candidate = Join-Path $scriptsDir 'uv.exe'
                if (Test-Path $candidate) { $uvExe = $candidate }
            }
        }
    }
    if (-not $uvExe) { throw 'Instalação do uv concluída, mas o comando uv nao foi encontrado no PATH.' }

    $ver = Invoke-NativeFirstLine -Exe $uvExe -Args @('--version')
    Write-Log "uv instalado: $ver ($uvExe)"
    return $uvExe
}

function Get-BootstrapNonEmptyStringArray {
    param([AllowNull()][string[]]$Values = @())

    return @($Values | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
}

function Ensure-UvToolPackage {
    param(
        [Parameter(Mandatory = $true)][string]$Package,
        [Parameter(Mandatory = $true)][string]$CommandName,
        [string]$DisplayName = $Package,
        [string[]]$VersionArgs = @('--version'),
        [string[]]$InstallArgs = @()
    )

    $sanitizedVersionArgs = Get-BootstrapNonEmptyStringArray -Values $VersionArgs
    $sanitizedInstallArgs = Get-BootstrapNonEmptyStringArray -Values $InstallArgs

    $exe = Resolve-CommandPath -Name $CommandName
    if ($exe) {
        $ver = Invoke-NativeFirstLine -Exe $exe -Args $sanitizedVersionArgs
        Write-Log "$DisplayName já instalado: $ver ($exe)"
        return
    }

    $uvExe = Ensure-Uv
    $localBin = Join-Path (Get-BootstrapUserHomePath) '.local\bin'
    $null = New-Item -Path $localBin -ItemType Directory -Force
    $env:UV_TOOL_BIN_DIR = $localBin

    # Prime o ambiente MSVC (cl.exe/INCLUDE/LIB) para o caso de a dependencia precisar compilar wheel
    # nativa; best-effort e idempotente (no-op se cl.exe ja resolve ou se o toolset nao existir).
    try { [void](Import-BootstrapMsvcEnvironment) } catch { }

    Write-Log "Instalando $DisplayName ($Package) via uv tool..."
    $installCommandArgs = @('tool', 'install', '--reinstall') + $sanitizedInstallArgs + @($Package)
    $exitCode = Invoke-NativeWithRetry -Exe $uvExe -Args $installCommandArgs -OperationName "$DisplayName via uv tool"

    Ensure-PathUserContains -Dir $localBin
    Refresh-SessionPath

    $exe = Resolve-CommandPath -Name $CommandName
    if (-not $exe) { throw "Instalação do $DisplayName concluída, mas o comando $CommandName nao foi encontrado no PATH." }

    if ($exitCode -ne 0) {
        Write-Log ("{0} retornou exit={1}, mas o comando {2} foi localizado no PATH; o bootstrap vai validar o binario e continuar." -f $DisplayName, $exitCode, $CommandName) 'WARN'
    }

    $ver = Invoke-NativeFirstLine -Exe $exe -Args $sanitizedVersionArgs
    Write-Log "$DisplayName instalado: $ver ($exe)"
}

function Ensure-Aider {
    Ensure-UvToolPackage -Package 'aider-chat' -CommandName 'aider' -DisplayName 'aider (aider-chat)' -VersionArgs @('--version')
}

function Ensure-Goose {
    param([Parameter(Mandatory = $true)][string]$BashPath)

    $gooseExe = Resolve-CommandPath -Name 'goose'
    if ($gooseExe) {
        $ver = Invoke-NativeFirstLine -Exe $gooseExe -Args @('--version')
        Write-Log "goose já instalado: $ver ($gooseExe)"
        return
    }

    $localBin = Join-Path (Get-BootstrapUserHomePath) '.local\bin'
    $null = New-Item -Path $localBin -ItemType Directory -Force
    Ensure-PathUserContains -Dir $localBin
    Refresh-SessionPath

    $destExe = Join-Path $localBin 'goose.exe'
    if (-not (Test-Path $destExe)) {
        $url = 'https://github.com/aaif-goose/goose/releases/download/stable/goose-x86_64-pc-windows-msvc.zip'
        $zipPath = Join-Path $env:TEMP ("goose_{0}.zip" -f ([Guid]::NewGuid().ToString('N')))
        $extractDir = Join-Path $env:TEMP ("goose_extract_{0}" -f ([Guid]::NewGuid().ToString('N')))
        try {
            Write-Log "Baixando goose (stable): $url"
            Invoke-WebRequestWithRetry -Uri $url -OutFile $zipPath -OperationName 'download do goose'
            Expand-Archive -Path $zipPath -DestinationPath $extractDir -Force
            $found = Get-ChildItem -Path $extractDir -Recurse -File -Filter 'goose.exe' -ErrorAction SilentlyContinue | Select-Object -First 1
            if (-not $found) { throw "Não encontrei goose.exe dentro do zip: $url" }
            Copy-Item -LiteralPath $found.FullName -Destination $destExe -Force
        } finally {
            if (Test-Path $zipPath) { Remove-Item -LiteralPath $zipPath -Force -ErrorAction SilentlyContinue }
            if (Test-Path $extractDir) { Remove-Item -LiteralPath $extractDir -Recurse -Force -ErrorAction SilentlyContinue }
        }
    }
    Refresh-SessionPath

    $gooseExe = Resolve-CommandPath -Name 'goose'
    if (-not $gooseExe) { throw 'Instalação do goose concluída, mas o comando goose nao foi encontrado no PATH.' }

    $ver = Invoke-NativeFirstLine -Exe $gooseExe -Args @('--version')
    Write-Log "goose instalado: $ver ($gooseExe)"
}

function Ensure-OpenCode {
    param([Parameter(Mandatory = $true)][string]$BashPath)
    $userProfileDir = Get-BootstrapUserHomePath
    $binDir = Join-Path $userProfileDir '.opencode\bin'
    $exe = Join-Path $binDir 'opencode.exe'
    $resolvedOpenCode = Resolve-CommandPath -Name 'opencode'

    if (Test-Path $exe) {
        $ver = & $exe --version
        Write-Log "opencode já instalado: $ver ($exe)"
    } elseif ($resolvedOpenCode) {
        $ver = Invoke-NativeFirstLine -Exe $resolvedOpenCode -Args @('--version')
        Write-Log "opencode ja instalado: $ver ($resolvedOpenCode)"
    } else {
        Write-Log 'Instalando opencode via script oficial...'
        $installCommand = @'
set -euo pipefail
tmp=$(mktemp "${TMPDIR:-/tmp}/phasezero-opencode.XXXXXX")
cleanup() { rm -f -- "$tmp"; }
trap cleanup EXIT
curl --proto '=https' --tlsv1.2 -fL --retry 3 --retry-delay 2 --connect-timeout 15 --max-time 120 https://opencode.ai/install -o "$tmp"
size=$(wc -c < "$tmp")
[ "$size" -ge 256 ] && [ "$size" -le 1048576 ]
head -n 1 "$tmp" | grep -q '^#!'
bash "$tmp"
'@
        $exitCode = Invoke-NativeWithRetry -Exe $BashPath -Args @('-lc', $installCommand) -OperationName 'instalacao do opencode via script oficial'
        if ($exitCode -ne 0) { throw "Falha ao instalar opencode via script oficial (exit=$exitCode)." }
        if (-not (Test-Path $exe)) { throw "Instalação do opencode concluída, mas nao encontrei: $exe" }
        $ver = & $exe --version
        Write-Log "opencode instalado: $ver ($exe)"
    }

    Ensure-PathUserContains -Dir $binDir
}

