function Ensure-HermesProjectOpenCloudConfig {
    param([Parameter(Mandatory = $true)][hashtable]$State)
    $path = Get-BootstrapHermesConfigPath -State $State
    if ([string]::IsNullOrWhiteSpace($path)) { throw 'Hermes: caminho de config nao resolvido.' }
    $settings = @{}
    if (Test-Path $path) {
        try {
            $settings = Read-BootstrapJsonFile -Path $path
            if (-not ($settings -is [hashtable])) { $settings = @{} }
        } catch {
            $backupPath = Backup-BootstrapFile -Path $path
            if ($backupPath) {
                Write-Log ("Hermes: config invalido; backup criado: {0}" -f $backupPath) 'WARN'
            }
            $settings = @{}
        }
    }
    $settings['schemaVersion'] = 1
    $settings['generatedAt'] = (Get-Date).ToString('o')
    $settings['tool'] = 'hermes'
    $opencloud = Ensure-BootstrapNamedMap -Parent $settings -Name 'opencloud'
    $opencloud['enabled'] = $true
    if (-not $opencloud.ContainsKey('mode') -or [string]::IsNullOrWhiteSpace([string]$opencloud['mode'])) {
        $opencloud['mode'] = 'project'
    }
    Write-BootstrapJsonFile -Path $path -Value $settings
    Write-Log "Hermes: config OpenCloud no projeto atualizado: $path"
}

function Ensure-Hermes {
    param([Parameter(Mandatory = $true)][hashtable]$State)
    Ensure-WslCore -State $State
    $catalog = Get-BootstrapAiToolCatalog
    $result = Install-BootstrapHermesAgentWsl -CatalogEntry $catalog['hermes-agent'] -InstallRoot (Get-BootstrapAiInstallRoot -InstallRoot '') -ProjectRoot (Get-Location).Path
    Write-Log ("Hermes Agent: {0} ({1})" -f [string]$result.status, [string]$result.version)
    Ensure-HermesProjectOpenCloudConfig -State $State
}

function Ensure-BootstrapOsSlimServer {
    # Enxuga o Windows para uso como servidor (menor RAM), de forma REVERSIVEL. Cada mutacao e
    # registrada (Register-BootstrapChange / Set-BootstrapServiceStartupTypes -State) para -Rollback.
    # NUNCA remove arquivos do usuario nem desabilita o shell grafico (Explorer/Winlogon); mantem o
    # SO utilizavel. Respeita -DryRun (nao muta o host). Mutacoes que exigem admin sao nao-fatais.
    param([Parameter(Mandatory = $true)][hashtable]$State)

    $dry = [bool]$State.DryRun
    Write-Log ("OS slim server: {0}..." -f $(if ($dry) { 'dry-run (sem alteracoes)' } else { 'aplicando enxugamento reversivel' }))

    # 1. Servicos nao-essenciais para servidor headless -> estado anterior salvo no manifesto.
    $serviceAdjustments = @(
        [pscustomobject]@{ Name = 'DiagTrack';       StartType = 'Disabled' }  # telemetria (Connected User Experiences)
        [pscustomobject]@{ Name = 'dmwappushservice'; StartType = 'Manual' }    # WAP Push (telemetria)
        [pscustomobject]@{ Name = 'WSearch';          StartType = 'Disabled' }  # indexacao/busca (RAM/IO)
        [pscustomobject]@{ Name = 'SysMain';          StartType = 'Disabled' }  # Superfetch (RAM/IO)
    )
    if (-not $dry) {
        Set-BootstrapServiceStartupTypes -State $State -ServiceAdjustments $serviceAdjustments -StopService
    }

    # 2. Tweaks de registro HKCU (efeitos visuais, apps de fundo, Game Bar/DVR), cada um registrado.
    $registryTweaks = @(
        [pscustomobject]@{ Path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects'; Name = 'VisualFXSetting'; Value = 2 }
        [pscustomobject]@{ Path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications'; Name = 'GlobalUserDisabled'; Value = 1 }
        [pscustomobject]@{ Path = 'HKCU:\Software\Microsoft\GameBar'; Name = 'AppCaptureEnabled'; Value = 0 }
        [pscustomobject]@{ Path = 'HKCU:\System\GameConfigStore'; Name = 'GameDVR_Enabled'; Value = 0 }
    )
    foreach ($tweak in $registryTweaks) {
        if ($dry) { continue }
        try {
            $old = $null
            if (Test-Path -LiteralPath $tweak.Path) {
                $existing = Get-ItemProperty -LiteralPath $tweak.Path -Name $tweak.Name -ErrorAction SilentlyContinue
                if ($existing) { $old = $existing.$($tweak.Name) }
            } else {
                $null = New-Item -Path $tweak.Path -Force -ErrorAction Stop
            }
            Register-BootstrapChange -State $State -Type 'Registry' -Target $tweak.Path -Name $tweak.Name -OldValue $old -NewValue $tweak.Value -Operation 'os-slim-tweak' -Component 'os-slim-server'
            Set-ItemProperty -LiteralPath $tweak.Path -Name $tweak.Name -Value $tweak.Value -Force -ErrorAction Stop
        } catch {
            Write-Log ("OS slim server: tweak {0}\{1} nao aplicado: {2}" -f $tweak.Path, $tweak.Name, $_.Exception.Message) 'WARN'
        }
    }

    # 3. Autostart do OneDrive: removido de forma REVERSIVEL (registra valor atual antes de remover).
    if (-not $dry) {
        $runPath = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
        try {
            if (Test-Path -LiteralPath $runPath) {
                $runItem = Get-ItemProperty -LiteralPath $runPath -ErrorAction SilentlyContinue
                if ($runItem) {
                    foreach ($prop in @($runItem.PSObject.Properties)) {
                        if ($prop.Name -like 'PS*') { continue }
                        if ($prop.Name -like 'OneDrive*') {
                            Register-BootstrapChange -State $State -Type 'Registry' -Target $runPath -Name $prop.Name -OldValue $prop.Value -NewValue $null -Operation 'os-slim-disable-onedrive' -Component 'os-slim-server'
                            Remove-ItemProperty -LiteralPath $runPath -Name $prop.Name -ErrorAction Stop
                            Write-Log ("OS slim server: autostart removido (reversivel) -> {0}" -f $prop.Name)
                        }
                    }
                }
            }
        } catch {
            Write-Log ("OS slim server: autostart OneDrive nao ajustado: {0}" -f $_.Exception.Message) 'WARN'
        }
    }

    # 4. Fast Startup/hibernacao desligados (reusa helper existente; exige admin, nao-fatal).
    if (-not $dry -and (Test-IsAdmin)) {
        try { $null = Repair-BootstrapFastStartup } catch { Write-Log ("OS slim server: Fast Startup nao ajustado: {0}" -f $_.Exception.Message) 'WARN' }
    }

    Write-Log ("OS slim server: {0}." -f $(if ($dry) { 'plano calculado (dry-run)' } else { 'enxugamento reversivel aplicado' }))
}

function Ensure-BootstrapGpeditHardening {
    # Aplica o pacote de hardening de privacidade/telemetria/IA do gpedit (Configuracao do Computador
    # e do Usuario) como tweaks de registro REVERSIVEIS (Apply-BootstrapRegistryDword registra o valor
    # anterior para -Rollback). NAO inclui o bloqueio agressivo "Forcar Negacao" de privacidade de apps
    # (camera/mic/local), que pode quebrar apps legitimos. NAO mexe no shell nem remove arquivos.
    param([Parameter(Mandatory = $true)][hashtable]$State)

    $dry = [bool]$State.DryRun
    Write-Log ("gpedit hardening: {0}..." -f $(if ($dry) { 'dry-run (sem alteracoes)' } else { 'aplicando politicas reversiveis' }))
    if ($dry) { return }

    # Cada item: Path (HKLM/HKCU Policies), Name, Value (DWORD). Politicas documentadas equivalentes
    # ao que o gpedit grava. Reversiveis individualmente.
    $policies = @(
        # 1. Telemetria (Permitir Dados de Diagnostico -> 0)
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection'; Name = 'AllowTelemetry'; Value = 0 }
        # 2. Compatibilidade de Aplicativos (telemetria/inventario/PCA/Steps Recorder/engine)
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppCompat'; Name = 'AITEnable'; Value = 0 }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppCompat'; Name = 'DisableInventory'; Value = 1 }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppCompat'; Name = 'DisablePCA'; Value = 1 }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppCompat'; Name = 'DisableUAR'; Value = 1 }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppCompat'; Name = 'DisableEngine'; Value = 1 }
        # 3. Conteudo de Nuvem (experiencias do consumidor/dicas/conteudo otimizado)
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent'; Name = 'DisableWindowsConsumerFeatures'; Value = 1 }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent'; Name = 'DisableSoftLanding'; Value = 1 }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent'; Name = 'DisableCloudOptimizedContent'; Value = 1 }
        # 4. Atualizacao automatica de dados de fala
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Speech'; Name = 'AllowSpeechModelUpdate'; Value = 0 }
        # 5. Explorador: insights baseados em conta/recentes
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Explorer'; Name = 'DisableGraphRecentItems'; Value = 1 }
        # 6. IA do Windows: Recall / analise de dados
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsAI'; Name = 'DisableAIDataAnalysis'; Value = 1 }
        # 7. Instalacao por Push
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\PushToInstall'; Name = 'DisablePushToInstall'; Value = 1 }
        # 8. Fornecedor de Local do Windows
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LocationAndSensors'; Name = 'DisableWindowsLocationProvider'; Value = 1 }
        # 9. Localizar Meu Dispositivo
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\FindMyDevice'; Name = 'AllowFindMyDevice'; Value = 0 }
        # 10. Loja: download/instalacao automatica de updates
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\WindowsStore'; Name = 'AutoDownload'; Value = 2 }
        # 11-12. Edge: preload e pre-inicializacao
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\MicrosoftEdge\Main'; Name = 'AllowPrelaunch'; Value = 0 }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\MicrosoftEdge\TabPreloader'; Name = 'AllowTabPreloading'; Value = 0 }
        # 13. Pesquisar: Cortana, pesquisa na nuvem, web em pesquisa
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search'; Name = 'AllowCortana'; Value = 0 }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search'; Name = 'AllowCloudSearch'; Value = 0 }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search'; Name = 'ConnectedSearchUseWeb'; Value = 0 }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search'; Name = 'DisableWebSearch'; Value = 1 }
        # 16-17. Relatorios de Erros do Windows
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Error Reporting'; Name = 'Disabled'; Value = 1 }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Error Reporting'; Name = 'LoggingDisabled'; Value = 1 }
        # 18. Nao sincronizar configuracoes
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\SettingSync'; Name = 'DisableSettingSync'; Value = 2 }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\SettingSync'; Name = 'DisableSettingSyncUserOverride'; Value = 1 }
        # 19. Widgets
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Dsh'; Name = 'AllowNewsAndInterests'; Value = 0 }
        # 23. Desligar o ID de anuncio
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\AdvertisingInfo'; Name = 'DisabledByGroupPolicy'; Value = 1 }
        # 24. Activity Feed / Timeline / Clipboard sync
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\System'; Name = 'EnableActivityFeed'; Value = 0 }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\System'; Name = 'PublishUserActivities'; Value = 0 }
        @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\System'; Name = 'UploadUserActivities'; Value = 0 }
        # 22. (Usuario) Menu Iniciar: nao manter historico de documentos recentes
        @{ Path = 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer'; Name = 'NoRecentDocsHistory'; Value = 1 }
    )

    $applied = 0
    foreach ($p in $policies) {
        try {
            Apply-BootstrapRegistryDword -State $State -Path $p.Path -Name $p.Name -Value $p.Value
            $applied++
        } catch {
            Write-Log ("gpedit hardening: politica {0}\{1} nao aplicada: {2}" -f $p.Path, $p.Name, $_.Exception.Message) 'WARN'
        }
    }
    Write-Log ("gpedit hardening: {0} politica(s) reversivel(eis) aplicada(s). (Bloqueio agressivo de privacidade de apps NAO incluido por padrao.)" -f $applied)
}

function Get-BootstrapLlamaOffloadPlan {
    # Calcula o plano de offload do llama.cpp (camadas na GPU vs CPU) para um modelo GGUF, dado o
    # hardware. Deterministico e sem efeitos colaterais (testavel). Porta da logica do parecer tecnico.
    param(
        [Parameter(Mandatory = $true)][double]$VramGB,
        [Parameter(Mandatory = $true)][double]$RamGB,
        [Parameter(Mandatory = $true)][double]$ModelSizeGB,
        [Parameter(Mandatory = $true)][int]$TotalLayers,
        [double]$SystemMarginGB = 1.0
    )

    $vramUtil = $VramGB - $SystemMarginGB
    $physicalCores = [Math]::Max(2, [int]([Environment]::ProcessorCount / 2))

    # Cenario 1: o modelo cabe inteiro na VRAM utilizavel -> performance maxima.
    if ($ModelSizeGB -lt $vramUtil) {
        return [ordered]@{ gpuLayers = $TotalLayers; cpuThreads = 1; lowVram = $false; insufficient = $false; vramUtilGB = $vramUtil }
    }

    # Cenario 2: excede a VRAM mas cabe na soma VRAM+RAM -> split hibrido proporcional.
    if ($ModelSizeGB -lt ($vramUtil + $RamGB)) {
        $fraction = if ($ModelSizeGB -gt 0) { $vramUtil / $ModelSizeGB } else { 0 }
        $gpuLayers = [Math]::Max(1, [int]($TotalLayers * $fraction) - 2)
        return [ordered]@{ gpuLayers = $gpuLayers; cpuThreads = $physicalCores; lowVram = $true; insufficient = $false; vramUtilGB = $vramUtil }
    }

    # Cenario 3: nem a soma cabe.
    return [ordered]@{ gpuLayers = 0; cpuThreads = $physicalCores; lowVram = $true; insufficient = $true; vramUtilGB = $vramUtil }
}

function Get-BootstrapLlamaPerformanceProfile {
    # Perfis de performance do LLM local (llama.cpp): otimizar velocidade de token, capacidade
    # (qualidade/contexto) ou moderado. Deterministico (testavel). Mapeia para flags reais do
    # llama-server (--ctx-size, --cache-type-k/v, --flash-attn) e um quant tier GGUF sugerido.
    param([ValidateSet('speed', 'capacity', 'moderate')][string]$Mode = 'moderate')

    switch ($Mode) {
        'speed' {
            return [ordered]@{
                mode = 'speed'; priority = 'Maxima velocidade de token (t/s)'; ctxSize = 2048;
                cacheTypeK = 'q4_0'; cacheTypeV = 'q4_0'; flashAttn = $true; batchSize = 512;
                quantTier = 'Q4_K_M'; maxGpuOffload = $true;
                description = 'Quant menor + KV cache q4_0 + contexto curto: mais tokens/s, menos qualidade/contexto.'
            }
        }
        'capacity' {
            return [ordered]@{
                mode = 'capacity'; priority = 'Maxima capacidade (qualidade e contexto)'; ctxSize = 8192;
                cacheTypeK = 'f16'; cacheTypeV = 'f16'; flashAttn = $true; batchSize = 512;
                quantTier = 'Q6_K'; maxGpuOffload = $false;
                description = 'Quant maior + KV cache f16 + contexto longo: melhor qualidade/contexto, menos tokens/s.'
            }
        }
        default {
            return [ordered]@{
                mode = 'moderate'; priority = 'Equilibrio entre velocidade e capacidade'; ctxSize = 4096;
                cacheTypeK = 'q8_0'; cacheTypeV = 'q8_0'; flashAttn = $true; batchSize = 512;
                quantTier = 'Q4_K_M'; maxGpuOffload = $true;
                description = 'Quant equilibrado + KV cache q8_0 + contexto medio: bom meio-termo.'
            }
        }
    }
}

function Get-BootstrapGgufDownloadUrl {
    # Monta a URL de download direto de um GGUF no Hugging Face (resolve/main). Deterministico.
    param(
        [Parameter(Mandatory = $true)][string]$Repo,
        [Parameter(Mandatory = $true)][string]$File
    )
    return ("https://huggingface.co/{0}/resolve/main/{1}" -f $Repo.Trim('/'), $File)
}

function Get-BootstrapGgufModelCatalog {
    # Catalogo curado de modelos GGUF recomendados, marcados por perfil de performance. Sugestoes
    # (o usuario pode baixar outro). Tamanhos aproximados. Sem efeitos colaterais.
    return @(
        [ordered]@{ id = 'qwen2.5-3b-speed';    repo = 'Qwen/Qwen2.5-3B-Instruct-GGUF';  file = 'qwen2.5-3b-instruct-q4_k_m.gguf';  profile = 'speed';    quant = 'Q4_K_M'; sizeGB = 2.0;  displayName = 'Qwen2.5 3B Instruct (Q4_K_M)' }
        [ordered]@{ id = 'qwen2.5-7b-moderate'; repo = 'Qwen/Qwen2.5-7B-Instruct-GGUF';  file = 'qwen2.5-7b-instruct-q4_k_m.gguf';  profile = 'moderate'; quant = 'Q4_K_M'; sizeGB = 4.7;  displayName = 'Qwen2.5 7B Instruct (Q4_K_M)' }
        [ordered]@{ id = 'qwen2.5-14b-capacity'; repo = 'Qwen/Qwen2.5-14B-Instruct-GGUF'; file = 'qwen2.5-14b-instruct-q6_k.gguf';     profile = 'capacity'; quant = 'Q6_K';   sizeGB = 12.1; displayName = 'Qwen2.5 14B Instruct (Q6_K)' }
    )
}

function Resolve-BootstrapGgufModelForProfile {
    # Escolhe um modelo recomendado do catalogo para o perfil de performance pedido. Deterministico.
    param([ValidateSet('speed', 'capacity', 'moderate')][string]$Mode = 'moderate')
    $catalog = @(Get-BootstrapGgufModelCatalog)
    $match = @($catalog | Where-Object { [string]$_.profile -eq $Mode }) | Select-Object -First 1
    if (-not $match) { $match = @($catalog | Where-Object { [string]$_.profile -eq 'moderate' }) | Select-Object -First 1 }
    return $match
}

function Install-BootstrapGgufModel {
    # Baixa (guiado) um GGUF do Hugging Face para o diretorio de modelos. Best-effort, registra o
    # arquivo criado para rollback. Respeita -DryRun. Modelos sao grandes: so baixa quando chamado.
    param(
        [Parameter(Mandatory = $true)][string]$Repo,
        [Parameter(Mandatory = $true)][string]$File,
        [Parameter(Mandatory = $true)][string]$ModelsDir,
        [AllowNull()][hashtable]$State = $null,
        [switch]$DryRun
    )

    $url = Get-BootstrapGgufDownloadUrl -Repo $Repo -File $File
    $dest = Join-Path $ModelsDir $File
    if ($DryRun) {
        return [ordered]@{ status = 'planned'; url = $url; path = $dest }
    }

    if (Test-Path -LiteralPath $dest) {
        return [ordered]@{ status = 'already-present'; url = $url; path = $dest }
    }
    [void][System.IO.Directory]::CreateDirectory($ModelsDir)
    if ($State -is [hashtable]) {
        try { Register-BootstrapFileChange -State $State -Target $dest -Operation 'gguf-download' -Component 'llamacpp-server' } catch { }
    }
    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        Write-Log ("GGUF: baixando {0} de {1} (pode levar varios minutos)..." -f $File, $Repo)
        Invoke-WebRequest -Uri $url -OutFile $dest -UseBasicParsing -Headers @{ 'User-Agent' = 'PhaseZero-Bootstrap' } -ErrorAction Stop
        Write-Log ("GGUF: modelo salvo em {0}" -f $dest)
        return [ordered]@{ status = 'downloaded'; url = $url; path = $dest }
    } catch {
        Write-Log ("GGUF: download falhou ({0}); baixe manualmente de {1}" -f $_.Exception.Message, $url) 'WARN'
        return [ordered]@{ status = 'failed'; url = $url; path = $dest; error = $_.Exception.Message }
    }
}

function Select-BootstrapLlamaCppAsset {
    # Escolhe o asset Windows x64 do release do llama.cpp conforme a preferencia de GPU. Deterministico
    # (testavel). Exclui o pacote 'cudart' (runtime CUDA, nao o binario principal). Retorna $null se nao
    # houver asset Windows x64 adequado.
    param(
        [string[]]$AssetNames,
        [ValidateSet('cuda', 'vulkan', 'cpu')][string]$Prefer = 'cpu'
    )

    $win = @($AssetNames | Where-Object { $_ -match 'bin-win' -and $_ -match 'x64' -and $_ -notmatch '^cudart' })
    if (@($win).Count -eq 0) { return $null }

    $order = switch ($Prefer) {
        'cuda'   { @('bin-win-cuda', 'bin-win-vulkan', 'bin-win-cpu') }
        'vulkan' { @('bin-win-vulkan', 'bin-win-cpu') }
        default  { @('bin-win-cpu') }
    }
    foreach ($pat in $order) {
        $hit = @($win | Where-Object { $_ -match [regex]::Escape($pat) }) | Select-Object -First 1
        if ($hit) { return [string]$hit }
    }
    return $null
}

function Get-BootstrapLlamaCppGpuPreference {
    # Detecta o fornecedor da GPU para escolher o build do llama.cpp (cuda/vulkan/cpu). Best-effort.
    $names = @()
    try { $names = @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop | ForEach-Object { [string]$_.Name }) } catch { $names = @() }
    $joined = ($names -join ' ').ToLowerInvariant()
    if ($joined -match 'nvidia|geforce|rtx|quadro|tesla') { return 'cuda' }
    if ($joined -match 'amd|radeon|intel|arc') { return 'vulkan' }
    return 'cpu'
}

function Ensure-BootstrapLlamaCppServer {
    # Componente opt-in (experimental): provisiona o launcher resiliente do llama.cpp para servir um
    # LLM local em :8080 com offload hibrido GPU/CPU. Baixa do release oficial fica como passo guiado
    # (driver/binarios de terceiros); o componente garante o launcher e instrucoes. Respeita -DryRun.
    param([Parameter(Mandatory = $true)][hashtable]$State)

    $dry = [bool]$State.DryRun
    $root = Get-BootstrapAiInstallRoot -InstallRoot ''
    $targetDir = Join-Path $root 'llamacpp'
    $launcherSrc = Join-Path $PSScriptRoot 'assets\home-server\run-llamacpp.ps1'
    $launcherDst = Join-Path $targetDir 'run-llamacpp.ps1'

    Write-Log ("llama.cpp server: {0} (destino {1})..." -f $(if ($dry) { 'dry-run' } else { 'provisionando launcher' }), $targetDir)
    if ($dry) { return }

    if (-not (Test-Path -LiteralPath $targetDir)) { $null = New-Item -Path $targetDir -ItemType Directory -Force }
    if (Test-Path -LiteralPath $launcherSrc) {
        Register-BootstrapFileChange -State $State -Target $launcherDst -Operation 'llamacpp-launcher' -Component 'llamacpp-server'
        Copy-Item -LiteralPath $launcherSrc -Destination $launcherDst -Force
        Write-Log ("llama.cpp server: launcher instalado em {0}" -f $launcherDst)
    } else {
        Write-Log ("llama.cpp server: launcher-fonte ausente: {0}" -f $launcherSrc) 'WARN'
    }
    # Fetch real do binario (best-effort, NAO-FATAL): release oficial -> asset por GPU detectada.
    try {
        $pref = Get-BootstrapLlamaCppGpuPreference
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        $rel = Invoke-RestMethod -Uri 'https://api.github.com/repos/ggml-org/llama.cpp/releases/latest' -Headers @{ 'User-Agent' = 'PhaseZero-Bootstrap' } -ErrorAction Stop
        $assetNames = @($rel.assets | ForEach-Object { [string]$_.name })
        $pick = Select-BootstrapLlamaCppAsset -AssetNames $assetNames -Prefer $pref
        if ($pick) {
            $assetObj = @($rel.assets | Where-Object { [string]$_.name -eq $pick })[0]
            $dlUrl = [string]$assetObj.browser_download_url
            $downloadRoot = Join-Path $targetDir 'downloads'
            [void][System.IO.Directory]::CreateDirectory($downloadRoot)
            $zipPath = Join-Path $downloadRoot $pick
            Write-Log ("llama.cpp server: baixando build '{0}' ({1}, GPU={2})..." -f $pick, [string]$rel.tag_name, $pref)
            Invoke-WebRequest -Uri $dlUrl -OutFile $zipPath -UseBasicParsing -Headers @{ 'User-Agent' = 'PhaseZero-Bootstrap' } -ErrorAction Stop
            Expand-Archive -LiteralPath $zipPath -DestinationPath $targetDir -Force
            $serverExe = Get-ChildItem -LiteralPath $targetDir -Recurse -Filter 'llama-server.exe' -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($serverExe) {
                Write-Log ("llama.cpp server: binario instalado em {0} (build {1})." -f $serverExe.FullName, [string]$rel.tag_name)
            } else {
                Write-Log 'llama.cpp server: zip extraido, mas llama-server.exe nao encontrado; verifique o release.' 'WARN'
            }
        } else {
            Write-Log ("llama.cpp server: nenhum asset Windows x64 adequado no release (GPU={0}); baixe manualmente." -f $pref) 'WARN'
        }
    } catch {
        Write-Log ("llama.cpp server: download automatico do binario falhou ({0}); use o passo guiado manual." -f $_.Exception.Message) 'WARN'
    }
    # Guia de modelos: recomenda um GGUF por perfil de performance (velocidade/moderado/capacidade).
    Write-Log 'llama.cpp server: escolha o foco com -PerfMode no launcher (speed = mais t/s, capacity = qualidade/contexto, moderate = equilibrio). Modelos GGUF recomendados por perfil:'
    foreach ($mode in @('speed', 'moderate', 'capacity')) {
        $m = Resolve-BootstrapGgufModelForProfile -Mode $mode
        if ($m) {
            Write-Log ("  [{0}] {1} (~{2}GB) -> {3}" -f $mode, [string]$m.displayName, [double]$m.sizeGB, (Get-BootstrapGgufDownloadUrl -Repo $m.repo -File $m.file))
        }
    }
    Write-Log 'llama.cpp server: baixe o GGUF (Install-BootstrapGgufModel ou manual) e rode run-llamacpp.ps1 -ModelPath <gguf> -PerfMode <speed|capacity|moderate>. O launcher reduz --n-gpu-layers automaticamente em caso de estouro de VRAM.'
}

function Ensure-BootstrapHermesRemote {
    # Habilita o Hermes para atuacao remota: garante a config OpenCloud do projeto, cura o launch dos
    # MCP (Windows-safe) e conecta o Tailscale (authkey via TS_AUTHKEY/secrets, NUNCA hardcode). O
    # Hermes deve ser acessado apenas pela rede Tailscale, nunca em 0.0.0.0 publico. Respeita -DryRun.
    param([Parameter(Mandatory = $true)][hashtable]$State)

    $dry = [bool]$State.DryRun
    Write-Log ("hermes-remote: {0}..." -f $(if ($dry) { 'dry-run (sem alteracoes)' } else { 'configurando atuacao remota' }))
    if ($dry) { return }

    try { Ensure-HermesProjectOpenCloudConfig -State $State } catch { Write-Log ("hermes-remote: config OpenCloud nao ajustada: {0}" -f $_.Exception.Message) 'WARN' }
    try {
        $hermesCfg = Get-BootstrapHermesConfigPath -State $State
        if ($hermesCfg) { $null = Invoke-BootstrapMcpConfigRepair -ConfigPaths @($hermesCfg) -State $State }
    } catch { Write-Log ("hermes-remote: reparo MCP do Hermes falhou: {0}" -f $_.Exception.Message) 'WARN' }

    $authKey = [string]$env:TS_AUTHKEY
    $tailscaleExe = [string](Resolve-CommandPath -Name 'tailscale')
    if ([string]::IsNullOrWhiteSpace($tailscaleExe)) {
        Write-Log 'hermes-remote: tailscale.exe nao encontrado (o componente tailscale e dependencia). Instale e rode novamente.' 'WARN'
    } elseif (-not [string]::IsNullOrWhiteSpace($authKey)) {
        $up = Invoke-BootstrapCommandCapture -Exe $tailscaleExe -Args @('up', '--authkey', $authKey, '--accept-dns=true')
        if ([int]$up.ExitCode -eq 0) { Write-Log 'hermes-remote: Tailscale conectado via authkey (valor mascarado).' }
        else { Write-Log ("hermes-remote: 'tailscale up' falhou (exit={0}); rode manualmente." -f [int]$up.ExitCode) 'WARN' }
    } else {
        Write-Log 'hermes-remote: defina TS_AUTHKEY (env/secrets) para conectar o Tailscale sem interacao, ou rode "tailscale up" manualmente. Exponha o Hermes apenas pela interface Tailscale.'
    }
    Write-Log 'hermes-remote: pronto. Atue no Hermes remotamente apenas pela rede Tailscale.'
}

function Get-BootstrapHomelabComposePath {
    # Resolve o diretorio de estado do homelab-stack (onde os composes/.env sao copiados).
    param([AllowNull()][hashtable]$State = $null)
    $root = Get-BootstrapAiInstallRoot -InstallRoot ''
    return (Join-Path (Join-Path $root 'homelab') 'docker-compose.homelab.yml')
}

function New-BootstrapHomelabSecret {
    # Segredo aleatorio para o .env do homelab (nunca hardcode no compose). Sem dependencias externas.
    return (([guid]::NewGuid().ToString('N')) + ([guid]::NewGuid().ToString('N')))
}

function Ensure-BootstrapHomelabStack {
    # Provisiona o stack de homelab via Docker (backend WSL2): camada CORE leve (Portainer, Jellyfin,
    # Syncthing, Vaultwarden, Uptime Kuma). Extras pesados (Nextcloud/Grafana/Paperless/n8n) ficam no
    # compose de extras, aplicados manualmente/opt-in. Segredos gerados no .env (nunca inline). -DryRun.
    param([Parameter(Mandatory = $true)][hashtable]$State)

    $dry = [bool]$State.DryRun
    $composeDst = Get-BootstrapHomelabComposePath -State $State
    $stackDir = Split-Path -Parent $composeDst
    $extrasDst = Join-Path $stackDir 'docker-compose.extras.yml'
    $envPath = Join-Path $stackDir '.env'
    $coreSrc = Join-Path $PSScriptRoot 'assets\home-server\docker-compose.homelab.yml'
    $extrasSrc = Join-Path $PSScriptRoot 'assets\home-server\docker-compose.extras.yml'

    Write-Log ("homelab-stack: {0} (destino {1})..." -f $(if ($dry) { 'dry-run' } else { 'provisionando' }), $stackDir)
    if ($dry) { return }

    if (-not (Test-Path -LiteralPath $stackDir)) { $null = New-Item -Path $stackDir -ItemType Directory -Force }

    foreach ($pair in @(@{ Src = $coreSrc; Dst = $composeDst }, @{ Src = $extrasSrc; Dst = $extrasDst })) {
        if (Test-Path -LiteralPath $pair.Src) {
            Register-BootstrapFileChange -State $State -Target $pair.Dst -Operation 'homelab-compose' -Component 'homelab-stack'
            Copy-Item -LiteralPath $pair.Src -Destination $pair.Dst -Force
        } else {
            Write-Log ("homelab-stack: compose-fonte ausente: {0}" -f $pair.Src) 'WARN'
        }
    }

    # .env com segredos gerados (idempotente: nao rotaciona se ja existe). Nunca logar os valores.
    if (-not (Test-Path -LiteralPath $envPath)) {
        Register-BootstrapFileChange -State $State -Target $envPath -Operation 'homelab-env' -Component 'homelab-stack'
        $envLines = @(
            ("VW_ADMIN_TOKEN={0}" -f (New-BootstrapHomelabSecret)),
            'VW_SIGNUPS_ALLOWED=false',
            ("NEXTCLOUD_DB_ROOT_PASSWORD={0}" -f (New-BootstrapHomelabSecret)),
            ("NEXTCLOUD_DB_PASSWORD={0}" -f (New-BootstrapHomelabSecret)),
            ("GRAFANA_ADMIN_PASSWORD={0}" -f (New-BootstrapHomelabSecret)),
            ("PAPERLESS_SECRET_KEY={0}" -f (New-BootstrapHomelabSecret)),
            ("N8N_ENCRYPTION_KEY={0}" -f (New-BootstrapHomelabSecret))
        )
        [System.IO.File]::WriteAllText($envPath, ($envLines -join [Environment]::NewLine), [System.Text.UTF8Encoding]::new($false))
        Write-Log 'homelab-stack: .env gerado com segredos aleatorios (valores mascarados).'
    }

    if (-not (Test-DockerReady)) {
        Write-Log 'homelab-stack: Docker indisponivel (instale/abra Docker Desktop ou habilite docker no WSL2). Composes/.env prontos; suba manualmente com: docker compose -f docker-compose.homelab.yml up -d' 'WARN'
        return
    }

    $dockerExe = [string](Resolve-CommandPath -Name 'docker')
    $up = Invoke-BootstrapCommandCapture -Exe $dockerExe -Args @('compose', '--project-directory', $stackDir, '-f', $composeDst, 'up', '-d')
    if ([int]$up.ExitCode -ne 0) {
        Write-Log ("homelab-stack: 'docker compose up' falhou (exit={0}); suba manualmente apos checar o Docker." -f [int]$up.ExitCode) 'WARN'
        return
    }
    Write-Log 'homelab-stack: camada CORE no ar (Portainer :9000, Jellyfin :8096, Syncthing :8384, Vaultwarden :8222, Uptime Kuma :3001). Extras opt-in: docker compose -f docker-compose.extras.yml up -d. Exponha apenas via Tailscale.'
}

function Install-BootstrapAiUsagebarComponent {
    param([Parameter(Mandatory = $true)][hashtable]$State)
    $null = $State
    $catalog = Get-BootstrapAiToolCatalog
    $result = Install-BootstrapAiUsagebar -CatalogEntry $catalog['ai-usagebar'] -InstallRoot (Get-BootstrapAiInstallRoot -InstallRoot '') -ProjectRoot (Get-Location).Path
    Write-Log ("ai-usagebar: {0} ({1}) {2}" -f [string]$result.status, [string]$result.version, [string]$result.message)
    if ([string]$result.status -eq 'blocked') {
        throw ([string]$result.message)
    }
}

function Install-BootstrapAiMemoryComponent {
    param([Parameter(Mandatory = $true)][hashtable]$State)
    $null = $State
    $catalog = Get-BootstrapAiToolCatalog
    $root = Get-BootstrapAiInstallRoot -InstallRoot ''
    $project = (Get-Location).Path
    $result = Install-BootstrapAiMemory -CatalogEntry $catalog['ai-memory'] -InstallRoot $root -ProjectRoot $project
    Write-Log ("ai-memory: {0} ({1}) {2}" -f [string]$result.status, [string]$result.version, [string]$result.message)
    if ([string]$result.status -eq 'blocked') {
        throw ([string]$result.message)
    }
    # configure = task de servidor loopback + wiring MCP/hooks por agente detectado (idempotente).
    $configure = Set-BootstrapAiMemoryConfig -InstallRoot $root -ProjectRoot $project
    Write-Log ("ai-memory configure: {0} {1}" -f [string]$configure.status, [string]$configure.message)
    # SDCard sync (ja acionado dentro de Set-BootstrapAiMemoryConfig; log extra aqui)
    if ($configure.Contains('sdSync') -and $configure['sdSync']) {
        $sync = $configure['sdSync']
        if ($sync.sdCardFound) {
            Write-Log ("ai-memory sd-sync: direcao={0} synced={1}" -f $sync.direction, $sync.synced) 'INFO'
        }
    }
    if ($configure.Contains('syncTask') -and $configure['syncTask']) {
        Write-Log ("ai-memory sync-task: {0}" -f [string]$configure['syncTask']['status']) 'INFO'
    }
}

function Install-BootstrapAionUiComponent {
    param([Parameter(Mandatory = $true)][hashtable]$State)
    $catalog = Get-BootstrapAiToolCatalog
    $result = Install-BootstrapAionUiComponentPackage -CatalogEntry $catalog['aionui'] -State $State -NoAdmin:(-not (Test-IsAdmin))
    Write-Log ("AionUI: {0} ({1}) {2}" -f [string]$result.status, [string]$result.version, [string]$result.message)
    if ([string]$result.status -eq 'blocked') {
        throw ([string]$result.message)
    }
}

function Ensure-RepoClone {
    param(
        [Parameter(Mandatory = $true)][string]$GitExe,
        [Parameter(Mandatory = $true)][string]$RepoUrl,
        [Parameter(Mandatory = $true)][string]$TargetDir
    )
    if (Test-Path $TargetDir) {
        Write-Log "Diretório já existe, pulando clone: $TargetDir"
        return
    }
    Write-Log "Clonando $RepoUrl em $TargetDir"
    $exitCode = Invoke-NativeWithRetry -Exe $GitExe -Args @('clone', $RepoUrl, $TargetDir) -OperationName "clone de $RepoUrl"
    if ($exitCode -ne 0) { throw "Falha ao clonar repositório (exit=$exitCode): $RepoUrl" }
    Write-Log "Clone concluído: $TargetDir"
}

function Resolve-CommandPath {
    param([Parameter(Mandatory = $true)][string]$Name)
    $cmd = Get-Command $Name -ErrorAction SilentlyContinue
    if (-not $cmd) { return $null }

    if ($cmd -is [System.Management.Automation.AliasInfo]) {
        return (Resolve-CommandPath -Name ([string]$cmd.Definition))
    }

    if ($cmd.CommandType -in @('Application', 'ExternalScript')) {
        $path = [string]$cmd.Source
        if (-not [string]::IsNullOrWhiteSpace($path) -and (Test-Path $path)) {
            return $path
        }
    }
    return $null
}

function Get-BootstrapCommandPathCandidates {
    param([Parameter(Mandatory = $true)][string]$Name)

    $paths = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    foreach ($cmd in @(Get-Command $Name -All -ErrorAction SilentlyContinue)) {
        if ($cmd -is [System.Management.Automation.AliasInfo]) { continue }
        if ($cmd.CommandType -notin @('Application', 'ExternalScript')) { continue }

        $path = [string]$cmd.Source
        if ([string]::IsNullOrWhiteSpace($path)) { continue }
        if (-not (Test-Path $path)) { continue }

        $key = $path.ToLowerInvariant()
        if ($seen.ContainsKey($key)) { continue }
        $seen[$key] = $true
        [void]$paths.Add($path)
    }

    return @($paths.ToArray())
}

function Test-BootstrapPythonPathIsRuntimeOnly {
    param([string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) { return $true }
    $normalized = ([string]$Path).Replace('/', '\')

    if ($normalized -match '\\Microsoft\\WindowsApps\\') { return $true }
    if ($normalized -match '\\\.hermes\\hermes-agent\\venv\\Scripts\\python(\.exe)?$') { return $true }
    if ($normalized -match '\\(\.venv|venv|\.env|env)\\Scripts\\python(\.exe)?$') { return $true }
    if ($normalized -match '\\virtualenvs\\[^\\]+\\Scripts\\python(\.exe)?$') { return $true }

    return $false
}

function Get-BootstrapUserHomePath {
    if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) { return $env:USERPROFILE }
    if (-not [string]::IsNullOrWhiteSpace($env:HOME)) { return $env:HOME }
    if (-not [string]::IsNullOrWhiteSpace($env:HOMEDRIVE) -and -not [string]::IsNullOrWhiteSpace($env:HOMEPATH)) {
        return ($env:HOMEDRIVE + $env:HOMEPATH)
    }
    if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) { return $env:LOCALAPPDATA }
    if (-not [string]::IsNullOrWhiteSpace($env:TEMP)) { return $env:TEMP }
    if (-not [string]::IsNullOrWhiteSpace($env:TMP)) { return $env:TMP }
    try {
        $folder = [Environment]::GetFolderPath('UserProfile')
        if (-not [string]::IsNullOrWhiteSpace($folder)) { return $folder }
    } catch {
    }
    return (Get-Location).Path
}

function Get-BootstrapDefaultWorkspaceRoot {
    if (-not [string]::IsNullOrWhiteSpace([string]$env:BOOTSTRAP_WORKSPACE_ROOT)) {
        $explicit = [string]$env:BOOTSTRAP_WORKSPACE_ROOT.Trim()
        if (-not [string]::IsNullOrWhiteSpace($explicit)) {
            return $explicit
        }
    }

    $steamPreferred = 'F:\Steam\Steamapps'
    try {
        $item = Get-Item -LiteralPath $steamPreferred -ErrorAction SilentlyContinue
        if ($item -and $item.PSIsContainer) {
            return $steamPreferred
        }
    } catch {
    }

    $userHome = Get-BootstrapUserHomePath
    if (-not [string]::IsNullOrWhiteSpace($userHome)) {
        return (Join-Path $userHome 'Workspace')
    }

    try {
        if (-not [string]::IsNullOrWhiteSpace($env:SystemDrive)) {
            return (Join-Path $env:SystemDrive 'Workspace')
        }
    } catch {
    }
    return (Get-Location).Path
}

# ─────────────────────────────────────────────────────────────
# Dual Boot Management Module
# ─────────────────────────────────────────────────────────────

function Get-BootstrapFastStartupStatus {
    $result = @{ Enabled = $false; Safe = $true; RegistryPath = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power'; Value = $null }
    try {
        $val = Get-ItemProperty -Path $result.RegistryPath -Name 'HiberbootEnabled' -ErrorAction SilentlyContinue
        if ($null -ne $val -and $val.HiberbootEnabled -eq 1) {
            $result.Enabled = $true
            $result.Safe    = $false
            $result.Value   = 1
        } else {
            $result.Value = if ($null -ne $val) { $val.HiberbootEnabled } else { $null }
        }
    } catch { }
    return $result
}

function Get-BootstrapBitLockerStatus {
    $result = @{ CEnabled = $false; StatusText = 'unknown' }
    try {
        $output = & manage-bde -status C: 2>$null
        if ($output) {
            $statusLine = $output | Where-Object { $_ -match 'Protection Status|Status de Prote' } | Select-Object -First 1
            if ($statusLine -match '(On|Ativad)') {
                $result.CEnabled   = $true
                $result.StatusText = 'enabled'
            } else {
                $result.StatusText = 'disabled'
            }
        }
    } catch {
        $result.StatusText = 'error'
    }
    return $result
}

function Get-BootstrapLinuxPartitions {
    param(
        [switch]$Force
    )

    if ($BootstrapUiLibraryMode -and -not $Force) { return @() }
    $linuxPartitions = @()
    try {
        $partitions = Get-Partition -ErrorAction SilentlyContinue
        foreach ($p in $partitions) {
            $vol = $null
            try { $vol = Get-Volume -Partition $p -ErrorAction SilentlyContinue } catch { }
            $fsType = if ($vol) { [string]$vol.FileSystemType } else { '' }
            $isLinuxPartition = ($fsType -eq '' -or $fsType -eq 'Unknown' -or $fsType -eq 'RAW') -and
                       ($p.Type -notin @('System', 'Reserved', 'Recovery', 'IU', 'Basic')) -and
                       ($p.Size -gt 1GB)
            if ($isLinuxPartition) {
                $linuxPartitions += @{
                    DiskNumber      = $p.DiskNumber
                    PartitionNumber = $p.PartitionNumber
                    SizeGB          = [math]::Round($p.Size / 1GB, 1)
                    Type            = [string]$p.Type
                    FileSystem      = if ($fsType) { $fsType } else { 'Unknown' }
                    GptType         = if ($p.GptType) { [string]$p.GptType } else { '' }
                }
            }
        }
    } catch { }
    return @($linuxPartitions)
}

# ---------------------------------------------------------------------------------------------------
# Btrfs dual-boot (Windows <-> SteamOS). REGRA INEGOCIAVEL: este modulo NUNCA formata/particiona.
# Nenhuma funcao abaixo chama Format-Volume, Initialize-Disk, Clear-Disk, mkfs ou diskpart. Apenas
# detecta, audita prontidao, instala (guiado) o driver WinBtrfs e mapeia permissao. Leitura+escrita
# sao providas pelo proprio WinBtrfs apos instalado; o gate de Fast Startup evita corrupcao.
# ---------------------------------------------------------------------------------------------------
function Get-BootstrapWinBtrfsState {
    # Detecta o driver WinBtrfs (maharmstone/btrfs) instalado no Windows. Nao monta nem altera nada.
    $driverPath = Join-Path $env:SystemRoot 'System32\drivers\btrfs.sys'
    $installed = (Test-Path -LiteralPath $driverPath)
    $serviceState = ''
    try {
        if (Get-Command -Name Get-Service -ErrorAction SilentlyContinue) {
            $svc = Get-Service -Name 'btrfs' -ErrorAction SilentlyContinue
            if ($svc) { $installed = $true; $serviceState = [string]$svc.Status }
        }
    } catch { }
    return [ordered]@{ installed = [bool]$installed; driverPath = $driverPath; serviceState = $serviceState }
}

function Get-BootstrapBtrfsAccessLevel {
    # Matriz de seguranca de acesso btrfs (deterministica, sem efeitos colaterais). Substitui o antigo
    # readWriteSupported=winbtrfsInstalled, que ignorava Fast Startup, reboot, servico e particao.
    # Niveis: blocked (sem acesso) | unsafe (montar arriscaria corromper) | read-only-ok (leitura segura,
    # escrita NAO habilitada) | write-opt-in (todos os gates passam; escrita so com opt-in + backup).
    param(
        [bool]$WinbtrfsInstalled,
        [string]$ServiceState = '',
        [bool]$FastStartupEnabled,
        [bool]$PendingReboot,
        [int]$LinuxPartitionCount
    )

    $reasons = New-Object System.Collections.Generic.List[string]
    $serviceRunning = [string]::Equals([string]$ServiceState, 'Running', [System.StringComparison]::OrdinalIgnoreCase)
    $serviceKnownStopped = (-not [string]::IsNullOrWhiteSpace([string]$ServiceState)) -and (-not $serviceRunning)

    if (-not $WinbtrfsInstalled) {
        $reasons.Add('winbtrfs-not-installed') | Out-Null
        return [ordered]@{ level = 'blocked'; blockedReasons = @($reasons.ToArray()) }
    }
    if ($serviceKnownStopped) {
        $reasons.Add('winbtrfs-service-not-running') | Out-Null
        return [ordered]@{ level = 'blocked'; blockedReasons = @($reasons.ToArray()) }
    }

    if ($FastStartupEnabled) { $reasons.Add('fast-startup-on') | Out-Null }
    if ($PendingReboot) { $reasons.Add('pending-reboot') | Out-Null }
    if ($FastStartupEnabled -or $PendingReboot) {
        return [ordered]@{ level = 'unsafe'; blockedReasons = @($reasons.ToArray()) }
    }

    if ($LinuxPartitionCount -le 0) {
        $reasons.Add('no-btrfs-partition-detected') | Out-Null
        return [ordered]@{ level = 'read-only-ok'; blockedReasons = @($reasons.ToArray()) }
    }

    return [ordered]@{ level = 'write-opt-in'; blockedReasons = @() }
}

function Get-BootstrapBtrfsReadiness {
    # Auditoria de prontidao para acesso btrfs no dual-boot. Sem efeitos colaterais; seguro em lib mode.
    param(
        [switch]$ScanPartitions
    )

    $fast = Get-BootstrapFastStartupStatus
    $rebootReasons = @()
    try { $rebootReasons = @(Get-BootstrapPendingRebootReasons) } catch { $rebootReasons = @() }
    $winbtrfs = Get-BootstrapWinBtrfsState
    $partitions = @()
    if ((-not $BootstrapUiLibraryMode) -or $ScanPartitions) {
        try { $partitions = @(Get-BootstrapLinuxPartitions -Force:$ScanPartitions) } catch { $partitions = @() }
    }

    $checks = [ordered]@{
        'fast-startup-off' = $(if ($fast.Enabled) { 'warning' } else { 'healthy' })
        'winbtrfs-driver'  = $(if ($winbtrfs.installed) { 'healthy' } else { 'not-installed' })
        'linux-partitions' = $(if (@($partitions).Count -gt 0) { 'healthy' } else { 'warning' })
    }
    $recommendations = New-Object System.Collections.Generic.List[string]
    if ($fast.Enabled) { $recommendations.Add('Desligue Fast Startup/hibernacao (aba Dual Boot) antes de montar btrfs R/W; senao a FS fica suja e pode corromper.') | Out-Null }
    if (-not $winbtrfs.installed) { $recommendations.Add('Instale o WinBtrfs (componente winbtrfs, guiado) para ler/escrever btrfs no Windows.') | Out-Null }
    $recommendations.Add('Para o Linux ver o dono correto, use uid/gid=1000 nas opcoes do volume WinBtrfs.') | Out-Null
    $recommendations.Add('Este modulo NUNCA formata particoes. Faca backup antes de habilitar escrita.') | Out-Null

    $pendingReboot = (@($rebootReasons).Count -gt 0)
    $access = Get-BootstrapBtrfsAccessLevel -WinbtrfsInstalled ([bool]$winbtrfs.installed) -ServiceState ([string]$winbtrfs.serviceState) -FastStartupEnabled ([bool]$fast.Enabled) -PendingReboot $pendingReboot -LinuxPartitionCount (@($partitions).Count)
    $accessLevel = [string]$access.level
    $readWrite = ($accessLevel -eq 'write-opt-in')
    $readOnly = ($accessLevel -in @('read-only-ok', 'write-opt-in'))
    foreach ($reason in @($access.blockedReasons)) {
        switch ([string]$reason) {
            'winbtrfs-service-not-running' { $recommendations.Add('Servico WinBtrfs parado: inicie-o (admin) ou reinicie apos instalar/atualizar o driver.') | Out-Null }
            'pending-reboot' { $recommendations.Add('Reinicie o Windows: ha reboot pendente antes de montar btrfs com seguranca.') | Out-Null }
            'no-btrfs-partition-detected' { $recommendations.Add('Nenhuma particao Linux/Btrfs detectada: leitura pode ser feita manualmente, mas a escrita fica bloqueada ate confirmar o alvo.') | Out-Null }
        }
    }

    return [ordered]@{
        fastStartupEnabled = [bool]$fast.Enabled
        pendingReboot = $pendingReboot
        winbtrfsInstalled = [bool]$winbtrfs.installed
        winbtrfsServiceState = [string]$winbtrfs.serviceState
        linuxPartitionCount = @($partitions).Count
        partitions = @($partitions)
        checks = $checks
        recommendations = @($recommendations.ToArray())
        accessLevel = $accessLevel
        blockedReasons = @($access.blockedReasons)
        readWriteSupported = [bool]$readWrite
        readOnlySupported = [bool]$readOnly
        neverFormats = $true
    }
}

function Get-BootstrapCandidateVolumeRoots {
    # Enumera volumes Windows com letra atribuida. Funcao isolada para permitir Mock nos testes.
    # Retorna objetos { Root; DriveLetter; FileSystem }. Sem efeitos colaterais.
    $roots = New-Object System.Collections.Generic.List[object]
    try {
        $volumes = Get-Volume -ErrorAction SilentlyContinue
        foreach ($v in $volumes) {
            $letter = [string]$v.DriveLetter
            if ([string]::IsNullOrWhiteSpace($letter)) { continue }
            $roots.Add([pscustomobject]@{
                Root        = ('{0}:\' -f $letter)
                DriveLetter = $letter
                FileSystem  = [string]$v.FileSystemType
            }) | Out-Null
        }
    } catch {
        Write-Verbose $_.Exception.Message
    }
    return @($roots.ToArray())
}

function Get-BootstrapSteamDeckHome {
    # Descoberta dinamica (SEM hardcode de letra) do HOME do Steam Deck montado via WinBtrfs.
    # Varre todos os volumes com letra procurando a arvore EmuDeck e valida antes de confiar.
    # Read-only: nunca escreve. Seguro em library mode salvo -ScanVolumes.
    param(
        [switch]$ScanVolumes
    )

    $result = [ordered]@{
        found             = $false
        deckHome          = ''
        emulationRoot     = ''
        driveLetter       = ''
        fileSystem        = ''
        validationReasons = @()
    }

    if ($BootstrapUiLibraryMode -and -not $ScanVolumes) { return $result }

    # Subcaminhos relativos onde o HOME do Deck costuma aparecer quando a particao raiz (subvol @)
    # do SteamOS e montada: '@\deck' (subvol cru), 'deck' e 'home\deck'.
    $homeRelCandidates = @('@\deck', 'deck', 'home\deck')
    $emulationMarkers = @('roms', 'bios', 'storage', 'tools', 'saves')

    $linuxPartitionCount = 0
    try { $linuxPartitionCount = @(Get-BootstrapLinuxPartitions -Force:$ScanVolumes).Count } catch { $linuxPartitionCount = 0 }

    foreach ($vol in @(Get-BootstrapCandidateVolumeRoots)) {
        foreach ($rel in $homeRelCandidates) {
            $homeCandidate = [System.IO.Path]::Combine([string]$vol.Root, $rel)
            $emulationCandidate = [System.IO.Path]::Combine($homeCandidate, 'Emulation')
            if (-not (Test-Path -LiteralPath $emulationCandidate -PathType Container)) { continue }

            $reasons = New-Object System.Collections.Generic.List[string]

            # Validacao 1: legibilidade real do diretorio.
            $childNames = @()
            try { $childNames = @(Get-ChildItem -LiteralPath $emulationCandidate -Force -ErrorAction Stop | Select-Object -ExpandProperty Name) }
            catch { $reasons.Add('emulation-root-unreadable') | Out-Null }

            # Validacao 2: marcadores da arvore EmuDeck/ES-DE.
            $hasMarker = $false
            foreach ($m in $emulationMarkers) {
                if ($childNames -contains $m) { $hasMarker = $true; break }
            }
            if (-not $hasMarker) { $reasons.Add('no-emudeck-markers') | Out-Null }

            # Validacao 3 (soft): filesystem nao-Windows (Btrfs/Unknown/RAW) ou ha particao Linux.
            $fs = [string]$vol.FileSystem
            $looksNonWindowsFs = ([string]::IsNullOrWhiteSpace($fs) -or $fs -in @('Btrfs', 'Unknown', 'RAW'))
            if (-not $looksNonWindowsFs -and $linuxPartitionCount -le 0) {
                $reasons.Add('volume-not-linux-backed') | Out-Null
            }

            if ($reasons.Count -eq 0) {
                $result.found = $true
                $result.deckHome = $homeCandidate
                $result.emulationRoot = $emulationCandidate
                $result.driveLetter = [string]$vol.DriveLetter
                $result.fileSystem = $fs
                $result.validationReasons = @()
                return $result
            }

            # Guarda o melhor "quase" para diagnostico, mas segue procurando um valido.
            if (-not $result.found -and $result.validationReasons.Count -eq 0) {
                $result.deckHome = $homeCandidate
                $result.emulationRoot = $emulationCandidate
                $result.driveLetter = [string]$vol.DriveLetter
                $result.fileSystem = $fs
                $result.validationReasons = @($reasons.ToArray())
            }
        }
    }

    return $result
}

function Get-BootstrapDeckEmulationRoot {
    # Resolve o root de emulacao do Deck (se valido) cruzado com a prontidao Btrfs (acesso R/O vs R/W).
    param(
        [switch]$ScanVolumes
    )

    $deckHome = Get-BootstrapSteamDeckHome -ScanVolumes:$ScanVolumes
    $accessLevel = 'unknown'
    $writable = $false
    try {
        $readiness = Get-BootstrapBtrfsReadiness -ScanPartitions:$ScanVolumes
        $accessLevel = [string]$readiness.accessLevel
        $writable = ($accessLevel -eq 'write-opt-in')
    } catch {
        Write-Verbose $_.Exception.Message
    }

    return [ordered]@{
        found             = [bool]$deckHome.found
        emulationRoot     = [string]$deckHome.emulationRoot
        deckHome          = [string]$deckHome.deckHome
        driveLetter       = [string]$deckHome.driveLetter
        accessLevel       = $accessLevel
        writable          = [bool]$writable
        readable          = ([bool]$deckHome.found -and ($accessLevel -in @('read-only-ok', 'write-opt-in')))
        validationReasons = @($deckHome.validationReasons)
    }
}

function Get-BootstrapEfiEntries {
    if (-not (Test-IsAdmin)) { return $null }
    $entries = @()
    try {
        $raw = & bcdedit /enum firmware 2>$null
        if (-not $raw) { return @() }
        $currentEntry = $null
        foreach ($line in $raw) {
            if ($line -match '^[-]+$') { continue }
            if ($line -match '^\s*$') {
                if ($currentEntry) { $entries += $currentEntry }
                $currentEntry = $null
                continue
            }
            if ($line -match '^(?:Firmware Boot Manager|Gerenciador de Inicializa)') {
                $currentEntry = @{ Type = 'bootmgr'; Id = ''; Description = ''; Path = '' }
                continue
            }
            if ($line -match '^(?:Firmware Application|Aplicativo de Firmware)') {
                $currentEntry = @{ Type = 'entry'; Id = ''; Description = ''; Path = '' }
                continue
            }
            if ($null -ne $currentEntry) {
                if ($line -match '(?:identifier|identificador)\s+(.+)') { $currentEntry.Id = ($Matches[1]).Trim() }
                if ($line -match '(?:description|descri)\s+(.+)')       { $currentEntry.Description = ($Matches[1]).Trim() }
                if ($line -match '(?:path|caminho)\s+(.+)')             { $currentEntry.Path = ($Matches[1]).Trim() }
            }
        }
        if ($currentEntry) { $entries += $currentEntry }
    } catch { }
    return @($entries)
}

function Get-BootstrapFileSystemRootCandidates {
    param([string[]]$RootPaths = @())

    $roots = New-Object System.Collections.Generic.List[string]
    if (@($RootPaths).Count -gt 0) {
        foreach ($root in @($RootPaths)) {
            if (-not [string]::IsNullOrWhiteSpace([string]$root)) { $roots.Add([string]$root) | Out-Null }
        }
    } else {
        try {
            foreach ($drive in @(Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue)) {
                if (-not [string]::IsNullOrWhiteSpace([string]$drive.Root)) { $roots.Add([string]$drive.Root) | Out-Null }
            }
        } catch { }
    }

    return @($roots.ToArray() | Select-Object -Unique | Where-Object { Test-Path -LiteralPath $_ })
}

function Get-BootstrapSteamOsEfiInstallations {
    param([string[]]$RootPaths = @())

    $installations = New-Object System.Collections.Generic.List[object]
    foreach ($root in @(Get-BootstrapFileSystemRootCandidates -RootPaths $RootPaths)) {
        $efiDir = Join-Path ([string]$root) 'EFI\steamos'
        $grubPath = Join-Path $efiDir 'grubx64.efi'
        $grubConfigPath = Join-Path $efiDir 'grub.cfg'
        if (-not (Test-Path -LiteralPath $grubPath -PathType Leaf)) { continue }
        if (-not (Test-Path -LiteralPath $grubConfigPath -PathType Leaf)) { continue }

        $customConfigPath = Join-Path $efiDir 'custom.cfg'
        $fallbackBootPath = Join-Path (Join-Path ([string]$root) 'EFI\Boot') 'bootx64.efi'
        $grubConfig = ''
        $customConfig = ''
        try { $grubConfig = [System.IO.File]::ReadAllText($grubConfigPath) } catch { $grubConfig = '' }
        if (Test-Path -LiteralPath $customConfigPath -PathType Leaf) {
            try { $customConfig = [System.IO.File]::ReadAllText($customConfigPath) } catch { $customConfig = '' }
        }
        $fallbackMatches = $false
        if (Test-Path -LiteralPath $fallbackBootPath -PathType Leaf) {
            try {
                $fallbackItem = Get-Item -LiteralPath $fallbackBootPath -ErrorAction Stop
                $grubItem = Get-Item -LiteralPath $grubPath -ErrorAction Stop
                $fallbackMatches = ([int64]$fallbackItem.Length -eq [int64]$grubItem.Length)
                if ($fallbackMatches -and (Get-Command -Name Get-FileHash -ErrorAction SilentlyContinue)) {
                    $fallbackMatches = ((Get-FileHash -LiteralPath $fallbackBootPath -Algorithm SHA256).Hash -eq (Get-FileHash -LiteralPath $grubPath -Algorithm SHA256).Hash)
                }
            } catch { $fallbackMatches = $false }
        }

        $hasWindowsEntry = (($grubConfig + "`n" + $customConfig) -match '(?i)Windows Boot Manager|bootmgfw\.efi')
        $dangerousPrefix = Test-BootstrapGrubEfiDangerousPrefix -Path $grubPath
        $installations.Add([pscustomobject][ordered]@{
            root = [string]$root
            efiPath = $efiDir
            grubPath = $grubPath
            grubConfigPath = $grubConfigPath
            customConfigPath = $customConfigPath
            customConfigExists = (Test-Path -LiteralPath $customConfigPath -PathType Leaf)
            customConfigManaged = ($customConfig -match '(?m)^# BEGIN PHASEZERO GRUB DUAL BOOT\s*$')
            grubConfigHasWindowsEntry = [bool]$hasWindowsEntry
            grubConfigTimeoutZero = ($grubConfig -match '(?m)^\s*timeout\s*=\s*0\s*$')
            fallbackBootPath = $fallbackBootPath
            fallbackBootExists = (Test-Path -LiteralPath $fallbackBootPath -PathType Leaf)
            fallbackBootMatchesGrub = [bool]$fallbackMatches
            grubEfiDangerousPrefix = [bool]$dangerousPrefix
        }) | Out-Null
    }

    return @($installations.ToArray())
}

function Test-BootstrapGrubEfiDangerousPrefix {
    param([Parameter(Mandatory = $true)][string]$Path)

    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $false }
    try {
        $bytes = [System.IO.File]::ReadAllBytes($Path)
        $text = [System.Text.Encoding]::ASCII.GetString($bytes)
    } catch {
        return $false
    }

    if ($text -match 'hd6,gpt2') { return $true }
    if ($text -match '\(,gpt[0-9]+\)/@/boot/grub') { return $true }
    if ($text -match '\(hd[0-9]+,gpt[0-9]+\)/@/boot/grub') { return $true }
    return $false
}

function Merge-BootstrapGrubMarkedTextBlock {
    param(
        [AllowNull()][string]$Content,
        [Parameter(Mandatory = $true)][string]$Body,
        [string]$Label = 'PHASEZERO GRUB DUAL BOOT'
    )

    $startMarker = "# BEGIN $Label"
    $endMarker = "# END $Label"
    $block = ($startMarker + [Environment]::NewLine + $Body.Trim() + [Environment]::NewLine + $endMarker)
    $current = if ($null -eq $Content) { '' } else { [string]$Content }
    $pattern = '(?s)# BEGIN ' + [regex]::Escape($Label) + '.*?# END ' + [regex]::Escape($Label)
    if ($current -match $pattern) {
        $updated = [regex]::Replace($current, $pattern, [System.Text.RegularExpressions.MatchEvaluator]{ param($m) $block }, 1)
    } elseif ([string]::IsNullOrWhiteSpace($current)) {
        $updated = $block + [Environment]::NewLine
    } else {
        $updated = $current.TrimEnd() + [Environment]::NewLine + [Environment]::NewLine + $block + [Environment]::NewLine
    }

    return [ordered]@{ content = $updated; changed = ($updated -ne $current) }
}

function Get-BootstrapSteamOsGrubDualBootBlock {
    return (@(
        'set timeout=5',
        'set timeout_style=menu',
        '',
        'menuentry "Windows Boot Manager" --class windows --class os {',
        '    insmod part_gpt',
        '    insmod fat',
        '    if search --no-floppy --file --set=windows_esp /EFI/Microsoft/Boot/bootmgfw.efi; then',
        '        chainloader ($windows_esp)/EFI/Microsoft/Boot/bootmgfw.efi',
        '    else',
        '        echo "Windows Boot Manager not found: /EFI/Microsoft/Boot/bootmgfw.efi"',
        '        sleep 5',
        '    fi',
        '}'
    ) -join [Environment]::NewLine)
}

function Ensure-BootstrapSteamOsGrubDualBootMenu {
    param(
        [string[]]$RootPaths = @(),
        [AllowNull()][hashtable]$State = $null,
        [switch]$DryRun
    )

    $rows = New-Object System.Collections.Generic.List[object]
    $changedAny = $false
    $body = Get-BootstrapSteamOsGrubDualBootBlock
    foreach ($install in @(Get-BootstrapSteamOsEfiInstallations -RootPaths $RootPaths)) {
        $path = [string]$install.customConfigPath
        $current = ''
        if (Test-Path -LiteralPath $path -PathType Leaf) {
            try { $current = [System.IO.File]::ReadAllText($path) } catch { $current = '' }
        }
        $merged = Merge-BootstrapGrubMarkedTextBlock -Content $current -Body $body
        $changed = [bool]$merged.changed
        $backupPath = ''
        if ($changed) {
            $changedAny = $true
            if (-not $DryRun) {
                if ($State) {
                    Register-BootstrapFileChange -State $State -Target $path -Operation 'steamos-grub-custom-cfg' -Component 'dual-boot' -NewValue 'phasezero-grub-dual-boot'
                } elseif (Test-Path -LiteralPath $path -PathType Leaf) {
                    $backupPath = Join-Path (Split-Path -Path $path -Parent) ("custom.cfg.phasezero-{0}.bak" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
                    Copy-Item -LiteralPath $path -Destination $backupPath -Force
                }
                Write-BootstrapTextFile -Path $path -Content ([string]$merged.content)
            }
        }
        $rows.Add([pscustomobject][ordered]@{
            root = [string]$install.root
            customConfigPath = $path
            changed = $changed
            dryRun = [bool]$DryRun
            backupPath = $backupPath
        }) | Out-Null
    }

    return [ordered]@{ success = $true; changed = $changedAny; dryRun = [bool]$DryRun; installations = @($rows.ToArray()) }
}

function Ensure-BootstrapSteamOsEfiFallbackBootloader {
    param(
        [string[]]$RootPaths = @(),
        [AllowNull()][hashtable]$State = $null,
        [switch]$DryRun
    )

    $rows = New-Object System.Collections.Generic.List[object]
    $changedAny = $false
    foreach ($install in @(Get-BootstrapSteamOsEfiInstallations -RootPaths $RootPaths)) {
        $source = [string]$install.grubPath
        $target = [string]$install.fallbackBootPath
        $changed = -not [bool]$install.fallbackBootMatchesGrub
        $backupPath = ''
        $blocked = [bool]$install.grubEfiDangerousPrefix
        if ($changed) {
            if ($blocked) {
                Write-Log "dualboot-manager: refusing EFI fallback copy from GRUB with dangerous disk-order prefix: $source"
            } else {
                $changedAny = $true
            }
            if ((-not $blocked) -and (-not $DryRun)) {
                $parent = Split-Path -Path $target -Parent
                if ($parent) { New-Item -Path $parent -ItemType Directory -Force | Out-Null }
                if ($State) {
                    Register-BootstrapFileChange -State $State -Target $target -Operation 'steamos-efi-fallback-bootloader' -Component 'dual-boot' -NewValue 'phasezero-steamos-grub-fallback'
                } elseif (Test-Path -LiteralPath $target -PathType Leaf) {
                    $backupPath = Join-Path $parent ("bootx64.efi.phasezero-{0}.bak" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
                    Copy-Item -LiteralPath $target -Destination $backupPath -Force
                }
                Copy-Item -LiteralPath $source -Destination $target -Force
            }
        }
        $rows.Add([pscustomobject][ordered]@{
            root = [string]$install.root
            source = $source
            target = $target
            changed = ($changed -and -not $blocked)
            dryRun = [bool]$DryRun
            backupPath = $backupPath
            blocked = $blocked
            blockReason = if ($blocked) { 'dangerous-grub-efi-prefix' } else { '' }
        }) | Out-Null
    }

    return [ordered]@{ success = $true; changed = $changedAny; dryRun = [bool]$DryRun; installations = @($rows.ToArray()) }
}

function Get-BootstrapGrubPresence {
    param([AllowNull()]$SteamOsEfiInstallations = $null)

    $result = @{ Detected = $false; Path = ''; Confidence = 'none'; EntryId = ''; EntryDesc = '' }
    if (Test-IsAdmin) {
        $efiEntries = @(Get-BootstrapEfiEntries)
        foreach ($entry in $efiEntries) {
            if ($entry.Type -ne 'entry') { continue }
            $p = [string]$entry.Path
            $d = [string]$entry.Description
            if ($p -match 'grubx64\.efi|shimx64\.efi' -or $d -match 'ubuntu|fedora|bazzite|steamos|linux|grub|refind|Pop!_OS|manjaro|arch|debian|opensuse|nixos') {
                $result.Detected   = $true
                $result.Path       = $p
                $result.Confidence = 'high'
                $result.EntryId    = $entry.Id
                $result.EntryDesc  = $d
                break
            }
        }
    }
    if (-not $result.Detected) {
        $steamOsEfi = if ($null -ne $SteamOsEfiInstallations) { @($SteamOsEfiInstallations) } else { @(Get-BootstrapSteamOsEfiInstallations) }
        if (@($steamOsEfi).Count -gt 0) {
            $first = @($steamOsEfi)[0]
            $result.Detected = $true
            $result.Path = [string]$first.grubPath
            $result.Confidence = 'high'
            $result.EntryDesc = 'SteamOS GRUB (EFI file)'
        }
    }
    if (-not $result.Detected) {
        $linuxParts = @(Get-BootstrapLinuxPartitions)
        if ($linuxParts.Count -gt 0) {
            $result.Detected   = $true
            $result.Confidence = 'medium'
        }
    }
    return $result
}

function Test-BootstrapIsDualBoot {
    if ($BootstrapUiLibraryMode) { return $false }
    $grub = Get-BootstrapGrubPresence
    if ($grub.Detected -eq $true) { return $true }
    $linuxParts = @(Get-BootstrapLinuxPartitions)
    return ($linuxParts.Count -gt 0)
}

function Get-BootstrapDualBootInfo {
    $isAdmin       = Test-IsAdmin
    $fastStartup   = Get-BootstrapFastStartupStatus
    $bitlocker     = Get-BootstrapBitLockerStatus
    $linuxParts    = @(Get-BootstrapLinuxPartitions)
    $steamOsEfi    = @(Get-BootstrapSteamOsEfiInstallations)
    $grub          = ConvertTo-BootstrapHashtable -InputObject (Get-BootstrapGrubPresence -SteamOsEfiInstallations $steamOsEfi)
    if (-not $grub.ContainsKey('Detected')) { $grub['Detected'] = $false }
    if (-not $grub.ContainsKey('Path')) { $grub['Path'] = '' }
    if (-not $grub.ContainsKey('Confidence')) { $grub['Confidence'] = 'none' }
    if (-not $grub.ContainsKey('EntryId')) { $grub['EntryId'] = '' }
    if (-not $grub.ContainsKey('EntryDesc')) { $grub['EntryDesc'] = '' }
    $efiEntries    = if ($isAdmin) { Get-BootstrapEfiEntries } else { $null }
    $isDualBoot    = ($grub.Detected -eq $true) -or ($linuxParts.Count -gt 0)
    $confidence    = if ($grub.Confidence -eq 'high') { 'high' } elseif ($linuxParts.Count -gt 0) { 'medium' } else { 'none' }
    $detectedOS    = @('Windows')
    if ($grub.EntryDesc) { $detectedOS += $grub.EntryDesc }
    elseif ($linuxParts.Count -gt 0) { $detectedOS += 'Linux (unknown distro)' }

    $warnings = New-Object System.Collections.Generic.List[string]
    if ($fastStartup.Enabled) {
        $warnings.Add('Fast Startup esta habilitado. Isso pode corromper particoes Linux ou impedir montagem de volumes NTFS compartilhados.')
    }
    if ($bitlocker.CEnabled) {
        $warnings.Add('BitLocker esta ativo em C:. Alteracoes no EFI podem disparar recuperacao do BitLocker.')
    }
    if (-not $isAdmin) {
        $warnings.Add('Executando sem privilegios de administrador. Algumas informacoes de EFI e disco podem estar incompletas.')
    }

    return @{
        IsDualBoot      = $isDualBoot
        Confidence      = $confidence
        DetectedOS      = @($detectedOS)
        GrubDetected    = [bool]$grub.Detected
        GrubEfiPath     = [string]$grub.Path
        GrubEntryId     = if ($grub.EntryId) { [string]$grub.EntryId } else { '' }
        GrubEntryDesc   = if ($grub.EntryDesc) { [string]$grub.EntryDesc } else { '' }
        LinuxPartitions = @($linuxParts)
        SteamOsEfiInstallations = @($steamOsEfi)
        EfiEntries      = $efiEntries
        FastStartup     = $fastStartup
        BitLocker       = $bitlocker
        IsAdmin         = $isAdmin
        Warnings        = @($warnings.ToArray())
    }
}

# --- Guardrails ---

function Test-BootstrapSafePartition {
    param(
        [Parameter(Mandatory = $true)][int]$DiskNumber,
        [Parameter(Mandatory = $true)][int]$PartitionNumber
    )
    try {
        $p = Get-Partition -DiskNumber $DiskNumber -PartitionNumber $PartitionNumber -ErrorAction Stop
    } catch {
        return $false
    }
    if ($p.Type -in @('System', 'Reserved', 'Recovery')) { return $false }
    $vol = $null
    try { $vol = Get-Volume -Partition $p -ErrorAction SilentlyContinue } catch { }
    $fs = if ($vol) { [string]$vol.FileSystemType } else { '' }
    if ($fs -eq '' -or $fs -eq 'Unknown' -or $fs -eq 'RAW') { return $false }
    return $true
}

function Assert-BootstrapDiskSafety {
    param(
        [Parameter(Mandatory = $true)][int]$DiskNumber,
        [Parameter(Mandatory = $true)][int]$PartitionNumber,
        [string]$OperationName = 'disk operation'
    )
    if (-not (Test-BootstrapSafePartition -DiskNumber $DiskNumber -PartitionNumber $PartitionNumber)) {
        throw "BLOCKED: $OperationName on Disk $DiskNumber Partition $PartitionNumber is not allowed. The partition is EFI System, Recovery, or has an unrecognized (possibly Linux) filesystem. This guard prevents accidental destruction of dual-boot partitions."
    }
}

function Test-BootstrapSafeEfiOperation {
    if (-not (Test-IsAdmin)) { return $false }
    try {
        $entries = Get-BootstrapEfiEntries
        if ($null -eq $entries -or $entries.Count -eq 0) { return $false }
        $hasBootMgr = ($entries | Where-Object { $_.Type -eq 'bootmgr' }).Count -gt 0
        return $hasBootMgr
    } catch { return $false }
}

# --- Prerequisites ---

function Test-BootstrapDualBootPrerequisites {
    $issues = @()
    $fastStartup = Get-BootstrapFastStartupStatus
    if ($fastStartup.Enabled) {
        $issues += @{
            Id          = 'fast-startup'
            Severity    = 'critical'
            Title       = 'Fast Startup habilitado'
            Description = 'O Fast Startup faz o Windows hibernar em vez de desligar, o que pode corromper particoes compartilhadas e impedir o Linux de montar volumes NTFS.'
            CanAutoFix  = $true
        }
    }
    $bitlocker = Get-BootstrapBitLockerStatus
    if ($bitlocker.CEnabled) {
        $issues += @{
            Id          = 'bitlocker'
            Severity    = 'warning'
            Title       = 'BitLocker ativo em C:'
            Description = 'BitLocker pode disparar a tela de recuperacao se o bootloader EFI for alterado. Considere suspender o BitLocker antes de modificar entradas de boot.'
            CanAutoFix  = $false
        }
    }
    return @($issues)
}

function Repair-BootstrapFastStartup {
    if (-not (Test-IsAdmin)) {
        throw 'Repair-BootstrapFastStartup requer privilegios de administrador.'
    }
    $status = Get-BootstrapFastStartupStatus
    if (-not $status.Enabled) {
        Write-Log 'Fast Startup ja esta desabilitado.'
        return @{ Changed = $false; PreviousValue = $status.Value }
    }
    $regPath = $status.RegistryPath
    $previousValue = $status.Value
    Set-ItemProperty -Path $regPath -Name 'HiberbootEnabled' -Value 0 -Type DWord -Force
    Write-Log "Fast Startup desabilitado (HiberbootEnabled: $previousValue -> 0)."
    return @{ Changed = $true; PreviousValue = $previousValue }
}

# --- Instalacao assistida de SteamOS/Bazzite (deteccao + seguranca; NUNCA grava em disco) -------

function Get-BootstrapHostManufacturerModel {
    # Wrapper mockavel da identificacao do host (Win32_ComputerSystem). Read-only.
    $result = [ordered]@{ manufacturer = ''; model = '' }
    try {
        $cs = Get-CimInstance -ClassName Win32_ComputerSystem -OperationTimeoutSec 5 -ErrorAction Stop
        $result.manufacturer = [string]$cs.Manufacturer
        $result.model = [string]$cs.Model
    } catch {
        Write-Verbose $_.Exception.Message
    }
    return $result
}

function Get-BootstrapOsInstallHostProfile {
    # Imagem recomendada conforme o host: Steam Deck Valve (Jupiter/Galileo) -> SteamOS recovery
    # oficial; qualquer outro host -> Bazzite (SteamOS-like para PC generico). Read-only.
    $hw = Get-BootstrapHostManufacturerModel
    $isDeck = ([string]$hw.manufacturer -match 'Valve') -and ([string]$hw.model -match 'Jupiter|Galileo')
    return [ordered]@{
        hostType         = $(if ($isDeck) { 'steam-deck' } else { 'generic-pc' })
        isSteamDeck      = [bool]$isDeck
        manufacturer     = [string]$hw.manufacturer
        model            = [string]$hw.model
        recommendedImage = $(if ($isDeck) { 'steamos-recovery' } else { 'bazzite' })
    }
}

function Get-BootstrapPhysicalDisksSnapshot {
    # Lista mockavel de discos fisicos + particoes (read-only). Base da analise de topologia.
    $disks = New-Object System.Collections.Generic.List[object]
    try {
        foreach ($d in @(Get-Disk -ErrorAction SilentlyContinue)) {
            $partRows = New-Object System.Collections.Generic.List[object]
            try {
                foreach ($p in @(Get-Partition -DiskNumber $d.Number -ErrorAction SilentlyContinue)) {
                    $fs = ''; $drive = ''; $label = ''
                    try {
                        $vol = Get-Volume -Partition $p -ErrorAction SilentlyContinue
                        if ($vol) { $fs = [string]$vol.FileSystemType; $drive = [string]$vol.DriveLetter; $label = [string]$vol.FileSystemLabel }
                    } catch { Write-Verbose $_.Exception.Message }
                    $partRows.Add([pscustomobject]@{
                        PartitionNumber = [int]$p.PartitionNumber
                        Type            = [string]$p.Type
                        SizeGB          = [math]::Round($p.Size / 1GB, 1)
                        FileSystem      = $fs
                        FileSystemLabel = $label
                        DriveLetter     = $drive
                        IsBoot          = [bool]$p.IsBoot
                        IsSystem        = [bool]$p.IsSystem
                    }) | Out-Null
                }
            } catch { Write-Verbose $_.Exception.Message }
            $disks.Add([pscustomobject]@{
                Number       = [int]$d.Number
                FriendlyName = [string]$d.FriendlyName
                SizeGB       = [math]::Round($d.Size / 1GB, 1)
                BusType      = [string]$d.BusType
                Partitions   = @($partRows.ToArray())
            }) | Out-Null
        }
    } catch {
        Write-Verbose $_.Exception.Message
    }
    return @($disks.ToArray())
}

function Test-BootstrapDiskHasWindows {
    # True se o disco contem QUALQUER sinal do Windows: particao do sistema/boot ativa, Recovery,
    # letra C: ou filesystem NTFS/ReFS. Conservador de proposito: na duvida, marca como Windows
    # (falso-positivo bloqueia o disco; falso-negativo seria catastrofico).
    param([Parameter(Mandatory = $true)]$Disk)

    foreach ($p in @($Disk.Partitions)) {
        if ([bool]$p.IsSystem -or [bool]$p.IsBoot) { return $true }
        if ([string]$p.Type -eq 'Recovery') { return $true }
        if ([string]$p.DriveLetter -eq 'C') { return $true }
        if ([string]$p.FileSystem -in @('NTFS', 'ReFS')) { return $true }
    }
    return $false
}

function Test-BootstrapOsInstallDiskRemovable {
    param([Parameter(Mandatory = $true)]$Disk)

    $busType = ([string]$Disk.BusType).Trim()
    if ($busType -in @('USB', 'SD')) { return $true }

    $friendlyName = ([string]$Disk.FriendlyName).Trim()
    if ($friendlyName -match '(?i)(\busb\b|\bflash\b|\bsdxc\b|\bsd card\b|\bcard reader\b|\bstorage device\b)') { return $true }
    return $false
}

function Test-BootstrapOsInstallPartitionLinuxLike {
    param([Parameter(Mandatory = $true)]$Partition)

    if ([bool]$Partition.IsSystem -or [bool]$Partition.IsBoot) { return $false }

    $type = (([string]$Partition.Type).Trim()).ToLowerInvariant()
    if ($type -in @('system', 'reserved', 'recovery')) { return $false }

    $fs = (([string]$Partition.FileSystem).Trim()).ToLowerInvariant()
    if ($fs -in @('ntfs', 'refs', 'fat', 'fat32', 'exfat')) { return $false }
    if ($fs -in @('', 'unknown', 'raw', 'ext4', 'btrfs', 'ext3', 'xfs')) { return $true }
    if ($type -in @('unknown', 'linux')) { return $true }
    if ($type -match 'linux') { return $true }

    return $false
}

function Get-BootstrapOsInstallDiskTopology {
    # Classifica cada disco fisico: Windows, removivel e candidato interno dedicado Linux. Read-only.
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($d in @(Get-BootstrapPhysicalDisksSnapshot)) {
        $partitions = @($d.Partitions)
        $hasWindows = Test-BootstrapDiskHasWindows -Disk $d
        $isRemovable = Test-BootstrapOsInstallDiskRemovable -Disk $d
        $installSizeOk = ([double]$d.SizeGB -ge 64)
        $linuxLike = @($partitions | Where-Object { Test-BootstrapOsInstallPartitionLinuxLike -Partition $_ })
        $onlyLinuxOrEmpty = (($partitions.Count -eq 0) -or ($linuxLike.Count -eq $partitions.Count))
        $isDedicatedLinuxCandidate = ((-not [bool]$hasWindows) -and (-not [bool]$isRemovable) -and [bool]$installSizeOk -and [bool]$onlyLinuxOrEmpty)
        $rows.Add([ordered]@{
            diskNumber                = [int]$d.Number
            friendlyName              = [string]$d.FriendlyName
            sizeGB                    = [double]$d.SizeGB
            busType                   = [string]$d.BusType
            partitionCount            = $partitions.Count
            linuxPartitionCount       = @($linuxLike).Count
            hasWindows                = [bool]$hasWindows
            isRemovable               = [bool]$isRemovable
            installSizeOk             = [bool]$installSizeOk
            onlyLinuxOrEmpty          = [bool]$onlyLinuxOrEmpty
            isDedicatedLinuxCandidate = [bool]$isDedicatedLinuxCandidate
            partitions                = @($partitions)
        }) | Out-Null
    }
    return @($rows.ToArray())
}

function Get-BootstrapOsInstallManualPartitionTargets {
    param([AllowNull()][object[]]$Topology = $null)

    if ($null -eq $Topology) { $Topology = @(Get-BootstrapOsInstallDiskTopology) }

    $targets = New-Object System.Collections.Generic.List[object]
    foreach ($d in @($Topology)) {
        if (-not [bool]$d.hasWindows) { continue }
        if ([bool]$d.isRemovable) { continue }
        foreach ($p in @($d.partitions)) {
            if (-not (Test-BootstrapOsInstallPartitionLinuxLike -Partition $p)) { continue }
            if ([double]$p.SizeGB -lt 32) { continue }
            $targets.Add([ordered]@{
                diskNumber      = [int]$d.diskNumber
                partitionNumber = [int]$p.PartitionNumber
                sizeGB          = [double]$p.SizeGB
                fileSystem      = [string]$p.FileSystem
                type            = [string]$p.Type
                method          = 'native-installer-manual-partition'
                reason          = 'mixed-disk-linux-partition-manual-only'
            }) | Out-Null
        }
    }
    return @($targets.ToArray())
}

function ConvertTo-BootstrapSafeVolumeLabel {
    param(
        [AllowNull()][string]$Text,
        [int]$MaxLength = 16
    )

    $value = ([string]$Text).Trim().ToUpperInvariant()
    $value = [regex]::Replace($value, '[^A-Z0-9-]+', '-')
    $value = [regex]::Replace($value, '-+', '-').Trim('-')
    if ([string]::IsNullOrWhiteSpace($value)) { $value = 'PZ-VOLUME' }
    if ($value.Length -gt $MaxLength) { $value = $value.Substring(0, $MaxLength).Trim('-') }
    return $value
}

function Get-BootstrapPartitionPedagogicalRole {
    param(
        [Parameter(Mandatory = $true)]$Disk,
        [Parameter(Mandatory = $true)]$Partition,
        [Parameter(Mandatory = $true)][bool]$DiskHasWindows,
        [Parameter(Mandatory = $true)][bool]$DiskIsRemovable
    )

    $type = (([string]$Partition.Type).Trim()).ToLowerInvariant()
    $fs = (([string]$Partition.FileSystem).Trim()).ToLowerInvariant()
    $drive = ([string]$Partition.DriveLetter).Trim()
    $label = (([string]$Partition.FileSystemLabel).Trim()).ToLowerInvariant()

    if ([bool]$Partition.IsSystem -or $type -eq 'system') { return 'efi-system' }
    if ((-not $DiskIsRemovable) -and ($fs -in @('fat', 'fat32')) -and ([double]$Partition.SizeGB -le 1) -and ($label -match 'efi|esp|system|boot')) { return 'efi-system' }
    if ($type -eq 'recovery') { return 'windows-recovery' }
    if ([bool]$Partition.IsBoot -or $drive -eq 'C') { return 'windows-system' }
    if (Test-BootstrapOsInstallPartitionLinuxLike -Partition $Partition) {
        if ($DiskHasWindows) { return 'steamos-linux-manual' }
        return 'linux-dedicated'
    }
    if ($DiskIsRemovable) {
        if (($fs -in @('exfat', 'fat', 'fat32')) -and ([double]$Partition.SizeGB -lt 64)) { return 'removable-install' }
        return 'removable-media'
    }
    if ((-not [string]::IsNullOrWhiteSpace($drive)) -and ($fs -in @('ntfs', 'refs', 'exfat', 'fat', 'fat32'))) { return 'windows-data' }
    return 'manual-review'
}

function Get-BootstrapPartitionRoleLabel {
    param(
        [Parameter(Mandatory = $true)][string]$Role,
        [AllowNull()][string]$DriveLetter = ''
    )

    $drive = ([string]$DriveLetter).Trim().TrimEnd(':').ToUpperInvariant()
    switch ($Role) {
        'efi-system' { return 'PZ-EFI-SYS' }
        'windows-recovery' { return 'PZ-WIN-REC' }
        'windows-system' { return $(if ([string]::IsNullOrWhiteSpace($drive)) { 'PZ-WIN-SYS' } else { "PZ-WIN-$drive" }) }
        'steamos-linux-manual' { return 'PZ-DECK-LINUX' }
        'linux-dedicated' { return 'PZ-LINUX' }
        'removable-install' { return 'PZ-USB-INSTALL' }
        'removable-media' { return 'PZ-USB-MEDIA' }
        'windows-data' { return $(if ([string]::IsNullOrWhiteSpace($drive)) { 'PZ-DATA' } else { "PZ-DATA-$drive" }) }
        default { return 'PZ-REVIEW' }
    }
}

function New-BootstrapPartitionLabelEntry {
    param(
        [Parameter(Mandatory = $true)]$Disk,
        [Parameter(Mandatory = $true)]$Partition
    )

    $diskHasWindows = Test-BootstrapDiskHasWindows -Disk $Disk
    $diskIsRemovable = Test-BootstrapOsInstallDiskRemovable -Disk $Disk
    $role = Get-BootstrapPartitionPedagogicalRole -Disk $Disk -Partition $Partition -DiskHasWindows:$diskHasWindows -DiskIsRemovable:$diskIsRemovable
    $drive = ([string]$Partition.DriveLetter).Trim().TrimEnd(':').ToUpperInvariant()
    $currentLabel = ([string]$Partition.FileSystemLabel).Trim()
    $proposedLabel = ConvertTo-BootstrapSafeVolumeLabel -Text (Get-BootstrapPartitionRoleLabel -Role $role -DriveLetter $drive)
    $fs = (([string]$Partition.FileSystem).Trim()).ToLowerInvariant()

    $reasons = New-Object System.Collections.Generic.List[string]
    if ([string]::IsNullOrWhiteSpace($drive)) { $reasons.Add('no-drive-letter') | Out-Null }
    if ($fs -notin @('ntfs', 'refs', 'exfat', 'fat', 'fat32')) { $reasons.Add('unsupported-filesystem') | Out-Null }
    if ($role -in @('efi-system', 'windows-recovery', 'windows-system')) { $reasons.Add('protected-windows-volume') | Out-Null }
    if ($role -in @('steamos-linux-manual', 'linux-dedicated')) { $reasons.Add('linux-or-unknown-filesystem') | Out-Null }
    if ($diskIsRemovable) { $reasons.Add('removable-volume') | Out-Null }
    if ($currentLabel -eq $proposedLabel) { $reasons.Add('label-already-set') | Out-Null }

    $canRename = (($role -eq 'windows-data') -and ($reasons.Count -eq 0))
    $action = if ($canRename) {
        'rename'
    } elseif ($currentLabel -eq $proposedLabel) {
        'unchanged'
    } elseif ($role -in @('steamos-linux-manual', 'linux-dedicated', 'removable-install', 'removable-media')) {
        'guide-only'
    } else {
        'blocked'
    }

    $letterText = if ([string]::IsNullOrWhiteSpace($drive)) { 'sem letra' } else { "$drive`:" }
    $fsText = if ([string]::IsNullOrWhiteSpace($Partition.FileSystem)) { 'Linux/Unknown' } else { [string]$Partition.FileSystem }
    $displayName = "Disco $([int]$Disk.Number) / Particao $([int]$Partition.PartitionNumber) - $letterText - $([double]$Partition.SizeGB)GB - $fsText"

    return [pscustomobject][ordered]@{
        identity        = ('D{0}P{1}' -f [int]$Disk.Number, [int]$Partition.PartitionNumber)
        diskNumber      = [int]$Disk.Number
        partitionNumber = [int]$Partition.PartitionNumber
        driveLetter     = $drive
        sizeGB          = [double]$Partition.SizeGB
        fileSystem      = [string]$Partition.FileSystem
        currentLabel    = $currentLabel
        proposedLabel   = $proposedLabel
        role            = $role
        displayName     = $displayName
        action          = $action
        canRename       = [bool]$canRename
        reasons         = @($reasons.ToArray())
        explanation     = switch ($role) {
            'efi-system' { 'Boot EFI: identifica inicializacao; nao renomear.' }
            'windows-recovery' { 'Recovery Windows: manutencao do sistema; nao renomear.' }
            'windows-system' { 'Windows principal: volume do sistema; nao renomear automaticamente.' }
            'steamos-linux-manual' { 'SteamOS/Linux em disco misto: confirmar pelo disco, particao e tamanho no instalador; Windows nao renomeia.' }
            'linux-dedicated' { 'Linux dedicado: usar como alvo apenas se o usuario confirmar no instalador.' }
            'removable-install' { 'Midia removivel/instalador: usar para boot ou transferencia; nao virar alvo de instalacao.' }
            'removable-media' { 'Midia removivel: revisar manualmente antes de renomear.' }
            'windows-data' { 'Dados Windows: pode receber rotulo pedagogico se aplicacao explicita estiver ligada.' }
            default { 'Revisao manual: sinais insuficientes para renomear com seguranca.' }
        }
    }
}

function Get-BootstrapPartitionLabelPlan {
    $entries = New-Object System.Collections.Generic.List[object]
    foreach ($d in @(Get-BootstrapPhysicalDisksSnapshot)) {
        foreach ($p in @($d.Partitions)) {
            $entries.Add((New-BootstrapPartitionLabelEntry -Disk $d -Partition $p)) | Out-Null
        }
    }
    $renameable = @($entries.ToArray() | Where-Object { [bool]$_.canRename })
    return [ordered]@{
        schemaVersion   = 'partition-labels/v1'
        generatedAt     = (Get-Date).ToString('o')
        entries         = @($entries.ToArray())
        renameableCount = $renameable.Count
        applyOptInEnv   = 'PHASEZERO_PARTITION_LABEL_APPLY=1'
        safetyModel     = 'read-only by default; only mounted non-system data volumes can be renamed'
    }
}

function Set-BootstrapVolumeLabel {
    param(
        [Parameter(Mandatory = $true)][string]$DriveLetter,
        [Parameter(Mandatory = $true)][string]$NewFileSystemLabel
    )

    $drive = ([string]$DriveLetter).Trim().TrimEnd(':').ToUpperInvariant()
    Set-Volume -DriveLetter $drive -NewFileSystemLabel $NewFileSystemLabel -ErrorAction Stop
    return [ordered]@{ status = 'renamed'; driveLetter = $drive; newLabel = $NewFileSystemLabel }
}

function Invoke-BootstrapPartitionLabelPlan {
    param(
        [Parameter(Mandatory = $true)]$Plan,
        [switch]$Apply
    )

    $changed = New-Object System.Collections.Generic.List[object]
    $skipped = New-Object System.Collections.Generic.List[object]
    foreach ($entry in @($Plan.entries)) {
        if (-not [bool]$entry.canRename) {
            $skipped.Add($entry) | Out-Null
            continue
        }
        if (-not $Apply) {
            $skipped.Add($entry) | Out-Null
            continue
        }
        $result = Set-BootstrapVolumeLabel -DriveLetter ([string]$entry.driveLetter) -NewFileSystemLabel ([string]$entry.proposedLabel)
        $changed.Add([ordered]@{ entry = $entry; result = $result }) | Out-Null
    }
    return [ordered]@{
        status       = $(if ($Apply) { 'completed' } else { 'planned' })
        apply        = [bool]$Apply
        changedCount = $changed.Count
        skippedCount = $skipped.Count
        changed      = @($changed.ToArray())
        skipped      = @($skipped.ToArray())
    }
}

function Get-BootstrapPartitionLabelPlanEntries {
    param([AllowNull()]$Plan)

    if ($null -eq $Plan) { return @() }
    try {
        if ($Plan -is [System.Collections.IDictionary]) {
            if ($Plan.Contains('entries')) { return @($Plan['entries']) }
            return @()
        }
        if ($Plan.PSObject.Properties['entries']) { return @($Plan.entries) }
    } catch {
        return @()
    }
    return @()
}

function Get-BootstrapPartitionLabelPlanCounts {
    param([AllowNull()]$Plan)

    $entries = @(Get-BootstrapPartitionLabelPlanEntries -Plan $Plan)
    $renameable = @($entries | Where-Object {
        try { [bool]$_.canRename } catch { $false }
    })
    $blocked = @($entries | Where-Object {
        try { [string]$_.action -eq 'blocked' } catch { $false }
    })
    $guideOnly = @($entries | Where-Object {
        try { [string]$_.action -eq 'guide-only' } catch { $false }
    })
    $unchanged = @($entries | Where-Object {
        try { [string]$_.action -eq 'unchanged' } catch { $false }
    })

    return [ordered]@{
        total      = [int]$entries.Count
        renameable = [int]$renameable.Count
        blocked    = [int]$blocked.Count
        guideOnly  = [int]$guideOnly.Count
        unchanged  = [int]$unchanged.Count
    }
}

function Test-BootstrapPartitionLabelApplyOptIn {
    $value = ([string]$env:PHASEZERO_PARTITION_LABEL_APPLY).Trim().ToLowerInvariant()
    return (@('1', 'true', 'yes', 'y', 'sim', 'on') -contains $value)
}

function Invoke-BootstrapPartitionLabelsMode {
    param(
        [switch]$Apply,
        [switch]$DryRun
    )

    Write-Log ("Modo: PartitionLabels (apply={0}; dryRun={1})" -f [bool]$Apply, [bool]$DryRun)
    $plan = Get-BootstrapPartitionLabelPlan
    $counts = Get-BootstrapPartitionLabelPlanCounts -Plan $plan
    $applyOptIn = Test-BootstrapPartitionLabelApplyOptIn
    $shouldApply = ([bool]$Apply -and [bool]$applyOptIn -and -not [bool]$DryRun)

    Write-Log ("PartitionLabels: particoes={0}; renomeaveis={1}; bloqueadas={2}; guia={3}; optIn={4}" -f [int]$counts.total, [int]$counts.renameable, [int]$counts.blocked, [int]$counts.guideOnly, [bool]$applyOptIn)
    foreach ($entry in @(Get-BootstrapPartitionLabelPlanEntries -Plan $plan)) {
        $reasonText = ''
        try { $reasonText = (@($entry.reasons) -join ',') } catch { $reasonText = '' }
        Write-Log ("PartitionLabels: {0}; papel={1}; atual='{2}'; sugerido='{3}'; acao={4}; motivo=[{5}]" -f [string]$entry.displayName, [string]$entry.role, [string]$entry.currentLabel, [string]$entry.proposedLabel, [string]$entry.action, $reasonText)
    }

    $result = Invoke-BootstrapPartitionLabelPlan -Plan $plan -Apply:$shouldApply
    $payload = [ordered]@{
        status = 'success'
        exitCode = 0
        mode = 'partition-labels'
        generatedAt = (Get-Date).ToString('o')
        logPath = $script:LogPath
        resultPath = $script:ResultPath
        applyRequested = [bool]$Apply
        applyOptIn = [bool]$applyOptIn
        dryRun = [bool]$DryRun
        counts = $counts
        plan = $plan
        partitionLabels = [ordered]@{
            status = [string]$result.status
            result = $result
        }
    }

    if ([bool]$Apply -and -not [bool]$applyOptIn) {
        $payload['status'] = 'blocked'
        $payload['exitCode'] = 2
        $payload['blockerKind'] = 'partition-label-apply-opt-in-missing'
        $payload['action'] = 'set-env-and-rerun'
        $payload['error'] = 'Aplicacao de rotulos exige confirmacao explicita por ambiente.'
        $payload['howToFix'] = 'Revise a grade/resultado. Para aplicar somente volumes seguros, defina PHASEZERO_PARTITION_LABEL_APPLY=1 e rode -ApplyPartitionLabels novamente.'
        Write-Log 'PartitionLabels: apply bloqueado; PHASEZERO_PARTITION_LABEL_APPLY=1 ausente.' 'WARN'
    } elseif ([bool]$Apply -and [bool]$DryRun) {
        $payload['status'] = 'warning'
        $payload['exitCode'] = 0
        $payload['howToFix'] = 'DryRun ativo: nenhuma alteracao foi aplicada.'
        Write-Log 'PartitionLabels: DryRun ativo; nenhuma alteracao aplicada.' 'WARN'
    } elseif ($shouldApply) {
        Write-Log ("PartitionLabels: aplicacao concluida; alterados={0}; pulados={1}" -f [int]$result.changedCount, [int]$result.skippedCount)
    } else {
        Write-Log 'PartitionLabels: diagnostico concluido; nenhuma alteracao aplicada.'
    }

    if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
        Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value $payload
    }
    return $payload
}

function Test-BootstrapOsInstallTargetSafe {
    # REGRA DURA: um disco com qualquer particao do Windows NUNCA e alvo seguro para raw passthrough
    # ou instalador disco-inteiro. So disco interno dedicado, grande e Linux/vazio libera esses metodos.
    param([Parameter(Mandatory = $true)][int]$DiskNumber)

    $disk = @(Get-BootstrapOsInstallDiskTopology | Where-Object { [int]$_.diskNumber -eq $DiskNumber })
    if (@($disk).Count -eq 0) {
        return [ordered]@{ diskNumber = $DiskNumber; safe = $false; isDedicated = $false; reasons = @('disk-not-found'); allowedMethods = @() }
    }
    $d = $disk[0]
    $reasons = New-Object System.Collections.Generic.List[string]
    if ([bool]$d.hasWindows) { $reasons.Add('disk-contains-windows-partitions') | Out-Null }
    if ([bool]$d.isRemovable) { $reasons.Add('disk-is-removable') | Out-Null }
    if (-not [bool]$d.installSizeOk) { $reasons.Add('disk-too-small') | Out-Null }
    if (-not [bool]$d.onlyLinuxOrEmpty) { $reasons.Add('disk-has-non-linux-partitions') | Out-Null }
    $safe = ([bool]$d.isDedicatedLinuxCandidate -and ($reasons.Count -eq 0))
    return [ordered]@{
        diskNumber     = $DiskNumber
        safe           = [bool]$safe
        isDedicated    = [bool]$d.isDedicatedLinuxCandidate
        reasons        = @($reasons.ToArray())
        # Passthrough e disco-inteiro so num disco dedicado; senao nenhum metodo automatizado.
        allowedMethods = $(if ($safe) { @('vm-raw-passthrough', 'native-installer') } else { @() })
    }
}

function Get-BootstrapOsImageCatalog {
    # Catalogo de imagens. URLs multi-GB/variantes mudam por release: a recovery da Valve nao publica
    # SHA256 estavel (manual-verify) e o Bazzite publica SHA256 por release no GitHub. O download real
    # (nos componentes) EXIGE url+sha256 resolvidos e verifica antes de usar; sem verificacao, recusa.
    return [ordered]@{
        'steamos-recovery' = [ordered]@{
            displayName    = 'SteamOS Recovery (Valve, oficial)'
            kind           = 'raw-img'
            url            = 'https://steamdeck-images.steamos.cloud/recovery/steamdeck-recovery-4.img.bz2'
            sha256         = ''
            checksumPolicy = 'manual-verify'
            target         = 'steam-deck'
            officialSource = 'https://store.steampowered.com/steamos/buildyourown'
            notes          = 'Imagem .img crua: grave em USB e reimageie o Steam Deck. NAO e caminho suportado em VM/disco generico.'
        }
        'bazzite' = [ordered]@{
            displayName    = 'Bazzite (SteamOS-like, PC generico)'
            kind           = 'iso'
            url            = ''
            sha256         = ''
            checksumPolicy = 'github-release-sha256'
            target         = 'generic-pc'
            officialSource = 'https://bazzite.gg/'
            notes          = 'ISO com instalador proprio. Baixe a variante adequada (bazzite-deck p/ handhelds, bazzite p/ desktop) e informe o SHA256 publicado no release.'
        }
    }
}

function Get-BootstrapOsInstallPlan {
    # Junta host + topologia + alvo recomendado + imagem + metodos elegiveis num relatorio read-only.
    $hostProfile = Get-BootstrapOsInstallHostProfile
    $topology = @(Get-BootstrapOsInstallDiskTopology)
    $dualBoot = $null
    try { $dualBoot = Get-BootstrapDualBootInfo } catch { $dualBoot = $null }

    $dedicated = @($topology | Where-Object { [bool]$_.isDedicatedLinuxCandidate })
    $manualPartitionTargets = @(Get-BootstrapOsInstallManualPartitionTargets -Topology $topology)
    $removableTargets = @($topology | Where-Object { [bool]$_.isRemovable })
    $recommendedTarget = if (@($dedicated).Count -gt 0) { [int]@($dedicated)[0].diskNumber } else { $null }

    $catalog = Get-BootstrapOsImageCatalog
    $image = $catalog[[string]$hostProfile.recommendedImage]

    $eligibleMethods = @()
    $blockReasons = New-Object System.Collections.Generic.List[string]
    if ($null -eq $recommendedTarget) {
        $blockReasons.Add('no-dedicated-disk') | Out-Null
        $blockReasons.Add('no-dedicated-internal-linux-disk') | Out-Null
    } else {
        $safety = Test-BootstrapOsInstallTargetSafe -DiskNumber $recommendedTarget
        $eligibleMethods = @($safety.allowedMethods)
        foreach ($r in @($safety.reasons)) { $blockReasons.Add($r) | Out-Null }
    }
    # SteamOS recovery (raw .img) nao roda em VM: VM so vale para Bazzite (ISO).
    if ([string]$hostProfile.recommendedImage -eq 'steamos-recovery') {
        $eligibleMethods = @($eligibleMethods | Where-Object { $_ -ne 'vm-raw-passthrough' })
    }

    $warnings = @()
    if ($dualBoot) { try { $warnings = @($dualBoot.Warnings) } catch { $warnings = @() } }

    return [ordered]@{
        schemaVersion     = 'os-install/v1'
        generatedAt       = (Get-Date).ToString('o')
        host              = $hostProfile
        recommendedImage  = [string]$hostProfile.recommendedImage
        image             = $image
        topology          = $topology
        recommendedTarget = $recommendedTarget
        manualPartitionTargets = @($manualPartitionTargets)
        removableTargets  = @($removableTargets)
        eligibleMethods   = @($eligibleMethods)
        blockReasons      = @($blockReasons.ToArray())
        warnings          = @($warnings)
        neverWritesDisk   = $true
    }
}

function Get-BootstrapVBoxManagePath {
    # Caminho do VBoxManage.exe (VirtualBox). Mockavel. '' se ausente.
    foreach ($c in @(
        (Join-Path $env:ProgramFiles 'Oracle\VirtualBox\VBoxManage.exe'),
        (Join-Path ${env:ProgramFiles(x86)} 'Oracle\VirtualBox\VBoxManage.exe')
    )) {
        if (-not [string]::IsNullOrWhiteSpace($c) -and (Test-Path -LiteralPath $c -PathType Leaf)) { return $c }
    }
    $cmd = Resolve-CommandPath -Name 'VBoxManage'
    if (-not [string]::IsNullOrWhiteSpace($cmd)) { return $cmd }
    return ''
}

function New-BootstrapRawVmdkPlan {
    # Plano (sem efeito) do .vmdk raw que mapeia o disco fisico DEDICADO para a VM. So gera o comando
    # quando o disco e seguro (sem particoes do Windows); senao retorna blocked com motivo.
    param(
        [Parameter(Mandatory = $true)][int]$DiskNumber,
        [Parameter(Mandatory = $true)][string]$OutputPath
    )

    $safety = Test-BootstrapOsInstallTargetSafe -DiskNumber $DiskNumber
    if (-not [bool]$safety.safe) {
        return [ordered]@{ status = 'blocked'; reasons = @($safety.reasons); diskNumber = $DiskNumber }
    }
    $physical = "\\.\PhysicalDrive$DiskNumber"
    return [ordered]@{
        status        = 'ready'
        diskNumber    = $DiskNumber
        physicalDrive = $physical
        vmdkPath      = $OutputPath
        command       = @('internalcommands', 'createrawvmdk', '-filename', $OutputPath, '-rawdisk', $physical)
    }
}

function Get-BootstrapOsInstallStagingRoot {
    return (Join-Path (Get-BootstrapDataRoot) 'os-install')
}

function Resolve-BootstrapOsImageDownload {
    # Resolve url+sha256 para a imagem. So aceita quando ambos vierem de fonte explicita (env ou
    # ComponentDef); imagens multi-GB nao sao hardcoded e o checksum e OBRIGATORIO antes de usar.
    param(
        [Parameter(Mandatory = $true)][string]$ImageKey,
        [AllowNull()]$ComponentDef = $null
    )
    $catalog = Get-BootstrapOsImageCatalog
    $entry = if ($catalog.Contains($ImageKey)) { $catalog[$ImageKey] } else { $null }

    $url = [string]$env:PHASEZERO_OS_IMAGE_URL
    $sha = [string]$env:PHASEZERO_OS_IMAGE_SHA256
    if ([string]::IsNullOrWhiteSpace($url) -and $ComponentDef) { try { $url = [string]$ComponentDef.ImageUrl } catch { } }
    if ([string]::IsNullOrWhiteSpace($sha) -and $ComponentDef) { try { $sha = [string]$ComponentDef.ImageSha256 } catch { } }
    if ([string]::IsNullOrWhiteSpace($url) -and $entry) { $url = [string]$entry.url }

    $hasUrl = -not [string]::IsNullOrWhiteSpace($url)
    $hasSha = -not [string]::IsNullOrWhiteSpace($sha)
    return [ordered]@{
        imageKey       = $ImageKey
        url            = $url
        sha256         = $sha
        officialSource = $(if ($entry) { [string]$entry.officialSource } else { '' })
        resolved       = ($hasUrl -and $hasSha)
        missing        = @(@(if (-not $hasUrl) { 'url' }) + @(if (-not $hasSha) { 'sha256' }))
    }
}

function Ensure-BootstrapOsInstallDetect {
    # Componente read-only: gera e loga o plano de instalacao (host, imagem, topologia, alvo seguro,
    # metodos elegiveis). NUNCA escreve nada.
    param([Parameter(Mandatory = $true)][hashtable]$State)

    $plan = Get-BootstrapOsInstallPlan
    Write-Log ("os-install-detect: host={0}; imagem={1}; alvoDisco={2}; metodos=[{3}]; bloqueios=[{4}]" -f `
        [string]$plan.host.hostType, [string]$plan.recommendedImage, $(if ($null -ne $plan.recommendedTarget) { $plan.recommendedTarget } else { 'nenhum' }), (@($plan.eligibleMethods) -join ','), (@($plan.blockReasons) -join ','))
    foreach ($w in @($plan.warnings)) { Write-Log ("os-install-detect: aviso dual-boot: {0}" -f [string]$w) 'WARN' }
    if (@($plan.eligibleMethods).Count -eq 0) {
        Write-Log 'os-install-detect: nenhum metodo automatizado elegivel (sem disco dedicado seguro). PhaseZero so faz deteccao/guia; nunca grava em disco do Windows.' 'WARN'
    }
    return [ordered]@{ status = 'completed'; readOnly = $true; plan = $plan; dryRun = [bool]$State.DryRun }
}

function Ensure-BootstrapPartitionLabels {
    # Plano pedagogico de rotulos. Por padrao nao altera nada; rename real exige opt-in via ambiente.
    param([Parameter(Mandatory = $true)][hashtable]$State)

    $plan = Get-BootstrapPartitionLabelPlan
    $applyOptIn = ([string]$env:PHASEZERO_PARTITION_LABEL_APPLY).Trim().ToLowerInvariant() -in @('1', 'true', 'yes', 'on')

    Write-Log ("partition-labels: {0} particao(oes); renomeaveis={1}; optIn={2}; dryRun={3}" -f @($plan.entries).Count, [int]$plan.renameableCount, [bool]$applyOptIn, [bool]$State.DryRun)
    foreach ($entry in @($plan.entries)) {
        Write-Log ("partition-labels: {0}; papel={1}; atual='{2}'; sugerido='{3}'; acao={4}; motivo=[{5}]" -f [string]$entry.displayName, [string]$entry.role, [string]$entry.currentLabel, [string]$entry.proposedLabel, [string]$entry.action, (@($entry.reasons) -join ','))
    }

    if ([bool]$State.DryRun -or (-not $applyOptIn)) {
        $result = Invoke-BootstrapPartitionLabelPlan -Plan $plan
        if (-not $applyOptIn) {
            Write-Log 'partition-labels: plano gerado. Para aplicar rotulos seguros, defina PHASEZERO_PARTITION_LABEL_APPLY=1 e rode novamente.' 'WARN'
        }
        return [ordered]@{ status = 'planned'; plan = $plan; result = $result; dryRun = [bool]$State.DryRun; applyOptIn = [bool]$applyOptIn }
    }

    $result = Invoke-BootstrapPartitionLabelPlan -Plan $plan -Apply
    foreach ($change in @($result.changed)) {
        $entry = $change.entry
        Write-Log ("partition-labels: rotulo aplicado em {0}: '{1}' -> '{2}'" -f [string]$entry.driveLetter, [string]$entry.currentLabel, [string]$entry.proposedLabel)
        if ($State.ContainsKey('Changes')) {
            try {
                Register-BootstrapChange -State $State -Type VolumeLabel -Target ("{0}:" -f [string]$entry.driveLetter) -OldValue ([string]$entry.currentLabel) -NewValue ([string]$entry.proposedLabel) -Operation 'partition-label-rename' -RollbackAction 'restore-volume-label' -Reversible 'full' -Component 'os-partition-labels'
            } catch { Write-Verbose $_.Exception.Message }
        }
    }
    return [ordered]@{ status = 'completed'; plan = $plan; result = $result; dryRun = $false; applyOptIn = $true }
}

function Ensure-BootstrapOsInstallVm {
    # Metodo 2 (VM isolada, raw passthrough). Estagia somente; NUNCA roda o install destrutivo.
    # Bloqueia se: imagem raw SteamOS (nao roda em VM), sem disco dedicado seguro, sem VirtualBox,
    # sem admin, ou imagem sem url+sha256 verificavel.
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [AllowNull()]$ComponentDef = $null
    )

    $plan = Get-BootstrapOsInstallPlan
    $imageKey = [string]$plan.recommendedImage
    if ($imageKey -eq 'steamos-recovery') {
        Write-Log 'os-install-vm: a recovery do SteamOS e imagem .img crua e NAO instala via VM; use os-install-native (USB de recovery).' 'WARN'
        return [ordered]@{ status = 'blocked'; reason = 'steamos-recovery-not-vm-installable'; image = $imageKey; dryRun = [bool]$State.DryRun }
    }
    $target = $plan.recommendedTarget
    if ($null -eq $target) {
        Write-Log 'os-install-vm: bloqueado: nenhum disco dedicado seguro detectado.' 'WARN'
        return [ordered]@{ status = 'blocked'; reason = 'no-dedicated-disk'; dryRun = [bool]$State.DryRun }
    }
    $stagingRoot = Get-BootstrapOsInstallStagingRoot
    $vmdkPath = Join-Path $stagingRoot ("rawdisk-{0}.vmdk" -f $target)
    $vmdkPlan = New-BootstrapRawVmdkPlan -DiskNumber $target -OutputPath $vmdkPath
    if ([string]$vmdkPlan.status -eq 'blocked') {
        Write-Log ("os-install-vm: bloqueado por seguranca do disco: {0}" -f (@($vmdkPlan.reasons) -join ',')) 'WARN'
        return [ordered]@{ status = 'blocked'; reason = 'unsafe-target'; reasons = @($vmdkPlan.reasons); dryRun = [bool]$State.DryRun }
    }

    $download = Resolve-BootstrapOsImageDownload -ImageKey $imageKey -ComponentDef $ComponentDef
    if ([bool]$State.DryRun) {
        Write-Log ("os-install-vm: (dry-run) criaria vmdk para {0} via: VBoxManage {1}" -f [string]$vmdkPlan.physicalDrive, (@($vmdkPlan.command) -join ' '))
        return [ordered]@{ status = 'planned'; image = $imageKey; target = $target; vmdkPlan = $vmdkPlan; imageResolved = [bool]$download.resolved; dryRun = $true }
    }

    if (-not (Test-IsAdmin)) {
        Write-Log 'os-install-vm: requer administrador para mapear o disco fisico.' 'WARN'
        return [ordered]@{ status = 'blocked'; reason = 'requires-admin'; dryRun = $false }
    }
    $vbox = Get-BootstrapVBoxManagePath
    if ([string]::IsNullOrWhiteSpace($vbox)) {
        Write-Log 'os-install-vm: VirtualBox (VBoxManage) nao encontrado. Instale o VirtualBox e rode novamente.' 'WARN'
        return [ordered]@{ status = 'blocked'; reason = 'virtualbox-missing'; dryRun = $false }
    }
    if (-not [bool]$download.resolved) {
        Write-Log ("os-install-vm: imagem sem {0}. Informe PHASEZERO_OS_IMAGE_URL e PHASEZERO_OS_IMAGE_SHA256 (verificado) da fonte oficial: {1}" -f (@($download.missing) -join '+'), [string]$download.officialSource) 'WARN'
        return [ordered]@{ status = 'blocked'; reason = 'image-url-or-sha-missing'; missing = @($download.missing); officialSource = [string]$download.officialSource; dryRun = $false }
    }

    $null = New-Item -ItemType Directory -Path $stagingRoot -Force -ErrorAction SilentlyContinue
    & $vbox @($vmdkPlan.command) 2>&1 | ForEach-Object { Write-Log ("VBoxManage: {0}" -f $_) }
    if ($State.ContainsKey('Changes')) {
        try { Register-BootstrapChange -State $State -Type File -Target $vmdkPath -OldValue $null -NewValue 'raw-vmdk-created' -Operation 'os-install-raw-vmdk' -RollbackAction 'delete-file' -Reversible 'full' -Component 'os-install-vm' } catch { Write-Verbose $_.Exception.Message }
    }
    Write-Log ("os-install-vm: vmdk criado em {0}. Proximo passo MANUAL: abra o VirtualBox como Administrador, crie a VM, anexe este vmdk e a ISO, instale confirmando a particao do disco dedicado. O Windows fica invisivel/isolado." -f $vmdkPath)
    return [ordered]@{ status = 'completed'; image = $imageKey; target = $target; vmdkPath = $vmdkPath; startedInstall = $false; dryRun = $false }
}

function Ensure-BootstrapOsInstallNative {
    # Metodo 1 (boot nativo do instalador). Baixa+verifica e estagia a imagem + guia; o
    # particionamento/format fica MANUAL no instalador. NUNCA grava no disco do sistema a partir do Windows.
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [AllowNull()]$ComponentDef = $null
    )

    $plan = Get-BootstrapOsInstallPlan
    $imageKey = [string]$plan.recommendedImage
    $download = Resolve-BootstrapOsImageDownload -ImageKey $imageKey -ComponentDef $ComponentDef
    $stagingRoot = Get-BootstrapOsInstallStagingRoot

    if ([bool]$State.DryRun) {
        Write-Log ("os-install-native: (dry-run) baixaria/verificaria a imagem '{0}' e prepararia USB (Ventoy)/boot. Particionamento fica manual no instalador." -f $imageKey)
        return [ordered]@{ status = 'planned'; image = $imageKey; imageResolved = [bool]$download.resolved; officialSource = [string]$download.officialSource; dryRun = $true }
    }
    if (-not [bool]$download.resolved) {
        Write-Log ("os-install-native: imagem sem {0}. Informe PHASEZERO_OS_IMAGE_URL e PHASEZERO_OS_IMAGE_SHA256 da fonte oficial: {1}" -f (@($download.missing) -join '+'), [string]$download.officialSource) 'WARN'
        return [ordered]@{ status = 'blocked'; reason = 'image-url-or-sha-missing'; missing = @($download.missing); officialSource = [string]$download.officialSource; dryRun = $false }
    }

    $null = New-Item -ItemType Directory -Path $stagingRoot -Force -ErrorAction SilentlyContinue
    $imageName = [System.IO.Path]::GetFileName(([uri][string]$download.url).AbsolutePath)
    if ([string]::IsNullOrWhiteSpace($imageName)) { $imageName = ("{0}.img" -f $imageKey) }
    $imagePath = Join-Path $stagingRoot $imageName

    if (-not (Test-Path -LiteralPath $imagePath -PathType Leaf)) {
        Invoke-WebRequestWithRetry -Uri ([string]$download.url) -OutFile $imagePath -OperationName ("download da imagem {0}" -f $imageKey)
    }
    $actual = (Get-BootstrapFileSha256 -Path $imagePath)
    if ($actual -ne ([string]$download.sha256).ToLowerInvariant()) {
        Write-Log ("os-install-native: SHA256 da imagem NAO confere (esperado {0}, obtido {1}); arquivo descartado." -f [string]$download.sha256, $actual) 'WARN'
        try { Remove-Item -LiteralPath $imagePath -Force -ErrorAction SilentlyContinue } catch { }
        return [ordered]@{ status = 'blocked'; reason = 'sha256-mismatch'; dryRun = $false }
    }
    if ($State.ContainsKey('Changes')) {
        try { Register-BootstrapChange -State $State -Type File -Target $imagePath -OldValue $null -NewValue 'os-image-staged' -Operation 'os-install-image-staged' -RollbackAction 'delete-file' -Reversible 'full' -Component 'os-install-native' } catch { Write-Verbose $_.Exception.Message }
    }
    Write-Log ("os-install-native: imagem verificada (sha256 ok) em {0}. Proximo passo MANUAL: grave em USB com Ventoy/Rufus e dê boot pelo USB; no instalador escolha particionamento MANUAL e selecione o disco dedicado. PhaseZero nao grava no disco do sistema." -f $imagePath)
    return [ordered]@{ status = 'completed'; image = $imageKey; imagePath = $imagePath; verified = $true; usbWritten = $false; dryRun = $false }
}

function Get-BootstrapDualBootRecommendations {
    param([AllowNull()]$DualBootInfo)
    if ($null -eq $DualBootInfo) { $DualBootInfo = Get-BootstrapDualBootInfo }
    $recs = New-Object System.Collections.Generic.List[string]
    if (-not $DualBootInfo.IsDualBoot) {
        $recs.Add('Nenhum dual boot detectado. Nenhuma acao necessaria.')
        return @($recs.ToArray())
    }
    if ($DualBootInfo.FastStartup.Enabled) {
        $recs.Add('[CRITICO] Desabilitar Fast Startup: evita corrupcao de particiones Linux.')
    }
    if ($DualBootInfo.BitLocker.CEnabled) {
        $recs.Add('[ATENCAO] BitLocker ativo: suspender antes de modificar bootloader.')
    }
    if ($DualBootInfo.GrubDetected) {
        $recs.Add('[INFO] GRUB detectado: ' + $DualBootInfo.GrubEfiPath)
    }
    $steamOsEfi = @()
    try { $steamOsEfi = @($DualBootInfo.SteamOsEfiInstallations) } catch { $steamOsEfi = @() }
    if ($steamOsEfi.Count -gt 0) {
        $needsCustom = @($steamOsEfi | Where-Object { -not [bool]$_.customConfigManaged -or -not [bool]$_.grubConfigHasWindowsEntry })
        if ($needsCustom.Count -gt 0) {
            $recs.Add('[ACAO] Aplicar custom.cfg gerenciado do GRUB SteamOS para mostrar Windows Boot Manager e timeout seguro.')
        }
        $needsFallback = @($steamOsEfi | Where-Object { -not [bool]$_.fallbackBootMatchesGrub })
        if ($needsFallback.Count -gt 0) {
            $recs.Add('[ACAO] Instalar fallback UEFI EFI\Boot\bootx64.efi apontando para o GRUB SteamOS quando NVRAM/boot order falha.')
        }
    }
    if ($DualBootInfo.LinuxPartitions.Count -gt 0) {
        $recs.Add("[INFO] $($DualBootInfo.LinuxPartitions.Count) particao(oes) Linux detectada(s).")
    }
    if (-not [bool]$DualBootInfo.IsAdmin) {
        $recs.Add('[ACAO] Execute como Administrador para auditar/priorizar a entrada SteamOS no firmware quando o power-on cai direto na BIOS.')
    }
    $recs.Add('[DICA] Use o menu UEFI da BIOS (F12/F2/Del) como alternativa segura para trocar de SO.')
    return @($recs.ToArray())
}

# --- Reboot Switch ---

function Get-BootstrapAlternateBootEntries {
    if (-not (Test-IsAdmin)) { return @() }
    $entries = Get-BootstrapEfiEntries
    $alternates = @()
    foreach ($entry in $entries) {
        if ($entry.Type -ne 'entry') { continue }
        $d = [string]$entry.Description
        $p = [string]$entry.Path
        $isWindowsEntry = ($d -match 'Windows Boot Manager' -or $p -match 'bootmgfw\.efi')
        if (-not $isWindowsEntry -and $entry.Id) {
            $alternates += @{
                Id          = $entry.Id
                Description = $d
                Path        = $p
            }
        }
    }
    return @($alternates)
}

function ConvertFrom-BootstrapBcdEditOutput {
    param([AllowNull()][string]$Text)

    $entries = New-Object System.Collections.Generic.List[object]
    if ([string]::IsNullOrWhiteSpace($Text)) { return @() }

    $current = $null
    $currentRaw = New-Object System.Collections.Generic.List[string]
    $lastKey = ''
    $lines = @(($Text -replace "`r", '') -split "`n")
    for ($i = 0; $i -lt $lines.Count; $i++) {
        $line = $lines[$i]
        $rawLine = [string]$line
        if ([string]::IsNullOrWhiteSpace($rawLine)) {
            continue
        }
        if ($rawLine -match '^-{3,}$') {
            continue
        }
        $nextLine = if (($i + 1) -lt $lines.Count) { [string]$lines[$i + 1] } else { '' }
        if ($rawLine -match '^\S.*$' -and $nextLine -match '^-{3,}$') {
            if ($current -and $current.Contains('identifier')) {
                $current['raw'] = @($currentRaw.ToArray())
                $entries.Add([pscustomobject]$current)
            }
            $current = [ordered]@{ section = $rawLine.Trim(); properties = [ordered]@{} }
            $currentRaw = New-Object System.Collections.Generic.List[string]
            $currentRaw.Add($rawLine)
            $lastKey = ''
            $i++
            continue
        }
        if (-not $current) {
            $current = [ordered]@{ section = 'Unknown'; properties = [ordered]@{} }
        }
        $currentRaw.Add($rawLine)
        if ($rawLine -match '^\s*([\p{L}A-Za-z0-9_\-]+)\s+(.+?)\s*$') {
            $key = $matches[1].Trim().ToLowerInvariant()
            $value = $matches[2].Trim()
            if ($current['properties'].Contains($key)) {
                $current['properties'][$key] = @($current['properties'][$key]) + @($value)
            } else {
                $current['properties'][$key] = $value
            }
            if ($key -in @('identifier','identificador')) {
                $current['identifier'] = $value
            }
            $lastKey = $key
        } elseif ($lastKey -and $rawLine -match '^\s+(\{[A-Za-z0-9\-]+\})\s*$') {
            $value = $matches[1]
            $current['properties'][$lastKey] = @($current['properties'][$lastKey]) + @($value)
        }
    }

    if ($current -and $current.Contains('identifier')) {
        $current['raw'] = @($currentRaw.ToArray())
        $entries.Add([pscustomobject]$current)
    }

    return @($entries.ToArray())
}

function Get-BootstrapBcdProperty {
    param(
        [Parameter(Mandatory = $true)]$Entry,
        [Parameter(Mandatory = $true)][string[]]$Names
    )

    foreach ($name in @($Names)) {
        $key = $name.ToLowerInvariant()
        if ($Entry.properties -and $Entry.properties.Contains($key)) {
            return $Entry.properties[$key]
        }
    }
    return $null
}

function Get-BootstrapBcdDescription {
    param([Parameter(Mandatory = $true)]$Entry)
    $value = Get-BootstrapBcdProperty -Entry $Entry -Names @('description','descricao','descrição')
    if ($null -eq $value) { return '' }
    return [string](@($value)[0])
}

function Resolve-BootstrapBcdAliasTargetId {
    param(
        [Parameter(Mandatory = $true)]$Entries,
        [AllowNull()][string]$AliasId = '{current}',
        [AllowNull()][string]$DefaultId = '',
        [AllowNull()][string[]]$DisplayOrder = @()
    )

    $alias = ([string]$AliasId).Trim().ToLowerInvariant()
    if ([string]::IsNullOrWhiteSpace($alias) -or $alias -notmatch '^\{.+\}$') {
        return ''
    }

    $aliasEntry = @($Entries | Where-Object { [string]$_.identifier -eq $alias }) | Select-Object -First 1
    $guidEntries = @($Entries | Where-Object {
        $id = ([string]$_.identifier).Trim().ToLowerInvariant()
        $id -match '^\{[0-9a-f\-]{36}\}$'
    })

    if ($aliasEntry) {
        $aliasDescription = [string](Get-BootstrapBcdDescription -Entry $aliasEntry)
        $aliasDevice = [string](@(Get-BootstrapBcdProperty -Entry $aliasEntry -Names @('device','dispositivo'))[0])
        $aliasOsDevice = [string](@(Get-BootstrapBcdProperty -Entry $aliasEntry -Names @('osdevice','osdispositivo'))[0])

        foreach ($candidate in @($guidEntries)) {
            $candidateDescription = [string](Get-BootstrapBcdDescription -Entry $candidate)
            $candidateDevice = [string](@(Get-BootstrapBcdProperty -Entry $candidate -Names @('device','dispositivo'))[0])
            $candidateOsDevice = [string](@(Get-BootstrapBcdProperty -Entry $candidate -Names @('osdevice','osdispositivo'))[0])
            $sameDescription = (-not [string]::IsNullOrWhiteSpace($aliasDescription)) -and ($candidateDescription -eq $aliasDescription)
            $sameDevice = (-not [string]::IsNullOrWhiteSpace($aliasDevice)) -and ($candidateDevice -eq $aliasDevice)
            $sameOsDevice = (-not [string]::IsNullOrWhiteSpace($aliasOsDevice)) -and ($candidateOsDevice -eq $aliasOsDevice)
            if ($sameDescription -or $sameDevice -or $sameOsDevice) {
                return [string]$candidate.identifier
            }
        }
    }

    $normalizedDefault = ([string]$DefaultId).Trim().ToLowerInvariant()
    if ($normalizedDefault -match '^\{[0-9a-f\-]{36}\}$') {
        return $normalizedDefault
    }

    foreach ($displayId in @($DisplayOrder)) {
        $normalizedDisplayId = ([string]$displayId).Trim().ToLowerInvariant()
        if ($normalizedDisplayId -match '^\{[0-9a-f\-]{36}\}$') {
            return $normalizedDisplayId
        }
    }

    return ''
}

function Test-BootstrapBcdEntryPhantom {
    param([Parameter(Mandatory = $true)]$Entry)

    $device = @(
        @(Get-BootstrapBcdProperty -Entry $Entry -Names @('device','dispositivo')),
        @(Get-BootstrapBcdProperty -Entry $Entry -Names @('osdevice','osdispositivo'))
    )
    foreach ($value in @($device)) {
        if ([string]$value -match '(?i)^unknown$') { return $true }
    }
    return $false
}

function Get-BootstrapWindowsBootManagerState {
    param([AllowNull()][string]$BcdText = $null)

    $rawText = $BcdText
    $commandError = ''
    if ([string]::IsNullOrWhiteSpace($rawText)) {
        try {
            $rawText = (& bcdedit /enum all /v 2>&1 | Out-String)
        } catch {
            $commandError = $_.Exception.Message
            $rawText = ''
        }
    }

    $entries = @(ConvertFrom-BootstrapBcdEditOutput -Text $rawText)
    $bootmgr = $entries | Where-Object { [string]$_.identifier -eq '{bootmgr}' } | Select-Object -First 1
    $displayOrder = @()
    $default = ''
    $timeout = $null

    if ($bootmgr) {
        $displayOrder = @((Get-BootstrapBcdProperty -Entry $bootmgr -Names @('displayorder','ordemdeexibicao','ordemexibicao')) | ForEach-Object { [string]$_ } | Where-Object { $_ -match '^\{.+\}$' })
        $default = [string](@(Get-BootstrapBcdProperty -Entry $bootmgr -Names @('default','padrao','padrão'))[0])
        $timeoutValue = [string](@(Get-BootstrapBcdProperty -Entry $bootmgr -Names @('timeout','tempo'))[0])
        if ($timeoutValue -match '^\d+$') { $timeout = [int]$timeoutValue }
    }

    $resolvedCurrentId = Resolve-BootstrapBcdAliasTargetId -Entries $entries -AliasId '{current}' -DefaultId $default -DisplayOrder $displayOrder
    $resolvedDefaultId = ([string]$default).Trim().ToLowerInvariant()
    if ($resolvedDefaultId -eq '{current}') {
        $resolvedDefaultId = $resolvedCurrentId
    }
    if ($resolvedDefaultId -eq '{default}') {
        $resolvedDefaultId = ''
    }

    $entryRows = New-Object System.Collections.Generic.List[object]
    foreach ($entry in @($entries)) {
        $id = ([string]$entry.identifier).Trim().ToLowerInvariant()
        if ([string]::IsNullOrWhiteSpace($id)) { continue }
        $description = Get-BootstrapBcdDescription -Entry $entry
        if ([string]::IsNullOrWhiteSpace($description)) {
            $description = "[sem descricao] $id"
        }
        $entryRows.Add([ordered]@{
            id = $id
            section = [string]$entry.section
            description = $description
            device = [string](@(Get-BootstrapBcdProperty -Entry $entry -Names @('device','dispositivo'))[0])
            osdevice = [string](@(Get-BootstrapBcdProperty -Entry $entry -Names @('osdevice','osdispositivo'))[0])
            inDisplayOrder = (@($displayOrder) -contains $id)
            isDefault = ($id -eq [string]$default -or (-not [string]::IsNullOrWhiteSpace($resolvedDefaultId) -and $id -eq $resolvedDefaultId))
            isCurrent = ($id -eq '{current}' -or (-not [string]::IsNullOrWhiteSpace($resolvedCurrentId) -and $id -eq $resolvedCurrentId))
            isPhantom = (Test-BootstrapBcdEntryPhantom -Entry $entry)
        })
    }

    return [ordered]@{
        IsAdmin = Test-IsAdmin
        CommandError = $commandError
        Default = ([string]$default).Trim().ToLowerInvariant()
        ResolvedDefault = $resolvedDefaultId
        ResolvedCurrent = $resolvedCurrentId
        Timeout = $timeout
        DisplayOrder = @($displayOrder)
        Entries = @($entryRows.ToArray())
        PhantomEntries = @($entryRows.ToArray() | Where-Object { $_.isPhantom })
        RawText = $rawText
    }
}

function Get-BootstrapFirmwareBootManagerState {
    param([AllowNull()][string]$BcdText = $null)

    $rawText = $BcdText
    $commandError = ''
    if ([string]::IsNullOrWhiteSpace($rawText)) {
        try {
            $rawText = (& bcdedit /enum firmware /v 2>&1 | Out-String)
        } catch {
            $commandError = $_.Exception.Message
            $rawText = ''
        }
    }

    $entries = @(ConvertFrom-BootstrapBcdEditOutput -Text $rawText)
    $fwbootmgr = $entries | Where-Object { [string]$_.identifier -eq '{fwbootmgr}' } | Select-Object -First 1
    $displayOrder = @()
    $bootSequence = ''
    if ($fwbootmgr) {
        $displayOrder = @((Get-BootstrapBcdProperty -Entry $fwbootmgr -Names @('displayorder','ordemdeexibicao','ordemexibicao')) | ForEach-Object { [string]$_ } | Where-Object { $_ -match '^\{.+\}$' })
        $bootSequence = [string](@(Get-BootstrapBcdProperty -Entry $fwbootmgr -Names @('bootsequence','sequenciadeinicializacao','sequênciadeinicialização'))[0])
    }

    $entryRows = New-Object System.Collections.Generic.List[object]
    foreach ($entry in @($entries)) {
        $id = ([string]$entry.identifier).Trim().ToLowerInvariant()
        if ([string]::IsNullOrWhiteSpace($id) -or $id -eq '{fwbootmgr}') { continue }
        $description = Get-BootstrapBcdDescription -Entry $entry
        $path = [string](@(Get-BootstrapBcdProperty -Entry $entry -Names @('path','caminho'))[0])
        $isSteamOs = ($description -match '(?i)steamos|steam|linux|grub|bazzite|arch') -or ($path -match '(?i)\\EFI\\steamos\\grubx64\.efi|grubx64\.efi|shimx64\.efi')
        $entryRows.Add([pscustomobject][ordered]@{
            id = $id
            description = $description
            path = $path
            inDisplayOrder = (@($displayOrder) -contains $id)
            isSteamOsCandidate = [bool]$isSteamOs
        }) | Out-Null
    }

    return [ordered]@{
        IsAdmin = Test-IsAdmin
        CommandError = $commandError
        DisplayOrder = @($displayOrder)
        BootSequence = $bootSequence
        Entries = @($entryRows.ToArray())
        SteamOsCandidates = @($entryRows.ToArray() | Where-Object { $_.isSteamOsCandidate })
        RawText = $rawText
    }
}

function Backup-BootstrapWindowsBootManager {
    if (-not (Test-IsAdmin)) { throw 'Backup-BootstrapWindowsBootManager requer privilegios de administrador.' }
    $backupDir = Join-Path (Get-BootstrapDataRoot) 'bcd-backups'
    if (-not (Test-Path $backupDir)) { New-Item -Path $backupDir -ItemType Directory -Force | Out-Null }
    $backupPath = Join-Path $backupDir ("bcd_backup_{0}.bak" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
    $output = & bcdedit /export $backupPath 2>&1
    if ($LASTEXITCODE -ne 0) {
        throw "Falha ao exportar BCD: $output"
    }
    Write-Log "BCD backup criado: $backupPath"
    return $backupPath
}

function Set-BootstrapFirmwareBootDefault {
    param(
        [Parameter(Mandatory = $true)][string]$EntryGuid,
        [AllowNull()][string]$BcdText = $null,
        [switch]$ClearBootSequence,
        [switch]$DryRun
    )

    $state = Get-BootstrapFirmwareBootManagerState -BcdText $BcdText
    $normalized = ([string]$EntryGuid).Trim().ToLowerInvariant()
    $entryIds = @($state.Entries | ForEach-Object { [string]$_.id })
    if (@($entryIds) -notcontains $normalized) { throw "Entrada firmware desconhecida: $EntryGuid" }

    $actions = New-Object System.Collections.Generic.List[string]
    $actions.Add("displayorder-addfirst=$normalized") | Out-Null
    if ($ClearBootSequence -or -not [string]::IsNullOrWhiteSpace([string]$state.BootSequence)) {
        $actions.Add('clear-bootsequence') | Out-Null
    }

    if ($DryRun) {
        return [ordered]@{ Success = $true; Changed = $false; DryRun = $true; Backup = ''; TargetGuid = $normalized; Actions = @($actions.ToArray()) }
    }
    if (-not (Test-IsAdmin)) { throw 'Set-BootstrapFirmwareBootDefault requer privilegios de administrador.' }

    $backupPath = Backup-BootstrapWindowsBootManager
    $output = & bcdedit /set '{fwbootmgr}' displayorder $normalized /addfirst 2>&1
    if ($LASTEXITCODE -ne 0) { throw "Falha ao priorizar entrada firmware: $output" }

    if (@($actions.ToArray()) -contains 'clear-bootsequence') {
        $deleteOutput = & bcdedit /deletevalue '{fwbootmgr}' bootsequence 2>&1
        if ($LASTEXITCODE -ne 0 -and ([string]$deleteOutput -notmatch '(?i)(not found|não.*encontr|nao.*encontr|elemento.*não|elemento.*nao)')) {
            throw "Falha ao limpar bootsequence firmware: $deleteOutput"
        }
    }

    return [ordered]@{ Success = $true; Changed = $true; DryRun = $false; Backup = $backupPath; TargetGuid = $normalized; Actions = @($actions.ToArray()) }
}

function Get-BootstrapBcdBackups {
    # Lista os backups de BCD (.bak) criados por Backup-BootstrapWindowsBootManager, mais novos primeiro.
    $backupDir = Join-Path (Get-BootstrapDataRoot) 'bcd-backups'
    if (-not (Test-Path -LiteralPath $backupDir)) { return @() }
    return @(Get-ChildItem -Path $backupDir -Filter 'bcd_backup_*.bak' -File -ErrorAction SilentlyContinue |
        Sort-Object LastWriteTime -Descending |
        ForEach-Object { [ordered]@{ Path = $_.FullName; Name = $_.Name; Created = $_.LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss') } })
}

function Restore-BootstrapWindowsBootManager {
    # Recuperacao: restaura o BCD a partir de um backup .bak (bcdedit /import). Requer administrador.
    param([Parameter(Mandatory = $true)][string]$BackupPath)

    if (-not (Test-IsAdmin)) { throw 'Restore-BootstrapWindowsBootManager requer privilegios de administrador.' }
    if ([string]::IsNullOrWhiteSpace($BackupPath) -or -not (Test-Path -LiteralPath $BackupPath -PathType Leaf)) {
        throw "Backup de BCD nao encontrado: $BackupPath"
    }
    $output = & bcdedit /import "$BackupPath" 2>&1
    if ($LASTEXITCODE -ne 0) { throw "Falha ao restaurar BCD a partir de '$BackupPath': $output" }
    Write-Log "BCD restaurado a partir do backup: $BackupPath"
    return [ordered]@{ Success = $true; Restored = $true; BackupPath = $BackupPath }
}

function Set-BootstrapWindowsBootManager {
    param(
        [AllowNull()][string]$DefaultId = '',
        [Nullable[int]]$Timeout = $null,
        [switch]$DryRun
    )

    if (-not (Test-IsAdmin)) { throw 'Set-BootstrapWindowsBootManager requer privilegios de administrador.' }
    $state = Get-BootstrapWindowsBootManagerState
    $entryIds = @($state.Entries | ForEach-Object { [string]$_['id'] })
    $actions = New-Object System.Collections.Generic.List[string]

    if (-not [string]::IsNullOrWhiteSpace($DefaultId)) {
        if (@($entryIds) -notcontains $DefaultId) { throw "Entrada BCD desconhecida: $DefaultId" }
        $actions.Add("default=$DefaultId")
    }
    if ($null -ne $Timeout) {
        if ($Timeout.Value -lt 0 -or $Timeout.Value -gt 600) { throw 'Timeout BCD deve ficar entre 0 e 600 segundos.' }
        $actions.Add("timeout=$($Timeout.Value)")
    }
    if ($actions.Count -eq 0) {
        return [ordered]@{ Success = $true; Changed = $false; DryRun = [bool]$DryRun; Actions = @() }
    }

    $backupPath = ''
    if (-not $DryRun) {
        $backupPath = Backup-BootstrapWindowsBootManager
        if (-not [string]::IsNullOrWhiteSpace($DefaultId)) {
            $output = & bcdedit /default $DefaultId 2>&1
            if ($LASTEXITCODE -ne 0) { throw "Falha ao definir default BCD: $output" }
        }
        if ($null -ne $Timeout) {
            $output = & bcdedit /timeout $Timeout.Value 2>&1
            if ($LASTEXITCODE -ne 0) { throw "Falha ao definir timeout BCD: $output" }
        }
    }

    return [ordered]@{
        Success = $true
        Changed = (-not [bool]$DryRun)
        DryRun = [bool]$DryRun
        Backup = $backupPath
        Actions = @($actions.ToArray())
    }
}

function Set-BootstrapOneTimeBootTarget {
    param(
        [Parameter(Mandatory = $true)][string]$EntryGuid,
        [switch]$CreateBackup
    )
    if (-not (Test-IsAdmin)) {
        throw 'Set-BootstrapOneTimeBootTarget requer privilegios de administrador.'
    }
    if (-not (Test-BootstrapSafeEfiOperation)) {
        throw 'Nao foi possivel validar as entradas EFI. Operacao cancelada por seguranca.'
    }
    if ($CreateBackup) {
        $backupDir = Join-Path (Get-BootstrapDataRoot) 'bcd-backups'
        if (-not (Test-Path $backupDir)) { New-Item -Path $backupDir -ItemType Directory -Force | Out-Null }
        $backupPath = Join-Path $backupDir ("bcd_backup_{0}.bak" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
        $exitCode = 0
        try {
            $output = & bcdedit /export $backupPath 2>&1
            if ($LASTEXITCODE -ne 0) { $exitCode = $LASTEXITCODE }
        } catch { $exitCode = 1 }
        if ($exitCode -ne 0) {
            Write-Log "[WARN] Falha ao criar backup do BCD: $backupPath"
        } else {
            Write-Log "BCD backup criado: $backupPath"
        }
    }
    $output = & bcdedit /set '{fwbootmgr}' bootsequence $EntryGuid 2>&1
    if ($LASTEXITCODE -ne 0) {
        throw "Falha ao definir bootsequence: $output"
    }
    Write-Log "Bootsequence definido para: $EntryGuid (proximo boot apenas)."
    return @{ Success = $true; TargetGuid = $EntryGuid }
}

function Invoke-BootstrapRebootToLinux {
    param(
        [string]$PreferredEntryGuid,
        [switch]$Force
    )
    if (-not (Test-IsAdmin)) {
        throw 'Invoke-BootstrapRebootToLinux requer privilegios de administrador.'
    }
    $alternates = Get-BootstrapAlternateBootEntries
    if ($alternates.Count -eq 0) {
        throw 'Nenhuma entrada de boot alternativa (Linux/SteamOS) encontrada no firmware.'
    }
    $target = $null
    if ($PreferredEntryGuid) {
        $target = $alternates | Where-Object { $_.Id -eq $PreferredEntryGuid } | Select-Object -First 1
    }
    if (-not $target) {
        $target = $alternates[0]
    }
    Write-Log "Preparando boot em: $($target.Description) ($($target.Id))"
    Set-BootstrapOneTimeBootTarget -EntryGuid $target.Id -CreateBackup
    if (-not $Force) {
        Write-Log 'Bootsequence definido com sucesso. Reinicie manualmente quando estiver pronto.'
        return @{ Success = $true; Target = $target; Rebooted = $false }
    }
    Write-Log 'Reiniciando em 3 segundos...'
    & shutdown /r /t 3
    return @{ Success = $true; Target = $target; Rebooted = $true }
}

function Get-BootstrapPhantomBootEntries {
    if (-not (Test-IsAdmin)) { return @() }
    $state = Get-BootstrapWindowsBootManagerState
    return @($state.PhantomEntries | Where-Object { [string]$_['id'] -ne '{current}' } | ForEach-Object {
        @{ Id = [string]$_['id']; Description = [string]$_['description'] }
    })
}

function Repair-BootstrapPhantomEntries {
    if (-not (Test-IsAdmin)) { throw 'Repair-BootstrapPhantomEntries requer privilegios de administrador.' }

    $phantoms = Get-BootstrapPhantomBootEntries
    if ($phantoms.Count -eq 0) {
        return @{ Success = $true; Removed = 0; Message = 'Nenhuma entrada inativa encontrada.' }
    }

    $backupPath = Backup-BootstrapWindowsBootManager

    $removedCount = 0
    foreach ($p in $phantoms) {
        Write-Log "Removendo phantom BCD entry: $($p.Description) ($($p.Id))"
        & bcdedit /delete $($p.Id) /cleanup 2>&1 | Out-Null
        if ($LASTEXITCODE -eq 0) { $removedCount++ }
    }

    # Se sobrar so 1 no displayorder (e for o current), removemos o timeout para single-OS boot rapido
    $state = Get-BootstrapWindowsBootManagerState
    if (@($state.DisplayOrder).Count -eq 1) {
        if ([string]$state.DisplayOrder[0] -eq '{current}') {
            & bcdedit /timeout 0 2>&1 | Out-Null
            Write-Log "Otimizacao: Timeout definido para 0 pois sobrou apenas a instalacao corrente."
        }
    }

    return @{ Success = $true; Removed = $removedCount; Backup = $backupPath }
}

