function New-BootstrapComponentDefinition {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [Parameter(Mandatory = $true)][string]$Description,
        [string[]]$DependsOn = @(),
        [bool]$Optional = $true,
        [Parameter(Mandatory = $true)][string]$Kind,
        [hashtable]$Data = @{},
        [double]$EstimatedSizeGB = 0.0,
        [bool]$RequiresNetwork = $false,
        [string]$VersionCheckCommand = '',
        [string]$ExpectedVersion = ''
    )

    $definition = [ordered]@{
        Name = $Name
        Description = $Description
        DependsOn = @($DependsOn)
        Optional = $Optional
        Kind = $Kind
        EstimatedSizeGB = $EstimatedSizeGB
        RequiresNetwork = $RequiresNetwork
        VersionCheckCommand = $VersionCheckCommand
        ExpectedVersion = $ExpectedVersion
    }

    foreach ($key in $Data.Keys) {
        $definition[$key] = $Data[$key]
    }

    return [pscustomobject]$definition
}

function New-BootstrapProfileDefinition {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [Parameter(Mandatory = $true)][string]$Description,
        [string[]]$Items = @()
    )

    return [pscustomobject]@{
        Name = $Name
        Description = $Description
        Items = @($Items)
    }
}

function ConvertTo-BootstrapNameText {
    param([AllowNull()]$Value)

    if ($null -eq $Value) { return '' }
    if ($Value -is [string]) { return $Value }
    if ($Value -is [System.Collections.IDictionary]) {
        foreach ($key in @('id', 'name', 'value', 'tag', 'component', 'app')) {
            if ($Value.Contains($key) -and -not [string]::IsNullOrWhiteSpace([string]$Value[$key])) {
                return [string]$Value[$key]
            }
        }
        return ''
    }
    foreach ($propertyName in @('id', 'Name', 'name', 'Value', 'value', 'Tag', 'tag', 'Content', 'content')) {
        $property = $Value.PSObject.Properties[$propertyName]
        if ($property -and -not [string]::IsNullOrWhiteSpace([string]$property.Value)) {
            return [string]$property.Value
        }
    }
    return [string]$Value
}

function Normalize-BootstrapNames {
    param([object[]]$Names)

    $normalized = New-Object System.Collections.Generic.List[string]
    foreach ($name in @($Names)) {
        $nameText = ConvertTo-BootstrapNameText -Value $name
        if ([string]::IsNullOrWhiteSpace($nameText)) { continue }
        foreach ($item in ($nameText -split ',')) {
            $trimmed = $item.Trim()
            if (-not [string]::IsNullOrWhiteSpace($trimmed)) {
                $normalized.Add($trimmed.ToLowerInvariant())
            }
        }
    }

    return @($normalized.ToArray())
}

function ConvertTo-BootstrapHashtable {
    param($InputObject)

    if ($null -eq $InputObject) { return $null }

    $value = $InputObject

    if ($value -is [System.Collections.IDictionary]) {
        $result = @{}
        foreach ($key in $value.Keys) {
            $result[[string]$key] = ConvertTo-BootstrapHashtable -InputObject $value[$key]
        }
        return $result
    }

    if (($value -is [System.Collections.IEnumerable]) -and -not ($value -is [string])) {
        $items = New-Object System.Collections.Generic.List[object]
        foreach ($item in $value) {
            $items.Add((ConvertTo-BootstrapHashtable -InputObject $item))
        }
        return ,@($items.ToArray())
    }

    # Precisa ser PSCustomObject de verdade. O acelerador [pscustomobject] casa com qualquer valor
    # embrulhado em PSObject - o que cmdlets como Test-Path e Join-Path devolvem - e fazia bool e
    # string cairem neste ramo, virando hashtable VAZIA e apagando o dado em silencio.
    if ($value -is [System.Management.Automation.PSCustomObject]) {
        $result = @{}
        foreach ($property in $InputObject.PSObject.Properties) {
            $result[$property.Name] = ConvertTo-BootstrapHashtable -InputObject $property.Value
        }
        return $result
    }

    return $value
}

function Test-BootstrapMapContainsKey {
    param(
        [AllowNull()]$Map,
        [AllowNull()]$Key
    )

    if ($null -eq $Map) { return $false }
    $keyText = [string]$Key
    if ([string]::IsNullOrWhiteSpace($keyText)) { return $false }

    if ($Map -is [hashtable]) {
        return $Map.ContainsKey($keyText)
    }
    if ($Map -is [System.Collections.Specialized.OrderedDictionary]) {
        return $Map.Contains($keyText)
    }
    if ($Map -is [System.Collections.IDictionary]) {
        $hasContainsKey = $Map.PSObject.Methods.Name -contains 'ContainsKey'
        if ($hasContainsKey) {
            return [bool]$Map.ContainsKey($keyText)
        }
        return [bool]$Map.Contains($keyText)
    }
    if ($Map.PSObject.Properties.Name -contains 'Keys') {
        return (@($Map.Keys) -contains $keyText)
    }
    return $false
}

function Merge-BootstrapData {
    param(
        [AllowNull()][Parameter(Mandatory = $true)]$Defaults,
        $Current
    )

    $normalizedDefaults = ConvertTo-BootstrapHashtable -InputObject $Defaults
    $normalizedCurrent = ConvertTo-BootstrapHashtable -InputObject $Current

    if ($normalizedDefaults -is [hashtable]) {
        $result = @{}
        foreach ($key in $normalizedDefaults.Keys) {
            if (($normalizedCurrent -is [hashtable]) -and $normalizedCurrent.ContainsKey($key)) {
                $result[$key] = Merge-BootstrapData -Defaults $normalizedDefaults[$key] -Current $normalizedCurrent[$key]
            } else {
                $result[$key] = $normalizedDefaults[$key]
            }
        }

        if ($normalizedCurrent -is [hashtable]) {
            foreach ($key in $normalizedCurrent.Keys) {
                if (-not $result.ContainsKey($key)) {
                    $result[$key] = $normalizedCurrent[$key]
                }
            }
        }

        return $result
    }

    if ($normalizedDefaults -is [System.Array]) {
        if ($normalizedCurrent -is [System.Array]) {
            return ,@($normalizedCurrent)
        }
        return ,@($normalizedDefaults)
    }

    if ($null -ne $normalizedCurrent) {
        if ($normalizedCurrent -is [string]) {
            if (-not [string]::IsNullOrWhiteSpace($normalizedCurrent)) {
                return $normalizedCurrent
            }
        } else {
            return $normalizedCurrent
        }
    }

    return $normalizedDefaults
}

function ConvertTo-BootstrapObjectGraph {
    param($InputObject)

    if ($null -eq $InputObject) { return $null }
    if ($InputObject -is [string]) { return [string]$InputObject }
    if ($InputObject -is [char]) { return [string]$InputObject }
    if ($InputObject -is [System.ValueType]) { return $InputObject }

    if ($InputObject -is [System.Collections.IDictionary]) {
        $result = [ordered]@{}
        foreach ($key in $InputObject.Keys) {
            $result[[string]$key] = ConvertTo-BootstrapObjectGraph -InputObject $InputObject[$key]
        }
        return [pscustomobject]$result
    }

    if ($InputObject -is [pscustomobject]) {
        $result = [ordered]@{}
        foreach ($property in $InputObject.PSObject.Properties) {
            $result[$property.Name] = ConvertTo-BootstrapObjectGraph -InputObject $property.Value
        }
        return [pscustomobject]$result
    }

    if (($InputObject -is [System.Collections.IEnumerable]) -and -not ($InputObject -is [string])) {
        $items = @()
        foreach ($item in $InputObject) {
            $items += @(ConvertTo-BootstrapObjectGraph -InputObject $item)
        }
        return ,@($items)
    }

    return $InputObject
}

function Normalize-BootstrapObjectArray {
    param($Value)

    if ($null -eq $Value) { return @() }

    if (($Value -is [System.Collections.IDictionary]) -or ($Value -is [pscustomobject])) {
        $propertyCount = if ($Value -is [pscustomobject]) { @($Value.PSObject.Properties).Count } else { @($Value.Keys).Count }
        if ($propertyCount -eq 0) { return @() }
        return @((ConvertTo-BootstrapHashtable -InputObject $Value))
    }

    if (($Value -is [System.Collections.IEnumerable]) -and -not ($Value -is [string])) {
        $items = @()
        foreach ($item in $Value) {
            $items += @(ConvertTo-BootstrapHashtable -InputObject $item)
        }
        return @($items)
    }

    return @($Value)
}

function Get-BootstrapHostHealthModes {
    return @('off', 'conservador', 'equilibrado', 'agressivo')
}

function Show-BootstrapHostHealthModes {
    foreach ($mode in (Get-BootstrapHostHealthModes)) {
        Write-Output $mode
    }
}

function Normalize-BootstrapHostHealthMode {
    param([AllowNull()][string]$Mode)

    if ([string]::IsNullOrWhiteSpace($Mode)) { return $null }
    $normalized = $Mode.Trim().ToLowerInvariant()
    if ((Get-BootstrapHostHealthModes) -notcontains $normalized) {
        throw "Modo de HostHealth desconhecido: $Mode"
    }
    return $normalized
}

function Test-BootstrapSafeDefaultProfileSelection {
    param(
        [Parameter(Mandatory = $true)]$Selection,
        [Parameter(Mandatory = $true)]$Resolution
    )

    $selectedProfiles = @($Selection.Profiles | ForEach-Object { [string]$_ })
    $selectedComponents = @($Selection.Components)
    $expandedProfiles = @($Resolution.ExpandedProfiles | ForEach-Object { [string]$_ })
    if ($selectedComponents.Count -gt 0) { return $false }
    if ($selectedProfiles.Count -eq 0) { return $false }
    foreach ($profileName in @($selectedProfiles + $expandedProfiles)) {
        if ([string]::IsNullOrWhiteSpace($profileName)) { continue }
        if ($profileName -notin @('safe-base', 'recommended')) { return $false }
    }
    return $true
}

function Test-BootstrapOsInstallOnlyProfileSelection {
    param(
        [Parameter(Mandatory = $true)]$Selection,
        [Parameter(Mandatory = $true)]$Resolution
    )

    $selectedProfiles = @($Selection.Profiles | ForEach-Object { [string]$_ } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    $selectedComponents = @($Selection.Components)
    $expandedProfiles = @($Resolution.ExpandedProfiles | ForEach-Object { [string]$_ } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if ($selectedComponents.Count -gt 0) { return $false }
    if ($selectedProfiles.Count -eq 0) { return $false }
    foreach ($profileName in @($selectedProfiles + $expandedProfiles)) {
        if ($profileName -ne 'steamos-install') { return $false }
    }
    return $true
}

function Get-BootstrapDefaultHostHealthMode {
    param(
        [Parameter(Mandatory = $true)]$Selection,
        [Parameter(Mandatory = $true)]$Resolution
    )

    $selectedProfiles = @($Selection.Profiles)
    $selectedComponents = @($Selection.Components)
    $expandedProfiles = @($Resolution.ExpandedProfiles)

    if (($selectedComponents.Count -eq 0) -and ($selectedProfiles.Count -eq 1) -and ($selectedProfiles[0] -eq 'legacy') -and ($expandedProfiles.Count -eq 1) -and ($expandedProfiles[0] -eq 'legacy')) {
        return 'off'
    }
    if (($selectedComponents.Count -gt 0) -and ($selectedProfiles.Count -eq 0)) {
        return 'off'
    }
    if (Test-BootstrapSafeDefaultProfileSelection -Selection $Selection -Resolution $Resolution) {
        return 'off'
    }
    if (Test-BootstrapOsInstallOnlyProfileSelection -Selection $Selection -Resolution $Resolution) {
        return 'off'
    }

    return 'conservador'
}

