function Show-BootstrapAppTuningCatalog {
    $catalog = Get-BootstrapAppTuningCatalog
    foreach ($category in @($catalog.categories)) {
        Write-Output ("{0} - {1}" -f $category.id, $category.description)
        foreach ($item in @($catalog.items | Where-Object { $_.category -eq $category.id })) {
            Write-Output ("  {0} - {1} | default: {2} | admin: {3}" -f $item.id, $item.displayName, $item.defaultMode, $item.requiresAdmin)
        }
    }
}

function ConvertTo-BootstrapExpandedPath {
    param([AllowNull()][string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) { return '' }
    $expanded = [Environment]::ExpandEnvironmentVariables($Path)
    $programFilesX86 = [Environment]::GetEnvironmentVariable('ProgramFiles(x86)')
    $expanded = $expanded -replace '\$env:ProgramFiles\(x86\)', $programFilesX86
    $expanded = $expanded -replace '\$env:ProgramFiles', $env:ProgramFiles
    $expanded = $expanded -replace '\$env:LOCALAPPDATA', $env:LOCALAPPDATA
    $expanded = $expanded -replace '\$env:APPDATA', $env:APPDATA
    $expanded = $expanded -replace '\$env:USERPROFILE', $env:USERPROFILE
    return $expanded
}

function Get-BootstrapInstalledAppInventory {
    $apps = @{}
    $paths = @{}
    $uninstallRoots = @(
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )

    foreach ($entry in @(Get-ItemProperty $uninstallRoots -ErrorAction SilentlyContinue)) {
        $name = if ($entry.PSObject.Properties.Name -contains 'DisplayName') { [string]$entry.DisplayName } else { '' }
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        $apps[$name.ToLowerInvariant()] = $true
    }

    try {
        foreach ($entry in @(Get-StartApps -ErrorAction SilentlyContinue)) {
            $name = if ($entry.PSObject.Properties.Name -contains 'Name') { [string]$entry.Name } else { '' }
            if ([string]::IsNullOrWhiteSpace($name)) { continue }
            $apps[$name.ToLowerInvariant()] = $true
        }
    } catch {
    }

    $catalog = Get-BootstrapAppTuningCatalog
    foreach ($item in @($catalog.items)) {
        foreach ($probePath in @($item.probePaths)) {
            $expanded = ConvertTo-BootstrapExpandedPath -Path ([string]$probePath)
            if ([string]::IsNullOrWhiteSpace($expanded)) { continue }
            if (Test-Path $expanded) {
                $paths[$expanded] = $true
                foreach ($targetApp in @($item.targetApps)) {
                    if (-not [string]::IsNullOrWhiteSpace([string]$targetApp)) {
                        $apps[[string]$targetApp.ToLowerInvariant()] = $true
                    }
                }
            }
        }
    }

    return [ordered]@{
        generatedAt = (Get-Date).ToString('o')
        apps = $apps
        paths = $paths
    }
}

function Test-BootstrapInventoryAppNameMatchesTarget {
    <#
    .SYNOPSIS
        Correspondencia inventario (DisplayName/Start menu) vs targetApp, evitando falsos positivos de Substring
        (ex.: "somethingnotepadplusplus" nao deve contar como Notepad++).
    #>
    param(
        [Parameter(Mandatory = $true)][string]$HaystackLower,
        [Parameter(Mandatory = $true)][string]$NeedleLower,
        [Parameter(Mandatory = $true)][bool]$StrictBoundary
    )

    if ([string]::IsNullOrWhiteSpace($HaystackLower) -or [string]::IsNullOrWhiteSpace($NeedleLower)) { return $false }
    if ($HaystackLower -eq $NeedleLower) { return $true }
    if (-not $StrictBoundary) {
        return ($HaystackLower.Contains($NeedleLower))
    }
    $escaped = [regex]::Escape($NeedleLower)
    return [regex]::IsMatch($HaystackLower, ('(?i)(^|[^0-9a-z]){0}([^0-9a-z]|$)' -f $escaped))
}

function Test-BootstrapAppTuningItemInstalled {
    param(
        [Parameter(Mandatory = $true)]$Item,
        [Parameter(Mandatory = $true)]$InstalledInventory
    )

    $itemMap = ConvertTo-BootstrapHashtable -InputObject $Item
    if (($itemMap -is [hashtable]) -and $itemMap.ContainsKey('alwaysAvailable') -and [bool]$itemMap['alwaysAvailable']) {
        return $true
    }

    $inventory = ConvertTo-BootstrapHashtable -InputObject $InstalledInventory
    $apps = if ((Test-BootstrapMapContainsKey -Map $inventory -Key 'apps') -and ($inventory['apps'] -is [hashtable])) { $inventory['apps'] } else { @{} }
    $paths = if ((Test-BootstrapMapContainsKey -Map $inventory -Key 'paths') -and ($inventory['paths'] -is [hashtable])) { $inventory['paths'] } else { @{} }

    $hasProbePaths = $false
    foreach ($pp in @($Item.probePaths)) {
        if (-not [string]::IsNullOrWhiteSpace([string]$pp)) { $hasProbePaths = $true; break }
    }

    foreach ($probePath in @($Item.probePaths)) {
        $expanded = ConvertTo-BootstrapExpandedPath -Path ([string]$probePath)
        if ([string]::IsNullOrWhiteSpace($expanded)) { continue }
        if (Test-BootstrapMapContainsKey -Map $paths -Key $expanded) {
            return $true
        }
    }

    if ($hasProbePaths) {
        return $false
    }

    foreach ($targetApp in @($Item.targetApps)) {
        $needle = ([string]$targetApp).Trim().ToLowerInvariant()
        if ([string]::IsNullOrWhiteSpace($needle)) { continue }
        foreach ($appName in @($apps.Keys)) {
            $text = ([string]$appName).ToLowerInvariant()
            if (Test-BootstrapInventoryAppNameMatchesTarget -HaystackLower $text -NeedleLower $needle -StrictBoundary $false) {
                return $true
            }
        }
    }

    return $false
}

function Get-BootstrapAppTuningItemValue {
    param(
        [Parameter(Mandatory = $true)]$Item,
        [Parameter(Mandatory = $true)][string]$Name,
        [AllowNull()]$Default = $null
    )

    $itemMap = ConvertTo-BootstrapHashtable -InputObject $Item
    if (($itemMap -is [hashtable]) -and $itemMap.ContainsKey($Name)) {
        return $itemMap[$Name]
    }
    return $Default
}

function Get-BootstrapAppTuningRiskTier {
    param([Parameter(Mandatory = $true)]$Item)

    $explicit = [string](Get-BootstrapAppTuningItemValue -Item $Item -Name 'riskTier' -Default '')
    if (-not [string]::IsNullOrWhiteSpace($explicit)) { return $explicit }
    $defaultMode = [string](Get-BootstrapAppTuningItemValue -Item $Item -Name 'defaultMode' -Default 'opt-in')
    $requiresAdmin = [bool](Get-BootstrapAppTuningItemValue -Item $Item -Name 'requiresAdmin' -Default $false)
    if ($defaultMode -eq 'recommended' -and -not $requiresAdmin) { return 'conservative' }
    if ($defaultMode -eq 'recommended') { return 'advanced' }
    return 'opt-in'
}

function Get-BootstrapAppTuningRollbackScope {
    param([Parameter(Mandatory = $true)]$Item)

    $explicit = [string](Get-BootstrapAppTuningItemValue -Item $Item -Name 'rollbackScope' -Default '')
    if (-not [string]::IsNullOrWhiteSpace($explicit)) { return $explicit }
    $rollback = @(Get-BootstrapAppTuningItemValue -Item $Item -Name 'rollback' -Default @())
    if ($rollback.Count -gt 0) { return (@($rollback) -join ',') }
    return 'manual'
}

function Get-BootstrapAppTuningSafetyNotes {
    param([Parameter(Mandatory = $true)]$Item)

    $notes = @(Get-BootstrapAppTuningItemValue -Item $Item -Name 'safetyNotes' -Default @())
    if ($notes.Count -gt 0) { return @($notes | ForEach-Object { [string]$_ } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) }
    return @('Ajuste segue contrato de AppTuning e nao deve sobrescrever configuracoes fora do item.')
}

function Get-BootstrapAppTuningBadges {
    param([Parameter(Mandatory = $true)]$Item)

    $badges = New-Object System.Collections.Generic.List[string]
    foreach ($badge in @(Get-BootstrapAppTuningItemValue -Item $Item -Name 'badges' -Default @())) {
        $text = ([string]$badge).Trim()
        if (-not [string]::IsNullOrWhiteSpace($text) -and -not $badges.Contains($text)) { $badges.Add($text) | Out-Null }
    }

    $riskTier = Get-BootstrapAppTuningRiskTier -Item $Item
    switch ($riskTier) {
        'conservative' { if (-not $badges.Contains('Seguro')) { $badges.Add('Seguro') | Out-Null } }
        'manual' { if (-not $badges.Contains('Manual')) { $badges.Add('Manual') | Out-Null } }
        'experimental' { if (-not $badges.Contains('Experimental')) { $badges.Add('Experimental') | Out-Null } }
    }
    if ([bool](Get-BootstrapAppTuningItemValue -Item $Item -Name 'requiresAdmin' -Default $false)) {
        if (-not $badges.Contains('Admin')) { $badges.Add('Admin') | Out-Null }
    }
    if ([bool](Get-BootstrapAppTuningItemValue -Item $Item -Name 'requiresInteractiveLogin' -Default $false)) {
        if (-not $badges.Contains('Login')) { $badges.Add('Login') | Out-Null }
    }
    return @($badges.ToArray())
}

function Get-BootstrapDefaultAppTuningMode {
    param(
        [Parameter(Mandatory = $true)]$Selection,
        [Parameter(Mandatory = $true)]$Resolution
    )

    if (@($Selection.Profiles).Count -eq 1 -and [string]$Selection.Profiles[0] -eq 'legacy') {
        return 'off'
    }
    if ((@($Selection.Components).Count -gt 0) -and (@($Selection.Profiles).Count -eq 0)) {
        return 'off'
    }
    if (Test-BootstrapSafeDefaultProfileSelection -Selection $Selection -Resolution $Resolution) {
        return 'off'
    }
    if (Test-BootstrapOsInstallOnlyProfileSelection -Selection $Selection -Resolution $Resolution) {
        return 'off'
    }
    return 'recommended'
}

function Resolve-BootstrapAppTuningSelection {
    param(
        [AllowNull()][string]$Mode,
        [string[]]$Categories = @(),
        [string[]]$Items = @(),
        [string[]]$ExcludedItems = @(),
        [Parameter(Mandatory = $true)]$Selection,
        [Parameter(Mandatory = $true)]$Resolution,
        [AllowNull()]$InstalledInventory = $null
    )

    $catalog = Get-BootstrapAppTuningCatalog
    $normalizedMode = Normalize-BootstrapAppTuningMode -Mode $Mode
    if ([string]::IsNullOrWhiteSpace($normalizedMode)) {
        $normalizedMode = Get-BootstrapDefaultAppTuningMode -Selection $Selection -Resolution $Resolution
    }

    $categoryLookup = @{}
    foreach ($category in @($catalog.categories)) { $categoryLookup[[string]$category.id] = $category }
    $itemLookup = @{}
    foreach ($item in @($catalog.items)) { $itemLookup[[string]$item.id] = $item }

    $selectedCategories = @(Normalize-BootstrapNames -Names $Categories)
    $selectedItems = @(Normalize-BootstrapNames -Names $Items)
    $excluded = @(Normalize-BootstrapNames -Names $ExcludedItems)

    foreach ($categoryId in @($selectedCategories)) {
        if (-not (Test-BootstrapMapContainsKey -Map $categoryLookup -Key $categoryId)) { throw "Categoria AppTuning desconhecida: $categoryId" }
    }
    foreach ($itemId in @($selectedItems + $excluded)) {
        if (-not (Test-BootstrapMapContainsKey -Map $itemLookup -Key $itemId)) { throw "Item AppTuning desconhecido: $itemId" }
    }

    $selectedMap = [ordered]@{}
    if ($normalizedMode -eq 'recommended') {
        foreach ($item in @($catalog.items)) {
            if ([string]$item.defaultMode -eq 'recommended') {
                $selectedMap[[string]$item.id] = $true
            }
        }
    } elseif ($normalizedMode -eq 'custom') {
        foreach ($categoryId in @($selectedCategories)) {
            foreach ($item in @($catalog.items | Where-Object { $_.category -eq $categoryId -and $_.defaultMode -eq 'recommended' })) {
                $selectedMap[[string]$item.id] = $true
            }
        }
        foreach ($itemId in @($selectedItems)) {
            $selectedMap[$itemId] = $true
        }
    }

    foreach ($itemId in @($excluded)) {
        if ($selectedMap.Contains($itemId)) { $selectedMap.Remove($itemId) }
    }

    $inventory = if ($InstalledInventory) { $InstalledInventory } else { Get-BootstrapInstalledAppInventory }
    $resolvedItems = @()
    foreach ($itemId in @($selectedMap.Keys)) {
        $item = $itemLookup[$itemId]
        $installed = Test-BootstrapAppTuningItemInstalled -Item $item -InstalledInventory $inventory
        $status = if ($installed) { 'pending' } else { 'skipped' }
        $riskTier = Get-BootstrapAppTuningRiskTier -Item $item
        $securityImpact = [bool](Get-BootstrapAppTuningItemValue -Item $item -Name 'securityImpact' -Default $false)
        $rollbackScope = Get-BootstrapAppTuningRollbackScope -Item $item
        $safetyNotes = @(Get-BootstrapAppTuningSafetyNotes -Item $item)
        $badges = @(Get-BootstrapAppTuningBadges -Item $item)
        $alwaysAvailable = [bool](Get-BootstrapAppTuningItemValue -Item $item -Name 'alwaysAvailable' -Default $false)
        $resolvedItems += @([ordered]@{
            id = [string]$item.id
            category = [string]$item.category
            displayName = [string]$item.displayName
            description = [string]$item.description
            targetApps = @($item.targetApps)
            probePaths = @($item.probePaths)
            requiresAdmin = [bool]$item.requiresAdmin
            defaultMode = [string]$item.defaultMode
            profiles = @($item.profiles)
            actions = @($item.actions)
            rollback = @($item.rollback)
            alwaysAvailable = $alwaysAvailable
            riskTier = $riskTier
            securityImpact = $securityImpact
            rollbackScope = $rollbackScope
            safetyNotes = @($safetyNotes)
            badges = @($badges)
            aliases = @(Get-BootstrapAppTuningItemValue -Item $item -Name 'aliases' -Default @())
            installed = $installed
            status = $status
        })
    }

    $categorySet = @{}
    foreach ($item in @($resolvedItems)) { $categorySet[[string]$item.category] = $true }

    return [ordered]@{
        mode = $normalizedMode
        categories = @($categorySet.Keys | Sort-Object)
        requestedCategories = @($selectedCategories)
        requestedItems = @($selectedItems)
        excludedItems = @($excluded)
        items = @($resolvedItems | Sort-Object category, id)
        skippedItems = @($resolvedItems | Where-Object { $_.status -eq 'skipped' } | ForEach-Object { $_.id })
        installedInventory = $inventory
    }
}

