    $catalog = Get-BootstrapSecretsProviderCatalog
    $providers = [ordered]@{}
    foreach ($providerName in $catalog.Keys) {
        $providers[$providerName] = Get-BootstrapSecretsProviderDefinitionTemplate -ProviderName $providerName
