function Normalize-BootstrapSteamDeckSettingsData {
    param($Settings)

    $normalized = ConvertTo-BootstrapHashtable -InputObject $Settings
    if (-not ($normalized -is [hashtable])) {
        $normalized = @{}
    }

    $normalized['monitorProfiles'] = @(Normalize-BootstrapObjectArray -Value ($normalized['monitorProfiles']))
    $normalized['monitorFamilies'] = @(Normalize-BootstrapObjectArray -Value ($normalized['monitorFamilies']))

    $internalDisplay = if ($normalized.ContainsKey('internalDisplay')) { ConvertTo-BootstrapHashtable -InputObject $normalized['internalDisplay'] } else { @{} }
    if (-not ($internalDisplay -is [hashtable])) { $internalDisplay = @{} }
    if (-not $internalDisplay.ContainsKey('manufacturer') -or [string]::IsNullOrWhiteSpace([string]$internalDisplay['manufacturer'])) {
        $internalDisplay['manufacturer'] = 'VLV'
    }
    if (-not $internalDisplay.ContainsKey('product') -or [string]::IsNullOrWhiteSpace([string]$internalDisplay['product'])) {
        $internalDisplay['product'] = 'ANX7530 U'
    }
    if (-not $internalDisplay.ContainsKey('primary')) {
        $internalDisplay['primary'] = $false
    }
    $normalized['internalDisplay'] = $internalDisplay

    $displayMode = if ($normalized.ContainsKey('displayMode')) { ([string]$normalized['displayMode']).Trim().ToLowerInvariant() } else { '' }
    if (@('extend', 'internal', 'external', 'clone') -notcontains $displayMode) {
        $displayMode = 'extend'
    }
    $normalized['displayMode'] = $displayMode

    $sessionProfileDefaults = @{
        HANDHELD = 'game-handheld'
        DOCKED_TV = 'game-docked'
        DOCKED_MONITOR = 'desktop'
    }
    $sessionProfiles = if ($normalized.ContainsKey('sessionProfiles')) { ConvertTo-BootstrapHashtable -InputObject $normalized['sessionProfiles'] } else { @{} }
    if (-not ($sessionProfiles -is [hashtable])) {
        $sessionProfiles = @{}
    }
    foreach ($sessionProfileKey in @($sessionProfileDefaults.Keys)) {
        if (-not $sessionProfiles.ContainsKey($sessionProfileKey) -or [string]::IsNullOrWhiteSpace([string]$sessionProfiles[$sessionProfileKey])) {
            $sessionProfiles[$sessionProfileKey] = $sessionProfileDefaults[$sessionProfileKey]
        }
    }
    $normalized['sessionProfiles'] = $sessionProfiles

    if (-not $normalized.ContainsKey('hostHealth')) {
        $normalized['hostHealth'] = @{
            mode = 'off'
            killInGame = @('ms-teams', 'olk', 'PhoneExperienceHost', 'msedge', 'Widgets', 'WidgetService')
            keepAlways = @('SecurityHealthSystray', 'RadeonSoftware', 'Steam', 'Sunshine', 'Tailscale', 'PowerControl', 'PerformanceOverlay', 'SteamController', 'FanControl', 'HandheldCompanion', 'GlosSI')
        }
    }

    if (-not $normalized.ContainsKey('sharedVramFix')) {
        $normalized['sharedVramFix'] = @{
            enabled = $true
            launchOption = '-sharedvram'
            games = @()
        }
    } else {
        $sharedVramFix = ConvertTo-BootstrapHashtable -InputObject $normalized['sharedVramFix']
        if (-not ($sharedVramFix -is [hashtable])) { $sharedVramFix = @{} }
        if (-not $sharedVramFix.ContainsKey('enabled')) { $sharedVramFix['enabled'] = $true }
        if (-not $sharedVramFix.ContainsKey('launchOption') -or [string]::IsNullOrWhiteSpace([string]$sharedVramFix['launchOption'])) {
            $sharedVramFix['launchOption'] = '-sharedvram'
        }
        if (-not $sharedVramFix.ContainsKey('games') -or -not ($sharedVramFix['games'] -is [System.Collections.IEnumerable])) {
            $sharedVramFix['games'] = @()
        } else {
            $sharedVramFix['games'] = @(Normalize-BootstrapObjectArray -Value $sharedVramFix['games'])
        }
        $normalized['sharedVramFix'] = $sharedVramFix
    }

    if (-not $normalized.ContainsKey('displayClassification')) {
        $normalized['displayClassification'] = @{
            unknownExternalMode = 'UNCLASSIFIED_EXTERNAL'
            uiFallbackMode = 'DOCKED_MONITOR'
        }
    }

    if (-not $normalized.ContainsKey('consoleSession')) {
        $normalized['consoleSession'] = @{
            primaryShell = 'steam'
            fallbackShell = 'playnite'
            steamLaunch = 'steam://open/bigpicture'
            softShell = $true
        }
    }

    $tweakDefaults = @{
        hibernation = 'enabled'
        realtimeUtc = $true
        requireLoginAfterSleep = $false
        gameBar = 'enabled'
        touchKeyboard = 'enabled'
    }
    $tweaks = if ($normalized.ContainsKey('steamdeckTweaks')) { ConvertTo-BootstrapHashtable -InputObject $normalized['steamdeckTweaks'] } else { @{} }
    if (-not ($tweaks -is [hashtable])) { $tweaks = @{} }
    foreach ($key in @($tweakDefaults.Keys)) {
        if (-not $tweaks.ContainsKey($key) -or $null -eq $tweaks[$key] -or [string]::IsNullOrWhiteSpace([string]$tweaks[$key])) {
            $tweaks[$key] = $tweakDefaults[$key]
        }
    }
    $normalized['steamdeckTweaks'] = $tweaks

    $toolDefaults = @{
        required = @('RTSS', 'AMD Adrenalin', 'CRU', 'Steam Deck Tools')
        autoStartOnHandheld = @('RTSS', 'Steam Deck Tools')
    }
    $tools = if ($normalized.ContainsKey('steamdeckTools')) { ConvertTo-BootstrapHashtable -InputObject $normalized['steamdeckTools'] } else { @{} }
    if (-not ($tools -is [hashtable])) { $tools = @{} }
    foreach ($key in @($toolDefaults.Keys)) {
        if (-not $tools.ContainsKey($key) -or $null -eq $tools[$key]) {
            $tools[$key] = $toolDefaults[$key]
        }
    }
    $tools['required'] = @($tools['required'])
    $tools['autoStartOnHandheld'] = @($tools['autoStartOnHandheld'])
    $normalized['steamdeckTools'] = $tools

    $steamInputDefaults = @{
        activeStack = 'steamdeck-tools'
        desktopLayoutConflictPolicy = 'manual-disable'
        recommendedAction = 'Steam > Settings > Controller > Desktop Layout: disable/clear layout when Steam Deck Tools, Handheld Companion or GlosSI manages desktop input.'
        advancedStacks = @('handheld-companion', 'glossi')
    }
    $steamInput = if ($normalized.ContainsKey('steamInput')) { ConvertTo-BootstrapHashtable -InputObject $normalized['steamInput'] } else { @{} }
    if (-not ($steamInput -is [hashtable])) { $steamInput = @{} }
    foreach ($key in @($steamInputDefaults.Keys)) {
        if (-not $steamInput.ContainsKey($key) -or $null -eq $steamInput[$key] -or [string]::IsNullOrWhiteSpace([string]$steamInput[$key])) {
            $steamInput[$key] = $steamInputDefaults[$key]
        }
    }
    $steamInput['advancedStacks'] = @($steamInput['advancedStacks'])
    $normalized['steamInput'] = $steamInput

    return $normalized
}

function Get-BootstrapSteamDeckSettingsData {
    param(
        [string]$RequestedSteamDeckVersion = 'Auto',
        [string]$ResolvedSteamDeckVersion = 'lcd'
    )

    $settingsPath = Get-BootstrapSteamDeckSettingsPath
    $current = $null
    if (Test-Path $settingsPath) {
        try {
            $current = Get-Content -Path $settingsPath -Raw | ConvertFrom-Json -ErrorAction Stop
        } catch {
            $current = $null
        }
    }

    $merged = Merge-BootstrapData -Defaults (Get-BootstrapSteamDeckSettingsDefaults -ResolvedSteamDeckVersion $ResolvedSteamDeckVersion) -Current $current
    $merged = Normalize-BootstrapSteamDeckSettingsData -Settings $merged
    $merged['steamDeckVersion'] = $RequestedSteamDeckVersion
    $merged['resolvedSteamDeckVersion'] = $ResolvedSteamDeckVersion

    return [ordered]@{
        Path = $settingsPath
        Data = $merged
    }
}

function Backup-BootstrapFile {
    param([Parameter(Mandatory = $true)][string]$Path)

    if (-not (Test-Path $Path)) { return $null }

    $backupPath = '{0}.{1:yyyyMMdd_HHmmss}.bak' -f $Path, (Get-Date)
    Copy-Item -LiteralPath $Path -Destination $backupPath -Force
    return $backupPath
}

function Save-BootstrapSteamDeckSettingsData {
    param(
        [Parameter(Mandatory = $true)]$Settings,
        [switch]$CreateBackup
    )

    $settingsPath = Get-BootstrapSteamDeckSettingsPath
    $normalized = Normalize-BootstrapSteamDeckSettingsData -Settings $Settings
    $backupPath = $null
    if ($CreateBackup) {
        $backupPath = Backup-BootstrapFile -Path $settingsPath
    }

    Write-BootstrapJsonFile -Path $settingsPath -Value $normalized

    return [ordered]@{
        Path = $settingsPath
        BackupPath = $backupPath
    }
}

function Apply-BootstrapSharedVramLaunchOptions {
    param(
        [string]$SteamRoot = "${env:ProgramFiles(x86)}\Steam",
        [AllowNull()]$Settings = $null,
        [switch]$DryRun
    )

    $settingsInput = $Settings
    if ($null -eq $settingsInput) {
        $settingsInput = (Get-BootstrapSteamDeckSettingsData).Data
    }
    $settingsMap = Normalize-BootstrapSteamDeckSettingsData -Settings $settingsInput
    $fix = if ($settingsMap.ContainsKey('sharedVramFix')) { ConvertTo-BootstrapHashtable -InputObject $settingsMap['sharedVramFix'] } else { @{} }
    $enabled = if ($fix.ContainsKey('enabled')) { [bool]$fix['enabled'] } else { $true }
    $launchOption = if ($fix.ContainsKey('launchOption') -and -not [string]::IsNullOrWhiteSpace([string]$fix['launchOption'])) { [string]$fix['launchOption'] } else { '-sharedvram' }
    $games = if ($fix.ContainsKey('games')) { @(Normalize-BootstrapObjectArray -Value $fix['games']) } else { @() }

    if (-not $enabled) {
        return [ordered]@{ DryRun = [bool]$DryRun; Status = 'skipped'; Reason = 'sharedVramFix desabilitado em settings.'; Changes = @() }
    }
    if ([string]::IsNullOrWhiteSpace($SteamRoot) -or -not (Test-Path $SteamRoot)) {
        return [ordered]@{ DryRun = [bool]$DryRun; Status = 'skipped'; Reason = "SteamRoot inexistente: $SteamRoot"; Changes = @() }
    }
    if (@($games).Count -eq 0) {
        return [ordered]@{ DryRun = [bool]$DryRun; Status = 'skipped'; Reason = 'Allowlist sharedVramFix.games vazia.'; Changes = @() }
    }

    $changes = @()
    foreach ($gameRaw in @($games)) {
        $game = ConvertTo-BootstrapHashtable -InputObject $gameRaw
        $appId = [string]$game['appId']
        if ([string]::IsNullOrWhiteSpace($appId)) {
            $changes += @([ordered]@{ appId = ''; status = 'skipped'; reason = 'appId ausente na allowlist.' })
            continue
        }

        $localConfigCandidates = @(Get-ChildItem -Path (Join-Path $SteamRoot 'userdata') -Filter 'localconfig.vdf' -Recurse -ErrorAction SilentlyContinue)
        if (@($localConfigCandidates).Count -eq 0) {
            $changes += @([ordered]@{ appId = $appId; status = 'skipped'; reason = 'localconfig.vdf nao encontrado para nenhum usuário Steam.' })
            continue
        }

        foreach ($candidate in @($localConfigCandidates)) {
            $targetPath = [string]$candidate.FullName
            $raw = ''
            try {
                $raw = Get-Content -Path $targetPath -Raw -Encoding utf8
            } catch {
                $changes += @([ordered]@{ appId = $appId; path = $targetPath; status = 'failed'; reason = "Falha leitura: $($_.Exception.Message)" })
                continue
            }

            $sectionPattern = "(?ms)(""$([regex]::Escape($appId))""\s*\{.*?\})"
            $hasGameSection = [regex]::IsMatch($raw, $sectionPattern)
            if (-not $hasGameSection) {
                $changes += @([ordered]@{ appId = $appId; path = $targetPath; status = 'skipped'; reason = 'App nao encontrado no localconfig.vdf deste usuário.' })
                continue
            }

            if ($DryRun) {
                $changes += @([ordered]@{ appId = $appId; path = $targetPath; status = 'planned'; launchOption = $launchOption })
                continue
            }

            $backup = Backup-BootstrapFile -Path $targetPath
            $updated = $raw
            $launchPattern = "(?ms)(""$([regex]::Escape($appId))""\s*\{.*?""LaunchOptions""\s*"")(.*?)("")"
            if ([regex]::IsMatch($updated, $launchPattern)) {
                $updated = [regex]::Replace($updated, $launchPattern, ('${1}{0}${3}' -f $launchOption), 1)
            } else {
                $insertPattern = "(?ms)(""$([regex]::Escape($appId))""\s*\{)"
                $updated = [regex]::Replace($updated, $insertPattern, ('$1`r`n`t`t"LaunchOptions"`t`t"{0}"' -f $launchOption), 1)
            }

            try {
                $encoding = New-Object System.Text.UTF8Encoding($false)
                [System.IO.File]::WriteAllText($targetPath, $updated, $encoding)
                $changes += @([ordered]@{ appId = $appId; path = $targetPath; status = 'applied'; backup = $backup; launchOption = $launchOption })
            } catch {
                $changes += @([ordered]@{ appId = $appId; path = $targetPath; status = 'failed'; backup = $backup; reason = "Falha escrita: $($_.Exception.Message)" })
            }
        }
    }

    $applied = @($changes | Where-Object { [string]$_.status -eq 'applied' }).Count
    $planned = @($changes | Where-Object { [string]$_.status -eq 'planned' }).Count
    $status = if ($DryRun -and $planned -gt 0) { 'planned' } elseif ($applied -gt 0) { 'applied' } else { 'skipped' }
    return [ordered]@{
        DryRun = [bool]$DryRun
        Status = $status
        Reason = if ($status -eq 'skipped') { 'Nenhuma alteração aplicável encontrada para allowlist.' } else { '' }
        LaunchOption = $launchOption
        Changes = @($changes)
    }
}

function Get-BootstrapSteamDeckCurrentDetectionData {
    $path = Get-BootstrapSteamDeckDetectionPath
    if (-not (Test-Path $path)) {
        return [ordered]@{
            Path = $path
            Data = $null
        }
    }

    return [ordered]@{
        Path = $path
        Data = (Read-BootstrapJsonFile -Path $path)
    }
}

function Get-BootstrapSteamDeckPendingExternalDisplay {
    $bundle = Get-BootstrapSteamDeckCurrentDetectionData
    $data = ConvertTo-BootstrapHashtable -InputObject $bundle.Data
    if (-not ($data -is [hashtable])) {
        return [ordered]@{
            Path = $bundle.Path
            Pending = $false
            Detection = $null
            Display = $null
        }
    }

    $pending = ($data.ContainsKey('mode') -and ([string]$data['mode'] -eq 'UNCLASSIFIED_EXTERNAL'))
    $display = if ($data.ContainsKey('selectedDisplay')) { $data['selectedDisplay'] } else { $null }
    return [ordered]@{
        Path = $bundle.Path
        Pending = [bool]$pending
        Detection = $data
        Display = $display
    }
}

function Add-BootstrapSteamDeckDisplayClassification {
    param(
        [Parameter(Mandatory = $true)][ValidateSet('MonitorDev', 'TvGame')][string]$Choice,
        [hashtable]$Display,
        [switch]$CreateBackup
    )

    if (-not $Display) {
        $pending = Get-BootstrapSteamDeckPendingExternalDisplay
        $Display = ConvertTo-BootstrapHashtable -InputObject $pending.Display
    }

    if (-not $Display) {
        throw 'Nenhum display externo pendente para classificar.'
    }

    $manufacturer = ([string]$Display['manufacturer']).Trim()
    $product = ([string]$Display['product']).Trim()
    $serial = ([string]$Display['serial']).Trim()
    if ([string]::IsNullOrWhiteSpace($manufacturer) -or [string]::IsNullOrWhiteSpace($product)) {
        throw 'Classificacao de display exige manufacturer e product.'
    }

    $mode = 'DOCKED_MONITOR'
    $layout = 'external-monitor-dev'
    $resolutionPolicy = 'native-prefer-1440p-else-1080p'
    if ($Choice -eq 'TvGame') {
        $mode = 'DOCKED_TV'
        $layout = 'external-tv-game'
        $resolutionPolicy = '1920x1080-safe'
    }

    $settingsBundle = Get-BootstrapSteamDeckSettingsData
    $settings = ConvertTo-BootstrapHashtable -InputObject $settingsBundle.Data
    $families = @(Normalize-BootstrapObjectArray -Value $settings['monitorFamilies'])
    $nextFamilies = @()
    $updated = $false

    foreach ($family in $families) {
        $familyMap = ConvertTo-BootstrapHashtable -InputObject $family
        $sameManufacturer = ([string]$familyMap['manufacturer']).Trim() -ieq $manufacturer
        $sameProduct = ([string]$familyMap['product']).Trim() -ieq $product
        if ($sameManufacturer -and $sameProduct) {
            $familyMap['mode'] = $mode
            $familyMap['layout'] = $layout
            $familyMap['resolutionPolicy'] = $resolutionPolicy
            $familyMap['primary'] = $true
            $familyMap['classifiedAt'] = (Get-Date).ToString('o')
            $familyMap['classifiedBy'] = 'bootstrap-ui'
            $updated = $true
        }
        $nextFamilies += @($familyMap)
    }

    if (-not $updated) {
        $entry = @{
            manufacturer = $manufacturer
            product = $product
            namePattern = $product
            mode = $mode
            layout = $layout
            resolutionPolicy = $resolutionPolicy
            primary = $true
            classifiedAt = (Get-Date).ToString('o')
            classifiedBy = 'bootstrap-ui'
        }
        if (-not [string]::IsNullOrWhiteSpace($serial)) {
            $entry['sampleSerial'] = $serial
        }
        $nextFamilies += @($entry)
    }

    $settings['monitorFamilies'] = @($nextFamilies)
    $saveResult = Save-BootstrapSteamDeckSettingsData -Settings $settings -CreateBackup:$CreateBackup

    return [ordered]@{
        Path = $saveResult.Path
        BackupPath = $saveResult.BackupPath
        Target = 'monitorFamilies'
        Mode = $mode
        Layout = $layout
        ResolutionPolicy = $resolutionPolicy
        Manufacturer = $manufacturer
        Product = $product
    }
}

function Ensure-BootstrapSteamDeckSettings {
    param([hashtable]$State)

    $dataRoot = Get-BootstrapDataRoot
    $settingsPath = Get-BootstrapSteamDeckSettingsPath
    $null = New-Item -Path $dataRoot -ItemType Directory -Force

    $current = $null
    if (Test-Path $settingsPath) {
        try {
            $current = Get-Content -Path $settingsPath -Raw | ConvertFrom-Json -ErrorAction Stop
        } catch {
            Write-Log "Falha ao ler $settingsPath. Os defaults do Steam Deck serao regravados." 'WARN'
        }
    }

    $merged = Merge-BootstrapData -Defaults (Get-BootstrapSteamDeckSettingsDefaults -ResolvedSteamDeckVersion $State.ResolvedSteamDeckVersion) -Current $current
    $merged = Normalize-BootstrapSteamDeckSettingsData -Settings $merged
    $merged.steamDeckVersion = $State.RequestedSteamDeckVersion
    $merged.resolvedSteamDeckVersion = $State.ResolvedSteamDeckVersion
    $json = [string]((ConvertTo-BootstrapObjectGraph -InputObject $merged) | ConvertTo-Json -Depth 12)
    $utf8 = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($settingsPath, $json, $utf8)
    $State.SteamDeckSettingsPath = $settingsPath
    Write-Log "Config do Steam Deck garantida: $settingsPath"

    return $settingsPath
}

function Ensure-BootstrapSteamDeckWatcherTask {
    param([hashtable]$State)

    $watcherScript = Join-Path $State.SteamDeckAutomationRoot 'ModeWatcher.ps1'
    if (-not (Test-Path $watcherScript)) { return }

    $powershellExe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    if (-not (Test-Path $powershellExe)) {
        Write-Log 'Nao foi possivel localizar powershell.exe para registrar o watcher do Steam Deck.' 'WARN'
        return
    }

    $taskName = 'BootstrapTools-SteamDeckModeWatcher'
    $taskCommand = ('"{0}" -NoProfile -ExecutionPolicy Bypass -File "{1}" -SettingsPath "{2}"' -f $powershellExe, $watcherScript, $State.SteamDeckSettingsPath)
    $schtasksExe = Resolve-CommandPath -Name 'schtasks.exe'
    if (-not $schtasksExe) { $schtasksExe = Join-Path $env:SystemRoot 'System32\schtasks.exe' }
    if (-not (Test-Path $schtasksExe)) {
        Write-Log 'schtasks.exe nao encontrado. O watcher do Steam Deck nao foi registrado.' 'WARN'
        return
    }

    $exitCode = Invoke-NativeWithLog -Exe $schtasksExe -Args @('/Create', '/SC', 'ONLOGON', '/TN', $taskName, '/TR', $taskCommand, '/F')
    if ($exitCode -ne 0) {
        Write-Log "Falha ao registrar a tarefa $taskName (exit=$exitCode)." 'WARN'
        return
    }

    Write-Log "Watcher do Steam Deck registrado: $taskName"
}

function Ensure-BootstrapSteamDeckAutomation {
    param([hashtable]$State)

    $settingsPath = Ensure-BootstrapSteamDeckSettings -State $State
    $sourceAutomationRoot = Get-BootstrapSteamDeckAssetsRoot
    $sourceMaintenanceRoot = Get-BootstrapSteamDeckMaintenanceAssetsRoot
    $targetAutomationRoot = Get-BootstrapSteamDeckAutomationRoot
    $targetMaintenanceRoot = Get-BootstrapSteamDeckMaintenanceRoot

    if (-not (Test-Path $sourceAutomationRoot)) {
        throw "Assets de automacao do Steam Deck nao encontrados em: $sourceAutomationRoot"
    }
    if (-not (Test-Path $sourceMaintenanceRoot)) {
        throw "Assets de manutencao do Steam Deck nao encontrados em: $sourceMaintenanceRoot"
    }

    $null = New-Item -Path $targetAutomationRoot -ItemType Directory -Force
    $null = New-Item -Path $targetMaintenanceRoot -ItemType Directory -Force
    Copy-Item -Path (Join-Path $sourceAutomationRoot '*') -Destination $targetAutomationRoot -Force -Recurse
    Copy-Item -Path (Join-Path $sourceMaintenanceRoot '*') -Destination $targetMaintenanceRoot -Force -Recurse
    Copy-Item -Path (Join-Path $PSScriptRoot 'bootstrap-tools.ps1') -Destination (Join-Path $targetMaintenanceRoot 'bootstrap-tools.ps1') -Force
    $State.SteamDeckAutomationRoot = $targetAutomationRoot
    $State.SteamDeckSettingsPath = $settingsPath

    Ensure-BootstrapSteamDeckWatcherTask -State $State
    Write-Log "Automacao/manutencao do Steam Deck garantidas: automation=$targetAutomationRoot maintenance=$targetMaintenanceRoot"
}

function Test-BootstrapManualRequirementInstalled {
    param([Parameter(Mandatory = $true)]$ComponentDef)

    if ($ComponentDef.PSObject.Properties.Name -contains 'CheckCommand') {
        $commandPath = Resolve-CommandPath -Name $ComponentDef.CheckCommand
        if ($commandPath) { return $true }
    }

    if ($ComponentDef.PSObject.Properties.Name -contains 'ProbePaths') {
        foreach ($path in @($ComponentDef.ProbePaths)) {
            if ([string]::IsNullOrWhiteSpace($path)) { continue }
            if (Test-Path $ExecutionContext.InvokeCommand.ExpandString($path)) {
                return $true
            }
        }
    }

    return $false
}

function Ensure-BootstrapManualRequirement {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$ComponentDef
    )

    if (Test-BootstrapManualRequirementInstalled -ComponentDef $ComponentDef) {
        Write-Log "$($ComponentDef.DisplayName) ja esta presente no host."
        return
    }

    $instructions = if ($ComponentDef.PSObject.Properties.Name -contains 'Instructions') { [string]$ComponentDef.Instructions } else { 'Instale manualmente e rode o bootstrap novamente.' }
    $componentName = if ($ComponentDef.PSObject.Properties.Name -contains 'Name') { [string]$ComponentDef.Name } else { [string]$ComponentDef.Id }
    $displayName = if ($ComponentDef.PSObject.Properties.Name -contains 'DisplayName') { [string]$ComponentDef.DisplayName } else { $componentName }
    $manualRequirement = [ordered]@{
        component = $componentName
        displayName = $displayName
        status = 'manual-required'
        instructions = $instructions
    }
    if ($State) {
        if (-not $State.ContainsKey('ManualRequirements') -or -not $State.ManualRequirements) {
            $State.ManualRequirements = New-Object System.Collections.Generic.List[object]
        }
        $State.ManualRequirements.Add($manualRequirement) | Out-Null
    }

    if ($script:IgnoreManualRequirements) {
        Write-Log ("Ignorando dependencia manual por flag global: {0}. {1}" -f $displayName, $instructions) 'WARN'
        return
    }

    if (($ComponentDef.PSObject.Properties.Name -contains 'Optional') -and [bool]$ComponentDef.Optional) {
        Write-Log ("Dependencia manual opcional ausente: {0}. {1}" -f $displayName, $instructions) 'WARN'
        return
    }

    if ($script:SkipManualRequirements) {
        Write-Log ("Pulando dependencia manual obrigatoria por flag global: {0}. {1}" -f $displayName, $instructions) 'WARN'
        return
    }

    throw ("Dependencia manual obrigatoria ausente: {0}. {1}" -f $displayName, $instructions)
}

function Get-BootstrapComponentStage {
    param([Parameter(Mandatory = $true)]$ComponentDef)

    if ($ComponentDef.PSObject.Properties.Name -contains 'Stage') {
        return ([string]$ComponentDef.Stage).ToLowerInvariant()
    }

    switch ($ComponentDef.Kind) {
        'system-core' { return 'runtime' }
        'git-core' { return 'runtime' }
        'node-core' { return 'runtime' }
        'dotnet-core' { return 'runtime' }
        'python-core' { return 'runtime' }
        'wsl-core' { return 'runtime' }
        'steamdeck-settings' { return 'config' }
        'steamdeck-automation' { return 'config' }
        'os-slim-server' { return 'config' }
        'gpedit-hardening' { return 'config' }
        'manual-required' { return 'verify' }
        default { return 'payload' }
    }
}

function Get-BootstrapUsesSteamDeckFlow {
    param(
        [Parameter(Mandatory = $true)]$Selection,
        [Parameter(Mandatory = $true)]$Resolution
    )

    foreach ($name in @($Selection.Profiles) + @($Selection.Components) + @($Resolution.ExpandedProfiles) + @($Resolution.ResolvedComponents)) {
        if (-not [string]::IsNullOrWhiteSpace($name) -and $name.ToLowerInvariant().StartsWith('steamdeck-')) {
            return $true
        }
    }

    return $false
}

function Get-BootstrapEmulationSharedLayout {
    param([string]$Root = '')

    if ([string]::IsNullOrWhiteSpace($Root)) {
        $Root = Join-Path $env:USERPROFILE 'Games\Emulation'
    }

    # [System.IO.Path]::Combine evita validacao de drive (Join-Path lanca em drive inexistente p.ex. X:).
    return [ordered]@{
        root = $Root
        emulators = [System.IO.Path]::Combine($Root, 'emulators')
        tools = [System.IO.Path]::Combine($Root, 'tools')
        roms = [System.IO.Path]::Combine($Root, 'roms')
        firmware = [System.IO.Path]::Combine($Root, 'firmware')
        saves = [System.IO.Path]::Combine($Root, 'saves')
        cache = [System.IO.Path]::Combine($Root, 'cache')
        mods = [System.IO.Path]::Combine($Root, 'mods')
        metadata = [System.IO.Path]::Combine($Root, 'metadata')
        systems = [ordered]@{
            ps1 = [ordered]@{
                emulatorKey = 'duckstation'
                executable = [System.IO.Path]::Combine($Root, 'emulators\duckstation\duckstation-qt.exe')
                roms = [System.IO.Path]::Combine($Root, 'roms\ps1')
                firmware = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'firmware\ps1\bios'); policy = 'user-provided-only'; shareWithLaunchers = $true }
                saves = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'saves\ps1\memcards'); policy = 'canonical-duckstation-memory-cards'; shareWithLaunchers = $true }
                cache = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'cache\duckstation'); policy = 'per-emulator-version-and-gpu'; shareAcrossVersions = $false }
                mods = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'mods\ps1'); policy = 'game-specific-user-managed'; shareWithLaunchers = $true }
                metadata = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'metadata\ps1'); policy = 'frontend-safe-artwork-and-library-data'; shareWithLaunchers = $true }
            }
            ps2 = [ordered]@{
                emulatorKey = 'pcsx2'
                executable = [System.IO.Path]::Combine($Root, 'emulators\pcsx2\pcsx2-qt.exe')
                roms = [System.IO.Path]::Combine($Root, 'roms\ps2')
                firmware = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'firmware\ps2\bios'); policy = 'user-provided-only'; shareWithLaunchers = $true }
                saves = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'saves\ps2\memcards'); policy = 'canonical-pcsx2-memory-cards'; shareWithLaunchers = $true }
                cache = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'cache\pcsx2'); policy = 'per-emulator-version-and-gpu'; shareAcrossVersions = $false }
                mods = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'mods\ps2'); policy = 'game-specific-user-managed'; shareWithLaunchers = $true }
                metadata = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'metadata\ps2'); policy = 'frontend-safe-artwork-and-library-data'; shareWithLaunchers = $true }
            }
            ps3 = [ordered]@{
                emulatorKey = 'rpcs3'
                executable = [System.IO.Path]::Combine($Root, 'emulators\rpcs3\rpcs3.exe')
                roms = [System.IO.Path]::Combine($Root, 'roms\ps3')
                firmware = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'firmware\ps3\PS3UPDAT.PUP'); policy = 'official-or-user-provided'; shareWithLaunchers = $true }
                saves = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'emulators\rpcs3\dev_hdd0\home\00000001\savedata'); policy = 'single-rpcs3-dev_hdd0-root'; shareWithLaunchers = $true; outsideSharedSavesRoot = $true; exceptionReason = 'RPCS3 exige saves dentro de seu dev_hdd0; root unico do proprio emulador (excecao consciente ao saves\ compartilhado).' }
                storage = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'emulators\rpcs3\dev_hdd0'); policy = 'single-rpcs3-dev_hdd0-root'; destructiveWrites = $false }
                cache = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'cache\rpcs3'); policy = 'per-rpcs3-version-and-gpu'; shareAcrossVersions = $false }
                mods = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'mods\ps3'); policy = 'game-specific-user-managed'; shareWithLaunchers = $true }
                metadata = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'metadata\ps3'); policy = 'frontend-safe-artwork-and-library-data'; shareWithLaunchers = $true }
            }
            switch = [ordered]@{
                emulatorKey = 'switch'
                selectedRuntimePolicy = 'user-selects-one-source-verified-family'
                roms = [System.IO.Path]::Combine($Root, 'roms\switch')
                keys = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'firmware\switch\keys'); policy = 'user-provided-own-console-only'; maskInLogs = $true; shareWithLaunchers = $false }
                firmware = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'firmware\switch\firmware'); policy = 'user-provided-own-console-only'; shareWithLaunchers = $false }
                nand = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'state\switch\nand'); policy = 'per-emulator-family'; shareAcrossEmulatorFamilies = $false }
                saves = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'saves\switch'); policy = 'backup-export-import-only'; shareAcrossEmulatorFamilies = $false; shareWithLaunchers = $true }
                cache = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'cache\switch'); policy = 'per-emulator-version-and-gpu'; shareAcrossEmulatorFamilies = $false }
                mods = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'mods\switch'); policy = 'per-title-and-engine-family'; shareAcrossEmulatorFamilies = $false }
                metadata = [ordered]@{ path = [System.IO.Path]::Combine($Root, 'metadata\switch'); policy = 'frontend-safe-artwork-and-library-data'; shareWithLaunchers = $true }
            }
        }
    }
}

function Get-BootstrapDeckEmulationMediaCompatMap {
    # Pastas canonicas "reais" + links de compatibilidade (alias -> alvo canonico) para scrapers.
    return [ordered]@{
        canonical = @('box2dfront', 'screenshot', 'video', 'marquee', 'bezel', 'wheel', 'titlescreen', 'manual', 'fanart', 'physicalmedia', 'box3dfront', 'boxback', 'miximage')
        compat = [ordered]@{
            'cover'        = 'box2dfront'
            'boxFront'     = 'box2dfront'
            'box2dback'    = 'boxback'
            'snap'         = 'video'
            'logo'         = 'wheel'
            'wheelcarbon'  = 'wheel'
            'titleshot'    = 'titlescreen'
            'support'      = 'physicalmedia'
            'background'   = 'fanart'
        }
    }
}

function Get-BootstrapDeckEmulationShortnames {
    # Shortnames ES-DE/EmuDeck dos sistemas suportados/comuns. Usados nas pastas roms/<shortname>
    # e storage/downloaded_media/<shortname>.
    return @('snes', 'nes', 'n64', 'gc', 'wii', 'gb', 'gba', 'gbc', 'nds', '3ds', 'switch',
             'psx', 'ps2', 'ps3', 'psp', 'genesis', 'megadrive', 'saturn', 'dreamcast',
             'segacd', 'gamegear', 'mastersystem', 'arcade', 'mame', 'fbneo', 'atari2600')
}

function Get-BootstrapDeckEmulationLayout {
    # Layout no padrao EmuDeck/ES-DE (shortname), distinto do layout PS-centrico de
    # Get-BootstrapEmulationSharedLayout. Usado quando apontamos para o HOME do Deck (ou um root
    # local equivalente). Sem efeitos colaterais.
    param([Parameter(Mandatory = $true)][string]$Root)

    $combine = { param($a, $b) [System.IO.Path]::Combine($a, $b) }
    return [ordered]@{
        root  = $Root
        # leitura compartilhada (ROMs/BIOS/midia): seguro apontar mesmo em read-only.
        bios  = [ordered]@{ path = (& $combine $Root 'bios');  access = 'read-shared' }
        tools = [ordered]@{ path = (& $combine $Root 'tools'); access = 'read-shared' }
        roms  = [ordered]@{ path = (& $combine $Root 'roms');  access = 'read-shared' }
        media = [ordered]@{ path = (& $combine $Root 'storage\downloaded_media'); access = 'read-shared' }
        # escrita (saves/states/cache): so no Deck quando write-opt-in; senao local Windows.
        saves  = [ordered]@{ path = (& $combine $Root 'saves');  access = 'write-gated' }
        states = [ordered]@{ path = (& $combine $Root 'states'); access = 'write-gated' }
        cache  = [ordered]@{ path = (& $combine $Root 'storage\cache'); access = 'write-gated' }
        shortnames = @(Get-BootstrapDeckEmulationShortnames)
        mediaCompat = (Get-BootstrapDeckEmulationMediaCompatMap)
    }
}

function Resolve-BootstrapEmulationRoots {
    # Ponto unico de resolucao de roots consumido por midia/frontends/atalhos.
    # Precedencia: HOME do Deck valido e legivel -> leitura no Deck; escrita no Deck so se
    # write-opt-in. Senao, fallback transparente para o root local do Windows.
    param(
        $DeckInfo = $null,
        [switch]$ScanVolumes
    )

    if ($null -eq $DeckInfo) {
        $DeckInfo = Get-BootstrapDeckEmulationRoot -ScanVolumes:$ScanVolumes
    }

    $windowsRoot = Join-Path $env:USERPROFILE 'Games\Emulation'

    $deckFound = [bool]$DeckInfo.found
    $deckReadable = ($deckFound -and [bool]$DeckInfo.readable)
    $deckWritable = ($deckFound -and [bool]$DeckInfo.writable)
    $deckRoot = [string]$DeckInfo.emulationRoot

    $readRoot  = if ($deckReadable) { $deckRoot } else { $windowsRoot }
    $writeRoot = if ($deckWritable) { $deckRoot } else { $windowsRoot }

    $readLayout  = Get-BootstrapDeckEmulationLayout -Root $readRoot
    $writeLayout = Get-BootstrapDeckEmulationLayout -Root $writeRoot

    return [ordered]@{
        deckFound    = $deckFound
        deckReadable = $deckReadable
        deckWritable = $deckWritable
        accessLevel  = [string]$DeckInfo.accessLevel
        windowsRoot  = $windowsRoot
        readRoot     = $readRoot
        writeRoot    = $writeRoot
        # caminhos efetivos por tipo de dado
        bios   = [string]$readLayout.bios.path
        tools  = [string]$readLayout.tools.path
        roms   = [string]$readLayout.roms.path
        media  = [string]$readLayout.media.path
        saves  = [string]$writeLayout.saves.path
        states = [string]$writeLayout.states.path
        cache  = [string]$writeLayout.cache.path
        readLayout  = $readLayout
        writeLayout = $writeLayout
    }
}

function New-BootstrapEmulationConfigPlan {
    param(
        [Parameter(Mandatory = $true)]$Layout,
        [Parameter(Mandatory = $true)]$Tuning
    )

    return [ordered]@{
        destructiveStorageWrites = $false
        pcsx2 = [ordered]@{
            iniPath = [System.IO.Path]::Combine([string]$Layout.systems.ps2.emulatorKey, 'inis\PCSX2.ini')
            values = [ordered]@{
                EmuCore = [ordered]@{ CdvdFastBoot = [bool]$Tuning.ps2.fastBoot }
                Graphics = [ordered]@{
                    Renderer = [string]$Tuning.ps2.renderer
                    AspectRatio = '16:9'
                    AnisotropicFiltering = '4x'
                }
            }
            cacheSharedAcrossVersions = [bool]$Layout.systems.ps2.cache.shareAcrossVersions
        }
        rpcs3 = [ordered]@{
            yamlPath = [System.IO.Path]::Combine([string]$Layout.systems.ps3.emulatorKey, 'config\global_config.yml')
            values = [ordered]@{
                Core = [ordered]@{
                    PPU_Decoder = [string]$Tuning.ps3.ppuDecoder
                    SPU_Decoder = [string]$Tuning.ps3.spuDecoder
                    SPU_Threads = [string]$Tuning.ps3.spuThreads
                }
                Video = [ordered]@{
                    Renderer = [string]$Tuning.ps3.renderer
                    Shader_Compilation_Mode = 'AsyncWithPrecompiler'
                }
            }
            cacheSharedAcrossVersions = [bool]$Layout.systems.ps3.cache.shareAcrossVersions
        }
    }
}

function Merge-BootstrapHydraClassicConfig {
    # Liga as flags de conteudo classico/retro do Hydra v4 (config.json) preservando chaves
    # desconhecidas. Nao escreve com Hydra em execucao salvo -Force. Sem download de nada.
    param(
        [Parameter(Mandatory = $true)][string]$ConfigPath,
        [bool]$DisplayClassicContent = $true,
        [bool]$EnableRetroUIFeatures = $true,
        [switch]$HydraProcessRunning,
        [switch]$Force
    )

    if ($HydraProcessRunning -and -not $Force) {
        return [pscustomobject]@{ status = 'blocked-process-running'; changed = $false; path = $ConfigPath }
    }

    $parent = Split-Path -Path $ConfigPath -Parent
    if (-not [string]::IsNullOrWhiteSpace($parent)) {
        New-Item -Path $parent -ItemType Directory -Force | Out-Null
    }

    $data = [ordered]@{}
    if (Test-Path -LiteralPath $ConfigPath) {
        $raw = Get-Content -LiteralPath $ConfigPath -Raw
        if (-not [string]::IsNullOrWhiteSpace($raw)) {
            $parsed = $raw | ConvertFrom-Json -ErrorAction Stop
            foreach ($prop in $parsed.PSObject.Properties) {
                $data[$prop.Name] = $prop.Value
            }
        }
    }

    $data['displayClassicContent'] = [bool]$DisplayClassicContent
    $data['enableRetroUIFeatures'] = [bool]$EnableRetroUIFeatures

    $json = $data | ConvertTo-Json -Depth 10
    [System.IO.File]::WriteAllText($ConfigPath, $json, [System.Text.UTF8Encoding]::new($false))
    return [pscustomobject]@{ status = 'updated'; changed = $true; path = $ConfigPath }
}

function Merge-BootstrapHydraEmulatorConfig {
    param(
        [Parameter(Mandatory = $true)][string]$ConfigPath,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$Entries,
        [switch]$HydraProcessRunning,
        [switch]$Force
    )

    if ($HydraProcessRunning -and -not $Force) {
        return [pscustomobject]@{ status = 'blocked-process-running'; changed = $false; path = $ConfigPath }
    }

    $parent = Split-Path -Path $ConfigPath -Parent
    if (-not [string]::IsNullOrWhiteSpace($parent)) {
        New-Item -Path $parent -ItemType Directory -Force | Out-Null
    }

    $data = [ordered]@{}
    if (Test-Path -LiteralPath $ConfigPath) {
        $raw = Get-Content -LiteralPath $ConfigPath -Raw
        if (-not [string]::IsNullOrWhiteSpace($raw)) {
            $parsed = $raw | ConvertFrom-Json -ErrorAction Stop
            foreach ($prop in $parsed.PSObject.Properties) {
                $data[$prop.Name] = $prop.Value
            }
        }
    }

    foreach ($entry in @($Entries)) {
        $systemKey = [string]$entry.systemKey
        if ([string]::IsNullOrWhiteSpace($systemKey)) { continue }
        $data[$systemKey] = [ordered]@{
            enabled = $true
            emulator_name = [string]$entry.emulatorName
            executable_path = [string]$entry.executablePath
            roms_directory = [string]$entry.romsDirectory
            default_flags = [string]$entry.defaultFlags
        }
    }

    $json = $data | ConvertTo-Json -Depth 10
    [System.IO.File]::WriteAllText($ConfigPath, $json, [System.Text.UTF8Encoding]::new($false))
    return [pscustomobject]@{ status = 'updated'; changed = $true; path = $ConfigPath }
}

function Get-BootstrapEmulationTuningRecommendation {
    param([Parameter(Mandatory = $true)]$HostProfile)

    $supportsVulkan = [bool]$HostProfile.SupportsVulkan
    $isDeck = [bool]$HostProfile.IsSteamDeck
    $logicalProcessors = [int]$HostProfile.LogicalProcessors
    $memoryGb = [int]$HostProfile.MemoryGB
    $storageClass = [string]$HostProfile.StorageClass

    $profileName = 'desktop-balanced'
    if (-not $supportsVulkan) {
        $profileName = 'compatibility'
    } elseif ($isDeck) {
        $profileName = 'handheld-balanced'
    } elseif ($logicalProcessors -ge 12 -and $memoryGb -ge 32) {
        $profileName = 'desktop-performance'
    }

    $ps2Renderer = if ($supportsVulkan) { 'Vulkan' } else { 'Direct3D12' }
    $media = if ($storageClass -match 'sd|usb|hdd') { 'prefer-chd-after-verification' } else { 'iso-or-chd-user-choice' }
    $ps3Mode = if ($supportsVulkan -and $memoryGb -ge 16) { 'standard' } else { 'manual-compatibility-review' }

    return [ordered]@{
        profile = $profileName
        ps2 = [ordered]@{
            frontend = 'PCSX2-Qt'
            renderer = $ps2Renderer
            fastBoot = $true
            mediaFormatRecommendation = $media
            libretroRecommended = $false
        }
        ps3 = [ordered]@{
            frontend = 'RPCS3'
            renderer = $(if ($supportsVulkan) { 'Vulkan' } else { 'manual' })
            ppuDecoder = 'LLVM'
            spuDecoder = 'LLVM'
            spuThreads = 'auto'
            mode = $ps3Mode
        }
        watchdog = [ordered]@{
            reportFirst = $true
            forceKillDefault = $false
            resetHydraStateOnlyWhenApiProbePasses = $true
        }
    }
}

function Get-BootstrapEmulationFriendlyFixCatalog {
    $switchMessage = 'Use apenas arquivos do usuario, extraidos do proprio console e jogos proprios. PhaseZero nao baixa keys, firmware, jogos, updates, DLC ou mods.'

    return @(
        [pscustomobject][ordered]@{ id = 'switch-missing-keys'; system = 'switch'; title = 'Switch: keys ausentes'; mode = 'guided-user-content'; safeAction = 'open-shared-switch-keys-folder'; destructiveDefault = $false; requiresBackup = $false; userMessage = $switchMessage; blockedActions = @('download-keys','bypass-decryption') }
        [pscustomobject][ordered]@{ id = 'switch-firmware-mismatch'; system = 'switch'; title = 'Switch: firmware incompativel'; mode = 'guided-user-content'; safeAction = 'open-shared-switch-firmware-folder'; destructiveDefault = $false; requiresBackup = $false; userMessage = $switchMessage; blockedActions = @('download-firmware') }
        [pscustomobject][ordered]@{ id = 'switch-black-screen'; system = 'switch'; title = 'Switch: tela preta'; mode = 'diagnose-renderer'; safeAction = 'recommend-renderer-and-driver-check'; destructiveDefault = $false; requiresBackup = $false; userMessage = 'Verifica Vulkan/GPU/driver, perfil handheld/docked e mods do usuario antes de alterar configs.'; blockedActions = @('delete-user-data') }
        [pscustomobject][ordered]@{ id = 'switch-controller-not-working'; system = 'switch'; title = 'Switch: controle nao detectado'; mode = 'guided-input-profile'; safeAction = 'show-input-stack-conflicts'; destructiveDefault = $false; requiresBackup = $false; userMessage = 'Audita Steam Input, ViGEm, Handheld Companion, GlosSI e mapeamento por emulador; perfil de input fica por usuario antes de gravar.'; blockedActions = @('disable-input-drivers') }
        [pscustomobject][ordered]@{ id = 'switch-stutter-shader-cache'; system = 'switch'; title = 'Switch: stutter/cache shader'; mode = 'guided-cleanup'; safeAction = 'backup-then-clear-selected-cache'; destructiveDefault = $false; requiresBackup = $true; userMessage = 'Cache shader fica por emulador, versao e GPU. Limpeza exige backup e selecao do usuario.'; blockedActions = @('clear-all-caches') }
        [pscustomobject][ordered]@{ id = 'switch-low-fps-host-capacity'; system = 'switch'; title = 'Switch: FPS baixo'; mode = 'host-capacity-profile'; safeAction = 'recommend-resolution-mode-and-power-profile'; destructiveDefault = $false; requiresBackup = $false; userMessage = 'Escolhe perfil por CPU, RAM, GPU, Vulkan, bateria e storage do usuario.'; blockedActions = @('force-overclock') }
        [pscustomobject][ordered]@{ id = 'switch-mod-conflict'; system = 'switch'; title = 'Switch: conflito de mods'; mode = 'audit-only'; safeAction = 'list-mods-per-title-and-engine'; destructiveDefault = $false; requiresBackup = $false; userMessage = 'Mods do usuario ficam por titulo e familia de emulador; PhaseZero so audita e permite desativacao guiada.'; blockedActions = @('delete-mods') }
        [pscustomobject][ordered]@{ id = 'switch-duplicate-runtime'; system = 'switch'; title = 'Switch: runtimes duplicados'; mode = 'audit-only'; safeAction = 'report-duplicate-emulator-roots'; destructiveDefault = $false; requiresBackup = $false; userMessage = 'Detecta duplicacao entre Hydra, EmuDeck, Playnite e Steam ROM Manager; runtimes do usuario nao sao removidos automaticamente.'; blockedActions = @('uninstall-runtime') }
        [pscustomobject][ordered]@{ id = 'switch-save-backup'; system = 'switch'; title = 'Switch: backup de saves'; mode = 'backup-only'; safeAction = 'snapshot-selected-save-roots'; destructiveDefault = $false; requiresBackup = $true; userMessage = 'Saves do usuario nao sao compartilhados entre familias por escrita direta; use backup, exportacao e importacao guiada.'; blockedActions = @('overwrite-saves') }
        [pscustomobject][ordered]@{ id = 'switch-vulkan-driver'; system = 'switch'; title = 'Switch: Vulkan/driver'; mode = 'readiness-check'; safeAction = 'run-gpu-vulkan-readiness'; destructiveDefault = $false; requiresBackup = $false; userMessage = 'Verifica driver e suporte Vulkan antes de recomendar renderer. Usuario escolhe aplicar.'; blockedActions = @('install-unverified-driver') }
    )
}

function Get-BootstrapSwitchEmulatorCandidateCatalog {
    function New-BootstrapSwitchEmulatorCandidate {
        param(
            [Parameter(Mandatory = $true)][string]$Id,
            [Parameter(Mandatory = $true)][string]$DisplayName,
            [Parameter(Mandatory = $true)][string]$Language,
            [Parameter(Mandatory = $true)][string]$DefaultStatus,
            [Parameter(Mandatory = $true)][string]$SourceTrust,
            [Parameter(Mandatory = $true)][string]$SharedRuntimeKey
        )

        return [pscustomobject][ordered]@{
            id = $Id
            displayName = $DisplayName
            language = $Language
            defaultStatus = $DefaultStatus
            sourceTrust = $SourceTrust
            sharedRuntimeKey = $SharedRuntimeKey
            systemKey = 'nintendo-switch'
            keysPolicy = 'user-provided-own-console-only'
            firmwarePolicy = 'user-provided-own-console-only'
            contentPolicy = 'user-owned-paths-only'
            autoInstallAllowed = $false
        }
    }

    return @(
        New-BootstrapSwitchEmulatorCandidate -Id 'ryujinx-family' -DisplayName 'Ryujinx family' -Language 'C#' -DefaultStatus 'manual-review' -SourceTrust 'verify-current-source-before-use' -SharedRuntimeKey 'switch-ryujinx-family'
        New-BootstrapSwitchEmulatorCandidate -Id 'yuzu-family' -DisplayName 'Yuzu family' -Language 'C++' -DefaultStatus 'reference-only' -SourceTrust 'discontinued-or-legacy-reference' -SharedRuntimeKey 'switch-yuzu-family'
        New-BootstrapSwitchEmulatorCandidate -Id 'suyu-family' -DisplayName 'Suyu family' -Language 'C++' -DefaultStatus 'manual-review' -SourceTrust 'verify-current-source-before-use' -SharedRuntimeKey 'switch-suyu-family'
        New-BootstrapSwitchEmulatorCandidate -Id 'sudachi-family' -DisplayName 'Sudachi family' -Language 'C++' -DefaultStatus 'manual-review' -SourceTrust 'verify-current-source-before-use' -SharedRuntimeKey 'switch-sudachi-family'
        New-BootstrapSwitchEmulatorCandidate -Id 'torzu-family' -DisplayName 'Torzu family' -Language 'C++' -DefaultStatus 'manual-review' -SourceTrust 'verify-current-source-before-use' -SharedRuntimeKey 'switch-torzu-family'
        New-BootstrapSwitchEmulatorCandidate -Id 'citron-family' -DisplayName 'Citron family' -Language 'C++' -DefaultStatus 'manual-review' -SourceTrust 'verify-current-source-before-use' -SharedRuntimeKey 'switch-citron-family'
        New-BootstrapSwitchEmulatorCandidate -Id 'eden-family' -DisplayName 'Eden family' -Language 'C++' -DefaultStatus 'manual-review' -SourceTrust 'verify-current-source-before-use' -SharedRuntimeKey 'switch-eden-family'
    )
}

function Get-BootstrapSwitchEmulationTuningRecommendation {
    param([Parameter(Mandatory = $true)]$HostProfile)

    $supportsVulkan = [bool]$HostProfile.SupportsVulkan
    $isDeck = [bool]$HostProfile.IsSteamDeck
    $memoryGb = [int]$HostProfile.MemoryGB
    $logicalProcessors = [int]$HostProfile.LogicalProcessors

    if (-not $supportsVulkan) {
        return [ordered]@{
            profile = 'compatibility-review'
            renderer = 'manual'
            consoleMode = 'handheld'
            resolutionScale = 1.0
            asyncShadersWhenSupported = $false
            autoApply = $false
            reason = 'Vulkan unavailable; user should review GPU driver and emulator compatibility.'
        }
    }

    if ($isDeck -or $memoryGb -lt 16 -or $logicalProcessors -lt 8) {
        return [ordered]@{
            profile = 'handheld-balanced'
            renderer = 'Vulkan'
            consoleMode = 'handheld'
            resolutionScale = 1.0
            asyncShadersWhenSupported = $true
            autoApply = $false
            reason = 'Conservative handheld profile for battery, thermals and shader stutter control.'
        }
    }

    return [ordered]@{
        profile = 'docked-balanced'
        renderer = 'Vulkan'
        consoleMode = 'docked'
        resolutionScale = 2.0
        asyncShadersWhenSupported = $true
        autoApply = $false
        reason = 'Desktop-capable host; still requires user review before applying.'
    }
}

