function Show-BootstrapProfiles {
    $profiles = Get-BootstrapProfileCatalog
    foreach ($profileName in $profiles.Keys) {
        $profileDef = $profiles[$profileName]
        Write-Output ("{0} - {1}" -f $profileDef.Name, $profileDef.Description)
    }
}

function Show-BootstrapComponents {
    $components = Get-BootstrapComponentCatalog
    foreach ($componentName in $components.Keys) {
        $componentDef = $components[$componentName]
        $depends = if ($componentDef.DependsOn.Count -gt 0) { $componentDef.DependsOn -join ', ' } else { '-' }
        $optional = if ($componentDef.Optional) { 'optional' } else { 'required' }
        Write-Output ("{0} - {1} | depends: {2} | {3}" -f $componentDef.Name, $componentDef.Description, $depends, $optional)
    }
}

function New-BootstrapSelectionObject {
    param(
        [string[]]$SelectedProfiles = @(),
        [string[]]$SelectedComponents = @(),
        [string[]]$ExcludedComponents = @(),
        [AllowNull()][string]$SelectedHostHealth = $null,
        [AllowNull()][string]$SelectedAppTuning = $null,
        [string[]]$SelectedAppTuningCategories = @(),
        [string[]]$SelectedAppTuningItems = @(),
        [string[]]$ExcludedAppTuningItems = @()
    )

    $profiles = @(Normalize-BootstrapNames -Names $SelectedProfiles)
    $components = @(Normalize-BootstrapNames -Names $SelectedComponents)
    $excludes = @(Normalize-BootstrapNames -Names $ExcludedComponents)
    $hostHealth = Normalize-BootstrapHostHealthMode -Mode $SelectedHostHealth
    $appTuningMode = Normalize-BootstrapAppTuningMode -Mode $SelectedAppTuning

    $hasExplicitAppTuningSelection = (
        -not [string]::IsNullOrWhiteSpace($appTuningMode) -or
        @($SelectedAppTuningCategories).Count -gt 0 -or
        @($SelectedAppTuningItems).Count -gt 0 -or
        @($ExcludedAppTuningItems).Count -gt 0
    )

    if ($profiles.Count -eq 0 -and $components.Count -eq 0 -and -not $hasExplicitAppTuningSelection) {
        $profiles = @('legacy')
    }

    return [pscustomobject]@{
        Profiles = @($profiles)
        Components = @($components)
        Excludes = @($excludes)
        HostHealth = $hostHealth
        AppTuning = $appTuningMode
        AppTuningCategories = @(Normalize-BootstrapNames -Names $SelectedAppTuningCategories)
        AppTuningItems = @(Normalize-BootstrapNames -Names $SelectedAppTuningItems)
        ExcludedAppTuningItems = @(Normalize-BootstrapNames -Names $ExcludedAppTuningItems)
    }
}

function Get-BootstrapProfileFamily {
    # Agrupa perfis em familias para a UI/CLI poderem rotular/agrupar (ex.: a familia de servidor).
    param([Parameter(Mandatory = $true)][string]$Name)
    $n = [string]$Name
    if ($n -match '^server-') { return 'Servidor caseiro' }
    if ($n -match '^steamdeck-') { return 'Steam Deck' }
    if ($n -match '^emulation-') { return 'Emulacao' }
    return 'Geral'
}

function Get-BootstrapUiContract {
    $profiles = Get-BootstrapProfileCatalog
    $components = Get-BootstrapComponentCatalog
    $apiCatalog = Get-BootstrapPublicApiCatalog
    $appCatalog = Get-BootstrapAppCapabilityCatalog
    $secretsData = $null
    $secretsPath = Get-BootstrapSecretsPath
    if (Test-Path $secretsPath) {
        try {
            $secretsData = Read-BootstrapJsonFile -Path $secretsPath
        } catch {
            $secretsData = Get-BootstrapSecretsTemplate
        }
    } else {
        $secretsData = Get-BootstrapSecretsTemplate
    }

    $profileEntries = foreach ($profileName in $profiles.Keys) {
        $profileDef = $profiles[$profileName]
        [ordered]@{
            name = $profileDef.Name
            description = $profileDef.Description
            items = @($profileDef.Items)
            family = (Get-BootstrapProfileFamily -Name $profileDef.Name)
        }
    }

    $statusCache = Read-BootstrapItemStatusCache
    $componentEntries = foreach ($componentName in $components.Keys) {
        $componentDef = $components[$componentName]
        $riskLevel = ''
        if ($componentDef.PSObject.Properties.Name -contains 'riskLevel') { $riskLevel = [string]$componentDef.riskLevel }
        if ([string]::IsNullOrWhiteSpace($riskLevel)) {
            $riskLevel = if ([string]$componentDef.Kind -eq 'manual-required') { 'manual' } else { 'safe' }
        }
        $manualReason = if ($componentDef.PSObject.Properties.Name -contains 'manualReason') { [string]$componentDef.manualReason } else { '' }
        $officialSource = if ($componentDef.PSObject.Properties.Name -contains 'officialSource') { [string]$componentDef.officialSource } else { '' }
        $requiresGpu = if ($componentDef.PSObject.Properties.Name -contains 'requiresGpu') { [bool]$componentDef.requiresGpu } else { $false }
        $requiresInteractiveLogin = if ($componentDef.PSObject.Properties.Name -contains 'requiresInteractiveLogin') { [bool]$componentDef.requiresInteractiveLogin } else { $false }
        $badges = New-Object System.Collections.Generic.List[string]
        switch ($riskLevel) {
            'safe' { $badges.Add('Seguro') | Out-Null }
            'experimental' { $badges.Add('Experimental') | Out-Null }
            'manual' { $badges.Add('Manual') | Out-Null }
            default { if (-not [string]::IsNullOrWhiteSpace($riskLevel)) { $badges.Add($riskLevel) | Out-Null } }
        }
        if ($requiresGpu) { $badges.Add('Requer GPU') | Out-Null }
        if ($requiresInteractiveLogin) { $badges.Add('Requer login') | Out-Null }
        $componentProbePaths = @()
        if ($componentDef.PSObject.Properties.Name -contains 'ProbePaths') { $componentProbePaths = @($componentDef.ProbePaths) }
        $componentWingetId = if ($componentDef.PSObject.Properties.Name -contains 'Id') { [string]$componentDef.Id } else { '' }
        $componentStatus = Get-BootstrapItemStatus -Kind 'app' -Id ([string]$componentDef.Name) -ProbePaths $componentProbePaths -WingetId $componentWingetId -Cache $statusCache
        [ordered]@{
            name = $componentDef.Name
            description = $componentDef.Description
            dependsOn = @($componentDef.DependsOn)
            optional = [bool]$componentDef.Optional
            kind = [string]$componentDef.Kind
            stage = Get-BootstrapComponentStage -ComponentDef $componentDef
            valueReason = if ($componentDef.PSObject.Properties.Name -contains 'ValueReason') { [string]$componentDef.ValueReason } else { [string]$componentDef.Description }
            riskLevel = $riskLevel
            manualReason = $manualReason
            requiresGpu = $requiresGpu
            requiresInteractiveLogin = $requiresInteractiveLogin
            officialSource = $officialSource
            badges = @($badges.ToArray())
            status = $componentStatus
            statusColor = (Get-BootstrapItemStatusColor -Status $componentStatus)
            reversibility = Get-BootstrapComponentReversibility -ComponentDef $componentDef
        }
    }

    $rotationEventsPath = ''
    try {
        $dataRoot = Get-BootstrapDataRoot
        if (-not [string]::IsNullOrWhiteSpace($dataRoot)) {
            $rotationEventsPath = Join-Path $dataRoot 'rotation-events.jsonl'
        }
    } catch {
        $rotationEventsPath = ''
    }
    $rotationScheduleState = Get-BootstrapRotationScheduledTaskState

    return [ordered]@{
        schemaVersion = '1.6.0'
        capabilities = [ordered]@{
            doctor = $true
            supportBundle = $true
            repairPlan = $true
            publicBetaProfile = ($profiles.Contains('public-beta'))
            steamDeckDoctor = $true
            githubCliAgentAuth = $true
            aionuiIntegration = $true
            aiConfigSync = $true
            aiProxySuite = $true
            aiMemory = $true
            launcherDiagnostics = $true
            guidedCliMenu = $true
            runTimeline = $true
            itemStatusSignals = $true
        }
        profileNames = @($profiles.Keys)
        componentNames = @($components.Keys)
        hostHealthModes = @(Get-BootstrapHostHealthModes)
        appTuningModes = @(Get-BootstrapAppTuningModes)
        defaults = [ordered]@{
            workspaceRoot = Get-BootstrapDefaultWorkspaceRoot
            steamDeckVersion = 'Auto'
            uiLanguage = 'pt-BR'
            legacyHostHealth = 'off'
            modernHostHealth = 'off'
            legacyAppTuning = 'off'
            modernAppTuning = 'off'
        }
        profiles = @($profileEntries)
        components = @($componentEntries)
        itemStatusLegend = @(Get-BootstrapItemStatusInfo)
        appTuningCatalog = Get-BootstrapAppTuningCatalog
        apiCatalog = $apiCatalog
        apiInventory = Get-BootstrapApiInventory -SecretsData $secretsData
        appCatalog = $appCatalog
        steamDeckSettingsDefaults = Get-BootstrapSteamDeckSettingsDefaults -ResolvedSteamDeckVersion 'lcd'
        secretsRotation = [ordered]@{
            schedule = if ($rotationScheduleState.exists) { 'unknown' } else { 'none' }
            scheduleOptions = @('none', 'daily', 'weekly')
            scheduledTaskName = [string]$rotationScheduleState.taskName
            scheduledTaskExists = [bool]$rotationScheduleState.exists
            eventsPath = $rotationEventsPath
            staleHoursDefault = 24
        }
    }
}

function Get-BootstrapAdminReasons {
    param(
        [Parameter(Mandatory = $true)]$Resolution,
        [Parameter(Mandatory = $true)][string]$ResolvedHostHealthMode,
        [bool]$UsesSteamDeckFlow = $false,
        [AllowNull()]$AppTuningPlan = $null
    )

    $reasons = New-Object System.Collections.Generic.List[string]
    $resolvedComponents = @($Resolution.ResolvedComponents)

    if ($resolvedComponents -contains 'wsl-core') {
        $reasons.Add('WSL e recursos opcionais do Windows podem exigir elevacao.')
    }

    if ($resolvedComponents -contains 'visual-studio-community') {
        $reasons.Add('Visual Studio Community normalmente pede elevacao para instalacao completa.')
    }

    if ($resolvedComponents -contains 'steamdeck-driver-pack') {
        $reasons.Add('Drivers especificos do Steam Deck exigem instalacao elevada.')
    }

    if ($resolvedComponents -contains 'steamdeck-amd-nebula-driver') {
        $reasons.Add('Instalar o driver AMD Nebula Hybrid Edition exige elevacao (setup de driver de GPU + tuning de registro).')
    }

    if (@('steamdeck-storage-driver', 'steamdeck-wifi-driver', 'steamdeck-bluetooth-driver') | Where-Object { $resolvedComponents -contains $_ }) {
        $reasons.Add('Instalar drivers oficiais do Steam Deck (SD/Wi-Fi/Bluetooth) via pnputil exige elevacao.')
    }

    if ($UsesSteamDeckFlow -and ($resolvedComponents -contains 'steamdeck-tools-runtime')) {
        $reasons.Add('Executar como admin instala o Steam Deck Tools em Program Files; sem elevacao ele vai para o perfil do usuario.')
    }

    if ($ResolvedHostHealthMode -in @('conservador', 'equilibrado', 'agressivo')) {
        $reasons.Add('HostHealth usa elevacao para limpeza completa de C:\Windows\Temp, DISM e Windows.old.')
    }

    if ($ResolvedHostHealthMode -in @('equilibrado', 'agressivo')) {
        $reasons.Add('HostHealth pode precisar de elevacao para desabilitar tarefas agendadas do sistema.')
    }

    if ($ResolvedHostHealthMode -eq 'agressivo') {
        $reasons.Add('HostHealth agressivo ajusta servicos e requer elevacao.')
    }

    if ($AppTuningPlan) {
        foreach ($item in @($AppTuningPlan.items | Where-Object { [bool]$_.requiresAdmin })) {
            $reasons.Add(("AppTuning item {0} pode exigir elevacao para {1}." -f [string]$item.id, (@($item.actions) -join ', ')))
        }
    }

    if (Test-BootstrapIsDualBoot) {
        $reasons.Add('Gestao e leitura de entradas UEFI/Dual Boot requer elevacao.')
    }

    return @($reasons.ToArray())
}

function Test-BootstrapComponentDependsOn {
    param(
        [Parameter(Mandatory = $true)][string]$ComponentName,
        [Parameter(Mandatory = $true)][string]$DependencyName,
        [Parameter(Mandatory = $true)]$Catalog,
        [hashtable]$Visited = @{}
    )

    if ($Visited.ContainsKey($ComponentName)) { return $false }
    $Visited[$ComponentName] = $true

    $componentDef = $Catalog[$ComponentName]
    if (-not $componentDef) { return $false }
    if ($componentDef.DependsOn -contains $DependencyName) { return $true }

    foreach ($dependency in $componentDef.DependsOn) {
        if (Test-BootstrapComponentDependsOn -ComponentName $dependency -DependencyName $DependencyName -Catalog $Catalog -Visited $Visited) {
            return $true
        }
    }

    return $false
}

function Get-BootstrapComponentReversibility {
    param([Parameter(Mandatory = $true)]$ComponentDef)

    $kind = [string]$ComponentDef.Kind
    $changeTypes = @()
    $reversible = 'manual'
    $notes = 'Validacao manual recomendada antes de reverter.'

    switch ($kind) {
        'alias' { $reversible = 'none'; $notes = 'Alias nao altera o sistema.' }
        'manual-required' { $reversible = 'none'; $changeTypes = @('manual'); $notes = 'Dependencia manual fora do controle do bootstrap.' }
        'system-core' { $reversible = 'partial'; $changeTypes = @('package', 'path'); $notes = 'App Installer/winget e PATH podem exigir reparo manual.' }
        'winget' { $reversible = 'manual'; $changeTypes = @('package'); $notes = 'Pacote pode ser removido via winget uninstall, mas rollback automatico nao remove apps por padrao.' }
        'chocolatey' { $reversible = 'manual'; $changeTypes = @('package'); $notes = 'Pacote pode ser removido via choco uninstall quando instalado pelo bootstrap.' }
        'npm' { $reversible = 'partial'; $changeTypes = @('package'); $notes = 'Pacote global pode ser removido via npm uninstall -g quando instalado pelo bootstrap.' }
        'uvtool' { $reversible = 'partial'; $changeTypes = @('package'); $notes = 'Ferramenta uv pode exigir remocao manual ou uv tool uninstall.' }
        'repo-clone' { $reversible = 'partial'; $changeTypes = @('clone', 'directory'); $notes = 'Diretorio clonado pode ser removido se foi criado pelo bootstrap.' }
        'workspace' { $reversible = 'partial'; $changeTypes = @('directory'); $notes = 'Diretorios vazios criados pelo bootstrap podem ser removidos.' }
        'web-app-shortcut' { $reversible = 'full'; $changeTypes = @('shortcut', 'file'); $notes = 'Atalhos criados pelo bootstrap podem ser removidos.' }
        'steamdeck-shell-menu' { $reversible = 'partial'; $changeTypes = @('registry', 'file'); $notes = 'Shell menu possui remocao especifica; valide backups.' }
        'bootstrap-secrets' { $reversible = 'partial'; $changeTypes = @('file', 'env'); $notes = 'Backups/manifests permitem restauracao parcial; segredos devem ser validados manualmente.' }
        'bootstrap-mcps' { $reversible = 'partial'; $changeTypes = @('file'); $notes = 'Configs com backup podem ser restauradas; entradas externas exigem validacao.' }
        'vscode-extensions' { $reversible = 'manual'; $changeTypes = @('package', 'file'); $notes = 'Extensoes podem ser removidas manualmente pelo editor/CLI.' }
        'vscode-extension' { $reversible = 'manual'; $changeTypes = @('package', 'file'); $notes = 'Extensao pode ser removida manualmente pelo editor/CLI.' }
        default {
            if ($kind -match 'settings|config|automation|agent-skills') {
                $reversible = 'partial'
                $changeTypes = @('file')
                $notes = 'Arquivos/configs devem usar backups quando disponiveis.'
            } elseif ($kind -match 'git|node|python|wsl|steamdeck|codex|claude|opencode|openclaw|goose|hermes|sevenzip') {
                $reversible = 'partial'
                $changeTypes = @('package', 'file', 'path')
                $notes = 'Instalacao automatizada com reversao parcial; remocao de apps e runtimes e manual por padrao.'
            } else {
                $changeTypes = @('unknown')
            }
        }
    }

    return [ordered]@{
        reversible = $reversible
        changeTypes = @($changeTypes)
        rollbackNotes = $notes
    }
}

function Resolve-BootstrapComponents {
    param(
        [string[]]$SelectedProfiles,
        [string[]]$SelectedComponents,
        [string[]]$ExcludedComponents
    )

    $profiles = Get-BootstrapProfileCatalog
    $components = Get-BootstrapComponentCatalog
    $requested = New-Object System.Collections.Generic.List[string]
    $expandedProfiles = New-Object System.Collections.Generic.List[string]

    function Add-ProfileItems {
        param([string]$ProfileName, [hashtable]$Stack)

        if (-not $profiles.Contains($ProfileName)) {
            throw "Perfil desconhecido: $ProfileName"
        }
        if ($Stack.ContainsKey($ProfileName)) {
            throw "Ciclo de perfis detectado: $ProfileName"
        }

        $Stack[$ProfileName] = $true
        if (-not $expandedProfiles.Contains($ProfileName)) {
            $expandedProfiles.Add($ProfileName)
        }

        foreach ($item in $profiles[$ProfileName].Items) {
            if ($profiles.Contains($item)) {
                Add-ProfileItems -ProfileName $item -Stack $Stack
            } else {
                if (-not $components.Contains($item)) {
                    throw "Item desconhecido no perfil ${ProfileName}: $item"
                }
                $requested.Add($item)
            }
        }

        $Stack.Remove($ProfileName) | Out-Null
    }

    foreach ($profileName in (Normalize-BootstrapNames -Names $SelectedProfiles)) {
        Add-ProfileItems -ProfileName $profileName -Stack @{}
    }

    foreach ($componentName in (Normalize-BootstrapNames -Names $SelectedComponents)) {
        if (-not $components.Contains($componentName)) {
            throw "Componente desconhecido: $componentName"
        }
        $requested.Add($componentName)
    }

    $resolved = New-Object System.Collections.Generic.List[string]
    $visiting = @{}
    $visited = @{}

    function Add-ResolvedComponent {
        param([string]$ComponentName)

        if ($visited.ContainsKey($ComponentName)) { return }
        if ($visiting.ContainsKey($ComponentName)) {
            throw "Ciclo de dependências detectado em: $ComponentName"
        }

        $componentDef = $components[$ComponentName]
        if (-not $componentDef) {
            throw "Componente desconhecido: $ComponentName"
        }

        $visiting[$ComponentName] = $true
        foreach ($dependency in $componentDef.DependsOn) {
            Add-ResolvedComponent -ComponentName $dependency
        }
        $visiting.Remove($ComponentName) | Out-Null
        $visited[$ComponentName] = $true

        if (-not $resolved.Contains($ComponentName)) {
            $resolved.Add($ComponentName)
        }
    }

    foreach ($componentName in $requested) {
        Add-ResolvedComponent -ComponentName $componentName
    }

    $normalizedExcludes = @(Normalize-BootstrapNames -Names $ExcludedComponents)
    foreach ($excludedName in $normalizedExcludes) {
        if (-not $components.Contains($excludedName)) {
            throw "Componente excluído desconhecido: $excludedName"
        }
        if (-not $resolved.Contains($excludedName)) { continue }

        if (-not $components[$excludedName].Optional) {
            throw "O componente $excludedName é obrigatório e nao pode ser excluído."
        }

        foreach ($resolvedName in @($resolved.ToArray())) {
            if ($resolvedName -eq $excludedName) { continue }
            if (Test-BootstrapComponentDependsOn -ComponentName $resolvedName -DependencyName $excludedName -Catalog $components) {
                throw "Não é possível excluir $excludedName porque ele é dependência obrigatória de $resolvedName."
            }
        }

        $resolved.Remove($excludedName) | Out-Null
    }

    return [pscustomobject]@{
        ExpandedProfiles = @($expandedProfiles.ToArray())
        RequestedComponents = @($requested.ToArray())
        ExcludedComponents = @($normalizedExcludes)
        ResolvedComponents = @($resolved.ToArray())
    }
}

function Invoke-BootstrapInteractiveSelection {
    Write-Host 'Selecione um modo de execução:'
    Write-Host '1. Recommended'
    Write-Host '2. Legacy'
    Write-Host '3. Full'
    Write-Host '4. Custom by profile'
    Write-Host '5. Custom by component'

    $choice = (Read-Host 'Opção').Trim()
    switch ($choice) {
        '1' { $selectedProfiles = @('recommended'); $selectedComponents = @(); $selectedExcludes = @() }
        '2' { $selectedProfiles = @('legacy'); $selectedComponents = @(); $selectedExcludes = @() }
        '3' { $selectedProfiles = @('full'); $selectedComponents = @(); $selectedExcludes = @() }
        '4' {
            $profilesInput = Read-Host 'Perfis (separados por vírgula)'
            $excludeInput = Read-Host 'Exclusões opcionais (ou Enter para nenhuma)'
            $selectedProfiles = Normalize-BootstrapNames -Names @($profilesInput)
            $selectedComponents = @()
            $selectedExcludes = Normalize-BootstrapNames -Names @($excludeInput)
        }
        '5' {
            $componentsInput = Read-Host 'Componentes (separados por vírgula)'
            $excludeInput = Read-Host 'Exclusões opcionais (ou Enter para nenhuma)'
            $selectedProfiles = @()
            $selectedComponents = Normalize-BootstrapNames -Names @($componentsInput)
            $selectedExcludes = Normalize-BootstrapNames -Names @($excludeInput)
        }
        default {
            throw "Opção interativa inválida: $choice"
        }
    }

    Write-Host 'Selecione o modo HostHealth:'
    Write-Host '1. conservador (recomendado)'
    Write-Host '2. equilibrado'
    Write-Host '3. agressivo'
    Write-Host '4. off'
    $hostHealthChoice = (Read-Host 'HostHealth').Trim()
    $selectedHostHealth = switch ($hostHealthChoice) {
        '1' { 'conservador' }
        '2' { 'equilibrado' }
        '3' { 'agressivo' }
        '4' { 'off' }
        default { throw "Modo HostHealth interativo inválido: $hostHealthChoice" }
    }

    return [pscustomobject]@{
        Profiles = @($selectedProfiles)
        Components = @($selectedComponents)
        Excludes = @($selectedExcludes)
        HostHealth = $selectedHostHealth
        AppTuning = ''
        AppTuningCategories = @()
        AppTuningItems = @()
        ExcludedAppTuningItems = @()
    }
}

function Get-BootstrapSelection {
    $profiles = @(Normalize-BootstrapNames -Names $Profile)
    $components = @(Normalize-BootstrapNames -Names $Component)
    $appComponents = @(Resolve-BootstrapAppComponents -Names $App)
    foreach ($componentName in @($appComponents)) {
        if (@($components) -notcontains $componentName) {
            $components += @($componentName)
        }
    }
    $excludes = @(Normalize-BootstrapNames -Names $Exclude)
    $selectedHostHealth = Normalize-BootstrapHostHealthMode -Mode $HostHealth
    $selectedAppTuning = Normalize-BootstrapAppTuningMode -Mode $AppTuning

    if ($Interactive -and -not $NonInteractive -and $profiles.Count -eq 0 -and $components.Count -eq 0) {
        return Invoke-BootstrapInteractiveSelection
    }

    $hasExplicitAppTuningSelection = (
        -not [string]::IsNullOrWhiteSpace($selectedAppTuning) -or
        @($AppTuningCategory).Count -gt 0 -or
        @($AppTuningItem).Count -gt 0 -or
        @($ExcludeAppTuningItem).Count -gt 0
    )

    if ($profiles.Count -eq 0 -and $components.Count -eq 0 -and -not $hasExplicitAppTuningSelection) {
        $profiles = @('legacy')
    }

    return [pscustomobject]@{
        Profiles = $profiles
        Components = $components
        Excludes = $excludes
        HostHealth = $selectedHostHealth
        AppTuning = $selectedAppTuning
        AppTuningCategories = @(Normalize-BootstrapNames -Names $AppTuningCategory)
        AppTuningItems = @(Normalize-BootstrapNames -Names $AppTuningItem)
        ExcludedAppTuningItems = @(Normalize-BootstrapNames -Names $ExcludeAppTuningItem)
    }
}

function Resolve-BootstrapCloneBaseDir {
    param(
        [string]$ExplicitCloneBaseDir,
        [Parameter(Mandatory = $true)][string]$ResolvedWorkspaceRoot,
        [string[]]$ResolvedComponents
    )

    $ExplicitCloneBaseDir = Normalize-BootstrapPathSegment -Value $ExplicitCloneBaseDir
    $ResolvedWorkspaceRoot = Normalize-BootstrapPathSegment -Value $ResolvedWorkspaceRoot

    if (-not [string]::IsNullOrWhiteSpace($ExplicitCloneBaseDir)) {
        return $ExplicitCloneBaseDir
    }

    $preferredProjectsDir = Join-Path -Path $ResolvedWorkspaceRoot -ChildPath 'DevProjetos'
    $driveRoot = $null
    try { $driveRoot = Split-Path -Path $ResolvedWorkspaceRoot -Qualifier } catch { $driveRoot = $null }

    if (($ResolvedComponents -contains 'workspace-layout') -and $driveRoot -and (Test-Path $driveRoot)) {
        return $preferredProjectsDir
    }

    if (-not [string]::IsNullOrWhiteSpace($PSScriptRoot)) {
        return $PSScriptRoot
    }

    return (Get-Location).Path
}

function New-BootstrapState {
    param(
        [Parameter(Mandatory = $true)][object]$Selection,
        [Parameter(Mandatory = $true)][string]$ResolvedWorkspaceRoot,
        [Parameter(Mandatory = $true)][string]$ResolvedCloneBaseDir,
        [string]$RequestedSteamDeckVersion = 'Auto',
        [string]$ResolvedSteamDeckVersion = 'lcd',
        [string]$HostHealthMode = 'off',
        [string]$AppTuningMode = 'off',
        [bool]$UsesSteamDeckFlow = $false,
        [bool]$IsDryRun = $false
    )

    $wsRoot = Normalize-BootstrapPathSegment -Value $ResolvedWorkspaceRoot
    $cloneRoot = Normalize-BootstrapPathSegment -Value $ResolvedCloneBaseDir

    return @{
        Selection = $Selection
        DryRun = $IsDryRun
        RunId = $script:RunId
        WorkspaceRoot = $wsRoot
        CloneBaseDir = $cloneRoot
        EnableClaudeCodeProjectMcps = $false
        RequestedSteamDeckVersion = $RequestedSteamDeckVersion
        ResolvedSteamDeckVersion = $ResolvedSteamDeckVersion
        HostHealthMode = $HostHealthMode
        AppTuningMode = $AppTuningMode
        UsesSteamDeckFlow = $UsesSteamDeckFlow
        HostHealthReportRoot = $null
        AppTuningReportRoot = $null
        SteamDeckSettingsPath = $null
        SteamDeckAutomationRoot = $null
        SteamDeckToolsRoot = $null
        Winget = $null
        GitInfo = $null
        NodeInfo = $null
        DotNetInfo = $null
        PythonReady = $false
        SecretsPath = $null
        SecretsSummary = $null
        McpStatePath = $null
        McpSummary = $null
        VsCodeExtensionsPath = $null
        VsCodeExtensionsSummary = $null
        PreflightDone = $false
        PreflightSummary = $null
        CurrentComponent = ''
        ComponentStatus = @{}
        SkippedComponents = New-Object System.Collections.Generic.List[object]
        Warnings = New-Object System.Collections.Generic.List[string]
        LastError = $null
        ChangeManifestPath = ''
        Completed = @{}
        ManualRequirements = New-Object System.Collections.Generic.List[object]
        Changes = New-Object System.Collections.Generic.List[object]
        AppTuningResults = New-Object System.Collections.Generic.List[object]
        HostHealthResults = New-Object System.Collections.Generic.List[object]
    }
}

function Ensure-BootstrapSystemCore {
    param([hashtable]$State)
    if ($State.Winget) { return }
    Ensure-ProxyEnvFromWinHttp
    $State.Winget = Ensure-Winget
    Refresh-SessionPath
}

function Ensure-BootstrapGitCore {
    param([hashtable]$State)
    if ($State.GitInfo) { return }
    Ensure-BootstrapSystemCore -State $State
    $State.GitInfo = Ensure-GitAndBash -WingetPath $State.Winget
    Refresh-SessionPath
}

function Ensure-BootstrapNodeCore {
    param([hashtable]$State)
    if ($State.NodeInfo) { return }
    Ensure-BootstrapSystemCore -State $State
    $State.NodeInfo = Ensure-NodeAndNpm -WingetPath $State.Winget
    Refresh-SessionPath
}

function Ensure-BootstrapDotNetCore {
    param([hashtable]$State)
    if ($State.DotNetInfo) { return }
    Ensure-BootstrapSystemCore -State $State
    $State.DotNetInfo = Ensure-DotNetSdkAndVerify -WingetPath $State.Winget
    Refresh-SessionPath
}

function Ensure-BootstrapPythonCore {
    param([hashtable]$State)
    if ($State.PythonReady) { return }
    Ensure-BootstrapSystemCore -State $State
    Ensure-Python -WingetPath $State.Winget
    $null = Ensure-Uv
    $State.PythonReady = $true
    Refresh-SessionPath
}

function Ensure-7ZipOnPath {
    $sevenZipDir = $null
    try { $sevenZipDir = Join-Path $env:ProgramFiles '7-Zip' } catch { $sevenZipDir = $null }
    if ($sevenZipDir -and (Test-Path $sevenZipDir)) {
        Ensure-PathUserContains -Dir $sevenZipDir
        Refresh-SessionPath
    }
}

function Get-BootstrapGitGlobalConfigPath {
    $userHome = Get-BootstrapUserHomePath
    if ([string]::IsNullOrWhiteSpace($userHome)) { return '' }
    return (Join-Path $userHome '.gitconfig')
}

function Test-BootstrapGitLfsConfigured {
    param([Parameter(Mandatory = $true)][string]$GitExe)

    $gitConfigPath = Get-BootstrapGitGlobalConfigPath
    if (-not [string]::IsNullOrWhiteSpace($gitConfigPath) -and (Test-Path -LiteralPath $gitConfigPath)) {
        try {
            $raw = [string]([System.IO.File]::ReadAllText($gitConfigPath))
            if (($raw -match '(?im)^\s*clean\s*=\s*git-lfs clean -- %f\s*$') -and
                ($raw -match '(?im)^\s*process\s*=\s*git-lfs filter-process\s*$') -and
                ($raw -match '(?im)^\s*required\s*=\s*true\s*$')) {
                return $true
            }
        } catch {
        }
    }

    $probe = Invoke-NativeCaptureWithLog -Exe $GitExe -Args @('config', '--global', '--list') -TimeoutMs 60000
    $text = [string]($probe.stdout + "`n" + $probe.stderr)
    if (($probe.exitCode -eq 0) -and ($text -match '(?im)filter\.lfs\.clean=git-lfs clean -- %f')) {
        return $true
    }
    return $false
}

function Test-BootstrapGitConfigLockErrorText {
    param([string]$Text = '')

    if ([string]::IsNullOrWhiteSpace($Text)) { return $false }
    return ($Text -match '(?im)could not lock config file' -or
        $Text -match '(?im)permission denied' -or
        $Text -match '(?im)access is denied')
}

function Ensure-GitLfs {
    param([hashtable]$State)
    Ensure-BootstrapGitCore -State $State
    Ensure-BootstrapSystemCore -State $State
    Ensure-WingetPackage -WingetPath $State.Winget -Id 'GitHub.GitLFS' -DisplayName 'Git LFS' -ProbePaths @("$env:ProgramFiles\Git LFS\git-lfs.exe", "$env:ProgramFiles\Git\mingw64\bin\git-lfs.exe", "${env:ProgramFiles(x86)}\Git LFS\git-lfs.exe")
    if (Test-BootstrapGitLfsConfigured -GitExe $State.GitInfo.Git) {
        Write-Log 'Git LFS ja configurado no escopo global do usuario.'
        return
    }

    $installArgs = @('lfs', 'install', '--skip-repo')
    $attempt = 0
    $maxAttempts = 3
    $delaySeconds = 2
    $lastExitCode = -1
    $lastText = ''

    while ($attempt -lt $maxAttempts) {
        $attempt++
        if ($attempt -gt 1) {
            Write-Log ("Repetindo configuracao do Git LFS (tentativa {0}/{1})" -f $attempt, $maxAttempts) 'WARN'
        }

        $result = Invoke-NativeCaptureWithLog -Exe $State.GitInfo.Git -Args $installArgs -TimeoutMs 120000
        $lastExitCode = [int]$result.exitCode
        $lastText = [string]($result.stdout + "`n" + $result.stderr)

        if ($lastExitCode -eq 0) { break }

        if ((Test-BootstrapGitConfigLockErrorText -Text $lastText) -and ($attempt -lt $maxAttempts)) {
            Write-Log ("Git LFS: ~/.gitconfig indisponivel no momento. Nova tentativa em {0}s." -f $delaySeconds) 'WARN'
            Start-Sleep -Seconds $delaySeconds
            $delaySeconds = [Math]::Min(10, ($delaySeconds * 2))
            continue
        }

        break
    }

    if (($lastExitCode -ne 0) -and (Test-BootstrapGitLfsConfigured -GitExe $State.GitInfo.Git)) {
        Write-Log ("Git LFS ja estava configurado apesar de exit={0}. Seguindo." -f $lastExitCode) 'WARN'
        return
    }

    if ($lastExitCode -ne 0) {
        if (Test-BootstrapGitConfigLockErrorText -Text $lastText) {
            $gitConfigPath = Get-BootstrapGitGlobalConfigPath
            $message = "Nao foi possivel configurar Git LFS no perfil do usuario: ~/.gitconfig esta bloqueado ou sem permissao ({0}). Feche apps Git/editores, ajuste permissoes e execute novamente." -f $gitConfigPath
            throw (New-BootstrapBlockedException -Message $message -Kind 'git-global-config-locked' -Action 'close-git-tools-or-fix-permissions' -Reasons @('gitconfig-lock-or-permission', $gitConfigPath))
        }
        throw "Falha ao executar git lfs install --skip-repo (exit=$lastExitCode)."
    }

    if (-not (Test-BootstrapGitLfsConfigured -GitExe $State.GitInfo.Git)) {
        throw 'Git LFS executou sem erro, mas a configuracao global nao foi confirmada.'
    }

    Write-Log 'Git LFS configurado no escopo global do usuario.'
}

function Repair-BootstrapWslCorruption {
    param(
        [Parameter(Mandatory = $true)][string]$WslExe,
        [hashtable]$State
    )

    if (-not (Test-IsAdmin)) {
        Write-Log 'WSL: reparo requer privilégios de administrador. Pulando.' 'WARN'
        return $false
    }

    Write-Log 'WSL: instalação parece corrompida. Tentando reparar...'

    try { $null = Invoke-NativeCaptureWithLog -Exe $WslExe -Args @('--shutdown') -TimeoutMs 30000 -InputText "`n" } catch { }

    $featureResults = @()
    $featureResults += @(Ensure-WindowsOptionalFeatureEnabled -FeatureName 'Microsoft-Windows-Subsystem-Linux' -DisplayName 'Windows Subsystem for Linux')
    $featureResults += @(Ensure-WindowsOptionalFeatureEnabled -FeatureName 'VirtualMachinePlatform' -DisplayName 'Virtual Machine Platform')
    if (Test-BootstrapWindowsFeatureResultsRequireReboot -Results $featureResults) {
        throw (New-BootstrapWslRestartRequiredException -FeatureResults $featureResults)
    }

    $pkg = $null
    try {
        $pkg = Get-AppxPackage -Name 'MicrosoftCorporationII.WindowsSubsystemForLinux' -ErrorAction SilentlyContinue | Select-Object -First 1
    } catch { $pkg = $null }

    if ($pkg -and -not [string]::IsNullOrWhiteSpace([string]$pkg.InstallLocation)) {
        $manifest = Join-Path ([string]$pkg.InstallLocation) 'AppxManifest.xml'
        if (Test-Path $manifest) {
            try {
                Add-AppxPackage -DisableDevelopmentMode -Register $manifest -ErrorAction Stop | Out-Null
                Write-Log "WSL: AppX re-registrado: $manifest"
            } catch {
                Write-Log ("WSL: falha ao re-registrar AppX: " + $_.Exception.Message) 'WARN'
            }
        }
    } else {
        if ($State -and $State.Winget) {
            try {
                $installExit = Invoke-NativeWithRetry -Exe $State.Winget -Args @('install','--id','Microsoft.WSL','-e','--source','winget','--accept-package-agreements','--accept-source-agreements','--disable-interactivity') -OperationName 'reinstalacao WSL via winget' -TimeoutMs 900000 -NonRetryableExitCodes @()
                if (($installExit -ne 0) -and ($installExit -ne 3010)) {
                    Write-Log ("WSL: winget install Microsoft.WSL retornou exit={0}; tentando upgrade." -f $installExit) 'WARN'
                    $upgradeExit = Invoke-NativeWithRetry -Exe $State.Winget -Args @('upgrade','--id','Microsoft.WSL','-e','--source','winget','--accept-package-agreements','--accept-source-agreements','--disable-interactivity') -OperationName 'upgrade WSL via winget' -TimeoutMs 900000 -NonRetryableExitCodes @()
                    if (($upgradeExit -ne 0) -and ($upgradeExit -ne 3010)) {
                        Write-Log ("WSL: winget upgrade Microsoft.WSL retornou exit={0}." -f $upgradeExit) 'WARN'
                    }
                }
            } catch {
                Write-Log ("WSL: falha ao instalar Microsoft.WSL via winget: " + $_.Exception.Message) 'WARN'
            }
        } else {
            Write-Log 'WSL: pacote AppX nao encontrado e winget indisponível para reinstalar.' 'WARN'
        }
    }

    $repairUpdate = Invoke-NativeCaptureWithLog -Exe $WslExe -Args @('--update') -TimeoutMs 900000 -InputText "`n"
    $repairText = [string]($repairUpdate.stdout + "`n" + $repairUpdate.stderr)
    if (Test-WslCorruptionText -Text $repairText) {
        Write-Log 'WSL: ainda corrompido apos reparo automático. Recomendo reiniciar e tentar novamente.' 'WARN'
        return $false
    }

    if (($repairUpdate.exitCode -ne 0) -and ($repairUpdate.exitCode -ne 3010)) {
        Write-Log "WSL: reparo executou, mas wsl --update retornou exit=$($repairUpdate.exitCode)." 'WARN'
    }

    $defaultVersionExitCode = Invoke-NativeWithLog -Exe $WslExe -Args @('--set-default-version', '2')
    if (($defaultVersionExitCode -ne 0) -and ($defaultVersionExitCode -ne 3010)) {
        Write-Log "WSL: falha ao executar wsl --set-default-version 2 (exit=$defaultVersionExitCode)." 'WARN'
    }

    Write-Log 'WSL: reparo finalizado.'
    return $true
}

function Ensure-WslCore {
    param([hashtable]$State)
    Ensure-BootstrapSystemCore -State $State

    $wslExe = Resolve-CommandPath -Name 'wsl.exe'
    if (-not $wslExe) {
        $candidate = Join-Path $env:SystemRoot 'System32\wsl.exe'
        if (Test-Path $candidate) { $wslExe = $candidate }
    }
    if ($wslExe) {
        try {
            $null = Assert-BootstrapWslNotCorrupt -WslExe $wslExe
        } catch {
            if (-not (Test-IsAdmin)) { throw }
            $repaired = Repair-BootstrapWslCorruption -WslExe $wslExe -State $State
            if (-not $repaired) { throw }
        }
    }

    if (-not (Test-IsAdmin)) {
        Write-Log 'WSL core requer privilégios de administrador para habilitar recursos do Windows. Pulando.' 'WARN'
        return
    }

    $featureResults = @()
    $featureResults += @(Ensure-WindowsOptionalFeatureEnabled -FeatureName 'Microsoft-Windows-Subsystem-Linux' -DisplayName 'Windows Subsystem for Linux')
    $featureResults += @(Ensure-WindowsOptionalFeatureEnabled -FeatureName 'VirtualMachinePlatform' -DisplayName 'Virtual Machine Platform')
    if (Test-BootstrapWindowsFeatureResultsRequireReboot -Results $featureResults) {
        throw (New-BootstrapWslRestartRequiredException -FeatureResults $featureResults)
    }

    $wslExe = Resolve-CommandPath -Name 'wsl.exe'
    if (-not $wslExe) {
        $candidate = Join-Path $env:SystemRoot 'System32\wsl.exe'
        if (Test-Path $candidate) { $wslExe = $candidate }
    }
    if (-not $wslExe) {
        Write-Log 'wsl.exe nao encontrado apos habilitar os recursos do Windows.' 'WARN'
        return
    }

    $distros = ''
    try { $distros = (& $wslExe -l -q 2>&1 | Out-String) } catch { $distros = '' }
    if ($distros -notmatch '(?im)^ubuntu\s*$') {
        $installExitCode = Invoke-NativeWithLog -Exe $wslExe -Args @('--install', '-d', 'Ubuntu')
        if (($installExitCode -ne 0) -and ($installExitCode -ne 3010)) {
            Write-Log "Falha ao executar wsl --install -d Ubuntu (exit=$installExitCode)." 'WARN'
        }
    } else {
        Write-Log 'Ubuntu já está listado no WSL.'
    }

    $updateResult = Invoke-NativeCaptureWithLog -Exe $wslExe -Args @('--update') -TimeoutMs 900000 -InputText "`n"
    $updateText = [string]($updateResult.stdout + "`n" + $updateResult.stderr)
    if (Test-WslCorruptionText -Text $updateText) {
        $null = Repair-BootstrapWslCorruption -WslExe $wslExe -State $State
    } elseif (($updateResult.exitCode -ne 0) -and ($updateResult.exitCode -ne 3010)) {
        Write-Log "Falha ao executar wsl --update (exit=$($updateResult.exitCode))." 'WARN'
    } elseif ($updateResult.timedOut) {
        Write-Log 'wsl --update excedeu timeout e foi encerrado. Docker/WSL podem falhar; recomendo reiniciar e tentar de novo.' 'WARN'
    }

    $defaultVersionExitCode = Invoke-NativeWithLog -Exe $wslExe -Args @('--set-default-version', '2')
    if (($defaultVersionExitCode -ne 0) -and ($defaultVersionExitCode -ne 3010)) {
        Write-Log "Falha ao executar wsl --set-default-version 2 (exit=$defaultVersionExitCode)." 'WARN'
    }
}

function Ensure-WorkspaceLayout {
    param([hashtable]$State)
    $workspaceRoot = Normalize-BootstrapPathSegment -Value $State.WorkspaceRoot
    $driveRoot = $null
    try { $driveRoot = Split-Path -Path $workspaceRoot -Qualifier } catch { $driveRoot = $null }
    if ($driveRoot -and (-not (Test-Path $driveRoot))) {
        Write-Log "Workspace root indisponível: $workspaceRoot. Mantendo CloneBaseDir atual: $($State.CloneBaseDir)" 'WARN'
        return
    }

    $paths = @(
        $workspaceRoot,
        (Join-Path -Path $workspaceRoot -ChildPath 'DevKits'),
        (Join-Path -Path $workspaceRoot -ChildPath 'DevProjetos'),
        (Join-Path -Path (Join-Path -Path $workspaceRoot -ChildPath 'DevProjetos') -ChildPath 'Docker')
    )

    foreach ($path in $paths) {
        $null = New-Item -Path $path -ItemType Directory -Force
        Write-Log "Workspace garantido: $path"
    }
}

function Ensure-BootstrapSteamDeckToolsRuntime {
    param([hashtable]$State)

    Ensure-BootstrapSystemCore -State $State

    $installRoot = if (Test-IsAdmin) {
        Join-Path $env:ProgramFiles 'SteamDeckTools'
    } else {
        Join-Path $env:LOCALAPPDATA 'Programs\SteamDeckTools'
    }

    $probePaths = @(
        (Join-Path $installRoot 'PowerControl.exe'),
        (Join-Path $installRoot 'SteamController.exe'),
        (Join-Path $installRoot 'FanControl.exe'),
        (Join-Path $installRoot 'PerformanceOverlay.exe')
    )

    $existingProbeCount = @($probePaths | Where-Object { Test-Path $_ }).Count
    if ($existingProbeCount -eq @($probePaths).Count) {
        $State.SteamDeckToolsRoot = $installRoot
        Write-Log "Steam Deck Tools ja encontrado em $installRoot"
        return
    }
    if ($existingProbeCount -gt 0) {
        Write-Log "Steam Deck Tools parcial em $installRoot; reinstalando pacote portable para completar componentes." 'WARN'
    }

    $downloadUrl = 'https://github.com/ayufan/steam-deck-tools/releases/download/0.7.3/SteamDeckTools-0.7.3-portable.zip'
    $zipPath = Join-Path $env:TEMP ("steamdecktools_{0}.zip" -f ([Guid]::NewGuid().ToString('N')))
    $extractDir = Join-Path $env:TEMP ("steamdecktools_extract_{0}" -f ([Guid]::NewGuid().ToString('N')))

    try {
        Write-Log "Baixando Steam Deck Tools portable: $downloadUrl"
        Invoke-WebRequestWithRetry -Uri $downloadUrl -OutFile $zipPath -OperationName 'download do Steam Deck Tools'
        $null = New-Item -Path $extractDir -ItemType Directory -Force
        Expand-Archive -Path $zipPath -DestinationPath $extractDir -Force
        $null = New-Item -Path $installRoot -ItemType Directory -Force
        Copy-Item -Path (Join-Path $extractDir '*') -Destination $installRoot -Recurse -Force
    } finally {
        if (Test-Path $zipPath) { Remove-Item -LiteralPath $zipPath -Force -ErrorAction SilentlyContinue }
        if (Test-Path $extractDir) { Remove-Item -LiteralPath $extractDir -Recurse -Force -ErrorAction SilentlyContinue }
    }

    $requiredProbes = @('PowerControl.exe', 'SteamController.exe', 'FanControl.exe', 'PerformanceOverlay.exe')
    $missingProbes = @($requiredProbes | Where-Object { -not (Test-Path (Join-Path $installRoot $_)) })
    if (@($missingProbes).Count -gt 0) {
        throw "Steam Deck Tools baixado, mas executaveis esperados nao foram encontrados em ${installRoot}: $(@($missingProbes) -join ', ')."
    }

    $State.SteamDeckToolsRoot = $installRoot
    Write-Log "Steam Deck Tools instalado em $installRoot"
}

function Resolve-BootstrapChocolateyPath {
    $commandPath = Resolve-CommandPath -Name 'choco.exe'
    if ($commandPath) { return $commandPath }

    $knownPath = Join-Path $env:ProgramData 'chocolatey\bin\choco.exe'
    if (Test-Path $knownPath) { return $knownPath }

    return $null
}

function Ensure-BootstrapChocolateyCore {
    param([hashtable]$State)

    $existing = Resolve-BootstrapChocolateyPath
    if ($existing) { return $existing }

    if (-not (Test-IsAdmin)) {
        throw 'Chocolatey ausente. Instale/rode o bootstrap como Administrador para provisionar componentes Chocolatey como GlosSI.'
    }

    Ensure-BootstrapSystemCore -State $State

    $installerUrl = 'https://community.chocolatey.org/install.ps1'
    $installerPath = Join-Path $env:TEMP ("chocolatey_install_{0}.ps1" -f ([guid]::NewGuid().ToString('N')))
    try {
        Write-Log "Baixando instalador oficial do Chocolatey: $installerUrl"
        Invoke-WebRequestWithRetry -Uri $installerUrl -OutFile $installerPath -OperationName 'download do Chocolatey'

        $powershellExe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
        if (-not (Test-Path $powershellExe)) { $powershellExe = 'powershell.exe' }
        $exitCode = Invoke-NativeWithLog -Exe $powershellExe -Args @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $installerPath)
        if ($exitCode -ne 0) {
            throw "Instalador do Chocolatey retornou exit code $exitCode."
        }
    } finally {
        if (Test-Path $installerPath) { Remove-Item -LiteralPath $installerPath -Force -ErrorAction SilentlyContinue }
    }

    Refresh-SessionPath
    $resolved = Resolve-BootstrapChocolateyPath
    if (-not $resolved) {
        throw 'Chocolatey instalado, mas choco.exe nao foi encontrado no PATH nem em ProgramData.'
    }
    return $resolved
}

function Ensure-ChocolateyPackage {
    param(
        [Parameter(Mandatory = $true)][string]$ChocoPath,
        [Parameter(Mandatory = $true)][string]$Package,
        [Parameter(Mandatory = $true)][string]$DisplayName,
        [string[]]$ProbePaths = @()
    )

    if ([string]::IsNullOrWhiteSpace($Package)) {
        throw "Pacote Chocolatey ausente para $DisplayName."
    }

    Write-Log "Garantindo pacote Chocolatey: $DisplayName ($Package)"
    $exitCode = Invoke-NativeWithLog -Exe $ChocoPath -Args @('upgrade', $Package, '-y', '--no-progress', '--accept-license')
    if (@(0, 3010, 1641) -notcontains $exitCode) {
        throw "Falha ao instalar/atualizar $DisplayName via Chocolatey (exit=$exitCode)."
    }
    if (@($ProbePaths).Count -gt 0 -and -not (Test-WingetProbePathsOnDisk -ProbePaths $ProbePaths)) {
        $message = "Instalacao Chocolatey de {0} retornou sucesso, mas nenhum ProbePaths apareceu em disco. Repare ou reinstale o pacote." -f $DisplayName
        throw (New-BootstrapBlockedException -Message $message -Kind 'chocolatey-post-install-unverified' -Action 'inspect-or-reinstall' -Reasons @('probe-path-missing', $Package))
    }
}

function Test-BootstrapSecretsManifestPath {
    param([string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    try {
        return ((Split-Path -Path $Path -Leaf) -ieq 'bootstrap-secrets.json')
    } catch {
        return $false
    }
}

function Test-BootstrapSecretsProtectedEnvelope {
    param([AllowNull()]$Value)

    $map = ConvertTo-BootstrapHashtable -InputObject $Value
    if (-not ($map -is [hashtable])) { return $false }
    if (-not $map.ContainsKey('protectedData')) { return $false }
    $metadata = if ($map.ContainsKey('metadata')) { ConvertTo-BootstrapHashtable -InputObject $map['metadata'] } else { @{} }
    if (-not ($metadata -is [hashtable])) { return $false }
    return ([string]$metadata['protection'] -eq 'dpapi-current-user')
}

function Protect-BootstrapDpapiText {
    param([Parameter(Mandatory = $true)][string]$Text)

    try {
        Add-Type -AssemblyName System.Security -ErrorAction SilentlyContinue
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($Text)
        $protected = [System.Security.Cryptography.ProtectedData]::Protect($bytes, $null, [System.Security.Cryptography.DataProtectionScope]::CurrentUser)
        return [Convert]::ToBase64String($protected)
    } catch {
        throw "DPAPI indisponivel para proteger bootstrap-secrets.json: $($_.Exception.Message)"
    }
}

function Unprotect-BootstrapDpapiText {
    param([Parameter(Mandatory = $true)][string]$ProtectedData)

    try {
        Add-Type -AssemblyName System.Security -ErrorAction SilentlyContinue
        $bytes = [Convert]::FromBase64String($ProtectedData)
        $plain = [System.Security.Cryptography.ProtectedData]::Unprotect($bytes, $null, [System.Security.Cryptography.DataProtectionScope]::CurrentUser)
        return [System.Text.Encoding]::UTF8.GetString($plain)
    } catch {
        throw "DPAPI indisponivel ou envelope de segredos corrompido: $($_.Exception.Message)"
    }
}

function Protect-BootstrapSecretsManifestData {
    param([Parameter(Mandatory = $true)]$Data)

    if (Test-BootstrapSecretsProtectedEnvelope -Value $Data) { return $Data }
    $plainJson = [string]((ConvertTo-BootstrapObjectGraph -InputObject $Data) | ConvertTo-Json -Depth 30)
    return [ordered]@{
        '$schema' = 'https://bootstrap.local/schemas/bootstrap-secrets-protected.schema.json'
        metadata = [ordered]@{
            version = 3
            protection = 'dpapi-current-user'
            protectedAt = (Get-Date).ToString('o')
        }
        protectedData = (Protect-BootstrapDpapiText -Text $plainJson)
    }
}

function Unprotect-BootstrapSecretsManifestData {
    param([Parameter(Mandatory = $true)]$Envelope)

    $map = ConvertTo-BootstrapHashtable -InputObject $Envelope
    if (-not (Test-BootstrapSecretsProtectedEnvelope -Value $map)) { return $map }
    $plainJson = Unprotect-BootstrapDpapiText -ProtectedData ([string]$map['protectedData'])
    return (ConvertTo-BootstrapHashtable -InputObject (ConvertFrom-BootstrapJsonText -Text $plainJson))
}

function Write-BootstrapJsonFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [AllowNull()][Parameter(Mandatory = $true)]$Value
    )

    $parent = Split-Path -Path $Path -Parent
    if ($parent) {
        $null = New-Item -Path $parent -ItemType Directory -Force
    }

    $valueToWrite = $Value
    if (Test-BootstrapSecretsManifestPath -Path $Path) {
        $valueToWrite = Protect-BootstrapSecretsManifestData -Data $Value
    }

    if ($null -eq $valueToWrite) {
        $json = 'null'
    } else {
        $json = [string]((ConvertTo-BootstrapObjectGraph -InputObject $valueToWrite) | ConvertTo-Json -Depth 12)
    }
    $utf8 = New-Object System.Text.UTF8Encoding($false)

    Write-BootstrapAtomicText -Path $Path -Content $json -Encoding $utf8
}

function Write-BootstrapAtomicText {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$Content,
        [System.Text.Encoding]$Encoding
    )
    if (-not $Encoding) { $Encoding = New-Object System.Text.UTF8Encoding($false) }

    # Stage to a sibling .tmp then move into place atomically. Same volume so a
    # rename is metadata-only on NTFS. Falls back to direct write if the temp
    # path can't be created (e.g., long-path issues, restricted parent).
    $tmpPath = $Path + '.bttmp'
    try {
        [System.IO.File]::WriteAllText($tmpPath, $Content, $Encoding)
    } catch {
        # If we couldn't even stage, write directly and bail (best-effort).
        [System.IO.File]::WriteAllText($Path, $Content, $Encoding)
        return
    }

    try {
        if (Test-Path -LiteralPath $Path) {
            try {
                [System.IO.File]::Replace($tmpPath, $Path, $null)
            } catch {
                # Replace fails on some volumes (network shares, ReFS without resilver,
                # cross-device, paths with reserved chars). Fall back to delete+move.
                Remove-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
                Move-Item -LiteralPath $tmpPath -Destination $Path -Force -ErrorAction Stop
            }
        } else {
            Move-Item -LiteralPath $tmpPath -Destination $Path -Force -ErrorAction Stop
        }
    } catch {
        if (Test-Path -LiteralPath $tmpPath) {
            try { Remove-Item -LiteralPath $tmpPath -Force -ErrorAction SilentlyContinue } catch { }
        }
        # Last resort: write the content directly so callers don't lose data.
        try { [System.IO.File]::WriteAllText($Path, $Content, $Encoding) } catch { throw }
    }
}

function Remove-BootstrapJsonComments {
    param([Parameter(Mandatory = $true)][string]$Text)

    $builder = New-Object System.Text.StringBuilder
    $inString = $false
    $escape = $false
    $inLineComment = $false
    $inBlockComment = $false

    for ($index = 0; $index -lt $Text.Length; $index++) {
        $char = $Text[$index]
        $next = if (($index + 1) -lt $Text.Length) { $Text[$index + 1] } else { [char]0 }

        if ($inLineComment) {
            if ($char -eq "`r" -or $char -eq "`n") {
                $inLineComment = $false
                [void]$builder.Append($char)
            }
            continue
        }

        if ($inBlockComment) {
            if ($char -eq '*' -and $next -eq '/') {
                $inBlockComment = $false
                $index += 1
            }
            continue
        }

        if ($inString) {
            [void]$builder.Append($char)
            if ($escape) {
                $escape = $false
            } elseif ($char -eq '\') {
                $escape = $true
            } elseif ($char -eq '"') {
                $inString = $false
            }
            continue
        }

        if ($char -eq '"') {
            $inString = $true
            [void]$builder.Append($char)
            continue
        }

        if ($char -eq '/' -and $next -eq '/') {
            $inLineComment = $true
            $index += 1
            continue
        }

        if ($char -eq '/' -and $next -eq '*') {
            $inBlockComment = $true
            $index += 1
            continue
        }

        [void]$builder.Append($char)
    }

    return $builder.ToString()
}

function Remove-BootstrapJsonTrailingCommas {
    param([Parameter(Mandatory = $true)][string]$Text)

    $builder = New-Object System.Text.StringBuilder
    $inString = $false
    $escape = $false

    for ($index = 0; $index -lt $Text.Length; $index++) {
        $char = $Text[$index]

        if ($inString) {
            [void]$builder.Append($char)
            if ($escape) {
                $escape = $false
            } elseif ($char -eq '\') {
                $escape = $true
            } elseif ($char -eq '"') {
                $inString = $false
            }
            continue
        }

        if ($char -eq '"') {
            $inString = $true
            [void]$builder.Append($char)
            continue
        }

        if ($char -eq ',') {
            $lookAhead = $index + 1
            while ($lookAhead -lt $Text.Length -and [char]::IsWhiteSpace($Text[$lookAhead])) {
                $lookAhead += 1
            }

            if ($lookAhead -lt $Text.Length -and $Text[$lookAhead] -in @('}', ']')) {
                continue
            }
        }

        [void]$builder.Append($char)
    }

    return $builder.ToString()
}

function ConvertFrom-BootstrapJsonText {
    param([Parameter(Mandatory = $true)][string]$Text)

    $withoutComments = Remove-BootstrapJsonComments -Text $Text
    $sanitized = Remove-BootstrapJsonTrailingCommas -Text $withoutComments
    return ($sanitized | ConvertFrom-Json -ErrorAction Stop)
}

function Read-BootstrapJsonFile {
    param([Parameter(Mandatory = $true)][string]$Path)

    if (-not (Test-Path $Path)) {
        return $null
    }

    $parsed = ConvertTo-BootstrapHashtable -InputObject (ConvertFrom-BootstrapJsonText -Text (Get-Content -Path $Path -Raw -Encoding utf8))
    if (Test-BootstrapSecretsManifestPath -Path $Path -and (Test-BootstrapSecretsProtectedEnvelope -Value $parsed)) {
        return (Unprotect-BootstrapSecretsManifestData -Envelope $parsed)
    }
    return $parsed
}

