function Get-BootstrapAiInstallRoot {
    param([string]$InstallRoot)
    if (-not [string]::IsNullOrWhiteSpace($InstallRoot)) {
        return [System.IO.Path]::GetFullPath($InstallRoot)
    }
    $tempRoot = $env:TEMP
    if ([string]::IsNullOrWhiteSpace($tempRoot)) { $tempRoot = $env:TMPDIR }
    if ([string]::IsNullOrWhiteSpace($tempRoot)) { $tempRoot = $env:TMP }
    if ([string]::IsNullOrWhiteSpace($tempRoot)) { $tempRoot = [System.IO.Path]::GetTempPath() }
    if ([string]::IsNullOrWhiteSpace($tempRoot)) { $tempRoot = (Get-Location).Path }
    $base = if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        Join-Path $env:LOCALAPPDATA 'PhaseZero'
    } else {
        Join-Path $tempRoot 'PhaseZero'
    }
    return (Join-Path $base 'ai-tools')
}

function Get-BootstrapAiToolManifestPath {
    param([Parameter(Mandatory = $true)][string]$InstallRoot)
    return (Join-Path (Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot) 'phasezero-ai-tools.json')
}

function New-BootstrapAiToolManifest {
    return @{
        schemaVersion = 1
        managedBy     = 'PhaseZero'
        tools         = @{}
        pathsAdded    = @{}
    }
}

function Read-BootstrapAiToolManifest {
    param([Parameter(Mandatory = $true)][string]$InstallRoot)
    $path = Get-BootstrapAiToolManifestPath -InstallRoot $InstallRoot
    if (-not (Test-Path -LiteralPath $path)) { return (New-BootstrapAiToolManifest) }
    try {
        $data = ConvertTo-BootstrapHashtable -InputObject (Read-BootstrapJsonFile -Path $path)
        if (-not $data.ContainsKey('tools') -or -not ($data['tools'] -is [hashtable])) { $data['tools'] = @{} }
        if (-not $data.ContainsKey('pathsAdded') -or -not ($data['pathsAdded'] -is [hashtable])) { $data['pathsAdded'] = @{} }
        return $data
    } catch {
        try { Backup-BootstrapFile -Path $path | Out-Null } catch { }
        return (New-BootstrapAiToolManifest)
    }
}

function Write-BootstrapAiToolManifest {
    param(
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [Parameter(Mandatory = $true)][hashtable]$Manifest
    )
    $path = Get-BootstrapAiToolManifestPath -InstallRoot $InstallRoot
    $parent = Split-Path -Path $path -Parent
    if (-not [string]::IsNullOrWhiteSpace($parent)) {
        [void][System.IO.Directory]::CreateDirectory($parent)
    }
    Write-BootstrapJsonFile -Path $path -Value $Manifest
    return $path
}

function Resolve-BootstrapAiProbePath {
    param([Parameter(Mandatory = $true)][string]$Path)
    $expanded = [Environment]::ExpandEnvironmentVariables($Path)
    if ($expanded -match '\$env:([A-Za-z_][A-Za-z0-9_]*)') {
        $expanded = [regex]::Replace($expanded, '\$env:([A-Za-z_][A-Za-z0-9_]*)', {
            param($match)
            $value = [Environment]::GetEnvironmentVariable($match.Groups[1].Value)
            if ($null -eq $value) { '' } else { $value }
        })
    }
    return $expanded
}

function Get-BootstrapNpmCommandForAiTools {
    foreach ($name in @('npm.cmd','npm.exe','npm')) {
        try {
            $cmd = Get-Command $name -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($cmd -and -not [string]::IsNullOrWhiteSpace([string]$cmd.Source)) {
                return [string]$cmd.Source
            }
        } catch {
        }
    }
    $fallback = Get-NpmCmd
    if ($fallback) { return $fallback }
    throw 'npm nao encontrado. Instale Node.js LTS e reexecute.'
}

function Get-BootstrapNpxCommandForAiTools {
    param([AllowEmptyString()][string]$NpmCommand = '')

    $candidates = New-Object System.Collections.Generic.List[string]
    if (-not [string]::IsNullOrWhiteSpace($NpmCommand)) {
        if ($NpmCommand -match '(?i)npm(\.cmd|\.exe|\.ps1)?$') {
            $candidates.Add(($NpmCommand -replace '(?i)npm(\.cmd|\.exe|\.ps1)?$', 'npx$1')) | Out-Null
        }
        $npmDir = Split-Path -Path $NpmCommand -Parent
        if (-not [string]::IsNullOrWhiteSpace($npmDir)) {
            foreach ($name in @('npx.cmd','npx.exe','npx.ps1','npx')) {
                $candidates.Add((Join-Path $npmDir $name)) | Out-Null
            }
        }
    }
    foreach ($candidate in @($candidates.ToArray())) {
        if (-not [string]::IsNullOrWhiteSpace($candidate) -and (Test-Path -LiteralPath $candidate)) {
            return $candidate
        }
    }
    foreach ($name in @('npx.cmd','npx.exe','npx')) {
        try {
            $cmd = Get-Command $name -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($cmd -and -not [string]::IsNullOrWhiteSpace([string]$cmd.Source)) {
                return [string]$cmd.Source
            }
        } catch {
        }
    }
    return 'npx.cmd'
}

function Get-BootstrapAiNpmPrefix {
    param([Parameter(Mandatory = $true)][string]$InstallRoot)
    return (Join-Path (Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot) 'npm-prefix')
}

function Get-BootstrapAiBinDir {
    param([Parameter(Mandatory = $true)][string]$InstallRoot)
    return (Join-Path (Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot) 'bin')
}

function Resolve-BootstrapAiToolCommandPath {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [string]$InstallRoot = ''
    )

    $names = @(Get-BootstrapNonEmptyStringArray -Values @($CatalogEntry['CommandNames']))
    $roots = New-Object System.Collections.Generic.List[string]
    if (-not [string]::IsNullOrWhiteSpace($InstallRoot)) {
        $resolvedRoot = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
        $roots.Add((Get-BootstrapAiNpmPrefix -InstallRoot $resolvedRoot)) | Out-Null
        $roots.Add((Get-BootstrapAiBinDir -InstallRoot $resolvedRoot)) | Out-Null
    }

    if ($CatalogEntry.Contains('ProbePaths')) {
        foreach ($probe in @($CatalogEntry['ProbePaths'])) {
            $path = Resolve-BootstrapAiProbePath -Path ([string]$probe)
            if (-not [string]::IsNullOrWhiteSpace($path) -and (Test-Path -LiteralPath $path)) { return $path }
        }
    }

    foreach ($root in @($roots.ToArray())) {
        if ([string]::IsNullOrWhiteSpace($root)) { continue }
        foreach ($name in @($names)) {
            foreach ($suffix in @('.cmd', '.exe', '.ps1', '')) {
                $candidate = Join-Path $root ($name + $suffix)
                if (Test-Path -LiteralPath $candidate) { return $candidate }
            }
        }
    }

    foreach ($name in @($names)) {
        try {
            $resolved = Resolve-CommandPath -Name $name
            if ($resolved) { return $resolved }
        } catch {
        }
        try {
            $cmd = Get-Command $name -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($cmd -and -not [string]::IsNullOrWhiteSpace([string]$cmd.Source)) { return [string]$cmd.Source }
        } catch {
        }
    }
    return ''
}

function Invoke-BootstrapAiNativeCommand {
    param(
        [Parameter(Mandatory = $true)][string]$Exe,
        [string[]]$Args = @(),
        [string]$WorkingDirectory = '',
        [int]$TimeoutMs = 120000
    )

    $runExe = $Exe
    $runArgs = @($Args)
    if ($Exe -match '\.ps1$') {
        $psHost = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
        if (-not (Test-Path -LiteralPath $psHost)) { $psHost = 'powershell.exe' }
        $runExe = $psHost
        $runArgs = @('-NoProfile','-ExecutionPolicy','Bypass','-File',$Exe) + @($Args)
    } elseif ($Exe -match '\.(cmd|bat)$') {
        $cmdHost = Join-Path $env:SystemRoot 'System32\cmd.exe'
        if (-not (Test-Path -LiteralPath $cmdHost)) { $cmdHost = 'cmd.exe' }
        $runExe = $cmdHost
        $runArgs = @('/d','/c',$Exe) + @($Args)
    }

    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $runExe
    $psi.Arguments = (($runArgs | ForEach-Object {
        $v = [string]$_
        if ($v -match '[\s"]') { '"' + ($v -replace '"', '\"') + '"' } else { $v }
    }) -join ' ')
    if (-not [string]::IsNullOrWhiteSpace($WorkingDirectory)) {
        $psi.WorkingDirectory = $WorkingDirectory
    }
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $psi.RedirectStandardInput = $true
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    # Forca git nao-interativo. Sem isto, o Git Credential Manager pode subir como processo
    # neto e ficar esperando input (mesmo em repo publico), segurando o pipe redirecionado e
    # travando a leitura indefinidamente. Inofensivo para npm/go/node.
    try {
        $psi.EnvironmentVariables['GIT_TERMINAL_PROMPT'] = '0'
        $psi.EnvironmentVariables['GCM_INTERACTIVE'] = 'never'
        $psi.EnvironmentVariables['GIT_ASKPASS'] = ''
    } catch { }

    $proc = New-Object System.Diagnostics.Process
    $proc.StartInfo = $psi
    [void]$proc.Start()
    $procId = $proc.Id
    # Fecha stdin imediatamente: qualquer prompt nativo recebe EOF e falha rapido em vez de
    # bloquear esperando entrada que nunca chega num run nao-interativo.
    try { $proc.StandardInput.Close() } catch { }
    $stdoutTask = $proc.StandardOutput.ReadToEndAsync()
    $stderrTask = $proc.StandardError.ReadToEndAsync()
    $timedOut = -not $proc.WaitForExit($TimeoutMs)
    if ($timedOut) {
        # Derruba a arvore inteira: git/npm geram netos (credential helpers, git-remote-https,
        # daemons de postinstall) que sobrevivem a um Kill() simples e seguram o pipe aberto,
        # fazendo as leituras abaixo travarem para sempre.
        Stop-BootstrapProcessTree -ProcessId $procId
        try { $null = $proc.WaitForExit(5000) } catch { }
    }
    $exitCode = if ($timedOut) { 124 } else { [int]$proc.ExitCode }
    # Leitura com deadline: nunca acessar .Result direto (bloqueia indefinidamente se um neto
    # orfao mantiver a ponta de escrita do pipe). Foi exatamente a causa de um hang de 4h em
    # `git clone` durante o setup de proxies locais.
    $readDeadlineMs = if ($timedOut) { 8000 } else { 20000 }
    $stdout = Get-BootstrapAsyncReadResult -Task $stdoutTask -TimeoutMs $readDeadlineMs
    $stderr = Get-BootstrapAsyncReadResult -Task $stderrTask -TimeoutMs $readDeadlineMs
    try { $proc.Dispose() } catch { }
    $first = (($stdout + "`n" + $stderr) -replace "`0", '' -replace "`r", '' -split "`n" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1)
    return [ordered]@{
        exitCode = $exitCode
        timedOut = $timedOut
        stdout   = $stdout
        stderr   = $stderr
        firstLine = if ($first) { [string]$first } else { '' }
    }
}

function Get-BootstrapCleanNativeText {
    param(
        [AllowNull()][string]$Text,
        [int]$MaxLength = 1200
    )
    if ([string]::IsNullOrWhiteSpace($Text)) { return '' }
    $clean = ([string]$Text) -replace "`0", ''
    $clean = $clean -replace "`r", ' ' -replace "`n", ' '
    $clean = ($clean -replace '\s+', ' ').Trim()
    $clean = $clean -replace '(?i)n.o registrada', 'nao registrada'
    $clean = $clean -replace '(?i)c.digo de erro', 'Codigo de erro'
    $clean = $clean -replace [char]0xFFFD, '?'
    if ($MaxLength -gt 0 -and $clean.Length -gt $MaxLength) {
        return ($clean.Substring(0, $MaxLength - 3) + '...')
    }
    return $clean
}

function Get-BootstrapAiToolVersion {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$CommandPath
    )
    $args = @(Get-BootstrapNonEmptyStringArray -Values @($CatalogEntry['VersionArgs']))
    if ($args.Count -eq 0) { $args = @('--version') }
    try {
        $result = Invoke-BootstrapAiNativeCommand -Exe $CommandPath -Args $args -TimeoutMs 30000
        if (-not [string]::IsNullOrWhiteSpace([string]$result['firstLine'])) { return [string]$result['firstLine'] }
    } catch {
    }
    return ''
}

function Test-BootstrapHostIsWindows {
    return ([string]$env:OS -eq 'Windows_NT')
}

function Get-BootstrapAionUiArchitecture {
    $arch = [string]$env:PROCESSOR_ARCHITECTURE
    if ($arch -match '(?i)arm64') { return 'arm64' }
    return 'x64'
}

