function Get-BootstrapAiUsagebarNativeConfigPathSet {
    $paths = New-Object System.Collections.Generic.List[string]
    $userHome = Get-BootstrapUserHomePath
    if (-not [string]::IsNullOrWhiteSpace($userHome)) {
        $paths.Add((Join-Path $userHome '.config\ai-usagebar\config.toml')) | Out-Null
    }
    if (-not [string]::IsNullOrWhiteSpace($env:APPDATA)) {
        $paths.Add((Join-Path $env:APPDATA 'ai-usagebar\config\config.toml')) | Out-Null
    }
    return @($paths.ToArray())
}

function Get-BootstrapAiUsagebarWindowsBinDir {
    $userHome = Get-BootstrapUserHomePath
    if (-not [string]::IsNullOrWhiteSpace($userHome)) {
        return (Join-Path $userHome '.local\bin')
    }
    return (Get-BootstrapAiBinDir -InstallRoot (Get-BootstrapAiInstallRoot -InstallRoot ''))
}

function Write-BootstrapAiUsagebarWindowsShim {
    param(
        [Parameter(Mandatory = $true)][string]$BinDir,
        [Parameter(Mandatory = $true)][string]$CommandName,
        [Parameter(Mandatory = $true)][string]$TargetExe
    )

    [void][System.IO.Directory]::CreateDirectory($BinDir)
    $shimPath = Join-Path $BinDir ("{0}.cmd" -f $CommandName)
    $targetName = Split-Path -Leaf $TargetExe
    $content = @(
        '@echo off',
        'setlocal',
        'if "%HOME%"=="" set "HOME=%USERPROFILE%"',
        ('"%~dp0{0}" %*' -f $targetName)
    ) -join "`r`n"
    [System.IO.File]::WriteAllText($shimPath, ($content + "`r`n"), [System.Text.Encoding]::ASCII)
    return $shimPath
}

function Invoke-BootstrapAiUsagebarCommandProbe {
    param([string]$CommandPath = '')

    $path = $CommandPath
    if ([string]::IsNullOrWhiteSpace($path)) {
        $catalog = Get-BootstrapAiToolCatalog
        if ($catalog.Contains('ai-usagebar')) {
            $path = Resolve-BootstrapAiToolCommandPath -CatalogEntry $catalog['ai-usagebar'] -InstallRoot (Get-BootstrapAiInstallRoot -InstallRoot '')
        }
    }
    if ([string]::IsNullOrWhiteSpace($path)) {
        return [ordered]@{ ok = $false; status = 'missing'; path = ''; version = ''; message = 'ai-usagebar nao encontrado.' }
    }

    try {
        $result = Invoke-BootstrapAiNativeCommand -Exe $path -Args @('--help') -TimeoutMs 30000
        $detail = Get-BootstrapCleanNativeText -Text (([string]$result['stdout']) + ' ' + ([string]$result['stderr'])) -MaxLength 500
        if ([int]$result['exitCode'] -eq 0) {
            $version = [string]$result['firstLine']
            if ([string]::IsNullOrWhiteSpace($version)) { $version = 'ai-usagebar' }
            return [ordered]@{ ok = $true; status = 'healthy'; path = $path; version = $version; message = $detail }
        }
        if ($detail -match '(?i)Controle de Aplicativo|Application Control|blocked|bloque') {
            return [ordered]@{ ok = $false; status = 'blocked'; path = $path; version = ''; message = $detail }
        }
        return [ordered]@{ ok = $false; status = 'error'; path = $path; version = ''; message = $detail }
    } catch {
        $detail = Get-BootstrapCleanNativeText -Text $_.Exception.Message -MaxLength 500
        $status = if ($detail -match '(?i)Controle de Aplicativo|Application Control|blocked|bloque') { 'blocked' } else { 'error' }
        return [ordered]@{ ok = $false; status = $status; path = $path; version = ''; message = $detail }
    }
}

function Write-BootstrapAiUsagebarConfigFile {
    param([Parameter(Mandatory = $true)][string]$Path)
    $parent = Split-Path -Path $Path -Parent
    if (-not [string]::IsNullOrWhiteSpace($parent)) {
        [void][System.IO.Directory]::CreateDirectory($parent)
    }
    [System.IO.File]::WriteAllText($Path, (Get-BootstrapAiUsagebarConfigText), [System.Text.UTF8Encoding]::new($false))
    return $Path
}

function Test-BootstrapAiUsagebarNativeConfigured {
    foreach ($path in @(Get-BootstrapAiUsagebarNativeConfigPathSet)) {
        if (-not [string]::IsNullOrWhiteSpace($path) -and (Test-Path -LiteralPath $path)) { return $true }
    }
    return $false
}

function Get-BootstrapAiUsagebarConfigBase64 {
    return [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes((Get-BootstrapAiUsagebarConfigText)))
}

function Test-BootstrapAiUsagebarWslConfigured {
    try {
        $wslExe = Get-BootstrapWslExePath
        if ([string]::IsNullOrWhiteSpace($wslExe)) { return $false }
        $null = Assert-BootstrapWslNotCorrupt -WslExe $wslExe -TimeoutMs 5000
        $result = Invoke-BootstrapAiNativeCommand -Exe $wslExe -Args @('bash','-lc','test -x "$HOME/.local/bin/ai-usagebar" && test -f "$HOME/.config/ai-usagebar/config.toml"') -TimeoutMs 10000
        return ([int]$result['exitCode'] -eq 0)
    } catch {
        Write-Verbose ("ai-usagebar WSL config probe skipped: {0}" -f (Get-BootstrapCleanNativeText -Text $_.Exception.Message -MaxLength 300))
        return $false
    }
}

function Get-BootstrapAiUsagebarWslVersion {
    try {
        $wslExe = Get-BootstrapWslExePath
        if ([string]::IsNullOrWhiteSpace($wslExe)) { return '' }
        $null = Assert-BootstrapWslNotCorrupt -WslExe $wslExe -TimeoutMs 5000
        $result = Invoke-BootstrapAiNativeCommand -Exe $wslExe -Args @('bash','-lc','"$HOME/.local/bin/ai-usagebar" --help | head -n 1') -TimeoutMs 10000
        if ([int]$result['exitCode'] -eq 0 -and -not [string]::IsNullOrWhiteSpace([string]$result['firstLine'])) {
            return [string]$result['firstLine']
        }
    } catch {
        Write-Verbose ("ai-usagebar WSL version probe skipped: {0}" -f (Get-BootstrapCleanNativeText -Text $_.Exception.Message -MaxLength 300))
    }
    return ''
}

function Test-BootstrapAiToolConfigured {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [string]$ProjectRoot = ''
    )

    switch ($ToolName) {
        'hermes-agent' {
            try {
                $wslExe = Get-BootstrapWslExePath
                if ([string]::IsNullOrWhiteSpace($wslExe)) { return $false }
                $null = Assert-BootstrapWslNotCorrupt -WslExe $wslExe -TimeoutMs 5000
                $result = Invoke-BootstrapAiNativeCommand -Exe $wslExe -Args @('bash','-lc','test -d "$HOME/.hermes/hermes-agent" && command -v hermes >/dev/null 2>&1') -TimeoutMs 15000
                return ([int]$result['exitCode'] -eq 0)
            } catch {
                return $false
            }
        }
        'claude-code' {
            return (-not [string]::IsNullOrWhiteSpace($env:ANTHROPIC_API_KEY))
        }
        'opencode' {
            $userHome = Get-BootstrapUserHomePath
            $paths = @()
            if ($userHome) { $paths += (Join-Path $userHome '.config\opencode\opencode.json') }
            if ($env:APPDATA) { $paths += (Join-Path $env:APPDATA 'OpenCode\opencode.json') }
            return [bool](@($paths | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1))
        }
        'openclaw' {
            $userHome = Get-BootstrapUserHomePath
            if (-not $userHome) { return $false }
            return (Test-Path -LiteralPath (Join-Path $userHome '.openclaw'))
        }
        'rtk' {
            $root = if ([string]::IsNullOrWhiteSpace($ProjectRoot)) { (Get-Location).Path } else { $ProjectRoot }
            return ((Test-Path -LiteralPath (Join-Path $root '.rtk')) -or (Test-Path -LiteralPath (Join-Path $root 'rtk.toml')))
        }
        'antigravity-workflows' {
            return (Test-BootstrapAntigravityWorkflows -ProjectRoot $ProjectRoot)
        }
        'ai-usagebar' {
            $probe = Invoke-BootstrapAiUsagebarCommandProbe
            if ([bool]$probe['ok']) {
                return ((Test-BootstrapAiUsagebarNativeConfigured) -or (Test-BootstrapAiUsagebarWslConfigured))
            }
            return (Test-BootstrapAiUsagebarWslConfigured)
        }
        'ai-memory' {
            $doctor = New-BootstrapAiMemoryDoctorReport
            return ([bool]$doctor['installed'] -and ([bool]$doctor['serverReachable'] -or [bool]$doctor['mcpConfigured']))
        }
        'aionui' {
            $doctor = Get-BootstrapAionUiDoctorReport
            return ([bool]$doctor['installed'] -and @($doctor['providersConfigured']).Count -gt 0)
        }
        default { return $false }
    }
}

function Test-BootstrapAntigravityWorkflows {
    param([string]$ProjectRoot = '')
    $root = if ([string]::IsNullOrWhiteSpace($ProjectRoot)) { (Get-Location).Path } else { $ProjectRoot }
    $workflowRoot = Join-Path $root '.antigravity\workflows'
    foreach ($name in @('planning.md','backend.md','frontend.md','tests.md','review.md')) {
        if (-not (Test-Path -LiteralPath (Join-Path $workflowRoot $name))) { return $false }
    }
    return $true
}

function Get-BootstrapAiToolStatusRows {
    param(
        [string]$InstallRoot = '',
        [string]$ProjectRoot = ''
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $catalog = Get-BootstrapAiToolCatalog
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($toolName in @($catalog.Keys)) {
        $entry = $catalog[$toolName]
        $status = 'absent'
        $commandPath = Resolve-BootstrapAiToolCommandPath -CatalogEntry $entry -InstallRoot $root
        $version = ''
        $configured = $false
        if ($toolName -eq 'antigravity-workflows') {
            $configured = Test-BootstrapAntigravityWorkflows -ProjectRoot $ProjectRoot
            $status = if ($configured) { 'configured' } else { 'absent' }
        } elseif ($toolName -eq 'hermes-agent') {
            $configured = Test-BootstrapAiToolConfigured -ToolName $toolName -ProjectRoot $ProjectRoot
            $status = if ($configured) { 'configured' } else { 'absent' }
            if ($configured) {
                try {
                    $wslExe = Get-BootstrapWslExePath
                    $hermesVersion = Invoke-BootstrapAiNativeCommand -Exe $wslExe -Args @('bash','-lc','hermes --version') -TimeoutMs 15000
                    $version = [string]$hermesVersion['firstLine']
                    $commandPath = 'wsl.exe bash -lc hermes'
                } catch {
                    $version = ''
                }
            }
        } elseif ($toolName -eq 'ai-usagebar') {
            $configured = Test-BootstrapAiToolConfigured -ToolName $toolName -ProjectRoot $ProjectRoot
            if (-not [string]::IsNullOrWhiteSpace($commandPath)) {
                $probe = Invoke-BootstrapAiUsagebarCommandProbe -CommandPath $commandPath
                $version = if (-not [string]::IsNullOrWhiteSpace([string]$probe['version'])) { [string]$probe['version'] } else { [string]$entry['ReleaseTag'] }
                if (-not [bool]$probe['ok']) {
                    $status = [string]$probe['status']
                    $configured = $false
                } else {
                    $status = if ($configured) { 'configured' } else { 'installed' }
                }
            } elseif ($configured) {
                $version = Get-BootstrapAiUsagebarWslVersion
                if ([string]::IsNullOrWhiteSpace($version)) { $version = [string]$entry['ReleaseTag'] }
                $commandPath = 'wsl.exe bash -lc ai-usagebar'
                $status = 'configured'
            }
        } elseif ($toolName -eq 'aionui') {
            $doctor = Get-BootstrapAionUiDoctorReport
            $commandPath = [string]$doctor['exePath']
            $version = [string]$doctor['version']
            $configured = (@($doctor['providersConfigured']).Count -gt 0)
            if ([bool]$doctor['installed']) {
                $status = if ($configured) { 'configured' } else { 'installed' }
            } else {
                $status = 'absent'
            }
        } elseif ($toolName -eq 'ai-proxy-suite') {
            $suite = New-BootstrapAiProxySuiteDoctorReport -InstallRoot $InstallRoot
            $configuredCount = [int]$suite['configuredProviders']
            $configured = ([string]$suite['status'] -eq 'ready')
            $status = switch ([string]$suite['status']) {
                'ready' { 'configured'; break }
                'start-required' { 'start-required'; break }
                'degraded' { 'unhealthy'; break }
                'warning' { 'installed'; break }
                default { 'absent' }
            }
            $version = [string]$suite['defaultModel']
            $commandPath = [string]$suite['manifestPath']
        } elseif (Test-BootstrapAiProxyToolName -ToolName $toolName) {
            $proxy = Get-BootstrapAiProxyToolDoctorReport -ToolName $toolName -InstallRoot $InstallRoot
            if ($proxy) {
                $commandPath = [string]$proxy['sourceRoot']
                $configured = [bool]$proxy['configured']
                $status = switch ([string]$proxy['status']) {
                    'configured' { 'configured'; break }
                    'start-required' { 'start-required'; break }
                    'auth-failed' { 'auth-failed'; break }
                    'unhealthy' { 'unhealthy'; break }
                    'warning' { 'installed'; break }
                    default { 'absent' }
                }
                $version = [string]$proxy['repo']
            }
        } elseif ($toolName -eq 'openclaw') {
            $configured = Test-BootstrapAiToolConfigured -ToolName $toolName -ProjectRoot $ProjectRoot
            $status = 'blocked'
        } elseif (-not [string]::IsNullOrWhiteSpace($commandPath)) {
            $version = Get-BootstrapAiToolVersion -CatalogEntry $entry -CommandPath $commandPath
            $configured = Test-BootstrapAiToolConfigured -ToolName $toolName -ProjectRoot $ProjectRoot
            $status = if ($configured) { 'configured' } else { 'installed' }
        } elseif ([string]$entry['InstallSupport'] -match '^manual') {
            $status = 'manual'
        }
        $usageBlocked = ($toolName -eq 'openclaw')
        $blockedReason = if ($usageBlocked) { 'connection-grant-not-enforceable' } else { '' }
        if ($usageBlocked) { $status = 'blocked' }
        $rows.Add([ordered]@{
            tool        = [string]$toolName
            name        = [string]$entry['DisplayName']
            status      = [string]$status
            version     = [string]$version
            configured  = [string]$configured
            commandPath = [string]$commandPath
            docs        = [string]$entry['DocsUrl']
            support     = [string]$entry['InstallSupport']
            message     = [string]$entry['Notes']
            usageBlocked = [bool]$usageBlocked
            blockedReason = [string]$blockedReason
        }) | Out-Null
    }
    return @($rows.ToArray())
}

function New-BootstrapAiToolResult {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [Parameter(Mandatory = $true)][string]$Action,
