    return [ordered]@{
        mode        = 'ai-tools'
        tool        = $ToolName
        action      = $Action
        status      = $Status
        installRoot = (Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot)
        projectRoot = if ([string]::IsNullOrWhiteSpace($ProjectRoot)) { (Get-Location).Path } else { $ProjectRoot }
        message     = $Message
        docs        = $Docs
        commandPath = $CommandPath
        version     = $Version
    }
}

