function New-BootstrapLocalApiKey {
    $bytes = New-Object byte[] 24
    try {
        $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
        $rng.GetBytes($bytes)
        $rng.Dispose()
    } catch {
        $bytes = ([Guid]::NewGuid().ToByteArray() + [Guid]::NewGuid().ToByteArray())
    }
    $token = [Convert]::ToBase64String($bytes)
    $token = $token.TrimEnd('=').Replace('+','').Replace('/','')
    return ('sk-phasezero-local-' + $token)
}

function Read-BootstrapDotEnvFile {
    param([Parameter(Mandatory = $true)][string]$Path)
    $map = [ordered]@{}
    if (-not (Test-Path -LiteralPath $Path)) { return $map }
    foreach ($line in @(Get-Content -LiteralPath $Path -ErrorAction SilentlyContinue)) {
        $text = [string]$line
        if ($text -notmatch '^\s*([^#=\s][^=]*)=(.*)$') { continue }
        $key = $matches[1].Trim()
        $value = [string]$matches[2]
        $value = $value.Trim()
        if (($value.StartsWith('"') -and $value.EndsWith('"')) -or ($value.StartsWith("'") -and $value.EndsWith("'"))) {
            if ($value.Length -ge 2) { $value = $value.Substring(1, $value.Length - 2) }
        }
        if (-not [string]::IsNullOrWhiteSpace($key)) { $map[$key] = $value }
    }
    return $map
}

function ConvertTo-BootstrapDotEnvValue {
    param([AllowNull()][string]$Value)
    $text = [string]$Value
    if ($text -match '[\r\n]') { $text = ($text -replace "[\r\n]+", ',') }
    if ($text -match '\s|#|"' ) {
        return ('"' + ($text -replace '\\', '\\' -replace '"', '\"') + '"')
    }
    return $text
}

function Get-BootstrapProcessOrUserEnvValue {
    param([Parameter(Mandatory = $true)][string[]]$Names)
    foreach ($scope in @('Process','User')) {
        foreach ($name in @($Names)) {
            if ([string]::IsNullOrWhiteSpace([string]$name)) { continue }
            $value = [Environment]::GetEnvironmentVariable([string]$name, $scope)
            if (-not [string]::IsNullOrWhiteSpace($value)) { return [string]$value }
        }
    }
    return ''
}

function Get-BootstrapAiProxyEnvMap {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$EnvPath
    )

    $existing = Read-BootstrapDotEnvFile -Path $EnvPath
    $envMap = [ordered]@{}
    $defaults = ConvertTo-BootstrapHashtable -InputObject $CatalogEntry['EnvDefaults']
    foreach ($key in @($defaults.Keys)) {
        $value = [string]$defaults[$key]
        if ($value -eq '{{generatedLocalApiKey}}') {
            if ($existing.Contains($key) -and -not [string]::IsNullOrWhiteSpace([string]$existing[$key])) {
                $value = [string]$existing[$key]
            } else {
                $value = New-BootstrapLocalApiKey
            }
        }
        $envMap[[string]$key] = $value
    }

    $from = ConvertTo-BootstrapHashtable -InputObject $CatalogEntry['EnvFrom']
    foreach ($targetKey in @($from.Keys)) {
        $names = @($from[$targetKey] | ForEach-Object { [string]$_ } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
        $value = Get-BootstrapProcessOrUserEnvValue -Names $names
        if (-not [string]::IsNullOrWhiteSpace($value)) {
            $envMap[[string]$targetKey] = $value
        } elseif ($existing.Contains($targetKey) -and -not [string]::IsNullOrWhiteSpace([string]$existing[$targetKey])) {
            $envMap[[string]$targetKey] = [string]$existing[$targetKey]
        }
    }

    return $envMap
}

function Write-BootstrapAiProxyEnvFile {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [string]$InstallRoot = ''
    )

    $sourceRoot = Get-BootstrapAiProxySourceRoot -ToolName $ToolName -InstallRoot $InstallRoot
    [void][System.IO.Directory]::CreateDirectory($sourceRoot)
    $envPath = Join-Path $sourceRoot '.env'
    $envMap = Get-BootstrapAiProxyEnvMap -CatalogEntry $CatalogEntry -EnvPath $envPath
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add('# Managed by PhaseZero. Do not commit this file.') | Out-Null
    foreach ($key in @($envMap.Keys)) {
        $lines.Add(('{0}={1}' -f [string]$key, (ConvertTo-BootstrapDotEnvValue -Value ([string]$envMap[$key])))) | Out-Null
    }
    if (Test-Path -LiteralPath $envPath) {
        try { Remove-Item -LiteralPath $envPath -Force -ErrorAction Stop } catch { Write-Verbose $_.Exception.Message }
    }
    $envStream = [System.IO.File]::Open($envPath, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::Read)
    try {
        $envBytes = [System.Text.Encoding]::UTF8.GetBytes((($lines.ToArray()) -join [Environment]::NewLine) + [Environment]::NewLine)
        $envStream.Write($envBytes, 0, $envBytes.Length)
    } finally {
        $envStream.Close()
        $envStream.Dispose()
    }
    try {
        $acl = Get-Acl -LiteralPath $envPath
        $currentIdentity = [System.Security.Principal.WindowsIdentity]::GetCurrent()
        $allowRule = New-Object System.Security.AccessControl.FileSystemAccessRule(
            $currentIdentity.User, 'Read,Write,Modify,FullControl',
            'ContainerInherit,ObjectInherit', 'None', 'Allow')
        $acl.SetAccessRuleProtection($true, $false)
        $acl.AddAccessRule($allowRule)
        $administrators = New-Object System.Security.Principal.SecurityIdentifier('S-1-5-32-544')
        $adminRule = New-Object System.Security.AccessControl.FileSystemAccessRule(
            $administrators, 'FullControl',
            'ContainerInherit,ObjectInherit', 'None', 'Allow')
        $acl.AddAccessRule($adminRule)
        Set-Acl -LiteralPath $envPath -AclObject $acl
    } catch {
        Write-Verbose $_.Exception.Message
    }
    return [ordered]@{
        path = $envPath
        keyCount = [int]$envMap.Count
        secretKeyCount = @($CatalogEntry['SecretKeys']).Count
        hasApiKey = $envMap.Contains('API_KEY')
    }
}

function New-BootstrapAiProxyManifest {
    param([string]$InstallRoot = '')
    $null = $InstallRoot
    $catalog = Get-BootstrapAiProxyCatalog
    $providers = New-Object System.Collections.Generic.List[object]
    foreach ($name in @($catalog.Keys)) {
        $entry = $catalog[$name]
        if ([int]$entry['Port'] -le 0) { continue }
        $providers.Add([ordered]@{
            id = [string]$name
            name = [string]$entry['DisplayName']
            preferred = [bool]$entry['PreferredDefault']
            baseUrl = [string]$entry['BaseUrl']
            defaultModel = [string]$entry['DefaultModel']
            models = @($entry['Models'])
            apiKeySource = '.env:API_KEY'
            loginCommand = [string]$entry['LoginCommand']
            startCommand = [string]$entry['StartCommand']
            requiresWebLoginValidation = [bool]$entry['RequiresWebLoginValidation']
            webValidationKind = [string]$entry['WebValidationKind']
        }) | Out-Null
    }
    return [ordered]@{
        schemaVersion = 1
        generatedAt = (Get-Date).ToString('o')
        defaultProvider = 'kimiproxy'
        defaultBaseUrl = [string]$catalog['kimiproxy']['BaseUrl']
        defaultModel = [string]$catalog['kimiproxy']['DefaultModel']
        providers = @($providers.ToArray())
        targets = @('vsCode','cursor','windsurf','trae','roo','cline','zed','zCode','openCode','hermes','kilo','continue')
        note = 'API keys live only in each proxy .env; this manifest is safe to include in support bundles.'
    }
}

function Write-BootstrapAiProxyManifest {
    param([string]$InstallRoot = '')
    $path = Get-BootstrapAiProxyManifestPath -InstallRoot $InstallRoot
    $parent = Split-Path -Path $path -Parent
    if (-not [string]::IsNullOrWhiteSpace($parent)) { [void][System.IO.Directory]::CreateDirectory($parent) }
    Write-BootstrapJsonFile -Path $path -Value (New-BootstrapAiProxyManifest -InstallRoot $InstallRoot)
    return $path
}

function Get-BootstrapAiProxyEnvVariableName {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [Parameter(Mandatory = $true)][string]$Suffix
    )

    $prefix = ([regex]::Replace($ToolName.ToUpperInvariant(), '[^A-Z0-9]+', '_')).Trim('_')
    return ('{0}_{1}' -f $prefix, $Suffix.ToUpperInvariant())
}

function Get-BootstrapAiProxyProviderId {
    param([Parameter(Mandatory = $true)][string]$ToolName)

    switch ($ToolName) {
        'kimiproxy' { return 'phasezero-kimi' }
        'qwenproxy' { return 'phasezero-qwen' }
        'deepsproxy' { return 'phasezero-deepseek' }
        'mimo-ai-proxy' { return 'phasezero-mimo' }
        'antigravity-openai-adapter' { return 'phasezero-antigravity' }
        default { return ('phasezero-' + (([regex]::Replace($ToolName.ToLowerInvariant(), '[^a-z0-9]+', '-')).Trim('-'))) }
    }
}

function ConvertTo-BootstrapAiProxySafeProviderRecord {
    param([Parameter(Mandatory = $true)][System.Collections.IDictionary]$Record)

    return [ordered]@{
        id = [string]$Record['id']
        providerId = [string]$Record['providerId']
        name = [string]$Record['name']
        configured = [bool]$Record['configured']
        preferred = [bool]$Record['preferred']
        baseUrl = [string]$Record['baseUrl']
        defaultModel = [string]$Record['defaultModel']
        models = @($Record['models'])
        port = [int]$Record['port']
        apiKeyEnvName = [string]$Record['apiKeyEnvName']
        baseUrlEnvName = [string]$Record['baseUrlEnvName']
        modelEnvName = [string]$Record['modelEnvName']
        envPath = [string]$Record['envPath']
        sourceRoot = [string]$Record['sourceRoot']
    }
}

function Get-BootstrapAiProxyProviderRecord {
    param(
        [string]$InstallRoot = '',
        [switch]$EnsureEnv
    )

    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $catalog = Get-BootstrapAiProxyCatalog
    $records = New-Object System.Collections.Generic.List[object]
    foreach ($name in @($catalog.Keys)) {
        $entry = $catalog[$name]
        if ([int]$entry['Port'] -le 0) { continue }
        $sourceRoot = Get-BootstrapAiProxySourceRoot -ToolName ([string]$name) -InstallRoot $root
        $envPath = Join-Path $sourceRoot '.env'
        if ($EnsureEnv) {
            Write-BootstrapAiProxyEnvFile -ToolName ([string]$name) -CatalogEntry $entry -InstallRoot $root | Out-Null
        }

        $envMap = @{}
        if (Test-Path -LiteralPath $envPath) {
            $envMap = Read-BootstrapDotEnvFile -Path $envPath
        }
        $apiKey = if (Test-BootstrapMapContainsKey -Map $envMap -Key 'API_KEY') { [string]$envMap['API_KEY'] } else { '' }
        $records.Add([ordered]@{
            id = [string]$name
            providerId = Get-BootstrapAiProxyProviderId -ToolName ([string]$name)
            name = [string]$entry['DisplayName']
            configured = (-not [string]::IsNullOrWhiteSpace($apiKey))
            preferred = [bool]$entry['PreferredDefault']
            baseUrl = [string]$entry['BaseUrl']
            defaultModel = [string]$entry['DefaultModel']
            models = @($entry['Models'])
            port = [int]$entry['Port']
            apiKey = $apiKey
            apiKeyEnvName = Get-BootstrapAiProxyEnvVariableName -ToolName ([string]$name) -Suffix 'API_KEY'
            baseUrlEnvName = Get-BootstrapAiProxyEnvVariableName -ToolName ([string]$name) -Suffix 'BASE_URL'
            modelEnvName = Get-BootstrapAiProxyEnvVariableName -ToolName ([string]$name) -Suffix 'MODEL'
            envPath = $envPath
            sourceRoot = $sourceRoot
        }) | Out-Null
    }
    return @($records.ToArray())
}

function Get-BootstrapAiProxyDefaultRecord {
    param([Parameter(Mandatory = $true)][object[]]$Records)

    $default = @($Records | Where-Object { [string]$_['id'] -eq 'kimiproxy' } | Select-Object -First 1)
    if (@($default).Count -gt 0) { return $default[0] }
    $preferred = @($Records | Where-Object { [bool]$_['preferred'] } | Select-Object -First 1)
    if (@($preferred).Count -gt 0) { return $preferred[0] }
    $firstRecords = @($Records | Select-Object -First 1)
    if ($firstRecords.Count -eq 0) { return $null }
    return $firstRecords[0]
}

function New-BootstrapAiProxyIdeEnvironment {
    param([Parameter(Mandatory = $true)][object[]]$Records)

    $default = Get-BootstrapAiProxyDefaultRecord -Records $Records
    $envMap = [ordered]@{
        OPENAI_API_KEY = [string]$default['apiKey']
        OPENAI_BASE_URL = [string]$default['baseUrl']
        OPENAI_MODEL = [string]$default['defaultModel']
        OPENAI_COMPAT_PROVIDER = [string]$default['id']
        OPENAI_COMPAT_STAGE = 'phasezero-ai-proxy-suite'
        PHASEZERO_AI_PROXY_DEFAULT = [string]$default['id']
    }

    foreach ($record in @($Records)) {
        if (-not [string]::IsNullOrWhiteSpace([string]$record['apiKey'])) {
            $envMap[[string]$record['apiKeyEnvName']] = [string]$record['apiKey']
        }
        $envMap[[string]$record['baseUrlEnvName']] = [string]$record['baseUrl']
        $envMap[[string]$record['modelEnvName']] = [string]$record['defaultModel']
    }
    return $envMap
}

function New-BootstrapAiProxyContinueModel {
    param([Parameter(Mandatory = $true)][object[]]$Records)

    $models = New-Object System.Collections.Generic.List[object]
    foreach ($record in @($Records)) {
        if ([string]::IsNullOrWhiteSpace([string]$record['apiKey'])) { continue }
        $models.Add([ordered]@{
            name = ('PhaseZero {0}' -f [string]$record['name'])
            provider = 'openai'
            model = [string]$record['defaultModel']
            apiBase = [string]$record['baseUrl']
            apiKey = ('${{ secrets.' + [string]$record['apiKeyEnvName'] + ' }}')
            roles = @('chat','edit','apply')
        }) | Out-Null
    }
    return @($models.ToArray())
}

function New-BootstrapAiProxyResolvedTarget {
    param([Parameter(Mandatory = $true)][object[]]$Records)

    $envMap = New-BootstrapAiProxyIdeEnvironment -Records $Records
    $targets = [ordered]@{}
    foreach ($targetName in @('claudeCode','cursor','windsurf','trae','vsCode','roo','cline','zed','zCode','hermes')) {
        $targets[$targetName] = [ordered]@{
            env = ConvertTo-BootstrapHashtable -InputObject $envMap
            mcpServers = [ordered]@{}
        }
    }
    $targets['continue'] = [ordered]@{
        env = ConvertTo-BootstrapHashtable -InputObject $envMap
        models = @(New-BootstrapAiProxyContinueModel -Records $Records)
        mcpServers = [ordered]@{}
    }
    return (ConvertTo-BootstrapHashtable -InputObject $targets)
}

function Set-BootstrapOpenCodeAiProxyProviderConfig {
    param(
        [string]$InstallRoot = '',
        [string]$ConfigPath = '',
        [string]$AuthPath = '',
        [string]$Label = 'OpenCode'
    )

    $records = @(Get-BootstrapAiProxyProviderRecord -InstallRoot $InstallRoot -EnsureEnv)
    $configured = @($records | Where-Object { [bool]$_['configured'] })
    $path = if ([string]::IsNullOrWhiteSpace($ConfigPath)) { Get-BootstrapOpenCodeConfigPath } else { $ConfigPath }
    $summary = [ordered]@{
        path = $path
        updated = $false
        defaultProvider = 'kimiproxy'
        defaultModel = 'k2d6-thinking'
        providers = @($configured | ForEach-Object { ConvertTo-BootstrapAiProxySafeProviderRecord -Record $_ })
        configUpdated = $false
        authPath = if ([string]::IsNullOrWhiteSpace($AuthPath)) { '' } else { $AuthPath }
        authUpdated = $false
    }
    if ([string]::IsNullOrWhiteSpace($path) -or $configured.Count -eq 0) {
        return $summary
    }

    $settings = @{}
    if (Test-Path -LiteralPath $path) {
        try {
            $settings = Read-BootstrapJsonFile -Path $path
            if (-not ($settings -is [hashtable])) { $settings = @{} }
        } catch {
            $backupPath = Backup-BootstrapFile -Path $path
            if ($backupPath) {
                Write-Log ("{0} config invalido; backup criado: {1}" -f $Label, $backupPath) 'WARN'
            }
            $settings = @{}
        }
    }

    $before = ((ConvertTo-BootstrapObjectGraph -InputObject $settings) | ConvertTo-Json -Depth 40 -Compress)
    if (-not $settings.ContainsKey('$schema')) {
        $settings['$schema'] = 'https://opencode.ai/config.json'
    }
    $providerMap = Ensure-BootstrapNamedMap -Parent $settings -Name 'provider'

    foreach ($record in @($configured)) {
        $providerId = [string]$record['providerId']
        $providerConfig = @{}
        if ($providerMap.ContainsKey($providerId) -and ($providerMap[$providerId] -is [hashtable])) {
            $providerConfig = ConvertTo-BootstrapHashtable -InputObject $providerMap[$providerId]
        }
        $providerConfig['name'] = [string]$record['name']
        $options = Ensure-BootstrapNamedMap -Parent $providerConfig -Name 'options'
        $options['baseURL'] = [string]$record['baseUrl']
        $options['apiKey'] = [string]$record['apiKey']
        $modelsMap = Ensure-BootstrapNamedMap -Parent $providerConfig -Name 'models'
        foreach ($modelId in @($record['models'])) {
            $id = [string]$modelId
            if ([string]::IsNullOrWhiteSpace($id)) { continue }
            if (-not $modelsMap.ContainsKey($id) -or -not ($modelsMap[$id] -is [hashtable])) {
                $modelsMap[$id] = [ordered]@{}
            }
        }
        $providerMap[$providerId] = $providerConfig
    }

    $default = Get-BootstrapAiProxyDefaultRecord -Records $configured
    $defaultModel = ('{0}/{1}' -f [string]$default['providerId'], [string]$default['defaultModel'])
    $settings['model'] = $defaultModel
    $smallModel = @($default['models'] | Where-Object { [string]$_ -ne [string]$default['defaultModel'] } | Select-Object -First 1)
    if (@($smallModel).Count -gt 0) {
        $settings['small_model'] = ('{0}/{1}' -f [string]$default['providerId'], [string]$smallModel[0])
    }

    $after = ((ConvertTo-BootstrapObjectGraph -InputObject $settings) | ConvertTo-Json -Depth 40 -Compress)
    $configUpdated = ($before -ne $after)
    if ($configUpdated) {
        if (Test-Path -LiteralPath $path) {
            Backup-BootstrapFile -Path $path | Out-Null
        }
        Write-BootstrapJsonFile -Path $path -Value $settings
        Write-Log ("{0} configurado com PhaseZero AI Proxy Suite: {1}" -f $Label, $path)
    }
    $authSummary = Set-BootstrapAiProxyProviderAuth -InstallRoot $InstallRoot -AuthPath $AuthPath -Label $Label
    $summary.configUpdated = $configUpdated
    $summary.authPath = [string]$authSummary.path
    $summary.authUpdated = [bool]$authSummary.updated
    $summary.updated = ($configUpdated -or [bool]$authSummary.updated)
    return $summary
}

function Set-BootstrapAiProxyProviderAuth {
    param(
        [string]$InstallRoot = '',
        [string]$AuthPath = '',
        [string]$Label = 'OpenCode'
    )

    $records = @(Get-BootstrapAiProxyProviderRecord -InstallRoot $InstallRoot -EnsureEnv)
    $configured = @($records | Where-Object { [bool]$_['configured'] })
    $path = $AuthPath
    if ([string]::IsNullOrWhiteSpace($path)) {
        $path = Get-BootstrapOpenCodeAuthPath
    }
    $summary = [ordered]@{
        path = $path
        updated = $false
        providers = @($configured | ForEach-Object {
            [ordered]@{
                id = [string]$_['id']
                providerId = [string]$_['providerId']
                name = [string]$_['name']
            }
        })
    }
    if ([string]::IsNullOrWhiteSpace($path) -or $configured.Count -eq 0) {
        return $summary
    }

    $auth = @{}
    if (Test-Path -LiteralPath $path) {
        try {
            $auth = Read-BootstrapJsonFile -Path $path
            if (-not ($auth -is [hashtable])) { $auth = @{} }
        } catch {
            $backupPath = Backup-BootstrapFile -Path $path
            if ($backupPath) {
                Write-Log ("{0} auth invalido; backup criado: {1}" -f $Label, $backupPath) 'WARN'
            }
            $auth = @{}
        }
    }

    $before = ((ConvertTo-BootstrapObjectGraph -InputObject $auth) | ConvertTo-Json -Depth 30 -Compress)
    foreach ($record in @($configured)) {
        $providerId = [string]$record['providerId']
        $apiKey = [string]$record['apiKey']
        if ([string]::IsNullOrWhiteSpace($providerId) -or [string]::IsNullOrWhiteSpace($apiKey)) { continue }
        $auth[$providerId] = [ordered]@{
            type = 'api'
            key = $apiKey
        }
    }

    $after = ((ConvertTo-BootstrapObjectGraph -InputObject $auth) | ConvertTo-Json -Depth 30 -Compress)
    if ($before -ne $after) {
        if (Test-Path -LiteralPath $path) {
            Backup-BootstrapFile -Path $path | Out-Null
        }
        Write-BootstrapJsonFile -Path $path -Value $auth
        Write-Log ("{0} auth sincronizado com PhaseZero AI Proxy Suite: {1}" -f $Label, $path)
        $summary.updated = $true
    }

    return $summary
}

function Get-BootstrapAiProxyRecordsFromResolvedEnv {
    param([hashtable]$Env)

    $records = New-Object System.Collections.Generic.List[object]
    if (-not ($Env -is [hashtable])) { return @() }
    $catalog = Get-BootstrapAiProxyCatalog
    foreach ($name in @($catalog.Keys)) {
        $apiKeyEnvName = Get-BootstrapAiProxyEnvVariableName -ToolName ([string]$name) -Suffix 'API_KEY'
        $baseUrlEnvName = Get-BootstrapAiProxyEnvVariableName -ToolName ([string]$name) -Suffix 'BASE_URL'
        $modelEnvName = Get-BootstrapAiProxyEnvVariableName -ToolName ([string]$name) -Suffix 'MODEL'
        if (-not ($Env.ContainsKey($baseUrlEnvName) -and $Env.ContainsKey($modelEnvName))) { continue }
        $entry = ConvertTo-BootstrapHashtable -InputObject $catalog[$name]
        $records.Add([ordered]@{
            id = [string]$name
            providerId = Get-BootstrapAiProxyProviderId -ToolName ([string]$name)
            name = [string]$entry['DisplayName']
            baseUrl = [string]$Env[$baseUrlEnvName]
            defaultModel = [string]$Env[$modelEnvName]
            models = @($entry['Models'])
            apiKeyEnvName = $apiKeyEnvName
            apiKey = $(if ($Env.ContainsKey($apiKeyEnvName)) { [string]$Env[$apiKeyEnvName] } else { '' })
            preferred = [bool]$entry['PreferredDefault']
        }) | Out-Null
    }
    return @($records.ToArray())
}

function Ensure-BootstrapOpenClawCompatibleConfigFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][hashtable]$Target,
        [Parameter(Mandatory = $true)][string]$Label
    )
    Write-Log ("{0} mantido intacto: grants por requisição para OpenClaw ainda não são aplicáveis." -f $Label) 'WARN'
    return $false
}

function Convert-BootstrapHermesYamlValue {
    param([AllowNull()][string]$Value)

    return (Convert-BootstrapContinueScalarToYaml -Value $Value)
}

function New-BootstrapHermesPhaseZeroYamlContent {
    param([Parameter(Mandatory = $true)][hashtable]$Env)

    $records = @(Get-BootstrapAiProxyRecordsFromResolvedEnv -Env $Env)
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add('# BEGIN PHASEZERO AI PROXY SUITE') | Out-Null
    $lines.Add('# Managed by PhaseZero. Secrets stay in ~/.hermes/.env.') | Out-Null
    if ($records.Count -gt 0) {
        $default = Get-BootstrapAiProxyDefaultRecord -Records $records
        if ($null -ne $default) {
            $lines.Add('model:') | Out-Null
            $lines.Add(('  provider: {0}' -f (Convert-BootstrapHermesYamlValue -Value ('custom:' + [string]$default['providerId'])))) | Out-Null
            $lines.Add(('  default: {0}' -f (Convert-BootstrapHermesYamlValue -Value ([string]$default['defaultModel'])))) | Out-Null
        }
        $lines.Add('custom_providers:') | Out-Null
        foreach ($record in @($records)) {
            $lines.Add(('  - name: {0}' -f (Convert-BootstrapHermesYamlValue -Value ([string]$record['providerId'])))) | Out-Null
            $lines.Add(('    base_url: {0}' -f (Convert-BootstrapHermesYamlValue -Value ([string]$record['baseUrl'])))) | Out-Null
            $lines.Add(('    key_env: {0}' -f (Convert-BootstrapHermesYamlValue -Value ([string]$record['apiKeyEnvName'])))) | Out-Null
            $lines.Add('    api_mode: chat_completions') | Out-Null
            $lines.Add(('    model: {0}' -f (Convert-BootstrapHermesYamlValue -Value ([string]$record['defaultModel'])))) | Out-Null
        }
    }
    $lines.Add('# END PHASEZERO AI PROXY SUITE') | Out-Null
    return ([string]::Join([Environment]::NewLine, @($lines.ToArray())) + [Environment]::NewLine)
}

function Merge-BootstrapHermesPhaseZeroBlock {
    param(
        [string]$Current,
        [string]$Block
    )

    $begin = '# BEGIN PHASEZERO AI PROXY SUITE'
    $end = '# END PHASEZERO AI PROXY SUITE'
    if ([string]::IsNullOrWhiteSpace($Current)) { return $Block }
    $pattern = '(?s)# BEGIN PHASEZERO AI PROXY SUITE.*?# END PHASEZERO AI PROXY SUITE\s*'
    if ($Current -match [regex]::Escape($begin)) {
        return ([regex]::Replace($Current, $pattern, $Block))
    }
    return $null
}

function Ensure-BootstrapHermesHomeProxyConfig {
    param([Parameter(Mandatory = $true)][hashtable]$Target)

    $summary = [ordered]@{
        envPath = Get-BootstrapHermesEnvPath
        configPath = Get-BootstrapHermesYamlConfigPath
        sidecarPath = Get-BootstrapHermesPhaseZeroConfigPath
        envUpdated = $false
        configUpdated = $false
        sidecarUpdated = $false
    }
    if (-not ($Target -is [hashtable]) -or -not ($Target.ContainsKey('env') -and ($Target['env'] -is [hashtable]))) {
        return $summary
    }

    $envValues = @{}
    Set-BootstrapNonEmptyStringValues -Target $envValues -Values $Target['env']
    if ($envValues.Count -eq 0) { return $summary }

    $envLines = New-Object System.Collections.Generic.List[string]
    $envLines.Add('# Managed by PhaseZero. Do not commit this file.') | Out-Null
    foreach ($name in ($envValues.Keys | Sort-Object)) {
        $envLines.Add((ConvertTo-BootstrapEnvFileLine -Name ([string]$name) -Value ([string]$envValues[$name]))) | Out-Null
    }
    $envContent = [string]::Join([Environment]::NewLine, @($envLines.ToArray())) + [Environment]::NewLine
    $summary.envUpdated = Ensure-BootstrapTextFile -Path $summary.envPath -Content $envContent -Label 'Hermes .env'

    $block = New-BootstrapHermesPhaseZeroYamlContent -Env $envValues
    $configPath = [string]$summary.configPath
    $current = if (-not [string]::IsNullOrWhiteSpace($configPath) -and (Test-Path -LiteralPath $configPath)) { [System.IO.File]::ReadAllText($configPath) } else { '' }
    $merged = Merge-BootstrapHermesPhaseZeroBlock -Current $current -Block $block
    if ($null -ne $merged) {
        $summary.configUpdated = Ensure-BootstrapTextFile -Path $configPath -Content $merged -Label 'Hermes config.yaml'
    } else {
        $summary.sidecarUpdated = Ensure-BootstrapTextFile -Path $summary.sidecarPath -Content $block -Label 'Hermes PhaseZero sidecar'
    }

    return $summary
}

function Set-BootstrapAiProxyIdeDefault {
    param(
        [string]$InstallRoot = '',
        [string]$ProjectRoot = '',
        [switch]$DryRun
    )

    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $project = if ([string]::IsNullOrWhiteSpace($ProjectRoot)) { (Get-Location).Path } else { [System.IO.Path]::GetFullPath($ProjectRoot) }
    $plannedTargets = @('claudeCode','cursor','windsurf','trae','vsCode','roo','cline','zed','zCode','openCode','hermes','kilo','continue')
    if ($DryRun) {
        return [ordered]@{
            status = 'planned'
            installRoot = $root
            projectRoot = $project
            manifestPath = Get-BootstrapAiProxyManifestPath -InstallRoot $root
            defaultProvider = 'kimiproxy'
            defaultBaseUrl = [string](Get-BootstrapAiProxyCatalog)['kimiproxy']['BaseUrl']
            defaultModel = [string](Get-BootstrapAiProxyCatalog)['kimiproxy']['DefaultModel']
            providers = @((Get-BootstrapAiProxyProviderRecord -InstallRoot $root) | ForEach-Object { ConvertTo-BootstrapAiProxySafeProviderRecord -Record $_ })
            targets = @($plannedTargets)
            targetUpdates = [ordered]@{}
        }
    }

    $records = @(Get-BootstrapAiProxyProviderRecord -InstallRoot $root -EnsureEnv)
    $manifestPath = Write-BootstrapAiProxyManifest -InstallRoot $root
    $resolvedTargets = New-BootstrapAiProxyResolvedTarget -Records $records
    $targetUpdates = [ordered]@{
        claudeCodeUpdated = Ensure-BootstrapClaudeCodeSecrets -ResolvedTargets $resolvedTargets
        cursorUpdated = Ensure-BootstrapCursorSecrets -ResolvedTargets $resolvedTargets
        windsurfUpdated = Ensure-BootstrapWindsurfSecrets -ResolvedTargets $resolvedTargets
        traeUpdated = Ensure-BootstrapTraeSecrets -ResolvedTargets $resolvedTargets
        vsCodeUpdated = Ensure-BootstrapVsCodeSecrets -ResolvedTargets $resolvedTargets
        rooUpdated = Ensure-BootstrapRooSecrets -ResolvedTargets $resolvedTargets
        clineUpdated = Ensure-BootstrapClineSecrets -ResolvedTargets $resolvedTargets
        zedUpdated = Ensure-BootstrapZedSecrets -ResolvedTargets $resolvedTargets
        zCodeUpdated = Ensure-BootstrapZCodeSecrets -ResolvedTargets $resolvedTargets
        openClawUpdated = Ensure-BootstrapOpenClawSecrets -ResolvedTargets $resolvedTargets
        hermesUpdated = Ensure-BootstrapHermesSecrets -ResolvedTargets $resolvedTargets -State @{ CloneBaseDir = $project }
        continueUpdated = $false
        openCodeUpdated = $false
        kiloUpdated = $false
    }
    $continueSummary = Ensure-BootstrapContinueExtensionConfig -ResolvedTargets $resolvedTargets
    $targetUpdates.continueUpdated = ([bool]$continueSummary.envUpdated -or [bool]$continueSummary.configUpdated)
    $openCodeSummary = Set-BootstrapOpenCodeAiProxyProviderConfig -InstallRoot $root
    $targetUpdates.openCodeUpdated = [bool]$openCodeSummary.updated
    $kiloSummary = Set-BootstrapOpenCodeAiProxyProviderConfig -InstallRoot $root -ConfigPath (Get-BootstrapKiloConfigPath) -AuthPath (Get-BootstrapKiloAuthPath) -Label 'Kilo CLI'
    $targetUpdates.kiloUpdated = [bool]$kiloSummary.updated
    $default = Get-BootstrapAiProxyDefaultRecord -Records $records

    return [ordered]@{
        status = 'configured'
        installRoot = $root
        projectRoot = $project
        manifestPath = $manifestPath
        defaultProvider = [string]$default['id']
        defaultBaseUrl = [string]$default['baseUrl']
        defaultModel = [string]$default['defaultModel']
        providers = @($records | ForEach-Object { ConvertTo-BootstrapAiProxySafeProviderRecord -Record $_ })
        targets = @($plannedTargets)
        targetUpdates = $targetUpdates
        continue = $continueSummary
        openCode = $openCodeSummary
        kilo = $kiloSummary
    }
}

function Install-BootstrapAiProxySuiteManagedTool {
    param(
        [string]$InstallRoot = '',
        [string]$ProjectRoot = '',
        [switch]$DryRun
    )

    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $project = if ([string]::IsNullOrWhiteSpace($ProjectRoot)) { (Get-Location).Path } else { [System.IO.Path]::GetFullPath($ProjectRoot) }
    $catalog = Get-BootstrapAiProxyCatalog
    $installResults = New-Object System.Collections.Generic.List[object]
    foreach ($name in @($catalog.Keys)) {
        $entry = $catalog[$name]
        $install = Install-BootstrapAiProxyManagedTool -ToolName ([string]$name) -CatalogEntry $entry -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun
        $installResults.Add([ordered]@{
            tool = [string]$install['tool']
            status = [string]$install['status']
            runtime = [string]$install['runtime']
            repoUrl = [string]$install['repoUrl']
            baseUrl = [string]$install['baseUrl']
            defaultModel = [string]$install['defaultModel']
        }) | Out-Null
    }

    $defaults = Set-BootstrapAiProxyIdeDefault -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun
    $start = Start-BootstrapAiProxySuite -InstallRoot $root -DryRun:$DryRun -TimeoutMs 30000
    $status = if ($DryRun) { 'planned' } elseif ([string]$start['status'] -eq 'started') { 'configured' } else { [string]$start['status'] }
    $result = New-BootstrapAiToolResult -ToolName 'ai-proxy-suite' -Action 'install' -Status $status -InstallRoot $root -ProjectRoot $project -Message 'AI proxy suite gerenciada: Kimi default; demais providers selecionaveis.' -Docs 'https://github.com/pedrofariasx/kimiproxy'
    $result['defaultProvider'] = [string]$defaults['defaultProvider']
    $result['defaultBaseUrl'] = [string]$defaults['defaultBaseUrl']
    $result['defaultModel'] = [string]$defaults['defaultModel']
    $result['providers'] = @($defaults['providers'])
    $result['targets'] = $defaults['targetUpdates']
    $result['installResults'] = @($installResults.ToArray())
    $result['startResults'] = @($start['startResults'])
    if (Test-BootstrapMapContainsKey -Map $start -Key 'doctor') { $result['runtimeStatus'] = $start['doctor'] }
    $result['manifestPath'] = [string]$defaults['manifestPath']
    return $result
}

function Add-BootstrapAiProxyResultField {
    param(
        [Parameter(Mandatory = $true)]$Result,
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [string]$InstallRoot = '',
        [string]$EnvPath = '',
        [string]$ManifestPath = ''
    )
    $Result['repoUrl'] = [string]$CatalogEntry['RepoUrl']
    $Result['runtime'] = [string]$CatalogEntry['Runtime']
    $Result['port'] = [int]$CatalogEntry['Port']
    $Result['baseUrl'] = [string]$CatalogEntry['BaseUrl']
    $Result['defaultModel'] = [string]$CatalogEntry['DefaultModel']
    $Result['models'] = @($CatalogEntry['Models'])
    $Result['preferredDefault'] = [bool]$CatalogEntry['PreferredDefault']
    $Result['playwright'] = [bool]$CatalogEntry['Playwright']
    $Result['sourceRoot'] = Get-BootstrapAiProxySourceRoot -ToolName ([string]$CatalogEntry['ToolName']) -InstallRoot $InstallRoot
    if (-not [string]::IsNullOrWhiteSpace($EnvPath)) { $Result['envPath'] = $EnvPath }
    if (-not [string]::IsNullOrWhiteSpace($ManifestPath)) { $Result['manifestPath'] = $ManifestPath }
    return $Result
}

function Set-BootstrapAiProxyEnvironment {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [string]$InstallRoot = '',
        [string]$ProjectRoot = '',
        [switch]$DryRun
    )

    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $sourceRoot = Get-BootstrapAiProxySourceRoot -ToolName $ToolName -InstallRoot $root
    $envPath = Join-Path $sourceRoot '.env'
    $manifestPath = Get-BootstrapAiProxyManifestPath -InstallRoot $root
    if ($DryRun) {
        $result = New-BootstrapAiToolResult -ToolName $ToolName -Action 'configure' -Status 'planned' -InstallRoot $root -ProjectRoot $ProjectRoot -Message ('Criar .env local redigido e manifest seguro para {0}.' -f [string]$CatalogEntry['DisplayName']) -Docs ([string]$CatalogEntry['DocsUrl'])
        $result['webValidation'] = Invoke-BootstrapAiProxyWebValidation -ToolName $ToolName -CatalogEntry $CatalogEntry -InstallRoot $root -SourceRoot $sourceRoot -EnvPath $envPath -DryRun
        return (Add-BootstrapAiProxyResultField -Result $result -CatalogEntry $CatalogEntry -InstallRoot $root -EnvPath $envPath -ManifestPath $manifestPath)
    }

    $envInfo = Write-BootstrapAiProxyEnvFile -ToolName $ToolName -CatalogEntry $CatalogEntry -InstallRoot $root
    $writtenManifestPath = Write-BootstrapAiProxyManifest -InstallRoot $root
    $result = New-BootstrapAiToolResult -ToolName $ToolName -Action 'configure' -Status 'configured' -InstallRoot $root -ProjectRoot $ProjectRoot -Message ('Config local criada para {0}; valores secretos permanecem somente no .env do proxy.' -f [string]$CatalogEntry['DisplayName']) -Docs ([string]$CatalogEntry['DocsUrl'])
    $result['env'] = [ordered]@{ keyCount = [int]$envInfo['keyCount']; secretKeyCount = [int]$envInfo['secretKeyCount']; hasApiKey = [bool]$envInfo['hasApiKey'] }
    $result['webValidation'] = Invoke-BootstrapAiProxyWebValidation -ToolName $ToolName -CatalogEntry $CatalogEntry -InstallRoot $root -SourceRoot $sourceRoot -EnvPath ([string]$envInfo['path'])
    return (Add-BootstrapAiProxyResultField -Result $result -CatalogEntry $CatalogEntry -InstallRoot $root -EnvPath ([string]$envInfo['path']) -ManifestPath $writtenManifestPath)
}

function Invoke-BootstrapAiProxyInstallCommand {
    param(
        [Parameter(Mandatory = $true)][string]$Exe,
        [string[]]$Arguments = @(),
        [Parameter(Mandatory = $true)][string]$WorkingDirectory,
        [int]$TimeoutMs = 600000,
        [string]$Label = 'command'
    )

    $result = Invoke-BootstrapAiNativeCommand -Exe $Exe -Args $Arguments -WorkingDirectory $WorkingDirectory -TimeoutMs $TimeoutMs
    if ([int]$result['exitCode'] -ne 0) {
        $detail = Get-BootstrapCleanNativeText -Text (([string]$result['stderr']) + ' ' + ([string]$result['stdout'])) -MaxLength 800
        throw ("{0} falhou (exit={1}). {2}" -f $Label, [int]$result['exitCode'], $detail)
    }
    return $result
}

function Test-BootstrapAiProxyManagedSourcePath {
    param([Parameter(Mandatory = $true)][string]$SourceRoot)

    $fullSource = [System.IO.Path]::GetFullPath($SourceRoot)
    $parent = [System.IO.Path]::GetFullPath((Split-Path -Path $fullSource -Parent))
    if ([string]::IsNullOrWhiteSpace($parent) -or (Split-Path -Path $parent -Leaf) -ne 'sources') {
        throw "Caminho de proxy gerenciado recusado: $SourceRoot"
    }
    $prefix = $parent.TrimEnd('\','/') + [System.IO.Path]::DirectorySeparatorChar
    if (-not $fullSource.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw "Caminho de proxy gerenciado fora de sources: $SourceRoot"
    }
    return $true
}

function Restore-BootstrapAiProxyManagedLocalState {
    param(
        [Parameter(Mandatory = $true)][string]$BackupPath,
        [Parameter(Mandatory = $true)][string]$SourceRoot
    )

    $restored = New-Object System.Collections.Generic.List[string]
    foreach ($name in @('.env','.env.local','user-data','user_data','browser-data','browser_data','playwright-data','profile','profiles','session','sessions','.session','.sessions','storageState.json','cookies.json')) {
        $from = Join-Path $BackupPath $name
        if (-not (Test-Path -LiteralPath $from)) { continue }
        $to = Join-Path $SourceRoot $name
        try {
            Copy-Item -LiteralPath $from -Destination $to -Recurse -Force -ErrorAction Stop
            $restored.Add($name) | Out-Null
        } catch {
            Write-Log ("Repo gerenciado: nao foi possivel restaurar estado local {0}: {1}" -f $name, $_.Exception.Message) 'WARN'
        }
    }
    return @($restored.ToArray())
}

function Repair-BootstrapAiProxyManagedRepository {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$SourceRoot,
        [Parameter(Mandatory = $true)][string]$GitExe
    )

    [void](Test-BootstrapAiProxyManagedSourcePath -SourceRoot $SourceRoot)
    $parent = Split-Path -Path $SourceRoot -Parent
    $leaf = Split-Path -Path $SourceRoot -Leaf
    $backupRoot = Join-Path $parent '.phasezero-repo-backups'
    [void][System.IO.Directory]::CreateDirectory($backupRoot)
    $stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    $backupPath = Join-Path $backupRoot ("{0}-{1}" -f $leaf, $stamp)
    if (Test-Path -LiteralPath $backupPath) {
        $backupPath = Join-Path $backupRoot ("{0}-{1}-{2}" -f $leaf, $stamp, ([Guid]::NewGuid().ToString('N').Substring(0, 8)))
    }

    Move-Item -LiteralPath $SourceRoot -Destination $backupPath -Force -ErrorAction Stop
    try {
        Invoke-BootstrapAiProxyInstallCommand -Exe $GitExe -Arguments @('clone','--depth','1',[string]$CatalogEntry['RepoUrl'],$SourceRoot) -WorkingDirectory $parent -TimeoutMs 600000 -Label 'git clone repair' | Out-Null
    } catch {
        if ((-not (Test-Path -LiteralPath $SourceRoot)) -and (Test-Path -LiteralPath $backupPath)) {
            try { Move-Item -LiteralPath $backupPath -Destination $SourceRoot -Force -ErrorAction SilentlyContinue } catch { }
        }
        throw
    }

    $restored = @(Restore-BootstrapAiProxyManagedLocalState -BackupPath $backupPath -SourceRoot $SourceRoot)
    Write-Log ("Repo gerenciado reparado por reclone limpo: {0}; backup: {1}" -f $SourceRoot, $backupPath) 'WARN'
    return [ordered]@{
        repaired = $true
        backupPath = $backupPath
        restoredLocalState = @($restored)
        envRestored = (@($restored) -contains '.env')
    }
}

function Ensure-BootstrapAiProxyPlaywrightRuntime {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$SourceRoot,
        [switch]$DryRun
    )

    if (-not ([bool]$CatalogEntry['Playwright'])) {
        return [ordered]@{ status = 'skipped'; changed = $false }
    }
    $playwrightArgs = @('playwright','install','chromium','chromium-headless-shell')
    if ($DryRun) {
        return [ordered]@{ status = 'planned'; changed = $false; command = 'npx playwright install chromium chromium-headless-shell' }
    }
    if (-not (Test-Path -LiteralPath $SourceRoot)) {
        throw "sourceRoot ausente para Playwright: $SourceRoot"
    }

    $npm = Get-BootstrapNpmCommandForAiTools
    $npx = Get-BootstrapNpxCommandForAiTools -NpmCommand $npm
    Clear-BootstrapPlaywrightStaleLock
    try {
        $direct = Ensure-BootstrapAiProxyPlaywrightRuntimeDirect -Npx $npx -SourceRoot $SourceRoot -BrowserArgs @('chromium','chromium-headless-shell')
        if ([string]$direct['status'] -eq 'ready') {
            return $direct
        }
    } catch {
        Write-Log ("Playwright direto indisponivel; usando fallback npx install. {0}" -f (Get-BootstrapCleanNativeText -Text $_.Exception.Message -MaxLength 300)) 'WARN'
    }

    $lastMessage = ''
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        Clear-BootstrapPlaywrightStaleLock
        try {
            Invoke-BootstrapAiProxyInstallCommand -Exe $npx -Arguments $playwrightArgs -WorkingDirectory $SourceRoot -TimeoutMs 300000 -Label 'playwright install chromium chromium-headless-shell' | Out-Null
            return [ordered]@{
                status = 'ready'
                changed = $true
                attempts = $attempt
                command = ('{0} playwright install chromium chromium-headless-shell' -f $npx)
            }
        } catch {
            $lastMessage = [string]$_.Exception.Message
            if ($attempt -lt 3 -and $lastMessage -match '(?i)__dirlock|lockfile|ENOENT|EEXIST|EPERM|EBUSY') {
                Write-Log ("Playwright install chromium/headless-shell falhou por lock/cache transitorio (tentativa {0}/3). Retry." -f $attempt) 'WARN'
                Start-Sleep -Milliseconds (750 * $attempt)
                continue
            }
            throw
        }
    }
    throw $lastMessage
}

function Get-BootstrapPlaywrightInstallPlan {
    param(
        [Parameter(Mandatory = $true)][string]$Npx,
        [Parameter(Mandatory = $true)][string]$SourceRoot,
        [string[]]$BrowserArgs = @('chromium','chromium-headless-shell')
    )

    $args = @('playwright','install') + @($BrowserArgs) + @('--dry-run')
    $result = Invoke-BootstrapAiNativeCommand -Exe $Npx -Args $args -WorkingDirectory $SourceRoot -TimeoutMs 60000
    if ([int]$result['exitCode'] -ne 0) {
        $detail = Get-BootstrapCleanNativeText -Text (([string]$result['stderr']) + ' ' + ([string]$result['stdout'])) -MaxLength 800
        throw ("playwright install --dry-run falhou (exit={0}). {1}" -f [int]$result['exitCode'], $detail)
    }

    $records = New-Object System.Collections.Generic.List[object]
    $currentName = ''
    $currentLocation = ''
    $seen = @{}
    foreach ($rawLine in (([string]$result['stdout']) -replace "`r", "`n" -split "`n")) {
        $line = ([string]$rawLine).Trim()
        if ([string]::IsNullOrWhiteSpace($line)) { continue }
        if ($line -match '^(?<name>.+?)\s+\(playwright\s+.+?\)$') {
            $currentName = $matches['name'].Trim()
            $currentLocation = ''
            continue
        }
        if ($line -match '^Install location:\s+(?<path>.+)$') {
            $currentLocation = $matches['path'].Trim()
            continue
        }
        if ($line -match '^Download url:\s+(?<url>https?://.+)$' -and -not [string]::IsNullOrWhiteSpace($currentLocation)) {
            $url = $matches['url'].Trim()
            $key = ([System.IO.Path]::GetFullPath($currentLocation)).ToLowerInvariant()
            if (-not $seen.ContainsKey($key)) {
                $seen[$key] = $true
                $records.Add([ordered]@{
                    name = $currentName
                    installLocation = $currentLocation
                    downloadUrl = $url
                }) | Out-Null
            }
        }
    }
    return @($records.ToArray())
}

function Invoke-BootstrapCurlDownload {
    param(
        [Parameter(Mandatory = $true)][string]$Url,
        [Parameter(Mandatory = $true)][string]$OutFile,
        [string]$Label = 'download'
    )

    $parent = Split-Path -Path $OutFile -Parent
    if ($parent) { [void][System.IO.Directory]::CreateDirectory($parent) }
    $curl = Resolve-CommandPath -Name 'curl.exe'
    if (-not $curl) {
        $candidate = Join-Path $env:SystemRoot 'System32\curl.exe'
        if (Test-Path -LiteralPath $candidate) { $curl = $candidate }
    }
    if ($curl) {
        $args = @('-L','--fail','--retry','3','--connect-timeout','30','--max-time','900','-o',$OutFile,$Url)
        $result = Invoke-BootstrapAiNativeCommand -Exe $curl -Args $args -TimeoutMs 930000
        if ([int]$result['exitCode'] -eq 0 -and (Test-Path -LiteralPath $OutFile)) { return }
        $detail = Get-BootstrapCleanNativeText -Text (([string]$result['stderr']) + ' ' + ([string]$result['stdout'])) -MaxLength 800
        throw ("{0} falhou via curl (exit={1}). {2}" -f $Label, [int]$result['exitCode'], $detail)
    }

    Invoke-WebRequestWithRetry -Uri $Url -OutFile $OutFile -OperationName $Label
}

function Expand-BootstrapZipArchiveSafe {
    param(
        [Parameter(Mandatory = $true)][string]$ZipPath,
        [Parameter(Mandatory = $true)][string]$DestinationPath
    )

    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $parent = Split-Path -Path $DestinationPath -Parent
    if ($parent) { [void][System.IO.Directory]::CreateDirectory($parent) }
    $tmp = $DestinationPath + '.tmp-' + ([Guid]::NewGuid().ToString('N').Substring(0, 8))
    if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue }
    [void][System.IO.Directory]::CreateDirectory($tmp)
    try {
        [System.IO.Compression.ZipFile]::ExtractToDirectory($ZipPath, $tmp)
        if (Test-Path -LiteralPath $DestinationPath) {
            Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
        } else {
            Move-Item -LiteralPath $tmp -Destination $DestinationPath -Force -ErrorAction Stop
        }
    } catch {
        if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue }
        throw
    }
}

function Ensure-BootstrapAiProxyPlaywrightRuntimeDirect {
    param(
        [Parameter(Mandatory = $true)][string]$Npx,
        [Parameter(Mandatory = $true)][string]$SourceRoot,
        [string[]]$BrowserArgs = @('chromium','chromium-headless-shell')
    )

    $plan = @(Get-BootstrapPlaywrightInstallPlan -Npx $Npx -SourceRoot $SourceRoot -BrowserArgs $BrowserArgs)
    if ($plan.Count -eq 0) {
        return [ordered]@{ status = 'unavailable'; changed = $false; reason = 'empty-plan' }
    }

    $missing = @($plan | Where-Object { -not (Test-Path -LiteralPath ([string]$_['installLocation'])) })
    if ($missing.Count -eq 0) {
        return [ordered]@{ status = 'ready'; changed = $false; direct = $true; installed = @(); planned = $plan.Count }
    }

    $downloadRoot = Join-Path (Get-BootstrapDataRoot) 'downloads\playwright'
    [void][System.IO.Directory]::CreateDirectory($downloadRoot)
    $installed = New-Object System.Collections.Generic.List[string]
    foreach ($item in @($missing)) {
        $url = [string]$item['downloadUrl']
        $location = [string]$item['installLocation']
        if ([string]::IsNullOrWhiteSpace($url) -or [string]::IsNullOrWhiteSpace($location)) { continue }
        $zipName = [System.IO.Path]::GetFileName(([Uri]$url).AbsolutePath)
        if ([string]::IsNullOrWhiteSpace($zipName)) { $zipName = ([Guid]::NewGuid().ToString('N') + '.zip') }
        $zipPath = Join-Path $downloadRoot $zipName
        Write-Log ("Playwright direto: baixando {0} de {1}" -f [string]$item['name'], $url)
        Invoke-BootstrapCurlDownload -Url $url -OutFile $zipPath -Label ("Playwright {0}" -f [string]$item['name'])
        Write-Log ("Playwright direto: extraindo {0} para {1}" -f $zipName, $location)
        Expand-BootstrapZipArchiveSafe -ZipPath $zipPath -DestinationPath $location
        $installed.Add($location) | Out-Null
    }

    return [ordered]@{ status = 'ready'; changed = ($installed.Count -gt 0); direct = $true; installed = @($installed.ToArray()); planned = $plan.Count }
}

function Sync-BootstrapAiProxyRepository {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$SourceRoot
    )

    $git = Resolve-CommandPath -Name 'git'
    if (-not $git) { throw 'git nao encontrado para clonar proxy local.' }
    if (Test-Path -LiteralPath (Join-Path $SourceRoot '.git')) {
        try {
            Invoke-BootstrapAiProxyInstallCommand -Exe $git -Arguments @('fetch','--depth','1','origin') -WorkingDirectory $SourceRoot -TimeoutMs 300000 -Label 'git fetch' | Out-Null
            Invoke-BootstrapAiProxyInstallCommand -Exe $git -Arguments @('pull','--ff-only') -WorkingDirectory $SourceRoot -TimeoutMs 300000 -Label 'git pull' | Out-Null
        } catch {
            $detail = [string]$_.Exception.Message
            if ($detail -match '(?i)diverg|fast-forward|would be overwritten|local changes|not possible|untracked|cannot lock ref') {
                Write-Log ("Repo gerenciado divergente/sujo; reparando por reclone com backup. {0}" -f (Get-BootstrapCleanNativeText -Text $detail -MaxLength 300)) 'WARN'
                Repair-BootstrapAiProxyManagedRepository -CatalogEntry $CatalogEntry -SourceRoot $SourceRoot -GitExe $git | Out-Null
            } else {
                throw
            }
        }
        return
    }
    if (Test-Path -LiteralPath $SourceRoot) {
        $items = @(Get-ChildItem -LiteralPath $SourceRoot -Force -ErrorAction SilentlyContinue)
        if ($items.Count -gt 0) { throw "Diretorio existe mas nao e clone git gerenciado: $SourceRoot" }
    } else {
        [void][System.IO.Directory]::CreateDirectory((Split-Path -Path $SourceRoot -Parent))
    }
    Invoke-BootstrapAiProxyInstallCommand -Exe $git -Arguments @('clone','--depth','1',[string]$CatalogEntry['RepoUrl'],$SourceRoot) -WorkingDirectory (Split-Path -Path $SourceRoot -Parent) -TimeoutMs 600000 -Label 'git clone' | Out-Null
}

function Install-BootstrapAiProxyManagedTool {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [string]$InstallRoot = '',
        [string]$ProjectRoot = '',
        [switch]$DryRun
    )

    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $sourceRoot = Get-BootstrapAiProxySourceRoot -ToolName $ToolName -InstallRoot $root
    $envPath = Join-Path $sourceRoot '.env'
    $manifestPath = Get-BootstrapAiProxyManifestPath -InstallRoot $root
    $runtime = [string]$CatalogEntry['Runtime']
    if ($DryRun) {
        $steps = @('git clone/update')
        if ($runtime -eq 'node' -or $runtime -eq 'tauri') { $steps += 'npm install' }
        if ([bool]$CatalogEntry['Playwright']) { $steps += 'npx playwright install chromium' }
        if ($runtime -eq 'go') { $steps += 'go mod download'; $steps += 'go build' }
        if ($runtime -eq 'tauri') { $steps += 'npm run build' }
        $result = New-BootstrapAiToolResult -ToolName $ToolName -Action 'install' -Status 'planned' -InstallRoot $root -ProjectRoot $ProjectRoot -Message (($steps -join '; ') + ('; repo={0}' -f [string]$CatalogEntry['RepoUrl'])) -Docs ([string]$CatalogEntry['DocsUrl'])
        $result['webValidation'] = Invoke-BootstrapAiProxyWebValidation -ToolName $ToolName -CatalogEntry $CatalogEntry -InstallRoot $root -SourceRoot $sourceRoot -EnvPath $envPath -DryRun
        return (Add-BootstrapAiProxyResultField -Result $result -CatalogEntry $CatalogEntry -InstallRoot $root -EnvPath $envPath -ManifestPath $manifestPath)
    }

    Sync-BootstrapAiProxyRepository -CatalogEntry $CatalogEntry -SourceRoot $sourceRoot
    $configResult = Set-BootstrapAiProxyEnvironment -ToolName $ToolName -CatalogEntry $CatalogEntry -InstallRoot $root -ProjectRoot $ProjectRoot

    if ($runtime -eq 'node' -or $runtime -eq 'tauri') {
        $npm = Get-BootstrapNpmCommandForAiTools
        $npmArgs = @('install')
        if ($CatalogEntry.Contains('NpmLegacyPeerDeps') -and [bool]$CatalogEntry['NpmLegacyPeerDeps']) {
            $npmArgs += '--legacy-peer-deps'
        }
        Invoke-BootstrapAiProxyInstallCommand -Exe $npm -Arguments $npmArgs -WorkingDirectory $sourceRoot -TimeoutMs 900000 -Label 'npm install' | Out-Null
        if ([bool]$CatalogEntry['Playwright']) {
            Ensure-BootstrapAiProxyPlaywrightRuntime -CatalogEntry $CatalogEntry -SourceRoot $sourceRoot | Out-Null
        }
        if ($runtime -eq 'tauri') {
            Invoke-BootstrapAiProxyInstallCommand -Exe $npm -Arguments @('run','build') -WorkingDirectory $sourceRoot -TimeoutMs 900000 -Label 'npm run build' | Out-Null
        }
    } elseif ($runtime -eq 'go') {
        $go = Resolve-CommandPath -Name 'go'
        if (-not $go) {
            $result = New-BootstrapAiToolResult -ToolName $ToolName -Action 'install' -Status 'blocked' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'Go nao encontrado. Instale componente go-core ou use Docker Compose do repositorio.' -Docs ([string]$CatalogEntry['DocsUrl'])
            return (Add-BootstrapAiProxyResultField -Result $result -CatalogEntry $CatalogEntry -InstallRoot $root -EnvPath ([string]$configResult['envPath']) -ManifestPath ([string]$configResult['manifestPath']))
        }
        Invoke-BootstrapAiProxyInstallCommand -Exe $go -Arguments @('mod','download') -WorkingDirectory $sourceRoot -TimeoutMs 900000 -Label 'go mod download' | Out-Null
        $binDir = Join-Path $sourceRoot 'bin'
        [void][System.IO.Directory]::CreateDirectory($binDir)
        Invoke-BootstrapAiProxyInstallCommand -Exe $go -Arguments @('build','-o',(Join-Path $binDir 'mimo-ai-proxy.exe'),'.') -WorkingDirectory $sourceRoot -TimeoutMs 900000 -Label 'go build' | Out-Null
    }

    $webValidation = Invoke-BootstrapAiProxyWebValidation -ToolName $ToolName -CatalogEntry $CatalogEntry -InstallRoot $root -SourceRoot $sourceRoot -EnvPath ([string]$configResult['envPath'])
    $manifest = Read-BootstrapAiToolManifest -InstallRoot $root
    $manifest['tools'][$ToolName] = @{
        kind = [string]$CatalogEntry['InstallSupport']
        repo = [string]$CatalogEntry['GitHubRepo']
        sourceRoot = $sourceRoot
        port = [int]$CatalogEntry['Port']
        baseUrl = [string]$CatalogEntry['BaseUrl']
        defaultModel = [string]$CatalogEntry['DefaultModel']
        installedAt = (Get-Date).ToString('o')
    }
    Write-BootstrapAiToolManifest -InstallRoot $root -Manifest $manifest | Out-Null
    $result = New-BootstrapAiToolResult -ToolName $ToolName -Action 'install' -Status 'installed' -InstallRoot $root -ProjectRoot $ProjectRoot -Message ('{0} instalado/configurado em source gerenciado.' -f [string]$CatalogEntry['DisplayName']) -Docs ([string]$CatalogEntry['DocsUrl'])
    $result['webValidation'] = $webValidation
    return (Add-BootstrapAiProxyResultField -Result $result -CatalogEntry $CatalogEntry -InstallRoot $root -EnvPath ([string]$configResult['envPath']) -ManifestPath ([string]$configResult['manifestPath']))
}

function Get-BootstrapAiProxyModelsUrl {
    param([AllowEmptyString()][string]$BaseUrl)
    if ([string]::IsNullOrWhiteSpace($BaseUrl)) { return '' }
    return (([string]$BaseUrl).TrimEnd('/') + '/models')
}

function Get-BootstrapAiProxyHealthUrl {
    param(
        [AllowEmptyString()][string]$BaseUrl,
        [string]$HealthPath = '/health'
    )
    if ([string]::IsNullOrWhiteSpace($BaseUrl) -or [string]::IsNullOrWhiteSpace($HealthPath)) { return '' }
    $root = ([string]$BaseUrl).TrimEnd('/') -replace '/v1$',''
    return ($root + '/' + ([string]$HealthPath).TrimStart('/'))
}

function Get-BootstrapAiProxyListeningProcessIds {
    param([int]$Port)
    $ids = New-Object System.Collections.Generic.List[int]
    if ($Port -le 0) { return @() }

    try {
        if (Get-Command -Name Get-NetTCPConnection -ErrorAction SilentlyContinue) {
            $rows = @(Get-NetTCPConnection -LocalPort $Port -State Listen -ErrorAction SilentlyContinue)
            foreach ($row in $rows) {
                $processId = [int]$row.OwningProcess
                if ($processId -gt 0 -and -not @($ids.ToArray()).Contains($processId)) { $ids.Add($processId) | Out-Null }
            }
        }
    } catch {
    }

    if ($ids.Count -eq 0) {
        try {
            $netstat = Join-Path $env:SystemRoot 'System32\netstat.exe'
            if (-not (Test-Path -LiteralPath $netstat)) { $netstat = 'netstat.exe' }
            $lines = @(& $netstat -ano -p tcp 2>$null)
            foreach ($line in $lines) {
                if ([string]$line -match ("(?i)^\s*TCP\s+\S+:{0}\s+\S+\s+LISTENING\s+(\d+)\s*$" -f [regex]::Escape([string]$Port))) {
                    $processId = [int]$matches[1]
                    if ($processId -gt 0 -and -not @($ids.ToArray()).Contains($processId)) { $ids.Add($processId) | Out-Null }
                }
            }
        } catch {
        }
    }

    return @($ids.ToArray())
}

function Get-BootstrapAiProxyProcessNames {
    param([int[]]$ProcessIds = @())
    $names = New-Object System.Collections.Generic.List[string]
    foreach ($processId in @($ProcessIds)) {
        try {
            $proc = Get-Process -Id ([int]$processId) -ErrorAction Stop
            $name = [string]$proc.ProcessName
            if (-not [string]::IsNullOrWhiteSpace($name) -and -not @($names.ToArray()).Contains($name)) { $names.Add($name) | Out-Null }
        } catch {
        }
    }
    return @($names.ToArray())
}

function Invoke-BootstrapAiProxyHttpProbe {
    param(
        [Parameter(Mandatory = $true)][string]$Url,
        [AllowNull()][string]$ApiKey = '',
        [int]$TimeoutMs = 3000
    )
    $started = [Diagnostics.Stopwatch]::StartNew()
    $status = 'unknown'
    $statusCode = 0
    $errorCode = ''
    if ([string]::IsNullOrWhiteSpace($Url)) {
        $started.Stop()
        return [ordered]@{ status = 'not-applicable'; statusCode = 0; errorCode = ''; durationMs = [long]$started.ElapsedMilliseconds }
    }

    try {
        $request = [System.Net.WebRequest]::Create($Url)
        $request.Method = 'GET'
        $request.Timeout = $TimeoutMs
        $request.ReadWriteTimeout = $TimeoutMs
        try { $request.Proxy = $null } catch { }
        if (-not [string]::IsNullOrWhiteSpace($ApiKey)) {
            $request.Headers['Authorization'] = 'Bearer ' + [string]$ApiKey
        }
        $response = $request.GetResponse()
        try {
            $statusCode = [int]$response.StatusCode
            $status = if ($statusCode -ge 200 -and $statusCode -lt 300) { 'ok' } elseif ($statusCode -eq 401 -or $statusCode -eq 403) { 'rejected' } else { 'error' }
        } finally {
            if ($response) { $response.Close(); $response.Dispose() }
        }
    } catch [System.Net.WebException] {
        $errorCode = [string]$_.Exception.Status
        $response = $_.Exception.Response
        if ($response) {
            try {
                $statusCode = [int]$response.StatusCode
                $status = if ($statusCode -eq 401 -or $statusCode -eq 403) { 'rejected' } else { 'error' }
            } finally {
                $response.Close()
                $response.Dispose()
            }
        } elseif ($_.Exception.Status -eq [System.Net.WebExceptionStatus]::Timeout) {
            $status = 'timeout'
        } else {
            $status = 'unreachable'
        }
    } catch {
        $errorCode = 'exception'
        $status = 'error'
    } finally {
        $started.Stop()
    }

    return [ordered]@{
        status = $status
        statusCode = [int]$statusCode
        errorCode = $errorCode
        durationMs = [long]$started.ElapsedMilliseconds
    }
}

function Test-BootstrapAiProxyRuntimeReady {
    param(
        [Parameter(Mandatory = $true)][string]$Runtime,
        [Parameter(Mandatory = $true)][string]$SourceRoot
    )
    if ([string]$Runtime -eq 'node' -or [string]$Runtime -eq 'tauri') {
        return (Test-Path -LiteralPath (Join-Path $SourceRoot 'node_modules'))
    }
    if ([string]$Runtime -eq 'go') {
        return ((Test-Path -LiteralPath (Join-Path $SourceRoot 'bin\mimo-ai-proxy.exe')) -or (Test-Path -LiteralPath (Join-Path $SourceRoot 'go.mod')))
    }
    return $false
}

function Test-BootstrapAiProxyEnvGroupPresent {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$EnvMap,
        [Parameter(Mandatory = $true)][string[]]$Keys
    )
    foreach ($key in @($Keys)) {
        if (Test-BootstrapMapContainsKey -Map $EnvMap -Key $key -and -not [string]::IsNullOrWhiteSpace([string]$EnvMap[$key])) {
            return $true
        }
    }
    return $false
}

function Get-BootstrapAiProxyWebValidationMissingGroups {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$EnvMap
    )
    $missing = New-Object System.Collections.Generic.List[string]
    if ([string]$ToolName -eq 'mimo-ai-proxy') {
        if (-not (Test-BootstrapAiProxyEnvGroupPresent -EnvMap $EnvMap -Keys @('SERVICE_TOKEN','SERVICE_TOKENS'))) { $missing.Add('mimo-service-session') | Out-Null }
        if (-not (Test-BootstrapAiProxyEnvGroupPresent -EnvMap $EnvMap -Keys @('USER_ID','USER_IDS'))) { $missing.Add('mimo-user-session') | Out-Null }
        if (-not (Test-BootstrapAiProxyEnvGroupPresent -EnvMap $EnvMap -Keys @('XIAOMI_CHATBOT_PH','XIAOMI_CHATBOT_PHS'))) { $missing.Add('mimo-chatbot-session') | Out-Null }
    }
    return @($missing.ToArray())
}

function Get-BootstrapAiProxyChatValidationUrl {
    param([AllowEmptyString()][string]$BaseUrl)
    if ([string]::IsNullOrWhiteSpace($BaseUrl)) { return '' }
    return (([string]$BaseUrl).TrimEnd('/') + '/chat/completions')
}

function Invoke-BootstrapAiProxyChatValidation {
    param(
        [Parameter(Mandatory = $true)][string]$Url,
        [Parameter(Mandatory = $true)][string]$Model,
        [AllowNull()][string]$ApiKey = '',
        [int]$TimeoutMs = 10000
    )
    $started = [Diagnostics.Stopwatch]::StartNew()
    $status = 'unknown'
    $statusCode = 0
    $errorCode = ''
    if ([string]::IsNullOrWhiteSpace($Url) -or [string]::IsNullOrWhiteSpace($Model)) {
        $started.Stop()
        return [ordered]@{ status = 'not-applicable'; statusCode = 0; errorCode = ''; durationMs = [long]$started.ElapsedMilliseconds }
    }

    $body = @{
        model = [string]$Model
        stream = $false
        max_tokens = 1
        messages = @(@{ role = 'user'; content = 'PhaseZero validation. Reply OK.' })
    } | ConvertTo-Json -Depth 6 -Compress
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($body)

    try {
        $request = [System.Net.WebRequest]::Create($Url)
        $request.Method = 'POST'
        $request.Timeout = $TimeoutMs
        $request.ReadWriteTimeout = $TimeoutMs
        $request.ContentType = 'application/json'
        $request.ContentLength = $bytes.Length
        try { $request.Proxy = $null } catch { }
        if (-not [string]::IsNullOrWhiteSpace($ApiKey)) {
            $request.Headers['Authorization'] = 'Bearer ' + [string]$ApiKey
        }
        $stream = $request.GetRequestStream()
        try {
            $stream.Write($bytes, 0, $bytes.Length)
        } finally {
            $stream.Close()
            $stream.Dispose()
        }
        $response = $request.GetResponse()
        try {
            $statusCode = [int]$response.StatusCode
            $status = if ($statusCode -ge 200 -and $statusCode -lt 300) { 'validated' } elseif ($statusCode -eq 401 -or $statusCode -eq 403) { 'auth-failed' } else { 'failed' }
        } finally {
            if ($response) { $response.Close(); $response.Dispose() }
        }
    } catch [System.Net.WebException] {
        $errorCode = [string]$_.Exception.Status
        $response = $_.Exception.Response
        if ($response) {
            try {
                $statusCode = [int]$response.StatusCode
                $text = ''
                try {
                    $reader = New-Object System.IO.StreamReader($response.GetResponseStream())
                    try { $text = $reader.ReadToEnd() } finally { $reader.Close(); $reader.Dispose() }
                } catch {
                    $text = ''
                }
                $safeText = Get-BootstrapCleanNativeText -Text $text -MaxLength 1200
                if ($statusCode -eq 401 -or $statusCode -eq 403) {
                    $status = 'auth-failed'
                } elseif ($safeText -match '(?i)\blogin\b|sign in|sess[aã]o|session|cookie|unauth') {
                    $status = 'login-required'
                    $errorCode = 'login-required'
                } else {
                    $status = 'failed'
                }
            } finally {
                $response.Close()
                $response.Dispose()
            }
        } elseif ($_.Exception.Status -eq [System.Net.WebExceptionStatus]::Timeout) {
            $status = 'timeout'
        } else {
            $status = 'unreachable'
        }
    } catch {
        $errorCode = 'exception'
        $status = 'failed'
    } finally {
        $started.Stop()
    }

    return [ordered]@{
        status = $status
        statusCode = [int]$statusCode
        errorCode = $errorCode
        durationMs = [long]$started.ElapsedMilliseconds
    }
}

function Invoke-BootstrapAiProxyWebValidation {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [string]$InstallRoot = '',
        [string]$SourceRoot = '',
        [string]$EnvPath = '',
        [AllowNull()][System.Collections.IDictionary]$RuntimeProbe = $null,
        [switch]$UseCachedOnly,
        [switch]$DryRun,
        [int]$TimeoutMs = 10000
    )
    $started = [Diagnostics.Stopwatch]::StartNew()
    $name = Normalize-BootstrapAiToolName -ToolName $ToolName
    $required = ($CatalogEntry.Contains('RequiresWebLoginValidation') -and [bool]$CatalogEntry['RequiresWebLoginValidation'])
    $kind = if ($CatalogEntry.Contains('WebValidationKind')) { [string]$CatalogEntry['WebValidationKind'] } else { '' }
    $command = if ($CatalogEntry.Contains('WebValidationCommand')) { [string]$CatalogEntry['WebValidationCommand'] } else { [string]$CatalogEntry['LoginCommand'] }
    $baseUrl = [string]$CatalogEntry['BaseUrl']
    $chatUrl = Get-BootstrapAiProxyChatValidationUrl -BaseUrl $baseUrl
    $modelsUrl = Get-BootstrapAiProxyModelsUrl -BaseUrl $baseUrl
    $result = [ordered]@{
        required = [bool]$required
        kind = $kind
        status = 'not-applicable'
        command = $command
        endpoint = $chatUrl
        modelsEndpoint = $modelsUrl
        modelsStatus = ''
        modelsStatusCode = 0
        chatStatusCode = 0
        missing = @()
        durationMs = 0
        recommendedAction = ''
    }
    if (-not $required) {
        $started.Stop()
        $result['durationMs'] = [long]$started.ElapsedMilliseconds
        return $result
    }
    if ($DryRun) {
        $started.Stop()
        $result['status'] = 'planned'
        $result['recommendedAction'] = 'Depois do install/start, validar sessao web local sem expor credenciais.'
        $result['durationMs'] = [long]$started.ElapsedMilliseconds
        return $result
    }

    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    if ([string]::IsNullOrWhiteSpace($SourceRoot)) { $SourceRoot = Get-BootstrapAiProxySourceRoot -ToolName $name -InstallRoot $root }
    if ([string]::IsNullOrWhiteSpace($EnvPath)) { $EnvPath = Join-Path $SourceRoot '.env' }
    $envMap = @{}
    if (Test-Path -LiteralPath $EnvPath) {
        try { $envMap = Read-BootstrapDotEnvFile -Path $EnvPath } catch { $envMap = @{} }
    }
    if ([string]$kind -eq 'env-session') {
        $missing = @(Get-BootstrapAiProxyWebValidationMissingGroups -ToolName $name -EnvMap $envMap)
        if ($missing.Count -gt 0) {
            $started.Stop()
            $result['status'] = 'missing-credentials'
            $result['missing'] = @($missing)
            $result['recommendedAction'] = 'Configure a sessao web local do provider no ambiente do usuario e rode configure/start novamente.'
            $result['durationMs'] = [long]$started.ElapsedMilliseconds
            return $result
        }
    }

    $installed = Test-Path -LiteralPath (Join-Path $SourceRoot '.git')
    $runtimeReady = Test-BootstrapAiProxyRuntimeReady -Runtime ([string]$CatalogEntry['Runtime']) -SourceRoot $SourceRoot
    if (-not $installed -or -not $runtimeReady) {
        $started.Stop()
        $result['status'] = 'not-ready'
        $result['recommendedAction'] = 'Conclua install/deps, inicie o proxy e execute a validacao web novamente.'
        if (-not [string]::IsNullOrWhiteSpace($command)) { $result['recommendedAction'] = $result['recommendedAction'] + (' Se a sessao falhar, rode manualmente: {0}.' -f $command) }
        $result['durationMs'] = [long]$started.ElapsedMilliseconds
        return $result
    }

    $probe = $RuntimeProbe
    if ($null -eq $probe) {
        $probe = Get-BootstrapAiProxyRuntimeProbe -ToolName $name -CatalogEntry $CatalogEntry -SourceRoot $SourceRoot -EnvPath $EnvPath -TimeoutMs 3000
    }
    $result['modelsStatus'] = [string]$probe['modelsStatus']
    $result['modelsStatusCode'] = [int]$probe['modelsStatusCode']
    if (-not [bool]$probe['runtimeAvailable']) {
        $started.Stop()
        $result['status'] = if ([bool]$probe['listening']) { 'failed' } else { 'start-required' }
        if ([string]$probe['modelsStatus'] -eq 'rejected') { $result['status'] = 'auth-failed' }
        $result['recommendedAction'] = 'Inicie o proxy e valide /v1/chat/completions local. Nenhum segredo sera exibido.'
        if (-not [string]::IsNullOrWhiteSpace($command)) { $result['recommendedAction'] = $result['recommendedAction'] + (' Se necessario, rode login manual: {0}.' -f $command) }
        $result['durationMs'] = [long]$started.ElapsedMilliseconds
        return $result
    }

    if ($UseCachedOnly) {
        $statePath = Get-BootstrapAiProxyRuntimeStatePath -ToolName $name -InstallRoot $root
        $cachedStatus = ''
        if (Test-Path -LiteralPath $statePath) {
            try {
                $state = Read-BootstrapJsonFile -Path $statePath
                if (Test-BootstrapMapContainsKey -Map $state -Key 'webValidationStatus') { $cachedStatus = [string]$state['webValidationStatus'] }
            } catch {
                $cachedStatus = ''
            }
        }
        $started.Stop()
        $result['status'] = if ([string]::IsNullOrWhiteSpace($cachedStatus)) { 'validation-required' } else { $cachedStatus }
        $result['recommendedAction'] = if ([string]$result['status'] -eq 'validated') { '' } else { 'Rode install-cli.ps1 --tool ' + $name + ' --start --yes --no-admin para executar validacao web ativa.' }
        $result['durationMs'] = [long]$started.ElapsedMilliseconds
        return $result
    }

    $apiKey = ''
    if (Test-BootstrapMapContainsKey -Map $envMap -Key 'API_KEY') { $apiKey = [string]$envMap['API_KEY'] }
    $chat = Invoke-BootstrapAiProxyChatValidation -Url $chatUrl -Model ([string]$CatalogEntry['DefaultModel']) -ApiKey $apiKey -TimeoutMs $TimeoutMs
    $started.Stop()
    $result['status'] = [string]$chat['status']
    $result['chatStatusCode'] = [int]$chat['statusCode']
    $result['durationMs'] = [long]$started.ElapsedMilliseconds
    $result['recommendedAction'] = switch ([string]$chat['status']) {
        'validated' { '' ; break }
        'auth-failed' { 'A API local rejeitou autenticacao redigida; recrie .env e reinicie o proxy.'; break }
        'login-required' { if ([string]::IsNullOrWhiteSpace($command)) { 'Sessao web requerida; configure login manual do provider.' } else { ('Sessao web requerida; rode login manual: {0}.' -f $command) }; break }
        'timeout' { 'Validacao web excedeu timeout curto; verifique proxy/login e tente novamente.'; break }
        default { 'Validacao web falhou; verifique sessao web/upstream e logs locais do proxy.' }
    }
    return $result
}

function Get-BootstrapAiProxyRuntimeProbe {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$SourceRoot,
        [Parameter(Mandatory = $true)][string]$EnvPath,
        [int]$TimeoutMs = 3000
    )
    $started = [Diagnostics.Stopwatch]::StartNew()
    $port = [int]$CatalogEntry['Port']
    $runtime = [string]$CatalogEntry['Runtime']
    $healthUrl = Get-BootstrapAiProxyHealthUrl -BaseUrl ([string]$CatalogEntry['BaseUrl']) -HealthPath ([string]$CatalogEntry['HealthPath'])
    $modelsUrl = Get-BootstrapAiProxyModelsUrl -BaseUrl ([string]$CatalogEntry['BaseUrl'])
    $apiKey = ''
    if (Test-Path -LiteralPath $EnvPath) {
        try {
            $envMap = Read-BootstrapDotEnvFile -Path $EnvPath
            if (Test-BootstrapMapContainsKey -Map $envMap -Key 'API_KEY') { $apiKey = [string]$envMap['API_KEY'] }
        } catch {
            $apiKey = ''
        }
    }

    if ($port -le 0 -or $runtime -eq 'tauri') {
        $started.Stop()
        return [ordered]@{
            listening = $false
            pid = @()
            processName = @()
            healthStatus = 'not-applicable'
            healthStatusCode = 0
            modelsStatus = 'not-applicable'
            modelsStatusCode = 0
            healthUrl = ''
            modelsUrl = ''
            runtimeAvailable = $false
            durationMs = [long]$started.ElapsedMilliseconds
        }
    }

    $pids = @(Get-BootstrapAiProxyListeningProcessIds -Port $port)
    $listening = ($pids.Count -gt 0)
    $health = [ordered]@{ status = 'unreachable'; statusCode = 0; errorCode = ''; durationMs = 0 }
    $models = [ordered]@{ status = 'unreachable'; statusCode = 0; errorCode = ''; durationMs = 0 }
    if ($listening) {
        $health = Invoke-BootstrapAiProxyHttpProbe -Url $healthUrl -ApiKey $apiKey -TimeoutMs $TimeoutMs
        $models = Invoke-BootstrapAiProxyHttpProbe -Url $modelsUrl -ApiKey $apiKey -TimeoutMs $TimeoutMs
    }
    $started.Stop()
    return [ordered]@{
        listening = [bool]$listening
        pid = @($pids)
        processName = @(Get-BootstrapAiProxyProcessNames -ProcessIds $pids)
        healthStatus = [string]$health['status']
        healthStatusCode = [int]$health['statusCode']
        modelsStatus = [string]$models['status']
        modelsStatusCode = [int]$models['statusCode']
        healthUrl = $healthUrl
        modelsUrl = $modelsUrl
        runtimeAvailable = ([string]$models['status'] -eq 'ok')
        durationMs = [long]$started.ElapsedMilliseconds
    }
}

function Get-BootstrapAiProxyToolDoctorReport {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [string]$InstallRoot = ''
    )
    $name = Normalize-BootstrapAiToolName -ToolName $ToolName
    $catalog = Get-BootstrapAiProxyCatalog
    if (-not $catalog.Contains($name)) { return $null }
    $entry = $catalog[$name]
    $sourceRoot = Get-BootstrapAiProxySourceRoot -ToolName $name -InstallRoot $InstallRoot
    $envPath = Join-Path $sourceRoot '.env'
    $installed = Test-Path -LiteralPath (Join-Path $sourceRoot '.git')
    $filesConfigured = Test-Path -LiteralPath $envPath
    $runtimeReady = $false
    $runtime = [string]$entry['Runtime']
    $runtimeReady = Test-BootstrapAiProxyRuntimeReady -Runtime $runtime -SourceRoot $sourceRoot
    $probe = Get-BootstrapAiProxyRuntimeProbe -ToolName $name -CatalogEntry $entry -SourceRoot $sourceRoot -EnvPath $envPath -TimeoutMs 3000
    $httpProxy = ([int]$entry['Port'] -gt 0 -and $runtime -ne 'tauri')
    $webValidation = Invoke-BootstrapAiProxyWebValidation -ToolName $name -CatalogEntry $entry -InstallRoot $InstallRoot -SourceRoot $sourceRoot -EnvPath $envPath -RuntimeProbe $probe -UseCachedOnly
    $webValidationOk = (-not [bool]$webValidation['required'] -or [string]$webValidation['status'] -eq 'validated')
    $configured = if ($httpProxy) { ($installed -and $filesConfigured -and $runtimeReady -and [bool]$probe['runtimeAvailable'] -and $webValidationOk) } else { ($installed -and $runtimeReady) }
    $status = 'missing'
    if ($configured) {
        $status = 'configured'
    } elseif ($installed -and $filesConfigured -and $runtimeReady -and $httpProxy -and [string]$webValidation['status'] -eq 'missing-credentials') {
        $status = 'auth-failed'
    } elseif ($installed -and $filesConfigured -and $runtimeReady -and $httpProxy -and [string]$webValidation['status'] -eq 'login-required') {
        $status = 'auth-failed'
    } elseif ($installed -and $filesConfigured -and $runtimeReady -and $httpProxy -and [bool]$probe['runtimeAvailable'] -and -not $webValidationOk) {
        $status = 'unhealthy'
    } elseif ($installed -and $filesConfigured -and $runtimeReady -and $httpProxy -and [string]$probe['modelsStatus'] -eq 'rejected') {
        $status = 'auth-failed'
    } elseif ($installed -and $filesConfigured -and $runtimeReady -and $httpProxy -and [bool]$probe['listening']) {
        $status = 'unhealthy'
    } elseif ($installed -and $filesConfigured -and $runtimeReady -and $httpProxy) {
        $status = 'start-required'
    } elseif ($installed -or $filesConfigured) {
        $status = 'warning'
    }
    $recommendedAction = switch ($status) {
        'configured' { '' ; break }
        'auth-failed' { ("Verifique o .env local de {0} e reinicie o proxy; valores permanecem redigidos." -f $name); break }
        'unhealthy' { ("{0} esta ouvindo, mas validacao web falhou; verifique upstream/login local e logs do proxy." -f $name); break }
        'start-required' { ("Execute install-cli.ps1 --tool {0} --start --yes --no-admin ou o componente ai-proxy-suite." -f $name); break }
        'warning' { ("Execute componente {0} para concluir clone/deps/.env." -f $name); break }
        default { ("Execute componente {0} para instalar e configurar." -f $name) }
    }
    return [ordered]@{
        id = $name
        name = [string]$entry['DisplayName']
        status = $status
        installed = [bool]$installed
        configured = [bool]$configured
        filesConfigured = [bool]$filesConfigured
        runtimeReady = [bool]$runtimeReady
        runtimeAvailable = [bool]$probe['runtimeAvailable']
        listening = [bool]$probe['listening']
        pid = @($probe['pid'])
        processName = @($probe['processName'])
        healthStatus = [string]$probe['healthStatus']
        healthStatusCode = [int]$probe['healthStatusCode']
        modelsStatus = [string]$probe['modelsStatus']
        modelsStatusCode = [int]$probe['modelsStatusCode']
        healthUrl = [string]$probe['healthUrl']
        modelsUrl = [string]$probe['modelsUrl']
        runtimeProbeDurationMs = [long]$probe['durationMs']
        webValidation = $webValidation
        recommendedAction = $recommendedAction
        sourceRoot = $sourceRoot
        envPath = $(if ($filesConfigured) { $envPath } else { '' })
        repo = [string]$entry['GitHubRepo']
        port = [int]$entry['Port']
        baseUrl = [string]$entry['BaseUrl']
        defaultModel = [string]$entry['DefaultModel']
        preferredDefault = [bool]$entry['PreferredDefault']
        startCommand = [string]$entry['StartCommand']
        loginCommand = [string]$entry['LoginCommand']
    }
}

function New-BootstrapAiProxySuiteDoctorReport {
    param([string]$InstallRoot = '')
    $started = [Diagnostics.Stopwatch]::StartNew()
    $catalog = Get-BootstrapAiProxyCatalog
    $items = @($catalog.Keys | ForEach-Object { Get-BootstrapAiProxyToolDoctorReport -ToolName ([string]$_) -InstallRoot $InstallRoot })
    $started.Stop()
    $httpProviders = @($items | Where-Object { [int]$_['port'] -gt 0 })
    $configured = @($httpProviders | Where-Object { [string]$_['status'] -eq 'configured' })
    $desktopConfigured = @($items | Where-Object { [int]$_['port'] -le 0 -and [string]$_['status'] -eq 'configured' })
    $runtimeReady = @($items | Where-Object { [bool]$_['runtimeReady'] })
    $startRequired = @($items | Where-Object { [string]$_['status'] -eq 'start-required' })
    $authFailed = @($items | Where-Object { [string]$_['status'] -eq 'auth-failed' })
    $unhealthy = @($items | Where-Object { [string]$_['status'] -eq 'unhealthy' })
    $partial = @($items | Where-Object { [string]$_['status'] -eq 'warning' })
    $status = 'missing'
    if ($httpProviders.Count -gt 0 -and $configured.Count -eq $httpProviders.Count) {
        $status = 'ready'
    } elseif ($unhealthy.Count -gt 0) {
        $status = 'degraded'
    } elseif ($startRequired.Count -gt 0 -or $authFailed.Count -gt 0) {
        $status = 'start-required'
    } elseif ($runtimeReady.Count -gt 0 -or $partial.Count -gt 0) {
        $status = 'warning'
    }
    return [ordered]@{
        schemaVersion = 1
        status = $status
        durationMs = [long]$started.ElapsedMilliseconds
        defaultProvider = 'kimiproxy'
        defaultBaseUrl = [string]$catalog['kimiproxy']['BaseUrl']
        defaultModel = [string]$catalog['kimiproxy']['DefaultModel']
        configuredProviders = [int]$configured.Count
        runtimeReadyProviders = [int]$runtimeReady.Count
        startRequiredProviders = [int]$startRequired.Count
        authFailedProviders = [int]$authFailed.Count
        unhealthyProviders = [int]$unhealthy.Count
        desktopConfiguredProviders = [int]$desktopConfigured.Count
        operationalProviders = @($configured | ForEach-Object { [string]$_['id'] })
        desktopConfiguredProviderIds = @($desktopConfigured | ForEach-Object { [string]$_['id'] })
        startRequiredProviderIds = @($startRequired | ForEach-Object { [string]$_['id'] })
        unhealthyProviderIds = @($unhealthy | ForEach-Object { [string]$_['id'] })
        providers = @($items)
        manifestPath = Get-BootstrapAiProxyManifestPath -InstallRoot $InstallRoot
    }
}

function Get-BootstrapAiProxyStartPlan {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [string]$InstallRoot = ''
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $sourceRoot = Get-BootstrapAiProxySourceRoot -ToolName $ToolName -InstallRoot $root
    $runtime = [string]$CatalogEntry['Runtime']
    $exe = ''
    $argumentList = @()
    $runtimeAvailable = $true
    $runtimeWarning = ''
    if ($runtime -eq 'node') {
        try {
            $exe = Get-BootstrapNpmCommandForAiTools
        } catch {
            $exe = 'npm'
            $runtimeAvailable = $false
            $runtimeWarning = $_.Exception.Message
        }
        $argumentList = @('run','start')
    } elseif ($runtime -eq 'go') {
        $bin = Join-Path (Join-Path $sourceRoot 'bin') 'mimo-ai-proxy.exe'
        if (Test-Path -LiteralPath $bin) {
            $exe = $bin
            $argumentList = @()
        } else {
            $go = Resolve-CommandPath -Name 'go'
            if ($go) {
                $exe = $go
                $argumentList = @('run','main.go')
            }
        }
        if ([string]::IsNullOrWhiteSpace($exe)) {
            $runtimeAvailable = $false
            $runtimeWarning = 'go runtime nao encontrado.'
        }
    } elseif ($runtime -eq 'tauri') {
        $exe = ''
        $argumentList = @()
    }

    $commandText = if ([string]::IsNullOrWhiteSpace($exe)) { '' } else { ((@($exe) + @($argumentList)) -join ' ') }
    return [ordered]@{
        tool = $ToolName
        runtime = $runtime
        exe = $exe
        args = @($argumentList)
        workingDirectory = $sourceRoot
        command = $commandText
        runtimeAvailable = [bool]$runtimeAvailable
        runtimeWarning = $runtimeWarning
        port = [int]$CatalogEntry['Port']
        baseUrl = [string]$CatalogEntry['BaseUrl']
        modelsUrl = Get-BootstrapAiProxyModelsUrl -BaseUrl ([string]$CatalogEntry['BaseUrl'])
    }
}

function Wait-BootstrapAiProxyRuntime {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$SourceRoot,
        [Parameter(Mandatory = $true)][string]$EnvPath,
        [int]$TimeoutMs = 30000
    )
    $started = [Diagnostics.Stopwatch]::StartNew()
    $probe = Get-BootstrapAiProxyRuntimeProbe -ToolName $ToolName -CatalogEntry $CatalogEntry -SourceRoot $SourceRoot -EnvPath $EnvPath -TimeoutMs 3000
    while (-not [bool]$probe['runtimeAvailable'] -and [long]$started.ElapsedMilliseconds -lt $TimeoutMs) {
        if ([string]$probe['modelsStatus'] -eq 'rejected') { break }
        Start-Sleep -Milliseconds 750
        $probe = Get-BootstrapAiProxyRuntimeProbe -ToolName $ToolName -CatalogEntry $CatalogEntry -SourceRoot $SourceRoot -EnvPath $EnvPath -TimeoutMs 3000
    }
    $started.Stop()
    $probe['waitDurationMs'] = [long]$started.ElapsedMilliseconds
    return $probe
}

function Start-BootstrapAiProxyTool {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [string]$InstallRoot = '',
        [switch]$DryRun,
        [int]$TimeoutMs = 60000
    )
    $name = Normalize-BootstrapAiToolName -ToolName $ToolName
    $catalog = Get-BootstrapAiProxyCatalog
    if (-not $catalog.Contains($name)) {
        return (New-BootstrapAiToolResult -ToolName $name -Action 'start' -Status 'blocked' -InstallRoot $InstallRoot -Message 'Proxy local desconhecido.' -Docs '')
    }
    $entry = $catalog[$name]
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $sourceRoot = Get-BootstrapAiProxySourceRoot -ToolName $name -InstallRoot $root
    $envPath = Join-Path $sourceRoot '.env'
    $runtime = [string]$entry['Runtime']
    $plan = Get-BootstrapAiProxyStartPlan -ToolName $name -CatalogEntry $entry -InstallRoot $root

    if ([int]$entry['Port'] -le 0 -or $runtime -eq 'tauri') {
        $result = New-BootstrapAiToolResult -ToolName $name -Action 'start' -Status 'skipped' -InstallRoot $root -Message 'Runtime desktop sem API HTTP local para iniciar via PhaseZero.' -Docs ([string]$entry['DocsUrl'])
        return (Add-BootstrapAiProxyResultField -Result $result -CatalogEntry $entry -InstallRoot $root -EnvPath $envPath -ManifestPath (Get-BootstrapAiProxyManifestPath -InstallRoot $root))
    }

    if ($DryRun) {
        $result = New-BootstrapAiToolResult -ToolName $name -Action 'start' -Status 'planned' -InstallRoot $root -Message ("Start {0}: {1}; validar {2}" -f $name, [string]$plan['command'], [string]$plan['modelsUrl']) -Docs ([string]$entry['DocsUrl'])
        $result['startPlan'] = [ordered]@{
            command = [string]$plan['command']
            workingDirectory = [string]$plan['workingDirectory']
            runtimeAvailable = [bool]$plan['runtimeAvailable']
            runtimeWarning = [string]$plan['runtimeWarning']
            port = [int]$plan['port']
            modelsUrl = [string]$plan['modelsUrl']
        }
        $result['webValidation'] = Invoke-BootstrapAiProxyWebValidation -ToolName $name -CatalogEntry $entry -InstallRoot $root -SourceRoot $sourceRoot -EnvPath $envPath -DryRun
        return (Add-BootstrapAiProxyResultField -Result $result -CatalogEntry $entry -InstallRoot $root -EnvPath $envPath -ManifestPath (Get-BootstrapAiProxyManifestPath -InstallRoot $root))
    }

    $doctor = Get-BootstrapAiProxyToolDoctorReport -ToolName $name -InstallRoot $root
    if ([bool]$doctor['runtimeAvailable']) {
        $doctorProbe = [ordered]@{
            listening = [bool]$doctor['listening']
            pid = @($doctor['pid'])
            processName = @($doctor['processName'])
            healthStatus = [string]$doctor['healthStatus']
            healthStatusCode = [int]$doctor['healthStatusCode']
            modelsStatus = [string]$doctor['modelsStatus']
            modelsStatusCode = [int]$doctor['modelsStatusCode']
            healthUrl = [string]$doctor['healthUrl']
            modelsUrl = [string]$doctor['modelsUrl']
            runtimeAvailable = [bool]$doctor['runtimeAvailable']
            durationMs = [long]$doctor['runtimeProbeDurationMs']
        }
        $webValidation = Invoke-BootstrapAiProxyWebValidation -ToolName $name -CatalogEntry $entry -InstallRoot $root -SourceRoot $sourceRoot -EnvPath $envPath -RuntimeProbe $doctorProbe
        $status = if ([string]$webValidation['status'] -eq 'auth-failed') { 'auth-failed' } else { 'running' }
        $message = if ($status -eq 'running' -and (-not [bool]$webValidation['required'] -or [string]$webValidation['status'] -eq 'validated')) {
            ("{0} ja responde em {1}." -f $name, [string]$doctor['modelsUrl'])
        } elseif ($status -eq 'running') {
            ("{0} responde /v1/models; validacao web esta {1}." -f $name, [string]$webValidation['status'])
        } else {
            ("{0} responde /v1/models, mas validacao web esta {1}." -f $name, [string]$webValidation['status'])
        }
        $result = New-BootstrapAiToolResult -ToolName $name -Action 'start' -Status $status -InstallRoot $root -Message $message -Docs ([string]$entry['DocsUrl'])
        $result['runtimeProbe'] = [ordered]@{
            listening = [bool]$doctor['listening']
            pid = @($doctor['pid'])
            healthStatus = [string]$doctor['healthStatus']
            modelsStatus = [string]$doctor['modelsStatus']
            modelsUrl = [string]$doctor['modelsUrl']
        }
        $result['webValidation'] = $webValidation
        $statePath = Get-BootstrapAiProxyRuntimeStatePath -ToolName $name -InstallRoot $root
        try {
            Write-BootstrapJsonFile -Path $statePath -Value ([ordered]@{
                tool = $name
                status = $status
                pid = if (@($doctor['pid']).Count -gt 0) { [int]@($doctor['pid'])[0] } else { 0 }
                checkedAt = (Get-Date).ToString('o')
                port = [int]$entry['Port']
                baseUrl = [string]$entry['BaseUrl']
                modelsUrl = [string]$doctor['modelsUrl']
                healthStatus = [string]$doctor['healthStatus']
                modelsStatus = [string]$doctor['modelsStatus']
                webValidationStatus = [string]$webValidation['status']
            })
            $result['statePath'] = $statePath
        } catch {
        }
        return (Add-BootstrapAiProxyResultField -Result $result -CatalogEntry $entry -InstallRoot $root -EnvPath $envPath -ManifestPath (Get-BootstrapAiProxyManifestPath -InstallRoot $root))
    }

    if (-not [bool]$doctor['installed'] -or -not [bool]$doctor['filesConfigured'] -or -not [bool]$doctor['runtimeReady']) {
        $result = New-BootstrapAiToolResult -ToolName $name -Action 'start' -Status 'blocked' -InstallRoot $root -Message ("{0} nao esta pronto para start: instale clone/deps/.env antes." -f $name) -Docs ([string]$entry['DocsUrl'])
        $result['readiness'] = [ordered]@{
            installed = [bool]$doctor['installed']
            filesConfigured = [bool]$doctor['filesConfigured']
            runtimeReady = [bool]$doctor['runtimeReady']
        }
        return (Add-BootstrapAiProxyResultField -Result $result -CatalogEntry $entry -InstallRoot $root -EnvPath $envPath -ManifestPath (Get-BootstrapAiProxyManifestPath -InstallRoot $root))
    }

    if ([bool]$doctor['listening']) {
        $doctorWebValidation = if (Test-BootstrapMapContainsKey -Map $doctor -Key 'webValidation') { $doctor['webValidation'] } else { $null }
        $browserSessionPending = (($doctorWebValidation -is [System.Collections.IDictionary]) -and [bool]$doctorWebValidation['required'] -and [string]$doctorWebValidation['kind'] -eq 'browser-session' -and [string]$doctor['healthStatus'] -eq 'ok')
        $status = if ($browserSessionPending) { 'running' } elseif ([string]$doctor['modelsStatus'] -eq 'rejected') { 'auth-failed' } else { 'error' }
        $message = if ($browserSessionPending) {
            ("{0} ja esta ouvindo e /health esta ok; /v1/models esta {1}. Validacao web/login pode ser necessaria." -f $name, [string]$doctor['modelsStatus'])
        } else {
            ("{0} ja esta ouvindo, mas /v1/models esta {1} ({2}); nao iniciei processo duplicado." -f $name, [string]$doctor['modelsStatus'], [int]$doctor['modelsStatusCode'])
        }
        $result = New-BootstrapAiToolResult -ToolName $name -Action 'start' -Status $status -InstallRoot $root -Message $message -Docs ([string]$entry['DocsUrl'])
        $result['runtimeProbe'] = [ordered]@{
            listening = [bool]$doctor['listening']
            pid = @($doctor['pid'])
            healthStatus = [string]$doctor['healthStatus']
            healthStatusCode = [int]$doctor['healthStatusCode']
            modelsStatus = [string]$doctor['modelsStatus']
            modelsStatusCode = [int]$doctor['modelsStatusCode']
            modelsUrl = [string]$doctor['modelsUrl']
        }
        $result['webValidation'] = $doctor['webValidation']
        return (Add-BootstrapAiProxyResultField -Result $result -CatalogEntry $entry -InstallRoot $root -EnvPath $envPath -ManifestPath (Get-BootstrapAiProxyManifestPath -InstallRoot $root))
    }

    if (-not [bool]$plan['runtimeAvailable'] -or [string]::IsNullOrWhiteSpace([string]$plan['exe'])) {
        $detail = [string]$plan['runtimeWarning']
        if ([string]::IsNullOrWhiteSpace($detail)) { $detail = 'runtime de start indisponivel' }
        $result = New-BootstrapAiToolResult -ToolName $name -Action 'start' -Status 'blocked' -InstallRoot $root -Message ("Runtime de start indisponivel para {0}: {1}." -f $name, $detail) -Docs ([string]$entry['DocsUrl'])
        return (Add-BootstrapAiProxyResultField -Result $result -CatalogEntry $entry -InstallRoot $root -EnvPath $envPath -ManifestPath (Get-BootstrapAiProxyManifestPath -InstallRoot $root))
    }

    $playwrightRuntime = [ordered]@{ status = 'skipped'; changed = $false }
    if ([bool]$entry['Playwright']) {
        try {
            $playwrightRuntime = Ensure-BootstrapAiProxyPlaywrightRuntime -CatalogEntry $entry -SourceRoot $sourceRoot
        } catch {
            $detail = Get-BootstrapCleanNativeText -Text $_.Exception.Message -MaxLength 500
            $result = New-BootstrapAiToolResult -ToolName $name -Action 'start' -Status 'blocked' -InstallRoot $root -Message ("Playwright runtime indisponivel para {0}: {1}. Rode install/start novamente apos liberar rede/cache." -f $name, $detail) -Docs ([string]$entry['DocsUrl'])
            $result['playwrightRuntime'] = [ordered]@{ status = 'error'; message = $detail }
            return (Add-BootstrapAiProxyResultField -Result $result -CatalogEntry $entry -InstallRoot $root -EnvPath $envPath -ManifestPath (Get-BootstrapAiProxyManifestPath -InstallRoot $root))
        }
    }

    $logRoot = Get-BootstrapAiProxyLogRoot -InstallRoot $root
    [void][System.IO.Directory]::CreateDirectory($logRoot)
    $stdoutPath = Join-Path $logRoot ("{0}-{1}.out.log" -f $name, $script:RunId)
    $stderrPath = Join-Path $logRoot ("{0}-{1}.err.log" -f $name, $script:RunId)
    $proc = $null
    $startError = $null
    try {
        $startParams = @{
            FilePath = [string]$plan['exe']
            WorkingDirectory = [string]$plan['workingDirectory']
            RedirectStandardOutput = $stdoutPath
            RedirectStandardError = $stderrPath
            WindowStyle = 'Hidden'
            PassThru = $true
            ErrorAction = 'Stop'
        }
        $startArgs = @($plan['args'] | Where-Object { $null -ne $_ -and -not [string]::IsNullOrWhiteSpace([string]$_) })
        if ($startArgs.Count -gt 0) { $startParams['ArgumentList'] = $startArgs }
        $proc = Start-Process @startParams
    } catch {
        $startError = $_
        if ($runtime -eq 'go' -and [string]$plan['exe'] -match 'mimo-ai-proxy\.exe$') {
            $go = Resolve-CommandPath -Name 'go'
            if ($go) {
                try {
                    $fallbackParams = @{}
                    foreach ($key in @($startParams.Keys)) { $fallbackParams[$key] = $startParams[$key] }
                    $fallbackParams['FilePath'] = $go
                    $fallbackParams['ArgumentList'] = @('run','main.go')
                    $proc = Start-Process @fallbackParams
                    $plan['command'] = ('{0} run main.go' -f $go)
                } catch {
                    $startError = $_
                }
            }
        }
    }
    if (-not $proc) {
        $startMessage = if ($startError) { (Get-BootstrapCleanNativeText -Text $startError.Exception.Message -MaxLength 240) } else { 'erro desconhecido' }
        $result = New-BootstrapAiToolResult -ToolName $name -Action 'start' -Status 'error' -InstallRoot $root -Message ("Falha ao iniciar {0}: {1}" -f $name, $startMessage) -Docs ([string]$entry['DocsUrl'])
        $result['logPath'] = $stdoutPath
        $result['errorLogPath'] = $stderrPath
        return (Add-BootstrapAiProxyResultField -Result $result -CatalogEntry $entry -InstallRoot $root -EnvPath $envPath -ManifestPath (Get-BootstrapAiProxyManifestPath -InstallRoot $root))
    }

    $wait = Wait-BootstrapAiProxyRuntime -ToolName $name -CatalogEntry $entry -SourceRoot $sourceRoot -EnvPath $envPath -TimeoutMs $TimeoutMs
    $webValidation = Invoke-BootstrapAiProxyWebValidation -ToolName $name -CatalogEntry $entry -InstallRoot $root -SourceRoot $sourceRoot -EnvPath $envPath -RuntimeProbe $wait
    $webValidationOk = (-not [bool]$webValidation['required'] -or [string]$webValidation['status'] -eq 'validated')
    $status = if ([bool]$wait['runtimeAvailable']) { 'started' } elseif ([string]$webValidation['status'] -eq 'login-required' -or [string]$webValidation['status'] -eq 'missing-credentials') { 'login-required' } elseif ([string]$wait['modelsStatus'] -eq 'rejected' -or [string]$webValidation['status'] -eq 'auth-failed') { 'auth-failed' } else { 'error' }
    $message = if ($status -eq 'started' -and $webValidationOk) {
        ("{0} responde em {1}." -f $name, [string]$wait['modelsUrl'])
    } elseif ($status -eq 'started') {
        ("{0} responde em {1}; validacao web esta {2}." -f $name, [string]$wait['modelsUrl'], [string]$webValidation['status'])
    } elseif ($status -eq 'auth-failed') {
        ("{0} iniciou, mas /v1/models rejeitou autenticacao local redigida." -f $name)
    } elseif ($status -eq 'login-required') {
        ("{0} iniciou, mas validacao web requer login/sessao local." -f $name)
    } else {
        ("{0} iniciou PID {1}, mas /v1/models nao respondeu dentro de {2}ms." -f $name, [int]$proc.Id, $TimeoutMs)
    }
    $statePath = Get-BootstrapAiProxyRuntimeStatePath -ToolName $name -InstallRoot $root
    $state = [ordered]@{
        tool = $name
        status = $status
        pid = [int]$proc.Id
        startedAt = (Get-Date).ToString('o')
        port = [int]$entry['Port']
        baseUrl = [string]$entry['BaseUrl']
        modelsUrl = [string]$wait['modelsUrl']
        healthStatus = [string]$wait['healthStatus']
        modelsStatus = [string]$wait['modelsStatus']
        webValidationStatus = [string]$webValidation['status']
        logPath = $stdoutPath
        errorLogPath = $stderrPath
    }
    try { Write-BootstrapJsonFile -Path $statePath -Value $state } catch { }

    $result = New-BootstrapAiToolResult -ToolName $name -Action 'start' -Status $status -InstallRoot $root -Message $message -Docs ([string]$entry['DocsUrl'])
    $result['pid'] = [int]$proc.Id
    $result['logPath'] = $stdoutPath
    $result['errorLogPath'] = $stderrPath
    $result['statePath'] = $statePath
    $result['playwrightRuntime'] = $playwrightRuntime
    $result['runtimeProbe'] = [ordered]@{
        listening = [bool]$wait['listening']
        pid = @($wait['pid'])
        healthStatus = [string]$wait['healthStatus']
        healthStatusCode = [int]$wait['healthStatusCode']
        modelsStatus = [string]$wait['modelsStatus']
        modelsStatusCode = [int]$wait['modelsStatusCode']
        modelsUrl = [string]$wait['modelsUrl']
        waitDurationMs = [long]$wait['waitDurationMs']
    }
    $result['webValidation'] = $webValidation
    return (Add-BootstrapAiProxyResultField -Result $result -CatalogEntry $entry -InstallRoot $root -EnvPath $envPath -ManifestPath (Get-BootstrapAiProxyManifestPath -InstallRoot $root))
}

function Get-BootstrapAiProxySuiteStartClassification {
    param(
        [AllowNull()][object[]]$Items = @(),
        [switch]$DryRun
    )

    $itemsList = @($Items)
    $ok = @($itemsList | Where-Object { [string]$_['status'] -in @('started','running','planned') })
    $bad = @($itemsList | Where-Object { [string]$_['status'] -notin @('started','running','planned') })
    $default = @($itemsList | Where-Object { [string]$_['tool'] -eq 'kimiproxy' } | Select-Object -First 1)
    $defaultStatus = if ($default.Count -gt 0) { [string]$default[0]['status'] } else { 'missing' }
    $defaultOk = ($defaultStatus -in @('started','running','planned'))
    $status = if ($DryRun) {
        'planned'
    } elseif ($itemsList.Count -eq 0) {
        'missing'
    } elseif ($defaultOk -and $bad.Count -eq 0) {
        'started'
    } elseif ($defaultOk) {
        'degraded'
    } elseif ($ok.Count -gt 0) {
        'degraded'
    } else {
        'error'
    }

    return [ordered]@{
        status = $status
        okCount = [int]$ok.Count
        degradedCount = [int]$bad.Count
        totalCount = [int]$itemsList.Count
        defaultProvider = 'kimiproxy'
        defaultProviderStatus = $defaultStatus
    }
}

function Start-BootstrapAiProxySuite {
    param(
        [string]$InstallRoot = '',
        [switch]$DryRun,
        [int]$TimeoutMs = 60000
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $catalog = Get-BootstrapAiProxyCatalog
    $results = New-Object System.Collections.Generic.List[object]
    foreach ($name in @($catalog.Keys)) {
        $entry = $catalog[$name]
        if ([int]$entry['Port'] -le 0) { continue }
        $start = Start-BootstrapAiProxyTool -ToolName ([string]$name) -InstallRoot $root -DryRun:$DryRun -TimeoutMs $TimeoutMs
        $results.Add([ordered]@{
            tool = [string]$start['tool']
            status = [string]$start['status']
            port = [int]$start['port']
            baseUrl = [string]$start['baseUrl']
            modelsUrl = if (Test-BootstrapMapContainsKey -Map $start -Key 'runtimeProbe') { [string]$start['runtimeProbe']['modelsUrl'] } elseif (Test-BootstrapMapContainsKey -Map $start -Key 'startPlan') { [string]$start['startPlan']['modelsUrl'] } else { Get-BootstrapAiProxyModelsUrl -BaseUrl ([string]$start['baseUrl']) }
            pid = if (Test-BootstrapMapContainsKey -Map $start -Key 'pid') { [int]$start['pid'] } else { 0 }
            logPath = if (Test-BootstrapMapContainsKey -Map $start -Key 'logPath') { [string]$start['logPath'] } else { '' }
            webValidationStatus = if (Test-BootstrapMapContainsKey -Map $start -Key 'webValidation') { [string]$start['webValidation']['status'] } else { '' }
            message = [string]$start['message']
        }) | Out-Null
    }
    $items = @($results.ToArray())
    $classification = Get-BootstrapAiProxySuiteStartClassification -Items $items -DryRun:$DryRun
    $status = [string]$classification['status']
    $message = if ($DryRun) {
        ("Start AI proxy suite planejado: {0} provider(s) HTTP." -f $items.Count)
    } else {
        ("Start AI proxy suite: {0}/{1} provider(s) OK; default {2}={3}." -f [int]$classification['okCount'], [int]$classification['totalCount'], [string]$classification['defaultProvider'], [string]$classification['defaultProviderStatus'])
    }
    $result = New-BootstrapAiToolResult -ToolName 'ai-proxy-suite' -Action 'start' -Status $status -InstallRoot $root -Message $message -Docs 'https://github.com/pedrofariasx/kimiproxy'
    $result['startResults'] = @($items)
    $result['okCount'] = [int]$classification['okCount']
    $result['degradedCount'] = [int]$classification['degradedCount']
    $result['totalCount'] = [int]$classification['totalCount']
    $result['defaultProvider'] = [string]$classification['defaultProvider']
    $result['defaultProviderStatus'] = [string]$classification['defaultProviderStatus']
    if (-not $DryRun) {
        $result['doctor'] = New-BootstrapAiProxySuiteDoctorReport -InstallRoot $root
    }
    return $result
}

function Add-BootstrapAionUiPlanField {
    param(
        [Parameter(Mandatory = $true)]$Result,
        [string]$Source = 'winget'
    )
    $Result['source'] = $Source
    $Result['wingetId'] = 'iOfficeAI.AionUi'
    $Result['architecture'] = Get-BootstrapAionUiArchitecture
    $Result['downloadUrl'] = 'https://aionui.com/download/'
    $Result['repo'] = 'iOfficeAI/AionUi'
    $Result['wikiUrl'] = 'https://github.com/iOfficeAI/AionUi/wiki/LLM-Configuration'
    $Result['providerEnv'] = @(Get-BootstrapAionUiEnvProviderCandidates)
    return $Result
}

function Install-BootstrapAionUiComponentPackage {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [AllowNull()][hashtable]$State = $null,
        [switch]$DryRun,
        [switch]$NoAdmin
    )

    if ($DryRun) {
        $message = 'winget install -e --id iOfficeAI.AionUi --scope user; fallback oficial .exe somente com silent args documentados.'
        $result = New-BootstrapAiToolResult -ToolName 'aionui' -Action 'install' -Status 'planned' -Message $message -Docs ([string]$CatalogEntry['DocsUrl'])
        return (Add-BootstrapAionUiPlanField -Result $result -Source 'winget')
    }

    $info = Get-BootstrapAionUiInstallInfo
    if ([bool]$info['installed']) {
        $result = New-BootstrapAiToolResult -ToolName 'aionui' -Action 'install' -Status 'installed' -Message 'AionUI ja instalado.' -Docs ([string]$CatalogEntry['DocsUrl']) -CommandPath ([string]$info['exePath']) -Version ([string]$info['version'])
        return (Add-BootstrapAionUiPlanField -Result $result -Source 'existing')
    }

    if (-not (Test-BootstrapHostIsWindows)) {
        $result = New-BootstrapAiToolResult -ToolName 'aionui' -Action 'install' -Status 'blocked' -Message 'AionUI Windows installer requer Windows.' -Docs ([string]$CatalogEntry['DocsUrl'])
        return (Add-BootstrapAionUiPlanField -Result $result -Source 'winget')
    }

    $winget = Get-Winget
    if (-not $winget) {
        $result = New-BootstrapAiToolResult -ToolName 'aionui' -Action 'install' -Status 'blocked' -Message 'winget ausente; baixe o instalador oficial em https://aionui.com/download/ ou instale winget.' -Docs ([string]$CatalogEntry['DocsUrl'])
        return (Add-BootstrapAionUiPlanField -Result $result -Source 'official-exe')
    }

    $probePaths = @($CatalogEntry['ProbePaths'])
    $allowFailure = [bool]$NoAdmin
    Ensure-WingetPackage -WingetPath $winget -Id ([string]$CatalogEntry['WingetId']) -DisplayName 'AionUI' -PreferUserScope $false -AllowFailureWhenNotAdmin $allowFailure -ProbePaths $probePaths -State $State -ComponentName 'aionui'
    $info = Get-BootstrapAionUiInstallInfo
    if (-not [bool]$info['installed']) {
        $status = if ($allowFailure -and -not (Test-IsAdmin)) { 'blocked' } else { 'manual' }
        $message = 'winget concluiu ou foi pulado, mas AionUI exe nao foi encontrado; instale via download oficial ou execute elevado.'
        $result = New-BootstrapAiToolResult -ToolName 'aionui' -Action 'install' -Status $status -Message $message -Docs ([string]$CatalogEntry['DocsUrl'])
        return (Add-BootstrapAionUiPlanField -Result $result -Source 'winget')
    }

    $config = Set-BootstrapAionUiProviderConfig -StartOnce
    $message = 'AionUI instalado via winget oficial. Provider config requer schema estavel; nenhuma chave foi impressa ou gravada pelo PhaseZero.'
    if (@($config['detectedProviders']).Count -gt 0) {
        $message = $message + (" Providers detectados no ambiente: {0}." -f ((@($config['detectedProviders']) | Sort-Object) -join ', '))
    }
    $result = New-BootstrapAiToolResult -ToolName 'aionui' -Action 'install' -Status 'installed' -Message $message -Docs ([string]$CatalogEntry['DocsUrl']) -CommandPath ([string]$info['exePath']) -Version ([string]$info['version'])
    $result['configuration'] = $config
    return (Add-BootstrapAionUiPlanField -Result $result -Source 'winget')
}

function Install-BootstrapAiNpmTool {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [switch]$DryRun
    )
    if ((Normalize-BootstrapAiToolName -ToolName $ToolName) -eq 'openclaw') {
        Assert-BootstrapOpenClawRequestGrant
    }
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $prefix = Get-BootstrapAiNpmPrefix -InstallRoot $root
    $packageName = [string]$CatalogEntry['PackageName']
    if ([string]::IsNullOrWhiteSpace($packageName)) {
        return (New-BootstrapAiToolResult -ToolName $ToolName -Action 'install' -Status 'blocked' -InstallRoot $root -Message 'Pacote npm oficial nao definido.' -Docs ([string]$CatalogEntry['DocsUrl']))
    }
    if ($DryRun) {
        return (New-BootstrapAiToolResult -ToolName $ToolName -Action 'install' -Status 'planned' -InstallRoot $root -Message ("npm install -g --prefix `"{0}`" {1}" -f $prefix, $packageName) -Docs ([string]$CatalogEntry['DocsUrl']))
    }

    [void][System.IO.Directory]::CreateDirectory($prefix)
    $npmCmd = Get-BootstrapNpmCommandForAiTools
    $result = Invoke-BootstrapAiNativeCommand -Exe $npmCmd -Args @('install','-g','--prefix',$prefix,$packageName) -TimeoutMs 600000
    if ([int]$result['exitCode'] -ne 0) {
        $detail = ([string]$result['stderr']).Trim()
        if ([string]::IsNullOrWhiteSpace($detail)) { $detail = ([string]$result['stdout']).Trim() }
        throw ("Falha ao instalar {0} via npm prefixado (exit={1}). {2}" -f $ToolName, [int]$result['exitCode'], $detail)
    }

    Ensure-PathUserContains -Dir $prefix
    Refresh-SessionPath
    $manifest = Read-BootstrapAiToolManifest -InstallRoot $root
    $manifest['tools'][$ToolName] = @{
        kind        = 'npm-prefix'
        packageName = $packageName
        prefix      = $prefix
        installedAt = (Get-Date).ToString('o')
    }
    $manifest['pathsAdded'][$prefix] = $true
    Write-BootstrapAiToolManifest -InstallRoot $root -Manifest $manifest | Out-Null

    $commandPath = Resolve-BootstrapAiToolCommandPath -CatalogEntry $CatalogEntry -InstallRoot $root
    if ([string]::IsNullOrWhiteSpace($commandPath)) {
        throw ("{0} instalado, mas comando esperado nao apareceu no PATH/prefixo." -f $ToolName)
    }
    $version = Get-BootstrapAiToolVersion -CatalogEntry $CatalogEntry -CommandPath $commandPath
    return (New-BootstrapAiToolResult -ToolName $ToolName -Action 'install' -Status 'installed' -InstallRoot $root -Message 'Instalacao validada.' -Docs ([string]$CatalogEntry['DocsUrl']) -CommandPath $commandPath -Version $version)
}

function Get-BootstrapWslExePath {
    $wslExe = Resolve-CommandPath -Name 'wsl.exe'
    if (-not $wslExe) {
        $candidate = Join-Path $env:SystemRoot 'System32\wsl.exe'
        if (Test-Path -LiteralPath $candidate) { $wslExe = $candidate }
    }
    return $wslExe
}

function Invoke-BootstrapWslBashCommand {
    param(
        [Parameter(Mandatory = $true)][string]$Command,
        [int]$TimeoutMs = 120000
    )

    $wslExe = Get-BootstrapWslExePath
    if ([string]::IsNullOrWhiteSpace($wslExe)) {
        throw (New-BootstrapBlockedException -Message 'wsl.exe nao encontrado. Esta ferramenta requer WSL2 no Windows ou fallback nativo disponivel.' -Kind 'wsl-missing' -Action 'install-wsl' -Reasons @('wsl.exe-missing'))
    }
    $null = Assert-BootstrapWslNotCorrupt -WslExe $wslExe -TimeoutMs 15000
    return (Invoke-BootstrapAiNativeCommand -Exe $wslExe -Args @('bash','-lc',$Command) -TimeoutMs $TimeoutMs)
}

function Install-BootstrapHermesAgentWsl {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [string]$ProjectRoot = '',
        [switch]$DryRun
    )

    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $installer = 'https://raw.githubusercontent.com/NousResearch/hermes-agent/main/scripts/install.sh'
    $command = @"
set -euo pipefail
tmp=`$(mktemp "`${TMPDIR:-/tmp}/phasezero-hermes.XXXXXX")
cleanup() { rm -f -- "`$tmp"; }
trap cleanup EXIT
curl --proto '=https' --tlsv1.2 -fL --retry 3 --retry-delay 2 --connect-timeout 15 --max-time 120 '$installer' -o "`$tmp"
size=`$(wc -c < "`$tmp")
[ "`$size" -ge 256 ] && [ "`$size" -le 2097152 ]
head -n 1 "`$tmp" | grep -q '^#!'
bash "`$tmp" --skip-setup
"@
    if ($DryRun) {
        return (New-BootstrapAiToolResult -ToolName 'hermes-agent' -Action 'install' -Status 'planned' -InstallRoot $root -ProjectRoot $ProjectRoot -Message ("WSL2: {0}" -f $command) -Docs ([string]$CatalogEntry['DocsUrl']))
    }

    $install = Invoke-BootstrapWslBashCommand -Command $command -TimeoutMs 1200000
    if ([int]$install['exitCode'] -ne 0) {
        $detail = ([string]$install['stderr']).Trim()
        if ([string]::IsNullOrWhiteSpace($detail)) { $detail = ([string]$install['stdout']).Trim() }
        throw ("Falha ao instalar Hermes Agent no WSL2 (exit={0}). {1}" -f [int]$install['exitCode'], $detail)
    }

    $validate = Invoke-BootstrapWslBashCommand -Command 'command -v hermes >/dev/null 2>&1 && hermes --version' -TimeoutMs 120000
    if ([int]$validate['exitCode'] -ne 0) {
        $detail = ([string]$validate['stderr']).Trim()
        if ([string]::IsNullOrWhiteSpace($detail)) { $detail = ([string]$validate['stdout']).Trim() }
        throw ("Hermes Agent instalado, mas comando hermes nao validou no WSL2 (exit={0}). {1}" -f [int]$validate['exitCode'], $detail)
    }

    $version = [string]$validate['firstLine']
    return (New-BootstrapAiToolResult -ToolName 'hermes-agent' -Action 'install' -Status 'installed' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'Hermes Agent instalado e validado no WSL2.' -Docs ([string]$CatalogEntry['DocsUrl']) -CommandPath 'wsl.exe bash -lc hermes' -Version $version)
}

function Get-BootstrapAiJailWslInstallCommand {
    # Bash (rodado dentro do WSL2): baixa a release linux do ai-jail para ~/.local/bin e tenta
    # instalar bubblewrap (best-effort, sem travar em senha). Nao usa cargo (evita toolchain Rust).
    return @'
set -e
arch=$(uname -m)
case "$arch" in x86_64|amd64) A=x86_64;; aarch64|arm64) A=aarch64;; *) A=x86_64;; esac
mkdir -p "$HOME/.local/bin"
url="https://github.com/akitaonrails/ai-jail/releases/latest/download/ai-jail-linux-${A}.tar.gz"
tmp=$(mktemp -d "${TMPDIR:-/tmp}/phasezero-ai-jail.XXXXXX")
trap 'rm -rf -- "$tmp"' EXIT
archive="$tmp/ai-jail.tar.gz"
curl --proto '=https' --tlsv1.2 -fL --retry 3 --retry-delay 2 --connect-timeout 15 --max-time 180 "$url" -o "$archive"
size=$(wc -c < "$archive")
[ "$size" -ge 1024 ] && [ "$size" -le 268435456 ]
tar -tzf "$archive" | grep -Eq '(^|/)ai-jail$'
extract="$tmp/extract"
mkdir -p "$extract"
tar --no-same-owner --no-same-permissions -xzf "$archive" -C "$extract"
candidate=$(find "$extract" -maxdepth 4 -type f -name ai-jail -print)
[ "$(printf '%s\n' "$candidate" | sed '/^$/d' | wc -l)" -eq 1 ]
[ ! -L "$candidate" ] && [ -s "$candidate" ]
install -m 0755 "$candidate" "$HOME/.local/bin/ai-jail"
if ! command -v bwrap >/dev/null 2>&1; then
  if command -v apt-get >/dev/null 2>&1; then sudo -n apt-get install -y bubblewrap >/dev/null 2>&1 || true; fi
  if ! command -v bwrap >/dev/null 2>&1 && command -v dnf >/dev/null 2>&1; then sudo -n dnf install -y bubblewrap >/dev/null 2>&1 || true; fi
  if ! command -v bwrap >/dev/null 2>&1 && command -v pacman >/dev/null 2>&1; then sudo -n pacman -S --noconfirm bubblewrap >/dev/null 2>&1 || true; fi
fi
if command -v bwrap >/dev/null 2>&1; then echo "BWRAP=ok"; else echo "BWRAP=missing"; fi
"$HOME/.local/bin/ai-jail" --version
'@
}

function Install-BootstrapAiJailWsl {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [string]$ProjectRoot = '',
        [switch]$DryRun
    )

    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $command = Get-BootstrapAiJailWslInstallCommand
    if ($DryRun) {
        return (New-BootstrapAiToolResult -ToolName 'ai-jail' -Action 'install' -Status 'planned' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'WSL2: baixa release linux do ai-jail para ~/.local/bin + bubblewrap (best-effort).' -Docs ([string]$CatalogEntry['DocsUrl']))
    }

    $install = Invoke-BootstrapWslBashCommand -Command $command -TimeoutMs 900000
    if ([int]$install['exitCode'] -ne 0) {
        $detail = ([string]$install['stderr']).Trim()
        if ([string]::IsNullOrWhiteSpace($detail)) { $detail = ([string]$install['stdout']).Trim() }
        throw ("Falha ao instalar ai-jail no WSL2 (exit={0}). {1}" -f [int]$install['exitCode'], $detail)
    }

    $stdout = [string]$install['stdout']
    $bwrapOk = ($stdout -match 'BWRAP=ok')
    $message = if ($bwrapOk) {
        'ai-jail instalado e validado no WSL2 (bubblewrap presente). Use dentro do WSL: ai-jail claude.'
    } else {
        'ai-jail instalado no WSL2, mas bubblewrap NAO foi detectado (faltou sudo/pacote). Instale manualmente no WSL: sudo apt install bubblewrap.'
    }
    $version = ''
    foreach ($line in @($stdout -split "`n")) {
        $trim = $line.Trim()
        if ($trim -and $trim -notmatch '^BWRAP=') { $version = $trim }
    }
    return (New-BootstrapAiToolResult -ToolName 'ai-jail' -Action 'install' -Status 'installed' -InstallRoot $root -ProjectRoot $ProjectRoot -Message $message -Docs ([string]$CatalogEntry['DocsUrl']) -CommandPath 'wsl.exe bash -lc ai-jail' -Version $version)
}

function Uninstall-BootstrapAiJailWsl {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [string]$ProjectRoot = '',
        [switch]$DryRun
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $command = 'rm -f "$HOME/.local/bin/ai-jail" && echo removed'
    if ($DryRun) {
        return (New-BootstrapAiToolResult -ToolName 'ai-jail' -Action 'uninstall' -Status 'planned' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'WSL2: remove ~/.local/bin/ai-jail (bubblewrap e configs .ai-jail por projeto sao preservados).' -Docs ([string]$CatalogEntry['DocsUrl']))
    }
    $r = Invoke-BootstrapWslBashCommand -Command $command -TimeoutMs 120000
    if ([int]$r['exitCode'] -ne 0) {
        throw ("Falha ao remover ai-jail no WSL2 (exit={0}). {1}" -f [int]$r['exitCode'], ([string]$r['stderr']).Trim())
    }
    return (New-BootstrapAiToolResult -ToolName 'ai-jail' -Action 'uninstall' -Status 'uninstalled' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'ai-jail removido do WSL2 (~/.local/bin). bubblewrap e .ai-jail por projeto preservados.' -Docs ([string]$CatalogEntry['DocsUrl']))
}

function Get-BootstrapAiUsagebarReleaseAsset {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$Architecture
    )
    $arch = $Architecture.Trim().ToLowerInvariant()
    if ($arch -in @('amd64','x64','x86_64')) { $arch = 'x86_64' }
    if ($arch -in @('arm64','aarch64')) { $arch = 'aarch64' }
    $assets = $CatalogEntry['ReleaseAssets']
    if ($assets -is [System.Collections.IDictionary] -and $assets.Contains($arch)) {
        return $assets[$arch]
    }
    throw "Arquitetura ai-usagebar nao suportada: $Architecture"
}

function Get-BootstrapAiUsagebarWslInstallCommand {
    param([Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry)
    $tag = [string]$CatalogEntry['ReleaseTag']
    $assets = $CatalogEntry['ReleaseAssets']
    $x64 = $assets['x86_64']
    $arm64 = $assets['aarch64']
    $configB64 = Get-BootstrapAiUsagebarConfigBase64
    return @"
set -euo pipefail
arch="`$(uname -m)"
case "`$arch" in
  x86_64|amd64) asset="$($x64['Name'])"; sha="$($x64['Sha256'])" ;;
  aarch64|arm64) asset="$($arm64['Name'])"; sha="$($arm64['Sha256'])" ;;
  *) echo "unsupported architecture: `$arch" >&2; exit 86 ;;
esac
tmp="`$(mktemp -d)"
trap 'rm -rf "`$tmp"' EXIT
mkdir -p "`$HOME/.local/bin" "`$HOME/.config/ai-usagebar"
url="https://github.com/akitaonrails/ai-usagebar/releases/download/$tag/`$asset"
curl -fsSL -o "`$tmp/`$asset" "`$url"
printf '%s  %s\n' "`$sha" "`$tmp/`$asset" | sha256sum -c -
tar xzf "`$tmp/`$asset" -C "`$HOME/.local/bin" ai-usagebar ai-usagebar-tui
chmod +x "`$HOME/.local/bin/ai-usagebar" "`$HOME/.local/bin/ai-usagebar-tui"
if [ ! -f "`$HOME/.config/ai-usagebar/config.toml" ]; then
  printf '%s' '$configB64' | base64 -d > "`$HOME/.config/ai-usagebar/config.toml"
  chmod 600 "`$HOME/.config/ai-usagebar/config.toml"
fi
"`$HOME/.local/bin/ai-usagebar" --help >/dev/null
test -x "`$HOME/.local/bin/ai-usagebar-tui"
"`$HOME/.local/bin/ai-usagebar" --help | head -n 1
"@
}

function Set-BootstrapAiUsagebarConfig {
    param(
        [string]$InstallRoot = '',
        [string]$ProjectRoot = '',
        [switch]$DryRun
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $paths = @(Get-BootstrapAiUsagebarNativeConfigPathSet)
    $message = ("Criar config sem secrets: {0}" -f ($paths -join ', '))
    if ($DryRun) {
        return (New-BootstrapAiToolResult -ToolName 'ai-usagebar' -Action 'configure' -Status 'planned' -InstallRoot $root -ProjectRoot $ProjectRoot -Message $message -Docs 'https://github.com/akitaonrails/ai-usagebar')
    }
    foreach ($path in @($paths)) {
        if ([string]::IsNullOrWhiteSpace($path)) { continue }
        Write-BootstrapAiUsagebarConfigFile -Path $path | Out-Null
    }
    try {
        $wslExe = Get-BootstrapWslExePath
        if (-not [string]::IsNullOrWhiteSpace($wslExe)) {
            $null = Assert-BootstrapWslNotCorrupt -WslExe $wslExe -TimeoutMs 5000
            $configB64 = Get-BootstrapAiUsagebarConfigBase64
            $command = "mkdir -p `"`$HOME/.config/ai-usagebar`" && printf '%s' '$configB64' | base64 -d > `"`$HOME/.config/ai-usagebar/config.toml`" && chmod 600 `"`$HOME/.config/ai-usagebar/config.toml`""
            $null = Invoke-BootstrapAiNativeCommand -Exe $wslExe -Args @('bash','-lc',$command) -TimeoutMs 10000
        }
    } catch {
        Write-Verbose ("ai-usagebar WSL config write skipped: {0}" -f (Get-BootstrapCleanNativeText -Text $_.Exception.Message -MaxLength 300))
    }
    if (Test-BootstrapHostIsWindows -and [string]::IsNullOrWhiteSpace($env:HOME)) {
        $userHome = Get-BootstrapUserHomePath
        if (-not [string]::IsNullOrWhiteSpace($userHome)) {
            $env:HOME = $userHome
            Set-UserEnvVar -Name 'HOME' -Value $userHome
        }
    }
    return (New-BootstrapAiToolResult -ToolName 'ai-usagebar' -Action 'configure' -Status 'configured' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'Config ai-usagebar criada sem tokens inline; usa env vars e OAuth dos CLIs oficiais.' -Docs 'https://github.com/akitaonrails/ai-usagebar')
}

function Install-BootstrapAiUsagebarViaWsl {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [string]$ProjectRoot = ''
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $command = Get-BootstrapAiUsagebarWslInstallCommand -CatalogEntry $CatalogEntry
    $install = Invoke-BootstrapWslBashCommand -Command $command -TimeoutMs 600000
    if ([int]$install['exitCode'] -ne 0) {
        $detail = Get-BootstrapCleanNativeText -Text ([string]$install['stderr'])
        if ([string]::IsNullOrWhiteSpace($detail)) { $detail = Get-BootstrapCleanNativeText -Text ([string]$install['stdout']) }
        throw ("Falha ao instalar ai-usagebar no WSL/Linux (exit={0}). {1}" -f [int]$install['exitCode'], $detail)
    }
    $version = [string]$install['firstLine']
    if ([string]::IsNullOrWhiteSpace($version)) { $version = [string]$CatalogEntry['ReleaseTag'] }
    return (New-BootstrapAiToolResult -ToolName 'ai-usagebar' -Action 'install' -Status 'installed' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'ai-usagebar instalado no WSL/Linux por release oficial verificada.' -Docs ([string]$CatalogEntry['DocsUrl']) -CommandPath 'wsl.exe bash -lc ai-usagebar' -Version $version)
}

function Get-BootstrapAiUsagebarWslFallbackNote {
    param([AllowNull()][string]$Reason)

    $cleanReason = Get-BootstrapCleanNativeText -Text $Reason -MaxLength 500
    if ([string]::IsNullOrWhiteSpace($cleanReason)) { return '' }

    return 'WSL indisponivel; fallback Cargo Windows usado.'
}

function Install-BootstrapAiUsagebarViaCargo {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [string]$ProjectRoot = '',
        [string]$BlockedReason = ''
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $gitExe = Resolve-CommandPath -Name 'git.exe'
    if (-not $gitExe) { $gitExe = Resolve-CommandPath -Name 'git' }
    $cargoExe = Resolve-CommandPath -Name 'cargo.exe'
    if (-not $cargoExe) { $cargoExe = Resolve-CommandPath -Name 'cargo' }
    if ([string]::IsNullOrWhiteSpace($gitExe) -or [string]::IsNullOrWhiteSpace($cargoExe)) {
        $missing = @()
        if ([string]::IsNullOrWhiteSpace($gitExe)) { $missing += 'git' }
        if ([string]::IsNullOrWhiteSpace($cargoExe)) { $missing += 'cargo/rustup' }
        $msg = ("ai-usagebar requer WSL saudavel ou fallback Cargo; ausente: {0}." -f ($missing -join ', '))
        $fallbackNote = Get-BootstrapAiUsagebarWslFallbackNote -Reason $BlockedReason
        if (-not [string]::IsNullOrWhiteSpace($fallbackNote)) { $msg = "$msg $fallbackNote" }
        return (New-BootstrapAiToolResult -ToolName 'ai-usagebar' -Action 'install' -Status 'blocked' -InstallRoot $root -ProjectRoot $ProjectRoot -Message $msg -Docs ([string]$CatalogEntry['DocsUrl']))
    }

    $tag = [string]$CatalogEntry['ReleaseTag']
    $sourceRoot = Join-Path $root 'sources'
    $sourceDir = Join-Path $sourceRoot ("ai-usagebar-{0}" -f ($tag.TrimStart('v')))
    $managedBinDir = Get-BootstrapAiBinDir -InstallRoot $root
    $binDir = if (Test-BootstrapHostIsWindows) { Get-BootstrapAiUsagebarWindowsBinDir } else { $managedBinDir }
    [void][System.IO.Directory]::CreateDirectory($sourceRoot)
    [void][System.IO.Directory]::CreateDirectory($binDir)

    if (-not (Test-Path -LiteralPath (Join-Path $sourceDir '.git'))) {
        $clone = Invoke-BootstrapAiNativeCommand -Exe $gitExe -Args @('clone','--depth','1','--branch',$tag,'https://github.com/akitaonrails/ai-usagebar.git',$sourceDir) -TimeoutMs 300000
        if ([int]$clone['exitCode'] -ne 0) {
            $detail = ([string]$clone['stderr']).Trim()
            if ([string]::IsNullOrWhiteSpace($detail)) { $detail = ([string]$clone['stdout']).Trim() }
            throw ("Falha ao clonar ai-usagebar {0} (exit={1}). {2}" -f $tag, [int]$clone['exitCode'], $detail)
        }
    } else {
        $fetch = Invoke-BootstrapAiNativeCommand -Exe $gitExe -Args @('-C',$sourceDir,'fetch','--tags','--force','--depth','1','origin',$tag) -TimeoutMs 300000
        if ([int]$fetch['exitCode'] -ne 0) {
            $detail = ([string]$fetch['stderr']).Trim()
            if ([string]::IsNullOrWhiteSpace($detail)) { $detail = ([string]$fetch['stdout']).Trim() }
            throw ("Falha ao atualizar fonte ai-usagebar {0} (exit={1}). {2}" -f $tag, [int]$fetch['exitCode'], $detail)
        }
        $checkout = Invoke-BootstrapAiNativeCommand -Exe $gitExe -Args @('-C',$sourceDir,'checkout','--force',$tag) -TimeoutMs 120000
        if ([int]$checkout['exitCode'] -ne 0) {
            $detail = ([string]$checkout['stderr']).Trim()
            if ([string]::IsNullOrWhiteSpace($detail)) { $detail = ([string]$checkout['stdout']).Trim() }
            throw ("Falha ao aplicar tag ai-usagebar {0} (exit={1}). {2}" -f $tag, [int]$checkout['exitCode'], $detail)
        }
    }

    $build = Invoke-BootstrapAiNativeCommand -Exe $cargoExe -Args @('build','--release') -WorkingDirectory $sourceDir -TimeoutMs 1200000
    if ([int]$build['exitCode'] -ne 0) {
        $detail = ([string]$build['stderr']).Trim()
        if ([string]::IsNullOrWhiteSpace($detail)) { $detail = ([string]$build['stdout']).Trim() }
        throw ("Falha ao compilar ai-usagebar via Cargo (exit={0}). {1}" -f [int]$build['exitCode'], $detail)
    }

    $shimPath = ''
    foreach ($binary in @('ai-usagebar.exe','ai-usagebar-tui.exe')) {
        $sourceBinary = Join-Path (Join-Path $sourceDir 'target\release') $binary
        if (-not (Test-Path -LiteralPath $sourceBinary)) { throw "Build ai-usagebar concluiu, mas binario nao existe: $sourceBinary" }
        $commandBase = [System.IO.Path]::GetFileNameWithoutExtension($binary)
        $targetBinaryName = if (Test-BootstrapHostIsWindows) { ("{0}-bin.exe" -f $commandBase) } else { $binary }
        $targetBinary = Join-Path $binDir $targetBinaryName
        Copy-Item -LiteralPath $sourceBinary -Destination $targetBinary -Force
        if (Test-BootstrapHostIsWindows) {
            $writtenShim = Write-BootstrapAiUsagebarWindowsShim -BinDir $binDir -CommandName $commandBase -TargetExe $targetBinary
            if ($commandBase -eq 'ai-usagebar') { $shimPath = $writtenShim }
            Remove-Item -LiteralPath (Join-Path $binDir $binary) -Force -ErrorAction SilentlyContinue
        }
        if ($managedBinDir -ne $binDir) {
            Remove-Item -LiteralPath (Join-Path $managedBinDir $binary) -Force -ErrorAction SilentlyContinue
            Remove-Item -LiteralPath (Join-Path $managedBinDir ("{0}.cmd" -f $commandBase)) -Force -ErrorAction SilentlyContinue
            Remove-Item -LiteralPath (Join-Path $managedBinDir ("{0}-bin.exe" -f $commandBase)) -Force -ErrorAction SilentlyContinue
        }
    }
    foreach ($path in @(Get-BootstrapAiUsagebarNativeConfigPathSet)) {
        if ([string]::IsNullOrWhiteSpace($path)) { continue }
        if (-not (Test-Path -LiteralPath $path)) { Write-BootstrapAiUsagebarConfigFile -Path $path | Out-Null }
    }
    Ensure-PathUserContains -Dir $binDir
    Refresh-SessionPath

    $manifest = Read-BootstrapAiToolManifest -InstallRoot $root
    $manifest['tools']['ai-usagebar'] = @{
        kind        = 'cargo-tag'
        repo        = 'akitaonrails/ai-usagebar'
        version     = $tag
        sourceDir   = $sourceDir
        binDir      = $binDir
        installedAt = (Get-Date).ToString('o')
    }
    $manifest['pathsAdded'][$binDir] = $true
    Write-BootstrapAiToolManifest -InstallRoot $root -Manifest $manifest | Out-Null

    $exe = if (-not [string]::IsNullOrWhiteSpace($shimPath)) { $shimPath } else { Join-Path $binDir 'ai-usagebar.exe' }
    $validate = Invoke-BootstrapAiUsagebarCommandProbe -CommandPath $exe
    if (-not [bool]$validate['ok']) {
        throw ("ai-usagebar instalado, mas --help falhou ({0}). {1}" -f [string]$validate['status'], [string]$validate['message'])
    }
    $message = 'ai-usagebar instalado por fallback Cargo na tag oficial.'
    $fallbackNote = Get-BootstrapAiUsagebarWslFallbackNote -Reason $BlockedReason
    if (-not [string]::IsNullOrWhiteSpace($fallbackNote)) { $message = "$message $fallbackNote" }
    return (New-BootstrapAiToolResult -ToolName 'ai-usagebar' -Action 'install' -Status 'installed' -InstallRoot $root -ProjectRoot $ProjectRoot -Message $message -Docs ([string]$CatalogEntry['DocsUrl']) -CommandPath $exe -Version $tag)
}

function Install-BootstrapAiUsagebar {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [string]$ProjectRoot = '',
        [switch]$DryRun
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $tag = [string]$CatalogEntry['ReleaseTag']
    $asset = Get-BootstrapAiUsagebarReleaseAsset -CatalogEntry $CatalogEntry -Architecture 'x86_64'
    if ($DryRun) {
        $message = ("GitHub akitaonrails/ai-usagebar {0}: baixar asset Linux verificado sha256 ({1}) via WSL quando saudavel; no Windows sem WSL, compilar fallback Cargo da tag oficial em bin gerenciado." -f $tag, [string]$asset['Name'])
        return (New-BootstrapAiToolResult -ToolName 'ai-usagebar' -Action 'install' -Status 'planned' -InstallRoot $root -ProjectRoot $ProjectRoot -Message $message -Docs ([string]$CatalogEntry['DocsUrl']))
    }

    if (Test-BootstrapHostIsWindows) {
        try {
            return (Install-BootstrapAiUsagebarViaWsl -CatalogEntry $CatalogEntry -InstallRoot $root -ProjectRoot $ProjectRoot)
        } catch {
            $reason = Get-BootstrapCleanNativeText -Text $_.Exception.Message
            return (Install-BootstrapAiUsagebarViaCargo -CatalogEntry $CatalogEntry -InstallRoot $root -ProjectRoot $ProjectRoot -BlockedReason $reason)
        }
    }

    try {
        $command = Get-BootstrapAiUsagebarWslInstallCommand -CatalogEntry $CatalogEntry
        $install = Invoke-BootstrapAiNativeCommand -Exe 'bash' -Args @('-lc',$command) -TimeoutMs 600000
        if ([int]$install['exitCode'] -ne 0) {
            $detail = ([string]$install['stderr']).Trim()
            if ([string]::IsNullOrWhiteSpace($detail)) { $detail = ([string]$install['stdout']).Trim() }
            throw ("Falha ao instalar ai-usagebar local Linux (exit={0}). {1}" -f [int]$install['exitCode'], $detail)
        }
        $version = [string]$install['firstLine']
        if ([string]::IsNullOrWhiteSpace($version)) { $version = $tag }
        return (New-BootstrapAiToolResult -ToolName 'ai-usagebar' -Action 'install' -Status 'installed' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'ai-usagebar instalado por release oficial Linux verificada.' -Docs ([string]$CatalogEntry['DocsUrl']) -CommandPath 'ai-usagebar' -Version $version)
    } catch {
        return (Install-BootstrapAiUsagebarViaCargo -CatalogEntry $CatalogEntry -InstallRoot $root -ProjectRoot $ProjectRoot -BlockedReason $_.Exception.Message)
    }
}

function Uninstall-BootstrapAiUsagebar {
    param(
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [string]$ProjectRoot = '',
        [switch]$DryRun
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $binDirs = @((Get-BootstrapAiBinDir -InstallRoot $root), (Get-BootstrapAiUsagebarWindowsBinDir)) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | Select-Object -Unique
    if ($DryRun) {
        return (New-BootstrapAiToolResult -ToolName 'ai-usagebar' -Action 'uninstall' -Status 'planned' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'Remover binarios Windows gerenciados; instalacao WSL/Linux fica manual para preservar config e tokens do usuario.' -Docs 'https://github.com/akitaonrails/ai-usagebar')
    }
    foreach ($binDir in @($binDirs)) {
        foreach ($binary in @('ai-usagebar.exe','ai-usagebar-tui.exe','ai-usagebar.cmd','ai-usagebar-tui.cmd','ai-usagebar-bin.exe','ai-usagebar-tui-bin.exe')) {
            $path = Join-Path $binDir $binary
            if (Test-Path -LiteralPath $path) { Remove-Item -LiteralPath $path -Force }
        }
    }
    $manifest = Read-BootstrapAiToolManifest -InstallRoot $root
    if ($manifest['tools'].ContainsKey('ai-usagebar')) { $manifest['tools'].Remove('ai-usagebar') | Out-Null }
    foreach ($binDir in @($binDirs)) {
        if ($manifest['pathsAdded'].ContainsKey($binDir)) { $manifest['pathsAdded'].Remove($binDir) | Out-Null }
    }
    Write-BootstrapAiToolManifest -InstallRoot $root -Manifest $manifest | Out-Null
    return (New-BootstrapAiToolResult -ToolName 'ai-usagebar' -Action 'uninstall' -Status 'removed' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'ai-usagebar Windows gerenciado removido; configs preservadas.' -Docs 'https://github.com/akitaonrails/ai-usagebar')
}

function Get-BootstrapAiMemoryInstallDir {
    param([Parameter(Mandatory = $true)][string]$InstallRoot)
    return (Join-Path (Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot) 'ai-memory')
}

function Get-BootstrapAiMemoryExePath {
    param([string]$InstallRoot = '')
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $candidates = New-Object System.Collections.Generic.List[string]
    $candidates.Add((Join-Path (Get-BootstrapAiMemoryInstallDir -InstallRoot $root) 'ai-memory.exe')) | Out-Null
    $candidates.Add((Join-Path (Get-BootstrapAiBinDir -InstallRoot $root) 'ai-memory.exe')) | Out-Null
    $userHome = Get-BootstrapUserHomePath
    if (-not [string]::IsNullOrWhiteSpace($userHome)) {
        $cargoHome = Join-Path $userHome '.cargo\bin\ai-memory.exe'
        $candidates.Add($cargoHome) | Out-Null
    }
    foreach ($candidate in @($candidates.ToArray())) {
        if (-not [string]::IsNullOrWhiteSpace($candidate) -and (Test-Path -LiteralPath $candidate)) { return $candidate }
    }
    return ''
}

function Get-BootstrapAiMemoryServerUrl {
    if (-not [string]::IsNullOrWhiteSpace($env:AI_MEMORY_SERVER_URL)) { return [string]$env:AI_MEMORY_SERVER_URL }
    return 'http://127.0.0.1:49374'
}

function Get-BootstrapAiMemoryReleaseAsset {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$Key
    )
    $assets = $CatalogEntry['ReleaseAssets']
    if ($assets -is [System.Collections.IDictionary] -and $assets.Contains($Key)) { return $assets[$Key] }
    throw ("Asset ai-memory '{0}' nao definido no catalogo." -f $Key)
}

function Get-BootstrapAiMemoryDataDir {
    # Retorna o diretorio de dados do ai-memory.
    # Padrao Windows: $env:LOCALAPPDATA\ai-memory.
    # Aceita override via env var AI_MEMORY_DATA_DIR.
    if (-not [string]::IsNullOrWhiteSpace($env:AI_MEMORY_DATA_DIR)) {
        return [string]$env:AI_MEMORY_DATA_DIR
    }
    $localAppData = if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        $env:LOCALAPPDATA
    } else {
        Join-Path $env:USERPROFILE 'AppData\Local'
    }
    return (Join-Path $localAppData 'ai-memory')
}

function Get-BootstrapAiMemoryDetectedAgents {
    # Mapeia agentes instalados para os identificadores --client/--agent do ai-memory.
    $agents = New-Object System.Collections.Generic.List[string]
    $catalog = Get-BootstrapAiToolCatalog
    $probe = @(
        @{ Tool = 'claude-code'; Id = 'claude-code' }
        @{ Tool = 'codex-cli'; Id = 'codex' }
        @{ Tool = 'opencode'; Id = 'opencode' }
        @{ Tool = 'gemini-cli'; Id = 'gemini-cli' }
    )
    foreach ($item in $probe) {
        $toolName = [string]$item.Tool
        if (-not $catalog.Contains($toolName)) { continue }
        try {
            $path = Resolve-BootstrapAiToolCommandPath -CatalogEntry $catalog[$toolName] -InstallRoot (Get-BootstrapAiInstallRoot -InstallRoot '')
        } catch {
            $path = ''
        }
        if (-not [string]::IsNullOrWhiteSpace($path)) { $agents.Add([string]$item.Id) | Out-Null }
    }
    return @($agents.ToArray())
}

function Invoke-BootstrapAiMemoryWiring {
    param(
        [Parameter(Mandatory = $true)][string]$ExePath,
        [string[]]$Agents = @(),
        [switch]$DryRun
    )
    # Executa install-mcp/install-hooks idempotentes por agente detectado. Sem --apply seria dry-run nativo.
    $serverUrl = Get-BootstrapAiMemoryServerUrl
    $applied = New-Object System.Collections.Generic.List[object]
    $aiRoot = Get-BootstrapAiInstallRoot
    $memoryInstallDir = Get-BootstrapAiMemoryInstallDir -InstallRoot $aiRoot
    foreach ($agent in @($Agents)) {
        if ([string]::IsNullOrWhiteSpace($agent)) { continue }
        foreach ($verb in @('install-mcp', 'install-hooks')) {
            $flag = if ($verb -eq 'install-mcp') { '--client' } else { '--agent' }
            $hooksDirArg = @()
            if ($verb -eq 'install-hooks' -and -not [string]::IsNullOrWhiteSpace($memoryInstallDir)) {
                $hooksDirArg = @('--hooks-dir', (Join-Path $memoryInstallDir 'hooks'))
            }
            if ($DryRun) {
                $applied.Add([ordered]@{ agent = $agent; command = ("{0} {1} {2} --apply --server-url {3} {4}" -f $verb, $flag, $agent, $serverUrl, ($hooksDirArg -join ' ')); status = 'planned' }) | Out-Null
                continue
            }
            try {
                $runArgs = @($verb, $flag, $agent, '--apply', '--server-url', $serverUrl) + $hooksDirArg
                $result = Invoke-BootstrapAiNativeCommand -Exe $ExePath -Args $runArgs -TimeoutMs 60000
                $status = if ([int]$result['exitCode'] -eq 0) { 'applied' } else { 'failed' }
                $applied.Add([ordered]@{ agent = $agent; command = ("{0} {1} {2}" -f $verb, $flag, $agent); status = $status; detail = (Get-BootstrapCleanNativeText -Text (([string]$result['stderr']) + ' ' + ([string]$result['stdout'])) -MaxLength 300) }) | Out-Null
            } catch {
                $applied.Add([ordered]@{ agent = $agent; command = ("{0} {1} {2}" -f $verb, $flag, $agent); status = 'failed'; detail = (Get-BootstrapCleanNativeText -Text $_.Exception.Message -MaxLength 300) }) | Out-Null
            }
        }
    }
    return @($applied.ToArray())
}

function Ensure-BootstrapAiMemoryServerTask {
    param(
        [Parameter(Mandatory = $true)][string]$ExePath,
        [switch]$DryRun,
        [switch]$Visible
    )
    # Registra task de logon que sobe o servidor loopback ai-memory serve.
    # Por padrao roda em segundo plano (sem janela de console) via launcher VBS;
    # use -Visible para manter o console visivel (debug).
    $taskName = 'BootstrapTools-AiMemoryServer'
    $serverUrl = Get-BootstrapAiMemoryServerUrl
    $bind = '127.0.0.1:49374'
    if ($serverUrl -match '://([^/]+)') { $bind = $matches[1] }

    $hidden = -not $Visible
    $vbsPath = ''
    if ($hidden) {
        $launcherDir = Split-Path -Parent $ExePath
        $vbsPath = Join-Path $launcherDir 'ai-memory-serve-hidden.vbs'
        # WScript.Shell.Run com window style 0 = oculto; False = nao espera.
        $vbsBody = 'CreateObject("WScript.Shell").Run """' + $ExePath + '"" serve --transport http --bind ' + $bind + '", 0, False'
        $wscriptExe = Join-Path $env:SystemRoot 'System32\wscript.exe'
        $taskCommand = ('"{0}" "{1}"' -f $wscriptExe, $vbsPath)
    } else {
        $taskCommand = ('"{0}" serve --transport http --bind {1}' -f $ExePath, $bind)
    }

    if ($DryRun) {
        return [ordered]@{ status = 'planned'; task = $taskName; command = $taskCommand; hidden = $hidden }
    }

    if ($hidden) {
        try {
            Write-BootstrapAtomicText -Path $vbsPath -Content $vbsBody -Encoding (New-Object System.Text.UTF8Encoding($false))
        } catch {
            return [ordered]@{ status = 'failed'; task = $taskName; command = $taskCommand; reason = ("vbs-write: {0}" -f $_.Exception.Message) }
        }
    }

    # Primario: Register-ScheduledTask (por-usuario, NAO exige elevacao, suporta janela oculta).
    if (Get-Command -Name Register-ScheduledTask -ErrorAction SilentlyContinue) {
        try {
            $existing = Get-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue
            if ($existing) { Unregister-ScheduledTask -TaskName $taskName -Confirm:$false -ErrorAction SilentlyContinue }
            if ($hidden) {
                $action = New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot 'System32\wscript.exe') -Argument ('"{0}"' -f $vbsPath)
            } else {
                $action = New-ScheduledTaskAction -Execute $ExePath -Argument ('serve --transport http --bind {0}' -f $bind)
            }
            $trigger = New-ScheduledTaskTrigger -AtLogOn -User $env:USERNAME
            $principal = New-ScheduledTaskPrincipal -UserId ("{0}\{1}" -f $env:USERDOMAIN, $env:USERNAME) -LogonType Interactive -RunLevel Limited
            $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit ([TimeSpan]::Zero)
            $settings.Hidden = $hidden
            Register-ScheduledTask -TaskName $taskName -Action $action -Trigger $trigger -Principal $principal -Settings $settings -Description 'Inicia o servidor loopback ai-memory no logon (segundo plano quando oculto).' -ErrorAction Stop | Out-Null
            return [ordered]@{ status = 'registered'; task = $taskName; command = $taskCommand; hidden = $hidden; method = 'register-scheduledtask' }
        } catch {
            Write-Log ("ai-memory: Register-ScheduledTask falhou ({0}); tentando schtasks." -f $_.Exception.Message) 'WARN'
        }
    }

    # Fallback: schtasks (pode exigir elevacao em alguns hosts).
    $schtasksExe = Resolve-CommandPath -Name 'schtasks.exe'
    if (-not $schtasksExe) { $schtasksExe = Join-Path $env:SystemRoot 'System32\schtasks.exe' }
    if (-not (Test-Path $schtasksExe)) {
        return [ordered]@{ status = 'skipped'; task = $taskName; command = $taskCommand; reason = 'schtasks.exe nao encontrado.' }
    }
    $exitCode = Invoke-NativeWithLog -Exe $schtasksExe -Args @('/Create', '/SC', 'ONLOGON', '/TN', $taskName, '/TR', $taskCommand, '/F', '/RU', $env:USERNAME)
    if ($exitCode -ne 0) {
        return [ordered]@{ status = 'failed'; task = $taskName; command = $taskCommand; reason = ("schtasks-exit={0}" -f $exitCode); hidden = $hidden }
    }
    return [ordered]@{ status = 'registered'; task = $taskName; command = $taskCommand; hidden = $hidden; method = 'schtasks' }
}

function Install-BootstrapAiMemory {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [string]$ProjectRoot = '',
        [switch]$DryRun
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $tag = [string]$CatalogEntry['ReleaseTag']
    $installDir = Get-BootstrapAiMemoryInstallDir -InstallRoot $root
    if ($DryRun) {
        $asset = Get-BootstrapAiMemoryReleaseAsset -CatalogEntry $CatalogEntry -Key 'windows'
        $message = ("GitHub akitaonrails/ai-memory {0}: baixar {1} verificado sha256, extrair ai-memory.exe em bin gerenciado, registrar PATH/task de logon e rodar install-mcp/install-hooks por agente; fallback cargo install quando indisponivel." -f $tag, [string]$asset['Name'])
        return (New-BootstrapAiToolResult -ToolName 'ai-memory' -Action 'install' -Status 'planned' -InstallRoot $root -ProjectRoot $ProjectRoot -Message $message -Docs ([string]$CatalogEntry['DocsUrl']))
    }

    if (Test-BootstrapHostIsWindows) {
        try {
            return (Install-BootstrapAiMemoryViaRelease -CatalogEntry $CatalogEntry -InstallRoot $root -ProjectRoot $ProjectRoot)
        } catch {
            $reason = Get-BootstrapCleanNativeText -Text $_.Exception.Message
            return (Install-BootstrapAiMemoryViaCargo -CatalogEntry $CatalogEntry -InstallRoot $root -ProjectRoot $ProjectRoot -BlockedReason $reason)
        }
    }

    return (Install-BootstrapAiMemoryViaCargo -CatalogEntry $CatalogEntry -InstallRoot $root -ProjectRoot $ProjectRoot)
}

function Install-BootstrapAiMemoryViaRelease {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [string]$ProjectRoot = ''
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $tag = [string]$CatalogEntry['ReleaseTag']
    $asset = Get-BootstrapAiMemoryReleaseAsset -CatalogEntry $CatalogEntry -Key 'windows'
    $assetName = [string]$asset['Name']
    $expected = ([string]$asset['Sha256']).ToLowerInvariant()
    $installDir = Get-BootstrapAiMemoryInstallDir -InstallRoot $root
    $downloadRoot = Join-Path $root 'downloads'
    [void][System.IO.Directory]::CreateDirectory($installDir)
    [void][System.IO.Directory]::CreateDirectory($downloadRoot)
    $assetPath = Join-Path $downloadRoot $assetName
    $url = ("https://github.com/{0}/releases/download/{1}/{2}" -f [string]$CatalogEntry['GitHubRepo'], $tag, $assetName)

    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    Invoke-WebRequest -Uri $url -OutFile $assetPath -UseBasicParsing -Headers @{ 'User-Agent' = 'PhaseZero-Bootstrap' } -ErrorAction Stop

    if (-not [string]::IsNullOrWhiteSpace($expected)) {
        $actual = (Get-BootstrapFileSha256 -Path $assetPath).ToLowerInvariant()
        if ($actual -ne $expected) {
            throw ("Checksum ai-memory invalido. Esperado={0} Atual={1}" -f $expected, $actual)
        }
    }

    if (Test-Path -LiteralPath (Join-Path $installDir 'ai-memory.exe')) {
        Remove-Item -LiteralPath (Join-Path $installDir 'ai-memory.exe') -Force -ErrorAction SilentlyContinue
    }
    Expand-Archive -LiteralPath $assetPath -DestinationPath $installDir -Force
    $exePath = Join-Path $installDir 'ai-memory.exe'
    if (-not (Test-Path -LiteralPath $exePath)) {
        $found = Get-ChildItem -LiteralPath $installDir -Recurse -Filter 'ai-memory.exe' | Select-Object -First 1
        if (-not $found) { throw 'Zip ai-memory extraido, mas ai-memory.exe nao foi encontrado.' }
        $exePath = $found.FullName
    }

    Ensure-PathUserContains -Dir $installDir
    $manifest = Read-BootstrapAiToolManifest -InstallRoot $root
    $manifest['tools']['ai-memory'] = @{
        kind        = 'windows-release'
        source      = $url
        version     = $tag
        binDir      = $installDir
        installedAt = (Get-Date).ToString('o')
    }
    $manifest['pathsAdded'][$installDir] = $true
    Write-BootstrapAiToolManifest -InstallRoot $root -Manifest $manifest | Out-Null

    $version = Get-BootstrapAiToolVersion -CatalogEntry $CatalogEntry -CommandPath $exePath
    if ([string]::IsNullOrWhiteSpace($version)) { $version = $tag }
    return (New-BootstrapAiToolResult -ToolName 'ai-memory' -Action 'install' -Status 'installed' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'ai-memory instalado por release nativa Windows verificada por sha256.' -Docs ([string]$CatalogEntry['DocsUrl']) -CommandPath $exePath -Version $version)
}

function Install-BootstrapAiMemoryViaCargo {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [string]$ProjectRoot = '',
        [string]$BlockedReason = ''
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $cargoExe = Resolve-CommandPath -Name 'cargo.exe'
    if (-not $cargoExe) { $cargoExe = Resolve-CommandPath -Name 'cargo' }
    if ([string]::IsNullOrWhiteSpace($cargoExe)) {
        $msg = 'ai-memory requer release nativa verificada ou fallback Cargo; cargo/rustup ausente.'
        $clean = Get-BootstrapCleanNativeText -Text $BlockedReason -MaxLength 400
        if (-not [string]::IsNullOrWhiteSpace($clean)) { $msg = "$msg Detalhe: $clean" }
        return (New-BootstrapAiToolResult -ToolName 'ai-memory' -Action 'install' -Status 'blocked' -InstallRoot $root -ProjectRoot $ProjectRoot -Message $msg -Docs ([string]$CatalogEntry['DocsUrl']))
    }

    $tag = [string]$CatalogEntry['ReleaseTag']
    $repo = [string]$CatalogEntry['GitHubRepo']
    $build = Invoke-BootstrapAiNativeCommand -Exe $cargoExe -Args @('install', '--git', ("https://github.com/{0}.git" -f $repo), '--tag', $tag, 'ai-memory-cli') -TimeoutMs 1200000
    if ([int]$build['exitCode'] -ne 0) {
        $detail = ([string]$build['stderr']).Trim()
        if ([string]::IsNullOrWhiteSpace($detail)) { $detail = ([string]$build['stdout']).Trim() }
        throw ("Falha ao compilar ai-memory via Cargo (exit={0}). {1}" -f [int]$build['exitCode'], $detail)
    }

    $exePath = Get-BootstrapAiMemoryExePath -InstallRoot $root
    if ([string]::IsNullOrWhiteSpace($exePath)) { $exePath = Join-Path $env:USERPROFILE '.cargo\bin\ai-memory.exe' }
    $manifest = Read-BootstrapAiToolManifest -InstallRoot $root
    $manifest['tools']['ai-memory'] = @{
        kind        = 'cargo-install'
        source      = ("https://github.com/{0}.git" -f $repo)
        version     = $tag
        binDir      = (Split-Path -Path $exePath -Parent)
        installedAt = (Get-Date).ToString('o')
    }
    Write-BootstrapAiToolManifest -InstallRoot $root -Manifest $manifest | Out-Null
    $version = Get-BootstrapAiToolVersion -CatalogEntry $CatalogEntry -CommandPath $exePath
    if ([string]::IsNullOrWhiteSpace($version)) { $version = $tag }
    return (New-BootstrapAiToolResult -ToolName 'ai-memory' -Action 'install' -Status 'installed' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'ai-memory instalado por fallback cargo install na tag oficial.' -Docs ([string]$CatalogEntry['DocsUrl']) -CommandPath $exePath -Version $version)
}

function Set-BootstrapAiMemoryConfig {
    param(
        [string]$InstallRoot = '',
        [string]$ProjectRoot = '',
        [switch]$DryRun
    )
    # configure = registra servidor (task de logon) + wiring MCP/hooks por agente detectado.
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $exePath = Get-BootstrapAiMemoryExePath -InstallRoot $root
    $agents = Get-BootstrapAiMemoryDetectedAgents
    if ([string]::IsNullOrWhiteSpace($exePath)) {
        if ($DryRun) {
            $msg = ("Planejado: registrar task servidor loopback e rodar install-mcp/install-hooks para: {0}" -f (($agents -join ', ')))
            return (New-BootstrapAiToolResult -ToolName 'ai-memory' -Action 'configure' -Status 'planned' -InstallRoot $root -ProjectRoot $ProjectRoot -Message $msg -Docs 'https://github.com/akitaonrails/ai-memory')
        }
        return (New-BootstrapAiToolResult -ToolName 'ai-memory' -Action 'configure' -Status 'absent' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'ai-memory.exe nao encontrado; instale antes de configurar.' -Docs 'https://github.com/akitaonrails/ai-memory')
    }

    $task = Ensure-BootstrapAiMemoryServerTask -ExePath $exePath -DryRun:$DryRun
    $wiring = Invoke-BootstrapAiMemoryWiring -ExePath $exePath -Agents $agents -DryRun:$DryRun
    $status = if ($DryRun) { 'planned' } else { 'configured' }
    $message = if (@($agents).Count -gt 0) {
        ("Servidor loopback {0}; MCP/hooks aplicados para: {1}." -f [string]$task['status'], (($agents -join ', ')))
    } else {
        ("Servidor loopback {0}; nenhum agente (Claude Code/Codex/OpenCode/Gemini) detectado para wiring automatico." -f [string]$task['status'])
    }
    $result = New-BootstrapAiToolResult -ToolName 'ai-memory' -Action 'configure' -Status $status -InstallRoot $root -ProjectRoot $ProjectRoot -Message $message -Docs 'https://github.com/akitaonrails/ai-memory' -CommandPath $exePath
    $result['serverTask'] = $task
    $result['agents'] = @($agents)
    $result['wiring'] = @($wiring)

    # Sync com SDCard + registra task agendada (criada sempre para capturar SDCard futuro)
    if (-not $DryRun) {
        $syncResult = Sync-BootstrapAiMemoryWithSdCard -DryRun:$DryRun
        $result['sdSync'] = $syncResult
        $taskResult = Ensure-BootstrapAiMemorySyncTask -DryRun:$DryRun
        $result['syncTask'] = $taskResult
    } else {
        $result['sdSync'] = [ordered]@{ schemaVersion = 1; sdCardFound = $false; direction = 'planned' }
        $result['syncTask'] = [ordered]@{ status = 'planned'; task = 'BootstrapTools-AiMemorySync' }
    }

    return $result
}

function Uninstall-BootstrapAiMemory {
    param(
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [string]$ProjectRoot = '',
        [switch]$DryRun
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $installDir = Get-BootstrapAiMemoryInstallDir -InstallRoot $root
    $taskName = 'BootstrapTools-AiMemoryServer'
    if ($DryRun) {
        return (New-BootstrapAiToolResult -ToolName 'ai-memory' -Action 'uninstall' -Status 'planned' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'Remover ai-memory.exe gerenciado e task de logon; preserva dados de memoria (wiki/raw/db) e configs dos agentes.' -Docs 'https://github.com/akitaonrails/ai-memory')
    }

    $schtasksExe = Resolve-CommandPath -Name 'schtasks.exe'
    if (-not $schtasksExe) { $schtasksExe = Join-Path $env:SystemRoot 'System32\schtasks.exe' }
    if (Test-Path $schtasksExe) {
        Invoke-NativeWithLog -Exe $schtasksExe -Args @('/Delete', '/TN', $taskName, '/F') | Out-Null
    }

    $exe = Join-Path $installDir 'ai-memory.exe'
    if (Test-Path -LiteralPath $exe) { Remove-Item -LiteralPath $exe -Force -ErrorAction SilentlyContinue }

    $manifest = Read-BootstrapAiToolManifest -InstallRoot $root
    if ($manifest['tools'].ContainsKey('ai-memory')) { $manifest['tools'].Remove('ai-memory') | Out-Null }
    if ($manifest['pathsAdded'].ContainsKey($installDir)) {
        Remove-PathUserEntry -Dir $installDir | Out-Null
        $manifest['pathsAdded'].Remove($installDir) | Out-Null
    }
    Write-BootstrapAiToolManifest -InstallRoot $root -Manifest $manifest | Out-Null
    return (New-BootstrapAiToolResult -ToolName 'ai-memory' -Action 'uninstall' -Status 'removed' -InstallRoot $root -ProjectRoot $ProjectRoot -Message 'ai-memory gerenciado e task removidos; dados de memoria do usuario preservados.' -Docs 'https://github.com/akitaonrails/ai-memory')
}

function Find-BootstrapAiMemorySdCard {
    # Varre drives removiveis (DriveType=2) procurando pasta "Ai-memory" na raiz.
    # Retorna path completo ou $null.
    try {
        $drives = Get-CimInstance -ClassName Win32_LogicalDisk -ErrorAction SilentlyContinue |
            Where-Object { $_.DriveType -eq 2 }
        foreach ($drive in $drives) {
            $candidate = Join-Path $drive.DeviceID 'Ai-memory'
            if (Test-Path -LiteralPath $candidate) {
                Write-Log "ai-memory: SDCard encontrado em $candidate" 'INFO'
                return $candidate
            }
        }
    } catch {
        Write-Log ("ai-memory: Find-BootstrapAiMemorySdCard WMI falhou ({0})" -f $_.Exception.Message) 'WARN'
    }
    # Fallback: drive literal F:\Ai-memory
    $fallback = 'F:\Ai-memory'
    if (Test-Path -LiteralPath $fallback) {
        Write-Log "ai-memory: SDCard fallback em $fallback" 'INFO'
        return $fallback
    }
    Write-Log 'ai-memory: Nenhum SDCard com pasta Ai-memory encontrado.' 'INFO'
    return $null
}

function Export-BootstrapAiMemoryToSdCard {
    <#
    .SYNOPSIS
        Exporta dados locais do ai-memory (wiki/raw/db/config) para SDCard.
    .DESCRIPTION
        wiki/ usa git push para bare repo no SDCard.
        raw/ e db/ usam robocopy /MIR.
        config.toml copiado direto.
    #>
    param(
        [Parameter(Mandatory = $true)][string]$SdCardPath,
        [Parameter(Mandatory = $true)][string]$DataDir,
        [switch]$DryRun
    )
    Write-Log "ai-memory: Exportando dados para SDCard $SdCardPath" 'INFO'

    $results = New-Object System.Collections.Generic.List[object]

    # Cria estrutura no SDCard
    if (-not $DryRun) {
        $null = New-Item -Path $SdCardPath -ItemType Directory -Force
        $null = New-Item -Path (Join-Path $SdCardPath 'raw') -ItemType Directory -Force
        $null = New-Item -Path (Join-Path $SdCardPath 'db') -ItemType Directory -Force
    }

    # wiki/ - git push para bare repo no SDCard
    $wikiLocal = Join-Path $DataDir 'wiki'
    $wikiBareSd = Join-Path $SdCardPath 'wiki.git'
    if (Test-Path -LiteralPath $wikiLocal) {
        # Inicializa bare repo no SDCard se necessario
        if (-not (Test-Path -LiteralPath $wikiBareSd)) {
            if (-not $DryRun) {
                $null = New-Item -Path $wikiBareSd -ItemType Directory -Force
                $initResult = Invoke-BootstrapAiNativeCommand -Exe 'git' -Args @('init', '--bare', $wikiBareSd) -TimeoutMs 30000
                if ([int]$initResult['exitCode'] -ne 0) {
                    $results.Add([ordered]@{ component = 'wiki.git'; status = 'failed'; detail = "git init --bare exit $($initResult.exitCode)" })
                    Write-Log "ai-memory: wiki.git init --bare falhou (exit $($initResult.exitCode))" 'WARN'
                }
            }
        }
        if (-not $DryRun) {
            $pushResult = Invoke-BootstrapAiNativeCommand -Exe 'git' -Args @('-C', $wikiLocal, 'push', $wikiBareSd, 'HEAD:main') -TimeoutMs 60000
            if ([int]$pushResult['exitCode'] -ne 0) {
                $results.Add([ordered]@{ component = 'wiki'; status = 'failed'; detail = "git push exit $($pushResult.exitCode)" })
                Write-Log "ai-memory: git push wiki falhou (exit $($pushResult.exitCode))" 'WARN'
            } else {
                $results.Add([ordered]@{ component = 'wiki'; status = 'exported'; detail = 'git push ok' })
                Write-Log 'ai-memory: wiki exportado via git push' 'INFO'
            }
        } else {
            $results.Add([ordered]@{ component = 'wiki'; status = 'planned'; detail = 'git push to bare repo' })
        }
    }

    # raw/ - robocopy /MIR
    $rawLocal = Join-Path $DataDir 'raw'
    $rawSd = Join-Path $SdCardPath 'raw'
    if (Test-Path -LiteralPath $rawLocal) {
        if (-not $DryRun) {
            $rcArgs = @($rawLocal, $rawSd, '/MIR', '/R:3', '/W:5', '/NP', '/NDL', '/NJH', '/NJS')
            $rcResult = Invoke-BootstrapAiNativeCommand -Exe 'robocopy' -Args $rcArgs -TimeoutMs 120000
            $rcExit = [int]$rcResult['exitCode']
            if ($rcExit -ge 8) {
                $results.Add([ordered]@{ component = 'raw'; status = 'failed'; detail = "robocopy exit $rcExit" })
                Write-Log "ai-memory: robocopy raw falhou (exit $rcExit)" 'WARN'
            } else {
                $results.Add([ordered]@{ component = 'raw'; status = 'exported'; detail = "robocopy exit $rcExit" })
                Write-Log "ai-memory: raw exportado (robocopy exit $rcExit)" 'INFO'
            }
        } else {
            $results.Add([ordered]@{ component = 'raw'; status = 'planned'; detail = 'robocopy /MIR' })
        }
    }

    # db/ - robocopy /MIR
    $dbLocal = Join-Path $DataDir 'db'
    $dbSd = Join-Path $SdCardPath 'db'
    if (Test-Path -LiteralPath $dbLocal) {
        if (-not $DryRun) {
            $rcArgs = @($dbLocal, $dbSd, '/MIR', '/R:3', '/W:5', '/NP', '/NDL', '/NJH', '/NJS')
            $rcResult = Invoke-BootstrapAiNativeCommand -Exe 'robocopy' -Args $rcArgs -TimeoutMs 120000
            $rcExit = [int]$rcResult['exitCode']
            if ($rcExit -ge 8) {
                $results.Add([ordered]@{ component = 'db'; status = 'failed'; detail = "robocopy exit $rcExit" })
                Write-Log "ai-memory: robocopy db falhou (exit $rcExit)" 'WARN'
            } else {
                $results.Add([ordered]@{ component = 'db'; status = 'exported'; detail = "robocopy exit $rcExit" })
                Write-Log "ai-memory: db exportado (robocopy exit $rcExit)" 'INFO'
            }
        } else {
            $results.Add([ordered]@{ component = 'db'; status = 'planned'; detail = 'robocopy /MIR' })
        }
    }

    # config.toml
    $configLocal = Join-Path $DataDir 'config.toml'
    $configSd = Join-Path $SdCardPath 'config.toml'
    if (Test-Path -LiteralPath $configLocal) {
        if (-not $DryRun) {
            Copy-Item -LiteralPath $configLocal -Destination $configSd -Force -ErrorAction SilentlyContinue
            $results.Add([ordered]@{ component = 'config.toml'; status = 'exported'; detail = '' })
        } else {
            $results.Add([ordered]@{ component = 'config.toml'; status = 'planned'; detail = 'Copy-Item' })
        }
    }

    return @($results.ToArray())
}

function Import-BootstrapAiMemoryFromSdCard {
    <#
    .SYNOPSIS
        Importa dados do SDCard para o diretorio local do ai-memory.
    .DESCRIPTION
        wiki/ usa git pull (ou git clone se local vazio).
        raw/ e db/ usam robocopy /MIR /XO (exclude older = newest-wins).
        config.toml copiado apenas se local nao existe.
    #>
    param(
        [Parameter(Mandatory = $true)][string]$SdCardPath,
        [Parameter(Mandatory = $true)][string]$DataDir,
        [switch]$DryRun
    )
    Write-Log "ai-memory: Importando dados do SDCard $SdCardPath" 'INFO'

    $results = New-Object System.Collections.Generic.List[object]

    if (-not $DryRun) {
        $null = New-Item -Path $DataDir -ItemType Directory -Force
    }

    # wiki/ - git pull ou git clone
    $wikiLocal = Join-Path $DataDir 'wiki'
    $wikiBareSd = Join-Path $SdCardPath 'wiki.git'
    if (Test-Path -LiteralPath $wikiBareSd) {
        if (Test-Path -LiteralPath $wikiLocal) {
            # git pull via remote sd-card
            if (-not $DryRun) {
                # Verifica se remote sd-card ja existe
                $remoteCheck = Invoke-BootstrapAiNativeCommand -Exe 'git' -Args @('-C', $wikiLocal, 'remote', 'get-url', 'sd-card') -TimeoutMs 10000
                if ([int]$remoteCheck['exitCode'] -ne 0) {
                    Invoke-BootstrapAiNativeCommand -Exe 'git' -Args @('-C', $wikiLocal, 'remote', 'add', 'sd-card', $wikiBareSd) -TimeoutMs 10000 | Out-Null
                }
                $pullResult = Invoke-BootstrapAiNativeCommand -Exe 'git' -Args @('-C', $wikiLocal, 'pull', 'sd-card', 'main') -TimeoutMs 60000
                if ([int]$pullResult['exitCode'] -ne 0) {
                    $results.Add([ordered]@{ component = 'wiki'; status = 'failed'; detail = "git pull exit $($pullResult.exitCode)" })
                    Write-Log "ai-memory: git pull wiki falhou (exit $($pullResult.exitCode))" 'WARN'
                } else {
                    $results.Add([ordered]@{ component = 'wiki'; status = 'imported'; detail = 'git pull ok' })
                    Write-Log 'ai-memory: wiki importado via git pull' 'INFO'
                }
            } else {
                $results.Add([ordered]@{ component = 'wiki'; status = 'planned'; detail = 'git pull from bare repo' })
            }
        } else {
            # git clone
            if (-not $DryRun) {
                $cloneResult = Invoke-BootstrapAiNativeCommand -Exe 'git' -Args @('clone', $wikiBareSd, $wikiLocal) -TimeoutMs 60000
                if ([int]$cloneResult['exitCode'] -ne 0) {
                    $results.Add([ordered]@{ component = 'wiki'; status = 'failed'; detail = "git clone exit $($cloneResult.exitCode)" })
                    Write-Log "ai-memory: git clone wiki falhou (exit $($cloneResult.exitCode))" 'WARN'
                } else {
                    $results.Add([ordered]@{ component = 'wiki'; status = 'imported'; detail = 'git clone ok' })
                    Write-Log 'ai-memory: wiki clonado do SDCard' 'INFO'
                }
            } else {
                $results.Add([ordered]@{ component = 'wiki'; status = 'planned'; detail = 'git clone from bare repo' })
            }
        }
    }

    # raw/ - robocopy /MIR /XO (newest-wins)
    $rawSd = Join-Path $SdCardPath 'raw'
    $rawLocal = Join-Path $DataDir 'raw'
    if (Test-Path -LiteralPath $rawSd) {
        if (-not $DryRun) {
            $null = New-Item -Path $rawLocal -ItemType Directory -Force
            $rcArgs = @($rawSd, $rawLocal, '/MIR', '/XO', '/R:3', '/W:5', '/NP', '/NDL', '/NJH', '/NJS')
            $rcResult = Invoke-BootstrapAiNativeCommand -Exe 'robocopy' -Args $rcArgs -TimeoutMs 120000
            $rcExit = [int]$rcResult['exitCode']
            if ($rcExit -ge 8) {
                $results.Add([ordered]@{ component = 'raw'; status = 'failed'; detail = "robocopy exit $rcExit" })
                Write-Log "ai-memory: robocopy raw import falhou (exit $rcExit)" 'WARN'
            } else {
                $results.Add([ordered]@{ component = 'raw'; status = 'imported'; detail = "robocopy exit $rcExit" })
                Write-Log "ai-memory: raw importado (robocopy exit $rcExit)" 'INFO'
            }
        } else {
            $results.Add([ordered]@{ component = 'raw'; status = 'planned'; detail = 'robocopy /MIR /XO' })
        }
    }

    # db/ - robocopy /MIR /XO
    $dbSd = Join-Path $SdCardPath 'db'
    $dbLocal = Join-Path $DataDir 'db'
    if (Test-Path -LiteralPath $dbSd) {
        if (-not $DryRun) {
            $null = New-Item -Path $dbLocal -ItemType Directory -Force
            $rcArgs = @($dbSd, $dbLocal, '/MIR', '/XO', '/R:3', '/W:5', '/NP', '/NDL', '/NJH', '/NJS')
            $rcResult = Invoke-BootstrapAiNativeCommand -Exe 'robocopy' -Args $rcArgs -TimeoutMs 120000
            $rcExit = [int]$rcResult['exitCode']
            if ($rcExit -ge 8) {
                $results.Add([ordered]@{ component = 'db'; status = 'failed'; detail = "robocopy exit $rcExit" })
                Write-Log "ai-memory: robocopy db import falhou (exit $rcExit)" 'WARN'
            } else {
                $results.Add([ordered]@{ component = 'db'; status = 'imported'; detail = "robocopy exit $rcExit" })
                Write-Log "ai-memory: db importado (robocopy exit $rcExit)" 'INFO'
            }
        } else {
            $results.Add([ordered]@{ component = 'db'; status = 'planned'; detail = 'robocopy /MIR /XO' })
        }
    }

    # config.toml (apenas se local nao existe)
    $configSd = Join-Path $SdCardPath 'config.toml'
    $configLocal = Join-Path $DataDir 'config.toml'
    $sdCardHasConfig = Test-Path -LiteralPath $configSd
    $localHasConfig = Test-Path -LiteralPath $configLocal
    if ($sdCardHasConfig -and (-not $localHasConfig)) {
        if (-not $DryRun) {
            Copy-Item -LiteralPath $configSd -Destination $configLocal -Force -ErrorAction SilentlyContinue
            $results.Add([ordered]@{ component = 'config.toml'; status = 'imported'; detail = '' })
        } else {
            $results.Add([ordered]@{ component = 'config.toml'; status = 'planned'; detail = 'Copy-Item if missing' })
        }
    }

    return ([object[]]$results.ToArray())
}

function Sync-BootstrapAiMemoryWithSdCard {
    <#
    .SYNOPSIS
        Orquestrador de sync bidirecional ai-memory entre host e SDCard.
    .DESCRIPTION
        Fluxo:
        1. Find-BootstrapAiMemorySdCard
        2. Decide direcao (export/import/bidirectional/none)
        3. Executa Export/Import conforme estado
        4. Escreve .phasezero-sync.json no SDCard
    #>
    param(
        [string]$InstallRoot = '',
        [switch]$DryRun
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot

    # 1. Encontra SDCard
    $sdCardPath = Find-BootstrapAiMemorySdCard
    if (-not $sdCardPath) {
        return [ordered]@{
            schemaVersion = 1
            sdCardFound  = $false
            sdCardPath   = ''
            dataDir      = ''
            direction    = 'none'
            results      = @()
            synced       = $false
        }
    }

    # 2. Data dir local
    $dataDir = Get-BootstrapAiMemoryDataDir
    $localExists = Test-Path -LiteralPath $dataDir
    $sdCardHasData = (Test-Path -LiteralPath (Join-Path $sdCardPath 'wiki.git')) -or
                     (Test-Path -LiteralPath (Join-Path $sdCardPath 'raw')) -or
                     (Test-Path -LiteralPath (Join-Path $sdCardPath 'db'))

    # 3. Decide direcao
    if (-not $localExists -and -not $sdCardHasData) {
        Write-Log 'ai-memory: Sync pulado - ambos local e SDCard vazios.' 'INFO'
        return [ordered]@{
            schemaVersion = 1
            sdCardFound  = $true
            sdCardPath   = $sdCardPath
            dataDir      = $dataDir
            direction    = 'none'
            results      = @()
            synced       = $false
        }
    }

    if (-not $localExists -and $sdCardHasData) {
        Write-Log 'ai-memory: Sync direcao=import (SDCard tem dados, local vazio)' 'INFO'
        $results = Import-BootstrapAiMemoryFromSdCard -SdCardPath $sdCardPath -DataDir $dataDir -DryRun:$DryRun
        $direction = 'import'
    } elseif ($localExists -and -not $sdCardHasData) {
        Write-Log 'ai-memory: Sync direcao=export (local tem dados, SDCard vazio)' 'INFO'
        $results = Export-BootstrapAiMemoryToSdCard -SdCardPath $sdCardPath -DataDir $dataDir -DryRun:$DryRun
        $direction = 'export'
    } else {
        Write-Log 'ai-memory: Sync direcao=bidirectional (ambos tem dados, newest-wins)' 'INFO'
        $exportResults = New-Object System.Collections.Generic.List[object]
        $exportTemp = Export-BootstrapAiMemoryToSdCard -SdCardPath $sdCardPath -DataDir $dataDir -DryRun:$DryRun
        if ($exportTemp) { foreach ($item in $exportTemp) { $exportResults.Add($item) | Out-Null } }
        $importResults = New-Object System.Collections.Generic.List[object]
        $importTemp = Import-BootstrapAiMemoryFromSdCard -SdCardPath $sdCardPath -DataDir $dataDir -DryRun:$DryRun
        if ($importTemp) { foreach ($item in $importTemp) { $importResults.Add($item) | Out-Null } }
        $combined = New-Object System.Collections.Generic.List[object]
        foreach ($item in $exportResults) { $combined.Add($item) | Out-Null }
        foreach ($item in $importResults) { $combined.Add($item) | Out-Null }
        $results = @($combined.ToArray())
        $direction = 'bidirectional'
    }

    # 4. Escreve manifest .phasezero-sync.json
    $anyFailed = (@($results | Where-Object { $_ -and $_.status -eq 'failed' }).Count) -gt 0
    $synced = (-not $anyFailed) -and (@($results).Count -gt 0)

    if (-not $DryRun -and $synced) {
        $hostname = if (-not [string]::IsNullOrWhiteSpace($env:COMPUTERNAME)) { $env:COMPUTERNAME } else { 'unknown' }
        $manifest = [ordered]@{
            lastSync   = (Get-Date).ToString('o')
            sourceHost = $hostname
            sourceUser = $env:USERNAME
            direction  = $direction
            components = @($results)
        }
        $manifestPath = Join-Path $sdCardPath '.phasezero-sync.json'
        $manifestJson = ConvertTo-Json -InputObject $manifest -Depth 5
        Write-BootstrapAtomicText -Path $manifestPath -Content $manifestJson
    }

    return [ordered]@{
        schemaVersion = 1
        sdCardFound  = $true
        sdCardPath   = $sdCardPath
        dataDir      = $dataDir
        direction    = $direction
        results      = @($results)
        synced       = $synced
    }
}

function Ensure-BootstrapAiMemorySyncTask {
    <#
    .SYNOPSIS
        Cria scheduled task para sync automatico do ai-memory com SDCard.
    .DESCRIPTION
        Triggers: logon + diario 12pm.
        Executa launcher .ps1 que dot-source bootstrap-tools.ps1 e chama Sync-BootstrapAiMemoryWithSdCard.
    #>
    param(
        [string]$BootstrapScriptPath = '',
        [switch]$DryRun
    )
    $taskName = 'BootstrapTools-AiMemorySync'

    if ([string]::IsNullOrWhiteSpace($BootstrapScriptPath)) {
        $BootstrapScriptPath = $PSCommandPath
    }

    $aiRoot = Get-BootstrapAiInstallRoot -InstallRoot ''
    $launcherDir = Get-BootstrapAiMemoryInstallDir -InstallRoot $aiRoot
    $launcherPath = Join-Path $launcherDir 'ai-memory-sync-launcher.ps1'

    $launcherContent = @"
# ai-memory SDCard sync launcher - gerado por PhaseZero BootstrapTools
# Nao edite manualmente; reexecute a instalacao para recriar.
param()
`$ErrorActionPreference = 'Stop'
`$logPath = Join-Path '$launcherDir' 'ai-memory-sync-launcher.log'
try {
    . '$BootstrapScriptPath'
    `$result = Sync-BootstrapAiMemoryWithSdCard
    if (`$result.synced) {
        "OK direcao=`$(`$result.direction) sdCard=`$(`$result.sdCardPath)" | Out-File -LiteralPath `$logPath -Encoding utf8 -Force
    } else {
        "SKIP razao=sdCardFound=`$(`$result.sdCardFound)" | Out-File -LiteralPath `$logPath -Encoding utf8 -Force
    }
} catch {
    "ERROR `$_" | Out-File -LiteralPath `$logPath -Encoding utf8 -Force
    exit 1
}
exit 0
"@

    if ($DryRun) {
        return [ordered]@{
            status   = 'planned'
            task     = $taskName
            launcher = $launcherPath
            script   = $BootstrapScriptPath
        }
    }

    try {
        Write-BootstrapAtomicText -Path $launcherPath -Content $launcherContent
    } catch {
        return [ordered]@{ status = 'failed'; task = $taskName; reason = "launcher-write: $($_.Exception.Message)" }
    }

    if (Get-Command -Name Register-ScheduledTask -ErrorAction SilentlyContinue) {
        try {
            $existing = Get-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue
            if ($existing) { Unregister-ScheduledTask -TaskName $taskName -Confirm:$false -ErrorAction SilentlyContinue }

            $action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$launcherPath`""
            $triggers = @(
                (New-ScheduledTaskTrigger -AtLogOn -User $env:USERNAME)
                (New-ScheduledTaskTrigger -Daily -At 12pm)
            )
            $principal = New-ScheduledTaskPrincipal -UserId ("{0}\{1}" -f $env:USERDOMAIN, $env:USERNAME) -LogonType Interactive -RunLevel Limited
            $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit ([TimeSpan]::FromHours(1))
            $settings.Hidden = $true
            Register-ScheduledTask -TaskName $taskName -Action $action -Trigger $triggers -Principal $principal -Settings $settings -Description 'Sincroniza ai-memory com SDCard (wiki/raw/db) no logon e diariamente.' -ErrorAction Stop | Out-Null
            Write-Log "ai-memory: Sync task '$taskName' registrada (logon + diario 12pm)" 'INFO'
            return [ordered]@{ status = 'registered'; task = $taskName; method = 'register-scheduledtask' }
        } catch {
            Write-Log ("ai-memory: Register-ScheduledTask sync falhou ({0})" -f $_.Exception.Message) 'WARN'
            return [ordered]@{ status = 'failed'; task = $taskName; reason = $_.Exception.Message; method = 'register-scheduledtask' }
        }
    }

    return [ordered]@{ status = 'skipped'; task = $taskName; reason = 'Register-ScheduledTask cmdlet nao disponivel' }
}

function Uninstall-BootstrapAiNpmTool {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [switch]$DryRun
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $prefix = Get-BootstrapAiNpmPrefix -InstallRoot $root
    $packageName = [string]$CatalogEntry['PackageName']
    if ($DryRun) {
        return (New-BootstrapAiToolResult -ToolName $ToolName -Action 'uninstall' -Status 'planned' -InstallRoot $root -Message ("npm uninstall -g --prefix `"{0}`" {1}" -f $prefix, $packageName) -Docs ([string]$CatalogEntry['DocsUrl']))
    }

    $manifest = Read-BootstrapAiToolManifest -InstallRoot $root
    if ((-not $manifest['tools'].ContainsKey($ToolName)) -and -not (Test-Path -LiteralPath $prefix)) {
        Remove-PathUserEntry -Dir $prefix | Out-Null
        return (New-BootstrapAiToolResult -ToolName $ToolName -Action 'uninstall' -Status 'absent' -InstallRoot $root -Message 'Nada gerenciado pelo projeto encontrado.' -Docs ([string]$CatalogEntry['DocsUrl']))
    }

    if (-not [string]::IsNullOrWhiteSpace($packageName) -and (Test-Path -LiteralPath $prefix)) {
        $npmCmd = Get-BootstrapNpmCommandForAiTools
        $result = Invoke-BootstrapAiNativeCommand -Exe $npmCmd -Args @('uninstall','-g','--prefix',$prefix,$packageName) -TimeoutMs 600000
        if ([int]$result['exitCode'] -ne 0) {
            $detail = ([string]$result['stderr']).Trim()
            if ([string]::IsNullOrWhiteSpace($detail)) { $detail = ([string]$result['stdout']).Trim() }
            throw ("Falha ao desinstalar {0} via npm prefixado (exit={1}). {2}" -f $ToolName, [int]$result['exitCode'], $detail)
        }
    }

    if ($manifest['tools'].ContainsKey($ToolName)) { $manifest['tools'].Remove($ToolName) | Out-Null }
    $otherUsesPrefix = $false
    foreach ($entryName in @($manifest['tools'].Keys)) {
        $entry = $manifest['tools'][$entryName]
        if ($entry -is [hashtable] -and $entry.ContainsKey('prefix') -and ([string]$entry['prefix']).TrimEnd('\') -ieq $prefix.TrimEnd('\')) {
            $otherUsesPrefix = $true
        }
    }
    if (-not $otherUsesPrefix) {
        Remove-PathUserEntry -Dir $prefix | Out-Null
        if ($manifest['pathsAdded'].ContainsKey($prefix)) { $manifest['pathsAdded'].Remove($prefix) | Out-Null }
    }
    Write-BootstrapAiToolManifest -InstallRoot $root -Manifest $manifest | Out-Null

    return (New-BootstrapAiToolResult -ToolName $ToolName -Action 'uninstall' -Status 'removed' -InstallRoot $root -Message 'Artefatos gerenciados removidos.' -Docs ([string]$CatalogEntry['DocsUrl']))
}

function Install-BootstrapRtkTool {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$CatalogEntry,
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [switch]$DryRun
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $binDir = Get-BootstrapAiBinDir -InstallRoot $root
    if ($DryRun) {
        return (New-BootstrapAiToolResult -ToolName 'rtk' -Action 'install' -Status 'planned' -InstallRoot $root -Message 'Baixar release oficial GitHub, validar checksum se publicado, instalar rtk.exe em bin gerenciado.' -Docs ([string]$CatalogEntry['DocsUrl']))
    }

    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    $api = 'https://api.github.com/repos/rtk-ai/rtk/releases/latest'
    $release = Invoke-RestMethod -Uri $api -Headers @{ 'User-Agent' = 'PhaseZero-Bootstrap' } -ErrorAction Stop
    $assets = @($release.assets)
    $asset = @($assets | Where-Object {
        ([string]$_.name) -match '(?i)(windows|win|pc-windows|x86_64-pc-windows|x64)' -and
        ([string]$_.name) -match '(?i)\.(zip|exe)$'
    } | Select-Object -First 1)
    if (-not $asset) {
        return (New-BootstrapAiToolResult -ToolName 'rtk' -Action 'install' -Status 'blocked' -InstallRoot $root -Message 'Release oficial nao publicou asset Windows compativel detectavel.' -Docs ([string]$CatalogEntry['DocsUrl']))
    }

    [void][System.IO.Directory]::CreateDirectory($binDir)
    $downloadRoot = Join-Path $root 'downloads'
    [void][System.IO.Directory]::CreateDirectory($downloadRoot)
    $assetPath = Join-Path $downloadRoot ([string]$asset.name)
    Invoke-WebRequest -Uri ([string]$asset.browser_download_url) -OutFile $assetPath -UseBasicParsing -Headers @{ 'User-Agent' = 'PhaseZero-Bootstrap' } -ErrorAction Stop

    $checksumAsset = @($assets | Where-Object { ([string]$_.name) -ieq (([string]$asset.name) + '.sha256') -or ([string]$_.name) -ieq 'SHA256SUMS' -or ([string]$_.name) -ieq 'checksums.txt' } | Select-Object -First 1)
    if ($checksumAsset) {
        $checksumPath = Join-Path $downloadRoot ([string]$checksumAsset.name)
        Invoke-WebRequest -Uri ([string]$checksumAsset.browser_download_url) -OutFile $checksumPath -UseBasicParsing -Headers @{ 'User-Agent' = 'PhaseZero-Bootstrap' } -ErrorAction Stop
        $expectedText = Get-Content -LiteralPath $checksumPath -Raw
        $expected = ''
        foreach ($line in @($expectedText -replace "`r", '' -split "`n")) {
            if ([string]$line -match [regex]::Escape([string]$asset.name)) {
                $expected = ([regex]::Match([string]$line, '(?i)\b[a-f0-9]{64}\b')).Value
                if (-not [string]::IsNullOrWhiteSpace($expected)) { break }
            }
        }
        if ([string]::IsNullOrWhiteSpace($expected)) {
            $expected = ([regex]::Match($expectedText, '(?i)\b[a-f0-9]{64}\b')).Value
        }
        if (-not [string]::IsNullOrWhiteSpace($expected)) {
            $actual = Get-BootstrapFileSha256 -Path $assetPath
            if ($actual -ne $expected.ToLowerInvariant()) {
                throw "Checksum RTK invalido. Esperado=$expected Atual=$actual"
            }
        }
    }

    $rtkExe = Join-Path $binDir 'rtk.exe'
    if ([string]$asset.name -match '(?i)\.zip$') {
        $extractRoot = Join-Path $downloadRoot ([System.IO.Path]::GetFileNameWithoutExtension([string]$asset.name))
        if (Test-Path -LiteralPath $extractRoot) { Remove-Item -LiteralPath $extractRoot -Recurse -Force }
        Expand-Archive -LiteralPath $assetPath -DestinationPath $extractRoot -Force
        $found = Get-ChildItem -LiteralPath $extractRoot -Recurse -Filter 'rtk.exe' | Select-Object -First 1
        if (-not $found) { throw 'Asset RTK baixado, mas rtk.exe nao foi encontrado dentro do zip.' }
        Copy-Item -LiteralPath $found.FullName -Destination $rtkExe -Force
    } else {
        Copy-Item -LiteralPath $assetPath -Destination $rtkExe -Force
    }

    Ensure-PathUserContains -Dir $binDir
    $manifest = Read-BootstrapAiToolManifest -InstallRoot $root
    $manifest['tools']['rtk'] = @{
        kind        = 'github-release'
        source      = [string]$asset.browser_download_url
        version     = [string]$release.tag_name
        binDir      = $binDir
        installedAt = (Get-Date).ToString('o')
    }
    $manifest['pathsAdded'][$binDir] = $true
    Write-BootstrapAiToolManifest -InstallRoot $root -Manifest $manifest | Out-Null
    $version = Get-BootstrapAiToolVersion -CatalogEntry $CatalogEntry -CommandPath $rtkExe
    return (New-BootstrapAiToolResult -ToolName 'rtk' -Action 'install' -Status 'installed' -InstallRoot $root -Message 'RTK instalado por release oficial GitHub.' -Docs ([string]$CatalogEntry['DocsUrl']) -CommandPath $rtkExe -Version $version)
}

function Uninstall-BootstrapRtkTool {
    param(
        [Parameter(Mandatory = $true)][string]$InstallRoot,
        [switch]$DryRun
    )
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $binDir = Get-BootstrapAiBinDir -InstallRoot $root
    if ($DryRun) {
        return (New-BootstrapAiToolResult -ToolName 'rtk' -Action 'uninstall' -Status 'planned' -InstallRoot $root -Message 'Remover rtk.exe gerenciado e PATH adicionado pelo projeto.' -Docs 'https://www.rtk-ai.app/docs/')
    }
    $rtkExe = Join-Path $binDir 'rtk.exe'
    if (Test-Path -LiteralPath $rtkExe) { Remove-Item -LiteralPath $rtkExe -Force }
    Remove-PathUserEntry -Dir $binDir | Out-Null
    $manifest = Read-BootstrapAiToolManifest -InstallRoot $root
    if ($manifest['tools'].ContainsKey('rtk')) { $manifest['tools'].Remove('rtk') | Out-Null }
    if ($manifest['pathsAdded'].ContainsKey($binDir)) { $manifest['pathsAdded'].Remove($binDir) | Out-Null }
    Write-BootstrapAiToolManifest -InstallRoot $root -Manifest $manifest | Out-Null
    return (New-BootstrapAiToolResult -ToolName 'rtk' -Action 'uninstall' -Status 'removed' -InstallRoot $root -Message 'RTK gerenciado removido.' -Docs 'https://www.rtk-ai.app/docs/')
}

function Set-BootstrapAntigravityWorkflows {
    param(
        [string]$ProjectRoot = '',
        [switch]$DryRun
    )
    $root = if ([string]::IsNullOrWhiteSpace($ProjectRoot)) { (Get-Location).Path } else { [System.IO.Path]::GetFullPath($ProjectRoot) }
    $workflowRoot = Join-Path $root '.antigravity\workflows'
    if ($DryRun) {
        return (New-BootstrapAiToolResult -ToolName 'antigravity-workflows' -Action 'configure' -Status 'planned' -ProjectRoot $root -Message "Criar templates em $workflowRoot" -Docs 'https://antigravity.google/')
    }

    [void][System.IO.Directory]::CreateDirectory($workflowRoot)
    $templates = [ordered]@{
        'planning.md' = @(
            '# Planning'
            ''
            '- Read repository state before proposing work.'
            '- List assumptions, blockers, validation commands, and rollback scope.'
            '- Do not write secrets. Use placeholders and secure stores.'
        ) -join [Environment]::NewLine
        'backend.md' = @(
            '# Backend'
            ''
            '- Keep changes scoped to existing service boundaries.'
            '- Add tests for every behavior change.'
            '- Validate install, upgrade, and uninstall flows when touched.'
        ) -join [Environment]::NewLine
        'frontend.md' = @(
            '# Frontend'
            ''
            '- Preserve keyboard focus, readable labels, and clear status states.'
            '- Validate XAML parse/load before claiming UI readiness.'
            '- Avoid false success messages.'
        ) -join [Environment]::NewLine
        'tests.md' = @(
            '# Tests'
            ''
            '- Start with failing coverage for each fix.'
            '- Exercise path-with-spaces, dependency-missing, offline, idempotent install, and idempotent uninstall cases.'
            '- Record exact commands and exit codes.'
        ) -join [Environment]::NewLine
        'review.md' = @(
            '# Review'
            ''
            '- Prioritize bugs, destructive side effects, secret handling, and unsupported external claims.'
            '- Confirm official sources for tool installs and model/provider availability.'
            '- Verify repo diff contains only intentional changes.'
        ) -join [Environment]::NewLine
    }

    foreach ($name in @($templates.Keys)) {
        $path = Join-Path $workflowRoot $name
        if (Test-Path -LiteralPath $path) { Backup-BootstrapFile -Path $path | Out-Null }
        [System.IO.File]::WriteAllText($path, [string]$templates[$name], [System.Text.UTF8Encoding]::new($false))
    }

    return (New-BootstrapAiToolResult -ToolName 'antigravity-workflows' -Action 'configure' -Status 'configured' -ProjectRoot $root -Message "Workflows gerados em $workflowRoot" -Docs 'https://antigravity.google/')
}

function Invoke-BootstrapAiToolAction {
    param(
        [Parameter(Mandatory = $true)][string]$ToolName,
        [ValidateSet('install','validate','configure','start','uninstall','gain','docs')][string]$Action = 'validate',
        [string]$InstallRoot = '',
        [string]$ProjectRoot = '',
        [switch]$DryRun,
        [switch]$Yes,
        [switch]$NoAdmin
    )

    $null = $Yes
    $null = $NoAdmin
    $name = Normalize-BootstrapAiToolName -ToolName $ToolName
    $catalog = Get-BootstrapAiToolCatalog
    if (-not $catalog.Contains($name)) { throw "AI tool desconhecida: $ToolName" }
    $entry = $catalog[$name]
    $root = Get-BootstrapAiInstallRoot -InstallRoot $InstallRoot
    $project = if ([string]::IsNullOrWhiteSpace($ProjectRoot)) { (Get-Location).Path } else { [System.IO.Path]::GetFullPath($ProjectRoot) }

    if ($name -eq 'openclaw' -and $Action -notin @('validate','docs','uninstall')) {
        $result = New-BootstrapAiToolResult -ToolName $name -Action $Action -Status 'blocked' -InstallRoot $root -ProjectRoot $project -Message 'OpenClaw blocked: account grants are not bound to each request.' -Docs ([string]$entry['DocsUrl'])
        $result['ready'] = $false
        $result['usageBlocked'] = $true
        $result['blockedReason'] = 'connection-grant-not-enforceable'
        return $result
    }

    if ($Action -eq 'validate') {
        $row = @(Get-BootstrapAiToolStatusRows -InstallRoot $root -ProjectRoot $project | Where-Object { [string]$_['tool'] -eq $name } | Select-Object -First 1)
        if ($row.Count -eq 0) {
            return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status 'error' -InstallRoot $root -ProjectRoot $project -Message 'Status nao encontrado.' -Docs ([string]$entry['DocsUrl']))
        }
        $result = New-BootstrapAiToolResult -ToolName $name -Action $Action -Status ([string]$row[0]['status']) -InstallRoot $root -ProjectRoot $project -Message ([string]$row[0]['message']) -Docs ([string]$row[0]['docs']) -CommandPath ([string]$row[0]['commandPath']) -Version ([string]$row[0]['version'])
        if ($name -eq 'openclaw') {
            $result['ready'] = $false
            $result['usageBlocked'] = $true
            $result['blockedReason'] = 'connection-grant-not-enforceable'
        }
        return $result
    }

    if ($Action -eq 'docs') {
        return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status 'manual' -InstallRoot $root -ProjectRoot $project -Message ([string]$entry['DocsUrl']) -Docs ([string]$entry['DocsUrl']))
    }

    if ($Action -eq 'start') {
        if ($name -eq 'ai-proxy-suite') {
            return (Start-BootstrapAiProxySuite -InstallRoot $root -DryRun:$DryRun -TimeoutMs 30000)
        }
        if (Test-BootstrapAiProxyToolName -ToolName $name) {
            return (Start-BootstrapAiProxyTool -ToolName $name -InstallRoot $root -DryRun:$DryRun -TimeoutMs 30000)
        }
        return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status 'manual' -InstallRoot $root -ProjectRoot $project -Message 'Start gerenciado existe apenas para proxies locais PhaseZero.' -Docs ([string]$entry['DocsUrl']))
    }

    if ($Action -eq 'gain') {
        if ($name -ne 'rtk') {
            return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status 'blocked' -InstallRoot $root -ProjectRoot $project -Message 'gain existe apenas para RTK.' -Docs ([string]$entry['DocsUrl']))
        }
        $commandPath = Resolve-BootstrapAiToolCommandPath -CatalogEntry $entry -InstallRoot $root
        if ([string]::IsNullOrWhiteSpace($commandPath)) {
            return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status 'absent' -InstallRoot $root -ProjectRoot $project -Message 'rtk nao encontrado.' -Docs ([string]$entry['DocsUrl']))
        }
        if ($DryRun) {
            return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status 'planned' -InstallRoot $root -ProjectRoot $project -Message 'rtk gain' -Docs ([string]$entry['DocsUrl']) -CommandPath $commandPath)
        }
        $result = Invoke-BootstrapAiNativeCommand -Exe $commandPath -Args @('gain') -TimeoutMs 120000
        $status = if ([int]$result['exitCode'] -eq 0) { 'validated' } else { 'error' }
        return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status $status -InstallRoot $root -ProjectRoot $project -Message ([string]$result['firstLine']) -Docs ([string]$entry['DocsUrl']) -CommandPath $commandPath)
    }

    if ($Action -eq 'configure') {
        if ($name -eq 'ai-proxy-suite') {
            $defaults = Set-BootstrapAiProxyIdeDefault -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun
            $status = [string]$defaults['status']
            $result = New-BootstrapAiToolResult -ToolName $name -Action $Action -Status $status -InstallRoot $root -ProjectRoot $project -Message 'AI proxy suite configurada para IDEs: Kimi default, demais providers selecionaveis.' -Docs ([string]$entry['DocsUrl'])
            $result['defaultProvider'] = [string]$defaults['defaultProvider']
            $result['defaultBaseUrl'] = [string]$defaults['defaultBaseUrl']
            $result['defaultModel'] = [string]$defaults['defaultModel']
            $result['providers'] = @($defaults['providers'])
            $result['targets'] = $defaults['targetUpdates']
            $result['manifestPath'] = [string]$defaults['manifestPath']
            return $result
        }
        if (Test-BootstrapAiProxyToolName -ToolName $name) {
            return (Set-BootstrapAiProxyEnvironment -ToolName $name -CatalogEntry $entry -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun)
        }
        if ($name -eq 'antigravity-workflows') {
            return (Set-BootstrapAntigravityWorkflows -ProjectRoot $project -DryRun:$DryRun)
        }
        if ($name -eq 'rtk') {
            $commandPath = Resolve-BootstrapAiToolCommandPath -CatalogEntry $entry -InstallRoot $root
            if ([string]::IsNullOrWhiteSpace($commandPath)) {
                return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status 'absent' -InstallRoot $root -ProjectRoot $project -Message 'rtk nao encontrado para rtk init.' -Docs ([string]$entry['DocsUrl']))
            }
            if ($DryRun) {
                return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status 'planned' -InstallRoot $root -ProjectRoot $project -Message 'rtk init' -Docs ([string]$entry['DocsUrl']) -CommandPath $commandPath)
            }
            $result = Invoke-BootstrapAiNativeCommand -Exe $commandPath -Args @('init') -TimeoutMs 120000
            if ([int]$result['exitCode'] -ne 0) {
                throw ("rtk init falhou (exit={0}). {1}" -f [int]$result['exitCode'], ([string]$result['stderr']).Trim())
            }
            return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status 'configured' -InstallRoot $root -ProjectRoot $project -Message 'rtk init validado.' -Docs ([string]$entry['DocsUrl']) -CommandPath $commandPath)
        }
        if ($name -eq 'ai-usagebar') {
            return (Set-BootstrapAiUsagebarConfig -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun)
        }
        if ($name -eq 'ai-memory') {
            return (Set-BootstrapAiMemoryConfig -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun)
        }
        if ($name -eq 'aionui') {
            $config = Set-BootstrapAionUiProviderConfig -DryRun:$DryRun -StartOnce:((-not $DryRun) -and (-not $NoAdmin))
            $status = [string]$config['status']
            $result = New-BootstrapAiToolResult -ToolName $name -Action $Action -Status $status -InstallRoot $root -ProjectRoot $project -Message ([string]$config['reason']) -Docs ([string]$entry['WikiUrl'])
            $result['configuration'] = $config
            $result['providerEnv'] = @(Get-BootstrapAionUiEnvProviderCandidates)
            return $result
        }
        return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status 'manual' -InstallRoot $root -ProjectRoot $project -Message 'Configuracao requer login/chave do usuario; nada foi gravado no repositorio.' -Docs ([string]$entry['DocsUrl']))
    }

    if ($Action -eq 'install') {
        switch ([string]$entry['InstallSupport']) {
            'npm-prefix' { return (Install-BootstrapAiNpmTool -ToolName $name -CatalogEntry $entry -InstallRoot $root -DryRun:$DryRun) }
            'wsl-installer' {
                if ($name -eq 'hermes-agent') { return (Install-BootstrapHermesAgentWsl -CatalogEntry $entry -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun) }
                if ($name -eq 'ai-jail') { return (Install-BootstrapAiJailWsl -CatalogEntry $entry -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun) }
            }
            'github-release' {
                if ($name -eq 'rtk') { return (Install-BootstrapRtkTool -CatalogEntry $entry -InstallRoot $root -DryRun:$DryRun) }
            }
            'workflow-only' { return (Set-BootstrapAntigravityWorkflows -ProjectRoot $project -DryRun:$DryRun) }
            'linux-release' {
                if ($name -eq 'ai-usagebar') { return (Install-BootstrapAiUsagebar -CatalogEntry $entry -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun) }
            }
            'native-release' {
                if ($name -eq 'ai-memory') { return (Install-BootstrapAiMemory -CatalogEntry $entry -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun) }
            }
            'winget-official-exe' {
                if ($name -eq 'aionui') { return (Install-BootstrapAionUiComponentPackage -CatalogEntry $entry -DryRun:$DryRun -NoAdmin:$NoAdmin) }
            }
            'git-node-playwright-proxy' { return (Install-BootstrapAiProxyManagedTool -ToolName $name -CatalogEntry $entry -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun) }
            'git-node-proxy' { return (Install-BootstrapAiProxyManagedTool -ToolName $name -CatalogEntry $entry -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun) }
            'git-go-proxy' { return (Install-BootstrapAiProxyManagedTool -ToolName $name -CatalogEntry $entry -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun) }
            'git-tauri-app' { return (Install-BootstrapAiProxyManagedTool -ToolName $name -CatalogEntry $entry -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun) }
            'ai-proxy-suite' { return (Install-BootstrapAiProxySuiteManagedTool -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun) }
        }
        $status = if ($DryRun) { 'planned' } else { 'manual' }
        return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status $status -InstallRoot $root -ProjectRoot $project -Message ([string]$entry['Notes']) -Docs ([string]$entry['DocsUrl']))
    }

    if ($Action -eq 'uninstall') {
        switch ([string]$entry['InstallSupport']) {
            'npm-prefix' { return (Uninstall-BootstrapAiNpmTool -ToolName $name -CatalogEntry $entry -InstallRoot $root -DryRun:$DryRun) }
            'wsl-installer' {
                if ($name -eq 'ai-jail') { return (Uninstall-BootstrapAiJailWsl -CatalogEntry $entry -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun) }
                $status = if ($DryRun) { 'planned' } else { 'manual' }
                return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status $status -InstallRoot $root -ProjectRoot $project -Message 'Remocao do Hermes Agent em WSL2 requer decisao manual para preservar ~/.hermes e dados do usuario.' -Docs ([string]$entry['DocsUrl']))
            }
            'github-release' {
                if ($name -eq 'rtk') { return (Uninstall-BootstrapRtkTool -InstallRoot $root -DryRun:$DryRun) }
            }
            'workflow-only' {
                $status = if ($DryRun) { 'planned' } else { 'manual' }
                return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status $status -InstallRoot $root -ProjectRoot $project -Message 'Remocao de workflows requer decisao manual; arquivos podem conter edicoes do usuario.' -Docs ([string]$entry['DocsUrl']))
            }
            'linux-release' {
                if ($name -eq 'ai-usagebar') { return (Uninstall-BootstrapAiUsagebar -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun) }
            }
            'native-release' {
                if ($name -eq 'ai-memory') { return (Uninstall-BootstrapAiMemory -InstallRoot $root -ProjectRoot $project -DryRun:$DryRun) }
            }
            'git-node-playwright-proxy' {
                $status = if ($DryRun) { 'planned' } else { 'manual' }
                return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status $status -InstallRoot $root -ProjectRoot $project -Message 'Remocao de proxy local preserva repo, profiles, .env e sessoes do navegador; remova manualmente se tiver backup.' -Docs ([string]$entry['DocsUrl']))
            }
            'git-node-proxy' {
                $status = if ($DryRun) { 'planned' } else { 'manual' }
                return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status $status -InstallRoot $root -ProjectRoot $project -Message 'Remocao de proxy local preserva repo e .env; remova manualmente se tiver backup.' -Docs ([string]$entry['DocsUrl']))
            }
            'git-go-proxy' {
                $status = if ($DryRun) { 'planned' } else { 'manual' }
                return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status $status -InstallRoot $root -ProjectRoot $project -Message 'Remocao de proxy local preserva repo e .env; remova manualmente se tiver backup.' -Docs ([string]$entry['DocsUrl']))
            }
            'git-tauri-app' {
                $status = if ($DryRun) { 'planned' } else { 'manual' }
                return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status $status -InstallRoot $root -ProjectRoot $project -Message 'Remocao de app Tauri gerenciado preserva fonte local; remova manualmente se tiver backup.' -Docs ([string]$entry['DocsUrl']))
            }
        }
        $status = if ($DryRun) { 'planned' } else { 'manual' }
        return (New-BootstrapAiToolResult -ToolName $name -Action $Action -Status $status -InstallRoot $root -ProjectRoot $project -Message 'Nenhum artefato gerenciado pelo projeto para remover.' -Docs ([string]$entry['DocsUrl']))
    }
}

function Ensure-BootstrapNamedMap {
    param(
        [Parameter(Mandatory = $true)][hashtable]$Parent,
        [Parameter(Mandatory = $true)][string]$Name
    )

    if (-not $Parent.ContainsKey($Name) -or -not ($Parent[$Name] -is [hashtable])) {
        $Parent[$Name] = @{}
    }
    return $Parent[$Name]
}

function Remove-BootstrapEmptyNamedMap {
    param(
        [Parameter(Mandatory = $true)][hashtable]$Parent,
        [Parameter(Mandatory = $true)][string]$Name
    )

    if ($Parent.ContainsKey($Name) -and ($Parent[$Name] -is [hashtable]) -and ($Parent[$Name].Count -eq 0)) {
        $Parent.Remove($Name) | Out-Null
        return $true
    }
    return $false
}

function Set-BootstrapNonEmptyStringValues {
    param(
        [Parameter(Mandatory = $true)][hashtable]$Target,
        [Parameter(Mandatory = $true)][hashtable]$Values
    )

    foreach ($key in $Values.Keys) {
        $value = Normalize-BootstrapScalarString -Value $Values[$key]
        if ([string]::IsNullOrWhiteSpace($value)) { continue }
        $Target[[string]$key] = $value
    }
}

function Normalize-BootstrapScalarString {
    param([AllowNull()][object]$Value)

    $text = if ($null -eq $Value) { '' } else { [string]$Value }
    $text = $text.Trim()
    if ($text.Length -ge 2) {
        foreach ($wrapper in @('`', '"', "'")) {
            if ($text.StartsWith($wrapper) -and $text.EndsWith($wrapper) -and $text.Length -ge 2) {
                $text = $text.Substring(1, $text.Length - 2).Trim()
                break
            }
        }
    }
    return $text
}

