function Get-BootstrapHermesConfigPath {
    param([AllowNull()][hashtable]$State = $null)

    $root = ''
    if (($State -is [hashtable]) -and -not [string]::IsNullOrWhiteSpace([string]$State.CloneBaseDir) -and (Test-Path ([string]$State.CloneBaseDir))) {
        $root = [string]$State.CloneBaseDir
    } elseif (-not [string]::IsNullOrWhiteSpace((Get-Location).Path)) {
        $root = (Get-Location).Path
    }
    if ([string]::IsNullOrWhiteSpace($root)) { return $null }
    return (Join-Path (Join-Path $root '.hermes') 'opencloud.json')
}

function Test-BootstrapSecretsProviderCredential {
    param(
        [Parameter(Mandatory = $true)][string]$ProviderName,
        [Parameter(Mandatory = $true)][hashtable]$ProviderDefinition,
        [Parameter(Mandatory = $true)][string]$CredentialId,
        [Parameter(Mandatory = $true)][hashtable]$Credential,
        [int]$TimeoutSeconds = 15
    )
    if ($TimeoutSeconds -lt 1) { $TimeoutSeconds = 1 }
    if ($TimeoutSeconds -gt 120) { $TimeoutSeconds = 120 }

    $catalog = Get-BootstrapSecretsProviderCatalog
    $checkedAt = (Get-Date).ToString('o')
    $providerMeta = if ($catalog.Contains($ProviderName)) { $catalog[$ProviderName] } else { @{} }
    $validationKind = if ($providerMeta.ContainsKey('validationKind')) { [string]$providerMeta['validationKind'] } else { 'unsupported' }
    $secret = [string]$Credential['secret']
    if ([string]::IsNullOrWhiteSpace($secret)) {
        return (New-BootstrapSecretValidationState -State 'failed' -CheckedAt $checkedAt -Message 'secret vazio')
    }

    $baseUrl = ''
    if ($Credential.ContainsKey('baseUrl') -and -not [string]::IsNullOrWhiteSpace([string]$Credential['baseUrl'])) {
        $baseUrl = [string]$Credential['baseUrl']
    } elseif ($ProviderDefinition.ContainsKey('defaults') -and ($ProviderDefinition['defaults'] -is [hashtable]) -and -not [string]::IsNullOrWhiteSpace([string]$ProviderDefinition['defaults']['baseUrl'])) {
        $baseUrl = [string]$ProviderDefinition['defaults']['baseUrl']
    } elseif ($providerMeta.ContainsKey('defaults') -and ($providerMeta['defaults'] -is [hashtable]) -and -not [string]::IsNullOrWhiteSpace([string]$providerMeta['defaults']['baseUrl'])) {
        $baseUrl = [string]$providerMeta['defaults']['baseUrl']
    }

    $headers = @{}
    $uri = ''
    switch ($validationKind) {
        'anthropic' {
            $uri = 'https://api.anthropic.com/v1/models'
            $headers = @{
                'x-api-key' = $secret
                'anthropic-version' = '2023-06-01'
            }
        }
        'google' {
            $uri = 'https://generativelanguage.googleapis.com/v1beta/models?key=' + [Uri]::EscapeDataString($secret)
        }
        'github' {
            $uri = 'https://api.github.com/user'
            $headers = @{
                Authorization = "Bearer $secret"
                Accept = 'application/vnd.github+json'
                'X-GitHub-Api-Version' = '2022-11-28'
                'User-Agent' = 'PhaseZero Bootstrap'
            }
        }
        'openaiCompatible' {
            if ([string]::IsNullOrWhiteSpace($baseUrl)) {
                return (New-BootstrapSecretValidationState -State 'failed' -CheckedAt $checkedAt -Message 'baseUrl ausente')
            }
            $uri = ($baseUrl.TrimEnd('/') + '/models')
            $headers = @{
                Authorization = "Bearer $secret"
            }
        }
        default {
            return (New-BootstrapSecretValidationState -State 'unsupported/manual-review' -CheckedAt $checkedAt -Message 'sem validador dedicado')
        }
    }

    try {
        $null = Invoke-RestMethod -Method Get -Uri $uri -Headers $headers -TimeoutSec $TimeoutSeconds -ErrorAction Stop
        return (New-BootstrapSecretValidationState -State 'passed' -CheckedAt $checkedAt -Message 'ok')
    } catch {
        # Sanitize the failure message so the secret can't leak through the
        # Authorization header / x-api-key / google ?key= URL parameter into logs.
        $msg = [string]$_.Exception.Message
        if (-not [string]::IsNullOrWhiteSpace($secret)) {
            try { $msg = $msg.Replace($secret, '<redacted>') } catch { }
            try {
                $escaped = [Uri]::EscapeDataString($secret)
                if ($escaped -ne $secret) { $msg = $msg.Replace($escaped, '<redacted>') }
            } catch { }
        }
        return (New-BootstrapSecretValidationState -State 'failed' -CheckedAt $checkedAt -Message $msg)
    }
}

function Test-BootstrapClaudeOrganizationAccessError {
    param([AllowNull()][string]$Message)

    if ([string]::IsNullOrWhiteSpace($Message)) { return $false }
    $normalized = $Message.ToLowerInvariant()
    return (
        $normalized.Contains('organization does not have access to claude') -or
        ($normalized.Contains('does not have access to claude') -and $normalized.Contains('organization')) -or
        ($normalized.Contains('contact your administrator') -and $normalized.Contains('claude')) -or
        ($normalized.Contains('no access') -and $normalized.Contains('claude'))
    )
}

function Invoke-BootstrapSecretsValidation {
    param(
        [Parameter(Mandatory = $true)]$SecretsData,
        [switch]$ValidateAll
    )

    $normalized = Normalize-BootstrapSecretsData -Secrets $SecretsData

    foreach ($providerName in @($normalized.providers.Keys)) {
        $provider = ConvertTo-BootstrapHashtable -InputObject $normalized.providers[$providerName]
        if (-not ($provider -is [hashtable])) { continue }
        if (-not ($provider.ContainsKey('credentials') -and ($provider['credentials'] -is [hashtable]))) { continue }

        $credentialIds = @()
        if ($ValidateAll) {
            $credentialIds = @($provider['credentials'].Keys)
        } else {
            $activeCredential = [string]$provider['activeCredential']
            if (-not [string]::IsNullOrWhiteSpace($activeCredential) -and $provider['credentials'].Contains($activeCredential)) {
                $credentialIds = @($activeCredential)
            }
        }

        foreach ($credentialId in $credentialIds) {
            $credential = ConvertTo-BootstrapHashtable -InputObject $provider['credentials'][$credentialId]
            if (-not ($credential -is [hashtable])) { continue }
            $provider['credentials'][$credentialId]['validation'] = Test-BootstrapSecretsProviderCredential -ProviderName ([string]$providerName) -ProviderDefinition $provider -CredentialId ([string]$credentialId) -Credential $credential
        }

        $normalized.providers[$providerName] = Convert-BootstrapSecretsProviderDefinition -ProviderName ([string]$providerName) -ProviderData $provider
    }

    return $normalized
}

function Set-BootstrapSecretsActiveCredential {
    param(
        [Parameter(Mandatory = $true)]$SecretsData,
        [Parameter(Mandatory = $true)][string]$ProviderName,
        [Parameter(Mandatory = $true)][string]$CredentialId
    )

    $normalized = Normalize-BootstrapSecretsData -Secrets $SecretsData
    if (-not $normalized.providers.Contains($ProviderName)) {
        throw "Provider desconhecido: $ProviderName"
    }

    $provider = ConvertTo-BootstrapHashtable -InputObject $normalized.providers[$ProviderName]
    if (-not ($provider.ContainsKey('credentials') -and ($provider['credentials'] -is [hashtable]) -and $provider['credentials'].Contains($CredentialId))) {
        throw "Credencial desconhecida para ${ProviderName}: $CredentialId"
    }

    $credential = ConvertTo-BootstrapHashtable -InputObject $provider['credentials'][$CredentialId]
    $provider['credentials'][$CredentialId]['validation'] = Test-BootstrapSecretsProviderCredential -ProviderName $ProviderName -ProviderDefinition $provider -CredentialId $CredentialId -Credential $credential
    if ([string]$provider['credentials'][$CredentialId]['validation']['state'] -eq 'passed') {
        $provider['activeCredential'] = $CredentialId
    }

    $normalized.providers[$ProviderName] = Convert-BootstrapSecretsProviderDefinition -ProviderName $ProviderName -ProviderData $provider
    return $normalized
}

function Move-BootstrapSecretsToNextCredential {
    param(
        [Parameter(Mandatory = $true)]$SecretsData,
        [Parameter(Mandatory = $true)][string]$ProviderName
    )

    $normalized = Normalize-BootstrapSecretsData -Secrets $SecretsData
    if (-not $normalized.providers.Contains($ProviderName)) {
        throw "Provider desconhecido: $ProviderName"
    }

    $provider = ConvertTo-BootstrapHashtable -InputObject $normalized.providers[$ProviderName]
    if (-not ($provider.ContainsKey('credentials') -and ($provider['credentials'] -is [hashtable]))) {
        return $normalized
    }

    $rotationOrder = @($provider['rotationOrder'])
    $activeCredential = [string]$provider['activeCredential']
    $candidateIds = New-Object System.Collections.Generic.List[string]
    if (-not [string]::IsNullOrWhiteSpace($activeCredential) -and $provider['credentials'].Contains($activeCredential)) {
        $candidateIds.Add($activeCredential)
    }
    foreach ($credentialId in $rotationOrder) {
        $value = [string]$credentialId
        if ([string]::IsNullOrWhiteSpace($value)) { continue }
        if (-not $candidateIds.Contains($value)) {
            $candidateIds.Add($value)
        }
    }
    foreach ($credentialId in $provider['credentials'].Keys) {
        if (-not $candidateIds.Contains([string]$credentialId)) {
            $candidateIds.Add([string]$credentialId)
        }
    }

    foreach ($credentialId in $candidateIds) {
        $credential = ConvertTo-BootstrapHashtable -InputObject $provider['credentials'][$credentialId]
        if (-not ($credential -is [hashtable])) { continue }

        $provider['credentials'][$credentialId]['validation'] = Test-BootstrapSecretsProviderCredential -ProviderName $ProviderName -ProviderDefinition $provider -CredentialId ([string]$credentialId) -Credential $credential
        $state = [string]$provider['credentials'][$credentialId]['validation']['state']
        if (($credentialId -eq $activeCredential) -and ($state -eq 'passed')) {
            $normalized.providers[$ProviderName] = Convert-BootstrapSecretsProviderDefinition -ProviderName $ProviderName -ProviderData $provider
            return $normalized
        }
        if (($credentialId -ne $activeCredential) -and ($state -eq 'passed')) {
            $provider['activeCredential'] = [string]$credentialId
            $normalized.providers[$ProviderName] = Convert-BootstrapSecretsProviderDefinition -ProviderName $ProviderName -ProviderData $provider
            return $normalized
        }
    }

    $normalized.providers[$ProviderName] = Convert-BootstrapSecretsProviderDefinition -ProviderName $ProviderName -ProviderData $provider
    return $normalized
}

# region Secrets rotation worker (ADR 0001)
#
# Estados: queued -> validating -> activating -> broadcasting -> settled | failed
# Funcoes puras (operam sobre o objeto $SecretsData em memoria, sem I/O).
# Persistencia + Register-BootstrapChange acontecem em Invoke-BootstrapSecretRotation.

function Get-BootstrapSecretsValidationFailureCategory {
    param([AllowNull()][string]$Message)
    if ([string]::IsNullOrWhiteSpace($Message)) { return 'unknown' }
    $normalized = $Message.ToLowerInvariant()
    if ($normalized -match '\b401\b' -or $normalized.Contains('unauthorized')) { return 'auth' }
    if ($normalized -match '\b403\b' -or $normalized.Contains('forbidden')) { return 'auth' }
    if ($normalized -match '\b429\b' -or $normalized.Contains('rate limit') -or $normalized.Contains('quota')) { return 'rate-limit' }
    if ($normalized -match '\b5\d\d\b' -or $normalized.Contains('server error') -or $normalized.Contains('bad gateway')) { return 'server' }
    if ($normalized.Contains('timeout') -or $normalized.Contains('timed out') -or $normalized.Contains('operation has timed out')) { return 'timeout' }
    if ($normalized.Contains('the underlying connection') -or $normalized.Contains('no such host') -or $normalized.Contains('unable to connect') -or $normalized.Contains('actively refused')) { return 'network' }
    return 'unknown'
}

function Test-BootstrapSecretsRetryableFailure {
    param([Parameter(Mandatory = $true)][string]$Category)
    return @('server', 'timeout', 'network', 'rate-limit') -contains $Category
}

function New-BootstrapSecretRotationId {
    param([Parameter(Mandatory = $true)][string]$ProviderName)
    $stamp = (Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssZ')
    $suffix = [Guid]::NewGuid().ToString('N').Substring(0, 4)
    return ('rot-{0}-{1}-{2}' -f $ProviderName, $stamp, $suffix)
}

function New-BootstrapSecretRotationItem {
    param(
        [Parameter(Mandatory = $true)][string]$ProviderName,
        [string]$TargetCredentialId = '',
        [string]$Trigger = 'manual',
        [int]$MaxAttempts = 3,
        [int]$TimeoutSecondsPerValidator = 15,
        [int]$TimeoutSecondsTotal = 120,
        [string]$PreviousActiveCredentialId = ''
    )
    $now = (Get-Date).ToUniversalTime().ToString('o')
    return [ordered]@{
        id = New-BootstrapSecretRotationId -ProviderName $ProviderName
        provider = $ProviderName
        targetCredentialId = [string]$TargetCredentialId
        trigger = [string]$Trigger
        state = 'queued'
        attempts = 0
        maxAttempts = $MaxAttempts
        timeoutSecondsPerValidator = $TimeoutSecondsPerValidator
        timeoutSecondsTotal = $TimeoutSecondsTotal
        createdAt = $now
        lastTransitionAt = $now
        previousActiveCredentialId = [string]$PreviousActiveCredentialId
        lastError = ''
        events = @(@{ at = $now; from = ''; to = 'queued'; message = '' })
    }
}

function Get-BootstrapSecretRotationQueue {
    param(
        [Parameter(Mandatory = $true)]$SecretsData,
        [Parameter(Mandatory = $true)][string]$ProviderName
    )
    $normalized = Normalize-BootstrapSecretsData -Secrets $SecretsData
    $providerKey = $ProviderName.ToLowerInvariant()
    if (-not $normalized.providers.Contains($providerKey)) {
        return @()
    }
    $provider = ConvertTo-BootstrapHashtable -InputObject $normalized.providers[$providerKey]
    if (-not ($provider -is [hashtable])) { return @() }
    if (-not $provider.ContainsKey('rotationQueue') -or -not ($provider['rotationQueue'] -is [System.Collections.IEnumerable])) {
        return @()
    }
    $items = New-Object System.Collections.ArrayList
    foreach ($entry in @($provider['rotationQueue'])) {
        $hashEntry = ConvertTo-BootstrapHashtable -InputObject $entry
        if ($hashEntry -is [hashtable]) { $null = $items.Add($hashEntry) }
    }
    return ,@($items.ToArray())
}

function Add-BootstrapSecretRotationItem {
    param(
        [Parameter(Mandatory = $true)]$SecretsData,
        [Parameter(Mandatory = $true)][string]$ProviderName,
        [string]$TargetCredentialId = '',
        [string]$Trigger = 'manual',
        [int]$MaxAttempts = 3,
        [int]$TimeoutSecondsPerValidator = 15,
        [int]$TimeoutSecondsTotal = 120
    )
    $normalized = Normalize-BootstrapSecretsData -Secrets $SecretsData
    $providerKey = $ProviderName.ToLowerInvariant()
    if (-not $normalized.providers.Contains($providerKey)) {
        throw "Provider desconhecido: $ProviderName"
    }
    $provider = ConvertTo-BootstrapHashtable -InputObject $normalized.providers[$providerKey]
    if (-not $provider.ContainsKey('rotationQueue') -or -not ($provider['rotationQueue'] -is [System.Collections.IEnumerable])) {
        $provider['rotationQueue'] = @()
    }
    if (-not [string]::IsNullOrWhiteSpace($TargetCredentialId)) {
        $hasCred = $false
        if ($provider.ContainsKey('credentials') -and $provider['credentials'] -is [System.Collections.IDictionary]) {
            $hasCred = $provider['credentials'].Contains($TargetCredentialId)
        }
        if (-not $hasCred) {
            throw "Credencial desconhecida para ${providerKey}: $TargetCredentialId"
        }
    }
    $previousActive = [string]$provider['activeCredential']
    $item = New-BootstrapSecretRotationItem -ProviderName $providerKey -TargetCredentialId $TargetCredentialId -Trigger $Trigger -MaxAttempts $MaxAttempts -TimeoutSecondsPerValidator $TimeoutSecondsPerValidator -TimeoutSecondsTotal $TimeoutSecondsTotal -PreviousActiveCredentialId $previousActive
    $provider['rotationQueue'] = @($provider['rotationQueue']) + @($item)
    $normalized.providers[$providerKey] = Convert-BootstrapSecretsProviderDefinition -ProviderName $providerKey -ProviderData $provider
    return @{
        Data = $normalized
        Item = $item
    }
}

function Update-BootstrapSecretRotationItemState {
    param(
        [Parameter(Mandatory = $true)][hashtable]$Item,
        [Parameter(Mandatory = $true)][string]$To,
        [string]$Message = ''
    )
    $from = [string]$Item['state']
    $now = (Get-Date).ToUniversalTime().ToString('o')
    $Item['state'] = $To
    $Item['lastTransitionAt'] = $now
    if (-not [string]::IsNullOrWhiteSpace($Message)) {
        $Item['lastError'] = $Message
    }
    $events = @($Item['events'])
    $events += @(@{ at = $now; from = $from; to = $To; message = $Message; attempt = [int]$Item['attempts'] })
    $Item['events'] = $events
    return $Item
}

function Get-BootstrapSecretRotationNextCandidate {
    param(
        [Parameter(Mandatory = $true)][hashtable]$Provider,
        [Parameter(Mandatory = $true)][hashtable]$Item
    )
    $target = [string]$Item['targetCredentialId']
    if (-not [string]::IsNullOrWhiteSpace($target)) {
        if ($Provider['credentials'].Contains($target)) { return $target }
        return $null
    }
    $activeCredential = [string]$Provider['activeCredential']
    $candidates = New-Object System.Collections.Generic.List[string]
    foreach ($credentialId in @($Provider['rotationOrder'])) {
        $value = [string]$credentialId
        if ([string]::IsNullOrWhiteSpace($value)) { continue }
        if ($value -eq $activeCredential) { continue }
        if (-not $Provider['credentials'].Contains($value)) { continue }
        if (-not $candidates.Contains($value)) { $candidates.Add($value) }
    }
    foreach ($credentialId in $Provider['credentials'].Keys) {
        $value = [string]$credentialId
        if ($value -eq $activeCredential) { continue }
        if (-not $candidates.Contains($value)) { $candidates.Add($value) }
    }
    if ($candidates.Count -gt 0) { return $candidates[0] }
    return $null
}

function Invoke-BootstrapSecretRotationItemTransitions {
    param(
        [Parameter(Mandatory = $true)]$SecretsData,
        [Parameter(Mandatory = $true)][hashtable]$Item,
        [DateTime]$Deadline = ([DateTime]::UtcNow.AddSeconds(120)),
        [scriptblock]$ValidatorOverride = $null,
        [scriptblock]$BroadcastOverride = $null,
        [scriptblock]$EventSink = $null,
        [switch]$DryRun
    )
    $normalized = Normalize-BootstrapSecretsData -Secrets $SecretsData
    $providerKey = [string]$Item['provider']
    if (-not $normalized.providers.Contains($providerKey)) {
        $Item = Update-BootstrapSecretRotationItemState -Item $Item -To 'failed' -Message "provider desconhecido: $providerKey"
        return @{ Data = $normalized; Item = $Item; Completed = $true }
    }
    $provider = ConvertTo-BootstrapHashtable -InputObject $normalized.providers[$providerKey]
    $emit = {
        param($name, $payload)
        if ($EventSink) {
            try { & $EventSink $name $payload } catch { }
        }
    }
    & $emit 'transition-start' @{ rotationId = $Item['id']; from = ''; to = [string]$Item['state']; provider = $providerKey }

    # queued -> validating
    if ([string]$Item['state'] -eq 'queued') {
        $Item = Update-BootstrapSecretRotationItemState -Item $Item -To 'validating'
        & $emit 'state-change' @{ rotationId = $Item['id']; state = 'validating' }
    }

    # validating loop
    while ([string]$Item['state'] -eq 'validating') {
        if ([DateTime]::UtcNow -gt $Deadline) {
            $Item = Update-BootstrapSecretRotationItemState -Item $Item -To 'failed' -Message 'timeout total da rotacao'
            & $emit 'timeout' @{ rotationId = $Item['id'] }
            break
        }
        $candidate = Get-BootstrapSecretRotationNextCandidate -Provider $provider -Item $Item
        if ([string]::IsNullOrWhiteSpace($candidate)) {
            $Item = Update-BootstrapSecretRotationItemState -Item $Item -To 'failed' -Message 'sem credenciais candidatas'
            break
        }
        $Item['attempts'] = [int]$Item['attempts'] + 1
        $credential = ConvertTo-BootstrapHashtable -InputObject $provider['credentials'][$candidate]
        $validation = $null
        if ($ValidatorOverride) {
            $validation = & $ValidatorOverride $providerKey $candidate $credential
        } else {
            $validation = Test-BootstrapSecretsProviderCredential -ProviderName $providerKey -ProviderDefinition $provider -CredentialId $candidate -Credential $credential -TimeoutSeconds ([int]$Item['timeoutSecondsPerValidator'])
        }
        $provider['credentials'][$candidate]['validation'] = $validation
        $state = [string]$validation['state']
        & $emit 'validation-result' @{ rotationId = $Item['id']; credentialId = $candidate; state = $state }
        if ($state -eq 'passed') {
            $Item['targetCredentialId'] = $candidate
            $Item = Update-BootstrapSecretRotationItemState -Item $Item -To 'activating'
            break
        }
        $category = Get-BootstrapSecretsValidationFailureCategory -Message ([string]$validation['message'])
        $retryable = Test-BootstrapSecretsRetryableFailure -Category $category
        if ((-not $retryable) -or ([int]$Item['attempts'] -ge [int]$Item['maxAttempts'])) {
            # Quando o usuario pediu uma credencial especifica, falha definitiva.
            if (-not [string]::IsNullOrWhiteSpace([string]$Item['targetCredentialId']) -and ([string]$Item['targetCredentialId'] -eq $candidate)) {
                $Item = Update-BootstrapSecretRotationItemState -Item $Item -To 'failed' -Message ("validacao falhou: $category")
                break
            }
            # Tenta proxima candidata zerando attempts? Nao — mantemos attempts globais por item para limitar custo.
            if ([int]$Item['attempts'] -ge [int]$Item['maxAttempts']) {
                $Item = Update-BootstrapSecretRotationItemState -Item $Item -To 'failed' -Message ("tentativas esgotadas (categoria=$category)")
                break
            }
            # Se erro nao retryavel mas ha outras candidatas, continua looping (proxima iteracao escolhe outra).
            continue
        }
        # Backoff antes da proxima tentativa.
        $delay = [Math]::Min(60, [Math]::Pow(2, [int]$Item['attempts']))
        $jitter = (Get-Random -Minimum 0 -Maximum 1500) / 1000.0
        $sleepMs = [int](([double]$delay + [double]$jitter) * 1000)
        if (-not $DryRun -and $sleepMs -gt 0) {
            $remainingMs = [int](($Deadline - [DateTime]::UtcNow).TotalMilliseconds)
            if ($remainingMs -le 0) {
                $Item = Update-BootstrapSecretRotationItemState -Item $Item -To 'failed' -Message 'timeout total da rotacao'
                break
            }
            Start-Sleep -Milliseconds ([Math]::Min($sleepMs, $remainingMs))
        }
    }

    # activating
    if ([string]$Item['state'] -eq 'activating') {
        $candidate = [string]$Item['targetCredentialId']
        if (-not $provider['credentials'].Contains($candidate)) {
            $Item = Update-BootstrapSecretRotationItemState -Item $Item -To 'failed' -Message 'credencial alvo desapareceu'
        } else {
            $provider['activeCredential'] = $candidate
            $Item = Update-BootstrapSecretRotationItemState -Item $Item -To 'broadcasting'
            & $emit 'state-change' @{ rotationId = $Item['id']; state = 'broadcasting' }
        }
    }

    # broadcasting
    if ([string]$Item['state'] -eq 'broadcasting') {
        $normalized.providers[$providerKey] = Convert-BootstrapSecretsProviderDefinition -ProviderName $providerKey -ProviderData $provider
        $broadcastOk = $false
        $broadcastMessage = ''
        try {
            if ($BroadcastOverride) {
                $broadcastOk = [bool](& $BroadcastOverride $normalized $providerKey $Item)
            } else {
                # Em DryRun nao chamamos Ensure-BootstrapSecrets; assumimos sucesso para deixar testes deterministicos.
                if ($DryRun) {
                    $broadcastOk = $true
                } else {
                    # Sem state real do bootstrap aqui — o caller (Invoke-BootstrapSecretRotation) cuida do broadcast real.
                    $broadcastOk = $true
                }
            }
        } catch {
            $broadcastOk = $false
            $broadcastMessage = [string]$_.Exception.Message
        }
        if ($broadcastOk) {
            $Item = Update-BootstrapSecretRotationItemState -Item $Item -To 'settled'
        } else {
            # Reverte activeCredential para previous se broadcast total falhou.
            if (-not [string]::IsNullOrWhiteSpace([string]$Item['previousActiveCredentialId']) -and $provider['credentials'].Contains([string]$Item['previousActiveCredentialId'])) {
                $provider['activeCredential'] = [string]$Item['previousActiveCredentialId']
                $normalized.providers[$providerKey] = Convert-BootstrapSecretsProviderDefinition -ProviderName $providerKey -ProviderData $provider
            }
            $Item = Update-BootstrapSecretRotationItemState -Item $Item -To 'failed' -Message ("broadcast falhou: $broadcastMessage")
        }
    }

    # Persistir fila atualizada no provider.
    $queue = @()
    if ($provider.ContainsKey('rotationQueue') -and ($provider['rotationQueue'] -is [System.Collections.IEnumerable])) {
        foreach ($entry in @($provider['rotationQueue'])) {
            $hashEntry = ConvertTo-BootstrapHashtable -InputObject $entry
            if (-not ($hashEntry -is [hashtable])) { continue }
            if ([string]$hashEntry['id'] -eq [string]$Item['id']) {
                $queue += ,$Item
            } else {
                $queue += ,$hashEntry
            }
        }
    }
    if (@($queue | Where-Object { [string]$_['id'] -eq [string]$Item['id'] }).Count -eq 0) {
        $queue += ,$Item
    }
    $provider['rotationQueue'] = $queue
    $normalized.providers[$providerKey] = Convert-BootstrapSecretsProviderDefinition -ProviderName $providerKey -ProviderData $provider
    return @{
        Data = $normalized
        Item = $Item
        Completed = ([string]$Item['state'] -in @('settled', 'failed'))
    }
}

function Lock-BootstrapSecretsFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [int]$TimeoutSeconds = 5
    )
    $lockPath = "$Path.lock"
    $directory = Split-Path -Path $lockPath -Parent
    if (-not [string]::IsNullOrWhiteSpace($directory) -and -not (Test-Path -LiteralPath $directory)) {
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
    }
    $deadline = [DateTime]::UtcNow.AddSeconds($TimeoutSeconds)
    while ([DateTime]::UtcNow -lt $deadline) {
        try {
            $stream = [System.IO.File]::Open($lockPath, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
            return $stream
        } catch {
            Start-Sleep -Milliseconds 200
        }
    }
    throw "RotationConcurrencyError: nao foi possivel adquirir lock em ${TimeoutSeconds}s ($lockPath)"
}

function Unlock-BootstrapSecretsFile {
    param([System.IO.FileStream]$Stream, [string]$Path)
    if ($Stream) {
        try { $Stream.Dispose() } catch { }
    }
    if (-not [string]::IsNullOrWhiteSpace($Path)) {
        $lockPath = "$Path.lock"
        try { if (Test-Path -LiteralPath $lockPath) { Remove-Item -LiteralPath $lockPath -Force -ErrorAction SilentlyContinue } } catch { }
    }
}

function Write-BootstrapRotationEvent {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [Parameter(Mandatory = $true)][hashtable]$Payload,
        [string]$EventsPath = ''
    )
    if ([string]::IsNullOrWhiteSpace($EventsPath)) {
        $root = Get-BootstrapDataRoot
        if ([string]::IsNullOrWhiteSpace($root)) { return }
        $EventsPath = Join-Path $root 'rotation-events.jsonl'
    }
    $directory = Split-Path -Path $EventsPath -Parent
    if (-not [string]::IsNullOrWhiteSpace($directory) -and -not (Test-Path -LiteralPath $directory)) {
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
    }
    $entry = [ordered]@{
        at = (Get-Date).ToUniversalTime().ToString('o')
        event = $Name
    }
    foreach ($key in $Payload.Keys) { $entry[[string]$key] = $Payload[$key] }
    $line = ($entry | ConvertTo-Json -Depth 6 -Compress)
    try {
        Add-Content -LiteralPath $EventsPath -Value $line -Encoding UTF8
    } catch { }
    # Rotacao simples: se passou de 1000 linhas, mantem ultimas 750.
    try {
        $existing = @()
        if (Test-Path -LiteralPath $EventsPath) { $existing = @(Get-Content -LiteralPath $EventsPath -Encoding UTF8) }
        if ($existing.Count -gt 1000) {
            $keep = $existing[($existing.Count - 750)..($existing.Count - 1)]
            $tmpPath = "$EventsPath.tmp"
            Set-Content -LiteralPath $tmpPath -Value $keep -Encoding UTF8
            Move-Item -LiteralPath $tmpPath -Destination $EventsPath -Force
        }
    } catch { }
}

function Invoke-BootstrapSecretRotation {
    param(
        [string]$ProviderName = '',
        [int]$MaxItems = 10,
        [int]$TimeoutSeconds = 120,
        [hashtable]$State = $null,
        [switch]$DryRun
    )
    $bundle = Get-BootstrapSecretsData
    $manifestPath = $bundle.Path
    $data = $bundle.Data
    $lock = $null
    $processed = New-Object System.Collections.ArrayList
    $eventsPath = ''
    try {
        $root = Get-BootstrapDataRoot
        if (-not [string]::IsNullOrWhiteSpace($root)) { $eventsPath = Join-Path $root 'rotation-events.jsonl' }
    } catch { $eventsPath = '' }
    $sink = {
        param($name, $payload)
        if (-not [string]::IsNullOrWhiteSpace($eventsPath)) {
            try { Write-BootstrapRotationEvent -Name $name -Payload $payload -EventsPath $eventsPath } catch { }
        }
    }
    try {
        $lock = Lock-BootstrapSecretsFile -Path $manifestPath -TimeoutSeconds 5
        $normalized = Normalize-BootstrapSecretsData -Secrets $data
        $providerFilter = ''
        if (-not [string]::IsNullOrWhiteSpace($ProviderName)) { $providerFilter = $ProviderName.ToLowerInvariant() }
        $globalDeadline = [DateTime]::UtcNow.AddSeconds($TimeoutSeconds)
        $itemBudget = $MaxItems
        foreach ($key in @($normalized.providers.Keys)) {
            if ($itemBudget -le 0) { break }
            if ([DateTime]::UtcNow -gt $globalDeadline) { break }
            if (-not [string]::IsNullOrWhiteSpace($providerFilter) -and ($key -ne $providerFilter)) { continue }
            $providerData = ConvertTo-BootstrapHashtable -InputObject $normalized.providers[$key]
            if (-not $providerData.ContainsKey('rotationQueue')) { continue }
            $queue = @($providerData['rotationQueue'])
            foreach ($entry in $queue) {
                if ($itemBudget -le 0) { break }
                if ([DateTime]::UtcNow -gt $globalDeadline) { break }
                $item = ConvertTo-BootstrapHashtable -InputObject $entry
                if (-not ($item -is [hashtable])) { continue }
                $itemState = [string]$item['state']
                if ($itemState -in @('settled', 'failed')) { continue }
                $itemDeadline = [DateTime]::UtcNow.AddSeconds([int]$item['timeoutSecondsTotal'])
                if ($itemDeadline -gt $globalDeadline) { $itemDeadline = $globalDeadline }
                $result = Invoke-BootstrapSecretRotationItemTransitions -SecretsData $normalized -Item $item -Deadline $itemDeadline -EventSink $sink -DryRun:$DryRun
                $normalized = $result.Data
                $item = $result.Item
                $itemBudget = $itemBudget - 1
                $finalState = [string]$item['state']
                if ($finalState -eq 'broadcasting') {
                    # transition stopped on broadcasting (provavelmente por DryRun + sem override). Marca settled em DryRun.
                    if ($DryRun) { $item = Update-BootstrapSecretRotationItemState -Item $item -To 'settled' -Message 'dry-run' }
                }
                if (-not $DryRun -and $finalState -eq 'broadcasting') {
                    try {
                        Write-BootstrapJsonFile -Path $manifestPath -Value $normalized
                        if ($State -ne $null) {
                            $stateForBroadcast = $State
                        } else {
                            $stateForBroadcast = New-BootstrapState -Selection @{} -ResolvedWorkspaceRoot (Get-Location).Path -ResolvedCloneBaseDir (Get-Location).Path -RequestedSteamDeckVersion 'Auto' -ResolvedSteamDeckVersion '' -HostHealthMode 'off' -UsesSteamDeckFlow:$false -IsDryRun:$false
                        }
                        Ensure-BootstrapSecrets -State $stateForBroadcast
                        $normalized = Read-BootstrapJsonFile -Path $manifestPath
                        $providerData2 = ConvertTo-BootstrapHashtable -InputObject $normalized.providers[$key]
                        $queue2 = @()
                        foreach ($q in @($providerData2['rotationQueue'])) {
                            $qHash = ConvertTo-BootstrapHashtable -InputObject $q
                            if (-not ($qHash -is [hashtable])) { continue }
                            if ([string]$qHash['id'] -eq [string]$item['id']) {
                                $item = Update-BootstrapSecretRotationItemState -Item $item -To 'settled'
                                $queue2 += ,$item
                            } else {
                                $queue2 += ,$qHash
                            }
                        }
                        $providerData2['rotationQueue'] = $queue2
                        $normalized.providers[$key] = Convert-BootstrapSecretsProviderDefinition -ProviderName $key -ProviderData $providerData2
                    } catch {
                        $broadcastError = [string]$_.Exception.Message
                        if (-not [string]::IsNullOrWhiteSpace([string]$item['previousActiveCredentialId'])) {
                            $providerData['activeCredential'] = [string]$item['previousActiveCredentialId']
                            $normalized.providers[$key] = Convert-BootstrapSecretsProviderDefinition -ProviderName $key -ProviderData $providerData
                        }
                        $item = Update-BootstrapSecretRotationItemState -Item $item -To 'failed' -Message ("broadcast falhou: $broadcastError")
                    }
                }
                if ($State -ne $null -and [string]$item['state'] -eq 'settled') {
                    try {
                        Register-BootstrapChange -State $State -Type 'SecretsRotation' -Target ("$key/$([string]$item['targetCredentialId'])") -OldValue ([string]$item['previousActiveCredentialId']) -NewValue ([string]$item['targetCredentialId']) -Name ([string]$item['id']) -Component 'bootstrap-secrets-rotation'
                    } catch { }
                }
                $null = $processed.Add($item)
                if (-not $DryRun) {
                    Write-BootstrapJsonFile -Path $manifestPath -Value $normalized
                }
            }
        }
        if ($DryRun) {
            # Em dry-run nao persiste no disco.
        } else {
            Write-BootstrapJsonFile -Path $manifestPath -Value $normalized
        }
        return @{
            Path = $manifestPath
            Processed = @($processed)
            Data = $normalized
        }
    } finally {
        Unlock-BootstrapSecretsFile -Stream $lock -Path $manifestPath
    }
}
# endregion

function Test-BootstrapSecretsTargetHasApplicableValues {
    param($Target)

    $normalized = ConvertTo-BootstrapHashtable -InputObject $Target
    if (-not ($normalized -is [hashtable])) {
        return $false
    }

    foreach ($key in $normalized.Keys) {
        if ($key -eq 'env' -and ($normalized[$key] -is [hashtable])) {
            foreach ($envKey in $normalized[$key].Keys) {
                if (-not [string]::IsNullOrWhiteSpace([string]$normalized[$key][$envKey])) {
                    return $true
                }
            }
            continue
        }

        if ($key -eq 'mcpServers' -and ($normalized[$key] -is [hashtable])) {
            foreach ($serverName in $normalized[$key].Keys) {
                $server = ConvertTo-BootstrapHashtable -InputObject $normalized[$key][$serverName]
                if (-not ($server -is [hashtable])) { continue }
                if ($server.ContainsKey('enabled') -and (-not [bool]$server['enabled'])) { continue }
                if ($server.ContainsKey('disabled') -and [bool]$server['disabled']) { continue }
                return $true
            }
            continue
        }

        if ($normalized[$key] -is [string]) {
            if (-not [string]::IsNullOrWhiteSpace([string]$normalized[$key])) {
                return $true
            }
        }
    }

    return $false
}

function Ensure-BootstrapUserEnvSecrets {
    param([hashtable]$ResolvedTargets)

    if (-not ($ResolvedTargets -is [hashtable]) -or -not $ResolvedTargets.ContainsKey('userEnv') -or -not ($ResolvedTargets['userEnv'] -is [hashtable])) {
        return 0
    }

    $applied = 0
    foreach ($name in $ResolvedTargets['userEnv'].Keys) {
        $value = [string]$ResolvedTargets['userEnv'][$name]
        if ([string]::IsNullOrWhiteSpace($value)) { continue }
        Set-UserEnvVar -Name ([string]$name) -Value $value
        $applied += 1
    }
    return $applied
}

function ConvertFrom-BootstrapRemoteBridgeServerDefinition {
    param([Parameter(Mandatory = $true)][hashtable]$ServerDefinition)

    if (-not $ServerDefinition.ContainsKey('command')) {
        return $null
    }

    $command = [string]$ServerDefinition['command']
    if (-not [string]::Equals($command, 'npx', [System.StringComparison]::OrdinalIgnoreCase)) {
        return $null
    }

    $args = Get-BootstrapNonEmptyStringArray -Values @($ServerDefinition['args'])
    if ($args.Count -lt 2) {
        return $null
    }
    if ($args[0] -ne '-y' -or $args[1] -ne 'mcp-remote@latest') {
        return $null
    }

    $url = ''
    $headers = [ordered]@{}
    $index = 2
    while ($index -lt $args.Count) {
        $token = [string]$args[$index]
        switch ($token) {
            '--http' {
                $index += 1
                if ($index -lt $args.Count) {
                    $url = [string]$args[$index]
                }
            }
            '--allow-http' {
            }
            '--header' {
                $index += 1
                if ($index -lt $args.Count) {
                    $headerLine = [string]$args[$index]
                    $parts = $headerLine -split ':\s*', 2
                    if ($parts.Count -eq 2) {
                        $headers[$parts[0]] = $parts[1]
                    }
                }
            }
            default {
                if ([string]::IsNullOrWhiteSpace($url) -and ($token -match '^[a-z]+://')) {
                    $url = $token
                }
            }
        }
        $index += 1
    }

    if ([string]::IsNullOrWhiteSpace($url)) {
        return $null
    }

    $remote = [ordered]@{
        url = $url
    }
    if ($headers.Count -gt 0) {
        $remote['headers'] = $headers
    }

    return $remote
}

function Get-BootstrapWindowsNpxLaunch {
    # Em Windows, um comando MCP "npx" puro nao e resolvido por CreateProcess (npx e npx.cmd),
    # causando "Could not attach to MCP server". Encapsula em `cmd /c npx ...` (forma padrao e
    # robusta no Windows). Mantemos a forma canonica 'npx' internamente; este wrap so e aplicado
    # na serializacao final de cada cliente. Retorna $null quando nao se aplica.
    [CmdletBinding()]
    param(
        [string]$Command,
        [Alias('Args')][string[]]$CommandArgs = @()
    )

    if (-not (Test-BootstrapHostIsWindows)) { return $null }
    if ([string]::IsNullOrWhiteSpace($Command)) { return $null }
    if ([string]::Equals($Command, 'cmd', [System.StringComparison]::OrdinalIgnoreCase)) { return $null }
    $base = [System.IO.Path]::GetFileNameWithoutExtension($Command)
    if (-not [string]::Equals($base, 'npx', [System.StringComparison]::OrdinalIgnoreCase)) { return $null }

    $newArgs = New-Object System.Collections.Generic.List[string]
    $newArgs.Add('/c') | Out-Null
    $newArgs.Add('npx') | Out-Null
    foreach ($a in @($CommandArgs)) { $newArgs.Add([string]$a) | Out-Null }
    return [ordered]@{ command = 'cmd'; args = @($newArgs.ToArray()) }
}

function Get-BootstrapManagedMcpRepairEntry {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [ValidateSet('standard', 'vscode')][string]$Format = 'standard'
    )

    $managedServers = Get-BootstrapManagedMcpServers -ManagedProviders @{}
    if (-not ($managedServers -is [System.Collections.IDictionary]) -or -not $managedServers.Contains($Name)) {
        return $null
    }

    $serverDefinition = ConvertTo-BootstrapHashtable -InputObject $managedServers[$Name]
    if (-not ($serverDefinition -is [System.Collections.IDictionary])) { return $null }
    return (ConvertTo-BootstrapMcpServerEntry -ServerDefinition $serverDefinition -Format $Format)
}

function Get-BootstrapMcpRepairTargets {
    # Clientes cujo config MCP usa o formato { mcpServers|servers: { nome: { command, args } } }
    # e e passivel de reparo automatico de comandos 'npx' puros (nao-lancaveis no Windows).
    $userHome = Get-BootstrapUserHomePath
    $map = [ordered]@{
        'claude-code'    = $(if ($userHome) { Join-Path $userHome '.claude\settings.json' } else { $null })
        'claude-desktop' = (Get-BootstrapClaudeDesktopConfigPath)
        'cursor'         = (Get-BootstrapCursorMcpConfigPath)
        'windsurf'       = (Get-BootstrapWindsurfMcpConfigPath)
        'trae'           = (Get-BootstrapTraeMcpConfigPath)
        'roo'            = (Get-BootstrapRooMcpConfigPath)
        'cline'          = (Get-BootstrapClineMcpConfigPath)
        'vscode'         = (Get-BootstrapVsCodeMcpConfigPath)
        'hermes'         = (Get-BootstrapHermesConfigPath)
    }
    $targets = New-Object System.Collections.Generic.List[object]
    foreach ($key in $map.Keys) {
        $p = [string]$map[$key]
        if (-not [string]::IsNullOrWhiteSpace($p)) { $targets.Add([ordered]@{ id = [string]$key; path = $p }) | Out-Null }
    }
    return @($targets.ToArray())
}

function Repair-BootstrapMcpServerMap {
    # Reescreve entradas com command 'npx' puro para 'cmd /c npx ...' (Windows-safe), idempotente
    # e cura configs gerados por versoes antigas que truncaram para `cmd /c npx` sem pacote.
    # Muta o hashtable recebido; retorna o numero de entradas alteradas.
    param(
        [Parameter(Mandatory = $true)][hashtable]$ServerMap,
        [ValidateSet('standard', 'vscode')][string]$Format = 'standard'
    )

    $changed = 0
    foreach ($name in @($ServerMap.Keys)) {
        $entry = ConvertTo-BootstrapHashtable -InputObject $ServerMap[$name]
        if (-not ($entry -is [hashtable]) -or -not $entry.ContainsKey('command')) { continue }
        $serverArgs = @()
        if ($entry.ContainsKey('args')) { $serverArgs = @($entry['args']) }
        $command = [string]$entry['command']
        $base = [System.IO.Path]::GetFileNameWithoutExtension($command)
        $replacement = $null

        if ([string]::Equals($base, 'npx', [System.StringComparison]::OrdinalIgnoreCase)) {
            $replacement = Get-BootstrapWindowsNpxLaunch -Command $command -CommandArgs $serverArgs
        } elseif ([string]::Equals($base, 'cmd', [System.StringComparison]::OrdinalIgnoreCase)) {
            $arg0 = if (@($serverArgs).Count -gt 0) { [string]$serverArgs[0] } else { '' }
            $arg1 = if (@($serverArgs).Count -gt 1) { [string]$serverArgs[1] } else { '' }
            $hasLauncherOnly = (
                (@($serverArgs).Count -eq 0) -or
                (@($serverArgs).Count -eq 1 -and [string]::Equals($arg0, 'npx', [System.StringComparison]::OrdinalIgnoreCase)) -or
                (@($serverArgs).Count -eq 2 -and [string]::Equals($arg0, '/c', [System.StringComparison]::OrdinalIgnoreCase) -and [string]::Equals($arg1, 'npx', [System.StringComparison]::OrdinalIgnoreCase))
            )
            $missingCmdSwitch = (@($serverArgs).Count -gt 0 -and [string]::Equals($arg0, 'npx', [System.StringComparison]::OrdinalIgnoreCase))
            if ($hasLauncherOnly) {
                $replacement = Get-BootstrapManagedMcpRepairEntry -Name ([string]$name) -Format $Format
            } elseif ($missingCmdSwitch) {
                $fixedArgs = New-Object System.Collections.Generic.List[string]
                $fixedArgs.Add('/c') | Out-Null
                foreach ($a in @($serverArgs)) { $fixedArgs.Add([string]$a) | Out-Null }
                $replacement = [ordered]@{ command = 'cmd'; args = @($fixedArgs.ToArray()) }
            }
        }

        if (-not ($replacement -is [System.Collections.IDictionary])) { continue }
        $ServerMap[$name] = ConvertTo-BootstrapHashtable -InputObject $replacement
        $changed++
    }
    return $changed
}

function Invoke-BootstrapMcpConfigRepair {
    # Doctor/reparo: varre os configs MCP dos clientes e reescreve comandos 'npx' puros para
    # 'cmd /c npx ...' (causa de "Could not attach" no Windows). Backup .bak antes de gravar,
    # idempotente, DryRun reporta sem mutar. -ConfigPaths injeta alvos (testes).
    param(
        [hashtable]$State,
        [string[]]$ConfigPaths = @(),
        [switch]$DryRun
    )

    $targets = if (@($ConfigPaths).Count -gt 0) {
        @($ConfigPaths | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [ordered]@{ id = (Split-Path -Path ([string]$_) -Leaf); path = [string]$_ } })
    } else {
        Get-BootstrapMcpRepairTargets
    }

    $results = New-Object System.Collections.Generic.List[object]
    foreach ($t in $targets) {
        $path = [string]$t.path
        if (-not (Test-Path -LiteralPath $path)) {
            $results.Add([ordered]@{ id = [string]$t.id; path = $path; status = 'absent'; fixed = 0 }) | Out-Null
            continue
        }
        $data = $null
        try { $data = Read-BootstrapJsonFile -Path $path } catch {
            $results.Add([ordered]@{ id = [string]$t.id; path = $path; status = 'invalid-json'; fixed = 0 }) | Out-Null
            continue
        }
        if (-not ($data -is [hashtable])) {
            $results.Add([ordered]@{ id = [string]$t.id; path = $path; status = 'not-object'; fixed = 0 }) | Out-Null
            continue
        }

        $totalChanged = 0
        foreach ($containerKey in @('mcpServers', 'servers')) {
            if ($data.ContainsKey($containerKey) -and ($data[$containerKey] -is [hashtable])) {
                $serverMap = ConvertTo-BootstrapHashtable -InputObject $data[$containerKey]
                $format = if ([string]::Equals($containerKey, 'servers', [System.StringComparison]::OrdinalIgnoreCase)) { 'vscode' } else { 'standard' }
                $count = Repair-BootstrapMcpServerMap -ServerMap $serverMap -Format $format
                if ($count -gt 0) { $data[$containerKey] = $serverMap; $totalChanged += $count }
            }
        }

        if ($totalChanged -eq 0) {
            $results.Add([ordered]@{ id = [string]$t.id; path = $path; status = 'ok'; fixed = 0 }) | Out-Null
            continue
        }
        if ($DryRun) {
            $results.Add([ordered]@{ id = [string]$t.id; path = $path; status = 'would-fix'; fixed = $totalChanged }) | Out-Null
            continue
        }
        try { Copy-Item -LiteralPath $path -Destination ($path + '.bak') -Force -ErrorAction Stop } catch {
            Write-Log ("Reparo MCP: backup falhou para {0}: {1}" -f $path, $_.Exception.Message) 'WARN'
        }
        if (($State -is [hashtable]) -and $State.ContainsKey('Changes')) {
            try { Register-BootstrapFileChange -State $State -Target $path -Operation 'repair-mcp-npx' -Component ([string]$t.id) } catch { }
        }
        Write-BootstrapJsonFile -Path $path -Value $data
        $results.Add([ordered]@{ id = [string]$t.id; path = $path; status = 'fixed'; fixed = $totalChanged }) | Out-Null
    }

    $totalFixed = (@($results | Where-Object { $_.status -in @('fixed', 'would-fix') } | ForEach-Object { [int]$_.fixed } | Measure-Object -Sum).Sum)
    return [ordered]@{ dryRun = [bool]$DryRun; totalFixed = [int]$totalFixed; targets = @($results.ToArray()) }
}

function ConvertTo-BootstrapMcpServerEntry {
    param(
        [Parameter(Mandatory = $true)][hashtable]$ServerDefinition,
        [Parameter(Mandatory = $true)][ValidateSet('standard', 'opencode', 'vscode', 'zed', 'zcode')][string]$Format
    )

    if ($ServerDefinition.ContainsKey('enabled') -and (-not [bool]$ServerDefinition['enabled'])) {
        return $null
    }
    if ($ServerDefinition.ContainsKey('disabled') -and [bool]$ServerDefinition['disabled']) {
        return $null
    }

    $effectiveDefinition = $ServerDefinition
    $remoteBridgeDefinition = ConvertFrom-BootstrapRemoteBridgeServerDefinition -ServerDefinition $ServerDefinition
    if (($remoteBridgeDefinition -is [System.Collections.IDictionary]) -and $Format -in @('vscode', 'zed', 'zcode')) {
        $effectiveDefinition = ConvertTo-BootstrapHashtable -InputObject $remoteBridgeDefinition
    }

    # Robustez Windows: encapsular comandos stdio 'npx' em `cmd /c npx ...` na saida final.
    if (($effectiveDefinition -is [System.Collections.IDictionary]) -and $effectiveDefinition.ContainsKey('command') -and -not $effectiveDefinition.ContainsKey('url')) {
        $npxWrap = Get-BootstrapWindowsNpxLaunch -Command ([string]$effectiveDefinition['command']) -CommandArgs @($effectiveDefinition['args'])
        if ($npxWrap) {
            $effectiveDefinition = ConvertTo-BootstrapHashtable -InputObject $effectiveDefinition
            $effectiveDefinition['command'] = [string]$npxWrap['command']
            $effectiveDefinition['args'] = @($npxWrap['args'])
        }
    }

    if ($Format -eq 'opencode') {
        $serverOut = @{}
        $type = ''
        if ($effectiveDefinition.ContainsKey('type')) {
            $type = [string]$effectiveDefinition['type']
        }
        if ([string]::IsNullOrWhiteSpace($type)) {
            $type = if ($effectiveDefinition.ContainsKey('url')) { 'remote' } else { 'local' }
        }
        $serverOut['type'] = $type

        if ($effectiveDefinition.ContainsKey('enabled')) {
            $serverOut['enabled'] = [bool]$effectiveDefinition['enabled']
        }

        if ($type -eq 'local') {
            $commandParts = @()
            if ($effectiveDefinition.ContainsKey('command')) {
                if (($effectiveDefinition['command'] -is [System.Collections.IEnumerable]) -and -not ($effectiveDefinition['command'] -is [string])) {
                    $commandParts += @($effectiveDefinition['command'])
                } else {
                    $commandParts += @([string]$effectiveDefinition['command'])
                }
            }
            if ($effectiveDefinition.ContainsKey('args')) {
                $commandParts += @($effectiveDefinition['args'])
            }
            $commandParts = @($commandParts | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
            if ($commandParts.Count -gt 0) {
                $serverOut['command'] = @($commandParts)
            }
            if ($effectiveDefinition.ContainsKey('env') -and ($effectiveDefinition['env'] -is [hashtable])) {
                $environment = @{}
                Set-BootstrapNonEmptyStringValues -Target $environment -Values $effectiveDefinition['env']
                if ($environment.Count -gt 0) {
                    $serverOut['environment'] = $environment
                }
            }
        } else {
            if ($effectiveDefinition.ContainsKey('url')) {
                $url = [string]$effectiveDefinition['url']
                if (-not [string]::IsNullOrWhiteSpace($url)) {
                    $serverOut['url'] = $url
                }
            }
            if ($effectiveDefinition.ContainsKey('headers') -and ($effectiveDefinition['headers'] -is [hashtable])) {
                $headers = @{}
                Set-BootstrapNonEmptyStringValues -Target $headers -Values $effectiveDefinition['headers']
                if ($headers.Count -gt 0) {
                    $serverOut['headers'] = $headers
                }
            }
        }

        if ($effectiveDefinition.ContainsKey('timeout')) {
            $serverOut['timeout'] = $effectiveDefinition['timeout']
        }
        if ($serverOut.Count -le 1 -and $serverOut.ContainsKey('type')) {
            return $null
        }
        return $serverOut
    }

    if ($Format -eq 'vscode' -or $Format -eq 'zcode') {
        $serverOut = @{}
        $type = ''
        if ($effectiveDefinition.ContainsKey('type')) {
            $type = [string]$effectiveDefinition['type']
        }
        if ([string]::IsNullOrWhiteSpace($type)) {
            $type = if ($effectiveDefinition.ContainsKey('url')) { 'http' } else { 'stdio' }
        }
        $serverOut['type'] = $type

        foreach ($propertyName in @('command', 'url')) {
            if ($effectiveDefinition.ContainsKey($propertyName)) {
                $value = [string]$effectiveDefinition[$propertyName]
                if (-not [string]::IsNullOrWhiteSpace($value)) {
                    $serverOut[$propertyName] = $value
                }
            }
        }
        if ($effectiveDefinition.ContainsKey('args')) {
            $serverOut['args'] = @($effectiveDefinition['args'])
        }
        if ($effectiveDefinition.ContainsKey('headers') -and ($effectiveDefinition['headers'] -is [hashtable])) {
            $headers = @{}
            Set-BootstrapNonEmptyStringValues -Target $headers -Values $effectiveDefinition['headers']
            if ($headers.Count -gt 0) {
                $serverOut['headers'] = $headers
            }
        }
        if ($effectiveDefinition.ContainsKey('env') -and ($effectiveDefinition['env'] -is [hashtable])) {
            $envOut = @{}
            Set-BootstrapNonEmptyStringValues -Target $envOut -Values $effectiveDefinition['env']
            if ($envOut.Count -gt 0) {
                $serverOut['env'] = $envOut
            }
        }
        if ($serverOut.Count -le 1 -and $serverOut.ContainsKey('type')) {
            return $null
        }
        return $serverOut
    }

    if ($Format -eq 'zed') {
        $serverOut = @{}
        if ($effectiveDefinition.ContainsKey('url')) {
            $url = [string]$effectiveDefinition['url']
            if (-not [string]::IsNullOrWhiteSpace($url)) {
                $serverOut['url'] = $url
            }
        }
        if ($effectiveDefinition.ContainsKey('headers') -and ($effectiveDefinition['headers'] -is [hashtable])) {
            $headers = @{}
            Set-BootstrapNonEmptyStringValues -Target $headers -Values $effectiveDefinition['headers']
            if ($headers.Count -gt 0) {
                $serverOut['headers'] = $headers
            }
        }
        if ($serverOut.Count -eq 0) {
            if ($effectiveDefinition.ContainsKey('command')) {
                $commandPath = [string]$effectiveDefinition['command']
                if (-not [string]::IsNullOrWhiteSpace($commandPath)) {
                    $serverOut['command'] = $commandPath
                }
            }
            if ($effectiveDefinition.ContainsKey('args')) {
                $serverOut['args'] = @($effectiveDefinition['args'])
            }
            if ($effectiveDefinition.ContainsKey('env') -and ($effectiveDefinition['env'] -is [hashtable])) {
                $envOut = @{}
                Set-BootstrapNonEmptyStringValues -Target $envOut -Values $effectiveDefinition['env']
                if ($envOut.Count -gt 0) {
                    $serverOut['env'] = $envOut
                }
            }
        }
        if ($serverOut.Count -eq 0) {
            return $null
        }
        return $serverOut
    }

    # Formato 'standard': usa $effectiveDefinition (ja com o wrap Windows npx aplicado quando cabivel).
    $result = @{}
    foreach ($propertyName in @('command', 'url', 'transport', 'type', 'serverUrl')) {
        if ($effectiveDefinition.ContainsKey($propertyName)) {
            $value = [string]$effectiveDefinition[$propertyName]
            if (-not [string]::IsNullOrWhiteSpace($value)) {
                $result[$propertyName] = $value
            }
        }
    }
    if ($effectiveDefinition.ContainsKey('args')) {
        $result['args'] = @($effectiveDefinition['args'])
    }
    if ($effectiveDefinition.ContainsKey('headers') -and ($effectiveDefinition['headers'] -is [hashtable])) {
        $headers = @{}
        Set-BootstrapNonEmptyStringValues -Target $headers -Values $effectiveDefinition['headers']
        if ($headers.Count -gt 0) {
            $result['headers'] = $headers
        }
    }
    if ($effectiveDefinition.ContainsKey('env') -and ($effectiveDefinition['env'] -is [hashtable])) {
        $envOut = @{}
        Set-BootstrapNonEmptyStringValues -Target $envOut -Values $effectiveDefinition['env']
        if ($envOut.Count -gt 0) {
            $result['env'] = $envOut
        }
    }
    if ($effectiveDefinition.ContainsKey('alwaysAllow')) {
        $result['alwaysAllow'] = @($effectiveDefinition['alwaysAllow'])
    }
    if ($effectiveDefinition.ContainsKey('disabled')) {
        $result['disabled'] = [bool]$effectiveDefinition['disabled']
    }
    if ($effectiveDefinition.ContainsKey('enabled')) {
        $result['enabled'] = [bool]$effectiveDefinition['enabled']
    }
    if ($result.Count -eq 0) {
        return $null
    }
    return $result
}

function Merge-BootstrapMcpServers {
    param(
        [Parameter(Mandatory = $true)][hashtable]$TargetMap,
        [Parameter(Mandatory = $true)][hashtable]$SourceMap,
        [Parameter(Mandatory = $true)][ValidateSet('standard', 'opencode', 'vscode', 'zed', 'zcode')][string]$Format
    )

    $applied = 0
    foreach ($serverName in $SourceMap.Keys) {
        $serverDef = ConvertTo-BootstrapHashtable -InputObject $SourceMap[$serverName]
        if (-not ($serverDef -is [hashtable])) { continue }

        $serverOut = ConvertTo-BootstrapMcpServerEntry -ServerDefinition $serverDef -Format $Format
        if (-not ($serverOut -is [hashtable])) { continue }

        $currentServer = @{}
        if ($TargetMap.ContainsKey($serverName) -and ($TargetMap[$serverName] -is [hashtable])) {
            $currentServer = ConvertTo-BootstrapHashtable -InputObject $TargetMap[$serverName]
        }
        foreach ($propertyName in $serverOut.Keys) {
            $currentServer[$propertyName] = $serverOut[$propertyName]
        }
        $TargetMap[[string]$serverName] = $currentServer
        $applied += 1
    }
    return $applied
}

function Ensure-BootstrapJsonTargetFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][hashtable]$Target,
        [Parameter(Mandatory = $true)][string]$Label,
        [ValidateSet('standard', 'opencode', 'vscode', 'zed', 'zcode')][string]$McpFormat = 'standard',
        [string]$McpPropertyName = 'mcpServers',
        [switch]$RemoveRootEnv
    )

    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }

    $settings = @{}
    if (Test-Path $Path) {
        try {
            $settings = Read-BootstrapJsonFile -Path $Path
            if (-not ($settings -is [hashtable])) { $settings = @{} }
        } catch {
            $backupPath = Backup-BootstrapFile -Path $Path
            if ($backupPath) {
                Write-Log ("{0} invalido; backup criado: {1}" -f $Label, $backupPath) 'WARN'
            } else {
                Write-Log "$Label invalido em $Path. O bootstrap vai preservar o arquivo existente e recriar o JSON mesclado." 'WARN'
            }
            $settings = @{}
        }
    }

    $before = ((ConvertTo-BootstrapObjectGraph -InputObject $settings) | ConvertTo-Json -Depth 20 -Compress)

    if ($RemoveRootEnv) {
        if ($settings.ContainsKey('env')) { $null = $settings.Remove('env') }
    } elseif ($Target.ContainsKey('env') -and ($Target['env'] -is [hashtable])) {
        $envMap = Ensure-BootstrapNamedMap -Parent $settings -Name 'env'
        Set-BootstrapNonEmptyStringValues -Target $envMap -Values $Target['env']
    }

    if ($Target.ContainsKey('mcpServers') -and ($Target['mcpServers'] -is [hashtable])) {
        $mcpChanges = @{}
        $appliedMcpServers = Merge-BootstrapMcpServers -TargetMap $mcpChanges -SourceMap $Target['mcpServers'] -Format $McpFormat
        if ($appliedMcpServers -gt 0) {
            $mcpMap = Ensure-BootstrapNamedMap -Parent $settings -Name $McpPropertyName
            foreach ($serverName in $mcpChanges.Keys) {
                $mcpMap[[string]$serverName] = $mcpChanges[$serverName]
            }
        }
    }

    if ($McpFormat -eq 'zed' -and $settings.ContainsKey($McpPropertyName) -and ($settings[$McpPropertyName] -is [hashtable])) {
        $rawMap = ConvertTo-BootstrapHashtable -InputObject $settings[$McpPropertyName]
        $cleanMap = @{}
        foreach ($serverName in @($rawMap.Keys)) {
            $entry = ConvertTo-BootstrapHashtable -InputObject $rawMap[$serverName]
            if (-not ($entry -is [hashtable])) { continue }

            $url = ''
            if ($entry.ContainsKey('url')) {
                $url = Normalize-BootstrapScalarString -Value $entry['url']
            }
            if (-not [string]::IsNullOrWhiteSpace($url)) {
                $clean = [ordered]@{
                    url = $url
                }
                if ($entry.ContainsKey('headers') -and ($entry['headers'] -is [hashtable])) {
                    $headers = @{}
                    Set-BootstrapNonEmptyStringValues -Target $headers -Values $entry['headers']
                    if ($headers.Count -gt 0) {
                        $clean['headers'] = $headers
                    }
                }
                $cleanMap[[string]$serverName] = $clean
                continue
            }

            $command = ''
            if ($entry.ContainsKey('command')) {
                $command = Normalize-BootstrapScalarString -Value $entry['command']
            }
            if (-not [string]::IsNullOrWhiteSpace($command)) {
                $clean = [ordered]@{
                    command = $command
                }
                if ($entry.ContainsKey('args')) {
                    $clean['args'] = @($entry['args'])
                }
                if ($entry.ContainsKey('env') -and ($entry['env'] -is [hashtable])) {
                    $envOut = @{}
                    Set-BootstrapNonEmptyStringValues -Target $envOut -Values $entry['env']
                    if ($envOut.Count -gt 0) {
                        $clean['env'] = $envOut
                    }
                }
                $cleanMap[[string]$serverName] = $clean
                continue
            }
        }
        $settings[$McpPropertyName] = $cleanMap
    }

    $after = ((ConvertTo-BootstrapObjectGraph -InputObject $settings) | ConvertTo-Json -Depth 20 -Compress)
    if ($before -eq $after) {
        return $false
    }

    if (Test-Path $Path) {
        $backupPath = Backup-BootstrapFile -Path $Path
        if ($backupPath) {
            Write-Log ("Backup criado antes de atualizar {0}: {1}" -f $Label, $backupPath)
        }
    }

    Write-BootstrapJsonFile -Path $Path -Value $settings
    Write-Log ("Segredos aplicados em {0}: {1}" -f $Label, $Path)
    return $true
}

function Ensure-BootstrapZCodeStateMap {
    param([hashtable]$Store)

    $storageText = ''
    if ($Store.ContainsKey('mcp-storage')) {
        $storageText = [string]$Store['mcp-storage']
    }

    $storage = @{}
    if (-not [string]::IsNullOrWhiteSpace($storageText)) {
        try {
            $storage = ConvertTo-BootstrapHashtable -InputObject ($storageText | ConvertFrom-Json -ErrorAction Stop)
        } catch {
            Write-Log 'ZCode mcp-storage invalido. O bootstrap vai recriar a estrutura MCP mesclada.' 'WARN'
            $storage = @{}
        }
    }

    $state = Ensure-BootstrapNamedMap -Parent $storage -Name 'state'
    $config = Ensure-BootstrapNamedMap -Parent $state -Name 'config'
    $mcp = Ensure-BootstrapNamedMap -Parent $config -Name 'mcp'
    $null = Ensure-BootstrapNamedMap -Parent $mcp -Name 'mcpServers'

    if (-not $state.ContainsKey('servers') -or -not ($state['servers'] -is [System.Collections.IEnumerable])) {
        $state['servers'] = @()
    } else {
        $state['servers'] = @($state['servers'])
    }

    return $storage
}

function Sort-BootstrapGraphKeys {
    param([AllowNull()]$Node)

    if ($null -eq $Node) { return $null }
    if ($Node -is [System.Collections.IDictionary]) {
        $ordered = [ordered]@{}
        foreach ($key in (@($Node.Keys) | Sort-Object)) {
            $ordered[[string]$key] = Sort-BootstrapGraphKeys -Node $Node[$key]
        }
        return $ordered
    }
    if ($Node -is [System.Management.Automation.PSCustomObject]) {
        $ordered = [ordered]@{}
        foreach ($prop in (@($Node.PSObject.Properties) | Sort-Object Name)) {
            $ordered[[string]$prop.Name] = Sort-BootstrapGraphKeys -Node $prop.Value
        }
        return $ordered
    }
    if (($Node -is [System.Collections.IEnumerable]) -and -not ($Node -is [string])) {
        return @($Node | ForEach-Object { Sort-BootstrapGraphKeys -Node $_ })
    }
    return $Node
}

function ConvertTo-BootstrapStableJson {
    # Serializacao canonica (chaves ordenadas em todos os niveis) para comparar estruturas
    # sem falso-positivo de mudanca por ordem de chaves/whitespace.
    param([AllowNull()]$InputObject)

    $graph = ConvertTo-BootstrapObjectGraph -InputObject $InputObject
    return ([string]((Sort-BootstrapGraphKeys -Node $graph) | ConvertTo-Json -Depth 30 -Compress))
}

function Ensure-BootstrapZCodeSecrets {
    param([hashtable]$ResolvedTargets)

    if (-not ($ResolvedTargets -is [hashtable]) -or -not $ResolvedTargets.ContainsKey('zCode') -or -not ($ResolvedTargets['zCode'] -is [hashtable])) {
        return $false
    }

    $target = ConvertTo-BootstrapHashtable -InputObject $ResolvedTargets['zCode']
    # Autoprotecao: este alvo so aplica mcpServers; sem servidores aplicaveis nao ha o que gravar (evita store esqueleto orfao).
    if (-not ($target.ContainsKey('mcpServers') -and ($target['mcpServers'] -is [hashtable]) -and (@($target['mcpServers'].Keys).Count -gt 0))) {
        return $false
    }
    $storePath = Get-BootstrapZCodeStorePath
    if ([string]::IsNullOrWhiteSpace($storePath)) { return $false }

    $store = @{}
    if (Test-Path $storePath) {
        try {
            $store = Read-BootstrapJsonFile -Path $storePath
            if (-not ($store -is [hashtable])) { $store = @{} }
        } catch {
            Write-Log "ZCode store invalido em $storePath. O bootstrap vai preservar o arquivo existente e recriar o JSON mesclado." 'WARN'
            $store = @{}
        }
    }

    $storage = Ensure-BootstrapZCodeStateMap -Store $store
    $state = Ensure-BootstrapNamedMap -Parent $storage -Name 'state'
    $config = Ensure-BootstrapNamedMap -Parent $state -Name 'config'
    $mcp = Ensure-BootstrapNamedMap -Parent $config -Name 'mcp'
    $mcpServers = Ensure-BootstrapNamedMap -Parent $mcp -Name 'mcpServers'
    # Snapshot canonico (chaves ordenadas) pos-skeleton: so muda se houver mudanca funcional, matando o churn.
    $beforeStable = ConvertTo-BootstrapStableJson -InputObject $storage

    if ($target.ContainsKey('mcpServers') -and ($target['mcpServers'] -is [hashtable])) {
        $mcpChanges = @{}
        $appliedMcpServers = Merge-BootstrapMcpServers -TargetMap $mcpChanges -SourceMap $target['mcpServers'] -Format 'zcode'
        if ($appliedMcpServers -gt 0) {
            foreach ($serverName in $mcpChanges.Keys) {
                $mcpServers[[string]$serverName] = $mcpChanges[$serverName]
            }

            $currentServers = @()
            if ($state.ContainsKey('servers')) {
                $currentServers = @($state['servers'])
            }
            $serversByName = @{}
            foreach ($serverItem in $currentServers) {
                $serverHash = ConvertTo-BootstrapHashtable -InputObject $serverItem
                if ($serverHash.Count -eq 0) { continue }
                $existingName = ''
                if ($serverHash.ContainsKey('name')) {
                    $existingName = [string]$serverHash['name']
                }
                if ([string]::IsNullOrWhiteSpace($existingName)) { continue }
                $serversByName[$existingName] = $serverHash
            }
            foreach ($serverName in $mcpChanges.Keys) {
                $sourceDefinition = ConvertTo-BootstrapHashtable -InputObject $target['mcpServers'][$serverName]
                $serverRecord = @{}
                if ($serversByName.ContainsKey($serverName)) {
                    $serverRecord = $serversByName[$serverName]
                }
                $serverRecord['id'] = "mcp-$serverName"
                $serverRecord['name'] = [string]$serverName
                $serverRecord['config'] = $mcpChanges[$serverName]
                if ($sourceDefinition.ContainsKey('enabled')) {
                    $serverRecord['enabled'] = [bool]$sourceDefinition['enabled']
                } elseif ($sourceDefinition.ContainsKey('disabled')) {
                    $serverRecord['enabled'] = (-not [bool]$sourceDefinition['disabled'])
                } elseif (-not $serverRecord.ContainsKey('enabled')) {
                    $serverRecord['enabled'] = $true
                }
                if (-not $serverRecord.ContainsKey('source')) {
                    $serverRecord['source'] = 'user'
                }
                if (-not $serverRecord.ContainsKey('status')) {
                    $serverRecord['status'] = 'disconnected'
                }
                $serverRecord['changed'] = $true
                $serversByName[$serverName] = $serverRecord
            }
            $state['servers'] = @($serversByName.Keys | Sort-Object | ForEach-Object { $serversByName[$_] })
        }
    }

    $afterStable = ConvertTo-BootstrapStableJson -InputObject $storage
    if ($beforeStable -eq $afterStable) {
        return $false
    }
    $store['mcp-storage'] = [string]((ConvertTo-BootstrapObjectGraph -InputObject $storage) | ConvertTo-Json -Depth 30 -Compress)

    # Backup recuperavel antes de sobrescrever (preserva inclusive o caso de JSON corrompido).
    if (Test-Path $storePath) {
        try {
            Copy-Item -LiteralPath $storePath -Destination ($storePath + '.bak') -Force -ErrorAction Stop
        } catch {
            Write-Log ("Nao foi possivel gravar backup do store ZCode: {0}" -f $_.Exception.Message) 'WARN'
        }
    }
    Write-BootstrapJsonFile -Path $storePath -Value $store
    Write-Log ("Segredos aplicados em ZCode: {0}" -f $storePath)
    return $true
}

