function Ensure-BootstrapOpenCodeProviderAuth {
    param(
        [Parameter(Mandatory = $true)]$SecretsData,
        [string]$AuthPath = '',
        [string]$Label = 'OpenCode'
    )

    $path = if ([string]::IsNullOrWhiteSpace($AuthPath)) { Get-BootstrapOpenCodeAuthPath } else { $AuthPath }
    $auth = @{}
    if (-not [string]::IsNullOrWhiteSpace($path) -and (Test-Path $path)) {
        try {
            $auth = Read-BootstrapJsonFile -Path $path
            if (-not ($auth -is [hashtable])) { $auth = @{} }
        } catch {
            $backupPath = Backup-BootstrapFile -Path $path
            if ($backupPath) {
                Write-Log ("{0} auth.json invalido; backup criado: {1}" -f $Label, $backupPath) 'WARN'
            } else {
                Write-Log ("{0} auth.json invalido em {1}. O bootstrap vai recriar o JSON mesclado." -f $Label, $path) 'WARN'
            }
            $auth = @{}
        }
    }

    $before = ((ConvertTo-BootstrapObjectGraph -InputObject $auth) | ConvertTo-Json -Depth 20 -Compress)
    $applied = @()
    foreach ($record in @(Get-BootstrapOpenCodeProviderRecords -SecretsData $SecretsData)) {
        $providerId = [string]$record.providerId
        if ([string]::IsNullOrWhiteSpace($providerId)) { continue }
        $auth[$providerId] = [ordered]@{
            type = 'api'
            key = [string]$record.secret
        }
        $applied += @([ordered]@{
            provider = [string]$record.providerName
            providerId = $providerId
            credentialId = [string]$record.credentialId
        })
    }

    $after = ((ConvertTo-BootstrapObjectGraph -InputObject $auth) | ConvertTo-Json -Depth 20 -Compress)
    $updated = ($before -ne $after)
    if ($updated -and -not [string]::IsNullOrWhiteSpace($path)) {
        if (Test-Path $path) {
            $backupPath = Backup-BootstrapFile -Path $path
            if ($backupPath) {
                Write-Log ("Backup criado antes de atualizar {0} auth: {1}" -f $Label, $backupPath)
            }
        }
        Write-BootstrapJsonFile -Path $path -Value $auth
        Write-Log ("{0} auth sincronizado: {1}" -f $Label, $path)
    }

    return [ordered]@{
        path = $path
        updated = $updated
        providers = @($applied)
    }
}

function Move-BootstrapOpenCodeRootEnvToProviderConfig {
    param([Parameter(Mandatory = $true)][hashtable]$Settings)

    if (-not ($Settings.ContainsKey('env') -and ($Settings['env'] -is [hashtable]))) {
        return @()
    }

    $envMap = ConvertTo-BootstrapHashtable -InputObject $Settings['env']
    if (-not ($envMap -is [hashtable]) -or $envMap.Count -eq 0) {
        $null = $Settings.Remove('env')
        return @()
    }

    $mappings = @(
        @{ env = 'OPENAI_API_KEY'; provider = 'openai'; option = 'apiKey' },
        @{ env = 'OPENAI_BASE_URL'; provider = 'openai'; option = 'baseURL' },
        @{ env = 'OPENAI_ORGANIZATION'; provider = 'openai'; option = 'organization' },
        @{ env = 'ANTHROPIC_API_KEY'; provider = 'anthropic'; option = 'apiKey' },
        @{ env = 'OPENROUTER_API_KEY'; provider = 'openrouter'; option = 'apiKey' },
        @{ env = 'OPENROUTER_BASE_URL'; provider = 'openrouter'; option = 'baseURL' },
        @{ env = 'DEEPSEEK_API_KEY'; provider = 'deepseek'; option = 'apiKey' },
        @{ env = 'DEEPSEEK_BASE_URL'; provider = 'deepseek'; option = 'baseURL' },
        @{ env = 'MOONSHOT_API_KEY'; provider = 'moonshot'; option = 'apiKey' },
        @{ env = 'MOONSHOT_BASE_URL'; provider = 'moonshot'; option = 'baseURL' },
        @{ env = 'XAI_API_KEY'; provider = 'xai'; option = 'apiKey' },
        @{ env = 'XAI_BASE_URL'; provider = 'xai'; option = 'baseURL' }
    )

    $providerMap = Ensure-BootstrapNamedMap -Parent $Settings -Name 'provider'
    $moved = @()
    foreach ($mapping in @($mappings)) {
        $envName = [string]$mapping.env
        if (-not $envMap.ContainsKey($envName)) { continue }
        $value = [string]$envMap[$envName]
        if ([string]::IsNullOrWhiteSpace($value)) { continue }

        $providerId = [string]$mapping.provider
        $optionName = [string]$mapping.option
        $providerConfig = @{}
        if ($providerMap.ContainsKey($providerId) -and ($providerMap[$providerId] -is [hashtable])) {
            $providerConfig = ConvertTo-BootstrapHashtable -InputObject $providerMap[$providerId]
        }
        $options = Ensure-BootstrapNamedMap -Parent $providerConfig -Name 'options'
        if (-not $options.ContainsKey($optionName) -or [string]::IsNullOrWhiteSpace([string]$options[$optionName])) {
            $options[$optionName] = $value
            $moved += @($envName)
        }
        $providerMap[$providerId] = $providerConfig
    }

    $null = $Settings.Remove('env')
    return @($moved)
}

function Ensure-BootstrapOpenCodeProviderConfig {
    param(
        [Parameter(Mandatory = $true)]$SecretsData,
        [string]$ConfigPath = '',
        [string]$Label = 'OpenCode'
    )

    $path = if ([string]::IsNullOrWhiteSpace($ConfigPath)) { Get-BootstrapOpenCodeConfigPath } else { $ConfigPath }
    $settings = @{}
    if (-not [string]::IsNullOrWhiteSpace($path) -and (Test-Path $path)) {
        try {
            $settings = Read-BootstrapJsonFile -Path $path
            if (-not ($settings -is [hashtable])) { $settings = @{} }
        } catch {
            $backupPath = Backup-BootstrapFile -Path $path
            if ($backupPath) {
                Write-Log ("{0} config invalido; backup criado: {1}" -f $Label, $backupPath) 'WARN'
            } else {
                Write-Log ("{0} config invalido em {1}. O bootstrap vai preservar o arquivo existente e recriar o JSON mesclado." -f $Label, $path) 'WARN'
            }
            $settings = @{}
        }
    }

    $before = ((ConvertTo-BootstrapObjectGraph -InputObject $settings) | ConvertTo-Json -Depth 30 -Compress)
    $migratedRootEnv = @(Move-BootstrapOpenCodeRootEnvToProviderConfig -Settings $settings)
    if (-not $settings.ContainsKey('$schema')) {
        $settings['$schema'] = 'https://opencode.ai/config.json'
    }

    $providerMap = Ensure-BootstrapNamedMap -Parent $settings -Name 'provider'
    $applied = @()
    foreach ($record in @(Get-BootstrapOpenCodeProviderRecords -SecretsData $SecretsData)) {
        if (-not [bool]$record.needsConfig) { continue }
        $providerId = [string]$record.providerId
        if ([string]::IsNullOrWhiteSpace($providerId)) { continue }

        $providerConfig = @{}
        if ($providerMap.ContainsKey($providerId) -and ($providerMap[$providerId] -is [hashtable])) {
            $providerConfig = ConvertTo-BootstrapHashtable -InputObject $providerMap[$providerId]
        }
        $options = Ensure-BootstrapNamedMap -Parent $providerConfig -Name 'options'
        $options['baseURL'] = [string]$record.baseUrl
        if (-not $providerConfig.ContainsKey('name') -or [string]::IsNullOrWhiteSpace([string]$providerConfig['name'])) {
            $providerConfig['name'] = [string]$record.displayName
        }
        $providerMap[$providerId] = $providerConfig
        $applied += @([ordered]@{
            provider = [string]$record.providerName
            providerId = $providerId
            credentialId = [string]$record.credentialId
        })
    }

    if ($providerMap.Count -eq 0) {
        Remove-BootstrapEmptyNamedMap -Parent $settings -Name 'provider' | Out-Null
    }

    $after = ((ConvertTo-BootstrapObjectGraph -InputObject $settings) | ConvertTo-Json -Depth 30 -Compress)
    $updated = ($before -ne $after)
    if ($updated -and -not [string]::IsNullOrWhiteSpace($path)) {
        if (Test-Path $path) {
            $backupPath = Backup-BootstrapFile -Path $path
            if ($backupPath) {
                Write-Log ("Backup criado antes de atualizar {0} config: {1}" -f $Label, $backupPath)
            }
        }
        Write-BootstrapJsonFile -Path $path -Value $settings
        Write-Log ("{0} provider config sincronizado: {1}" -f $Label, $path)
        if ($migratedRootEnv.Count -gt 0) {
            Write-Log ("{0} env raiz invalido migrado/removido: {1}" -f $Label, (@($migratedRootEnv) -join ', '))
        }
    }

    return [ordered]@{
        path = $path
        updated = $updated
        providers = @($applied)
    }
}

