        claudeCode = [ordered]@{ displayName = 'Claude Code'; ruleFiles = @((Join-Path $root 'CLAUDE.md'), (Join-Path $root 'AGENTS.md')); mcp = @((Join-Path $env:USERPROFILE '.claude\settings.json')) }
        cursor = [ordered]@{ displayName = 'Cursor'; ruleFiles = @((Join-Path $root '.cursor\rules\phasezero-tools.mdc')); mcp = @((Get-BootstrapCursorMcpConfigPath)) }
        windsurf = [ordered]@{ displayName = 'Windsurf'; ruleFiles = @((Join-Path $root '.windsurf\rules\phasezero-tools.md')); mcp = @((Get-BootstrapWindsurfMcpConfigPath)) }
        vsCode = [ordered]@{ displayName = 'VS Code'; ruleFiles = @((Join-Path $root '.github\copilot-instructions.md')); mcp = @((Get-BootstrapVsCodeMcpConfigPath)) }
        zed = [ordered]@{ displayName = 'Zed'; ruleFiles = @(); mcp = @((Get-BootstrapZedConfigPath)) }
        openCode = [ordered]@{ displayName = 'OpenCode'; ruleFiles = @((Join-Path $root 'AGENTS.md')); mcp = @((Get-BootstrapOpenCodeConfigPath)) }
        cline = [ordered]@{ displayName = 'Cline'; ruleFiles = @((Join-Path $root '.clinerules\phasezero-tools.md')); mcp = @((Get-BootstrapClineMcpConfigPath)) }
        roo = [ordered]@{ displayName = 'Roo Code'; ruleFiles = @(); mcp = @((Get-BootstrapRooMcpConfigPath)) }
        geminiCli = [ordered]@{ displayName = 'Gemini CLI'; ruleFiles = @((Join-Path $root 'AGENTS.md')); mcp = @() }
    }
}

function Get-BootstrapAgentCompatPlan {
    param([string]$WorkspaceRoot = (Get-Location).Path)

    $root = if ([string]::IsNullOrWhiteSpace($WorkspaceRoot)) { (Get-Location).Path } else { [System.IO.Path]::GetFullPath($WorkspaceRoot) }
    $rtkPath = Resolve-BootstrapAgentCompatToolPath -Name 'rtk'
    $memoryPath = Resolve-BootstrapAgentCompatToolPath -Name 'ai-memory'
    $ponytailDetected = Test-BootstrapPonytailWorkspace -WorkspaceRoot $root
    $cavemanTemplate = Get-BootstrapCavemanTemplatePath

    $targets = [ordered]@{}
    $targetCatalog = Get-BootstrapAgentCompatTargetCatalog -WorkspaceRoot $root
    foreach ($targetId in @($targetCatalog.Keys)) {
        $target = ConvertTo-BootstrapHashtable -InputObject $targetCatalog[$targetId]
        $paths = @(@($target['ruleFiles']) + @($target['mcp']) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
        $present = $false
        foreach ($candidate in @($paths)) {
            if (Test-Path -LiteralPath ([string]$candidate)) { $present = $true; break }
        }
        $targets[$targetId] = [ordered]@{
            displayName = [string]$target['displayName']
            configuredArtifactPresent = $present
            ruleFiles = @($target['ruleFiles'])
            mcpFiles = @($target['mcp'])
        }
    }

    $mode = if (-not [string]::IsNullOrWhiteSpace($rtkPath) -and -not [string]::IsNullOrWhiteSpace($memoryPath)) { 'ready' } else { 'degraded' }
    return [ordered]@{
        schemaVersion = 'agent-compat/v1'
        generatedAt = (Get-Date).ToString('o')
        workspaceRoot = $root
        mode = $mode
        tools = [ordered]@{
            caveman = [ordered]@{ status = if (Test-Path -LiteralPath $cavemanTemplate) { 'available' } else { 'fallback' }; path = $cavemanTemplate; role = 'style' }
            rtk = [ordered]@{ status = if ([string]::IsNullOrWhiteSpace($rtkPath)) { 'absent' } else { 'available' }; path = $rtkPath; role = 'shell-compression' }
            aiMemory = [ordered]@{ status = if ([string]::IsNullOrWhiteSpace($memoryPath)) { 'absent' } else { 'available' }; path = $memoryPath; role = 'memory-handoff' }
            ponytail = [ordered]@{ status = if ($ponytailDetected) { 'active' } else { 'inactive' }; path = Get-BootstrapPonytailTemplatePath; role = 'workspace-architecture' }
        }
        policies = [ordered]@{
            caveman = 'always-on-style'
            rtk = if ([string]::IsNullOrWhiteSpace($rtkPath)) { 'degraded' } else { 'strict' }
            aiMemory = if ([string]::IsNullOrWhiteSpace($memoryPath)) { 'degraded' } else { 'wired' }
            ponytail = if ($ponytailDetected) { 'workspace-only' } else { 'inactive' }
        }
        targets = $targets
        conflictRules = @(
            'style=caveman',
            'shell=rtk-when-present',
            'memory=ai-memory-when-present',
            'architecture=ponytail-workspace-only',
            'no-duplicate-wrappers',
            'no-secrets-in-rules'
        )
    }
}

function Get-BootstrapAgentCompatStatePath {
    return (Join-Path (Get-BootstrapDataRoot) 'agent-compat-state.json')
}

function Ensure-BootstrapAgentCompatRuntime {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [AllowNull()]$ComponentDef = $null
    )

    $workspaceRoot = if ($State -and $State.ContainsKey('CloneBaseDir') -and -not [string]::IsNullOrWhiteSpace([string]$State.CloneBaseDir)) { [string]$State.CloneBaseDir } else { (Get-Location).Path }
    $plan = Get-BootstrapAgentCompatPlan -WorkspaceRoot $workspaceRoot
    $dryRun = [bool]$State.DryRun
    if ($dryRun) {
        $phaseZeroRules = [ordered]@{ status = 'planned'; updated = $false; workspaceRoot = $workspaceRoot }
        $ponytailRules = if ([string]$plan.tools.ponytail.status -eq 'active') {
            [ordered]@{ status = 'planned'; reason = 'ponytail-detected'; updated = $false; workspaceRoot = $workspaceRoot }
        } else {
            [ordered]@{ status = 'skipped'; reason = 'ponytail-not-detected'; updated = $false; workspaceRoot = $workspaceRoot }
        }
    } else {
        $phaseZeroRules = Ensure-BootstrapPhaseZeroToolRuleFiles -WorkspaceRoot $workspaceRoot
        $ponytailRules = Ensure-BootstrapPonytailRuleFiles -WorkspaceRoot $workspaceRoot
    }

    $summary = [ordered]@{
        status = 'completed'
        dryRun = $dryRun
        statePath = Get-BootstrapAgentCompatStatePath
        plan = $plan
        phaseZeroRules = $phaseZeroRules
        ponytailRules = $ponytailRules
    }

    if (-not $dryRun) {
        Write-BootstrapJsonFile -Path ([string]$summary.statePath) -Value $summary
        Write-Log ("Agent compat runtime sincronizado: {0}; mode={1}" -f [string]$summary.statePath, [string]$plan.mode)
    } else {
        Write-Log ("Agent compat runtime dry-run: mode={0}; workspace={1}" -f [string]$plan.mode, $workspaceRoot)
    }

    $State.AgentCompatStatePath = [string]$summary.statePath
    $State.AgentCompatSummary = $summary
    return $summary
}

function Invoke-BootstrapPhaseZeroPostConfig {
    param(
        [hashtable]$State,
        [switch]$DryRun
    )
    $results = New-Object System.Collections.Generic.List[object]
    # 1. rtk — garantir instalado e aplicar agent-config-claude-rtk-template
    $rtkEntry = $null
    $aiCatalog = Get-BootstrapAiToolCatalog
    if ($aiCatalog -and $aiCatalog.Contains('rtk')) { $rtkEntry = $aiCatalog['rtk'] }
    if ($rtkEntry) {
        try {
            $rtkResult = Install-BootstrapAiProxyManagedTool -ToolName 'rtk' -CatalogEntry $rtkEntry -DryRun:$DryRun
            $results.Add([ordered]@{ tool = 'rtk'; action = 'install'; status = if ($DryRun) { 'planned' } else { 'installed' }; detail = ($rtkResult.Message -replace '\s+',' ') })
        } catch {
            $results.Add([ordered]@{ tool = 'rtk'; action = 'install'; status = 'failed'; detail = $_.Exception.Message })
        }
    }
    # 2. ai-memory — detect agents and wire
    $agentsToWire = @()
    foreach ($agent in @('claude-code', 'codex-cli', 'opencode')) {
        $path = Resolve-CommandPath -Name ($agent -replace '-cli$','')
        if ($path) { $agentsToWire += $agent }
    }
    $memoryExe = Get-BootstrapAiMemoryExePath
    if (-not $memoryExe) { $memoryExe = Resolve-CommandPath -Name 'ai-memory' }
    if ($memoryExe -and $agentsToWire.Count -gt 0) {
        $wiringResult = Invoke-BootstrapAiMemoryWiring -ExePath $memoryExe -Agents $agentsToWire -DryRun:$DryRun
        $results.Add([ordered]@{ tool = 'ai-memory'; action = 'wiring'; agents = @($agentsToWire); status = 'applied'; detail = @($wiringResult) })
        $taskResult = Ensure-BootstrapAiMemoryServerTask -ExePath $memoryExe -DryRun:$DryRun
        $results.Add([ordered]@{ tool = 'ai-memory'; action = 'server-task'; status = $taskResult.status; detail = $taskResult })
    } else {
        $results.Add([ordered]@{ tool = 'ai-memory'; action = 'wiring'; status = 'skipped'; detail = if (-not $memoryExe) { 'ai-memory nao encontrado' } else { 'nenhum agente detectado' } })
    }
    # Resolve workspace de forma segura: nunca cair no diretorio atual silenciosamente.
    $workspaceRoot = $PSScriptRoot
    if ($State -and ($State -is [hashtable]) -and $State.ContainsKey('CloneBaseDir') -and -not [string]::IsNullOrWhiteSpace([string]$State.CloneBaseDir)) {
        $workspaceRoot = [string]$State.CloneBaseDir
    }
    # 3. caveman — reaplicar Ensure-BootstrapAgentSkills
    if ($DryRun) {
        $results.Add([ordered]@{ tool = 'caveman'; action = 'agent-skills'; status = 'planned'; detail = 'DryRun: nenhuma regra caveman gravada.' })
    } else {
        try {
            $cavemanResult = Ensure-BootstrapAgentSkills -State $State
            $results.Add([ordered]@{ tool = 'caveman'; action = 'agent-skills'; status = 'applied'; detail = $cavemanResult })
        } catch {
            $results.Add([ordered]@{ tool = 'caveman'; action = 'agent-skills'; status = 'failed'; detail = $_.Exception.Message })
        }
    }
    # 4. phasezero-tools rule files
    if ($DryRun) {
        $results.Add([ordered]@{ tool = 'phasezero-tools-rule'; action = 'rule-files'; status = 'planned'; detail = ("DryRun: regras seriam gravadas em {0}." -f $workspaceRoot) })
    } else {
        try {
            $rulesResult = Ensure-BootstrapPhaseZeroToolRuleFiles -WorkspaceRoot $workspaceRoot
            $results.Add([ordered]@{ tool = 'phasezero-tools-rule'; action = 'rule-files'; status = 'applied'; detail = $rulesResult })
        } catch {
            $results.Add([ordered]@{ tool = 'phasezero-tools-rule'; action = 'rule-files'; status = 'failed'; detail = $_.Exception.Message })
        }
    }
    return [ordered]@{
        phaseZeroPostConfig = [ordered]@{
            results = @($results.ToArray())
            completedAt = (Get-Date).ToString('o')
        }
    }
}

function Invoke-BootstrapCavemanCommandList {
    param(
        [Parameter(Mandatory = $true)][string]$RuntimePath,
        [Parameter(Mandatory = $true)][object[]]$Commands
    )

    $lastCommand = ''
    foreach ($commandRaw in @($Commands)) {
        $command = ConvertTo-BootstrapHashtable -InputObject $commandRaw
        if (-not ($command -is [hashtable])) { continue }
        $lastCommand = Format-BootstrapCommandSpec -Command $command
        $exitCode = Invoke-NativeWithLog -Exe $RuntimePath -Args @($command['args'])
        if ($exitCode -ne 0) {
            return [ordered]@{
                ok = $false
                lastCommand = $lastCommand
                exitCode = $exitCode
            }
        }
    }

    return [ordered]@{
        ok = $true
        lastCommand = $lastCommand
        exitCode = 0
    }
}

function Ensure-BootstrapAgentSkills {
    param([hashtable]$State)

    $statePath = Get-BootstrapAgentSkillStatePath
    $catalog = Get-BootstrapCavemanTargetCatalog
    $summary = [ordered]@{
        path = $statePath
        generatedAt = (Get-Date).ToString('o')
        skill = 'caveman'
        templatePath = Get-BootstrapCavemanTemplatePath
        rules = Ensure-BootstrapCavemanRuleFiles -WorkspaceRoot ([string]$State.CloneBaseDir)
        targets = [ordered]@{}
    }

    foreach ($targetId in @($catalog.Keys)) {
        $target = ConvertTo-BootstrapHashtable -InputObject $catalog[$targetId]
        $runtimeName = [string]$target['runtime']
        $runtimePath = Resolve-CommandPath -Name $runtimeName
        $record = [ordered]@{
            displayName = [string]$target['displayName']
            runtime = $runtimeName
            runtimePath = if ($runtimePath) { [string]$runtimePath } else { '' }
            status = 'skipped'
            lastCommand = ''
            error = ''
            fallbackUsed = $false
            checkedAt = (Get-Date).ToString('o')
        }

        if (-not $runtimePath) {
            $record.error = 'runtime ausente'
            $summary.targets[$targetId] = $record
            Write-Log ("Agent skills: runtime ausente para {0}; pulando." -f $record.displayName) 'WARN'
            continue
        }

        $result = Invoke-BootstrapCavemanCommandList -RuntimePath $runtimePath -Commands @($target['commands'])
        if (-not [bool]$result.ok -and $targetId -eq 'claudeCode' -and @($target['fallbackCommands']).Count -gt 0) {
            $fallbackRuntime = Resolve-CommandPath -Name 'powershell'
            if (-not $fallbackRuntime) {
                $fallbackRuntime = Resolve-CommandPath -Name 'powershell.exe'
            }
            if ($fallbackRuntime) {
                $record.fallbackUsed = $true
                $result = Invoke-BootstrapCavemanCommandList -RuntimePath $fallbackRuntime -Commands @($target['fallbackCommands'])
            }
        }

        $record.lastCommand = [string]$result.lastCommand
        if ([bool]$result.ok) {
            $record.status = if ([bool]$record.fallbackUsed) { 'installed-fallback' } else { 'installed' }
        } else {
            $record.status = 'failed'
            $record.error = ('exit={0}' -f [string]$result.exitCode)
        }
        $summary.targets[$targetId] = $record
    }

    Write-BootstrapJsonFile -Path $statePath -Value $summary
    Write-Log ("Estado local de agent skills sincronizado: {0}" -f $statePath)

    $State.AgentSkillStatePath = $statePath
    $State.AgentSkillSummary = $summary
    return $summary
}

function Ensure-BootstrapVsCodeExtensions {
    param([hashtable]$State)

    $bundlePath = if (-not [string]::IsNullOrWhiteSpace([string]$State.SecretsPath) -and (Test-Path $State.SecretsPath)) {
        [string]$State.SecretsPath
    } else {
        Get-BootstrapSecretsPath
    }

    $secretsData = if (Test-Path $bundlePath) { Read-BootstrapJsonFile -Path $bundlePath } else { Get-BootstrapSecretsTemplate }
    $resolvedTargets = Get-BootstrapResolvedSecretsTargets -SecretsData $secretsData -IncludeManagedMcps
    $editorTargets = Get-BootstrapVsCodeEditorTargets
    $extensionCatalog = Get-BootstrapVsCodeExtensionCatalog
    $statePath = Get-BootstrapVsCodeExtensionStatePath

    $summary = [ordered]@{
        path = $statePath
        generatedAt = (Get-Date).ToString('o')
        editors = [ordered]@{}
        continue = [ordered]@{}
        authPending = @()
        extensions = @()
    }

    $agentMemorySettings = @{
        'agentMemory.storageBackend' = 'secret'
        'agentMemory.autoSyncToFile' = ''
    }

    foreach ($channel in @($editorTargets.Keys)) {
        $editor = $editorTargets[$channel]
        $editorSummary = [ordered]@{
            displayName = [string]$editor['displayName']
            available = [bool]$editor['available']
            cliPath = [string]$editor['cliPath']
            settingsPath = [string]$editor['settingsPath']
            settingsUpdated = $false
            installed = @()
            failed = @()
        }

        if (-not $editorSummary.available) {
            Write-Log ("Editor ausente, extensoes serao ignoradas: {0}" -f $editorSummary.displayName) 'WARN'
            $summary.editors[$channel] = $editorSummary
            continue
        }

        $installedExtensions = @(Get-BootstrapInstalledVsCodeExtensions -CliPath $editorSummary.cliPath)
        foreach ($extensionId in $extensionCatalog.Keys) {
            $definition = $extensionCatalog[$extensionId]
            if (-not (@($definition['channels']) -contains $channel)) { continue }

            $installResult = Ensure-BootstrapVsCodeExtensionInstalled -CliPath $editorSummary.cliPath -ExtensionDefinition $definition -InstalledExtensions $installedExtensions -EditorLabel $editorSummary.displayName
            $record = [ordered]@{
                editor = $editorSummary.displayName
                extensionId = [string]$definition['id']
                displayName = [string]$definition['displayName']
                installed = [bool]$installResult['installed']
                changed = [bool]$installResult['changed']
                configKind = [string]$definition['configKind']
                error = [string]$installResult['error']
            }

            if ($record.installed) {
                $editorSummary.installed += @([string]$record.extensionId)
                if ($record.changed) {
                    $installedExtensions += @([string]$record.extensionId)
                }
            } else {
                $editorSummary.failed += @([string]$record.extensionId)
            }

            $summary.extensions += @($record)
        }

        $editorSummary.settingsUpdated = Ensure-BootstrapJsonPropertyFile -Path $editorSummary.settingsPath -Values $agentMemorySettings -Label ($editorSummary.displayName + ' settings.json')
        $summary.editors[$channel] = $editorSummary
    }

    if ($resolvedTargets.ContainsKey('roo') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['roo'])) {
        $null = Ensure-BootstrapRooSecrets -ResolvedTargets $resolvedTargets
    }
    if ($resolvedTargets.ContainsKey('cline') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['cline'])) {
        $null = Ensure-BootstrapClineSecrets -ResolvedTargets $resolvedTargets
    }

    $summary.continue = Ensure-BootstrapContinueExtensionConfig -ResolvedTargets $resolvedTargets
    foreach ($definition in $extensionCatalog.Values) {
        if ([string]::IsNullOrWhiteSpace([string]$definition['authPendingReason'])) { continue }
        $summary.authPending += @([ordered]@{
            extensionId = [string]$definition['id']
            displayName = [string]$definition['displayName']
            reason = [string]$definition['authPendingReason']
        })
    }

    Write-BootstrapJsonFile -Path $statePath -Value $summary
    Write-Log ("Estado local de extensoes VS Code sincronizado: {0}" -f $statePath)

    $State.VsCodeExtensionsPath = $statePath
    $State.VsCodeExtensionsSummary = $summary
    return $summary
}

function Ensure-BootstrapSecrets {
    param([hashtable]$State)

    $bundle = Get-BootstrapSecretsData
    $validatedData = Invoke-BootstrapSecretsValidation -SecretsData $bundle.Data
    Write-BootstrapJsonFile -Path $bundle.Path -Value $validatedData
    $resolvedTargets = Get-BootstrapResolvedSecretsTargets -SecretsData $validatedData
    $diagnostics = Get-BootstrapSecretsDiagnostics -SecretsData $validatedData
    $summary = [ordered]@{
        path = [string]$bundle['Path']
        createdTemplate = $bundle.Created
        userEnvApplied = 0
        claudeCodeUpdated = $false
        claudeDesktopUpdated = $false
        cursorUpdated = $false
        windsurfUpdated = $false
        traeUpdated = $false
        openCodeUpdated = $false
        vsCodeUpdated = $false
        rooUpdated = $false
        clineUpdated = $false
        zedUpdated = $false
        zCodeUpdated = $false
        openClawUpdated = $false
        hermesUpdated = $false
        kiloUpdated = $false
        cometUpdated = $false
        cometGuide = Get-BootstrapCometGuide -SecretsData $validatedData
        diagnostics = $diagnostics
    }

    if ($resolvedTargets.ContainsKey('userEnv') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['userEnv'])) {
        $summary.userEnvApplied = Ensure-BootstrapUserEnvSecrets -ResolvedTargets $resolvedTargets
    }
    if ($resolvedTargets.ContainsKey('claudeCode') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['claudeCode'])) {
        $summary.claudeCodeUpdated = Ensure-BootstrapClaudeCodeSecrets -ResolvedTargets $resolvedTargets
    }
    if ($resolvedTargets.ContainsKey('claudeDesktop') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['claudeDesktop'])) {
        $summary.claudeDesktopUpdated = Ensure-BootstrapClaudeDesktopSecrets -ResolvedTargets $resolvedTargets
    }
    if ($resolvedTargets.ContainsKey('cursor') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['cursor'])) {
        $summary.cursorUpdated = Ensure-BootstrapCursorSecrets -ResolvedTargets $resolvedTargets
    }
    if ($resolvedTargets.ContainsKey('windsurf') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['windsurf'])) {
        $summary.windsurfUpdated = Ensure-BootstrapWindsurfSecrets -ResolvedTargets $resolvedTargets
    }
    if ($resolvedTargets.ContainsKey('trae') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['trae'])) {
        $summary.traeUpdated = Ensure-BootstrapTraeSecrets -ResolvedTargets $resolvedTargets
    }
    if ($resolvedTargets.ContainsKey('openCode') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['openCode'])) {
        $summary.openCodeUpdated = Ensure-BootstrapOpenCodeSecrets -ResolvedTargets $resolvedTargets -SecretsData $validatedData
    }
    if ($resolvedTargets.ContainsKey('vsCode') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['vsCode'])) {
        $summary.vsCodeUpdated = Ensure-BootstrapVsCodeSecrets -ResolvedTargets $resolvedTargets
    }
    if ($resolvedTargets.ContainsKey('roo') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['roo'])) {
        $summary.rooUpdated = Ensure-BootstrapRooSecrets -ResolvedTargets $resolvedTargets
    }
    if ($resolvedTargets.ContainsKey('cline') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['cline'])) {
        $summary.clineUpdated = Ensure-BootstrapClineSecrets -ResolvedTargets $resolvedTargets
    }
    if ($resolvedTargets.ContainsKey('zed') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['zed'])) {
        $summary.zedUpdated = Ensure-BootstrapZedSecrets -ResolvedTargets $resolvedTargets
    }
    if ($resolvedTargets.ContainsKey('zCode') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['zCode'])) {
        $summary.zCodeUpdated = Ensure-BootstrapZCodeSecrets -ResolvedTargets $resolvedTargets
    }
    if ($resolvedTargets.ContainsKey('openClaw') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['openClaw'])) {
        $summary.openClawUpdated = Ensure-BootstrapOpenClawSecrets -ResolvedTargets $resolvedTargets
    }
    if ($resolvedTargets.ContainsKey('hermes') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['hermes'])) {
        $summary.hermesUpdated = Ensure-BootstrapHermesSecrets -ResolvedTargets $resolvedTargets -State $State
    }
    if ($resolvedTargets.ContainsKey('kilo') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['kilo'])) {
        $summary.kiloUpdated = Ensure-BootstrapKiloSecrets -ResolvedTargets $resolvedTargets -SecretsData $validatedData
    }
    if ($resolvedTargets.ContainsKey('comet') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['comet'])) {
        $summary.cometUpdated = Ensure-BootstrapCometSecrets -ResolvedTargets $resolvedTargets -SecretsData $validatedData
    }

    $State.SecretsPath = [string]$bundle['Path']
    $State.SecretsSummary = $summary

    foreach ($warning in @($diagnostics.warnings)) {
        Write-Log "Manifesto de segredos: $warning" 'WARN'
    }
    if ($diagnostics.Contains('openAiCompatible')) {
        $compat = ConvertTo-BootstrapHashtable -InputObject $diagnostics.openAiCompatible
        if (($compat -is [hashtable]) -and [string]$compat['status'] -ne 'selected') {
            Write-Log ("OpenAI-compatible: nenhum provider utilizável selecionado (status={0})." -f [string]$compat['status']) 'WARN'
        }
    }
    if ($diagnostics.Contains('claudeDesktopAccess')) {
        $claudeAccess = ConvertTo-BootstrapHashtable -InputObject $diagnostics.claudeDesktopAccess
        if (($claudeAccess -is [hashtable]) -and [string]$claudeAccess['status'] -eq 'blocked') {
            Write-Log ("Claude Desktop: {0} Ação: {1}" -f [string]$claudeAccess['message'], [string]$claudeAccess['action']) 'WARN'
        }
    }

    if ($bundle.Created) {
        Write-Log "Manifesto de segredos criado em $($bundle['Path']). Preencha as chaves e rode o bootstrap novamente para propagar tudo automaticamente." 'WARN'
    } else {
        Write-Log ("Manifesto de segredos sincronizado: env={0}, claudeCode={1}, claudeDesktop={2}, cursor={3}, windsurf={4}, trae={5}, openCode={6}, vsCode={7}, roo={8}, cline={9}, zed={10}, zCode={11}, openClaw={12}, hermes={13}, kilo={14}, comet={15}" -f $summary.userEnvApplied, $summary.claudeCodeUpdated, $summary.claudeDesktopUpdated, $summary.cursorUpdated, $summary.windsurfUpdated, $summary.traeUpdated, $summary.openCodeUpdated, $summary.vsCodeUpdated, $summary.rooUpdated, $summary.clineUpdated, $summary.zedUpdated, $summary.zCodeUpdated, $summary.openClawUpdated, $summary.hermesUpdated, $summary.kiloUpdated, $summary.cometUpdated)
    }
}

function Add-BootstrapResultFieldIfMissing {
    param(
        [Parameter(Mandatory = $true)][System.Collections.IDictionary]$Payload,
        [Parameter(Mandatory = $true)][string]$Name,
        [AllowNull()]$Value
    )

    if (-not $Payload.Contains($Name) -or $null -eq $Payload[$Name]) {
        $Payload[$Name] = $Value
    }
}

function ConvertTo-BootstrapResultPayloadDictionary {
    param([Parameter(Mandatory = $true)]$Value)

    $payload = [ordered]@{}
    if ($Value -is [System.Collections.IDictionary]) {
        foreach ($key in $Value.Keys) {
            $payload[[string]$key] = $Value[$key]
        }
        return $payload
    }

    foreach ($prop in @($Value.PSObject.Properties)) {
        $payload[[string]$prop.Name] = $prop.Value
    }
    return $payload
}

function Get-BootstrapResultExitCodeForStatus {
    param([string]$Status)

    switch (([string]$Status).ToLowerInvariant()) {
        'success' { return 0 }
        'warning' { return 0 }
        'blocked' { return 2 }
        default { return 1 }
    }
}

function Complete-BootstrapExecutionResultEnvelope {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)]$Value
    )

    $payload = ConvertTo-BootstrapResultPayloadDictionary -Value $Value
    Add-BootstrapResultFieldIfMissing -Payload $payload -Name 'mode' -Value 'profile'
    Add-BootstrapResultFieldIfMissing -Payload $payload -Name 'generatedAt' -Value ((Get-Date).ToString('o'))
    Add-BootstrapResultFieldIfMissing -Payload $payload -Name 'logPath' -Value $script:LogPath
    Add-BootstrapResultFieldIfMissing -Payload $payload -Name 'resultPath' -Value $Path
    Add-BootstrapResultFieldIfMissing -Payload $payload -Name 'exitCode' -Value (Get-BootstrapResultExitCodeForStatus -Status ([string]$payload['status']))
    $payload['logPath'] = Normalize-BootstrapPathSegment -Value $payload['logPath']
    $payload['resultPath'] = Normalize-BootstrapPathSegment -Value $payload['resultPath']

    if (-not $payload.Contains('artifactPaths') -or $null -eq $payload['artifactPaths']) {
        $artifactPaths = [ordered]@{
            logPath = [string]$payload['logPath']
            resultPath = [string]$payload['resultPath']
        }
        foreach ($name in @('stdoutPath','stderrPath','changesPath','appTuningReportRoot','hostHealthReportRoot')) {
            if ($payload.Contains($name) -and -not [string]::IsNullOrWhiteSpace([string]$payload[$name])) {
                $artifactPaths[$name] = [string]$payload[$name]
            }
        }
        $payload['artifactPaths'] = $artifactPaths
    }

    if (-not $payload.Contains('diagnostics') -or $null -eq $payload['diagnostics']) {
        $status = ([string]$payload['status']).ToLowerInvariant()
        $message = ''
        if ($payload.Contains('error')) { $message = [string]$payload['error'] }
        if ([string]::IsNullOrWhiteSpace($message) -and $payload.Contains('message')) { $message = [string]$payload['message'] }
        if ($status -in @('error','blocked','warning') -or -not [string]::IsNullOrWhiteSpace($message)) {
            if ([string]::IsNullOrWhiteSpace($message)) { $message = [string]$payload['status'] }
            $payload['diagnostics'] = @([ordered]@{
                severity = $(if ($status -eq 'blocked') { 'blocked' } elseif ($status -eq 'warning') { 'warning' } else { 'error' })
                message = $message
                howToFix = $(if ($payload.Contains('howToFix')) { [string]$payload['howToFix'] } else { '' })
            })
        } else {
            $payload['diagnostics'] = @()
        }
    }

    if (-not $payload.Contains('scope') -or $null -eq $payload['scope']) {
        $payload['scope'] = [ordered]@{
            selection = $(if ($payload.Contains('selection')) { $payload['selection'] } else { $null })
            resolution = $(if ($payload.Contains('resolution')) { $payload['resolution'] } else { $null })
            hostHealth = $(if ($payload.Contains('resolvedHostHealthMode')) { [string]$payload['resolvedHostHealthMode'] } else { '' })
            appTuning = $(if ($payload.Contains('resolvedAppTuningMode')) { [string]$payload['resolvedAppTuningMode'] } else { '' })
            steamDeckVersion = $(if ($payload.Contains('resolvedSteamDeckVersion')) { [string]$payload['resolvedSteamDeckVersion'] } else { '' })
        }
    }

    if (-not $payload.Contains('rollback') -or $null -eq $payload['rollback']) {
        $changesPath = if ($payload.Contains('changesPath')) { [string]$payload['changesPath'] } else { '' }
        $available = $false
        if ($payload.Contains('rollbackAvailable')) { $available = [bool]$payload['rollbackAvailable'] }
        $payload['rollback'] = [ordered]@{
            available = $available
            changesPath = $changesPath
            summary = $(if ($payload.Contains('changesSummary')) { $payload['changesSummary'] } else { $null })
        }
    }

    return $payload
}

function Write-BootstrapExecutionResultFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)]$Value
    )

    Write-BootstrapJsonFile -Path $Path -Value (Complete-BootstrapExecutionResultEnvelope -Path $Path -Value $Value)
}

function Ensure-BootstrapRegistryPath {
    param([Parameter(Mandatory = $true)][string]$Path)

    if (-not (Test-Path $Path)) {
        $null = New-Item -Path $Path -Force
    }
}

function Set-BootstrapRegistryDword {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$Name,
        [Parameter(Mandatory = $true)][int]$Value
    )

    try {
        $previous = $null
        if (Test-Path $Path) {
            $current = Get-ItemProperty -Path $Path -Name $Name -ErrorAction SilentlyContinue
            if ($current -and ($current.PSObject.Properties.Name -contains $Name)) {
                $previous = $current.$Name
            }
        } else {
            $null = New-Item -Path $Path -Force -ErrorAction SilentlyContinue
        }

        if ($State) {
            Register-BootstrapChange -State $State -Type 'Registry' -Target $Path -Name $Name -OldValue $previous
        }

        if (Test-Path $Path) {
            Set-ItemProperty -Path $Path -Name $Name -Value $Value -Type DWord -Force -ErrorAction Stop | Out-Null
        } else {
            New-ItemProperty -Path $Path -Name $Name -PropertyType DWord -Value $Value -Force -ErrorAction Stop | Out-Null
        }
    } catch {
        $msg = $_.Exception.Message
        if ($msg -match 'acesso.*negado' -or $msg -match 'localizar.*caminho' -or $_.Exception.GetType().FullName -match 'UnauthorizedAccess') {
            Write-Log ("HostHealth/Registry: acesso negado ou caminho ausente para {0}\{1}. Requer elevacao." -f $Path, $Name) 'WARN'
        } else {
            Write-Log ("HostHealth/Registry: falha ao definir {0}\{1} -> {2}" -f $Path, $Name, $msg) 'WARN'
        }
    }
}

function Get-BootstrapHostHealthReportRoot {
    param([hashtable]$State)

    if (-not $State.HostHealthReportRoot) {
        $State.HostHealthReportRoot = Get-BootstrapHostHealthRoot
    }

    $null = New-Item -Path $State.HostHealthReportRoot -ItemType Directory -Force
    return $State.HostHealthReportRoot
}

function Export-BootstrapHostHealthSnapshots {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Policy
    )

    $reportRoot = Get-BootstrapHostHealthReportRoot -State $State

    $startup = @(Get-CimInstance Win32_StartupCommand -ErrorAction SilentlyContinue | Select-Object Name, Command, Location, User)
    $tasks = @(Get-ScheduledTask -ErrorAction SilentlyContinue | Select-Object TaskPath, TaskName, State)
    $services = @(Get-Service -ErrorAction SilentlyContinue | Select-Object Name, DisplayName, StartType, Status)
    $appx = @(Get-AppxPackage -ErrorAction SilentlyContinue | Select-Object Name, PackageFullName)

    Write-BootstrapJsonFile -Path (Join-Path $reportRoot 'snapshot-startup.json') -Value $startup
    Write-BootstrapJsonFile -Path (Join-Path $reportRoot 'snapshot-tasks.json') -Value $tasks
    Write-BootstrapJsonFile -Path (Join-Path $reportRoot 'snapshot-services.json') -Value $services
    Write-BootstrapJsonFile -Path (Join-Path $reportRoot 'snapshot-appx.json') -Value $appx
    Write-BootstrapJsonFile -Path (Join-Path $reportRoot 'policy.json') -Value $Policy
}

function Test-BootstrapHostHealthProtectedTempItem {
    param([AllowNull()][string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) { return $true }

    try {
        $fullPath = [System.IO.Path]::GetFullPath($Path)
    } catch {
        $fullPath = [string]$Path
    }

    foreach ($protectedPath in @(
        $script:LogPath,
        $script:ResultPath,
        (Get-BootstrapDataRoot),
        (Join-Path $env:TEMP 'bootstrap-tools'),
        (Join-Path $env:LOCALAPPDATA 'bootstrap-tools'),
        (Join-Path $env:USERPROFILE '.bootstrap-tools')
    )) {
        if ([string]::IsNullOrWhiteSpace($protectedPath)) { continue }
        try {
            $protectedFullPath = [System.IO.Path]::GetFullPath([string]$protectedPath).TrimEnd('\')
        } catch {
            $protectedFullPath = ([string]$protectedPath).TrimEnd('\')
        }
        if ($fullPath.TrimEnd('\').Equals($protectedFullPath, [System.StringComparison]::OrdinalIgnoreCase) -or
            $fullPath.StartsWith($protectedFullPath + '\', [System.StringComparison]::OrdinalIgnoreCase)) {
            return $true
        }
    }

    $leaf = Split-Path -Path $fullPath -Leaf
    if ($leaf -match '^(codex|codex[-_].*|node-repl.*|node_repl.*|kernel-assets|bootstrap-tools)(\.|-|_|$)') {
        return $true
    }

    return $false
}

function Clear-BootstrapDirectoryContents {
    param([Parameter(Mandatory = $true)][string]$TargetPath)

    if (-not (Test-Path $TargetPath)) { return }

    foreach ($item in @(Get-ChildItem -LiteralPath $TargetPath -Force -ErrorAction SilentlyContinue)) {
        if (Test-BootstrapHostHealthProtectedTempItem -Path $item.FullName) {
            Write-Log "HostHealth cleanup: preservando $($item.FullName)"
            continue
        }
        try {
            if ($item.PSIsContainer) {
                Remove-Item -LiteralPath $item.FullName -Recurse -Force -ErrorAction Stop
            } else {
                Remove-Item -LiteralPath $item.FullName -Force -ErrorAction Stop
            }
        } catch {
            Write-Log "Nao foi possivel remover $($item.FullName). Pulando item em uso ou protegido." 'WARN'
        }
    }
}

function Invoke-BootstrapHostHealthCleanup {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Policy
    )

    $targets = @(
        $env:TEMP,
        (Join-Path $env:LOCALAPPDATA 'Temp')
    )

    if (Test-IsAdmin) {
        $targets += @('C:\Windows\Temp')
    }

    foreach ($target in $targets) {
        if ([string]::IsNullOrWhiteSpace($target)) { continue }
        Write-Log "HostHealth cleanup: limpando $target"
        Clear-BootstrapDirectoryContents -TargetPath $target
    }

    $bootstrapTempFiles = @(Get-ChildItem -LiteralPath $env:TEMP -Filter 'bootstrap-tools_*' -Force -ErrorAction SilentlyContinue)
    foreach ($file in $bootstrapTempFiles) {
        if ((Test-BootstrapHostHealthProtectedTempItem -Path $file.FullName) -or ($file.Extension -in @('.log', '.json'))) {
            Write-Log "HostHealth cleanup: preservando residuo observavel $($file.FullName)"
            continue
        }
        try {
            Remove-Item -LiteralPath $file.FullName -Force -ErrorAction Stop
        } catch {
            Write-Log "Nao foi possivel remover residuo do bootstrap: $($file.FullName)" 'WARN'
        }
    }

    if (Test-IsAdmin) {
        $dismExe = Join-Path $env:SystemRoot 'System32\dism.exe'
        if (Test-Path $dismExe) {
            $exitCode = Invoke-NativeWithLog -Exe $dismExe -Args @('/Online', '/Cleanup-Image', '/StartComponentCleanup')
            if (($exitCode -ne 0) -and ($exitCode -ne 3010)) {
                Write-Log "HostHealth cleanup: DISM StartComponentCleanup falhou (exit=$exitCode)." 'WARN'
            }
        }

        $windowsOld = 'C:\Windows.old'
        if (Test-Path $windowsOld) {
            $resolvedWindowsOld = (Get-Item -LiteralPath $windowsOld -ErrorAction SilentlyContinue).FullName
            if ($resolvedWindowsOld -eq $windowsOld) {
                try {
                    Remove-Item -LiteralPath $windowsOld -Recurse -Force -ErrorAction Stop
                    Write-Log 'HostHealth cleanup: Windows.old removido.'
                } catch {
                    Write-Log 'HostHealth cleanup: nao foi possivel remover C:\Windows.old.' 'WARN'
                }
            }
        }
    } else {
        Write-Log 'HostHealth cleanup: DISM e remocao de Windows.old requerem elevacao. Pulando.' 'WARN'
    }
}

function Disable-BootstrapRunEntries {
    param([string[]]$Patterns)

    $runPath = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
    if (-not (Test-Path $runPath)) { return }

    $item = Get-ItemProperty -Path $runPath -ErrorAction SilentlyContinue
    if (-not $item) { return }

    foreach ($property in @($item.PSObject.Properties)) {
        if ($property.Name -like 'PS*') { continue }
        foreach ($pattern in @($Patterns)) {
            if ($property.Name -like $pattern) {
                try {
                    Remove-ItemProperty -Path $runPath -Name $property.Name -ErrorAction Stop
                    Write-Log "HostHealth startup: entrada Run removida -> $($property.Name)"
                } catch {
                    Write-Log "HostHealth startup: falha ao remover Run $($property.Name)." 'WARN'
                }
                break
            }
        }
    }
}

function Disable-BootstrapScheduledTasks {
    param($TaskDefinitions)

    foreach ($taskDefinition in @($TaskDefinitions)) {
        if (-not $taskDefinition) { continue }
        try {
            $task = Get-ScheduledTask -TaskPath $taskDefinition.TaskPath -TaskName $taskDefinition.TaskName -ErrorAction Stop
            Disable-ScheduledTask -InputObject $task -ErrorAction Stop | Out-Null
            Write-Log "HostHealth startup: tarefa desabilitada -> $($taskDefinition.TaskPath)$($taskDefinition.TaskName)"
        } catch {
            Write-Log "HostHealth startup: tarefa nao alterada -> $($taskDefinition.TaskPath)$($taskDefinition.TaskName)" 'WARN'
        }
    }
}

function Set-BootstrapServiceStartupTypes {
    param(
        [AllowNull()][hashtable]$State = $null,
        $ServiceAdjustments,
        [switch]$StopService
    )

    if ($State) {
        $results = Set-BootstrapServiceTuning -State $State -ServiceAdjustments $ServiceAdjustments -StopService:$StopService
        foreach ($result in @($results)) {
            if ([string]$result.status -eq 'applied') {
                Write-Log "HostHealth startup: servico ajustado -> $([string]$result.name) => $([string]$result.startType)"
            } else {
                Write-Log "HostHealth startup: servico nao alterado -> $([string]$result.name) ($([string]$result.reason))" 'WARN'
            }
        }
        return
    }

    foreach ($adjustment in @($ServiceAdjustments)) {
        if (-not $adjustment) { continue }
        try {
            if ($StopService) { Stop-Service -Name $adjustment.Name -ErrorAction SilentlyContinue }
            Set-Service -Name $adjustment.Name -StartupType $adjustment.StartType -ErrorAction Stop
            Write-Log "HostHealth startup: servico ajustado -> $($adjustment.Name) => $($adjustment.StartType)"
        } catch {
            Write-Log "HostHealth startup: servico nao alterado -> $($adjustment.Name)" 'WARN'
        }
    }
}

function Invoke-BootstrapHostHealthStartup {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Policy
    )

    Disable-BootstrapRunEntries -Patterns @(
        'MicrosoftEdgeAutoLaunch_*',
        'Teams',
        'GoogleChromeAutoLaunch_*',
        'Outlook*',
        '*DevHome*',
        '*PCManager*'
    )

    if ($Policy.Mode -in @('equilibrado', 'agressivo')) {
        Disable-BootstrapScheduledTasks -TaskDefinitions $Policy.ScheduledTasksDisable
    }

    if ($Policy.Mode -eq 'agressivo') {
        if (Test-IsAdmin) {
            Set-BootstrapServiceStartupTypes -State $State -ServiceAdjustments $Policy.ServiceAdjustments -StopService
        } else {
            Write-Log 'HostHealth startup: ajustes de servico requerem elevacao. Pulando.' 'WARN'
        }
    }
}

function Invoke-BootstrapHostHealthRegistryFixes {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Policy
    )

    $contentPath = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager'
    foreach ($valueName in @(
        'SilentInstalledAppsEnabled',
        'SubscribedContent-338388Enabled',
        'SubscribedContent-338389Enabled',
        'SubscribedContent-353698Enabled',
        'SystemPaneSuggestionsEnabled'
    )) {
        Set-BootstrapRegistryDword -State $State -Path $contentPath -Name $valueName -Value 0
    }

    $edgePolicyPath = 'HKCU:\Software\Policies\Microsoft\Edge'
    Set-BootstrapRegistryDword -State $State -Path $edgePolicyPath -Name 'StartupBoostEnabled' -Value 0
    Set-BootstrapRegistryDword -State $State -Path $edgePolicyPath -Name 'BackgroundModeEnabled' -Value 0

    $explorerAdvancedPath = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced'
    Set-BootstrapRegistryDword -State $State -Path $explorerAdvancedPath -Name 'TaskbarDa' -Value 0

    $gameBarPath = 'HKCU:\Software\Microsoft\GameBar'
    Set-BootstrapRegistryDword -State $State -Path $gameBarPath -Name 'AutoGameModeEnabled' -Value 1
}

function Sync-BootstrapSteamDeckHostHealthSettings {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Policy
    )

    $settingsPath = Ensure-BootstrapSteamDeckSettings -State $State
    $settings = Get-Content -Path $settingsPath -Raw | ConvertFrom-Json -ErrorAction Stop
    $settingsData = Normalize-BootstrapSteamDeckSettingsData -Settings $settings
    $settingsData['sessionProfiles'] = ConvertTo-BootstrapHashtable -InputObject $Policy.SessionProfiles
    $settingsData['hostHealth'] = @{
        mode = $Policy.Mode
        killInGame = @($Policy.KillInGame)
        keepAlways = @($Policy.KeepAlways)
    }
    Write-BootstrapJsonFile -Path $settingsPath -Value $settingsData
    $State.SteamDeckSettingsPath = $settingsPath
}

function Invoke-BootstrapHostHealthGameMode {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Policy
    )

    if ($State.UsesSteamDeckFlow) {
        Sync-BootstrapSteamDeckHostHealthSettings -State $State -Policy $Policy
        Write-Log "HostHealth game-mode: session profiles atualizados para o watcher do Steam Deck ($($Policy.Mode))."
    } else {
        Write-Log 'HostHealth game-mode: nenhum watcher Steam Deck ativo neste fluxo; somente politica do host foi registrada.'
    }
}

function Invoke-BootstrapHostHealthBloat {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Policy
    )

    foreach ($packageName in @($Policy.AppxRemove)) {
        try {
            $packages = @(Get-AppxPackage -Name $packageName -ErrorAction SilentlyContinue)
            if ($packages.Count -eq 0) {
                Write-Log "HostHealth bloat: pacote nao presente -> $packageName"
                continue
            }

            foreach ($package in $packages) {
                Remove-AppxPackage -Package $package.PackageFullName -ErrorAction Stop
                Write-Log "HostHealth bloat: pacote removido do usuario atual -> $packageName"
            }
        } catch {
            Write-Log "HostHealth bloat: falha ao remover $packageName do usuario atual." 'WARN'
        }
    }
}

function Invoke-BootstrapHostHealthTelemetry {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Policy
    )

    $telemetry = ConvertTo-BootstrapHashtable -InputObject $Policy.Telemetry
    if (-not ($telemetry -is [hashtable]) -or [string]$telemetry['mode'] -ne 'opt-in-agressivo') {
        Write-Log 'HostHealth telemetry: modo nao agressivo, nenhuma ação.'
        return
    }
    if (-not (Test-IsAdmin)) {
        Write-Log 'HostHealth telemetry: requer admin para ajustes reversíveis. Pulando.' 'WARN'
        return
    }

    $reportRoot = Get-BootstrapHostHealthReportRoot -State $State
    $changes = @()
    foreach ($adjustment in @($telemetry['serviceAdjustments'])) {
        try {
            $service = Get-Service -Name ([string]$adjustment['Name']) -ErrorAction Stop
            $changes += @([ordered]@{ type = 'service'; name = [string]$adjustment['Name']; previousStartType = [string]$service.StartType })
            Set-Service -Name ([string]$adjustment['Name']) -StartupType ([string]$adjustment['StartType']) -ErrorAction Stop
            Write-Log "HostHealth telemetry: serviço ajustado -> $([string]$adjustment['Name'])"
        } catch {
            Write-Log "HostHealth telemetry: falha serviço $([string]$adjustment['Name']) => $($_.Exception.Message)" 'WARN'
        }
    }
    foreach ($taskDef in @($telemetry['scheduledTasksDisable'])) {
        try {
            $task = Get-ScheduledTask -TaskPath ([string]$taskDef['TaskPath']) -TaskName ([string]$taskDef['TaskName']) -ErrorAction Stop
            $changes += @([ordered]@{ type = 'task'; taskPath = [string]$taskDef['TaskPath']; taskName = [string]$taskDef['TaskName']; previousState = [string]$task.State })
            Disable-ScheduledTask -InputObject $task -ErrorAction Stop | Out-Null
            Write-Log "HostHealth telemetry: tarefa desabilitada -> $([string]$taskDef['TaskPath'])$([string]$taskDef['TaskName'])"
        } catch {
            Write-Log "HostHealth telemetry: falha tarefa $([string]$taskDef['TaskPath'])$([string]$taskDef['TaskName']) => $($_.Exception.Message)" 'WARN'
        }
    }

    Write-BootstrapJsonFile -Path (Join-Path $reportRoot 'telemetry-changes.json') -Value ([ordered]@{
        generatedAt = (Get-Date).ToString('o')
        reversible = $true
        changes = @($changes)
    })
}

function Invoke-BootstrapHostHealthVerify {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Policy
    )

    $reportRoot = Get-BootstrapHostHealthReportRoot -State $State
    $summary = [ordered]@{
        mode = $Policy.Mode
        reportRoot = $reportRoot
        generatedAt = (Get-Date).ToString('o')
        host = $env:COMPUTERNAME
        user = $env:USERNAME
        usesSteamDeckFlow = $State.UsesSteamDeckFlow
    }
    Write-BootstrapJsonFile -Path (Join-Path $reportRoot 'summary.json') -Value $summary
}

function Invoke-BootstrapHostHealth {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][string]$Mode
    )

    $normalizedMode = Normalize-BootstrapHostHealthMode -Mode $Mode
    if ($normalizedMode -eq 'off') {
        Write-Log 'HostHealth: desligado para esta execucao.'
        return
    }

    $policy = Get-BootstrapHostHealthPolicy -Mode $normalizedMode
    Export-BootstrapHostHealthSnapshots -State $State -Policy $policy
    Invoke-BootstrapHostHealthCleanup -State $State -Policy $policy
    Invoke-BootstrapHostHealthStartup -State $State -Policy $policy
    Invoke-BootstrapHostHealthRegistryFixes -State $State -Policy $policy
    Invoke-BootstrapHostHealthGameMode -State $State -Policy $policy
    Invoke-BootstrapHostHealthBloat -State $State -Policy $policy
    Invoke-BootstrapHostHealthTelemetry -State $State -Policy $policy
    Invoke-BootstrapHostHealthVerify -State $State -Policy $policy

    $State.HostHealthResults.Add([ordered]@{
        mode = $normalizedMode
        status = 'completed'
        timestamp = (Get-Date).ToString('o')
    })
}

function Get-BootstrapAppTuningReportRoot {
    param([Parameter(Mandatory = $true)][hashtable]$State)

    if (-not $State.AppTuningReportRoot) {
        $State.AppTuningReportRoot = Get-BootstrapAppTuningRoot
    }
    $null = New-Item -Path $State.AppTuningReportRoot -ItemType Directory -Force
    return $State.AppTuningReportRoot
}

function New-BootstrapAppTuningSnapshot {
    param([Parameter(Mandatory = $true)]$Plan)

    return [ordered]@{
        generatedAt = (Get-Date).ToString('o')
        mode = [string]$Plan.mode
        categories = @($Plan.categories)
        requestedCategories = @($Plan.requestedCategories)
        requestedItems = @($Plan.requestedItems)
        excludedItems = @($Plan.excludedItems)
        items = @($Plan.items)
        skippedItems = @($Plan.skippedItems)
        installedInventory = $Plan.installedInventory
    }
}

function Apply-BootstrapRegistryDword {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$Name,
        [Parameter(Mandatory = $true)][int]$Value
    )

    $previous = $null
    try {
        if (Test-Path $Path) {
            $current = Get-ItemProperty -Path $Path -Name $Name -ErrorAction SilentlyContinue
            if ($current -and ($current.PSObject.Properties.Name -contains $Name)) {
                $previous = $current.$Name
            }
        } else {
            $parent = Split-Path $Path -Parent
            if (-not (Test-Path $parent)) {
                # Tentar criar recursivamente se possivel, mas sem -Force no alvo
                $null = New-Item -Path $parent -ItemType Directory -Force -ErrorAction SilentlyContinue
            }
            $null = New-Item -Path $Path -ErrorAction SilentlyContinue
        }

        Register-BootstrapChange -State $State -Type 'Registry' -Target $Path -Name $Name -OldValue $previous

        if (Test-Path $Path) {
            Set-ItemProperty -Path $Path -Name $Name -Value $Value -Type DWord -Force | Out-Null
        } else {
            # Fallback se New-Item falhou silenciosamente
            New-ItemProperty -Path $Path -Name $Name -Value $Value -PropertyType DWord -Force | Out-Null
        }

        return [ordered]@{ path = $Path; name = $Name; previous = $previous; value = $Value; status = 'applied' }
    } catch {
        return [ordered]@{ path = $Path; name = $Name; previous = $previous; value = $Value; status = 'failed'; error = $_.Exception.Message }
    }
}

function Get-BootstrapServiceSnapshot {
    param([Parameter(Mandatory = $true)][string]$Name)

    try {
        $service = Get-Service -Name $Name -ErrorAction Stop
        return [ordered]@{
            Name = $Name
            StartType = [string]$service.StartType
            Status = [string]$service.Status
            Exists = $true
        }
    } catch {
        return [ordered]@{
            Name = $Name
            StartType = ''
            Status = ''
            Exists = $false
            Error = $_.Exception.Message
        }
    }
}

function Set-BootstrapServiceTuning {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$ServiceAdjustments,
        [switch]$StopService
    )

    $results = @()
    if (-not (Test-IsAdmin)) {
        foreach ($adjustment in @($ServiceAdjustments)) {
            $results += @([ordered]@{ name = [string]$adjustment.Name; status = 'skipped'; reason = 'admin-required'; blocking = $false })
        }
        return @($results)
    }

    foreach ($adjustment in @($ServiceAdjustments)) {
        if (-not $adjustment) { continue }
        $name = [string]$adjustment.Name
        $startType = [string]$adjustment.StartType
        if ([string]::IsNullOrWhiteSpace($name) -or [string]::IsNullOrWhiteSpace($startType)) { continue }
        $snapshot = Get-BootstrapServiceSnapshot -Name $name
        if (-not [bool]$snapshot.Exists) {
            $results += @([ordered]@{ name = $name; status = 'skipped'; reason = 'service-not-found'; blocking = $false; snapshot = $snapshot })
            continue
        }

        try {
            Register-BootstrapChange -State $State -Type 'Service' -Target $name -Name 'StartupType' -OldValue $snapshot -NewValue $startType -Operation 'service-startup' -RollbackAction 'restore-service-state' -Reversible 'partial'
            if ($StopService -and [string]$snapshot.Status -eq 'Running') {
                Stop-Service -Name $name -ErrorAction SilentlyContinue
            }
            Set-Service -Name $name -StartupType $startType -ErrorAction Stop
            $results += @([ordered]@{ name = $name; status = 'applied'; startType = $startType; stopped = [bool]$StopService; snapshot = $snapshot })
        } catch {
            $results += @([ordered]@{ name = $name; status = 'failed'; startType = $startType; error = $_.Exception.Message; blocking = $false; snapshot = $snapshot })
        }
    }

    return @($results)
}

function Add-BootstrapDefenderExclusion {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][ValidateSet('ExclusionPath','ExclusionProcess')][string]$Kind,
        [Parameter(Mandatory = $true)][string]$Value
    )

    if ([string]::IsNullOrWhiteSpace($Value)) {
        return [ordered]@{ kind = $Kind; value = ''; status = 'skipped'; reason = 'empty-value'; blocking = $false }
    }
    if (-not (Test-IsAdmin)) {
        return [ordered]@{ kind = $Kind; value = $Value; status = 'skipped'; reason = 'admin-required'; blocking = $false }
    }

    $resolved = [string]$Value
    try {
        $resolved = [System.IO.Path]::GetFullPath([Environment]::ExpandEnvironmentVariables($Value))
    } catch {
        $resolved = [Environment]::ExpandEnvironmentVariables($Value)
    }

    try {
        $pref = Get-MpPreference -ErrorAction SilentlyContinue
        $existing = @()
        if ($pref -and $pref.PSObject.Properties[$Kind]) { $existing = @($pref.$Kind) }
        if (@($existing | ForEach-Object { [string]$_ }).Contains($resolved)) {
            return [ordered]@{ kind = $Kind; value = $resolved; status = 'configured'; reason = 'already-present'; blocking = $false }
        }

        Register-BootstrapChange -State $State -Type 'DefenderExclusion' -Target $resolved -Name $Kind -OldValue $null -NewValue $resolved -Operation 'defender-exclusion-add' -RollbackAction 'remove-defender-exclusion' -Reversible 'partial'
        if ($Kind -eq 'ExclusionProcess') {
            Add-MpPreference -ExclusionProcess $resolved -ErrorAction Stop
        } else {
            Add-MpPreference -ExclusionPath $resolved -ErrorAction Stop
        }
        return [ordered]@{ kind = $Kind; value = $resolved; status = 'applied'; blocking = $false }
    } catch {
        return [ordered]@{ kind = $Kind; value = $resolved; status = 'failed'; error = $_.Exception.Message; blocking = $false }
    }
}

function Set-BootstrapDockerHighPriority {
    $processes = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match '^(Docker Desktop|Docker|com\.docker|vpnkit|dockerd)$' })
    if ($processes.Count -eq 0) {
        return [ordered]@{ status = 'skipped'; reason = 'docker-process-not-running'; changed = @(); failed = @(); blocking = $false }
    }

    $changed = @()
    $failed = @()
    foreach ($proc in @($processes)) {
        try {
            $proc.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::High
            $changed += @([ordered]@{ id = $proc.Id; processName = $proc.ProcessName; priority = 'High' })
        } catch {
            $failed += @([ordered]@{ id = $proc.Id; processName = $proc.ProcessName; error = $_.Exception.Message })
        }
    }
    return [ordered]@{
        status = if ($changed.Count -gt 0) { 'applied' } elseif ($failed.Count -gt 0) { 'partial' } else { 'skipped' }
        changed = @($changed)
        failed = @($failed)
        blocking = $false
    }
}

function Get-BootstrapAiAgentPerformanceAudit {
    function Get-OptionalPropertyString {
        param(
            [AllowNull()]$Object,
            [Parameter(Mandatory = $true)][string]$Name
        )
        if ($null -eq $Object) { return '' }
        $propertyNames = @($Object.PSObject.Properties | ForEach-Object { [string]$_.Name })
        if ($propertyNames -notcontains $Name) { return '' }
        return [string]$Object.$Name
    }

    $services = @()
    foreach ($name in @('DiagTrack','dmwappushservice','WSearch','SysMain')) {
        $services += @(Get-BootstrapServiceSnapshot -Name $name)
    }

    $defender = [ordered]@{ available = $false; exclusionPath = @(); exclusionProcess = @(); error = ''; timedOut = $false }
    $defenderProbe = Invoke-BootstrapScriptBlockWithTimeout -Name 'Get-MpPreference' -TimeoutSeconds 5 -ScriptBlock {
        $pref = Get-MpPreference -ErrorAction Stop
        return [ordered]@{
            available = $true
            exclusionPath = @($pref.ExclusionPath)
            exclusionProcess = @($pref.ExclusionProcess)
        }
    }
    if ([bool]$defenderProbe.timedOut) {
        $defender.error = 'Get-MpPreference timeout'
        $defender.timedOut = $true
    } elseif ([string]$defenderProbe.status -eq 'ok') {
        $value = ConvertTo-BootstrapHashtable -InputObject $defenderProbe.value
        $defender.available = [bool]$value['available']
        $defender.exclusionPath = @($value['exclusionPath'])
        $defender.exclusionProcess = @($value['exclusionProcess'])
    } else {
        $defender.error = [string]$defenderProbe.error
    }

    $smartScreen = Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\AppHost' -ErrorAction SilentlyContinue
    $deviceGuard = Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard' -ErrorAction SilentlyContinue
    $visual = Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' -ErrorAction SilentlyContinue
    $delivery = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization' -ErrorAction SilentlyContinue

    return [ordered]@{
        generatedAt = (Get-Date).ToString('o')
        services = @($services)
        defender = $defender
        smartScreen = [ordered]@{ enabledV2 = Get-OptionalPropertyString -Object $smartScreen -Name 'EnableWebContentEvaluation' }
        deviceGuard = [ordered]@{ enableVirtualizationBasedSecurity = Get-OptionalPropertyString -Object $deviceGuard -Name 'EnableVirtualizationBasedSecurity' }
        visualEffects = [ordered]@{ visualFxSetting = Get-OptionalPropertyString -Object $visual -Name 'VisualFXSetting' }
        deliveryOptimization = [ordered]@{ doDownloadMode = Get-OptionalPropertyString -Object $delivery -Name 'DODownloadMode' }
        dockerProcesses = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match '^(Docker Desktop|Docker|com\.docker|vpnkit|dockerd)$' } | Select-Object Id, ProcessName, PriorityClass)
    }
}

function Export-BootstrapAiAgentPerformanceAuditReport {
    param([Parameter(Mandatory = $true)][hashtable]$State)

    $reportRoot = Get-BootstrapAppTuningReportRoot -State $State
    $path = Join-Path $reportRoot 'ai-agent-performance-audit.json'
    Write-BootstrapJsonFile -Path $path -Value (Get-BootstrapAiAgentPerformanceAudit)
    return $path
}

function Apply-AiAgentPerformanceTuning {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Item
    )

    switch ([string]$Item.id) {
        'windows-ai-visual-performance' {
            $changes = @(
                (Apply-BootstrapRegistryDword -State $State -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' -Name 'VisualFXSetting' -Value 2),
                (Apply-BootstrapRegistryDword -State $State -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' -Name 'EnableTransparency' -Value 0)
            )
            $failed = @($changes | Where-Object { [string]$_['status'] -eq 'failed' })
            return [ordered]@{ id = [string]$Item.id; status = if ($failed.Count -gt 0) { 'partial' } else { 'applied' }; changes = @($changes); blocking = $false }
        }
        'windows-ai-delivery-optimization-http-only' {
            if (-not (Test-IsAdmin)) {
                return [ordered]@{ id = [string]$Item.id; status = 'skipped'; reason = 'admin-required'; blocking = $false }
            }
            $change = Apply-BootstrapRegistryDword -State $State -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization' -Name 'DODownloadMode' -Value 0
            return [ordered]@{ id = [string]$Item.id; status = [string]$change.status; change = $change; blocking = $false }
        }
        'windows-ai-docker-high-priority' {
            $result = Set-BootstrapDockerHighPriority
            $result['id'] = [string]$Item.id
            return $result
        }
        'windows-ai-security-posture-audit' {
            $path = Export-BootstrapAiAgentPerformanceAuditReport -State $State
            return [ordered]@{ id = [string]$Item.id; status = 'audited'; report = $path; blocking = $false }
        }
        'windows-ai-workspace-defender-exclusion' {
            $targets = @([string]$State.WorkspaceRoot, [string]$State.CloneBaseDir) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique
            $results = @()
            foreach ($target in @($targets)) {
                $results += @(Add-BootstrapDefenderExclusion -State $State -Kind 'ExclusionPath' -Value $target)
            }
            return [ordered]@{ id = [string]$Item.id; status = if (@($results | Where-Object { [string]$_['status'] -eq 'applied' }).Count -gt 0) { 'applied' } else { 'skipped' }; results = @($results); blocking = $false }
        }
        'windows-ai-node-python-defender-process-exclusion' {
            $paths = @()
            foreach ($cmd in @('node','python','python3')) {
                $p = Resolve-CommandPath -Name $cmd
                if (-not [string]::IsNullOrWhiteSpace($p) -and -not (@($paths) -contains $p)) { $paths += @($p) }
            }
            $results = @()
            foreach ($path in @($paths)) {
                $results += @(Add-BootstrapDefenderExclusion -State $State -Kind 'ExclusionProcess' -Value $path)
            }
            return [ordered]@{ id = [string]$Item.id; status = if (@($results | Where-Object { [string]$_['status'] -eq 'applied' }).Count -gt 0) { 'applied' } else { 'skipped' }; results = @($results); blocking = $false }
        }
        'windows-ai-services-deep-tuning' {
            $services = @(
                [ordered]@{ Name = 'DiagTrack'; StartType = 'Disabled' },
                [ordered]@{ Name = 'dmwappushservice'; StartType = 'Disabled' },
                [ordered]@{ Name = 'WSearch'; StartType = 'Disabled' },
                [ordered]@{ Name = 'SysMain'; StartType = 'Disabled' }
            )
            $results = Set-BootstrapServiceTuning -State $State -ServiceAdjustments $services -StopService
            return [ordered]@{ id = [string]$Item.id; status = if (@($results | Where-Object { [string]$_['status'] -eq 'applied' }).Count -gt 0) { 'applied' } else { 'skipped' }; results = @($results); blocking = $false }
        }
        default {
            return [ordered]@{ id = [string]$Item.id; status = 'audited'; note = 'AI agent performance item audit-only.'; blocking = $false }
        }
    }
}

function Apply-BrowserStartupTuning {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Item
    )

    $changes = @()
    switch ([string]$Item.id) {
        'edge-background-off' {
            $changes += @(Apply-BootstrapRegistryDword -State $State -Path 'HKCU:\Software\Policies\Microsoft\Edge' -Name 'StartupBoostEnabled' -Value 0)
            $changes += @(Apply-BootstrapRegistryDword -State $State -Path 'HKCU:\Software\Policies\Microsoft\Edge' -Name 'BackgroundModeEnabled' -Value 0)
        }
        'chrome-background-off' {
            $changes += @(Apply-BootstrapRegistryDword -State $State -Path 'HKCU:\Software\Policies\Google\Chrome' -Name 'BackgroundModeEnabled' -Value 0)
        }
    }

    $failed = @($changes | Where-Object { [string]$_.status -eq 'failed' })
    $isRecoverableError = $false
    $errorMsg = ''
    if ($failed.Count -gt 0) {
        $errorMsg = [string]$failed[0].error
        $isRecoverableError = Test-BootstrapAppTuningRecoverableError -Message $errorMsg -ExceptionType ''
    }
    $hasFailure = ($failed.Count -gt 0)
    $hasBlockingFailure = ($hasFailure -and -not $isRecoverableError)

    $result = [ordered]@{
        id = [string]$Item.id
        status = if ($hasFailure) { 'failed' } else { 'applied' }
        changes = @($changes)
        blocking = $hasBlockingFailure
        error = $errorMsg
    }
    if ($hasFailure -and $isRecoverableError) {
        $result['severity'] = 'warning'
        $result['classification'] = 'permission-denied'
    } elseif ($hasFailure) {
        $result['severity'] = 'blocking'
        $result['classification'] = 'execution-failure'
    }
    return $result
}

function Ensure-BootstrapPlayniteFullscreenConfig {
    $configPath = Join-BootstrapKnownFolderPath -Base $env:APPDATA -ChildPath 'Playnite\config.json'
    if ([string]::IsNullOrWhiteSpace($configPath) -or -not (Test-Path $configPath)) {
        return [ordered]@{ status = 'skipped'; note = "Playnite config ausente: $configPath" }
    }

    try {
        $raw = Get-Content -Path $configPath -Raw -Encoding utf8
        $config = ConvertTo-BootstrapHashtable -InputObject ($raw | ConvertFrom-Json -ErrorAction Stop)
    } catch {
        throw "Falha ao ler config do Playnite em $configPath. Valide JSON/schema. Erro: $($_.Exception.Message)"
    }

    if (-not (($config.ContainsKey('StartInFullscreen') -or $config.ContainsKey('StartFullScreen') -or $config.ContainsKey('StartInFullScreen')))) {
        throw "Schema Playnite inesperado em $configPath. Campos fullscreen nao encontrados (StartInFullscreen/StartFullScreen/StartInFullScreen)."
    }

    $backup = Backup-BootstrapFile -Path $configPath
    if ($config.ContainsKey('StartInFullscreen')) { $config['StartInFullscreen'] = $true }
    if ($config.ContainsKey('StartFullScreen')) { $config['StartFullScreen'] = $true }
    if ($config.ContainsKey('StartInFullScreen')) { $config['StartInFullScreen'] = $true }
    Write-BootstrapJsonFile -Path $configPath -Value $config

    return [ordered]@{
        status = 'applied'
        note = 'Playnite configurado para fullscreen com backup.'
        path = $configPath
        backup = $backup
    }
}

function Ensure-BootstrapRtssLowOverlayProfile {
    $profilePath = "${env:ProgramFiles(x86)}\RivaTuner Statistics Server\Profiles\Global"
    if (-not (Test-Path $profilePath)) {
        return [ordered]@{ status = 'skipped'; note = "RTSS profile ausente: $profilePath" }
    }
    $backup = Backup-BootstrapFile -Path $profilePath
    $content = @(
        '[Framerate]',
        'Limit=60',
        '[OSD]',
        'ShowOSD=1',
        'ShowFramerate=1',
        'ShowFrametime=0',
        'ShowMemory=0',
        'Raster3D=0'
    ) -join [Environment]::NewLine
    try {
        [System.IO.File]::WriteAllText($profilePath, $content, (New-Object System.Text.UTF8Encoding($false)))
    } catch {
        return [ordered]@{ status = 'failed'; note = "Falha escrita RTSS profile: $($_.Exception.Message)"; path = $profilePath; backup = $backup }
    }
    return [ordered]@{ status = 'applied'; note = 'RTSS low overlay aplicado.'; path = $profilePath; backup = $backup }
}

function Ensure-BootstrapAfterburnerLowOverlayProfile {
    $candidates = @(
        "${env:ProgramFiles(x86)}\MSI Afterburner\Profiles\MSIAfterburner.cfg",
        "${env:ProgramFiles}\MSI Afterburner\Profiles\MSIAfterburner.cfg"
    )
    $targetPath = [string]($candidates | Where-Object { Test-Path $_ } | Select-Object -First 1)
    if ([string]::IsNullOrWhiteSpace($targetPath)) {
        return [ordered]@{ status = 'skipped'; note = 'Afterburner profile ausente; ajuste nao fatal.' }
    }
    $backup = Backup-BootstrapFile -Path $targetPath
    $content = @(
        '[Settings]',
        'EnableOSD=1',
        'OSDGraphs=0',
        'OSDCoordinateSpace=0',
        'ShowHardwareInfo=0'
    ) -join [Environment]::NewLine
    try {
        [System.IO.File]::WriteAllText($targetPath, $content, (New-Object System.Text.UTF8Encoding($false)))
    } catch {
        return [ordered]@{ status = 'failed'; note = "Falha escrita Afterburner profile: $($_.Exception.Message)"; path = $targetPath; backup = $backup }
    }
    return [ordered]@{ status = 'applied'; note = 'Afterburner low overlay aplicado.'; path = $targetPath; backup = $backup }
}

function Apply-SteamConsoleTuning {
    param([Parameter(Mandatory = $true)]$Item)

    if ([string]$Item.id -eq 'rtss-frame-presets') {
        $rtss = Ensure-BootstrapRtssLowOverlayProfile
        $afterburner = Ensure-BootstrapAfterburnerLowOverlayProfile
        $failed = @($rtss, $afterburner | Where-Object { [string]$_.status -eq 'failed' })
        return [ordered]@{
            id = [string]$Item.id
            status = if ($failed.Count -gt 0) { 'failed' } elseif ((@($rtss, $afterburner | Where-Object { [string]$_.status -eq 'applied' }).Count -gt 0)) { 'applied' } else { 'skipped' }
            note = 'Perfis low overlay avaliados para RTSS/Afterburner.'
            rtss = $rtss
            afterburner = $afterburner
        }
    }

    return [ordered]@{ id = [string]$Item.id; status = 'prepared'; note = 'Session policy prepared; Steam never forced as admin.' }
}

function Apply-PlayniteTuning {
    param([Parameter(Mandatory = $true)]$Item)
    $result = Ensure-BootstrapPlayniteFullscreenConfig
    return [ordered]@{
        id = [string]$Item.id
        status = [string]$result.status
        note = [string]$result.note
        details = $result
    }
}

function Resolve-BootstrapOpenAiCompatibleProviderCandidate {
    param(
        [string[]]$PreferredProviders = @('mimo', 'openrouter', 'openai', 'moonshot', 'deepseek', 'xai'),
        [AllowNull()]$SecretsData = $null
    )

    $secretsInput = if ($null -ne $SecretsData) { $SecretsData } else { (Get-BootstrapSecretsData).Data }
    $normalized = Normalize-BootstrapSecretsData -Secrets $secretsInput
    $catalog = Get-BootstrapSecretsProviderCatalog
    $activeProvidersValidated = Get-BootstrapActiveProviders -SecretsData $normalized -RequirePassedValidation
    $activeProviders = Get-BootstrapActiveProviders -SecretsData $normalized
    $attempts = New-Object System.Collections.Generic.List[object]

    foreach ($providerName in @($PreferredProviders)) {
        if ([string]::IsNullOrWhiteSpace($providerName)) { continue }
        $normalizedProviderName = $providerName.Trim().ToLowerInvariant()
        $stage = if ($activeProvidersValidated.Contains($normalizedProviderName)) { 'validated-active' } else { 'active-fallback' }

        if (-not $normalized.providers.Contains($normalizedProviderName)) {
            $attempts.Add([ordered]@{
                provider = $normalizedProviderName
                stage = $stage
                selected = $false
                reason = 'provider-not-configured'
                validationState = 'missing'
                credentialId = ''
                hasSecret = $false
                hasBaseUrl = $false
            })
            continue
        }

        $provider = ConvertTo-BootstrapHashtable -InputObject $normalized.providers[$normalizedProviderName]
        $activeCredentialId = [string]$provider['activeCredential']
        if ([string]::IsNullOrWhiteSpace($activeCredentialId)) {
            $attempts.Add([ordered]@{
                provider = $normalizedProviderName
                stage = $stage
                selected = $false
                reason = 'active-credential-missing'
                validationState = 'missing'
                credentialId = ''
                hasSecret = $false
                hasBaseUrl = $false
            })
            continue
        }
        if (-not ($provider.ContainsKey('credentials') -and ($provider['credentials'] -is [hashtable]) -and $provider['credentials'].Contains($activeCredentialId))) {
            $attempts.Add([ordered]@{
                provider = $normalizedProviderName
                stage = $stage
                selected = $false
                reason = 'active-credential-not-found'
                validationState = 'missing'
                credentialId = $activeCredentialId
                hasSecret = $false
                hasBaseUrl = $false
            })
            continue
        }

        $credential = ConvertTo-BootstrapHashtable -InputObject $provider['credentials'][$activeCredentialId]
        $validationState = if ($credential.ContainsKey('validation') -and ($credential['validation'] -is [hashtable])) { [string]$credential['validation']['state'] } else { 'unknown' }
        if ($validationState -match '^(failed|invalid|revoked|disabled)$') {
            $attempts.Add([ordered]@{
                provider = $normalizedProviderName
                stage = $stage
                selected = $false
                reason = 'validation-failed'
                validationState = $validationState
                credentialId = $activeCredentialId
                hasSecret = (-not [string]::IsNullOrWhiteSpace([string]$credential['secret']))
                hasBaseUrl = $true
            })
            continue
        }
        if ($stage -eq 'active-fallback' -and $validationState -eq 'passed') {
            $stage = 'active-validated'
        }

        $providerActive = if ($activeProviders.Contains($normalizedProviderName)) { ConvertTo-BootstrapHashtable -InputObject $activeProviders[$normalizedProviderName] } else { @{} }
        $providerActiveValidated = if ($activeProvidersValidated.Contains($normalizedProviderName)) { ConvertTo-BootstrapHashtable -InputObject $activeProvidersValidated[$normalizedProviderName] } else { @{} }
        $selectedProviderState = if ($stage -eq 'validated-active') { $providerActiveValidated } else { $providerActive }

        $apiKey = ''
        if ($selectedProviderState.ContainsKey('apiKey')) { $apiKey = [string]$selectedProviderState['apiKey'] }
        if ([string]::IsNullOrWhiteSpace($apiKey) -and $selectedProviderState.ContainsKey('token')) { $apiKey = [string]$selectedProviderState['token'] }
        if ([string]::IsNullOrWhiteSpace($apiKey) -and $selectedProviderState.ContainsKey('secret')) { $apiKey = [string]$selectedProviderState['secret'] }
        if ([string]::IsNullOrWhiteSpace($apiKey)) {
            $apiKey = [string]$credential['secret']
        }

        $baseUrl = ''
        if ($selectedProviderState.ContainsKey('baseUrl')) { $baseUrl = [string]$selectedProviderState['baseUrl'] }
        if ([string]::IsNullOrWhiteSpace($baseUrl) -and $selectedProviderState.ContainsKey('baseURL')) { $baseUrl = [string]$selectedProviderState['baseURL'] }
        if ([string]::IsNullOrWhiteSpace($baseUrl) -and $credential.ContainsKey('baseUrl')) { $baseUrl = [string]$credential['baseUrl'] }
        if ([string]::IsNullOrWhiteSpace($baseUrl) -and $provider.ContainsKey('defaults') -and ($provider['defaults'] -is [hashtable])) { $baseUrl = [string]$provider['defaults']['baseUrl'] }
        if ([string]::IsNullOrWhiteSpace($baseUrl) -and $catalog.Contains($normalizedProviderName)) {
            $providerMeta = ConvertTo-BootstrapHashtable -InputObject $catalog[$normalizedProviderName]
            if ($providerMeta.ContainsKey('defaults') -and ($providerMeta['defaults'] -is [hashtable])) {
                $baseUrl = [string]$providerMeta['defaults']['baseUrl']
            }
        }
        if ([string]::IsNullOrWhiteSpace($baseUrl) -and [string]::Equals([string]$normalizedProviderName, 'openai', [System.StringComparison]::OrdinalIgnoreCase)) {
            $baseUrl = 'https://api.openai.com/v1'
        }

        if ([string]::IsNullOrWhiteSpace($apiKey)) {
            $attempts.Add([ordered]@{
                provider = $normalizedProviderName
                stage = $stage
                selected = $false
                reason = 'secret-missing'
                validationState = $validationState
                credentialId = $activeCredentialId
                hasSecret = $false
                hasBaseUrl = (-not [string]::IsNullOrWhiteSpace($baseUrl))
            })
            continue
        }
        if ([string]::IsNullOrWhiteSpace($baseUrl)) {
            $attempts.Add([ordered]@{
                provider = $normalizedProviderName
                stage = $stage
                selected = $false
                reason = 'baseurl-missing'
                validationState = $validationState
                credentialId = $activeCredentialId
                hasSecret = $true
                hasBaseUrl = $false
            })
            continue
        }

        $attempts.Add([ordered]@{
            provider = $normalizedProviderName
            stage = $stage
            selected = $true
            reason = 'selected'
            validationState = $validationState
            credentialId = $activeCredentialId
            hasSecret = $true
            hasBaseUrl = $true
        })
        return [ordered]@{
            status = 'selected'
            provider = $normalizedProviderName
            apiKey = $apiKey
            baseUrl = $baseUrl
            stage = $stage
            attempts = @($attempts.ToArray())
        }
    }

    return [ordered]@{
        status = 'no-compatible-provider'
        provider = ''
        apiKey = ''
        baseUrl = ''
        stage = 'none'
        attempts = @($attempts.ToArray())
    }
}

function Ensure-BootstrapOpenAiCompatibleUserEnv {
    param([string[]]$PreferredProviders = @('mimo', 'openrouter', 'openai', 'moonshot', 'deepseek', 'xai'))

    $candidate = ConvertTo-BootstrapHashtable -InputObject (Resolve-BootstrapOpenAiCompatibleProviderCandidate -PreferredProviders $PreferredProviders)
    if (-not ($candidate -is [hashtable]) -or [string]$candidate['status'] -ne 'selected') {
        foreach ($attempt in @(if ($candidate -and (Test-BootstrapMapContainsKey -Map $candidate -Key 'attempts')) { $candidate['attempts'] } else { @() })) {
            $attemptMap = ConvertTo-BootstrapHashtable -InputObject $attempt
            Write-Log ("OpenAI-compatible tentativa: provider={0}, stage={1}, selected={2}, reason={3}, validation={4}" -f [string]$attemptMap['provider'], [string]$attemptMap['stage'], [string]$attemptMap['selected'], [string]$attemptMap['reason'], [string]$attemptMap['validationState']) 'WARN'
        }
        return [ordered]@{
            status = 'skipped'
            reason = 'no-openai-compatible-provider'
            provider = ''
            baseUrl = ''
            stage = 'none'
            updated = @()
            skipped = @()
            warnings = @('Nenhum provider OpenAI-compatible ativo e utilizável foi encontrado.')
            attempts = if ($candidate -and (Test-BootstrapMapContainsKey -Map $candidate -Key 'attempts')) { @($candidate['attempts']) } else { @() }
        }
    }

    $updated = @()
    $skipped = @()
    $warnings = @()
    $providerName = [string]$candidate['provider']
    $apiKey = [string]$candidate['apiKey']
    $baseUrl = [string]$candidate['baseUrl']

    $currentOpenAiKey = [Environment]::GetEnvironmentVariable('OPENAI_API_KEY', 'User')
    if ([string]::IsNullOrWhiteSpace($currentOpenAiKey)) {
        Set-UserEnvVar -Name 'OPENAI_API_KEY' -Value $apiKey
        $updated += @('OPENAI_API_KEY')
    } elseif ($currentOpenAiKey -eq $apiKey) {
        $skipped += @('OPENAI_API_KEY')
    } else {
        $skipped += @('OPENAI_API_KEY')
        $warnings += @("OPENAI_API_KEY já definido no usuário com valor diferente; ajuste manual necessario para usar o provider '$providerName'.")
    }

    $currentOpenAiBaseUrl = [Environment]::GetEnvironmentVariable('OPENAI_BASE_URL', 'User')
    if ([string]::IsNullOrWhiteSpace($currentOpenAiBaseUrl)) {
        Set-UserEnvVar -Name 'OPENAI_BASE_URL' -Value $baseUrl
        $updated += @('OPENAI_BASE_URL')
    } elseif ($currentOpenAiBaseUrl -eq $baseUrl) {
        $skipped += @('OPENAI_BASE_URL')
    } else {
        $skipped += @('OPENAI_BASE_URL')
        $warnings += @("OPENAI_BASE_URL já definido no usuário com valor diferente ($currentOpenAiBaseUrl); ajuste manual necessario para usar $baseUrl.")
    }

    $finalOpenAiKey = [Environment]::GetEnvironmentVariable('OPENAI_API_KEY', 'User')
    if (-not [string]::IsNullOrWhiteSpace($finalOpenAiKey)) {
        Set-UserEnvVar -Name 'CLAUDE_CODE_USE_OPENAI' -Value '1'
        $updated += @('CLAUDE_CODE_USE_OPENAI')
    }

    foreach ($warning in @($warnings)) {
        Write-Log "OpenAI-compatible env: $warning" 'WARN'
    }
    foreach ($attempt in @($candidate['attempts'])) {
        $attemptMap = ConvertTo-BootstrapHashtable -InputObject $attempt
        Write-Log ("OpenAI-compatible tentativa: provider={0}, stage={1}, selected={2}, reason={3}, validation={4}" -f [string]$attemptMap['provider'], [string]$attemptMap['stage'], [string]$attemptMap['selected'], [string]$attemptMap['reason'], [string]$attemptMap['validationState'])
    }

    return [ordered]@{
        status = if ($updated.Count -gt 0) { 'applied' } else { 'configured' }
        reason = if ($warnings.Count -gt 0) { 'existing-user-env-conflict' } else { 'ok' }
        provider = $providerName
        baseUrl = $baseUrl
        stage = [string]$candidate['stage']
        updated = @($updated)
        skipped = @($skipped)
        warnings = @($warnings)
        attempts = @($candidate['attempts'])
    }
}

function Ensure-BootstrapAiWorkflowContextPack {
    param([AllowNull()][string]$WorkspaceRoot = '')

    $root = if ([string]::IsNullOrWhiteSpace($WorkspaceRoot)) { (Get-Location).Path } else { $WorkspaceRoot }
    $targetDir = Join-Path $root '.codex\context-packs'
    $targetPath = Join-Path $targetDir 'ai-agent-workflows.md'
    $content = @(
        '# AI Agent Workflow Context Pack',
        '',
        '- Classify work before execution: simple tasks stay single-agent; complex work gets planning, small subtasks, and verification.',
        '- Keep context clean: summarize long failed attempts before starting a new lane.',
        '- Keep Gemini keys scoped to Antigravity only; use OpenAI-compatible or local providers for other agents.',
        '- Prefer local Qwen/Hermes/Ollama/LM Studio only when configured and explicitly selected.',
        '- Run QA after worker output: parse configs, run targeted tests, then run broad tests before merge.',
        '- Never disable SmartScreen, VBS/Core Isolation, whole-disk indexing, or QoS automatically.'
    ) -join [Environment]::NewLine

    $backup = ''
    if (Test-Path -LiteralPath $targetPath) {
        $current = Get-Content -LiteralPath $targetPath -Raw -ErrorAction SilentlyContinue
        if ($current -eq $content) {
            return [ordered]@{ status = 'configured'; path = $targetPath; backup = '' }
        }
        $backup = Backup-BootstrapFile -Path $targetPath
    } else {
        $null = New-Item -Path $targetDir -ItemType Directory -Force
    }

    Write-BootstrapAtomicText -Path $targetPath -Content $content
    return [ordered]@{ status = 'applied'; path = $targetPath; backup = $backup }
}

function Ensure-BootstrapHeadroomAgentIntegration {
    param([AllowNull()][string]$WorkspaceRoot = '')

    $root = if ([string]::IsNullOrWhiteSpace($WorkspaceRoot)) { (Get-Location).Path } else { [System.IO.Path]::GetFullPath($WorkspaceRoot) }
    $docDir = Join-Path $root '.codex\context-packs'
    $scriptDir = Join-Path $root '.codex\scripts'
    $docPath = Join-Path $docDir 'headroom-agent-integration.md'
    $scriptPath = Join-Path $scriptDir 'headroom-agent.ps1'

    $docContent = @(
        '# Headroom Agent Integration',
        '',
        'Purpose: keep Headroom setup explicit, local, and reversible. This file documents supported wrappers and proxy/MCP paths without storing API keys.',
        '',
        'Install:',
        '- PhaseZero app: app-headroom-ai',
        '- Package source: PyPI headroom-ai[proxy]',
        '',
        'Supported wrappers:',
        '- Claude Code: `headroom wrap claude --memory`',
        '- Codex CLI: `headroom wrap codex --memory`',
        '- Aider: `headroom wrap aider`',
        '- Cursor: `headroom wrap cursor`',
        '- GitHub Copilot CLI: `headroom wrap copilot`',
        '- Gemini CLI: `headroom wrap gemini`',
        '- OpenClaw: blocked until each request can enforce an explicit account grant (exit 69).',
        '- OpenCode: manual proxy only; no stable Headroom wrapper is confirmed upstream yet.',
        '',
        'Proxy and automation:',
        '- n8n: run `headroom proxy --port 8787` and point OpenAI-compatible nodes to the local proxy after adding your own credentials in n8n.',
        '- MCP: run `headroom mcp install` only after reviewing target agent config.',
        '- Stats: run `headroom stats` to inspect local savings.',
        '',
        'Helper:',
        '- Use `.codex/scripts/headroom-agent.ps1 -Action status` to see available agent CLIs.',
        '- Use `.codex/scripts/headroom-agent.ps1 -Action wrap-claude` or another wrap action when you intentionally want Headroom to touch that agent.',
        '',
        'Safety:',
        '- No secrets are written here.',
        '- No wrappers run automatically during PhaseZero tuning.',
        '- Review generated agent config diffs after each wrap command.'
    ) -join [Environment]::NewLine

    $scriptContent = @'
param(
    [ValidateSet('status','proxy','wrap-claude','wrap-codex','wrap-aider','wrap-cursor','wrap-copilot','wrap-gemini','wrap-openclaw','mcp-install','stats')]
    [string]$Action = 'status',

    [Parameter(ValueFromRemainingArguments = $true)]
    [string[]]$ExtraArgs = @()
)

$ErrorActionPreference = 'Stop'

function Resolve-PhaseZeroCommand {
    param([Parameter(Mandatory = $true)][string]$Name)

    $cmd = Get-Command -Name $Name -ErrorAction SilentlyContinue | Select-Object -First 1
    if (-not $cmd) { return '' }
    if (-not [string]::IsNullOrWhiteSpace([string]$cmd.Source)) { return [string]$cmd.Source }
    return [string]$cmd.Name
}

function Invoke-Headroom {
    param([Parameter(Mandatory = $true)][string[]]$Args)

    $headroom = Resolve-PhaseZeroCommand -Name 'headroom'
    if ([string]::IsNullOrWhiteSpace($headroom)) {
        throw 'headroom not found. Install app-headroom-ai first.'
    }

    $allArgs = @($Args) + @($ExtraArgs)
    & $headroom @allArgs
    if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
}

switch ($Action) {
    'status' {
        Invoke-Headroom -Args @('version')
        foreach ($name in @('claude','codex','aider','cursor','copilot','gemini','openclaw','opencode','n8n')) {
            $path = Resolve-PhaseZeroCommand -Name $name
            if ([string]::IsNullOrWhiteSpace($path)) {
                Write-Output ("{0}: missing" -f $name)
            } else {
                Write-Output ("{0}: {1}" -f $name, $path)
            }
        }
    }
    'proxy' { Invoke-Headroom -Args @('proxy','--port','8787') }
    'wrap-claude' { Invoke-Headroom -Args @('wrap','claude','--memory') }
    'wrap-codex' { Invoke-Headroom -Args @('wrap','codex','--memory') }
    'wrap-aider' { Invoke-Headroom -Args @('wrap','aider') }
    'wrap-cursor' { Invoke-Headroom -Args @('wrap','cursor') }
    'wrap-copilot' { Invoke-Headroom -Args @('wrap','copilot') }
    'wrap-gemini' { Invoke-Headroom -Args @('wrap','gemini') }
    'wrap-openclaw' {
        Write-Output '{"blocked":true,"usageBlocked":true,"reason":"connection-grant-not-enforceable"}'
        [Console]::Error.WriteLine('OpenClaw blocked: account grants are not bound to each request.')
        exit 69
    }
    'mcp-install' { Invoke-Headroom -Args @('mcp','install') }
    'stats' { Invoke-Headroom -Args @('stats') }
}
'@

    $null = New-Item -Path $docDir -ItemType Directory -Force
    $null = New-Item -Path $scriptDir -ItemType Directory -Force

    $changed = $false
    $backups = New-Object System.Collections.Generic.List[string]
    foreach ($entry in @(
        [ordered]@{ path = $docPath; content = $docContent },
        [ordered]@{ path = $scriptPath; content = $scriptContent }
    )) {
        $path = [string]$entry.path
        $content = [string]$entry.content
        if (Test-Path -LiteralPath $path) {
            $current = Get-Content -LiteralPath $path -Raw -ErrorAction SilentlyContinue
            if ($current -eq $content) { continue }
            $backup = Backup-BootstrapFile -Path $path
            if (-not [string]::IsNullOrWhiteSpace($backup)) { $backups.Add($backup) }
        }
        Write-BootstrapAtomicText -Path $path -Content $content
        $changed = $true
    }

    return [ordered]@{
        status = if ($changed) { 'applied' } else { 'configured' }
        root = $root
        paths = @($docPath, $scriptPath)
        backups = @($backups.ToArray())
    }
}

function ConvertTo-BootstrapWorkspaceRelativePath {
    param(
        [Parameter(Mandatory = $true)][string]$Root,
        [Parameter(Mandatory = $true)][string]$Path
    )

    try {
        $rootFull = [System.IO.Path]::GetFullPath($Root)
        if (-not $rootFull.EndsWith([System.IO.Path]::DirectorySeparatorChar)) {
            $rootFull += [System.IO.Path]::DirectorySeparatorChar
        }
        $pathFull = [System.IO.Path]::GetFullPath($Path)
        $rootUri = New-Object System.Uri($rootFull)
        $pathUri = New-Object System.Uri($pathFull)
        return ([System.Uri]::UnescapeDataString($rootUri.MakeRelativeUri($pathUri).ToString())).Replace('\', '/')
    } catch {
        return ([string]$Path).Replace('\', '/')
    }
}

function Write-BootstrapMarkedTemplateFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$Body,
        [Parameter(Mandatory = $true)][string]$Label,
        [ValidateSet('html','hash')][string]$MarkerStyle = 'html'
    )

    $parent = Split-Path -Path $Path -Parent
    if ($parent) { $null = New-Item -Path $parent -ItemType Directory -Force }

    $current = if (Test-Path -LiteralPath $Path) { Get-Content -LiteralPath $Path -Raw -ErrorAction SilentlyContinue } else { '' }
    $merged = if ($MarkerStyle -eq 'hash') {
        Merge-BootstrapGrubMarkedTextBlock -Content $current -Body $Body -Label $Label
    } else {
        Merge-BootstrapMarkedTextBlock -Content $current -Body $Body -Label $Label
    }
    if (-not [bool]$merged.changed) {
        return [ordered]@{ path = $Path; status = 'configured'; backup = '' }
    }

    $backup = ''
    if (Test-Path -LiteralPath $Path) {
        $backup = Backup-BootstrapFile -Path $Path
    }
    Write-BootstrapAtomicText -Path $Path -Content ([string]$merged.content)
    return [ordered]@{ path = $Path; status = 'applied'; backup = $backup }
}

