        root = $base
        paths = @($results.ToArray() | ForEach-Object { [string]$_['path'] })
        fileResults = @($results.ToArray())
        prohibitions = @('token-scraping','session-extraction','waf-bypass','captcha-bypass','proxy-rotation-abuse')
        nextSteps = @('Configure .env com endpoint e chave proprios.', 'Rode npm install e npm start dentro da pasta gerada.')
    }
}

function Get-BootstrapAiGatewayDoctorReport {
    param(
        [AllowNull()][string]$BaseUrl = '',
        [AllowNull()][string]$ApiKey = '',
        [ValidateRange(1,60)][int]$TimeoutSec = 8
    )

    $checks = New-Object System.Collections.Generic.List[object]
    $base = ([string]$BaseUrl).Trim().TrimEnd('/')
    $secretPresent = -not [string]::IsNullOrWhiteSpace([string]$ApiKey)

    $checks.Add([ordered]@{
        id = 'base-url'
        status = if ([string]::IsNullOrWhiteSpace($base)) { 'blocked' } else { 'healthy' }
        summary = if ([string]::IsNullOrWhiteSpace($base)) { 'Base URL ausente.' } else { 'Base URL informada.' }
    }) | Out-Null
    $checks.Add([ordered]@{
        id = 'secret'
        status = if ($secretPresent) { 'healthy' } else { 'blocked' }
        secretPresent = $secretPresent
        summary = if ($secretPresent) { 'Segredo presente e redigido.' } else { 'Segredo ausente.' }
    }) | Out-Null

    if ([string]::IsNullOrWhiteSpace($base) -or -not $secretPresent) {
        return [ordered]@{
            status = 'blocked'
            changed = $false
            checks = @($checks.ToArray())
            secretPresent = $secretPresent
            nextSteps = @('Informe base URL e chave de provider autorizado.', 'Depois valide /v1/models e streaming simples.')
        }
    }

    try {
        $headers = @{ Authorization = "Bearer $ApiKey" }
        $response = Invoke-WebRequest -Uri ($base + '/models') -Headers $headers -UseBasicParsing -TimeoutSec $TimeoutSec -ErrorAction Stop
        $checks.Add([ordered]@{ id = 'models'; status = 'healthy'; statusCode = [int]$response.StatusCode; summary = '/models respondeu.' }) | Out-Null
    } catch {
        $checks.Add([ordered]@{ id = 'models'; status = 'warning'; summary = 'Falha ao validar /models; revise endpoint, quota e modelo.' }) | Out-Null
    }

    $warnings = @($checks.ToArray() | Where-Object { [string]$_['status'] -eq 'warning' }).Count
    return [ordered]@{
        status = if ($warnings -gt 0) { 'warning' } else { 'healthy' }
        changed = $false
        checks = @($checks.ToArray())
        secretPresent = $secretPresent
        nextSteps = @('Propague este endpoint apenas para apps compativeis.', 'Mantenha chaves fora de logs e arquivos versionados.')
    }
}

function Apply-ContainerHostingTuning {
    param(
        [Parameter(Mandatory = $true)]$Item,
        [AllowNull()][hashtable]$State = $null
    )

    $workspace = if ($State -and $State.ContainsKey('CloneBaseDir') -and -not [string]::IsNullOrWhiteSpace([string]$State['CloneBaseDir'])) { [string]$State['CloneBaseDir'] } else { (Get-Location).Path }
    switch ([string]$Item.id) {
        'docker-hosting-doctor' {
            $doctor = Get-BootstrapDockerHostingDoctorReport
            return [ordered]@{ id = [string]$Item.id; category = [string]$Item.category; status = [string]$doctor.status; changed = $false; doctor = $doctor; note = 'Docker hosting doctor executado sem mutacao.' }
        }
        default {
            $pack = Ensure-BootstrapContainerHostingPack -WorkspaceRoot $workspace
            return [ordered]@{ id = [string]$Item.id; category = [string]$Item.category; status = [string]$pack.status; changed = [bool]$pack.changed; paths = @($pack.paths); doctor = $pack.doctor; nextSteps = @($pack.nextSteps); manifest = $pack }
        }
    }
}

function Apply-AiEdgeSafeTuning {
    param(
        [Parameter(Mandatory = $true)]$Item,
        [AllowNull()][hashtable]$State = $null
    )

    $workspace = if ($State -and $State.ContainsKey('CloneBaseDir') -and -not [string]::IsNullOrWhiteSpace([string]$State['CloneBaseDir'])) { [string]$State['CloneBaseDir'] } else { (Get-Location).Path }
    switch ([string]$Item.id) {
        'ai-gateway-doctor' {
            $doctor = Get-BootstrapAiGatewayDoctorReport
            return [ordered]@{ id = [string]$Item.id; category = [string]$Item.category; status = [string]$doctor.status; changed = $false; doctor = $doctor; note = 'AI gateway doctor executado com segredos redigidos.' }
        }
        'ai-provider-gateway-config' {
            $template = Ensure-BootstrapAiEdgeSafeTemplate -WorkspaceRoot $workspace
            $state = New-BootstrapState -Selection @{} -ResolvedWorkspaceRoot $workspace -ResolvedCloneBaseDir $workspace -RequestedSteamDeckVersion 'Auto' -ResolvedSteamDeckVersion '' -HostHealthMode 'off' -UsesSteamDeckFlow:$false -IsDryRun:$false
            Ensure-BootstrapSecrets -State $state
            return [ordered]@{ id = [string]$Item.id; category = [string]$Item.category; status = 'applied'; changed = [bool]$template.changed; paths = @($template.paths); summary = $state.SecretsSummary; nextSteps = @('Revise backups dos JSONs alterados.', 'Valide apps compativeis antes de trocar default global.') }
        }
        default {
            $template = Ensure-BootstrapAiEdgeSafeTemplate -WorkspaceRoot $workspace
            return [ordered]@{ id = [string]$Item.id; category = [string]$Item.category; status = [string]$template.status; changed = [bool]$template.changed; paths = @($template.paths); nextSteps = @($template.nextSteps); manifest = $template }
        }
    }
}

function Set-BootstrapGithubCliAgentAuth {
    $bundle = Get-BootstrapSecretsData
    $secretsData = ConvertTo-BootstrapHashtable -InputObject $bundle.Data
    $tokenState = Get-BootstrapGithubActiveTokenState -SecretsData $secretsData
    $summary = [ordered]@{
        status = 'skipped'
        reason = ''
        path = [string]$bundle.Path
        userEnvApplied = 0
        tokenAvailable = [bool]$tokenState['tokenAvailable']
        tokenSource = [string]$tokenState['tokenSource']
        credentialId = [string]$tokenState['credentialId']
        validationState = [string]$tokenState['validationState']
        targets = [ordered]@{
            claudeCodeUpdated = $false
            claudeDesktopUpdated = $false
            cursorUpdated = $false
            windsurfUpdated = $false
            traeUpdated = $false
            openCodeUpdated = $false
            vsCodeUpdated = $false
            rooUpdated = $false
            clineUpdated = $false
            zedUpdated = $false
            zCodeUpdated = $false
            openClawUpdated = $false
            hermesUpdated = $false
            kiloUpdated = $false
            continueUpdated = $false
        }
        warnings = @()
    }

    if (-not [bool]$tokenState['tokenAvailable']) {
        $summary['reason'] = 'github-token-missing'
        $summary['warnings'] = @('Nenhum token GitHub ativo encontrado em bootstrap-secrets.')
        return $summary
    }
    if ([string]$tokenState['tokenSource'] -ne 'bootstrap-secrets:validated-active') {
        $summary['reason'] = 'github-token-not-validated'
        $summary['warnings'] = @('Token GitHub existe, mas ainda nao tem validacao passed; agentes nao foram atualizados.')
        return $summary
    }

    $resolvedTargets = Get-BootstrapResolvedSecretsTargets -SecretsData $secretsData -IncludeManagedMcps
    if ($resolvedTargets.ContainsKey('claudeCode') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['claudeCode'])) {
        $summary.targets.claudeCodeUpdated = [bool](Ensure-BootstrapClaudeCodeSecrets -ResolvedTargets $resolvedTargets)
    }
    if ($resolvedTargets.ContainsKey('claudeDesktop') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['claudeDesktop'])) {
        $summary.targets.claudeDesktopUpdated = [bool](Ensure-BootstrapClaudeDesktopSecrets -ResolvedTargets $resolvedTargets)
    }
    if ($resolvedTargets.ContainsKey('cursor') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['cursor'])) {
        $summary.targets.cursorUpdated = [bool](Ensure-BootstrapCursorSecrets -ResolvedTargets $resolvedTargets)
    }
    if ($resolvedTargets.ContainsKey('windsurf') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['windsurf'])) {
        $summary.targets.windsurfUpdated = [bool](Ensure-BootstrapWindsurfSecrets -ResolvedTargets $resolvedTargets)
    }
    if ($resolvedTargets.ContainsKey('trae') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['trae'])) {
        $summary.targets.traeUpdated = [bool](Ensure-BootstrapTraeSecrets -ResolvedTargets $resolvedTargets)
    }
    if ($resolvedTargets.ContainsKey('openCode') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['openCode'])) {
        $summary.targets.openCodeUpdated = [bool](Ensure-BootstrapOpenCodeSecrets -ResolvedTargets $resolvedTargets -SecretsData $secretsData)
    }
    if ($resolvedTargets.ContainsKey('vsCode') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['vsCode'])) {
        $summary.targets.vsCodeUpdated = [bool](Ensure-BootstrapVsCodeSecrets -ResolvedTargets $resolvedTargets)
    }
    if ($resolvedTargets.ContainsKey('roo') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['roo'])) {
        $summary.targets.rooUpdated = [bool](Ensure-BootstrapRooSecrets -ResolvedTargets $resolvedTargets)
    }
    if ($resolvedTargets.ContainsKey('cline') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['cline'])) {
        $summary.targets.clineUpdated = [bool](Ensure-BootstrapClineSecrets -ResolvedTargets $resolvedTargets)
    }
    if ($resolvedTargets.ContainsKey('zed') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['zed'])) {
        $summary.targets.zedUpdated = [bool](Ensure-BootstrapZedSecrets -ResolvedTargets $resolvedTargets)
    }
    if ($resolvedTargets.ContainsKey('zCode') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['zCode'])) {
        $summary.targets.zCodeUpdated = [bool](Ensure-BootstrapZCodeSecrets -ResolvedTargets $resolvedTargets)
    }
    if ($resolvedTargets.ContainsKey('openClaw') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['openClaw'])) {
        $summary.targets.openClawUpdated = [bool](Ensure-BootstrapOpenClawSecrets -ResolvedTargets $resolvedTargets)
    }
    if ($resolvedTargets.ContainsKey('hermes') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['hermes'])) {
        $summary.targets.hermesUpdated = [bool](Ensure-BootstrapHermesSecrets -ResolvedTargets $resolvedTargets -State $null)
    }
    if ($resolvedTargets.ContainsKey('kilo') -and (Test-BootstrapSecretsTargetHasApplicableValues -Target $resolvedTargets['kilo'])) {
        $summary.targets.kiloUpdated = [bool](Ensure-BootstrapKiloSecrets -ResolvedTargets $resolvedTargets -SecretsData $secretsData)
    }
    $continueResult = Ensure-BootstrapContinueExtensionConfig -ResolvedTargets $resolvedTargets
    $summary.targets.continueUpdated = ($null -ne $continueResult)

    $updatedCount = 0
    foreach ($key in @($summary.targets.Keys)) {
        if ([bool]$summary.targets[$key]) { $updatedCount += 1 }
    }
    $summary['status'] = if ($updatedCount -gt 0) { 'applied' } else { 'configured' }
    $summary['reason'] = 'agent-context-only'
    return $summary
}

function Apply-DevAiTuning {
    param(
        [Parameter(Mandatory = $true)]$Item,
        [AllowNull()][hashtable]$State = $null
    )

    switch ([string]$Item.id) {
        'notepadpp-defaults' {
            $result = Ensure-BootstrapNotepadPlusPlusDefaults
            return [ordered]@{
                id = [string]$Item.id
                status = [string]$result.status
                note = 'Curadoria Notepad++ aplicada com plugins/UDLs oficiais e custom.'
                manifest = $result
            }
        }
        'claude-code-defaults' {
            $gitBashPath = Get-GitBashExe
            Ensure-ClaudeCodeDefaults -GitBashPath $gitBashPath
            Ensure-ClaudeHookConfigsHealthy -GitBashPath $gitBashPath

            $secretsInfo = Get-BootstrapSecretsData
            $secretsData = ConvertTo-BootstrapHashtable -InputObject $secretsInfo.Data
            $resolvedTargets = Get-BootstrapResolvedSecretsTargets -SecretsData $secretsData
            $secretsUpdated = Ensure-BootstrapClaudeCodeSecrets -ResolvedTargets $resolvedTargets
            $envShim = Ensure-BootstrapOpenAiCompatibleUserEnv -PreferredProviders @('mimo', 'openrouter', 'moonshot', 'deepseek', 'openai', 'xai')

            return [ordered]@{
                id = [string]$Item.id
                status = 'applied'
                note = ("Claude Code defaults + hooks + env OpenAI-compatible (provider={0}, status={1})." -f [string]$envShim.provider, [string]$envShim.status)
                secretsUpdated = [bool]$secretsUpdated
                envShim = $envShim
            }
        }
        'opencode-auth-config' {
            $secretsInfo = Get-BootstrapSecretsData
            $secretsData = ConvertTo-BootstrapHashtable -InputObject $secretsInfo.Data
            $resolvedTargets = Get-BootstrapResolvedSecretsTargets -SecretsData $secretsData
            $updated = Ensure-BootstrapOpenCodeSecrets -ResolvedTargets $resolvedTargets -SecretsData $secretsData
            return [ordered]@{
                id = [string]$Item.id
                status = if ([bool]$updated) { 'applied' } else { 'configured' }
                note = 'OpenCode auth/config sincronizado via manifesto.'
                updated = [bool]$updated
            }
        }
        'ai-agent-byok-config' {
            $state = New-BootstrapState -Selection @{} -ResolvedWorkspaceRoot (Get-Location).Path -ResolvedCloneBaseDir (Get-Location).Path -RequestedSteamDeckVersion 'Auto' -ResolvedSteamDeckVersion '' -HostHealthMode 'off' -UsesSteamDeckFlow:$false -IsDryRun:$false
            Ensure-BootstrapSecrets -State $state
            return [ordered]@{
                id = [string]$Item.id
                status = 'applied'
                note = 'Manifesto BYOK sincronizado para agentes CLI/IDE suportados.'
                summary = $state.SecretsSummary
            }
        }
        'ai-agent-workflow-context-pack' {
            $workspace = if ($State) { [string]$State.CloneBaseDir } else { (Get-Location).Path }
            $result = Ensure-BootstrapAiWorkflowContextPack -WorkspaceRoot $workspace
            return [ordered]@{
                id = [string]$Item.id
                status = [string]$result.status
                note = 'AI workflow/context pack aplicado sem automacao destrutiva.'
                manifest = $result
            }
        }
        'github-cli-agent-auth' {
            $summary = Set-BootstrapGithubCliAgentAuth
            return [ordered]@{
                id = [string]$Item.id
                status = [string]$summary.status
                note = 'GitHub token sincronizado para configs de agentes sem persistir GH_TOKEN global.'
                summary = $summary
            }
        }
        'codex-desktop-repair' {
            $repair = Repair-BootstrapCodexDesktop
            return [ordered]@{
                id = [string]$Item.id
                status = [string]$repair['status']
                note = [string]$repair['note']
                manifest = $repair
            }
        }
        'antigravity-settings' {
            $envShim = Ensure-BootstrapOpenAiCompatibleUserEnv -PreferredProviders @('mimo', 'moonshot', 'openrouter', 'deepseek', 'openai', 'xai')
            return [ordered]@{
                id = [string]$Item.id
                status = [string]$envShim.status
                note = ("Env OpenAI-compatible para Antigravity/CLIs: provider={0}, status={1}, motivo={2}." -f [string]$envShim.provider, [string]$envShim.status, [string]$envShim.reason)
                envShim = $envShim
            }
        }
        'openclaude-cli-env' {
            $envShim = Ensure-BootstrapOpenAiCompatibleUserEnv -PreferredProviders @('mimo', 'openrouter', 'moonshot', 'deepseek', 'openai', 'xai')
            return [ordered]@{
                id = [string]$Item.id
                status = [string]$envShim.status
                note = 'Env OpenAI-compatible aplicado para OpenClaude CLI.'
                envShim = $envShim
            }
        }
        'llamacpp-mtp-template' {
            $template = Ensure-BootstrapLlamacppMtpTemplate -WorkspaceRoot (Get-BootstrapAppTuningWorkspaceRoot -State $State)
            return [ordered]@{
                id = [string]$Item.id
                status = [string]$template.status
                changed = [bool]$template.changed
                note = 'Template de diagnostico MTP gerado; nenhum modelo foi baixado.'
                paths = @($template.paths)
                nextSteps = @($template.nextSteps)
                rollback = 'file-template'
            }
        }
        default {
            return [ordered]@{ id = [string]$Item.id; status = 'audited'; note = 'Dev/AI integration audited; secrets remain managed by bootstrap-secrets.' }
        }
    }
}

