function Test-BootstrapApiRelatedErrorMessage {
    param([AllowNull()][string]$Message)

    if ([string]::IsNullOrWhiteSpace($Message)) { return $false }
    $normalized = $Message.ToLowerInvariant()
    return (
        $normalized.Contains('openai-compatible') -or
        $normalized.Contains('no-openai-compatible-provider') -or
        $normalized.Contains('api key') -or
        $normalized.Contains('api_key') -or
        $normalized.Contains('token') -or
        $normalized.Contains('organization does not have access to claude') -or
        $normalized.Contains('anthropic')
    )
}

function Test-BootstrapAppTuningRecoverableError {
    param(
        [AllowNull()][string]$Message,
        [AllowNull()][string]$ExceptionType
    )

    $messageText = if ([string]::IsNullOrWhiteSpace($Message)) { '' } else { [string]$Message }
    $exceptionText = if ([string]::IsNullOrWhiteSpace($ExceptionType)) { '' } else { [string]$ExceptionType }
    $messageComparable = ConvertTo-BootstrapArtifactComparableText -Value $messageText

    return (
        $messageText -match '(?i)acesso.*negado' -or
        $messageText -match '(?i)n[aã]o\s+(e|é)\s+permitido' -or
        ($messageComparable.Contains('registro') -and $messageComparable.Contains('permitido')) -or
        ($messageComparable.Contains('acesso') -and $messageComparable.Contains('permitido')) -or
        $messageText -match '(?i)localizar.*caminho' -or
        $messageText -match '(?i)access is not allowed' -or
        $messageText -match '(?i)access is denied' -or
        $messageText -match '(?i)not permitted' -or
        $messageText -match '(?i)requested registry access' -or
        $messageText -match '(?i)unauthorized' -or
        $messageText -match '(?i)cannot find.*path' -or
        $exceptionText -match '(?i)UnauthorizedAccess' -or
        $exceptionText -match '(?i)SecurityException'
    )
}

function Get-BootstrapAppTuningFailureClassification {
    param(
        [Parameter(Mandatory = $true)]$Item,
        [AllowNull()][string]$ErrorMessage,
        [AllowNull()][string]$ExceptionType
    )

    $itemId = [string]$Item.id
    $itemCategory = [string]$Item.category
    $message = if ([string]::IsNullOrWhiteSpace($ErrorMessage)) { 'sem detalhe de erro' } else { [string]$ErrorMessage }

    if ((Test-BootstrapApiRelatedErrorMessage -Message $message) -and ($itemCategory -eq 'dev-ai')) {
        return [ordered]@{
            severity = 'warning'
            classification = 'api-non-blocking'
            reason = 'Dependencia de API detectada em item dev-ai; classificada como nao bloqueante.'
            blocking = $false
            message = $message
            exceptionType = if ([string]::IsNullOrWhiteSpace($ExceptionType)) { 'RuntimeException' } else { [string]$ExceptionType }
        }
    }

    # Se for erro de permissao ou caminho inexistente em registro, nao bloquear.
    # Cobrir mensagens PT e EN e os tipos de excecao reais: ajustes que escrevem em
    # chaves protegidas/HKLM num run sem admin lancam System.Security.SecurityException
    # ("Requested registry access is not allowed.") ou UnauthorizedAccessException.
    # Sem isso, um unico ajuste admin-only (ex.: edge-background-off) abortava TODA a fase
    # de AppTuning + HostHealth em vez de pular como os componentes admin-only fazem.
    $permissionDenied = Test-BootstrapAppTuningRecoverableError -Message $message -ExceptionType $ExceptionType
    if ($permissionDenied) {
        return [ordered]@{
            severity = 'warning'
            classification = 'permission-denied'
            reason = "Acesso negado ou caminho ausente ao aplicar ajuste {0}; classificado como nao bloqueante (pode requerer admin)." -f $itemId
            blocking = $false
            message = $message
            exceptionType = $ExceptionType
        }
    }

    return [ordered]@{
        severity = 'blocking'
        classification = 'execution-failure'
        reason = ("Falha bloqueante no item {0} ({1})." -f $itemId, $itemCategory)
        blocking = $true
        message = $message
        exceptionType = if ([string]::IsNullOrWhiteSpace($ExceptionType)) { 'RuntimeException' } else { [string]$ExceptionType }
    }
}

function Apply-LocalAiContainerTuning {
    param([Parameter(Mandatory = $true)]$Item)
    return [ordered]@{ id = [string]$Item.id; status = 'prepared'; note = 'Marked for Desktop/Dev session only; not Game - Steam Deck.' }
