function Apply-WindowsQolTuning {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Item
    )

    $itemId = [string]$Item.id
    $result = switch ($itemId) {
        'quicklook-defaults'    { Ensure-BootstrapQuickLookSession }
        'explorerpatcher-optin' { Ensure-BootstrapExplorerPatcherOptIn -State $State }
        'mica-optin'            { Ensure-BootstrapMicaOptIn -State $State }
        'powertoys-qol'         { Ensure-BootstrapPowerToysQol -State $State }
        default                 { [ordered]@{ status = 'skipped'; reason = 'no-handler'; note = "Item windows-qol sem handler dedicado: $itemId." } }
    }

    $map = ConvertTo-BootstrapHashtable -InputObject $result
    if (-not ($map -is [hashtable])) { $map = @{ status = 'skipped'; reason = 'invalid-result' } }
    $map['id'] = $itemId
    $map['category'] = [string]$Item.category
    return $map
}

function Invoke-BootstrapAppTuningItem {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Item
    )

    if (-not [bool]$Item.installed) {
        return [ordered]@{ id = [string]$Item.id; category = [string]$Item.category; status = 'skipped'; reason = 'app absent' }
    }

    switch ([string]$Item.category) {
        'browser-startup' { return (Apply-BrowserStartupTuning -State $State -Item $Item) }
        'gaming-console' {
            if ([string]$Item.id -eq 'playnite-fullscreen') { return (Apply-PlayniteTuning -Item $Item) }
            return (Apply-SteamConsoleTuning -Item $Item)
        }
        'steamdeck-control' { return (Apply-SteamDeckControlTuning -Item $Item -State $State) }
        'dev-ai' { return (Apply-DevAiTuning -State $State -Item $Item) }
        'agent-config' { return (Apply-AgentConfigTuning -State $State -Item $Item) }
        'local-ai-containers' { return (Apply-LocalAiContainerTuning -Item $Item) }
        'container-hosting' { return (Apply-ContainerHostingTuning -State $State -Item $Item) }
        'ai-edge-safe' { return (Apply-AiEdgeSafeTuning -State $State -Item $Item) }
        'ai-agent-performance' { return (Apply-AiAgentPerformanceTuning -State $State -Item $Item) }
        'capture-creator' { return (Apply-CaptureTuning -Item $Item -State $State) }
        'windows-qol' { return (Apply-WindowsQolTuning -State $State -Item $Item) }
        'connectivity' { return (Apply-ConnectivityTuning -State $State -Item $Item) }
        'knowledge-vault' { return (Apply-KnowledgeVaultTuning -State $State -Item $Item) }
        'workflow-automation' { return (Apply-WorkflowAutomationTuning -State $State -Item $Item) }
        default {
            # Sem handler para a categoria. Itens que so declaram auditoria sao honestos como
            # 'audited'; itens que declaram acao mutante nao podem reportar sucesso sem ter mutado
            # nada - viram 'skipped' com motivo explicito para nao mentir no status nem no -Audit.
            $declaredActions = @()
            if (($Item -is [System.Collections.IDictionary]) -and $Item.Contains('actions')) {
                $declaredActions = @($Item['actions'])
            } elseif ($Item.PSObject.Properties['actions']) {
                $declaredActions = @($Item.actions)
            }
            $mutatingActions = @($declaredActions | Where-Object {
                @('audit', 'install') -notcontains [string]$_
            })
            if ($mutatingActions.Count -gt 0) {
                return [ordered]@{
                    id = [string]$Item.id
                    category = [string]$Item.category
                    status = 'skipped'
                    reason = 'no-handler'
                    blocking = $false
                    note = ('Categoria {0} nao possui handler de tuning; acoes declaradas nao foram aplicadas: {1}.' -f [string]$Item.category, (@($mutatingActions) -join ', '))
                    declaredActions = @($mutatingActions)
                }
            }
            return [ordered]@{ id = [string]$Item.id; category = [string]$Item.category; status = 'audited'; note = 'Item somente de auditoria; nenhuma mutacao declarada.' }
        }
    }
}

function Normalize-BootstrapAppTuningItemResult {
    param([AllowNull()]$Result)

    $itemResult = ConvertTo-BootstrapHashtable -InputObject $Result
    if (-not ($itemResult -is [hashtable])) {
        return $Result
    }

    $status = [string]$itemResult['status']
    if ($status -eq 'partial') {
        if (-not (Test-BootstrapMapContainsKey -Map $itemResult -Key 'severity')) { $itemResult['severity'] = 'warning' }
        if (-not (Test-BootstrapMapContainsKey -Map $itemResult -Key 'classification')) { $itemResult['classification'] = 'partial-application' }
        if (-not (Test-BootstrapMapContainsKey -Map $itemResult -Key 'blocking')) { $itemResult['blocking'] = $false }
    }
    if ($status -eq 'failed') {
        $errorMessage = if (Test-BootstrapMapContainsKey -Map $itemResult -Key 'error') { [string]$itemResult['error'] } elseif (Test-BootstrapMapContainsKey -Map $itemResult -Key 'reason') { [string]$itemResult['reason'] } elseif (Test-BootstrapMapContainsKey -Map $itemResult -Key 'note') { [string]$itemResult['note'] } else { '' }
        $exceptionType = if (Test-BootstrapMapContainsKey -Map $itemResult -Key 'exceptionType') { [string]$itemResult['exceptionType'] } else { '' }
        if (Test-BootstrapAppTuningRecoverableError -Message $errorMessage -ExceptionType $exceptionType) {
            $itemResult['severity'] = 'warning'
            $itemResult['classification'] = 'permission-denied'
            $itemResult['blocking'] = $false
        } else {
            if (-not (Test-BootstrapMapContainsKey -Map $itemResult -Key 'severity')) { $itemResult['severity'] = 'blocking' }
            if (-not (Test-BootstrapMapContainsKey -Map $itemResult -Key 'classification')) { $itemResult['classification'] = 'execution-failure' }
            if (-not (Test-BootstrapMapContainsKey -Map $itemResult -Key 'blocking')) { $itemResult['blocking'] = $true }
        }
    }

    return $itemResult
}

function Convert-BootstrapAppTuningResultToItemStatus {
    param([AllowNull()]$Result)

    $resultMap = ConvertTo-BootstrapHashtable -InputObject $Result
    if (-not ($resultMap -is [hashtable]) -or -not (Test-BootstrapMapContainsKey -Map $resultMap -Key 'status')) { return '' }
    switch ([string]$resultMap['status']) {
        'applied'    { return 'configured' }
        'configured' { return 'configured' }
        'unchanged'  { return 'configured' }
        'audited'    { return 'optimized-tested' }
        default      { return '' }
    }
}

function Invoke-BootstrapAppTuning {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$Plan
    )

    if ([string]$Plan.mode -eq 'off') {
        Write-Log 'AppTuning: desligado para esta execucao.'
        return
    }

    $reportRoot = Get-BootstrapAppTuningReportRoot -State $State
    $snapshotPath = Join-Path $reportRoot 'snapshot.json'
    $resultPath = Join-Path $reportRoot 'result.json'
    Write-BootstrapJsonFile -Path $snapshotPath -Value (New-BootstrapAppTuningSnapshot -Plan $Plan)

    $results = @()
    $blockingFailures = @()
    # Inventario do plano e do inicio do run; apos winget instalar apps, precisamos reavaliar probePaths/targetApps
    # para nao pular itens (ex.: notepadpp-defaults) com "app absent" indevidamente na mesma execucao.
    $freshInventory = Get-BootstrapInstalledAppInventory
    foreach ($item in @($Plan.items)) {
        $liveItem = ConvertTo-BootstrapHashtable -InputObject $item
        if (-not ($liveItem -is [hashtable])) { $liveItem = @{ } }
        try {
            $liveItem['installed'] = (Test-BootstrapAppTuningItemInstalled -Item $liveItem -InstalledInventory $freshInventory)
        } catch {
            $liveItem['installed'] = $false
        }

        $itemId = [string]$liveItem['id']
        $itemCategory = [string]$liveItem['category']
        $itemTargetApps = if ($liveItem['targetApps'] -is [System.Collections.IEnumerable]) { @($liveItem['targetApps']) -join ',' } else { '' }
        $plannedStatus = if ($item -is [System.Collections.IDictionary] -and (Test-BootstrapMapContainsKey -Map $item -Key 'status')) { [string]$item['status'] } else { '' }
        Write-Log ("AppTuning: itemId={0} category={1} stage=pre-invoke planStatus={2} installedNow={3}" -f $itemId, $itemCategory, $plannedStatus, [bool]$liveItem['installed'])

        $itemResult = $null
        try {
            $itemResult = Invoke-BootstrapAppTuningItem -State $State -Item $liveItem
        } catch {
            $classification = Get-BootstrapAppTuningFailureClassification -Item $item -ErrorMessage $_.Exception.Message -ExceptionType $_.Exception.GetType().FullName
            $itemResult = [ordered]@{
                id = $itemId
                category = $itemCategory
                targetApps = if ([string]::IsNullOrWhiteSpace($itemTargetApps)) { @() } else { @($itemTargetApps -split ',') }
                stage = 'invoke-item'
                status = 'failed'
                severity = [string]$classification['severity']
                classification = [string]$classification['classification']
                blocking = [bool]$classification['blocking']
                reason = [string]$classification['reason']
                error = [string]$classification['message']
                exceptionType = [string]$classification['exceptionType']
            }
            Write-Log ("AppTuning: itemId={0} category={1} targetApps={2} stage=invoke-item status=failed severity={3} classification={4} exceptionType={5} message={6}" -f $itemId, $itemCategory, $itemTargetApps, [string]$itemResult['severity'], [string]$itemResult['classification'], [string]$itemResult['exceptionType'], [string]$itemResult['error']) 'WARN'
        }

        $itemResult = Normalize-BootstrapAppTuningItemResult -Result $itemResult
        if ($itemResult -is [System.Collections.IDictionary]) {
            if ((Test-BootstrapMapContainsKey -Map $itemResult -Key 'blocking') -and [bool]$itemResult['blocking']) {
                $blockingFailures += @($itemResult)
            }
            if (-not [bool]$State.DryRun) {
                $visualStatus = Convert-BootstrapAppTuningResultToItemStatus -Result $itemResult
                if (-not [string]::IsNullOrWhiteSpace($itemId) -and -not [string]::IsNullOrWhiteSpace($visualStatus)) {
                    Set-BootstrapItemStatus -Kind 'config' -Id $itemId -Status $visualStatus
                }
            }
            $State.AppTuningResults.Add($itemResult)
        }
        $results += @($itemResult)
    }

    Write-BootstrapJsonFile -Path $resultPath -Value ([ordered]@{
        generatedAt = (Get-Date).ToString('o')
        mode = [string]$Plan.mode
        reportRoot = $reportRoot
        snapshotPath = $snapshotPath
        results = @($results)
        blockingFailures = @($blockingFailures)
    })
    if (@($blockingFailures).Count -gt 0) {
        $firstBlocking = ConvertTo-BootstrapHashtable -InputObject $blockingFailures[0]
        throw ("AppTuning bloqueado em {0}: {1}" -f [string]$firstBlocking['id'], [string]$firstBlocking['error'])
    }
    Write-Log "AppTuning report: $reportRoot"
}

function Get-BootstrapDesktopPath {
    $desktopPath = [Environment]::GetFolderPath('Desktop')
    if (-not [string]::IsNullOrWhiteSpace($desktopPath)) {
        return $desktopPath
    }
    $userHome = Get-BootstrapUserHomePath
    if ([string]::IsNullOrWhiteSpace($userHome)) { return '' }
    return (Join-Path $userHome 'Desktop')
}

function Get-BootstrapWebAppBrowserCandidate {
    $candidates = @(
        [ordered]@{
            browser = 'edge'
            exe = (Resolve-CommandPath -Name 'msedge')
            argsPrefix = '--app='
            fallbackPaths = @(
                (Join-Path $env:ProgramFiles 'Microsoft\Edge\Application\msedge.exe'),
                (Join-Path ${env:ProgramFiles(x86)} 'Microsoft\Edge\Application\msedge.exe')
            )
        },
        [ordered]@{
            browser = 'chrome'
            exe = (Resolve-CommandPath -Name 'chrome')
            argsPrefix = '--app='
            fallbackPaths = @(
                (Join-Path $env:ProgramFiles 'Google\Chrome\Application\chrome.exe'),
                (Join-Path ${env:ProgramFiles(x86)} 'Google\Chrome\Application\chrome.exe'),
                (Join-Path $env:LOCALAPPDATA 'Google\Chrome\Application\chrome.exe')
            )
        }
    )

    foreach ($candidate in @($candidates)) {
        $exePath = [string]$candidate.exe
        if ([string]::IsNullOrWhiteSpace($exePath)) {
            foreach ($fallbackPath in @($candidate.fallbackPaths)) {
                if (-not [string]::IsNullOrWhiteSpace($fallbackPath) -and (Test-Path $fallbackPath)) {
                    $exePath = $fallbackPath
                    break
                }
            }
        }
        if (-not [string]::IsNullOrWhiteSpace($exePath) -and (Test-Path $exePath)) {
            return [ordered]@{
                browser = [string]$candidate.browser
                exe = $exePath
                argsPrefix = [string]$candidate.argsPrefix
            }
        }
    }

    return [ordered]@{
        browser = ''
        exe = ''
        argsPrefix = '--app='
    }
}

function Test-BootstrapIcoFile {
    # Valida que o arquivo e um .ico real (magic bytes 00 00 01 00) e nao um HTML/404.
    param([Parameter(Mandatory = $true)][string]$Path)
    try {
        if (-not (Test-Path -LiteralPath $Path)) { return $false }
        $bytes = [System.IO.File]::ReadAllBytes($Path)
        if ($bytes.Length -lt 6) { return $false }
        return ($bytes[0] -eq 0 -and $bytes[1] -eq 0 -and $bytes[2] -eq 1 -and $bytes[3] -eq 0)
    } catch { return $false }
}

function Resolve-BootstrapWebAppIconLocation {
    # Cascata resiliente de icone de identidade para web apps; nunca lanca. Retorna '' se nada servir.
    # 1) asset curado assets/webapp-icons/<slug>.ico  2) cache local  3) download host/favicon.ico (validado)
    param(
        [Parameter(Mandatory = $true)][string]$Url,
        [Parameter(Mandatory = $true)][string]$DisplayName
    )

    $slug = ([string]$DisplayName).ToLowerInvariant() -replace '[^a-z0-9]+', '-'
    $slug = $slug.Trim('-')

    # 1) Asset curado versionado no repo (offline, confiavel).
    try {
        $curated = Join-Path $PSScriptRoot ("assets\webapp-icons\{0}.ico" -f $slug)
        if (Test-BootstrapIcoFile -Path $curated) { return ("{0},0" -f $curated) }
    } catch { }

    # Host da URL (evita colidir com a variavel automatica $Host).
    $urlHost = ''
    try { $urlHost = ([System.Uri]$Url).Host } catch { $urlHost = '' }
    if ([string]::IsNullOrWhiteSpace($urlHost)) { return '' }

    # 2) Cache local.
    $cacheDir = ''
    try {
        $cacheDir = Join-Path (Get-BootstrapDataRoot) 'webapp-icons'
        if (-not (Test-Path -LiteralPath $cacheDir)) { $null = New-Item -ItemType Directory -Path $cacheDir -Force }
    } catch { $cacheDir = '' }
    if ([string]::IsNullOrWhiteSpace($cacheDir)) { return '' }
    $cached = Join-Path $cacheDir ("{0}.ico" -f $urlHost)
    if (Test-BootstrapIcoFile -Path $cached) { return ("{0},0" -f $cached) }

    # 3) Download favicon.ico (best-effort, validado por magic bytes; nunca bloqueia).
    foreach ($candidateUrl in @(("https://{0}/favicon.ico" -f $urlHost))) {
        try {
            [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
            Invoke-WebRequest -Uri $candidateUrl -OutFile $cached -UseBasicParsing -TimeoutSec 8 -ErrorAction Stop | Out-Null
            if (Test-BootstrapIcoFile -Path $cached) { return ("{0},0" -f $cached) }
            Remove-Item -LiteralPath $cached -Force -ErrorAction SilentlyContinue
        } catch {
            try { if (Test-Path -LiteralPath $cached) { Remove-Item -LiteralPath $cached -Force -ErrorAction SilentlyContinue } } catch { }
        }
    }

    return ''
}

function Ensure-BootstrapWebAppShortcut {
    param(
        [Parameter(Mandatory = $true)][string]$DisplayName,
        [Parameter(Mandatory = $true)][string]$Url,
        [Parameter(Mandatory = $true)][string]$CategoryFolder
    )

    if ([string]::IsNullOrWhiteSpace($DisplayName)) {
        throw 'Web app shortcut sem DisplayName.'
    }
    if ([string]::IsNullOrWhiteSpace($Url)) {
        throw "Web app shortcut '$DisplayName' sem URL."
    }

    $browser = Get-BootstrapWebAppBrowserCandidate
    if ([string]::IsNullOrWhiteSpace([string]$browser.exe)) {
        throw "Nenhum navegador suportado encontrado para web app '$DisplayName' (Edge/Chrome)."
    }

    $desktopPath = Get-BootstrapDesktopPath
    if ([string]::IsNullOrWhiteSpace($desktopPath)) {
        throw "Não foi possível resolver a Área de Trabalho para '$DisplayName'."
    }

    $safeFolder = if ([string]::IsNullOrWhiteSpace($CategoryFolder)) { 'Produtividade' } else { $CategoryFolder.Trim() }
    $targetFolder = Join-Path $desktopPath $safeFolder
    $null = New-Item -Path $targetFolder -ItemType Directory -Force
    $shortcutPath = Join-Path $targetFolder ("{0}.lnk" -f $DisplayName)
    $arguments = "{0}`"{1}`"" -f [string]$browser.argsPrefix, $Url
    $workingDirectory = Split-Path -Path ([string]$browser.exe) -Parent

    $before = ''
    if (Test-Path $shortcutPath) {
        try {
            $before = (Get-Item -LiteralPath $shortcutPath).LastWriteTimeUtc.ToString('o')
        } catch {
            $before = ''
        }
    }

    try {
        $shell = New-Object -ComObject WScript.Shell
        $shortcut = $shell.CreateShortcut($shortcutPath)
        $shortcut.TargetPath = [string]$browser.exe
        $shortcut.Arguments = $arguments
        $shortcut.WorkingDirectory = $workingDirectory
        $iconLocation = Resolve-BootstrapWebAppIconLocation -Url $Url -DisplayName $DisplayName
        if ([string]::IsNullOrWhiteSpace($iconLocation)) { $iconLocation = ("{0},0" -f [string]$browser.exe) }
        $shortcut.IconLocation = $iconLocation
        $shortcut.Description = ("Bootstrap web app: {0}" -f $DisplayName)
        $shortcut.Save()
    } catch {
        throw ("Falha ao criar atalho web app '{0}': {1}" -f $DisplayName, $_.Exception.Message)
    }

    $after = ''
    try {
        $after = (Get-Item -LiteralPath $shortcutPath).LastWriteTimeUtc.ToString('o')
    } catch {
        $after = ''
    }

    return [ordered]@{
        displayName = $DisplayName
        url = $Url
        category = $safeFolder
        path = $shortcutPath
        browser = [string]$browser.browser
        updated = ($before -ne $after)
    }
}

function Ensure-BootstrapWebAppComponent {
    param(
        [Parameter(Mandatory = $true)]$State,
        [Parameter(Mandatory = $true)]$ComponentDef
    )

    $summary = Ensure-BootstrapWebAppShortcut -DisplayName ([string]$ComponentDef.DisplayName) -Url ([string]$ComponentDef.Url) -CategoryFolder ([string]$ComponentDef.CategoryFolder)
    Write-Log ("Web app shortcut: {0} | browser={1} | updated={2} | path={3}" -f [string]$summary.displayName, [string]$summary.browser, [string]$summary.updated, [string]$summary.path)
    return $summary
}

function Get-BootstrapSteamDeckZeroTouchComponents {
    return @('steam', 'playnite', 'heroic', 'rtss', 'epic-games', 'msi-afterburner', 'mem-reduct')
}

function Invoke-BootstrapSteamDeckZeroTouchProvisioning {
    param([Parameter(Mandatory = $true)]$State)

    $catalog = Get-BootstrapComponentCatalog
    $results = @()
    foreach ($componentName in @(Get-BootstrapSteamDeckZeroTouchComponents)) {
        if (-not $catalog.Contains($componentName)) {
            $results += @([ordered]@{ component = $componentName; status = 'skipped'; reason = 'componente nao encontrado no catalogo' })
            continue
        }
        $component = $catalog[$componentName]
        if ([string]$component.Kind -ne 'winget') {
            $results += @([ordered]@{ component = $componentName; status = 'skipped'; reason = "kind nao suportado para zero-touch: $([string]$component.Kind)" })
            continue
        }
        if ([bool]$State.IsDryRun) {
            $results += @([ordered]@{ component = $componentName; status = 'planned'; wingetId = [string]$component.Id })
            continue
        }

        try {
            Ensure-WingetPackage -WingetPath $State.Winget -Id ([string]$component.Id) -DisplayName ([string]$component.DisplayName) -AllowFailureWhenNotAdmin $true
            $results += @([ordered]@{ component = $componentName; status = 'ensured'; wingetId = [string]$component.Id })
        } catch {
            $results += @([ordered]@{ component = $componentName; status = 'failed'; wingetId = [string]$component.Id; error = $_.Exception.Message })
        }
    }

    Write-Log ("SteamDeck zero-touch: {0}" -f ((@($results | ForEach-Object { "{0}:{1}" -f [string]$_.component, [string]$_.status }) -join ', ')))
    return [ordered]@{
        status = 'completed'
        results = @($results)
    }
}

function Get-BootstrapEmulationSharedRuntimeDirectories {
    param([Parameter(Mandatory = $true)]$Layout)

    $directories = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    function Add-EmulationDir {
        param(
            [AllowNull()][string]$Path,
            [bool]$TreatAsFile = $false
        )
        if ([string]::IsNullOrWhiteSpace($Path)) { return }
        $expanded = ConvertTo-BootstrapExpandedPath -Path $Path
        if ([string]::IsNullOrWhiteSpace($expanded)) { return }
        $dir = $expanded
        if ($TreatAsFile -or [System.IO.Path]::HasExtension($expanded)) {
            $dir = Split-Path -Path $expanded -Parent
        }
        if ([string]::IsNullOrWhiteSpace($dir)) { return }
        if (-not $seen.ContainsKey($dir)) {
            $seen[$dir] = $true
            $directories.Add($dir) | Out-Null
        }
    }

    foreach ($top in @('root','emulators','tools','roms','firmware','saves','cache','mods','metadata')) {
        try { Add-EmulationDir -Path ([string]$Layout[$top]) } catch { }
    }

    foreach ($systemName in @('ps1','ps2','ps3','switch')) {
        $system = $null
        try { $system = $Layout.systems[$systemName] } catch { $system = $null }
        if (-not $system) { continue }
        foreach ($key in @('executable')) {
            try { Add-EmulationDir -Path ([string]$system[$key]) -TreatAsFile $true } catch { }
        }
        foreach ($key in @('roms','firmware','keys','saves','storage','nand','cache','mods','metadata')) {
            try {
                $value = $system[$key]
                if ($value -is [System.Collections.IDictionary]) {
                    Add-EmulationDir -Path ([string]$value['path'])
                } else {
                    Add-EmulationDir -Path ([string]$value)
                }
            } catch { }
        }
    }

    return @($directories.ToArray())
}

function Ensure-BootstrapEmulationSharedRuntime {
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$ComponentDef
    )

    $root = ''
    if ($ComponentDef.PSObject.Properties.Name -contains 'sharedRootDefault') {
        $root = ConvertTo-BootstrapExpandedPath -Path ([string]$ComponentDef.sharedRootDefault)
    }
    if ([string]::IsNullOrWhiteSpace($root)) {
        $root = Join-Path $env:USERPROFILE 'Games\Emulation'
    }

    $layout = Get-BootstrapEmulationSharedLayout -Root $root
    $dirs = @(Get-BootstrapEmulationSharedRuntimeDirectories -Layout $layout)
    $created = 0
    $planned = 0
    foreach ($dir in $dirs) {
        if (Test-Path -LiteralPath $dir -PathType Container) { continue }
        if ([bool]$State.DryRun) {
            $planned++
            continue
        }
        $null = New-Item -ItemType Directory -Path $dir -Force -ErrorAction Stop
        $created++
        if ($State.ContainsKey('Changes')) {
            Register-BootstrapChange -State $State -Type Directory -Target $dir -OldValue $null -NewValue 'created' -Operation 'emulation-shared-runtime-directory' -Component 'emulation-shared-runtime'
        }
    }

    Write-Log ("Emulation shared runtime: root={0}; dirs={1}; created={2}; planned={3}; dryRun={4}" -f [string]$layout.root, $dirs.Count, $created, $planned, [bool]$State.DryRun)
    return [ordered]@{
        status = 'completed'
        root = [string]$layout.root
        directories = @($dirs)
        created = $created
        planned = $planned
        dryRun = [bool]$State.DryRun
    }
}

function Ensure-BootstrapSteamDeckHomeDetect {
    # Descoberta + auditoria (read-only) do HOME do Steam Deck. Nao escreve nada; apenas reporta.
    # Guarda o resultado em State para os componentes seguintes (media/frontends) consumirem.
    param([Parameter(Mandatory = $true)][hashtable]$State)

    $info = Get-BootstrapDeckEmulationRoot -ScanVolumes
    if ([bool]$info.found) {
        Write-Log ("steamdeck-home-detect: HOME do Deck em {0} (drive {1}); emulationRoot={2}; accessLevel={3}; writable={4}" -f [string]$info.deckHome, [string]$info.driveLetter, [string]$info.emulationRoot, [string]$info.accessLevel, [bool]$info.writable)
        if (-not [bool]$info.writable) {
            Write-Log 'steamdeck-home-detect: acesso somente-leitura; ROMs/BIOS/midia serao lidos do Deck, mas saves/states/cache ficam locais no Windows ate o acesso virar write-opt-in (desligue Fast Startup, inicie o servico WinBtrfs e reinicie se pendente).' 'WARN'
        }
    } else {
        $reasonText = if (@($info.validationReasons).Count -gt 0) { @($info.validationReasons) -join ', ' } else { 'nenhum volume com arvore Emulation valida' }
        Write-Log ("steamdeck-home-detect: HOME do Deck nao encontrado/validado ({0}) - usando root local Windows para a emulacao." -f $reasonText)
    }

    if ($State.ContainsKey('DeckEmulation')) {
        $State['DeckEmulation'] = $info
    } else {
        $State.Add('DeckEmulation', $info)
    }

    return [ordered]@{
        status            = 'completed'
        found             = [bool]$info.found
        emulationRoot     = [string]$info.emulationRoot
        accessLevel       = [string]$info.accessLevel
        writable          = [bool]$info.writable
        readable          = [bool]$info.readable
        validationReasons = @($info.validationReasons)
        dryRun            = [bool]$State.DryRun
    }
}

function Get-BootstrapDirectoryReparseTarget {
    # Retorna o alvo de uma junction/symlink de diretorio, ou '' se nao for reparse point.
    # Diretorio normal -> ''. Item inexistente -> $null.
    param([Parameter(Mandatory = $true)][string]$Path)

    try {
        $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    } catch {
        return $null
    }
    $isReparse = (($item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -eq [System.IO.FileAttributes]::ReparsePoint)
    if (-not $isReparse) { return '' }
    $target = ''
    try { if ($item.PSObject.Properties.Name -contains 'Target' -and $item.Target) { $target = @($item.Target)[0] } } catch { Write-Verbose $_.Exception.Message }
    return [string]$target
}

function Ensure-BootstrapDeckMediaCanonical {
    # Canonicaliza storage/downloaded_media/<shortname> (pastas reais + junctions de compat),
    # de forma NAO-DESTRUTIVA. Escrita so quando o root de midia e gravavel (Deck write-opt-in
    # ou root local Windows). Em read-only no Deck: apenas relata o plano com WARN.
    param([Parameter(Mandatory = $true)][hashtable]$State)

    $deckInfo = $null
    if ($State.ContainsKey('DeckEmulation')) { $deckInfo = $State['DeckEmulation'] }
    $roots = Resolve-BootstrapEmulationRoots -DeckInfo $deckInfo -ScanVolumes
    $compatMap = Get-BootstrapDeckEmulationMediaCompatMap

    $mediaRoot = [string]$roots.media
    $romsRoot = [string]$roots.roms

    # Midia em Deck somente-leitura nao pode ser escrita; midia local sempre pode.
    $canWrite = ((-not [bool]$roots.deckReadable) -or [bool]$roots.deckWritable)
    $dryRun = ([bool]$State.DryRun -or -not $canWrite)
    if (-not $canWrite) {
        Write-Log ("emulation-deck-shared-media: root de midia em acesso somente-leitura ({0}); apenas planejando, sem escrita." -f [string]$roots.accessLevel) 'WARN'
    }

    # Sistemas a processar: shortnames que ja existem em midia OU em roms (nao cria sistema novo).
    $systems = New-Object System.Collections.Generic.List[string]
    foreach ($base in @($mediaRoot, $romsRoot)) {
        if ([string]::IsNullOrWhiteSpace($base) -or -not (Test-Path -LiteralPath $base -PathType Container)) { continue }
        try {
            foreach ($d in @(Get-ChildItem -LiteralPath $base -Directory -Force -ErrorAction Stop)) {
                if (-not $systems.Contains($d.Name)) { $systems.Add($d.Name) | Out-Null }
            }
        } catch { }
    }

    $created = 0; $planned = 0; $linksCreated = 0; $linksPlanned = 0; $warnings = 0

    foreach ($sn in $systems) {
        $snMedia = [System.IO.Path]::Combine($mediaRoot, $sn)

        foreach ($canon in @($compatMap.canonical)) {
            $canonPath = [System.IO.Path]::Combine($snMedia, $canon)
            if (Test-Path -LiteralPath $canonPath -PathType Container) { continue }
            if ($dryRun) { $planned++; continue }
            $null = New-Item -ItemType Directory -Path $canonPath -Force -ErrorAction Stop
            $created++
            if ($State.ContainsKey('Changes')) {
                Register-BootstrapChange -State $State -Type Directory -Target $canonPath -OldValue $null -NewValue 'created' -Operation 'emulation-media-canonical-dir' -Component 'emulation-deck-shared-media'
            }
        }

        foreach ($alias in $compatMap.compat.Keys) {
            $canon = [string]$compatMap.compat[$alias]
            $aliasPath = [System.IO.Path]::Combine($snMedia, $alias)
            $canonPath = [System.IO.Path]::Combine($snMedia, $canon)

            $existingTarget = Get-BootstrapDirectoryReparseTarget -Path $aliasPath
            if ($null -ne $existingTarget) {
                if ($existingTarget -eq '') {
                    # Pasta real ja ocupa o nome do alias: nunca sobrescreve.
                    Write-Log ("emulation-deck-shared-media: '{0}' ja e uma pasta real (nao-junction) em {1}; mantida, sem alterar." -f $alias, $snMedia) 'WARN'
                    $warnings++
                } elseif (-not (Test-Path -LiteralPath $aliasPath)) {
                    # Reparse point quebrado (alvo inacessivel): nao remove, apenas reporta.
                    Write-Log ("emulation-deck-shared-media: link '{0}' em {1} esta quebrado (alvo '{2}'); reportado, sem remover." -f $alias, $snMedia, $existingTarget) 'WARN'
                    $warnings++
                }
                # Junction valida (existingTarget != '') -> no-op idempotente.
                continue
            }

            # Alias ausente: cria junction apontando para a pasta canonica.
            if ($dryRun) { $linksPlanned++; continue }
            if (-not (Test-Path -LiteralPath $canonPath -PathType Container)) {
                $null = New-Item -ItemType Directory -Path $canonPath -Force -ErrorAction Stop
            }
            try {
                $null = New-Item -ItemType Junction -Path $aliasPath -Target $canonPath -ErrorAction Stop
                $linksCreated++
                if ($State.ContainsKey('Changes')) {
                    Register-BootstrapChange -State $State -Type Directory -Target $aliasPath -OldValue $null -NewValue ('junction->' + $canon) -Operation 'emulation-media-compat-junction' -Component 'emulation-deck-shared-media'
                }
            } catch {
                Write-Log ("emulation-deck-shared-media: falha ao criar junction '{0}' -> '{1}' em {2}: {3}" -f $alias, $canon, $snMedia, $_.Exception.Message) 'WARN'
                $warnings++
            }
        }
    }

    Write-Log ("emulation-deck-shared-media: mediaRoot={0}; sistemas={1}; dirs(created={2},planned={3}); links(created={4},planned={5}); warnings={6}; dryRun={7}" -f $mediaRoot, $systems.Count, $created, $planned, $linksCreated, $linksPlanned, $warnings, $dryRun)
    return [ordered]@{
        status        = 'completed'
        mediaRoot     = $mediaRoot
        systems       = @($systems.ToArray())
        dirsCreated   = $created
        dirsPlanned   = $planned
        linksCreated  = $linksCreated
        linksPlanned  = $linksPlanned
        warnings      = $warnings
        writable      = $canWrite
        dryRun        = $dryRun
    }
}

function Test-BootstrapProcessRunning {
    # True se algum processo com um dos nomes informados estiver em execucao. Sem efeitos.
    param([string[]]$Names = @())
    foreach ($n in $Names) {
        if ([string]::IsNullOrWhiteSpace($n)) { continue }
        try {
            $p = Get-Process -Name $n -ErrorAction SilentlyContinue
            if ($p) { return $true }
        } catch { }
    }
    return $false
}

function Set-BootstrapEsdePaths {
    # Aponta ROMDirectory e MediaDirectory do ES-DE para os roots resolvidos, preservando as
    # demais chaves (merge-safe), com backup antes de escrever. Nao escreve com o ES-DE rodando.
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][string]$RomDir,
        [Parameter(Mandatory = $true)][string]$MediaDir
    )

    $candidates = @(
        (Join-Path $env:USERPROFILE 'ES-DE\settings\es_settings.xml'),
        (Join-Path $env:USERPROFILE '.emulationstation\es_settings.xml')
    )
    $settingsPath = $null
    foreach ($c in $candidates) { if (Test-Path -LiteralPath $c -PathType Leaf) { $settingsPath = $c; break } }
    if (-not $settingsPath) {
        return [ordered]@{ frontend = 'es-de'; status = 'skipped'; reason = 'es_settings.xml nao encontrado' }
    }
    if (Test-BootstrapProcessRunning -Names @('ES-DE', 'emulationstation')) {
        Write-Log 'frontend-pointing: ES-DE em execucao; pulando escrita para nao corromper config.' 'WARN'
        return [ordered]@{ frontend = 'es-de'; status = 'skipped'; reason = 'frontend-running' }
    }

    [xml]$xml = Get-Content -LiteralPath $settingsPath -Raw
    $changed = $false
    $apply = @{ 'ROMDirectory' = $RomDir; 'MediaDirectory' = $MediaDir }
    foreach ($name in $apply.Keys) {
        $value = [string]$apply[$name]
        $node = $xml.SelectSingleNode(("/*/string[@name='{0}']" -f $name))
        if ($null -eq $node) {
            $node = $xml.CreateElement('string')
            $node.SetAttribute('name', $name)
            $node.SetAttribute('value', $value)
            $null = $xml.DocumentElement.AppendChild($node)
            $changed = $true
        } elseif ([string]$node.value -ne $value) {
            $node.value = $value
            $changed = $true
        }
    }

    if (-not $changed) {
        return [ordered]@{ frontend = 'es-de'; status = 'unchanged'; path = $settingsPath }
    }
    if ([bool]$State.DryRun) {
        return [ordered]@{ frontend = 'es-de'; status = 'planned'; path = $settingsPath }
    }

    $backup = Backup-BootstrapFile -Path $settingsPath
    $xml.Save($settingsPath)
    if ($State.ContainsKey('Changes')) {
        Register-BootstrapChange -State $State -Type File -Target $settingsPath -OldValue $backup -NewValue 'esde-paths-pointed' -Operation 'emulation-frontend-pointing' -Component 'emulation-frontend-pointing'
    }
    Write-Log ("frontend-pointing: ES-DE apontado para roms={0}; media={1} ({2})" -f $RomDir, $MediaDir, $settingsPath)
    return [ordered]@{ frontend = 'es-de'; status = 'updated'; path = $settingsPath; backup = $backup }
}

function Set-BootstrapPegasusPaths {
    # Adiciona (sem duplicar) o root de ROMs ao game_dirs do Pegasus. Nao-destrutivo: so anexa.
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][string]$RomDir
    )

    $gameDirsPath = Join-Path $env:APPDATA 'pegasus-frontend\game_dirs.txt'
    $pegasusDir = Split-Path -Parent $gameDirsPath
    if (-not (Test-Path -LiteralPath $pegasusDir -PathType Container)) {
        return [ordered]@{ frontend = 'pegasus'; status = 'skipped'; reason = 'pegasus-frontend nao encontrado' }
    }
    if (Test-BootstrapProcessRunning -Names @('pegasus-fe', 'pegasus-frontend')) {
        Write-Log 'frontend-pointing: Pegasus em execucao; pulando escrita.' 'WARN'
        return [ordered]@{ frontend = 'pegasus'; status = 'skipped'; reason = 'frontend-running' }
    }

    $existing = @()
    if (Test-Path -LiteralPath $gameDirsPath -PathType Leaf) {
        $existing = @(Get-Content -LiteralPath $gameDirsPath -ErrorAction SilentlyContinue)
    }
    if (@($existing | ForEach-Object { $_.Trim() }) -contains $RomDir) {
        return [ordered]@{ frontend = 'pegasus'; status = 'unchanged'; path = $gameDirsPath }
    }
    if ([bool]$State.DryRun) {
        return [ordered]@{ frontend = 'pegasus'; status = 'planned'; path = $gameDirsPath }
    }

    $backup = ''
    if (Test-Path -LiteralPath $gameDirsPath -PathType Leaf) { $backup = Backup-BootstrapFile -Path $gameDirsPath }
    $newContent = @($existing) + @($RomDir)
    Set-Content -LiteralPath $gameDirsPath -Value $newContent -Encoding UTF8
    if ($State.ContainsKey('Changes')) {
        Register-BootstrapChange -State $State -Type File -Target $gameDirsPath -OldValue $backup -NewValue 'pegasus-romdir-appended' -Operation 'emulation-frontend-pointing' -Component 'emulation-frontend-pointing'
    }
    Write-Log ("frontend-pointing: Pegasus game_dir adicionado: {0}" -f $RomDir)
    return [ordered]@{ frontend = 'pegasus'; status = 'updated'; path = $gameDirsPath; backup = $backup }
}

function Get-BootstrapPlaynitePointerGuidance {
    # Playnite guarda as libs de emulacao no proprio DB (LiteDB); nao editamos por fora para nao
    # corromper. Retorna orientacao pointer-only para o usuario.
    param([Parameter(Mandatory = $true)][string]$RomDir)
    $installed = (Test-Path -LiteralPath (Join-Path $env:LOCALAPPDATA 'Playnite\Playnite.DesktopApp.exe')) -or
                 (Test-Path -LiteralPath (Join-Path $env:ProgramFiles 'Playnite\Playnite.DesktopApp.exe'))
    if (-not $installed) {
        return [ordered]@{ frontend = 'playnite'; status = 'skipped'; reason = 'playnite nao encontrado' }
    }
    return [ordered]@{ frontend = 'playnite'; status = 'manual-pointer'; reason = ("Em Playnite > Bibliotecas > Emulacao, aponte os diretorios de ROMs para {0} (nao editamos o DB do Playnite por seguranca)." -f $RomDir) }
}

function Ensure-BootstrapEmulationFrontendPaths {
    # Aponta os frontends Windows detectados para os roots compartilhados resolvidos (Deck ou
    # fallback local), sem duplicar dados. Merge-safe, backup, guard de processo, dry-run.
    param([Parameter(Mandatory = $true)][hashtable]$State)

    $deckInfo = $null
    if ($State.ContainsKey('DeckEmulation')) { $deckInfo = $State['DeckEmulation'] }
    $roots = Resolve-BootstrapEmulationRoots -DeckInfo $deckInfo -ScanVolumes

    $results = New-Object System.Collections.Generic.List[object]
    foreach ($writer in @(
        { Set-BootstrapEsdePaths -State $State -RomDir ([string]$roots.roms) -MediaDir ([string]$roots.media) },
        { Set-BootstrapPegasusPaths -State $State -RomDir ([string]$roots.roms) },
        { Get-BootstrapPlaynitePointerGuidance -RomDir ([string]$roots.roms) }
    )) {
        try { $results.Add((& $writer)) | Out-Null }
        catch { $results.Add([ordered]@{ frontend = 'unknown'; status = 'failed'; reason = $_.Exception.Message }) | Out-Null }
    }

    Write-Log ("emulation-frontend-pointing: roms={0}; media={1}; resultados={2}" -f [string]$roots.roms, [string]$roots.media, ((@($results | ForEach-Object { "{0}:{1}" -f [string]$_.frontend, [string]$_.status }) -join ', ')))
    return [ordered]@{
        status   = 'completed'
        roms     = [string]$roots.roms
        media    = [string]$roots.media
        deckFound = [bool]$roots.deckFound
        results  = @($results.ToArray())
        dryRun   = [bool]$State.DryRun
    }
}

function Get-BootstrapEmulationShortcutTargets {
    # Resolve {DisplayName, Exe} dos emuladores/frontends do perfil de emulacao que estao
    # instalados em disco (via ProbePaths do catalogo + caminhos conhecidos de ES-DE/Pegasus).
    $catalog = Get-BootstrapComponentCatalog
    $targets = New-Object System.Collections.Generic.List[object]
    $seen = @{}

    $componentIds = @('pcsx2', 'rpcs3', 'duckstation', 'playnite', 'hydra-launcher')
    foreach ($id in $componentIds) {
        if (-not $catalog.Contains($id)) { continue }
        $def = $catalog[$id]
        $display = if ($def.PSObject.Properties.Name -contains 'DisplayName' -and $def.DisplayName) { [string]$def.DisplayName } else { $id }
        $probePaths = @()
        if ($def.PSObject.Properties.Name -contains 'ProbePaths') { $probePaths = @($def.ProbePaths) }
        foreach ($p in $probePaths) {
            $exp = ConvertTo-BootstrapExpandedPath -Path ([string]$p)
            if ([string]::IsNullOrWhiteSpace($exp)) { continue }
            if (-not $exp.ToLower().EndsWith('.exe')) { continue }
            if (Test-Path -LiteralPath $exp -PathType Leaf) {
                if (-not $seen.ContainsKey($exp)) {
                    $seen[$exp] = $true
                    $targets.Add([pscustomobject]@{ DisplayName = $display; Exe = $exp }) | Out-Null
                }
                break
            }
        }
    }

    # Frontends sem componente winget dedicado: caminhos conhecidos.
    $extra = [ordered]@{
        'ES-DE'   = @((Join-Path $env:USERPROFILE 'ES-DE\ES-DE.exe'), (Join-Path ${env:ProgramFiles} 'ES-DE\ES-DE.exe'))
        'Pegasus' = @((Join-Path $env:APPDATA 'pegasus-frontend\pegasus-fe.exe'), (Join-Path ${env:LOCALAPPDATA} 'Programs\pegasus-frontend\pegasus-fe.exe'))
    }
    foreach ($name in $extra.Keys) {
        foreach ($exe in $extra[$name]) {
            if ([string]::IsNullOrWhiteSpace($exe)) { continue }
            if (Test-Path -LiteralPath $exe -PathType Leaf) {
                if (-not $seen.ContainsKey($exe)) {
                    $seen[$exe] = $true
                    $targets.Add([pscustomobject]@{ DisplayName = $name; Exe = $exe }) | Out-Null
                }
                break
            }
        }
    }

    return @($targets.ToArray())
}

function Ensure-BootstrapEmulationDesktopShortcuts {
    # Cria a pasta Desktop\Emulacao com atalhos para emuladores/frontends instalados e aplica um
    # icone de pasta (desktop.ini). Nao-destrutivo: reaproveita pasta/atalhos existentes.
    param([Parameter(Mandatory = $true)][hashtable]$State)

    $desktop = Get-BootstrapDesktopPath
    if ([string]::IsNullOrWhiteSpace($desktop)) {
        Write-Log 'emulation-desktop-shortcuts: nao foi possivel resolver a Area de Trabalho.' 'WARN'
        return [ordered]@{ status = 'skipped'; reason = 'desktop-unresolved' }
    }
    $folder = Join-Path $desktop 'Emulação'
    $targets = @(Get-BootstrapEmulationShortcutTargets)
    if ($targets.Count -eq 0) {
        Write-Log 'emulation-desktop-shortcuts: nenhum emulador/frontend instalado detectado; nada a fazer.'
        return [ordered]@{ status = 'completed'; folder = $folder; created = 0; planned = 0; targets = 0; dryRun = [bool]$State.DryRun }
    }

    if ([bool]$State.DryRun) {
        Write-Log ("emulation-desktop-shortcuts: planejado folder={0}; atalhos={1}" -f $folder, $targets.Count)
        return [ordered]@{ status = 'completed'; folder = $folder; created = 0; planned = $targets.Count; targets = $targets.Count; dryRun = $true }
    }

    if (-not (Test-Path -LiteralPath $folder -PathType Container)) {
        $null = New-Item -ItemType Directory -Path $folder -Force -ErrorAction Stop
        if ($State.ContainsKey('Changes')) {
            Register-BootstrapChange -State $State -Type Directory -Target $folder -OldValue $null -NewValue 'created' -Operation 'emulation-desktop-folder' -Component 'emulation-desktop-shortcuts'
        }
    }

    $created = 0
    $shell = New-Object -ComObject WScript.Shell
    foreach ($t in $targets) {
        $lnk = Join-Path $folder (('{0}.lnk' -f $t.DisplayName))
        try {
            $sc = $shell.CreateShortcut($lnk)
            $sc.TargetPath = [string]$t.Exe
            $sc.WorkingDirectory = (Split-Path -Parent ([string]$t.Exe))
            $sc.IconLocation = ('{0},0' -f [string]$t.Exe)
            $sc.Description = ('Emulacao: {0}' -f [string]$t.DisplayName)
            $sc.Save()
            $created++
            if ($State.ContainsKey('Changes')) {
                Register-BootstrapChange -State $State -Type File -Target $lnk -OldValue $null -NewValue ([string]$t.Exe) -Operation 'emulation-desktop-shortcut' -Component 'emulation-desktop-shortcuts'
            }
        } catch {
            Write-Log ("emulation-desktop-shortcuts: falha ao criar atalho '{0}': {1}" -f [string]$t.DisplayName, $_.Exception.Message) 'WARN'
        }
    }

    # Icone da pasta via desktop.ini (merge nao-destrutivo da chave de icone).
    try {
        $iconExe = [string]$targets[0].Exe
        $iniPath = Join-Path $folder 'desktop.ini'
        $iniLines = @()
        if (Test-Path -LiteralPath $iniPath -PathType Leaf) {
            $iniLines = @(Get-Content -LiteralPath $iniPath -ErrorAction SilentlyContinue | Where-Object { $_ -notmatch '^\s*(IconResource|IconFile|IconIndex)\s*=' -and $_ -notmatch '^\s*\[\.ShellClassInfo\]\s*$' })
        }
        $newIni = @('[.ShellClassInfo]', ('IconResource={0},0' -f $iconExe)) + @($iniLines | Where-Object { $_ -and $_.Trim() -ne '' })
        # Remove atributos para reescrever, depois reaplica Hidden+System no arquivo e System na pasta.
        if (Test-Path -LiteralPath $iniPath) { attrib -h -s $iniPath 2>$null | Out-Null }
        Set-Content -LiteralPath $iniPath -Value $newIni -Encoding Default
        attrib +h +s $iniPath 2>$null | Out-Null
        attrib +s $folder 2>$null | Out-Null
        if ($State.ContainsKey('Changes')) {
            Register-BootstrapChange -State $State -Type File -Target $iniPath -OldValue $null -NewValue 'folder-icon' -Operation 'emulation-desktop-icon' -Component 'emulation-desktop-shortcuts'
        }
    } catch {
        Write-Log ("emulation-desktop-shortcuts: falha ao aplicar icone da pasta: {0}" -f $_.Exception.Message) 'WARN'
    }

    Write-Log ("emulation-desktop-shortcuts: folder={0}; atalhos criados/atualizados={1}/{2}" -f $folder, $created, $targets.Count)
    return [ordered]@{ status = 'completed'; folder = $folder; created = $created; planned = 0; targets = $targets.Count; dryRun = $false }
}

function Ensure-BootstrapDualBootManager {
    param([Parameter(Mandatory = $true)][hashtable]$State)

    $info = Get-BootstrapDualBootInfo
    foreach ($rec in @(Get-BootstrapDualBootRecommendations -DualBootInfo $info)) {
        Write-Log ("dualboot-manager: {0}" -f [string]$rec)
    }

    $steamOsEfi = @()
    try { $steamOsEfi = @($info.SteamOsEfiInstallations) } catch { $steamOsEfi = @() }
    if (-not [bool]$info.IsDualBoot -and $steamOsEfi.Count -eq 0) {
        Write-Log 'dualboot-manager: nenhum dual boot SteamOS/GRUB detectado; sem alteracoes.'
        return [ordered]@{ status = 'skipped'; reason = 'dualboot-not-detected'; dryRun = [bool]$State.DryRun }
    }

    $dryRun = [bool]$State.DryRun
    $menu = Ensure-BootstrapSteamOsGrubDualBootMenu -State $State -DryRun:$dryRun
    $fallback = Ensure-BootstrapSteamOsEfiFallbackBootloader -State $State -DryRun:$dryRun
    Write-Log ("dualboot-manager: grubCustomChanged={0}; fallbackChanged={1}; dryRun={2}" -f [bool]$menu.changed, [bool]$fallback.changed, $dryRun)

    return [ordered]@{
        status = 'completed'
        dryRun = $dryRun
        info = $info
        grubCustom = $menu
        fallback = $fallback
    }
}

function Ensure-BootstrapBuiltinComponent {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)]$ComponentDef
    )

    switch ($Name) {
        'emulation-shared-runtime' { return (Ensure-BootstrapEmulationSharedRuntime -State $State -ComponentDef $ComponentDef) }
        'steamdeck-home-detect' { return (Ensure-BootstrapSteamDeckHomeDetect -State $State) }
        'emulation-deck-shared-media' { return (Ensure-BootstrapDeckMediaCanonical -State $State) }
        'msvc-build-env' { return (Ensure-BootstrapMsvcBuildEnv -State $State) }
        'emulation-frontend-pointing' { return (Ensure-BootstrapEmulationFrontendPaths -State $State) }
        'emulation-desktop-shortcuts' { return (Ensure-BootstrapEmulationDesktopShortcuts -State $State) }
        'dualboot-manager' { return (Ensure-BootstrapDualBootManager -State $State) }
        'os-install-detect' { return (Ensure-BootstrapOsInstallDetect -State $State) }
        'os-partition-labels' { return (Ensure-BootstrapPartitionLabels -State $State) }
        'os-install-vm' { return (Ensure-BootstrapOsInstallVm -State $State -ComponentDef $ComponentDef) }
        'os-install-native' { return (Ensure-BootstrapOsInstallNative -State $State -ComponentDef $ComponentDef) }
        'agent-compat-runtime' { return (Ensure-BootstrapAgentCompatRuntime -State $State -ComponentDef $ComponentDef) }
        default { throw "Componente builtin sem executor: $Name" }
    }
}

function Invoke-BootstrapComponent {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [Parameter(Mandatory = $true)][hashtable]$State
    )

    if ($State.Completed.ContainsKey($Name)) { return }

    $catalog = Get-BootstrapComponentCatalog
    $componentDef = $catalog[$Name]
    if (-not $componentDef) { throw "Componente desconhecido: $Name" }

    # JIT Resilience Checks
    if ($Offline -and $componentDef.RequiresNetwork) {
        Write-Log "Offline mode: pulando componente que exige rede: $Name" 'WARN'
        return
    }

    if ($componentDef.EstimatedSizeGB -gt 0) {
        Assert-BootstrapDiskSpace -RequiredGB $componentDef.EstimatedSizeGB
    }

    Write-Log "Executando componente: $Name"

    switch ($componentDef.Kind) {
        'alias' { }
        'builtin' {
            Ensure-BootstrapBuiltinComponent -Name $Name -State $State -ComponentDef $componentDef | Out-Null
        }
        'system-core' { Ensure-BootstrapSystemCore -State $State }
        'git-core' { Ensure-BootstrapGitCore -State $State }
        'node-core' { Ensure-BootstrapNodeCore -State $State }
        'dotnet-core' { Ensure-BootstrapDotNetCore -State $State }
        'python-core' { Ensure-BootstrapPythonCore -State $State }
        'bootstrap-secrets' { Ensure-BootstrapSecrets -State $State }
        'bootstrap-mcps' { Ensure-BootstrapManagedMcps -State $State | Out-Null }
        'vscode-extensions' { Ensure-BootstrapVsCodeExtensions -State $State | Out-Null }
        'vscode-extension' { Ensure-BootstrapSingleVsCodeExtension -State $State -ComponentDef $componentDef | Out-Null }
        'agent-skills' { Ensure-BootstrapAgentSkills -State $State | Out-Null }
        'sevenzip' {
            Ensure-BootstrapSystemCore -State $State
            Ensure-WingetPackage -WingetPath $State.Winget -Id '7zip.7zip' -DisplayName '7-Zip' -AllowFailureWhenNotAdmin $true
            Ensure-7ZipOnPath
        }
        'winget' {
            Ensure-BootstrapSystemCore -State $State
            $preferUserScope = $true
            if ($componentDef.PSObject.Properties.Name -contains 'PreferUserScope') { $preferUserScope = [bool]$componentDef.PreferUserScope }
            $allowFailureWhenNotAdmin = $false
            if ($componentDef.PSObject.Properties.Name -contains 'AllowFailureWhenNotAdmin') { $allowFailureWhenNotAdmin = [bool]$componentDef.AllowFailureWhenNotAdmin }
            $probePaths = @()
            if ($componentDef.PSObject.Properties.Name -contains 'ProbePaths') { $probePaths = @($componentDef.ProbePaths) }
            $appxPackageNames = @()
            if ($componentDef.PSObject.Properties.Name -contains 'AppxPackageNames') { $appxPackageNames = @($componentDef.AppxPackageNames) }
            Ensure-WingetPackage -WingetPath $State.Winget -Id $componentDef.Id -DisplayName $componentDef.DisplayName -PreferUserScope $preferUserScope -AllowFailureWhenNotAdmin $allowFailureWhenNotAdmin -ProbePaths $probePaths -AppxPackageNames $appxPackageNames -State $State -ComponentName $Name
            if ($Name -eq 'notepadpp' -and [string]$State.AppTuningMode -eq 'off') {
                $notepadDefaults = Ensure-BootstrapNotepadPlusPlusDefaults
                if ([string]$notepadDefaults.status -eq 'partial') {
                    if (-not $State.ContainsKey('Warnings')) {
                        $State.Warnings = New-Object System.Collections.Generic.List[string]
                    }
                    $State.Warnings.Add('notepadpp-defaults-partial: Notepad++ defaults parcial; alguns plugins/assets falharam. Veja bootstrap-notepadpp.json e reexecute o componente notepadpp.')
                }
            }
        }
        'chocolatey' {
            $chocoPath = Ensure-BootstrapChocolateyCore -State $State
            $probePaths = @()
            if ($componentDef.PSObject.Properties.Name -contains 'ProbePaths') { $probePaths = @($componentDef.ProbePaths) }
            Ensure-ChocolateyPackage -ChocoPath $chocoPath -Package ([string]$componentDef.Package) -DisplayName ([string]$componentDef.DisplayName) -ProbePaths $probePaths
        }
        'git-lfs' {
            Ensure-GitLfs -State $State
        }
        'wsl-core' {
            Ensure-WslCore -State $State
        }
        'wsl-ui' {
            Ensure-BootstrapSystemCore -State $State
            Ensure-WslUi -WingetPath $State.Winget
        }
        'windows-feature' {
            Ensure-BootstrapWindowsFeatureComponent -State $State -ComponentName $Name -ComponentDef $componentDef | Out-Null
        }
        'windows-capability' {
            Ensure-BootstrapWindowsCapabilityComponent -State $State -ComponentName $Name -ComponentDef $componentDef | Out-Null
        }
        'claude-code' {
            Ensure-BootstrapSystemCore -State $State
            Ensure-ClaudeCode -WingetPath $State.Winget
        }
        'codex-installer' {
            Ensure-BootstrapSystemCore -State $State
            Ensure-CodexInstaller -WingetPath $State.Winget
        }
        'npm' {
            Ensure-BootstrapNodeCore -State $State
            $commandNames = @()
            if ($componentDef.PSObject.Properties.Name -contains 'CommandNames') { $commandNames = @($componentDef.CommandNames) }
            elseif ($componentDef.PSObject.Properties.Name -contains 'CommandName') { $commandNames = @($componentDef.CommandName) }
            $versionArgs = @('--version')
            if ($componentDef.PSObject.Properties.Name -contains 'VersionArgs') { $versionArgs = @($componentDef.VersionArgs) }
            $npmBin = ''
            if ($State.NodeInfo -and $State.NodeInfo.NpmBin) { $npmBin = [string]$State.NodeInfo.NpmBin }
            Ensure-NpmGlobalPackage -NpmCmd $State.NodeInfo.NpmCmd -Package $componentDef.Package -DisplayName $componentDef.DisplayName -CommandNames $commandNames -VersionArgs $versionArgs -NpmBin $npmBin
            if ($Name -eq 'mimo-code' -or ([string]$componentDef.Package) -eq '@mimo-ai/cli') {
                try { Ensure-BootstrapMimoCodeConfig -State $State | Out-Null }
                catch { Write-Log ("MiMo Code: configuracao de provider nao aplicada (nao-bloqueante): {0}" -f $_.Exception.Message) 'WARN' }
            }
            if ($Name -eq 'bonsai-cli' -or ([string]$componentDef.Package) -eq '@bonsai-ai/cli') {
                $bonsaiCommandPath = $null
                if ($State.NodeInfo -and $State.NodeInfo.NpmBin) {
                    $candidate = Join-Path ([string]$State.NodeInfo.NpmBin) 'bonsai.ps1'
                    if (Test-Path -LiteralPath $candidate) { $bonsaiCommandPath = $candidate }
                }
                $repair = Repair-BootstrapBonsaiCliSnapshotHooks -BonsaiCommandPath $bonsaiCommandPath
                if ($repair.Status -eq 'patched') {
                    Write-Log ("Bonsai hooks corrigidos para Git Bash: {0}" -f $repair.Path)
                } elseif ($repair.Status -eq 'already-patched') {
                    Write-Log ("Bonsai hooks ja corrigidos: {0}" -f $repair.Path)
                } else {
                    Write-Log ("Bonsai hooks nao corrigidos automaticamente (status={0})." -f $repair.Status) 'WARN'
                }
            }
        }
        'uvtool' {
            Ensure-BootstrapPythonCore -State $State
            Ensure-UvToolPackage -Package $componentDef.Package -CommandName $componentDef.CommandName -DisplayName $componentDef.DisplayName -VersionArgs $componentDef.VersionArgs
        }
        'goose' {
            Ensure-BootstrapGitCore -State $State
            Ensure-Goose -BashPath $State.GitInfo.Bash
        }
        'opencode' {
            Ensure-BootstrapGitCore -State $State
            Ensure-OpenCode -BashPath $State.GitInfo.Bash
        }
        'openclaw' {
            Assert-BootstrapOpenClawRequestGrant
        }
        'hermes' {
            Ensure-Hermes -State $State
        }
        'os-slim-server' {
            Ensure-BootstrapOsSlimServer -State $State
        }
        'gpedit-hardening' {
            Ensure-BootstrapGpeditHardening -State $State
        }
        'llamacpp-server' {
            Ensure-BootstrapLlamaCppServer -State $State
        }
        'homelab-stack' {
            Ensure-BootstrapHomelabStack -State $State
        }
        'hermes-remote' {
            Ensure-BootstrapHermesRemote -State $State
        }
        'ai-usagebar' {
            Install-BootstrapAiUsagebarComponent -State $State
        }
        'ai-memory' {
            Install-BootstrapAiMemoryComponent -State $State
        }
        'aionui' {
            Install-BootstrapAionUiComponent -State $State
        }
        'ai-proxy-repo' {
            try {
                $toolName = if ($componentDef.PSObject.Properties.Name -contains 'ToolName') { [string]$componentDef.ToolName } else { [string]$Name }
                $catalog = Get-BootstrapAiToolCatalog
                $normalizedToolName = Normalize-BootstrapAiToolName -ToolName $toolName
                if (-not $catalog.Contains($normalizedToolName)) { throw "AI proxy desconhecido no componente '$Name': $toolName" }
                $result = Install-BootstrapAiProxyManagedTool -ToolName $normalizedToolName -CatalogEntry $catalog[$normalizedToolName] -InstallRoot (Get-BootstrapAiInstallRoot -InstallRoot '') -ProjectRoot $PSScriptRoot -DryRun:([bool]$State.DryRun)
                Write-Log ("AI proxy {0}: {1} ({2})" -f [string]$result['tool'], [string]$result['status'], [string]$result['baseUrl'])
            } catch {
                $msg = [string]$_.Exception.Message
                if ($script:SkipManualRequirements -and $msg.StartsWith('Diretorio existe mas nao e clone git gerenciado:')) {
                    Write-Log ("Pulando {0} por requisito manual (repo nao gerenciado). {1}" -f $Name, $msg) 'WARN'
                    Register-BootstrapComponentSkip -State $State -ComponentName $Name -Reason 'manual-requirement' -Message $msg -Action 'fix-or-delete-directory'
                    return
                }
                throw
            }
        }
        'ai-proxy-suite' {
            try {
                $summary = Install-BootstrapAiProxySuiteManagedTool -InstallRoot (Get-BootstrapAiInstallRoot -InstallRoot '') -ProjectRoot $PSScriptRoot -DryRun:([bool]$State.DryRun)
                Write-Log ("AI proxy suite: {0}; manifest={1}; default={2} {3}" -f [string]$summary['status'], [string]$summary['manifestPath'], [string]$summary['defaultProvider'], [string]$summary['defaultModel'])
                if (-not [bool]$State.DryRun -and [string]$summary['status'] -in @('error','blocked','auth-failed')) {
                    throw ("AI proxy suite nao ficou operacional: {0}" -f [string]$summary['status'])
                }
            } catch {
                $msg = [string]$_.Exception.Message
                if ($script:SkipManualRequirements -and $msg.StartsWith('Diretorio existe mas nao e clone git gerenciado:')) {
                    Write-Log ("Pulando {0} por requisito manual (repo nao gerenciado). {1}" -f $Name, $msg) 'WARN'
                    Register-BootstrapComponentSkip -State $State -ComponentName $Name -Reason 'manual-requirement' -Message $msg -Action 'fix-or-delete-directory'
                    return
                }
                throw
            }
        }
        'winhance' {
            Ensure-BootstrapSystemCore -State $State
            Install-BootstrapWinhanceComponent -State $State -ComponentDef $componentDef | Out-Null
        }
        'amd-nebula-driver' {
            Ensure-BootstrapSystemCore -State $State
            Install-BootstrapAmdNebulaDriverComponent -State $State -ComponentDef $componentDef | Out-Null
        }
        'steamdeck-zip-driver' {
            Ensure-BootstrapSystemCore -State $State
            Install-BootstrapSteamDeckZipDriverComponent -State $State -ComponentDef $componentDef | Out-Null
        }
        'claude-config' {
            Ensure-BootstrapGitCore -State $State
            Ensure-ClaudeCodeDefaults -GitBashPath $State.GitInfo.Bash
            Ensure-ClaudeHookConfigsHealthy -GitBashPath $State.GitInfo.Bash
        }
        'claude-plugins' {
            Ensure-ClaudeCodePlugins -State $State | Out-Null
        }
        'openwebui' {
            Ensure-OpenWebUI -State $State
        }
        'repo-clone' {
            Ensure-BootstrapGitCore -State $State
            $cloneBase = [string](@($State.CloneBaseDir)[0]).Trim()
            $targetNameRaw = $componentDef.TargetName
            if ($null -eq $targetNameRaw) {
                throw "repo-clone: TargetName ausente para o componente '$Name'. Corrija o catalogo."
            }
            if (($targetNameRaw -is [System.Collections.IEnumerable]) -and -not ($targetNameRaw -is [string])) {
                $names = @($targetNameRaw | ForEach-Object { [string]$_ } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
                if ($names.Count -gt 1) {
                    throw ("repo-clone: TargetName deve ser uma unica string; recebido {0} valores ({1}) para '{2}'." -f $names.Count, ($names -join ', '), $Name)
                }
                $targetName = if ($names.Count -gt 0) { $names[0].Trim() } else { '' }
            } else {
                $targetName = [string]$targetNameRaw
                $targetName = $targetName.Trim()
            }
            if ([string]::IsNullOrWhiteSpace($targetName)) {
                throw "repo-clone: TargetName vazio ou invalido para o componente '$Name'."
            }
            if ([string]::IsNullOrWhiteSpace($cloneBase)) {
                throw "repo-clone: CloneBaseDir vazio ou invalido no estado do bootstrap."
            }
            $targetDir = Join-Path $cloneBase $targetName
            Ensure-RepoClone -GitExe $State.GitInfo.Git -RepoUrl ([string]$componentDef.RepoUrl) -TargetDir $targetDir
        }
        'workspace' {
            Ensure-WorkspaceLayout -State $State
        }
        'steamdeck-shell-menu' {
            Install-BootstrapSteamDeckShellMenu -DryRun:$State.IsDryRun | Out-Null
        }
        'steamdeck-zero-touch' {
            Invoke-BootstrapSteamDeckZeroTouchProvisioning -State $State | Out-Null
        }
        'steamdeck-sharedvram-launch-options' {
            $settingsBundle = Get-BootstrapSteamDeckSettingsData -RequestedSteamDeckVersion ([string]$State.RequestedSteamDeckVersion) -ResolvedSteamDeckVersion ([string]$State.ResolvedSteamDeckVersion)
            $launchResult = Apply-BootstrapSharedVramLaunchOptions -Settings $settingsBundle.Data -DryRun:$State.IsDryRun
            Write-Log ("SteamDeck sharedvram apply: status={0} reason={1}" -f [string]$launchResult.Status, [string]$launchResult.Reason)
        }
        'web-app-shortcut' {
            Ensure-BootstrapSystemCore -State $State
            Ensure-BootstrapWebAppComponent -State $State -ComponentDef $componentDef | Out-Null
        }
        'steamdeck-tools' {
            Ensure-BootstrapSteamDeckToolsRuntime -State $State
        }
        'steamdeck-settings' {
            Ensure-BootstrapSteamDeckSettings -State $State | Out-Null
        }
        'steamdeck-automation' {
            Ensure-BootstrapSteamDeckAutomation -State $State
        }
        'manual-required' {
            Ensure-BootstrapManualRequirement -State $State -ComponentDef $componentDef
        }
        default {
            throw "Tipo de componente nao suportado: $($componentDef.Kind)"
        }
    }

    if (Test-BootstrapComponentSkipped -State $State -ComponentName $Name) {
        return
    }

    Refresh-SessionPath
    $State.Completed[$Name] = $true
}

function Get-BootstrapExecutionPlanLines {
    param(
        [Parameter(Mandatory = $true)]$Selection,
        [Parameter(Mandatory = $true)]$Resolution,
        [Parameter(Mandatory = $true)][string]$ResolvedWorkspaceRoot,
        [Parameter(Mandatory = $true)][string]$ResolvedCloneBaseDir,
        [string]$ResolvedSteamDeckVersion = '',
        [Parameter(Mandatory = $true)][string]$ResolvedHostHealthMode,
        [AllowNull()]$AppTuningPlan = $null
    )

    $catalog = Get-BootstrapComponentCatalog
    $usesSteamDeckFlow = Get-BootstrapUsesSteamDeckFlow -Selection $Selection -Resolution $Resolution
    $lines = New-Object System.Collections.Generic.List[string]
    $stageLookup = [ordered]@{
        runtime = New-Object System.Collections.Generic.List[string]
        payload = New-Object System.Collections.Generic.List[string]
        config = New-Object System.Collections.Generic.List[string]
        verify = New-Object System.Collections.Generic.List[string]
    }
    $manualBlockers = New-Object System.Collections.Generic.List[string]

    foreach ($componentName in @($Resolution.ResolvedComponents)) {
        $componentDef = $catalog[$componentName]
        if (-not $componentDef) { continue }
        $stage = Get-BootstrapComponentStage -ComponentDef $componentDef
        if (-not $stageLookup.Contains($stage)) {
            $stageLookup[$stage] = New-Object System.Collections.Generic.List[string]
        }
        $stageLookup[$stage].Add($componentName)
        if ($componentDef.Kind -eq 'manual-required') {
            $manualBlockers.Add($componentName)
        }
    }

    $lines.Add(('Selected profiles: {0}' -f ($(if (@($Selection.Profiles).Count -gt 0) { @($Selection.Profiles) -join ', ' } else { '-' }))))
    $lines.Add(('Selected components: {0}' -f ($(if (@($Selection.Components).Count -gt 0) { @($Selection.Components) -join ', ' } else { '-' }))))
    $lines.Add(('Excluded components: {0}' -f ($(if (@($Selection.Excludes).Count -gt 0) { @($Selection.Excludes) -join ', ' } else { '-' }))))
    $lines.Add(('Expanded profiles: {0}' -f ($(if (@($Resolution.ExpandedProfiles).Count -gt 0) { @($Resolution.ExpandedProfiles) -join ', ' } else { '-' }))))
    $lines.Add(('Resolved components: {0}' -f ($(if (@($Resolution.ResolvedComponents).Count -gt 0) { @($Resolution.ResolvedComponents) -join ', ' } else { '-' }))))
    $lines.Add(('WorkspaceRoot: {0}' -f $ResolvedWorkspaceRoot))
    $lines.Add(('CloneBaseDir: {0}' -f $ResolvedCloneBaseDir))
    $lines.Add(('Host health mode: {0}' -f $ResolvedHostHealthMode))
    if ($AppTuningPlan) {
        $lines.Add(('AppTuning: {0}' -f [string]$AppTuningPlan.mode))
        $lines.Add(('AppTuning categories: {0}' -f ($(if (@($AppTuningPlan.categories).Count -gt 0) { @($AppTuningPlan.categories) -join ', ' } else { '-' }))))
        $lines.Add(('AppTuning items: {0}' -f ($(if (@($AppTuningPlan.items).Count -gt 0) { @($AppTuningPlan.items | ForEach-Object { $_.id }) -join ', ' } else { '-' }))))
        $lines.Add(('AppTuning skipped: {0}' -f ($(if (@($AppTuningPlan.skippedItems).Count -gt 0) { @($AppTuningPlan.skippedItems) -join ', ' } else { '-' }))))
    }

    if ($usesSteamDeckFlow) {
        $lines.Add(('Resolved steam deck version: {0}' -f $ResolvedSteamDeckVersion))
    }

    if ($usesSteamDeckFlow) {
        $lines.Add('Audit:')
        foreach ($componentName in @($Resolution.ResolvedComponents)) {
            $componentDef = $catalog[$componentName]
            if (-not $componentDef) { continue }
            $stage = Get-BootstrapComponentStage -ComponentDef $componentDef
            $dependsOn = if (@($componentDef.DependsOn).Count -gt 0) { @($componentDef.DependsOn) -join ', ' } else { '-' }
            $valueReason = if ($componentDef.PSObject.Properties.Name -contains 'ValueReason') { [string]$componentDef.ValueReason } else { [string]$componentDef.Description }
            $provisioning = if ($componentDef.PSObject.Properties.Name -contains 'Provisioning') { [string]$componentDef.Provisioning } else { $componentDef.Kind }
            $lines.Add(('  - {0} | stage: {1} | depends: {2} | provisioning: {3} | gain: {4}' -f $componentName, $stage, $dependsOn, $provisioning, $valueReason))
        }

        $lines.Add(('Runtimes: {0}' -f ($(if ($stageLookup['runtime'].Count -gt 0) { @($stageLookup['runtime'].ToArray()) -join ', ' } else { '-' }))))
        $lines.Add(('Payloads: {0}' -f ($(if ($stageLookup['payload'].Count -gt 0) { @($stageLookup['payload'].ToArray()) -join ', ' } else { '-' }))))
        $lines.Add(('Config: {0}' -f ($(if ($stageLookup['config'].Count -gt 0) { @($stageLookup['config'].ToArray()) -join ', ' } else { '-' }))))
        $lines.Add(('Verify: {0}' -f ($(if ($stageLookup['verify'].Count -gt 0) { @($stageLookup['verify'].ToArray()) -join ', ' } else { '-' }))))
        $lines.Add(('Manual blockers: {0}' -f ($(if ($manualBlockers.Count -gt 0) { @($manualBlockers.ToArray()) -join ', ' } else { '-' }))))
        $lines.Add('Console mode: HANDHELD=Game - Steam Deck, DOCKED_TV=Game - Steam Deck, DOCKED_MONITOR=Desktop/Dev')
        $lines.Add('Console shell: Steam Big Picture first, Playnite fallback, soft shell keeps explorer.exe intact')
        $lines.Add('Handheld tweaks: hibernation=enabled, UTC clock, login-after-sleep=off, ms-gamebar=enabled, touch-keyboard=enabled')
        $lines.Add('Steam Deck tooling: RTSS, AMD Adrenalin, CRU, Steam Deck Tools (Controller, PowerControl, FanControl, PerformanceOverlay)')
        $lines.Add('Advanced input opt-in: Handheld Companion (Auto-TDP/gyro/DS4/QuickTools) and GlosSI (global Steam Input)')
        $lines.Add('Steam Input guardrail: review/disable Desktop Layout when external input stack is active to avoid double input')
        $lines.Add('Unknown external: UNCLASSIFIED_EXTERNAL -> UI classification -> fallback Desktop/Dev')
        $lines.Add('Console readiness audit: Steam, Playnite, Steam Deck Tools, Steam Input Desktop Layout, RTSS, AMD Adrenalin, CRU, SoundSwitch, ModeWatcher')
    }

    if ($ResolvedHostHealthMode -ne 'off') {
        $policy = Get-BootstrapHostHealthPolicy -Mode $ResolvedHostHealthMode
        $lines.Add(('Host health cleanup: {0}' -f (@($policy.Cleanup) -join ', ')))
        $lines.Add(('Host health startup: {0}' -f ((@($policy.StartupDisableSafe) + @($policy.ScheduledTasksDisable | ForEach-Object { "$($_.TaskPath)$($_.TaskName)" }) + @($policy.ServiceAdjustments | ForEach-Object { "$($_.Name)=$($_.StartType)" })) -join ', ')))
        $lines.Add(('Host health registry-fixes: {0}' -f (@($policy.RegistryFixes) -join ', ')))
        $lines.Add(('Host health game-mode: HANDHELD={0}, DOCKED_TV={1}, DOCKED_MONITOR={2}' -f $policy.SessionProfiles.HANDHELD, $policy.SessionProfiles.DOCKED_TV, $policy.SessionProfiles.DOCKED_MONITOR))
        $lines.Add(('Host health bloat: {0}' -f ($(if (@($policy.AppxRemove).Count -gt 0) { @($policy.AppxRemove) -join ', ' } else { '-' }))))
        $lines.Add(('Host health verify: {0}' -f (@($policy.Verify) -join ', ')))
    }

    return @($lines.ToArray())
}

function Get-BootstrapExecutionPlanText {
    param(
        [Parameter(Mandatory = $true)]$Selection,
        [Parameter(Mandatory = $true)]$Resolution,
        [Parameter(Mandatory = $true)][string]$ResolvedWorkspaceRoot,
        [Parameter(Mandatory = $true)][string]$ResolvedCloneBaseDir,
        [string]$ResolvedSteamDeckVersion = '',
        [Parameter(Mandatory = $true)][string]$ResolvedHostHealthMode,
        [AllowNull()]$AppTuningPlan = $null
    )

    return ((Get-BootstrapExecutionPlanLines -Selection $Selection -Resolution $Resolution -ResolvedWorkspaceRoot $ResolvedWorkspaceRoot -ResolvedCloneBaseDir $ResolvedCloneBaseDir -ResolvedSteamDeckVersion $ResolvedSteamDeckVersion -ResolvedHostHealthMode $ResolvedHostHealthMode -AppTuningPlan $AppTuningPlan) -join [Environment]::NewLine)
}

function Show-BootstrapExecutionPlan {
    param(
        [Parameter(Mandatory = $true)]$Selection,
        [Parameter(Mandatory = $true)]$Resolution,
        [Parameter(Mandatory = $true)][string]$ResolvedWorkspaceRoot,
        [Parameter(Mandatory = $true)][string]$ResolvedCloneBaseDir,
        [string]$ResolvedSteamDeckVersion = '',
        [Parameter(Mandatory = $true)][string]$ResolvedHostHealthMode,
        [AllowNull()]$AppTuningPlan = $null
    )

    foreach ($line in (Get-BootstrapExecutionPlanLines -Selection $Selection -Resolution $Resolution -ResolvedWorkspaceRoot $ResolvedWorkspaceRoot -ResolvedCloneBaseDir $ResolvedCloneBaseDir -ResolvedSteamDeckVersion $ResolvedSteamDeckVersion -ResolvedHostHealthMode $ResolvedHostHealthMode -AppTuningPlan $AppTuningPlan)) {
        Write-Output $line
    }
}

function Get-BootstrapPreviewData {
    param(
        [string[]]$SelectedProfiles = @(),
        [string[]]$SelectedComponents = @(),
        [string[]]$ExcludedComponents = @(),
        [string]$RequestedSteamDeckVersion = 'Auto',
        [AllowNull()][string]$RequestedHostHealthMode = $null,
        [AllowNull()][string]$RequestedAppTuningMode = $null,
        [string[]]$RequestedAppTuningCategories = @(),
        [string[]]$RequestedAppTuningItems = @(),
        [string[]]$ExcludedAppTuningItems = @(),
        [string]$RequestedWorkspaceRoot = '',
        [string]$ExplicitCloneBaseDir = ''
    )

    $selection = New-BootstrapSelectionObject -SelectedProfiles $SelectedProfiles -SelectedComponents $SelectedComponents -ExcludedComponents $ExcludedComponents -SelectedHostHealth $RequestedHostHealthMode -SelectedAppTuning $RequestedAppTuningMode -SelectedAppTuningCategories $RequestedAppTuningCategories -SelectedAppTuningItems $RequestedAppTuningItems -ExcludedAppTuningItems $ExcludedAppTuningItems
    $resolvedWorkspaceRoot = if ([string]::IsNullOrWhiteSpace($RequestedWorkspaceRoot)) { Get-BootstrapDefaultWorkspaceRoot } else { $RequestedWorkspaceRoot }
    $resolution = Resolve-BootstrapComponents -SelectedProfiles $selection.Profiles -SelectedComponents $selection.Components -ExcludedComponents $selection.Excludes
    $resolvedCloneBaseDir = Resolve-BootstrapCloneBaseDir -ExplicitCloneBaseDir $ExplicitCloneBaseDir -ResolvedWorkspaceRoot $resolvedWorkspaceRoot -ResolvedComponents $resolution.ResolvedComponents
    $usesSteamDeckFlow = Get-BootstrapUsesSteamDeckFlow -Selection $selection -Resolution $resolution
    $resolvedSteamDeckVersion = if ($usesSteamDeckFlow) { Get-BootstrapResolvedSteamDeckVersion -RequestedVersion $RequestedSteamDeckVersion } else { '' }
    $resolvedHostHealthMode = if ($selection.HostHealth) { $selection.HostHealth } else { Get-BootstrapDefaultHostHealthMode -Selection $selection -Resolution $resolution }
    $appTuningPlan = Resolve-BootstrapAppTuningSelection -Mode $selection.AppTuning -Categories $selection.AppTuningCategories -Items $selection.AppTuningItems -ExcludedItems $selection.ExcludedAppTuningItems -Selection $selection -Resolution $resolution
    $adminReasons = Get-BootstrapAdminReasons -Resolution $resolution -ResolvedHostHealthMode $resolvedHostHealthMode -UsesSteamDeckFlow:$usesSteamDeckFlow -AppTuningPlan $appTuningPlan
    $planLines = Get-BootstrapExecutionPlanLines -Selection $selection -Resolution $resolution -ResolvedWorkspaceRoot $resolvedWorkspaceRoot -ResolvedCloneBaseDir $resolvedCloneBaseDir -ResolvedSteamDeckVersion $resolvedSteamDeckVersion -ResolvedHostHealthMode $resolvedHostHealthMode -AppTuningPlan $appTuningPlan
    $componentCatalog = Get-BootstrapComponentCatalog
    $reversibilitySummary = [ordered]@{ full = 0; partial = 0; manual = 0; none = 0; unknown = 0 }
    foreach ($componentName in @($resolution.ResolvedComponents)) {
        $def = $componentCatalog[[string]$componentName]
        if (-not $def) { $reversibilitySummary.unknown++; continue }
        $rev = Get-BootstrapComponentReversibility -ComponentDef $def
        $key = [string]$rev.reversible
        if ([string]::IsNullOrWhiteSpace($key) -or -not $reversibilitySummary.Contains($key)) { $key = 'unknown' }
        $reversibilitySummary[$key]++
    }

    return [ordered]@{
        Selection = $selection
        Resolution = $resolution
        UsesSteamDeckFlow = $usesSteamDeckFlow
        ResolvedSteamDeckVersion = $resolvedSteamDeckVersion
        ResolvedHostHealthMode = $resolvedHostHealthMode
        ResolvedAppTuningMode = [string]$appTuningPlan.mode
        AppTuningPlan = $appTuningPlan
        ResolvedWorkspaceRoot = $resolvedWorkspaceRoot
        ResolvedCloneBaseDir = $resolvedCloneBaseDir
        AdminReasons = @($adminReasons)
        ReversibilitySummary = $reversibilitySummary
        PlanLines = @($planLines)
        PlanText = ($planLines -join [Environment]::NewLine)
    }
}

function Write-BootstrapCommandSummary {
    param(
        [Parameter(Mandatory = $true)][string]$Label,
        [Parameter(Mandatory = $true)][string]$CommandName,
        [string[]]$Args = @('--version')
    )

    $commandPath = Resolve-CommandPath -Name $CommandName
    if (-not $commandPath) {
        Write-Log ("{0}: NAO ENCONTRADO" -f $Label) 'WARN'
        return
    }

    if ($commandPath -match '\\Microsoft\\WindowsApps\\') {
        Write-Log ("{0}: NAO ENCONTRADO (atalho Microsoft Store em PATH, nao binario real): {1}" -f $Label, $commandPath) 'WARN'
        return
    }

    Write-Log ("{0}: {1} ({2})" -f $Label, (Invoke-NativeFirstLine -Exe $commandPath -Args $Args), $commandPath)
}

function Write-BootstrapDotNetSdksSummary {
    $labelSdks = 'dotnet_sdks'
    $commandPath = Resolve-CommandPath -Name 'dotnet'
    if (-not $commandPath) {
        Write-Log ("{0}: NAO ENCONTRADO" -f $labelSdks) 'WARN'
        return
    }
    if ($commandPath -match '\\Microsoft\\WindowsApps\\') {
        Write-Log ("{0}: NAO ENCONTRADO (atalho Microsoft Store em PATH, nao binario real): {1}" -f $labelSdks, $commandPath) 'WARN'
        return
    }
    try {
        $raw = (& $commandPath @('--list-sdks') 2>&1 | ForEach-Object { [string]$_ }) -join [Environment]::NewLine
        if ([string]::IsNullOrWhiteSpace($raw)) {
            Write-Log ("{0}: (vazio; possivel host sem SDK) ({1})" -f $labelSdks, $commandPath) 'WARN'
            return
        }
        $oneLine = ($raw.Trim() -replace "`r?`n", ' | ')
        if ($oneLine.Length -gt 500) { $oneLine = $oneLine.Substring(0, 497) + '...' }
        Write-Log ("{0}: {1} ({2})" -f $labelSdks, $oneLine, $commandPath)
    } catch {
        Write-Log ("{0}: ERRO ({1}) ({2})" -f $labelSdks, $_.Exception.Message, $commandPath) 'WARN'
    }
}

function Write-BootstrapDoctorToolSummary {
    param(
        [Parameter(Mandatory = $true)][string]$Label,
        [Parameter(Mandatory = $true)][string]$CommandName,
        [string[]]$ToolArgs = @('--version')
    )

    $commandPath = Resolve-CommandPath -Name $CommandName
    if (-not $commandPath) {
        Write-Log ("{0}: NAO ENCONTRADO" -f $Label) 'WARN'
        return
    }

    if ($commandPath -match '\.ps1$') {
        Write-Log ("{0}: script ({1})" -f $Label, $commandPath)
        return
    }

    try {
        $firstLine = [string](Invoke-NativeFirstLine -Exe $commandPath -Args $ToolArgs)
        if ([string]::IsNullOrWhiteSpace($firstLine)) {
            Write-Log ("{0}: (sem saida) ({1})" -f $Label, $commandPath) 'WARN'
            return
        }
        Write-Log ("{0}: {1} ({2})" -f $Label, $firstLine.Trim(), $commandPath)
    } catch {
        Write-Log ("{0}: ERRO ({1}) ({2})" -f $Label, $_.Exception.Message, $commandPath) 'WARN'
    }
}

function Invoke-BootstrapDoctorCommandProbe {
    param(
        [Parameter(Mandatory = $true)][string]$Label,
        [Parameter(Mandatory = $true)][string]$CommandName,
        [string[]]$CommandArgs = @('--version'),
        [int]$TimeoutMs = 3000
    )

    $started = [Diagnostics.Stopwatch]::StartNew()
    $commandPath = Resolve-CommandPath -Name $CommandName
    if (-not $commandPath) {
        $started.Stop()
        return [ordered]@{
            id = $Label
            status = 'missing'
            severity = 'warning'
            path = ''
            version = ''
            durationMs = [long]$started.ElapsedMilliseconds
            timedOut = $false
            summary = "$Label nao encontrado."
        }
    }

    $stdout = ''
    $stderr = ''
    $timedOut = $false
    $exitCode = $null
    $startFailed = $false
    try {
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $runCommandPath = $commandPath
        $runArgs = @($CommandArgs)
        if ($commandPath -match '\.(cmd|bat)$') {
            $cmdHost = Join-Path $env:SystemRoot 'System32\cmd.exe'
            if (-not (Test-Path -LiteralPath $cmdHost)) { $cmdHost = 'cmd.exe' }
            $runCommandPath = $cmdHost
            $runArgs = @('/d','/c',$commandPath) + @($CommandArgs)
        } elseif ($commandPath -match '\.ps1$') {
            $psHost = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
            if (-not (Test-Path -LiteralPath $psHost)) { $psHost = 'powershell.exe' }
            $runCommandPath = $psHost
            $runArgs = @('-NoProfile','-ExecutionPolicy','Bypass','-File',$commandPath) + @($CommandArgs)
        }
        $psi.FileName = $runCommandPath
        $psi.UseShellExecute = $false
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $psi.CreateNoWindow = $true
        $process = New-Object System.Diagnostics.Process
        $process.StartInfo = $psi
        if ($runArgs -and $runArgs.Count -gt 0) {
            $psi.Arguments = (($runArgs | ForEach-Object {
                        $argText = [string]$_
                        if ($argText -match '[\s"]') { '"' + ($argText -replace '"', '\"') + '"' } else { $argText }
                    }) -join ' ')
        }
        if (-not $process.Start()) { throw "Falha ao iniciar $CommandName" }
        $stdoutTask = $process.StandardOutput.ReadToEndAsync()
        $stderrTask = $process.StandardError.ReadToEndAsync()
        if (-not $process.WaitForExit([Math]::Max(500, $TimeoutMs))) {
            $timedOut = $true
            try { $process.Kill() } catch { Write-Verbose $_.Exception.Message }
        } else {
            $exitCode = $process.ExitCode
            $stdout = [string]$stdoutTask.Result
            $stderr = [string]$stderrTask.Result
        }
    } catch {
        $startFailed = $true
        $stderr = [string]$_.Exception.Message
    }
    $started.Stop()

    $firstLine = ''
    foreach ($line in @($stdout -split "`r?`n") + @($stderr -split "`r?`n")) {
        if (-not [string]::IsNullOrWhiteSpace([string]$line)) {
            $firstLine = ([string]$line).Trim()
            break
        }
    }
    if ($firstLine.Length -gt 240) { $firstLine = $firstLine.Substring(0, 237) + '...' }

    $status = 'healthy'
    $severity = 'info'
    $summary = if ([string]::IsNullOrWhiteSpace($firstLine)) { "$Label encontrado." } else { "${Label}: $firstLine" }
    if ($timedOut) {
        $status = 'timeout'
        $severity = 'warning'
        $summary = "$Label excedeu timeout de ${TimeoutMs}ms."
    } elseif ($startFailed) {
        $status = 'warning'
        $severity = 'warning'
    } elseif ($null -ne $exitCode -and [int]$exitCode -ne 0) {
        $status = 'warning'
        $severity = 'warning'
    }

    return [ordered]@{
        id = $Label
        status = $status
        severity = $severity
        path = [string]$commandPath
        version = $firstLine
        exitCode = $exitCode
        durationMs = [long]$started.ElapsedMilliseconds
        timedOut = [bool]$timedOut
        summary = $summary
    }
}

function Get-BootstrapGithubActiveTokenState {
    param([AllowNull()]$SecretsData = $null)

    $result = [ordered]@{
        tokenAvailable = $false
        tokenSource = 'none'
        credentialId = ''
        displayName = ''
        validationState = 'missing'
    }

    try {
        $secretsInput = $SecretsData
        if ($null -eq $secretsInput) {
            $bundle = Get-BootstrapSecretsData
            $secretsInput = $bundle.Data
        }
        $normalized = Normalize-BootstrapSecretsData -Secrets $secretsInput

        $githubProvider = @{}
        $activeCredentialId = ''
        $credential = @{}
        if (Test-BootstrapMapContainsKey -Map $normalized.providers -Key 'github') {
            $githubProvider = ConvertTo-BootstrapHashtable -InputObject $normalized.providers['github']
            $activeCredentialId = [string]$githubProvider['activeCredential']
            if (-not [string]::IsNullOrWhiteSpace($activeCredentialId) -and
                (Test-BootstrapMapContainsKey -Map $githubProvider -Key 'credentials') -and
                (Test-BootstrapMapContainsKey -Map $githubProvider['credentials'] -Key $activeCredentialId)) {
                $credential = ConvertTo-BootstrapHashtable -InputObject $githubProvider['credentials'][$activeCredentialId]
                $result['credentialId'] = $activeCredentialId
                $result['displayName'] = [string]$credential['displayName']
                if ((Test-BootstrapMapContainsKey -Map $credential -Key 'validation') -and ($credential['validation'] -is [System.Collections.IDictionary])) {
                    $validation = ConvertTo-BootstrapHashtable -InputObject $credential['validation']
                    $result['validationState'] = [string]$validation['state']
                } else {
                    $result['validationState'] = 'unknown'
                }
            }
        }

        $validated = Get-BootstrapActiveProviders -SecretsData $normalized -RequirePassedValidation
        if ((Test-BootstrapMapContainsKey -Map $validated -Key 'github') -and
            -not [string]::IsNullOrWhiteSpace([string]$validated['github']['token'])) {
            $result['tokenAvailable'] = $true
            $result['tokenSource'] = 'bootstrap-secrets:validated-active'
            $result['validationState'] = 'passed'
            if ([string]::IsNullOrWhiteSpace([string]$result['credentialId'])) {
                $result['credentialId'] = [string]$validated['github']['credentialId']
                $result['displayName'] = [string]$validated['github']['displayName']
            }
            return $result
        }

        $active = Get-BootstrapActiveProviders -SecretsData $normalized
        if ((Test-BootstrapMapContainsKey -Map $active -Key 'github') -and
            -not [string]::IsNullOrWhiteSpace([string]$active['github']['token'])) {
            $result['tokenAvailable'] = $true
            $result['tokenSource'] = 'bootstrap-secrets:active-fallback'
            if ([string]::IsNullOrWhiteSpace([string]$result['credentialId'])) {
                $result['credentialId'] = [string]$active['github']['credentialId']
                $result['displayName'] = [string]$active['github']['displayName']
            }
        }
    } catch {
        $result['tokenAvailable'] = $false
        $result['tokenSource'] = 'error'
        $result['validationState'] = 'error'
    }

    return $result
}

function Get-BootstrapGithubCliAuthHealth {
    param(
        [AllowNull()]$SecretsData = $null,
        [int]$TimeoutMs = 3000
    )

    $started = [Diagnostics.Stopwatch]::StartNew()
    $tokenState = Get-BootstrapGithubActiveTokenState -SecretsData $SecretsData
    $ghPath = Resolve-CommandPath -Name 'gh'
    if (-not $ghPath) {
        $started.Stop()
        return [ordered]@{
            id = 'github-cli-auth'
            status = 'missing'
            severity = 'warning'
            ghInstalled = $false
            ghAuthStatus = 'missing'
            path = ''
            exitCode = $null
            durationMs = [long]$started.ElapsedMilliseconds
            timedOut = $false
            tokenAvailable = [bool]$tokenState['tokenAvailable']
            tokenSource = [string]$tokenState['tokenSource']
            credentialId = [string]$tokenState['credentialId']
            validationState = [string]$tokenState['validationState']
            summary = 'GitHub CLI (gh) nao encontrado.'
            recommendedAction = 'Instale o componente github-cli; depois aplique github-cli-agent-auth ou use gh auth login manualmente.'
        }
    }

    $probe = Invoke-BootstrapDoctorCommandProbe -Label 'github-cli-auth' -CommandName 'gh' -CommandArgs @('auth','status') -TimeoutMs $TimeoutMs
    $probeMap = ConvertTo-BootstrapHashtable -InputObject $probe
    $timedOut = $false
    if (Test-BootstrapMapContainsKey -Map $probeMap -Key 'timedOut') { $timedOut = [bool]$probeMap['timedOut'] }
    $exitCode = $null
    if (Test-BootstrapMapContainsKey -Map $probeMap -Key 'exitCode') { $exitCode = $probeMap['exitCode'] }
    $probeStatus = if (Test-BootstrapMapContainsKey -Map $probeMap -Key 'status') { [string]$probeMap['status'] } else { 'warning' }
    $started.Stop()

    $tokenAvailable = [bool]$tokenState['tokenAvailable']
    $status = 'warning'
    $severity = 'warning'
    $ghAuthStatus = 'unauthenticated'
    $recommendedAction = 'Adicione token GitHub em bootstrap-secrets ou rode gh auth login manualmente.'
    if ($timedOut) {
        $status = 'critical'
        $severity = 'warning'
        $ghAuthStatus = 'timeout'
        $recommendedAction = 'Revise instalacao do gh; probe de autenticacao excedeu timeout.'
    } elseif ($probeStatus -eq 'healthy' -or ($null -ne $exitCode -and [int]$exitCode -eq 0)) {
        $status = 'healthy'
        $severity = 'info'
        $ghAuthStatus = 'authenticated'
        $recommendedAction = 'Nenhuma acao necessaria.'
    } elseif ($tokenAvailable) {
        $recommendedAction = 'Aplique github-cli-agent-auth para injetar GH_TOKEN nos agentes; gh auth login segue opcional e manual.'
    }

    $summary = switch ($ghAuthStatus) {
        'authenticated' { 'GitHub CLI autenticado.' }
        'timeout' { 'GitHub CLI auth status excedeu timeout.' }
        default {
            if ($tokenAvailable) {
                'GitHub CLI sem auth interativo; token GitHub ativo disponivel para agentes.'
            } else {
                'GitHub CLI sem autenticacao e sem token GitHub ativo.'
            }
        }
    }

    return [ordered]@{
        id = 'github-cli-auth'
        status = $status
        severity = $severity
        ghInstalled = $true
        ghAuthStatus = $ghAuthStatus
        path = [string]$ghPath
        exitCode = $exitCode
        durationMs = [long]$started.ElapsedMilliseconds
        timedOut = $timedOut
        tokenAvailable = $tokenAvailable
        tokenSource = [string]$tokenState['tokenSource']
        credentialId = [string]$tokenState['credentialId']
        validationState = [string]$tokenState['validationState']
        summary = $summary
        recommendedAction = $recommendedAction
        probeSummary = if (Test-BootstrapMapContainsKey -Map $probeMap -Key 'summary') { [string]$probeMap['summary'] } else { '' }
    }
}

function Get-BootstrapSecretsManifestHealth {
    $path = Get-BootstrapSecretsPath
    if (-not (Test-Path -LiteralPath $path)) {
        return [ordered]@{
            id = 'secrets'
            status = 'missing'
            severity = 'warning'
            path = $path
            state = 'missing'
            summary = 'bootstrap-secrets.json ausente.'
        }
    }

    try {
        $raw = Microsoft.PowerShell.Management\Get-Content -LiteralPath $path -Raw -Encoding utf8
        $parsed = ConvertTo-BootstrapHashtable -InputObject (ConvertFrom-BootstrapJsonText -Text $raw)
        $protected = Test-BootstrapSecretsProtectedEnvelope -Value $parsed
        $metadata = if ($parsed.ContainsKey('metadata')) { ConvertTo-BootstrapHashtable -InputObject $parsed['metadata'] } else { @{} }
        $version = if ($metadata.ContainsKey('version')) { [string]$metadata['version'] } else { '' }
        if ($protected) {
            return [ordered]@{
                id = 'secrets'
                status = 'healthy'
                severity = 'info'
                path = $path
                state = 'protected'
                version = $version
                summary = 'bootstrap-secrets.json protegido com DPAPI.'
            }
        }
        $state = if ($version -eq '2') { 'needsMigration' } else { 'plaintext' }
        return [ordered]@{
            id = 'secrets'
            status = 'warning'
            severity = 'warning'
            path = $path
            state = $state
            version = $version
            summary = "bootstrap-secrets.json nao esta protegido ($state)."
        }
    } catch {
        return [ordered]@{
            id = 'secrets'
            status = 'corrupt'
            severity = 'error'
            path = $path
            state = 'corrupt'
            summary = "bootstrap-secrets.json invalido/corrompido: $($_.Exception.Message)"
        }
    }
}

function Get-BootstrapVersionHealth {
    $versionPath = Join-Path $PSScriptRoot 'version.json'
    $version = ''
    if (Test-Path -LiteralPath $versionPath) {
        try {
            $versionJson = Microsoft.PowerShell.Management\Get-Content -LiteralPath $versionPath -Raw -Encoding utf8 | ConvertFrom-Json -ErrorAction Stop
            if ($versionJson.PSObject.Properties['version']) { $version = [string]$versionJson.version }
        } catch {
            $version = ''
        }
    }

    $commit = ''
    try {
        $git = Resolve-CommandPath -Name 'git'
        if ($git -and -not [string]::IsNullOrWhiteSpace($PSScriptRoot)) {
            $commit = [string]((& $git -C $PSScriptRoot rev-parse --short HEAD 2>$null | Select-Object -First 1))
        }
    } catch {
        $commit = ''
    }

    return [ordered]@{
        id = 'version'
        status = 'healthy'
        severity = 'info'
        version = $version
        commit = $commit
        summary = ("version={0} commit={1}" -f $(if ([string]::IsNullOrWhiteSpace($version)) { 'unknown' } else { $version }), $(if ([string]::IsNullOrWhiteSpace($commit)) { 'unknown' } else { $commit }))
    }
}

function Get-BootstrapUiContractHealth {
    try {
        $contract = Get-BootstrapUiContract
        $capabilities = if ($contract.Contains('capabilities')) { $contract['capabilities'] } else { @{} }
        return [ordered]@{
            id = 'ui-contract'
            status = 'healthy'
            severity = 'info'
            schemaVersion = [string]$contract['schemaVersion']
            capabilities = $capabilities
            summary = ("UI contract {0}" -f [string]$contract['schemaVersion'])
        }
    } catch {
        return [ordered]@{
            id = 'ui-contract'
            status = 'error'
            severity = 'error'
            schemaVersion = ''
            summary = "Falha ao gerar UI contract: $($_.Exception.Message)"
        }
    }
}

function Get-BootstrapWslDoctorHealth {
    $wsl = Resolve-CommandPath -Name 'wsl.exe'
    if (-not $wsl) {
        return [ordered]@{
            id = 'wsl'
            status = 'missing'
            severity = 'warning'
            path = ''
            summary = 'wsl.exe nao encontrado.'
        }
    }
    try {
        $probe = Get-BootstrapWslStatusProbe -WslExe $wsl -TimeoutMs 5000
        $text = ([string]$probe.stdout + "`n" + [string]$probe.stderr).Trim()
        $status = if ([bool]$probe.timedOut) { 'timeout' } elseif (Test-WslCorruptionText -Text $text) { 'corrupt' } else { 'healthy' }
        return [ordered]@{
            id = 'wsl'
            status = $status
            severity = $(if ($status -eq 'healthy') { 'info' } else { 'warning' })
            path = $wsl
            timedOut = [bool]$probe.timedOut
            exitCode = $probe.exitCode
            summary = $(if ([string]::IsNullOrWhiteSpace($text)) { "WSL probe $status." } else { (($text -split "`r?`n") | Select-Object -First 1) })
        }
    } catch {
        return [ordered]@{
            id = 'wsl'
            status = 'error'
            severity = 'warning'
            path = $wsl
            summary = "Falha no probe WSL: $($_.Exception.Message)"
        }
    }
}

function Get-BootstrapWslRepairCorruptionKind {
    param(
        [AllowNull()][string]$Text,
        [bool]$AppxPresent = $false,
        [bool]$ServicePresent = $false
    )

    if (-not [string]::IsNullOrWhiteSpace($Text) -and ([string]$Text -match '(?i)REGDB_E_CLASSNOTREG')) { return 'REGDB_E_CLASSNOTREG' }
    if (-not $AppxPresent) { return 'missingAppx' }
    if (-not $ServicePresent) { return 'missingService' }
    return 'unknown'
}

function New-BootstrapWslRepairDoctorReport {
    $started = [Diagnostics.Stopwatch]::StartNew()
    $wslPath = Resolve-CommandPath -Name 'wsl.exe'
    if (-not $wslPath) {
        try {
            $candidate = Join-Path $env:SystemRoot 'System32\wsl.exe'
            if (Test-Path -LiteralPath $candidate) { $wslPath = $candidate }
        } catch {
            $wslPath = ''
        }
    }

    $appxPresent = $false
    try {
        $appxPresent = [bool](Test-BootstrapAppxPackageInstalled -Names @('MicrosoftCorporationII.WindowsSubsystemForLinux', 'Microsoft.WSL'))
    } catch {
        $appxPresent = $false
    }

    $servicePresent = $false
    $serviceStatus = ''
    try {
        $service = Get-Service -Name 'LxssManager' -ErrorAction Stop
        $servicePresent = $true
        $serviceStatus = [string]$service.Status
    } catch {
        $servicePresent = $false
    }

    $timedOut = $false
    $exitCode = $null
    $probeText = ''
    if (-not [string]::IsNullOrWhiteSpace($wslPath)) {
        try {
            $probe = Get-BootstrapWslStatusProbe -WslExe $wslPath -TimeoutMs 5000
            $timedOut = [bool]$probe.timedOut
            $exitCode = $probe.exitCode
            $probeText = ([string]$probe.stdout + "`n" + [string]$probe.stderr)
        } catch {
            $probeText = [string]$_.Exception.Message
        }
    }

    $corruptionDetected = $false
    if (-not [string]::IsNullOrWhiteSpace($probeText) -and (Test-WslCorruptionText -Text $probeText)) { $corruptionDetected = $true }
    if (-not $appxPresent -or -not $servicePresent) { $corruptionDetected = $true }
    $kind = Get-BootstrapWslRepairCorruptionKind -Text $probeText -AppxPresent:$appxPresent -ServicePresent:$servicePresent
    $requiresAdmin = $corruptionDetected -and ($kind -in @('REGDB_E_CLASSNOTREG','missingAppx','missingService','unknown'))
    $isAdmin = [bool](Test-IsAdmin)

    $status = 'healthy'
    $action = 'Nenhuma acao necessaria.'
    if ([string]::IsNullOrWhiteSpace($wslPath)) {
        $status = 'warning'
        $kind = 'missingAppx'
        $requiresAdmin = $true
        $action = 'Abra PowerShell como administrador e execute .\bootstrap-tools.ps1 -Component wsl-core -DryRun; depois confirme RepairPlan.'
    } elseif ($timedOut) {
        $status = 'blocked'
        $action = 'Probe WSL excedeu timeout curto; rode Doctor novamente ou confirme RepairPlan pela UI se persistir.'
    } elseif ($corruptionDetected) {
        if ($isAdmin) { $status = 'critical' } else { $status = 'blocked' }
        $action = 'Abra PowerShell como administrador e execute RepairPlan confirmado para repair-wsl-registration.'
    } elseif ($servicePresent -and $serviceStatus -notin @('Running','Stopped')) {
        $status = 'warning'
        $action = 'Revise LxssManager e reinicie o Windows se WSL falhar.'
    }

    $started.Stop()
    return [ordered]@{
        schemaVersion = 1
        status = $status
        corruptionDetected = [bool]$corruptionDetected
        corruptionKind = $kind
        requiresAdmin = [bool]$requiresAdmin
        recommendedAction = $action
        durationMs = [long]$started.ElapsedMilliseconds
        wslPresent = -not [string]::IsNullOrWhiteSpace($wslPath)
        appxPresent = [bool]$appxPresent
        servicePresent = [bool]$servicePresent
        serviceStatus = $serviceStatus
        timedOut = [bool]$timedOut
        exitCode = $exitCode
    }
}

function Get-BootstrapDoctorProviderEnvNames {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseSingularNouns','')]
    param([Parameter(Mandatory = $true)][string]$ProviderName)
    switch ($ProviderName) {
        'openai' { return @('OPENAI_API_KEY', 'OPENAI_ADMIN_KEY') }
        'anthropic' { return @('ANTHROPIC_API_KEY') }
        'github' { return @('GH_TOKEN', 'GITHUB_TOKEN') }
        'openrouter' { return @('OPENROUTER_API_KEY') }
        'zai' { return @('ZAI_API_KEY') }
        'deepseek' { return @('DEEPSEEK_API_KEY') }
        default { return @() }
    }
}

function Test-BootstrapDoctorAnyEnvPresent {
    param([string[]]$Names = @())
    foreach ($name in @($Names)) {
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        $value = [Environment]::GetEnvironmentVariable($name, 'Process')
        if (-not [string]::IsNullOrWhiteSpace($value)) { return $true }
        $value = [Environment]::GetEnvironmentVariable($name, 'User')
        if (-not [string]::IsNullOrWhiteSpace($value)) { return $true }
    }
    return $false
}

function Get-BootstrapDoctorProviderVaultState {
    param(
        [Parameter(Mandatory = $true)][string]$ProviderName,
        [Parameter(Mandatory = $true)]$SecretsData
    )

    $result = [ordered]@{
        present = $false
        validationState = 'missing'
        lastErrorCode = ''
    }
    try {
        $normalized = Normalize-BootstrapSecretsData -Secrets $SecretsData
        if (-not (Test-BootstrapMapContainsKey -Map $normalized.providers -Key $ProviderName)) { return $result }
        $provider = ConvertTo-BootstrapHashtable -InputObject $normalized.providers[$ProviderName]
        $activeCredentialId = [string]$provider['activeCredential']
        if ([string]::IsNullOrWhiteSpace($activeCredentialId)) { return $result }
        if (-not (Test-BootstrapMapContainsKey -Map $provider -Key 'credentials')) { return $result }
        if (-not (Test-BootstrapMapContainsKey -Map $provider['credentials'] -Key $activeCredentialId)) { return $result }
        $credential = ConvertTo-BootstrapHashtable -InputObject $provider['credentials'][$activeCredentialId]
        if (-not [string]::IsNullOrWhiteSpace([string]$credential['secret'])) {
            $result['present'] = $true
        }
        if ((Test-BootstrapMapContainsKey -Map $credential -Key 'validation') -and ($credential['validation'] -is [System.Collections.IDictionary])) {
            $validation = ConvertTo-BootstrapHashtable -InputObject $credential['validation']
            $result['validationState'] = [string]$validation['state']
            $message = [string]$validation['message']
            if ($message -match '(?i)\b(401|403|expired|invalid|unauthorized)\b') {
                $result['lastErrorCode'] = [string]$matches[1]
            }
        } elseif ([bool]$result['present']) {
            $result['validationState'] = 'unknown'
        }
    } catch {
        $result['validationState'] = 'unknown'
    }
    return $result
}

function Convert-BootstrapDoctorValidationStatus {
    param(
        [AllowNull()][string]$ValidationState,
        [AllowNull()][string]$LastErrorCode,
        [bool]$HasSecret = $false
    )

    $state = [string]$ValidationState
    $code = [string]$LastErrorCode
    if ($state -eq 'passed') { return 'present' }
    if ($code -match '(?i)expired') { return 'expired' }
    if ($state -eq 'failed' -or $code -match '^(401|403)$|(?i)invalid|unauthorized') { return 'rejected' }
    if ($HasSecret) { return 'present' }
    return 'missing'
}

function New-BootstrapSecretsDoctorReport {
    param([AllowNull()]$SecretsData = $null)

    if ($null -eq $SecretsData) {
        try {
            $bundle = Get-BootstrapSecretsData
            $SecretsData = $bundle.Data
        } catch {
            $SecretsData = Get-BootstrapSecretsTemplate
        }
    }

    $providers = New-Object System.Collections.Generic.List[object]
    foreach ($providerName in @('openai','anthropic','github','openrouter','zai')) {
        $envPresent = Test-BootstrapDoctorAnyEnvPresent -Names (Get-BootstrapDoctorProviderEnvNames -ProviderName $providerName)
        $vault = Get-BootstrapDoctorProviderVaultState -ProviderName $providerName -SecretsData $SecretsData
        $oauthPresent = $false
        if ($providerName -eq 'github') {
            try {
                $gh = Get-BootstrapGithubCliAuthHealth -SecretsData $SecretsData -TimeoutMs 3000
                $oauthPresent = ([string]$gh['ghAuthStatus'] -eq 'authenticated')
            } catch {
                $oauthPresent = $false
            }
        }
        $hasSecret = ($envPresent -or [bool]$vault['present'] -or $oauthPresent)
        $status = Convert-BootstrapDoctorValidationStatus -ValidationState ([string]$vault['validationState']) -LastErrorCode ([string]$vault['lastErrorCode']) -HasSecret:$hasSecret
        $source = 'missing'
        if ($envPresent) { $source = 'env' } elseif ([bool]$vault['present']) { $source = 'vault' } elseif ($oauthPresent) { $source = 'oauth' }
        $action = if ($status -eq 'missing') { "Configure credencial local para $providerName." } elseif ($status -in @('rejected','expired')) { "Rotacione credencial local de $providerName." } else { 'Nenhuma acao necessaria.' }
        $providers.Add([ordered]@{
            provider = $providerName
            status = $status
            source = $source
            envPresent = [bool]$envPresent
            vaultPresent = [bool]$vault['present']
            oauthPresent = [bool]$oauthPresent
            lastErrorCode = [string]$vault['lastErrorCode']
            recommendedAction = $action
        })
    }

    return [ordered]@{
        schemaVersion = 1
        generatedAt = (Get-Date).ToString('o')
        providers = @($providers.ToArray())
    }
}

function Read-BootstrapAiUsagebarConfigReport {
    $result = [ordered]@{
        configured = $false
        primaryVendor = ''
        enabledVendors = @()
        vendors = [ordered]@{}
        configPaths = @()
    }

    $enabled = New-Object System.Collections.Generic.List[string]
    foreach ($path in @(Get-BootstrapAiUsagebarNativeConfigPathSet)) {
        if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path)) { continue }
        $result['configured'] = $true
        $result['configPaths'] += @([ordered]@{ path = $path; present = $true })
        $currentSection = ''
        try {
            $lines = @(Microsoft.PowerShell.Management\Get-Content -LiteralPath $path -Encoding utf8 -ErrorAction Stop)
            foreach ($line in @($lines)) {
                $text = ([string]$line).Trim()
                if ($text -match '^\[([A-Za-z0-9_\-]+)\]$') {
                    $currentSection = $matches[1].ToLowerInvariant()
                    if (-not $result['vendors'].Contains($currentSection)) {
                        $result['vendors'][$currentSection] = [ordered]@{ enabled = $false; inlineApiKeyPresent = $false; apiKeyEnv = '' }
                    }
                    continue
                }
                if ($text -match '^(primary)\s*=\s*"?([^"#]+)"?') {
                    $result['primaryVendor'] = ([string]$matches[2]).Trim().Trim('"').ToLowerInvariant()
                    continue
                }
                if ([string]::IsNullOrWhiteSpace($currentSection)) { continue }
                if (-not $result['vendors'].Contains($currentSection)) {
                    $result['vendors'][$currentSection] = [ordered]@{ enabled = $false; inlineApiKeyPresent = $false; apiKeyEnv = '' }
                }
                if ($text -match '^enabled\s*=\s*true\b') {
                    $result['vendors'][$currentSection]['enabled'] = $true
                    if (-not (@($enabled.ToArray()) -contains $currentSection)) { $enabled.Add($currentSection) }
                } elseif ($text -match '^(api_key|admin_key)\s*=') {
                    $result['vendors'][$currentSection]['inlineApiKeyPresent'] = $true
                } elseif ($text -match '^(api_key_env|admin_key_env)\s*=\s*"?([^"#]+)"?') {
                    $result['vendors'][$currentSection]['apiKeyEnv'] = ([string]$matches[2]).Trim().Trim('"')
                }
            }
        } catch {
            $result['configPaths'] += @([ordered]@{ path = $path; present = $true; error = $_.Exception.Message })
        }
    }
    $result['enabledVendors'] = @($enabled.ToArray())
    return $result
}

function Get-BootstrapAiUsagebarVendorStatus {
    param(
        [Parameter(Mandatory = $true)][string]$Vendor,
        [Parameter(Mandatory = $true)]$Config,
        [switch]$ValidateOpenRouter
    )

    $vendorInfo = if ($Config['vendors'].Contains($Vendor)) { $Config['vendors'][$Vendor] } else { [ordered]@{ enabled = $false; inlineApiKeyPresent = $false; apiKeyEnv = '' } }
    $envNames = Get-BootstrapDoctorProviderEnvNames -ProviderName $Vendor
    if (-not [string]::IsNullOrWhiteSpace([string]$vendorInfo['apiKeyEnv'])) { $envNames = @([string]$vendorInfo['apiKeyEnv']) }
    $envPresent = Test-BootstrapDoctorAnyEnvPresent -Names $envNames
    $inlinePresent = [bool]$vendorInfo['inlineApiKeyPresent']
    $status = if ($envPresent -or $inlinePresent) { 'present' } else { 'missing' }
    $lastErrorCode = ''

    if ($Vendor -eq 'openrouter' -and $ValidateOpenRouter -and $envPresent) {
        $secret = [Environment]::GetEnvironmentVariable('OPENROUTER_API_KEY', 'Process')
        if ([string]::IsNullOrWhiteSpace($secret)) { $secret = [Environment]::GetEnvironmentVariable('OPENROUTER_API_KEY', 'User') }
        try {
            $providerDefinition = Get-BootstrapSecretsProviderDefinitionTemplate -ProviderName 'openrouter'
            $validation = Test-BootstrapSecretsProviderCredential -ProviderName 'openrouter' -ProviderDefinition $providerDefinition -CredentialId 'env-openrouter' -Credential @{ secret = $secret; secretKind = 'apiKey' } -TimeoutSeconds 10
            $message = [string]$validation['message']
            if ($message -match '(?i)\b(401|403|expired|invalid|unauthorized)\b') { $lastErrorCode = [string]$matches[1] }
            $status = Convert-BootstrapDoctorValidationStatus -ValidationState ([string]$validation['state']) -LastErrorCode $lastErrorCode -HasSecret:$true
        } catch {
            $status = 'unknown'
            $lastErrorCode = 'probe-error'
        }
    }

    return [ordered]@{
        status = $status
        envPresent = [bool]$envPresent
        inlineApiKeyPresent = [bool]$inlinePresent
        enabled = [bool]$vendorInfo['enabled']
        lastErrorCode = $lastErrorCode
    }
}

function New-BootstrapAiUsagebarDoctorReport {
    param([switch]$ValidateOpenRouter)

    $commandPath = ''
    $catalog = Get-BootstrapAiToolCatalog
    if ($catalog.Contains('ai-usagebar')) {
        try {
            $commandPath = Resolve-BootstrapAiToolCommandPath -CatalogEntry $catalog['ai-usagebar'] -InstallRoot (Get-BootstrapAiInstallRoot -InstallRoot '')
        } catch {
            $commandPath = ''
        }
    }
    $probe = Invoke-BootstrapAiUsagebarCommandProbe -CommandPath $commandPath
    $version = [string]$probe['version']
    if ([string]::IsNullOrWhiteSpace($commandPath)) { $commandPath = [string]$probe['path'] }

    $config = Read-BootstrapAiUsagebarConfigReport
    $nativeConfigured = [bool]$config['configured']
    $wslConfigured = $false
    try {
        $wslConfigured = [bool](Test-BootstrapAiUsagebarWslConfigured)
    } catch {
        $wslConfigured = $false
    }
    $vendors = [ordered]@{}
    foreach ($vendor in @('openai','anthropic','openrouter','zai','deepseek')) {
        $vendors[$vendor] = Get-BootstrapAiUsagebarVendorStatus -Vendor $vendor -Config $config -ValidateOpenRouter:$ValidateOpenRouter
    }

    return [ordered]@{
        schemaVersion = 1
        installed = ([bool]$probe['ok'] -or $wslConfigured)
        configured = ($nativeConfigured -or $wslConfigured)
        nativeConfigured = $nativeConfigured
        wslConfigured = $wslConfigured
        commandStatus = [string]$probe['status']
        commandMessage = [string]$probe['message']
        primaryVendor = [string]$config['primaryVendor']
        enabledVendors = @($config['enabledVendors'])
        commandPath = [string]$commandPath
        version = $version
        configPaths = @($config['configPaths'])
        vendors = $vendors
    }
}

function Test-BootstrapAiMemoryServerReachable {
    param([string]$ServerUrl = '')
    $url = if ([string]::IsNullOrWhiteSpace($ServerUrl)) { Get-BootstrapAiMemoryServerUrl } else { $ServerUrl }
    foreach ($suffix in @('/health', '/')) {
        try {
            [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
            $response = Invoke-WebRequest -Uri ($url.TrimEnd('/') + $suffix) -UseBasicParsing -TimeoutSec 3 -ErrorAction Stop
            if ($null -ne $response) { return $true }
        } catch {
            $status = $null
            try { $status = $_.Exception.Response.StatusCode.value__ } catch { $status = $null }
            # Qualquer resposta HTTP (mesmo 404/401) prova que o servidor esta de pe.
            if ($null -ne $status) { return $true }
        }
    }
    return $false
}

function New-BootstrapAiMemoryDoctorReport {
    $catalog = Get-BootstrapAiToolCatalog
    $entry = if ($catalog.Contains('ai-memory')) { $catalog['ai-memory'] } else { $null }
    $exePath = Get-BootstrapAiMemoryExePath -InstallRoot ''
    $installed = (-not [string]::IsNullOrWhiteSpace($exePath))
    $version = ''
    $commandStatus = 'missing'
    if ($installed -and $null -ne $entry) {
        $probe = Invoke-BootstrapDoctorCommandProbe -Label 'ai-memory-version' -CommandName $exePath -CommandArgs @('--version') -TimeoutMs 5000
        $commandStatus = [string]$probe['status']
        if ($probe.Contains('firstLine')) { $version = [string]$probe['firstLine'] }
        if ([string]::IsNullOrWhiteSpace($version)) { $version = [string]$entry['ReleaseTag'] }
    }

    $serverUrl = Get-BootstrapAiMemoryServerUrl
    $serverReachable = $false
    try { $serverReachable = [bool](Test-BootstrapAiMemoryServerReachable -ServerUrl $serverUrl) } catch { $serverReachable = $false }

    $agents = @()
    try { $agents = Get-BootstrapAiMemoryDetectedAgents } catch { $agents = @() }

    # Sinal de wiring: marcadores ai-memory nos arquivos de config dos agentes nativos.
    $mcpConfigured = $false
    $userHome = Get-BootstrapUserHomePath
    $markerCandidates = New-Object System.Collections.Generic.List[string]
    if (-not [string]::IsNullOrWhiteSpace($userHome)) {
        $markerCandidates.Add((Join-Path $userHome '.claude.json')) | Out-Null
        $markerCandidates.Add((Join-Path $userHome '.claude\settings.json')) | Out-Null
        $markerCandidates.Add((Join-Path $userHome '.codex\config.toml')) | Out-Null
    }
    foreach ($candidate in @($markerCandidates.ToArray())) {
        if ([string]::IsNullOrWhiteSpace($candidate) -or -not (Test-Path -LiteralPath $candidate)) { continue }
        try {
            $text = Microsoft.PowerShell.Management\Get-Content -LiteralPath $candidate -Raw -ErrorAction Stop
            if ($text -match '(?i)ai-memory') { $mcpConfigured = $true; break }
        } catch {
        }
    }

    # Status sync SDCard
    $sdCardFound = $false
    $sdCardPath = ''
    $lastSync = ''
    try {
        $found = Find-BootstrapAiMemorySdCard
        if ($found) {
            $sdCardFound = $true
            $sdCardPath = $found
            $manifestPath = Join-Path $found '.phasezero-sync.json'
            if (Test-Path -LiteralPath $manifestPath) {
                try {
                    $syncManifest = Microsoft.PowerShell.Management\Get-Content -LiteralPath $manifestPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                    $lastSync = [string]$syncManifest.lastSync
                } catch { }
            }
        }
    } catch { }

    return [ordered]@{
        schemaVersion  = 1
        installed      = $installed
        configured     = ($installed -and ($serverReachable -or $mcpConfigured))
        serverReachable = $serverReachable
        mcpConfigured  = $mcpConfigured
        commandStatus  = $commandStatus
        commandPath    = [string]$exePath
        serverUrl      = [string]$serverUrl
        version        = [string]$version
        detectedAgents = @($agents)
        sdCardFound    = $sdCardFound
        sdCardPath     = [string]$sdCardPath
        lastSync       = [string]$lastSync
        notes          = 'Beta: servidor loopback opt-in; handoff entre Claude Code/Codex/OpenCode. SDCard sync automatico.'
    }
}

function Get-BootstrapAiConfigProviderEnvMap {
    return @(
        [ordered]@{ provider = 'openai'; env = @('OPENAI_API_KEY'); targetApps = @('openCode','hermes','continue','vsCode','cursor','windsurf','trae','roo','cline','zed','zCode','kilo') }
        [ordered]@{ provider = 'anthropic'; env = @('ANTHROPIC_API_KEY'); targetApps = @('hermes','continue','vsCode','cursor','windsurf','trae','roo','cline','zed','zCode') }
        [ordered]@{ provider = 'gemini'; env = @('GEMINI_API_KEY','GOOGLE_API_KEY'); targetApps = @('continue','vsCode','cursor','windsurf','trae','roo','cline') }
        [ordered]@{ provider = 'openrouter'; env = @('OPENROUTER_API_KEY'); targetApps = @('openCode','hermes','continue','kilo','aiUsagebar') }
        [ordered]@{ provider = 'deepseek'; env = @('DEEPSEEK_API_KEY'); targetApps = @('openCode','hermes','continue','kilo','aiUsagebar') }
        [ordered]@{ provider = 'xai'; env = @('XAI_API_KEY'); targetApps = @('continue','vsCode') }
        [ordered]@{ provider = 'dashscope'; env = @('DASHSCOPE_API_KEY','QWEN_API_KEY'); targetApps = @('continue') }
        [ordered]@{ provider = 'zai'; env = @('ZAI_API_KEY'); targetApps = @('hermes','continue','aiUsagebar') }
        [ordered]@{ provider = 'github'; env = @('GH_TOKEN','GITHUB_TOKEN'); targetApps = @('claudeCode','claudeDesktop','vsCode','cursor','windsurf','trae','continue','zed','zCode','openCode') }
    )
}

function Get-BootstrapAiConfigKnownTargetList {
    return @(
        'claudeCode','claudeDesktop','vsCode','cursor','windsurf','trae','roo','cline',
        'zed','zCode','openCode','kilo','continue','openClaw','hermes','aionui','aiUsagebar'
    )
}

function Get-BootstrapAiConfigProviderReport {
    $providers = New-Object System.Collections.Generic.List[object]
    foreach ($provider in @(Get-BootstrapAiConfigProviderEnvMap)) {
        $names = @($provider['env'])
        $presentNames = New-Object System.Collections.Generic.List[string]
        foreach ($name in @($names)) {
            if (Test-BootstrapDoctorAnyEnvPresent -Names @([string]$name)) {
                $presentNames.Add([string]$name) | Out-Null
            }
        }
        $status = if ($presentNames.Count -gt 0) { 'present' } else { 'missing' }
        $providers.Add([ordered]@{
            provider = [string]$provider['provider']
            status = $status
            source = $(if ($presentNames.Count -gt 0) { 'env' } else { 'missing' })
            envPresent = ($presentNames.Count -gt 0)
            envNames = @($presentNames.ToArray())
            targetApps = @($provider['targetApps'])
            value = '[redacted]'
        }) | Out-Null
    }
    return @($providers.ToArray())
}

function Get-BootstrapAiConfigTargetReport {
    param([object[]]$Providers = @())

    $targets = New-Object System.Collections.Generic.List[object]
    foreach ($target in @(Get-BootstrapAiConfigKnownTargetList)) {
        $providerNames = @($Providers | Where-Object { [bool]$_['envPresent'] -and (@($_['targetApps']) -contains $target) } | ForEach-Object { [string]$_['provider'] })
        $status = if ($target -eq 'openClaw') {
            'blocked'
        } elseif ($target -in @('aionui')) {
            'manualRequired'
        } elseif ($providerNames.Count -gt 0) {
            'ready'
        } else {
            'missing'
        }
        $manual = ($target -in @('aionui','openClaw','hermes'))
        $reason = if ($target -eq 'openClaw') {
            'OpenClaw usage blocked: account grants are not bound to each request.'
        } elseif ($target -eq 'aionui') {
            'AionUI provider store is encrypted/undocumented; use manual app settings.'
        } elseif ($target -eq 'hermes') {
            'Hermes config writes must use hermes config set when command exists.'
        } elseif ($providerNames.Count -gt 0) {
            'Provider env available for app-scoped sync.'
        } else {
            'No compatible provider env detected.'
        }
        $targets.Add([ordered]@{
            id = $target
            status = $status
            providers = @($providerNames)
            manualRequired = [bool]$manual
            drift = 'unknown'
            reason = $reason
        }) | Out-Null
    }
    return @($targets.ToArray())
}

function Get-BootstrapAiConfigMcpHealth {
    $servers = New-Object System.Collections.Generic.List[object]
    $managed = Get-BootstrapManagedMcpCatalog
    foreach ($name in @($managed.Keys)) {
        $def = ConvertTo-BootstrapHashtable -InputObject $managed[$name]
        $command = if ($def.ContainsKey('command')) { [string]$def['command'] } else { '' }
        $url = if ($def.ContainsKey('url')) { [string]$def['url'] } elseif ($def.ContainsKey('baseUrl')) { [string]$def['baseUrl'] } else { '' }
        $status = 'unknown'
        if (-not [string]::IsNullOrWhiteSpace($command)) {
            $status = if (Resolve-CommandPath -Name $command) { 'ready' } else { 'missing' }
        } elseif (-not [string]::IsNullOrWhiteSpace($url)) {
            $status = 'remote'
        }
        $servers.Add([ordered]@{
            id = [string]$name
            status = $status
            profile = if ($def.ContainsKey('profile')) { [string]$def['profile'] } else { 'core' }
            command = $command
            url = $url
            auth = if ($def.ContainsKey('env') -or $def.ContainsKey('headers')) { 'redacted' } else { 'none' }
        }) | Out-Null
    }
    return [ordered]@{
        schemaVersion = 1
        status = 'success'
        servers = @($servers.ToArray())
    }
}

function Get-BootstrapHermesAiConfigReport {
    $catalog = Get-BootstrapAiToolCatalog
    $entry = $catalog['hermes-agent']
    $cmd = Resolve-BootstrapAiToolCommandPath -CatalogEntry $entry -InstallRoot ''
    $userHome = Get-BootstrapUserHomePath
    $hermesHome = if (-not [string]::IsNullOrWhiteSpace($userHome)) { Join-Path $userHome '.hermes' } else { '' }
    $layout = if (-not [string]::IsNullOrWhiteSpace($cmd) -and $cmd -match '(?i)\\AppData\\Local\\hermes\\') { 'windows-native' } elseif (-not [string]::IsNullOrWhiteSpace($hermesHome) -and (Test-Path -LiteralPath $hermesHome)) { 'wsl-or-posix' } else { 'unknown' }
    return [ordered]@{
        installed = -not [string]::IsNullOrWhiteSpace($cmd)
        commandPath = [string]$cmd
        layout = $layout
        windowsInstallSupport = [string]$entry['WindowsInstallSupport']
        windowsInstallCommand = [string]$entry['WindowsInstallCommand']
        configMethod = 'hermes config set'
        manualRequired = $true
        smoke = [ordered]@{
            version = $(if ($cmd) { Invoke-BootstrapDoctorCommandProbe -Label 'hermes-version' -CommandName $cmd -CommandArgs @('--version') -TimeoutMs 3000 } else { [ordered]@{ status = 'missing' } })
            doctor = $(if ($cmd) { Invoke-BootstrapDoctorCommandProbe -Label 'hermes-doctor' -CommandName $cmd -CommandArgs @('doctor') -TimeoutMs 5000 } else { [ordered]@{ status = 'missing' } })
            configCheck = $(if ($cmd) { Invoke-BootstrapDoctorCommandProbe -Label 'hermes-config-check' -CommandName $cmd -CommandArgs @('config','check') -TimeoutMs 5000 } else { [ordered]@{ status = 'missing' } })
        }
    }
}

function Get-BootstrapOpenClawAiConfigReport {
    $catalog = Get-BootstrapAiToolCatalog
    $entry = $catalog['openclaw']
    $cmd = Resolve-BootstrapAiToolCommandPath -CatalogEntry $entry -InstallRoot ''
    return [ordered]@{
        ready = $false
        usageBlocked = $true
        blockedReason = 'connection-grant-not-enforceable'
        installed = -not [string]::IsNullOrWhiteSpace($cmd)
        commandPath = [string]$cmd
        minimumNodeMajor = [int]$entry['MinimumNodeMajor']
        nodeMajor = $null
        nodeStatus = 'not-probed'
        aliases = @($entry['Aliases'])
        onboarding = 'manual'
        daemon = 'manual-opt-in'
        smoke = [ordered]@{
            version = [ordered]@{ status = $(if ($cmd) { 'not-probed' } else { 'missing' }) }
            status = [ordered]@{ status = 'blocked'; reason = 'connection-grant-not-enforceable' }
        }
    }
}

function New-BootstrapAiConfigDoctorReport {
    $started = [Diagnostics.Stopwatch]::StartNew()
    $providers = @(Get-BootstrapAiConfigProviderReport)
    $targets = @(Get-BootstrapAiConfigTargetReport -Providers $providers)
    $mcpHealth = Get-BootstrapAiConfigMcpHealth
    $hermes = Get-BootstrapHermesAiConfigReport
    $openclaw = Get-BootstrapOpenClawAiConfigReport
    $aiProxies = New-BootstrapAiProxySuiteDoctorReport
    $mcpNpxRepair = $null
    try { $mcpNpxRepair = Invoke-BootstrapMcpConfigRepair -DryRun } catch { $mcpNpxRepair = [ordered]@{ dryRun = $true; totalFixed = 0; targets = @(); error = [string]$_.Exception.Message } }
    $manual = (@($targets | Where-Object { [bool]$_['manualRequired'] }).Count -gt 0)
    $drift = @($targets | Where-Object { [string]$_['drift'] -eq 'drift' })
    $started.Stop()
    return [ordered]@{
        schemaVersion = 1
        status = $(if ($manual) { 'warning' } else { 'success' })
        generatedAt = (Get-Date).ToString('o')
        durationMs = [long]$started.ElapsedMilliseconds
        providers = @($providers)
        targets = @($targets)
        mcps = $mcpHealth
        mcpNpxRepair = $mcpNpxRepair
        drift = @($drift)
        applied = @()
        skipped = @()
        manualRequired = [bool]$manual
        hermes = $hermes
        openclaw = $openclaw
        aiProxies = $aiProxies
        aionui = Get-BootstrapAionUiDoctorReport
        aiUsagebar = New-BootstrapAiUsagebarDoctorReport
        aiMemory = New-BootstrapAiMemoryDoctorReport
    }
}

function Invoke-BootstrapAiConfigSync {
    param([switch]$DryRun)

    $doctor = New-BootstrapAiConfigDoctorReport
    $planned = New-Object System.Collections.Generic.List[object]
    foreach ($target in @($doctor['targets'])) {
        $providers = @($target['providers'])
        if ($providers.Count -eq 0) { continue }
        $planned.Add([ordered]@{
            target = [string]$target['id']
            action = $(if ([bool]$target['manualRequired']) { 'manual-fallback' } else { 'sync-app-scoped-config' })
            providers = @($providers)
            writesSecrets = $false
            backupRequired = (-not [bool]$DryRun)
            status = $(if ($DryRun) { 'planned' } else { 'skipped' })
            reason = [string]$target['reason']
        }) | Out-Null
    }

    return [ordered]@{
        schemaVersion = 1
        status = $(if ($DryRun) { 'planned' } else { 'manualRequired' })
        dryRun = [bool]$DryRun
        generatedAt = (Get-Date).ToString('o')
        providers = @($doctor['providers'])
        targets = @($doctor['targets'])
        planned = @($planned.ToArray())
        applied = @()
        skipped = @($planned.ToArray() | Where-Object { [string]$_['action'] -eq 'manual-fallback' })
        manualRequired = $true
        recommendedAction = 'Run with app-specific documented CLI/config support only; AionUI/OpenClaw onboarding/Hermes gateway remain manual unless confirmed.'
    }
}

function Invoke-BootstrapAiConfigDoctorMode {
    Write-Log 'Modo: AiConfigDoctor'
    $report = New-BootstrapAiConfigDoctorReport
    if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
        Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value ([ordered]@{
            status = [string]$report['status']
            exitCode = 0
            mode = 'ai-config-doctor'
            generatedAt = (Get-Date).ToString('o')
            logPath = $script:LogPath
            resultPath = $script:ResultPath
            aiConfig = ConvertTo-BootstrapSupportSafeObject -Value $report -Name 'aiConfig'
        })
    }
    Write-Log ("AiConfigDoctor: status={0} targets={1}" -f [string]$report['status'], @($report['targets']).Count)
}

function Invoke-BootstrapAiConfigSyncMode {
    Write-Log 'Modo: AiConfigSync'
    $report = Invoke-BootstrapAiConfigSync -DryRun:$DryRun
    if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
        Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value ([ordered]@{
            status = [string]$report['status']
            exitCode = 0
            mode = 'ai-config-sync'
            generatedAt = (Get-Date).ToString('o')
            logPath = $script:LogPath
            resultPath = $script:ResultPath
            aiConfig = ConvertTo-BootstrapSupportSafeObject -Value $report -Name 'aiConfigSync'
        })
    }
    Write-Log ("AiConfigSync: status={0} planned={1} dryRun={2}" -f [string]$report['status'], @($report['planned']).Count, [bool]$report['dryRun'])
}

function Get-BootstrapDeckCimInstance {
    param([Parameter(Mandatory = $true)][string]$ClassName)

    try {
        if (Get-Command -Name Get-CimInstance -ErrorAction SilentlyContinue) {
            return @(Get-CimInstance -ClassName $ClassName -ErrorAction Stop)
        }
    } catch {
        Write-Verbose $_.Exception.Message
    }
    return @()
}

function Invoke-BootstrapDeckCommandProbe {
    param(
        [Parameter(Mandatory = $true)][string]$Label,
        [Parameter(Mandatory = $true)][string]$FileName,
        [string[]]$Arguments = @(),
        [int]$TimeoutMs = 3000
    )

    $probe = Invoke-BootstrapDoctorCommandProbe -Label $Label -CommandName $FileName -CommandArgs $Arguments -TimeoutMs $TimeoutMs
    return [ordered]@{
        label = $Label
        status = [string]$probe['status']
        path = [string]$probe['path']
        exitCode = $probe['exitCode']
        timedOut = [bool]$probe['timedOut']
        output = [string]$probe['output']
    }
}

function Test-BootstrapDeckAnyPath {
    param([string[]]$Paths = @())
    return [bool](Test-WingetProbePathsOnDisk -ProbePaths $Paths)
}

function Get-BootstrapDeckComponentProbePath {
    param([Parameter(Mandatory = $true)][string]$ComponentName)

    try {
        $catalog = Get-BootstrapComponentCatalog
        if (-not $catalog.Contains($ComponentName)) { return @() }
        $component = $catalog[$ComponentName]
        if ($component.PSObject.Properties.Name -contains 'ProbePaths') {
            return @($component.ProbePaths | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
        }
    } catch {
        Write-Verbose $_.Exception.Message
    }
    return @()
}

function Get-BootstrapDeckObjectText {
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return '' }
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($item in @($Value)) {
        if ($null -eq $item) { continue }
        foreach ($propName in @('Manufacturer','Model','Product','Name','Caption','Description','SMBIOSBIOSVersion','PNPDeviceID','DriverVersion')) {
            try {
                if ($item.PSObject.Properties[$propName] -and -not [string]::IsNullOrWhiteSpace([string]$item.$propName)) {
                    $parts.Add([string]$item.$propName)
                }
            } catch {
                Write-Verbose $_.Exception.Message
            }
        }
    }
    return (@($parts.ToArray()) -join ' ')
}

function New-BootstrapDeckCheck {
    param(
        [Parameter(Mandatory = $true)][string]$Id,
        [Parameter(Mandatory = $true)][string]$Status,
        [ValidateSet('info','warning','error')][string]$Severity = 'info',
        [Parameter(Mandatory = $true)][string]$Summary,
        [System.Collections.IDictionary]$Data = @{}
    )

    $check = [ordered]@{
        id = $Id
        status = $Status
        severity = $Severity
        summary = $Summary
    }
    foreach ($key in @($Data.Keys)) {
        $check[$key] = $Data[$key]
    }
    return $check
}

function Get-BootstrapDeckLibrarySummary {
    $candidates = @(
        'F:\Steam\Steamapps',
        "$env:ProgramFiles\Steam\steamapps",
        "${env:ProgramFiles(x86)}\Steam\steamapps"
    )
    $present = New-Object System.Collections.Generic.List[object]
    foreach ($candidate in @($candidates)) {
        if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
        $expanded = ConvertTo-BootstrapExpandedPath -Path ([string]$candidate)
        if ([string]::IsNullOrWhiteSpace($expanded) -or -not (Test-Path -LiteralPath $expanded)) { continue }
        $driveName = ''
        $freeGb = $null
        try {
            $root = [System.IO.Path]::GetPathRoot($expanded)
            if (-not [string]::IsNullOrWhiteSpace($root)) {
                $driveName = $root.TrimEnd('\').TrimEnd(':')
                $drive = Get-PSDrive -Name $driveName -ErrorAction SilentlyContinue
                if ($drive) { $freeGb = [math]::Round(([double]$drive.Free / 1GB), 2) }
            }
        } catch {
            Write-Verbose $_.Exception.Message
        }
        $present.Add([ordered]@{
            path = $expanded
            drive = $driveName
            freeGb = $freeGb
        })
    }
    return [ordered]@{
        candidates = @($candidates)
        present = @($present.ToArray())
        count = @($present.ToArray()).Count
    }
}

function New-BootstrapSteamDeckDoctorReport {
    $started = [Diagnostics.Stopwatch]::StartNew()
    $checks = New-Object System.Collections.Generic.List[object]

    $computer = @(Get-BootstrapDeckCimInstance -ClassName 'Win32_ComputerSystem')
    $baseBoard = @(Get-BootstrapDeckCimInstance -ClassName 'Win32_BaseBoard')
    $bios = @(Get-BootstrapDeckCimInstance -ClassName 'Win32_BIOS')
    $video = @(Get-BootstrapDeckCimInstance -ClassName 'Win32_VideoController')
    $battery = @(Get-BootstrapDeckCimInstance -ClassName 'Win32_Battery')
    $monitors = @(Get-BootstrapDeckCimInstance -ClassName 'Win32_DesktopMonitor')

    $hardwareText = ((Get-BootstrapDeckObjectText -Value $computer), (Get-BootstrapDeckObjectText -Value $baseBoard), (Get-BootstrapDeckObjectText -Value $bios), (Get-BootstrapDeckObjectText -Value $video)) -join ' '
    $isDeck = ($hardwareText -match '(?i)\bValve\b|Steam\s*Deck|Jupiter|Galileo|Van\s*Gogh|AMD\s*Custom\s*GPU')
    $hardwareStatus = if ($isDeck) { 'healthy' } else { 'notDetected' }
    $checks.Add((New-BootstrapDeckCheck -Id 'deck-hardware' -Status $hardwareStatus -Severity 'info' -Summary $(if ($isDeck) { 'Steam Deck hardware detected.' } else { 'Steam Deck hardware not detected.' }) -Data @{
        manufacturer = $(if ($computer.Count -gt 0) { [string]$computer[0].Manufacturer } else { '' })
        model = $(if ($computer.Count -gt 0) { [string]$computer[0].Model } else { '' })
        baseBoard = $(if ($baseBoard.Count -gt 0) { [string]$baseBoard[0].Product } else { '' })
    }))

    if (-not $isDeck) {
        $started.Stop()
        return [ordered]@{
            schemaVersion = 1
            status = 'notDetected'
            isLikelySteamDeck = $false
            durationMs = [long]$started.ElapsedMilliseconds
            summary = 'Steam Deck hardware not detected.'
            checks = @($checks.ToArray())
            power = [ordered]@{ batteryPresent = ($battery.Count -gt 0); activeScheme = ''; battery = @($battery) }
            display = [ordered]@{ monitorCount = $monitors.Count; monitors = @($monitors) }
            libraries = Get-BootstrapDeckLibrarySummary
        }
    }

    $amdVideo = @($video | Where-Object { ((Get-BootstrapDeckObjectText -Value $_) -match '(?i)AMD|Radeon|Van\s*Gogh|Custom\s*GPU') })
    $checks.Add((New-BootstrapDeckCheck -Id 'deck-amd-driver' -Status $(if ($amdVideo.Count -gt 0) { 'healthy' } else { 'warning' }) -Severity $(if ($amdVideo.Count -gt 0) { 'info' } else { 'warning' }) -Summary $(if ($amdVideo.Count -gt 0) { "AMD GPU driver: $([string]$amdVideo[0].DriverVersion)" } else { 'AMD GPU driver not detected via WMI.' }) -Data @{
        adapters = @($video | ForEach-Object { [ordered]@{ name = [string]$_.Name; driverVersion = [string]$_.DriverVersion } })
    }))

    $powerProbe = Invoke-BootstrapDeckCommandProbe -Label 'powercfg-active-scheme' -FileName 'powercfg.exe' -Arguments @('/GETACTIVESCHEME') -TimeoutMs 3000
    $batterySummary = if ($battery.Count -gt 0) {
        "Battery detected; charge=$([string]$battery[0].EstimatedChargeRemaining)%"
    } else {
        'Battery not reported by Windows WMI.'
    }
    $checks.Add((New-BootstrapDeckCheck -Id 'deck-power' -Status $(if ($battery.Count -gt 0) { 'healthy' } else { 'warning' }) -Severity $(if ($battery.Count -gt 0) { 'info' } else { 'warning' }) -Summary $batterySummary -Data @{
        batteryPresent = ($battery.Count -gt 0)
        estimatedChargeRemaining = $(if ($battery.Count -gt 0) { $battery[0].EstimatedChargeRemaining } else { $null })
        activeScheme = [string]$powerProbe['output']
        powercfgTimedOut = [bool]$powerProbe['timedOut']
    }))

    $checks.Add((New-BootstrapDeckCheck -Id 'deck-display' -Status 'healthy' -Severity 'info' -Summary ("Displays reported by Windows: {0}" -f $monitors.Count) -Data @{
        monitorCount = $monitors.Count
        monitors = @($monitors | ForEach-Object { [ordered]@{ name = [string]$_.Name; pnpDeviceId = [string]$_.PNPDeviceID } })
    }))

    $steamPresent = Test-BootstrapDeckAnyPath -Paths @('${env:ProgramFiles(x86)}\Steam\steam.exe', '$env:ProgramFiles\Steam\steam.exe', '$env:LOCALAPPDATA\Steam\steam.exe')
    $handheldPresent = Test-BootstrapDeckAnyPath -Paths @('$env:ProgramFiles\Handheld Companion\HandheldCompanion.exe', '$env:LOCALAPPDATA\Programs\Handheld Companion\HandheldCompanion.exe')
    $glossiPresent = Test-BootstrapDeckAnyPath -Paths @('$env:ProgramFiles\GlosSI\GlosSIConfig.exe', '$env:ProgramData\chocolatey\lib\glossi\tools\GlosSIConfig.exe')
    $deckToolsPresent = Test-BootstrapDeckAnyPath -Paths @('$env:ProgramFiles\Steam Deck Tools', '$env:ProgramFiles\SteamDeckTools', '$env:LOCALAPPDATA\Programs\Steam Deck Tools')
    $inputLayers = @()
    if ($steamPresent) { $inputLayers += 'Steam Input' }
    if ($handheldPresent) { $inputLayers += 'Handheld Companion' }
    if ($glossiPresent) { $inputLayers += 'GlosSI' }
    if ($deckToolsPresent) { $inputLayers += 'Steam Deck Tools' }
    $inputConflict = ($steamPresent -and ($handheldPresent -or $glossiPresent)) -or ($inputLayers.Count -gt 2)
    $checks.Add((New-BootstrapDeckCheck -Id 'deck-input-conflicts' -Status $(if ($inputConflict) { 'warning' } else { 'healthy' }) -Severity $(if ($inputConflict) { 'warning' } else { 'info' }) -Summary $(if ($inputConflict) { "Potential input overlap: $($inputLayers -join ', ')." } else { "Input layers: $($inputLayers -join ', ')." }) -Data @{
        steamInput = [bool]$steamPresent
        handheldCompanion = [bool]$handheldPresent
        glossi = [bool]$glossiPresent
        steamDeckTools = [bool]$deckToolsPresent
        layers = @($inputLayers)
    }))

    $streaming = [ordered]@{}
    foreach ($component in @('sunshine','moonlight','tailscale','rustdesk')) {
        $streaming[$component] = [bool](Test-BootstrapDeckAnyPath -Paths (Get-BootstrapDeckComponentProbePath -ComponentName $component))
    }
    $checks.Add((New-BootstrapDeckCheck -Id 'deck-streaming-connectivity' -Status 'healthy' -Severity 'info' -Summary ("Streaming/connectivity installed: {0}" -f ((@($streaming.Keys) | Where-Object { [bool]$streaming[$_] }) -join ', ')) -Data $streaming))

    $libraries = Get-BootstrapDeckLibrarySummary
    $checks.Add((New-BootstrapDeckCheck -Id 'deck-steam-libraries' -Status $(if ([int]$libraries['count'] -gt 0) { 'healthy' } else { 'warning' }) -Severity $(if ([int]$libraries['count'] -gt 0) { 'info' } else { 'warning' }) -Summary ("Steam libraries found: {0}" -f [int]$libraries['count']) -Data @{
        libraryCount = [int]$libraries['count']
        libraries = @($libraries['present'])
    }))

    $hasError = (@($checks | Where-Object { [string]$_['severity'] -eq 'error' }).Count -gt 0)
    $hasWarning = (@($checks | Where-Object { [string]$_['severity'] -eq 'warning' }).Count -gt 0)
    $started.Stop()

    return [ordered]@{
        schemaVersion = 1
        status = $(if ($hasError) { 'critical' } elseif ($hasWarning) { 'warning' } else { 'healthy' })
        isLikelySteamDeck = $true
        durationMs = [long]$started.ElapsedMilliseconds
        summary = $(if ($hasWarning) { 'Steam Deck diagnostics completed with warnings.' } else { 'Steam Deck diagnostics healthy.' })
        checks = @($checks.ToArray())
        power = [ordered]@{
            batteryPresent = ($battery.Count -gt 0)
            battery = @($battery | ForEach-Object { [ordered]@{ estimatedChargeRemaining = $_.EstimatedChargeRemaining; batteryStatus = $_.BatteryStatus } })
            activeScheme = [string]$powerProbe['output']
        }
        display = [ordered]@{
            monitorCount = $monitors.Count
            monitors = @($monitors | ForEach-Object { [ordered]@{ name = [string]$_.Name; pnpDeviceId = [string]$_.PNPDeviceID } })
        }
        libraries = $libraries
    }
}

function Get-BootstrapCheckSeverityRank {
    # Rank de saude para diff de drift: 0=ok, 1=atencao, 2=critico. Maior = pior.
    param([string]$Status)
    switch -Regex (([string]$Status).Trim().ToLowerInvariant()) {
        '^(error|critical|corrupt|blocked|failed|rejected|expired|unhealthy|ghostinstall|broken)$' { return 2 }
        '^(warning|missing|notdetected|absent|pending|degraded|manual-review|manual|unknown)$' { return 1 }
        default { return 0 }
    }
}

function Get-BootstrapDriftChecksMap {
    # Extrai o mapa id->status de um snapshot (hashtable em processo ou PSCustomObject de JSON).
    param([AllowNull()]$Snapshot)
    $result = @{}
    if ($null -eq $Snapshot) { return $result }
    $checks = Get-BootstrapNamedValue -Object $Snapshot -Name 'checks' -Default $null
    if ($null -eq $checks) { return $result }
    $checks = ConvertTo-BootstrapHashtable -InputObject $checks
    if ($checks -is [System.Collections.IDictionary]) {
        foreach ($k in @($checks.Keys)) { $result[[string]$k] = [string]$checks[$k] }
    }
    return $result
}

function Get-BootstrapDriftSnapshotFromDoctor {
    # Snapshot estavel (id->status) a partir dos checks do doctor report.
    param([Parameter(Mandatory = $true)]$DoctorReport)
    $map = [ordered]@{}
    $checks = @(Get-BootstrapNamedValue -Object $DoctorReport -Name 'checks' -Default @())
    foreach ($c in @($checks)) {
        $id = [string](Get-BootstrapNamedValue -Object $c -Name 'id' -Default '')
        if ([string]::IsNullOrWhiteSpace($id)) { continue }
        $map[$id] = [string](Get-BootstrapNamedValue -Object $c -Name 'status' -Default '')
    }
    return [ordered]@{ generatedAt = (Get-Date).ToString('o'); checks = $map }
}

function Compare-BootstrapDriftSnapshot {
    # Regressoes = checks cujo rank de severidade piorou em relacao ao baseline. Puro/testavel.
    param([AllowNull()]$Baseline, [AllowNull()]$Current)
    $baseMap = Get-BootstrapDriftChecksMap -Snapshot $Baseline
    $curMap = Get-BootstrapDriftChecksMap -Snapshot $Current
    $regressions = New-Object System.Collections.Generic.List[object]
    foreach ($id in @($curMap.Keys)) {
        if (-not $baseMap.ContainsKey($id)) { continue }  # check novo nao e regressao
        $from = [string]$baseMap[$id]
        $to = [string]$curMap[$id]
        if ((Get-BootstrapCheckSeverityRank -Status $to) -gt (Get-BootstrapCheckSeverityRank -Status $from)) {
            $regressions.Add([ordered]@{ id = $id; from = $from; to = $to }) | Out-Null
        }
    }
    return @($regressions.ToArray())
}

function Get-BootstrapDriftBaselinePath { return (Join-Path (Get-BootstrapDataRoot) 'drift-baseline.json') }
function Get-BootstrapDriftLastPath { return (Join-Path (Get-BootstrapDataRoot) 'drift-last.json') }
function Get-BootstrapDriftCheckTaskName { return 'BootstrapTools-DriftCheck' }

function Invoke-BootstrapDriftCheck {
    # Roda o doctor, compara com o baseline persistido e grava o ultimo resultado. Na primeira vez
    # (ou com -UpdateBaseline) salva o baseline e nao reporta regressoes.
    param([switch]$UpdateBaseline)

    $doctor = New-BootstrapDoctorReport
    $snapshot = Get-BootstrapDriftSnapshotFromDoctor -DoctorReport $doctor
    $baselinePath = Get-BootstrapDriftBaselinePath
    $baseline = $null
    if (Test-Path -LiteralPath $baselinePath) { try { $baseline = Read-BootstrapJsonFile -Path $baselinePath } catch { $baseline = $null } }
    $baselineExisted = ($null -ne $baseline)

    $regressions = @()
    if ($baselineExisted -and -not $UpdateBaseline) {
        $regressions = @(Compare-BootstrapDriftSnapshot -Baseline $baseline -Current $snapshot)
    }
    if (-not $baselineExisted -or $UpdateBaseline) {
        Write-BootstrapJsonFile -Path $baselinePath -Value $snapshot
    }

    $result = [ordered]@{
        checkedAt = [string]$snapshot.generatedAt
        baselineExisted = [bool]$baselineExisted
        doctorStatus = [string]$doctor.status
        regressionCount = @($regressions).Count
        regressions = @($regressions)
    }
    Write-BootstrapJsonFile -Path (Get-BootstrapDriftLastPath) -Value $result
    return $result
}

function Get-BootstrapDriftCheckTaskState {
    $name = Get-BootstrapDriftCheckTaskName
    if (Get-Command -Name Get-ScheduledTask -ErrorAction SilentlyContinue) {
        $t = Get-ScheduledTask -TaskName $name -ErrorAction SilentlyContinue
        return [ordered]@{ registered = [bool]$t; task = $name }
    }
    return [ordered]@{ registered = $false; task = $name }
}

function Register-BootstrapDriftCheckTask {
    # Agenda verificacao de drift semanal (por-usuario, sem elevacao quando possivel).
    param([Parameter(Mandatory = $true)][string]$ScriptPath)

    $name = Get-BootstrapDriftCheckTaskName
    $ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $argLine = ('-NoProfile -ExecutionPolicy Bypass -File "{0}" -DriftCheck -NonInteractive' -f $ScriptPath)

    if (Get-Command -Name Register-ScheduledTask -ErrorAction SilentlyContinue) {
        try {
            $existing = Get-ScheduledTask -TaskName $name -ErrorAction SilentlyContinue
            if ($existing) { Unregister-ScheduledTask -TaskName $name -Confirm:$false -ErrorAction SilentlyContinue }
            $action = New-ScheduledTaskAction -Execute $ps -Argument $argLine
            $trigger = New-ScheduledTaskTrigger -Weekly -DaysOfWeek Monday -At ([datetime]'09:00')
            $principal = New-ScheduledTaskPrincipal -UserId ("{0}\{1}" -f $env:USERDOMAIN, $env:USERNAME) -LogonType Interactive -RunLevel Limited
            $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable
            Register-ScheduledTask -TaskName $name -Action $action -Trigger $trigger -Principal $principal -Settings $settings -Description 'PhaseZero: verificacao semanal de drift (Doctor) e alerta de regressoes.' -ErrorAction Stop | Out-Null
            return [ordered]@{ status = 'registered'; task = $name; method = 'register-scheduledtask' }
        } catch {
            Write-Log ("drift: Register-ScheduledTask falhou ({0}); tentando schtasks." -f $_.Exception.Message) 'WARN'
        }
    }
    $schtasksExe = Join-Path $env:SystemRoot 'System32\schtasks.exe'
    if (-not (Test-Path $schtasksExe)) { return [ordered]@{ status = 'skipped'; task = $name; reason = 'schtasks.exe nao encontrado.' } }
    $tr = ('"{0}" {1}' -f $ps, $argLine)
    $exit = Invoke-NativeWithLog -Exe $schtasksExe -Args @('/Create', '/SC', 'WEEKLY', '/D', 'MON', '/ST', '09:00', '/TN', $name, '/TR', $tr, '/F', '/RU', $env:USERNAME)
    if ($exit -ne 0) { return [ordered]@{ status = 'failed'; task = $name; reason = ("schtasks-exit={0}" -f $exit) } }
    return [ordered]@{ status = 'registered'; task = $name; method = 'schtasks' }
}

function Unregister-BootstrapDriftCheckTask {
    $name = Get-BootstrapDriftCheckTaskName
    if (Get-Command -Name Unregister-ScheduledTask -ErrorAction SilentlyContinue) {
        try {
            $existing = Get-ScheduledTask -TaskName $name -ErrorAction SilentlyContinue
            if ($existing) { Unregister-ScheduledTask -TaskName $name -Confirm:$false -ErrorAction Stop; return [ordered]@{ status = 'removed'; task = $name } }
            return [ordered]@{ status = 'absent'; task = $name }
        } catch {
            Write-Log ("drift: Unregister-ScheduledTask falhou ({0}); tentando schtasks." -f $_.Exception.Message) 'WARN'
        }
    }
    $schtasksExe = Join-Path $env:SystemRoot 'System32\schtasks.exe'
    if (Test-Path $schtasksExe) { [void](Invoke-NativeWithLog -Exe $schtasksExe -Args @('/Delete', '/TN', $name, '/F')) }
    return [ordered]@{ status = 'removed'; task = $name }
}

function Get-BootstrapDoctorScopeCatalog {
    # Escopos validos do Doctor por card/area. 'all' executa tudo (comportamento legado).
    return @('wsl', 'winget', 'reboot', 'secrets', 'github', 'ai-usagebar', 'ai-memory',
             'aionui', 'steamdeck', 'rollback', 'mcp', 'agent-tools', 'windows-optimization', 'msvc', 'all')
}

function Resolve-BootstrapDoctorScopes {
    # Normaliza a lista de escopos pedida. Vazio/nulo -> 'all'. Tokens desconhecidos sao ignorados.
    param([AllowNull()][string[]]$Scopes)

    if ($null -eq $Scopes -or @($Scopes).Count -eq 0) { return @('all') }
    $valid = Get-BootstrapDoctorScopeCatalog
    $resolved = @($Scopes | ForEach-Object { [string]$_ } | Where-Object { $valid -contains $_ } | Select-Object -Unique)
    if (@($resolved).Count -eq 0) { return @('all') }
    return @($resolved)
}

function Test-BootstrapDoctorScope {
    # True se o probe nomeado deve rodar para a lista de escopos resolvida.
    param(
        [Parameter(Mandatory = $true)][string[]]$Scopes,
        [Parameter(Mandatory = $true)][string]$Name
    )
    if (@($Scopes) -contains 'all') { return $true }
    return (@($Scopes) -contains $Name)
}

function Test-BootstrapAiContextFrugalityConfigured {
    # True somente quando o pack de frugality realmente foi instalado: exige artefatos unicos do
    # pack (.codex\ai-context\frugality-manifest.json / repo-skeleton.json / doc) OU o bloco marcado
    # 'PHASEZERO AI CONTEXT FRUGALITY' no .aiderignore. NUNCA marca configurado so por AGENTS.md/CLAUDE.md.
    param([Parameter(Mandatory = $true)][string]$Root)

    foreach ($unique in @(
            (Join-Path $Root '.codex\ai-context\frugality-manifest.json'),
            (Join-Path $Root '.codex\ai-context\repo-skeleton.json'),
            (Join-Path $Root '.codex\context-packs\ai-context-frugality.md')
        )) {
        if (Test-Path -LiteralPath $unique -PathType Leaf) { return $true }
    }

    $aiderIgnore = Join-Path $Root '.aiderignore'
    if (Test-Path -LiteralPath $aiderIgnore -PathType Leaf) {
        try {
            $text = Get-Content -LiteralPath $aiderIgnore -Raw -ErrorAction Stop
            if ($text -match 'PHASEZERO AI CONTEXT FRUGALITY') { return $true }
        } catch {
            Write-Verbose $_.Exception.Message
        }
    }
    return $false
}

function New-BootstrapAgentToolsDoctorReport {
    # Valida o ecossistema de tokens/memoria/agentes: RTK, ai-memory, Caveman, Headroom, Ponytail,
    # ai-context-frugality. Graphify retorna placeholder seguro (notConfigured) sem falhar o Doctor.
    # Cada ferramenta declara um repairKind/repairTarget com FLUXO REAL (component | app-tuning |
    # ai-tool | none); RepairPlan nunca emite comando inexistente.
    param([string]$WorkspaceRoot = (Get-Location).Path)

    $root = if ([string]::IsNullOrWhiteSpace($WorkspaceRoot)) { (Get-Location).Path } else { $WorkspaceRoot }
    $plan = Get-BootstrapAgentCompatPlan -WorkspaceRoot $root

    # RTK / ai-memory / Caveman / Ponytail vem do plano de compatibilidade.
    $rtkStatus = [string]$plan.tools.rtk.status        # available | absent
    $memStatus = [string]$plan.tools.aiMemory.status   # available | absent
    $cavemanStatus = [string]$plan.tools.caveman.status # available | fallback
    $ponytailStatus = [string]$plan.tools.ponytail.status # active | inactive

    # Headroom: presenca do binario.
    $headroomPath = Resolve-CommandPath -Name 'headroom'
    $headroomStatus = if ([string]::IsNullOrWhiteSpace($headroomPath)) { 'absent' } else { 'available' }

    # ai-context-frugality: exige artefatos reais do pack (nao basta AGENTS.md/CLAUDE.md existir).
    $frugalityPresent = Test-BootstrapAiContextFrugalityConfigured -Root $root
    $frugalityStatus = if ($frugalityPresent) { 'configured' } else { 'notConfigured' }

    # repairKind: 'component' = .\bootstrap-tools.ps1 -Component <target>; 'app-tuning' =
    # -AppTuningItem <target>; 'ai-tool' = install-cli --tool <target>; 'none' = sem reparo automatico.
    $tools = [ordered]@{
        rtk = [ordered]@{ id = 'rtk'; displayName = 'RTK (shell compression)'; status = $rtkStatus; configured = ($rtkStatus -eq 'available'); path = [string]$plan.tools.rtk.path; repairKind = 'ai-tool'; repairTarget = 'rtk'; repairComponent = '' }
        aiMemory = [ordered]@{ id = 'ai-memory'; displayName = 'ai-memory'; status = $memStatus; configured = ($memStatus -eq 'available'); path = [string]$plan.tools.aiMemory.path; repairKind = 'component'; repairTarget = 'ai-memory'; repairComponent = 'ai-memory' }
        caveman = [ordered]@{ id = 'caveman'; displayName = 'Caveman (style)'; status = $cavemanStatus; configured = ($cavemanStatus -eq 'available'); path = [string]$plan.tools.caveman.path; repairKind = 'component'; repairTarget = 'agent-skills'; repairComponent = 'agent-skills' }
        headroom = [ordered]@{ id = 'headroom'; displayName = 'Headroom'; status = $headroomStatus; configured = ($headroomStatus -eq 'available'); path = [string]$headroomPath; repairKind = 'component'; repairTarget = 'headroom-ai'; repairComponent = 'headroom-ai' }
        ponytail = [ordered]@{ id = 'ponytail'; displayName = 'Ponytail (workspace architecture)'; status = $ponytailStatus; configured = ($ponytailStatus -eq 'active'); path = [string]$plan.tools.ponytail.path; repairKind = 'component'; repairTarget = 'agent-compat-runtime'; repairComponent = 'agent-compat-runtime' }
        aiContextFrugality = [ordered]@{ id = 'ai-context-frugality'; displayName = 'AI context frugality pack'; status = $frugalityStatus; configured = $frugalityPresent; repairKind = 'app-tuning'; repairTarget = 'ai-context-frugality-pack'; repairComponent = '' }
        graphify = [ordered]@{ id = 'graphify'; displayName = 'Graphify'; status = 'notConfigured'; configured = $false; placeholder = $true; action = 'informar fonte oficial'; repairKind = 'none'; repairTarget = ''; repairComponent = '' }
    }

    # Degradado se RTK ou ai-memory ausentes (impacto direto em tokens/memoria). Graphify placeholder
    # NUNCA derruba o status.
    $degraded = (($rtkStatus -eq 'absent') -or ($memStatus -eq 'absent'))
    $status = if ($degraded) { 'degraded' } else { 'healthy' }

    return [ordered]@{
        schemaVersion = 'agent-tools-doctor/v1'
        id = 'agent-tools'
        status = $status
        generatedAt = (Get-Date).ToString('o')
        workspaceRoot = $root
        mode = [string]$plan.mode
        tools = $tools
        graphifyPlaceholder = $true
        summary = ("RTK={0}; ai-memory={1}; Caveman={2}; Headroom={3}; Ponytail={4}; frugality={5}; Graphify=placeholder" -f $rtkStatus, $memStatus, $cavemanStatus, $headroomStatus, $ponytailStatus, $frugalityStatus)
    }
}

function New-BootstrapWindowsOptimizationDoctorReport {
    # Audit-only: lista recomendacoes de HostHealth/AppTuning sem aplicar nenhum tweak.
    $modes = @()
    try { $modes = @(Get-BootstrapHostHealthModes) } catch { $modes = @() }

    $tuningRecommended = @()
    try {
        $catalog = Get-BootstrapAppTuningCatalog
        # Catalogo e OrderedDictionary com uma lista plana 'items'; recomendado = defaultMode 'recommended'.
        foreach ($item in @($catalog['items'])) {
            if ([string]$item['defaultMode'] -eq 'recommended') {
                $tuningRecommended += @([ordered]@{ id = [string]$item['id']; category = [string]$item['category']; displayName = [string]$item['displayName']; risk = [string]$item['riskTier'] })
            }
        }
    } catch {
        Write-Verbose $_.Exception.Message
    }

    return [ordered]@{
        schemaVersion = 'windows-optimization-doctor/v1'
        id = 'windows-optimization'
        status = 'info'
        auditOnly = $true
        generatedAt = (Get-Date).ToString('o')
        hostHealthModes = @($modes)
        recommendedTuning = @($tuningRecommended)
        summary = ("Audit-only: {0} modo(s) HostHealth; {1} item(ns) AppTuning recomendado(s). Nenhum tweak aplicado." -f @($modes).Count, @($tuningRecommended).Count)
    }
}

function New-BootstrapManagedMcpDoctorReport {
    # Valida (sem reparar) o estado dos MCPs gerenciados. Apenas leitura.
    $servers = @()
    try { $servers = @(Get-BootstrapManagedMcpServers) } catch { $servers = @() }
    $targets = @()
    try { $targets = @(Get-BootstrapManagedMcpCapableTargets) } catch { $targets = @() }
    $statePath = ''
    try { $statePath = Get-BootstrapMcpStatePath } catch { $statePath = '' }
    $stateExists = (-not [string]::IsNullOrWhiteSpace($statePath) -and (Test-Path -LiteralPath $statePath -PathType Leaf))

    return [ordered]@{
        schemaVersion = 'mcp-doctor/v1'
        id = 'mcp'
        status = $(if ($stateExists) { 'healthy' } else { 'info' })
        generatedAt = (Get-Date).ToString('o')
        serverCount = @($servers).Count
        targetCount = @($targets).Count
        statePath = $statePath
        stateExists = $stateExists
        summary = ("MCPs gerenciados: {0} servidor(es) sobre {1} alvo(s); state={2}." -f @($servers).Count, @($targets).Count, $(if ($stateExists) { 'presente' } else { 'ausente' }))
    }
}

function New-BootstrapMsvcDoctorReport {
    # Valida o toolchain MSVC no host: DLLs do runtime VC++ (vcruntime140/msvcp140) e cl.exe.
    # Apenas leitura; o reparo das DLLs vai pela fila (componente vcpp-redist), cl.exe e manual.
    $system32 = Join-Path $env:SystemRoot 'System32'
    $runtimeDlls = @('vcruntime140.dll', 'vcruntime140_1.dll', 'msvcp140.dll')
    $dllRows = New-Object System.Collections.Generic.List[object]
    $missingDll = $false
    foreach ($dll in $runtimeDlls) {
        $path = Join-Path $system32 $dll
        $present = Test-Path -LiteralPath $path -PathType Leaf
        if (-not $present) { $missingDll = $true }
        $dllRows.Add([ordered]@{ name = $dll; present = [bool]$present; path = $path }) | Out-Null
    }

    # cl.exe: PATH direto ou via vswhere (Build Tools / VS).
    $clPath = Resolve-CommandPath -Name 'cl.exe'
    if ([string]::IsNullOrWhiteSpace($clPath)) { $clPath = Resolve-CommandPath -Name 'cl' }
    $vswhere = Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe'
    $vsInstall = ''
    if ([string]::IsNullOrWhiteSpace($clPath) -and (Test-Path -LiteralPath $vswhere -PathType Leaf)) {
        try {
            $probe = Invoke-BootstrapDoctorCommandProbe -Label 'vswhere-vc' -CommandName $vswhere -CommandArgs @('-products','*','-requires','Microsoft.VisualStudio.Component.VC.Tools.x86.x64','-property','installationPath','-format','value') -TimeoutMs 4000
            if ($probe -and ($probe.PSObject.Properties.Name -contains 'stdout')) { $vsInstall = ([string]$probe.stdout).Trim() }
        } catch { $vsInstall = '' }
    }
    $clAvailable = (-not [string]::IsNullOrWhiteSpace($clPath)) -or (-not [string]::IsNullOrWhiteSpace($vsInstall))

    $status = if ($missingDll) { 'critical' } elseif (-not $clAvailable) { 'warning' } else { 'healthy' }
    # DLLs do runtime ausentes -> vcpp-redist; compilador (cl.exe) ausente -> msvc-build-env.
    $repairComponent = if ($missingDll) { 'vcpp-redist' } elseif (-not $clAvailable) { 'msvc-build-env' } else { '' }

    return [ordered]@{
        schemaVersion = 'msvc-doctor/v1'
        id = 'msvc'
        status = $status
        generatedAt = (Get-Date).ToString('o')
        runtimeDlls = @($dllRows.ToArray())
        runtimeDllsMissing = [bool]$missingDll
        clExePath = [string]$clPath
        vsInstallationPath = [string]$vsInstall
        compilerAvailable = [bool]$clAvailable
        repairComponent = $repairComponent
        summary = ("MSVC: runtime DLLs {0}; cl.exe {1}{2}" -f $(if ($missingDll) { 'AUSENTES (instale vcpp-redist)' } else { 'OK' }), $(if ($clAvailable) { 'presente' } else { 'ausente (instale VS Build Tools - VC.Tools.x86.x64)' }), $(if (-not $clAvailable -and [string]::IsNullOrWhiteSpace($clPath)) { '' } else { '' }))
    }
}

function Get-BootstrapVsWherePath {
    foreach ($c in @(
        (Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe'),
        (Join-Path $env:ProgramFiles 'Microsoft Visual Studio\Installer\vswhere.exe')
    )) {
        if (-not [string]::IsNullOrWhiteSpace($c) -and (Test-Path -LiteralPath $c -PathType Leaf)) { return $c }
    }
    return ''
}

function Get-BootstrapMsvcInstallationPath {
    # installationPath de uma instalacao VS/BuildTools com o toolset VC.Tools.x86.x64 (via vswhere).
    $vswhere = Get-BootstrapVsWherePath
    if ([string]::IsNullOrWhiteSpace($vswhere)) { return '' }
    try {
        $out = & $vswhere -products '*' -requires 'Microsoft.VisualStudio.Component.VC.Tools.x86.x64' -latest -property installationPath 2>$null
        $path = ([string]($out | Select-Object -First 1)).Trim()
        if (-not [string]::IsNullOrWhiteSpace($path) -and (Test-Path -LiteralPath $path)) { return $path }
    } catch {
        Write-Verbose $_.Exception.Message
    }
    return ''
}

function Get-BootstrapVcvars64Path {
    param([string]$InstallationPath = '')
    $root = if ([string]::IsNullOrWhiteSpace($InstallationPath)) { Get-BootstrapMsvcInstallationPath } else { $InstallationPath }
    if ([string]::IsNullOrWhiteSpace($root)) { return '' }
    $vcvars = Join-Path $root 'VC\Auxiliary\Build\vcvars64.bat'
    if (Test-Path -LiteralPath $vcvars -PathType Leaf) { return $vcvars }
    return ''
}

function Import-BootstrapMsvcEnvironment {
    # Carrega o ambiente do MSVC (cl.exe/INCLUDE/LIB/PATH) no processo atual via vcvars64.bat.
    # Idempotente: no-op se cl.exe ja resolve. Best-effort: retorna $false sem lancar se indisponivel.
    param([switch]$Force)

    if (-not $Force) {
        $cl = Resolve-CommandPath -Name 'cl.exe'
        if (-not [string]::IsNullOrWhiteSpace($cl)) { return $true }
    }
    $vcvars = Get-BootstrapVcvars64Path
    if ([string]::IsNullOrWhiteSpace($vcvars)) { return $false }

    try {
        $captured = & cmd /c ('"{0}" >NUL 2>&1 && set' -f $vcvars)
        $importNames = @('PATH','INCLUDE','LIB','LIBPATH','VCINSTALLDIR','VCToolsInstallDir',
                         'WindowsSdkDir','WindowsSDKVersion','UCRTVersion','UniversalCRTSdkDir',
                         'VSCMD_ARG_HOST_ARCH','VSCMD_ARG_TGT_ARCH','VSINSTALLDIR')
        foreach ($line in @($captured)) {
            $idx = ([string]$line).IndexOf('=')
            if ($idx -lt 1) { continue }
            $name = ([string]$line).Substring(0, $idx)
            $value = ([string]$line).Substring($idx + 1)
            if ($importNames -contains $name) { Set-Item -Path ("Env:{0}" -f $name) -Value $value -Force }
        }
        $cl = Resolve-CommandPath -Name 'cl.exe'
        return (-not [string]::IsNullOrWhiteSpace($cl))
    } catch {
        Write-Log ("MSVC env: falha ao importar vcvars64: {0}" -f $_.Exception.Message) 'WARN'
        return $false
    }
}

function Ensure-BootstrapMsvcBuildEnv {
    # Garante o toolset MSVC (cl.exe). Se ausente, instala VS Build Tools (VC.Tools.x86.x64) via
    # winget e importa vcvars64 no processo. Nunca formata; idempotente.
    param([Parameter(Mandatory = $true)][hashtable]$State)

    $installPath = Get-BootstrapMsvcInstallationPath
    $installedNow = $false
    if ([string]::IsNullOrWhiteSpace($installPath)) {
        if ([bool]$State.DryRun) {
            Write-Log 'msvc-build-env: (dry-run) instalaria Microsoft.VisualStudio.2022.BuildTools (VC.Tools.x86.x64) e importaria vcvars64.'
            return [ordered]@{ status = 'planned'; toolsetPath = ''; installedNow = $false; envImported = $false; dryRun = $true }
        }
        # SEGURANCA: a instalacao do VS Build Tools e pesada (varios GB) e muta o host. NUNCA roda em
        # library mode (testes) e so roda quando explicitamente liberada via PHASEZERO_ALLOW_MSVC_BUILDTOOLS_INSTALL.
        # Sem opt-in, reporta guia acionavel em vez de instalar sozinho.
        $allowInstall = (-not $BootstrapUiLibraryMode) -and ('1','true','yes' -contains ([string]$env:PHASEZERO_ALLOW_MSVC_BUILDTOOLS_INSTALL).ToLowerInvariant())
        if (-not $allowInstall) {
            $cmd = 'winget install -e --id Microsoft.VisualStudio.2022.BuildTools --override "--quiet --wait --norestart --add Microsoft.VisualStudio.Workload.VCTools --add Microsoft.VisualStudio.Component.VC.Tools.x86.x64 --includeRecommended"'
            Write-Log ("msvc-build-env: toolset VC ausente. Instalacao automatica desligada por seguranca; defina PHASEZERO_ALLOW_MSVC_BUILDTOOLS_INSTALL=1 para liberar, ou rode manualmente: {0}" -f $cmd) 'WARN'
            return [ordered]@{ status = 'requires-install'; toolsetPath = ''; installedNow = $false; envImported = $false; repairCommand = $cmd; dryRun = $false }
        }
        $winget = ''
        try { $winget = [string]$State.Winget } catch { $winget = '' }
        if ([string]::IsNullOrWhiteSpace($winget)) { $winget = Resolve-CommandPath -Name 'winget' }
        if (-not [string]::IsNullOrWhiteSpace($winget)) {
            Write-Log 'msvc-build-env: toolset VC ausente; instalando Microsoft.VisualStudio.2022.BuildTools (VC.Tools.x86.x64) (opt-in liberado)...'
            $override = '--quiet --wait --norestart --add Microsoft.VisualStudio.Workload.VCTools --add Microsoft.VisualStudio.Component.VC.Tools.x86.x64 --includeRecommended'
            $wingetArgs = @('install', '-e', '--id', 'Microsoft.VisualStudio.2022.BuildTools', '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity', '--override', $override)
            $exit = Invoke-NativeWithRetry -Exe $winget -Args $wingetArgs -OperationName 'VS Build Tools (VC.Tools) via winget' -MaxAttempts 2 -InitialDelaySeconds 3 -SoftSuccessExitCodes $script:WingetSoftSuccessExitCodes
            $installedNow = ($exit -eq 0)
            if ($State.ContainsKey('Changes')) {
                try { Register-BootstrapChange -State $State -Type Package -Target 'Microsoft.VisualStudio.2022.BuildTools' -Name 'VS Build Tools (VC.Tools.x86.x64)' -OldValue $null -NewValue @{ Source = 'winget' } -Operation 'winget-install' -RollbackAction 'winget-uninstall' -Reversible 'partial' -Component 'msvc-build-env' } catch { Write-Verbose $_.Exception.Message }
            }
            $installPath = Get-BootstrapMsvcInstallationPath
        } else {
            Write-Log 'msvc-build-env: winget ausente; instale VS Build Tools (VC.Tools.x86.x64) manualmente.' 'WARN'
        }
    }

    $imported = Import-BootstrapMsvcEnvironment -Force
    $cl = Resolve-CommandPath -Name 'cl.exe'
    $status = if (-not [string]::IsNullOrWhiteSpace($cl)) { 'completed' } else { 'degraded' }
    Write-Log ("msvc-build-env: toolsetPath={0}; installedNow={1}; envImported={2}; cl={3}" -f $(if ($installPath) { $installPath } else { 'ausente' }), $installedNow, $imported, $(if ($cl) { $cl } else { 'ausente' }))
    return [ordered]@{ status = $status; toolsetPath = [string]$installPath; installedNow = [bool]$installedNow; envImported = [bool]$imported; clPath = [string]$cl; dryRun = [bool]$State.DryRun }
}

function New-BootstrapDoctorReport {
    param(
        [int]$AuditTimeoutSeconds = 180,
        [int]$AuditComponentTimeoutSeconds = 30,
        [string[]]$Scopes = @('all')
    )

    $Scopes = Resolve-BootstrapDoctorScopes -Scopes $Scopes
    $isAll = (@($Scopes) -contains 'all')

    $started = [Diagnostics.Stopwatch]::StartNew()
    $checks = New-Object System.Collections.Generic.List[object]

    $checks.Add((Get-BootstrapVersionHealth))
    $checks.Add([ordered]@{
        id = 'powershell'
        status = 'healthy'
        severity = 'info'
        version = [string]$PSVersionTable.PSVersion
        edition = [string]$PSVersionTable.PSEdition
        summary = "PowerShell $($PSVersionTable.PSVersion)"
    })
    $checks.Add([ordered]@{
        id = 'admin'
        status = $(if (Test-IsAdmin) { 'admin' } else { 'standard-user' })
        severity = 'info'
        isAdmin = [bool](Test-IsAdmin)
        summary = ("Admin={0}" -f [bool](Test-IsAdmin))
    })

    $dataRoot = Get-BootstrapDataRoot
    $checks.Add([ordered]@{
        id = 'data-root'
        status = $(if (Test-BootstrapDirectoryWritable -Path $dataRoot) { 'healthy' } else { 'warning' })
        severity = $(if (Test-BootstrapDirectoryWritable -Path $dataRoot) { 'info' } else { 'warning' })
        path = $dataRoot
        summary = "DataRoot: $dataRoot"
    })
    # --- Probes condicionados por escopo. 'all' executa tudo (comportamento legado). ----------
    $secretsDoctor = $null; $aiUsagebarDoctor = $null; $aiMemoryDoctor = $null
    $aionUiDoctor = $null; $aiConfigDoctor = $null; $aiProxyDoctor = $null
    $wslRepairDoctor = $null; $githubCliAuth = $null; $deckReport = $null
    $agentToolsDoctor = $null; $windowsOptimizationDoctor = $null; $mcpDoctor = $null; $msvcDoctor = $null
    $auditRows = @()
    $auditSummary = [pscustomobject](New-BootstrapAuditSeveritySummary -Rows @())

    if (Test-BootstrapDoctorScope -Scopes $Scopes -Name 'secrets') {
        $checks.Add((Get-BootstrapSecretsManifestHealth))
        $secretsDoctor = New-BootstrapSecretsDoctorReport
    }
    if (Test-BootstrapDoctorScope -Scopes $Scopes -Name 'ai-usagebar') { $aiUsagebarDoctor = New-BootstrapAiUsagebarDoctorReport }
    if (Test-BootstrapDoctorScope -Scopes $Scopes -Name 'ai-memory')   { $aiMemoryDoctor = New-BootstrapAiMemoryDoctorReport }
    if (Test-BootstrapDoctorScope -Scopes $Scopes -Name 'aionui')      { $aionUiDoctor = Get-BootstrapAionUiDoctorReport -ValidateProviders }
    if ($isAll) {
        $aiConfigDoctor = New-BootstrapAiConfigDoctorReport
        $aiProxyDoctor = New-BootstrapAiProxySuiteDoctorReport
    }

    if (Test-BootstrapDoctorScope -Scopes $Scopes -Name 'reboot') {
        $rebootReasons = @()
        try { $rebootReasons = @(Get-BootstrapPendingRebootReasons) } catch { $rebootReasons = @() }
        $checks.Add([ordered]@{
            id = 'pending-reboot'
            status = $(if ($rebootReasons.Count -gt 0) { 'warning' } else { 'healthy' })
            severity = $(if ($rebootReasons.Count -gt 0) { 'warning' } else { 'info' })
            pending = ($rebootReasons.Count -gt 0)
            reasons = @($rebootReasons)
            summary = $(if ($rebootReasons.Count -gt 0) { "Reinicio pendente: $($rebootReasons -join ', ')" } else { 'Sem reinicio pendente detectado.' })
        })
    }

    if (Test-BootstrapDoctorScope -Scopes $Scopes -Name 'winget') {
        foreach ($tool in @(
                @{ Label = 'winget'; CommandName = 'winget'; Args = @('--version') },
                @{ Label = 'git'; CommandName = 'git'; Args = @('--version') },
                @{ Label = 'node'; CommandName = 'node'; Args = @('-v') },
                @{ Label = 'npm'; CommandName = 'npm'; Args = @('--version') },
                @{ Label = 'dotnet'; CommandName = 'dotnet'; Args = @('--version') },
                @{ Label = 'python'; CommandName = 'python'; Args = @('--version') },
                @{ Label = 'gh'; CommandName = 'gh'; Args = @('--version') }
            )) {
            $checks.Add((Invoke-BootstrapDoctorCommandProbe -Label ([string]$tool['Label']) -CommandName ([string]$tool['CommandName']) -CommandArgs @($tool['Args']) -TimeoutMs 3000))
        }
    }

    if (Test-BootstrapDoctorScope -Scopes $Scopes -Name 'github') {
        $githubCliAuth = Get-BootstrapGithubCliAuthHealth
        $checks.Add($githubCliAuth)
    }

    if (Test-BootstrapDoctorScope -Scopes $Scopes -Name 'wsl') {
        $wslRepairDoctor = New-BootstrapWslRepairDoctorReport
        $checks.Add((Get-BootstrapWslDoctorHealth))
    }

    if ($isAll) { $checks.Add((Get-BootstrapUiContractHealth)) }

    if (Test-BootstrapDoctorScope -Scopes $Scopes -Name 'rollback') {
        $checks.Add([ordered]@{
            id = 'rollback-gate'
            status = $(if (Test-Path -LiteralPath (Join-Path $PSScriptRoot 'tests\bootstrap-quality-gates.tests.ps1')) { 'healthy' } else { 'warning' })
            severity = $(if (Test-Path -LiteralPath (Join-Path $PSScriptRoot 'tests\bootstrap-quality-gates.tests.ps1')) { 'info' } else { 'warning' })
            summary = 'Rollback/mutation gate coberto por tests/bootstrap-quality-gates.tests.ps1.'
        })
    }

    # Probes novos (cards/botoes dedicados): rodam SOMENTE quando o escopo e pedido explicitamente,
    # nunca em 'all', para nao adicionar latencia ao Doctor completo/SupportBundle (legado).
    if (@($Scopes) -contains 'agent-tools')          { $agentToolsDoctor = New-BootstrapAgentToolsDoctorReport }
    if (@($Scopes) -contains 'windows-optimization') { $windowsOptimizationDoctor = New-BootstrapWindowsOptimizationDoctorReport }
    if (@($Scopes) -contains 'mcp')                  { $mcpDoctor = New-BootstrapManagedMcpDoctorReport }
    if (@($Scopes) -contains 'msvc')                 { $msvcDoctor = New-BootstrapMsvcDoctorReport }

    # Audit pesado e baseline: somente no escopo 'all' (scoped fica rapido e focado).
    if ($isAll) {
        try {
            $resolution = Resolve-BootstrapComponents -SelectedProfiles @('safe-base') -SelectedComponents @() -ExcludedComponents @()
            $auditRows = @(Invoke-BootstrapAuditMode -Resolution $resolution -TimeoutSeconds $AuditTimeoutSeconds -ComponentTimeoutSeconds $AuditComponentTimeoutSeconds)
            $auditSummary = New-BootstrapAuditSeveritySummary -Rows $auditRows
        } catch {
            $checks.Add([ordered]@{ id = 'audit'; status = 'error'; severity = 'warning'; summary = "Audit resumido falhou: $($_.Exception.Message)" })
        }
        try {
            $phaseZeroBaseline = Invoke-BootstrapPhaseZeroBaselineProbe
            $checks.Add([ordered]@{ id = 'phasezero-baseline'; status = 'healthy'; severity = 'info'; summary = 'PhaseZero baseline audit concluido.'; phasezeroBaseline = $phaseZeroBaseline })
        } catch {
            $checks.Add([ordered]@{ id = 'phasezero-baseline'; status = 'error'; severity = 'warning'; summary = "PhaseZero baseline audit falhou: $($_.Exception.Message)" })
        }
    }

    if (Test-BootstrapDoctorScope -Scopes $Scopes -Name 'steamdeck') { $deckReport = New-BootstrapSteamDeckDoctorReport }

    $hasError = (@($checks | Where-Object { [string]($_['severity']) -eq 'error' }).Count -gt 0)
    $hasWarning = (@($checks | Where-Object { [string]($_['severity']) -eq 'warning' }).Count -gt 0)
    try {
        if ([int]$auditSummary.critical -gt 0 -or [int]$auditSummary.timedOut -gt 0) { $hasWarning = $true }
    } catch {
        Write-Verbose $_.Exception.Message
    }
    foreach ($scoped in @($deckReport, $wslRepairDoctor, $aionUiDoctor, $agentToolsDoctor, $msvcDoctor)) {
        if ($null -eq $scoped) { continue }
        try {
            if ([string]$scoped['status'] -in @('warning','critical','blocked','degraded','error')) { $hasWarning = $true }
        } catch {
            Write-Verbose $_.Exception.Message
        }
    }
    $started.Stop()

    $result = [ordered]@{
        schemaVersion = 1
        status = $(if ($hasError) { 'error' } elseif ($hasWarning) { 'warning' } else { 'success' })
        generatedAt = (Get-Date).ToString('o')
        durationMs = [long]$started.ElapsedMilliseconds
        scopes = @($Scopes)
        checks = @($checks.ToArray())
        secrets = $secretsDoctor
        aiUsagebar = $aiUsagebarDoctor
        aiMemory = $aiMemoryDoctor
        aionui = $aionUiDoctor
        aiConfig = $aiConfigDoctor
        aiProxies = $aiProxyDoctor
        wslRepair = $wslRepairDoctor
        githubCliAuth = $githubCliAuth
        deck = $deckReport
        auditSummary = $auditSummary
        auditResults = @($auditRows)
    }
    if ($null -ne $agentToolsDoctor)          { $result['agentTools'] = $agentToolsDoctor }
    if ($null -ne $windowsOptimizationDoctor) { $result['windowsOptimization'] = $windowsOptimizationDoctor }
    if ($null -ne $mcpDoctor)                 { $result['mcp'] = $mcpDoctor }
    if ($null -ne $msvcDoctor)                { $result['msvc'] = $msvcDoctor }
    return $result
}

function Add-BootstrapRepairPlanItem {
    param(
        [Parameter(Mandatory = $true)]$Items,
        [Parameter(Mandatory = $true)][string]$Id,
        [AllowEmptyString()][string]$Component = '',
        [ValidateSet('low','medium','high')][string]$Risk = 'medium',
        [bool]$RequiresAdmin = $false,
        [bool]$RollbackAvailable = $false,
        [string]$DryRunCommand = '',
        [string]$ExecuteCommand = '',
        [string]$Reason = '',
        [bool]$ConfirmationRequired = $true,
        # repairKind documenta a natureza do reparo: 'component' (component e um id real do catalogo),
        # 'app-tuning' (target e um AppTuning item), 'ai-tool' (install-cli --tool). Target carrega o id
        # alvo independe do tipo. Consumidores que tratam 'component' como catalogo DEVEM checar repairKind.
        [ValidateSet('component','app-tuning','ai-tool','reboot','other')][string]$RepairKind = 'component',
        [string]$Target = ''
    )

    $Items.Add([ordered]@{
        id = $Id
        component = $Component
        repairKind = $RepairKind
        target = $Target
        risk = $Risk
        requiresAdmin = [bool]$RequiresAdmin
        rollbackAvailable = [bool]$RollbackAvailable
        dryRunCommand = $DryRunCommand
        executeCommand = $ExecuteCommand
        reason = $Reason
        confirmationRequired = [bool]$ConfirmationRequired
    })
}

function New-BootstrapRepairPlan {
    param([AllowNull()]$DoctorReport = $null)

    $started = [Diagnostics.Stopwatch]::StartNew()
    $items = New-Object System.Collections.Generic.List[object]
    $repoCommand = '.\bootstrap-tools.ps1'

    if ($DoctorReport) {
        $wslRepair = $null
        try {
            if ($DoctorReport -is [System.Collections.IDictionary] -and $DoctorReport.Contains('wslRepair')) {
                $wslRepair = $DoctorReport['wslRepair']
            } elseif ($DoctorReport.PSObject.Properties['wslRepair']) {
                $wslRepair = $DoctorReport.wslRepair
            }
        } catch {
            $wslRepair = $null
        }
        if ($wslRepair) {
            $wslStatus = [string]$wslRepair['status']
            $wslCorrupt = [bool]$wslRepair['corruptionDetected']
            if ($wslCorrupt -or $wslStatus -in @('blocked','critical')) {
                $kind = [string]$wslRepair['corruptionKind']
                Add-BootstrapRepairPlanItem -Items $items -Id 'repair-wsl-registration' -Component 'wsl-core' -Risk 'high' -RequiresAdmin:$true -RollbackAvailable:$false -DryRunCommand "$repoCommand -Component wsl-core -DryRun -NonInteractive" -ExecuteCommand "$repoCommand -Component wsl-core -NonInteractive" -Reason ("WSL repair required: {0}. {1}" -f $kind, [string]$wslRepair['recommendedAction']) -ConfirmationRequired:$true
            }
        }

        foreach ($check in @($DoctorReport['checks'])) {
            $id = [string]$check['id']
            $status = [string]$check['status']
            if ($id -eq 'pending-reboot' -and [bool]$check['pending']) {
                Add-BootstrapRepairPlanItem -Items $items -Id 'restart-windows' -Component 'pending-reboot' -Risk 'low' -RequiresAdmin:$false -RollbackAvailable:$false -DryRunCommand '' -ExecuteCommand 'shutdown /r /t 0' -Reason ([string]$check['summary'])
            } elseif ($id -eq 'secrets' -and [string]$check['state'] -in @('needsMigration','plaintext','corrupt')) {
                Add-BootstrapRepairPlanItem -Items $items -Id 'repair-secrets-manifest' -Component 'bootstrap-secrets' -Risk 'medium' -RequiresAdmin:$false -RollbackAvailable:$true -DryRunCommand "$repoCommand -Component bootstrap-secrets -DryRun -NonInteractive" -ExecuteCommand "$repoCommand -Component bootstrap-secrets -NonInteractive" -Reason ([string]$check['summary'])
            } elseif ($id -eq 'wsl' -and $status -in @('timeout','corrupt','error') -and (@($items.ToArray() | Where-Object { [string]$_['id'] -eq 'repair-wsl-registration' }).Count -eq 0)) {
                Add-BootstrapRepairPlanItem -Items $items -Id 'repair-wsl-registration' -Component 'wsl-core' -Risk 'high' -RequiresAdmin:$true -RollbackAvailable:$false -DryRunCommand "$repoCommand -Component wsl-core -DryRun -NonInteractive" -ExecuteCommand "$repoCommand -Component wsl-core -NonInteractive" -Reason ([string]$check['summary']) -ConfirmationRequired:$true
            }
        }

        foreach ($row in @($DoctorReport['auditResults'])) {
            $component = [string]$row.Component
            if ([string]::IsNullOrWhiteSpace($component)) { continue }
            $severity = [string]$row.Severity
            if ($severity -notin @('NeedsInstall','NeedsRepair','RequiresRestart','ManualAction')) { continue }
            $risk = if ($severity -eq 'RequiresRestart') { 'high' } elseif ($severity -eq 'ManualAction') { 'medium' } else { 'low' }
            Add-BootstrapRepairPlanItem -Items $items -Id ("repair-{0}" -f $component) -Component $component -Risk $risk -RequiresAdmin:$false -RollbackAvailable:$false -DryRunCommand "$repoCommand -Component $component -DryRun -NonInteractive" -ExecuteCommand "$repoCommand -Component $component -NonInteractive" -Reason ([string]$row.HowToFix)
        }

        # MSVC: DLLs do runtime VC++ ausentes -> reparo via componente vcpp-redist.
        $msvc = $null
        try {
            if ($DoctorReport -is [System.Collections.IDictionary] -and $DoctorReport.Contains('msvc')) {
                $msvc = $DoctorReport['msvc']
            } elseif ($DoctorReport.PSObject.Properties['msvc']) {
                $msvc = $DoctorReport.msvc
            }
        } catch { $msvc = $null }
        if ($msvc) {
            $msvcComponent = ''
            try { $msvcComponent = [string]$msvc['repairComponent'] } catch { $msvcComponent = '' }
            if (-not [string]::IsNullOrWhiteSpace($msvcComponent)) {
                Add-BootstrapRepairPlanItem -Items $items -Id 'repair-msvc-runtime' -Component $msvcComponent -Risk 'low' -RequiresAdmin:$false -RollbackAvailable:$false -DryRunCommand "$repoCommand -Component $msvcComponent -DryRun -NonInteractive" -ExecuteCommand "$repoCommand -Component $msvcComponent -NonInteractive" -Reason ('Runtime MSVC (VC++) ausente; reinstale o redistribuivel. ' + [string]$msvc['summary']) -ConfirmationRequired:$true
            }
        }

        # Gestao tokens/memoria: itens de reparo das ferramentas de agente nao configuradas.
        # Graphify e placeholder seguro (sem repairComponent) e NUNCA entra no plano.
        $agentTools = $null
        try {
            if ($DoctorReport -is [System.Collections.IDictionary] -and $DoctorReport.Contains('agentTools')) {
                $agentTools = $DoctorReport['agentTools']
            } elseif ($DoctorReport.PSObject.Properties['agentTools']) {
                $agentTools = $DoctorReport.agentTools
            }
        } catch { $agentTools = $null }
        if ($agentTools) {
            $componentCatalog = $null
            try { $componentCatalog = Get-BootstrapComponentCatalog } catch { $componentCatalog = $null }
            $toolsMap = $null
            try { $toolsMap = $agentTools['tools'] } catch { $toolsMap = $null }
            if ($toolsMap) {
                foreach ($toolKey in @($toolsMap.Keys)) {
                    $tool = $toolsMap[$toolKey]
                    $configured = $false
                    try { $configured = [bool]$tool['configured'] } catch { $configured = $false }
                    if ($configured) { continue }

                    $repairKind = ''
                    try { $repairKind = [string]$tool['repairKind'] } catch { $repairKind = '' }
                    $target = ''
                    try { $target = [string]$tool['repairTarget'] } catch { $target = '' }
                    $displayName = ''
                    try { $displayName = [string]$tool['displayName'] } catch { $displayName = $target }
                    if ([string]::IsNullOrWhiteSpace($target)) { continue } # graphify/none: sem reparo automatico

                    $dryRunCommand = ''
                    $executeCommand = ''
                    # 'component' so e mantido quando o id existe MESMO no catalogo (campo component fica
                    # vazio para app-tuning/ai-tool, evitando ambiguidade para consumidores).
                    $componentField = ''
                    switch ($repairKind) {
                        'component' {
                            if ($null -ne $componentCatalog -and $componentCatalog.Contains($target)) {
                                $componentField = $target
                                $dryRunCommand = "$repoCommand -Component $target -DryRun -NonInteractive"
                                $executeCommand = "$repoCommand -Component $target -NonInteractive"
                            }
                        }
                        'app-tuning' {
                            $dryRunCommand = "$repoCommand -AppTuningItem $target -DryRun -NonInteractive"
                            $executeCommand = "$repoCommand -AppTuningItem $target -NonInteractive"
                        }
                        'ai-tool' {
                            # Ferramentas de IA (ex.: rtk) instalam pelo fluxo install-cli, nao por -Component.
                            $dryRunCommand = ".\install-cli.bat --tool $target --install --dry-run --yes"
                            $executeCommand = ".\install-cli.bat --tool $target --install --yes"
                        }
                        default { }
                    }
                    if ([string]::IsNullOrWhiteSpace($executeCommand)) { continue } # sem executor real: nao adiciona item

                    Add-BootstrapRepairPlanItem -Items $items -Id ("repair-agent-{0}" -f $target) -Component $componentField -RepairKind $repairKind -Target $target -Risk 'low' -RequiresAdmin:$false -RollbackAvailable:$false -DryRunCommand $dryRunCommand -ExecuteCommand $executeCommand -Reason ("Ferramenta de tokens/memoria nao configurada: {0}." -f $displayName) -ConfirmationRequired:$true
                }
            }
        }
    }

    $started.Stop()
    return [ordered]@{
        schemaVersion = 1
        generatedAt = (Get-Date).ToString('o')
        durationMs = [long]$started.ElapsedMilliseconds
        defaultExecution = 'manual-confirmation'
        items = @($items.ToArray())
    }
}

function Get-BootstrapPSScriptAnalyzerSummary {
    $module = Get-Module -ListAvailable -Name PSScriptAnalyzer | Sort-Object Version -Descending | Select-Object -First 1
    if (-not $module) {
        return [ordered]@{ available = $false; errors = $null; warnings = $null; note = 'PSScriptAnalyzer not installed.' }
    }
    $started = [Diagnostics.Stopwatch]::StartNew()
    try {
        $targets = @('bootstrap-tools.ps1','bootstrap-ui.ps1','install-cli.ps1') | ForEach-Object { Join-Path $PSScriptRoot $_ } | Where-Object { Test-Path -LiteralPath $_ }
        $job = Start-Job -ScriptBlock {
            param([string[]]$AnalyzerTargets)
            Import-Module PSScriptAnalyzer -Force
            $results = @()
            foreach ($target in @($AnalyzerTargets)) {
                $results += @(Invoke-ScriptAnalyzer -Path $target -Severity Warning,Error -ExcludeRule 'PSUseShouldProcessForStateChangingFunctions','PSAvoidUsingInvokeExpression')
            }
            [ordered]@{
                errors = @($results | Where-Object { $_.Severity -eq 'Error' }).Count
                warnings = @($results | Where-Object { $_.Severity -eq 'Warning' }).Count
            }
        } -ArgumentList (,$targets)
        try {
            if (-not (Wait-Job -Job $job -Timeout 20)) {
                try { Stop-Job -Job $job -ErrorAction SilentlyContinue } catch { }
                $started.Stop()
                return [ordered]@{
                    available = $true
                    version = [string]$module.Version
                    files = @($targets).Count
                    errors = $null
                    warnings = $null
                    timedOut = $true
                    durationMs = [long]$started.ElapsedMilliseconds
                    note = 'PSScriptAnalyzer summary timed out; run tests/bootstrap-quality-gates.tests.ps1 for authoritative budget.'
                }
            }
            $summary = Receive-Job -Job $job -ErrorAction Stop
        } finally {
            Remove-Job -Job $job -Force -ErrorAction SilentlyContinue
        }
        $started.Stop()
        return [ordered]@{
            available = $true
            version = [string]$module.Version
            files = @($targets).Count
            errors = [int]$summary['errors']
            warnings = [int]$summary['warnings']
            timedOut = $false
            durationMs = [long]$started.ElapsedMilliseconds
        }
    } catch {
        $started.Stop()
        return [ordered]@{ available = $true; errors = $null; warnings = $null; timedOut = $false; durationMs = [long]$started.ElapsedMilliseconds; note = $_.Exception.Message }
    }
}

function Test-BootstrapPrivateIpv4Address {
    param([Parameter(Mandatory = $true)][string]$Address)

    $parts = @($Address -split '\.')
    if ($parts.Count -ne 4) { return $true }
    $octets = @()
    foreach ($part in @($parts)) {
        $value = 0
        if (-not [int]::TryParse($part, [ref]$value)) { return $true }
        $octets += $value
    }
    if ($octets[0] -eq 10) { return $true }
    if ($octets[0] -eq 127) { return $true }
    if ($octets[0] -eq 169 -and $octets[1] -eq 254) { return $true }
    if ($octets[0] -eq 172 -and $octets[1] -ge 16 -and $octets[1] -le 31) { return $true }
    if ($octets[0] -eq 192 -and $octets[1] -eq 168) { return $true }
    if ($octets[0] -eq 0) { return $true }
    return $false
}

function ConvertTo-BootstrapSupportSafeText {
    param([AllowNull()][string]$Text)

    if ($null -eq $Text) { return $null }
    $safe = [string]$Text
    foreach ($root in @($env:USERPROFILE, $env:LOCALAPPDATA, $env:APPDATA, $env:TEMP)) {
        if ([string]::IsNullOrWhiteSpace($root)) { continue }
        $safe = $safe -replace [regex]::Escape($root), '[redacted-user-path]'
    }
    $safe = $safe -replace '(?i)(sk-[A-Za-z0-9_\-]{8,})', '[redacted]'
    $safe = $safe -replace '(?i)(ghp_[A-Za-z0-9_]{8,}|github_pat_[A-Za-z0-9_]{8,})', '[redacted]'
    $safe = $safe -replace '\b(GH_TOKEN|GITHUB_TOKEN|OPENAI_API_KEY|OPENAI_BASE_URL|OPENAI_MODEL|ANTHROPIC_API_KEY|GEMINI_API_KEY|GOOGLE_API_KEY|OPENROUTER_API_KEY|DEEPSEEK_API_KEY|XAI_API_KEY|DASHSCOPE_API_KEY|QWEN_API_KEY|ZAI_API_KEY|ZAI_BASE_URL|MOONSHOT_API_KEY|MOONSHOT_BASE_URL|KIMIPROXY_API_KEY|KIMIPROXY_BASE_URL|KIMIPROXY_MODEL|QWENPROXY_API_KEY|QWENPROXY_BASE_URL|QWENPROXY_MODEL|DEEPSPROXY_API_KEY|DEEPSPROXY_BASE_URL|DEEPSPROXY_MODEL|MIMO_AI_PROXY_API_KEY|MIMO_AI_PROXY_BASE_URL|MIMO_AI_PROXY_MODEL|ANTIGRAVITY_OPENAI_ADAPTER_API_KEY|ANTIGRAVITY_OPENAI_ADAPTER_BASE_URL|ANTIGRAVITY_OPENAI_ADAPTER_MODEL|QWEN_EMAIL|QWEN_PASSWORD|SERVICE_TOKEN|SERVICE_TOKENS|USER_ID|USER_IDS|XIAOMI_CHATBOT_PH|XIAOMI_CHATBOT_PHS|MIMO_SERVICE_TOKEN|MIMO_SERVICE_TOKENS|MIMO_USER_ID|MIMO_USER_IDS|ANTIGRAVITY_UPSTREAM_API_KEY|ANTIGRAVITY_UPSTREAM_URL)\b', '[redacted-env-name]'
    $safe = $safe -replace '(?i)(bearer\s+)[A-Za-z0-9._\-]+', '$1[redacted]'
    $ipv4Pattern = '\b(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b'
    $safe = [regex]::Replace($safe, $ipv4Pattern, {
        param($match)
        if (Test-BootstrapPrivateIpv4Address -Address ([string]$match.Value)) { return [string]$match.Value }
        return '[redacted-public-ip]'
    })
    return $safe
}

function ConvertTo-BootstrapSupportSafeObject {
    param(
        [AllowNull()]$Value,
        [string]$Name = ''
    )

    $lowerName = $Name.ToLowerInvariant()
    if ($lowerName -match 'protecteddata|(^|[^a-z])secret($|[^a-z])|token($|[^a-z])|apikey|api_key|password|credential|steamlogin|steamid|refresh') {
        return '[redacted]'
    }
    if ($null -eq $Value) { return $null }
    if ($Value -is [string]) {
        return (ConvertTo-BootstrapSupportSafeText -Text ([string]$Value))
    }
    if ($Value -is [ValueType]) { return $Value }
    if ($Value -is [System.Collections.IDictionary]) {
        $safe = [ordered]@{}
        foreach ($key in @($Value.Keys)) {
            $safe[[string]$key] = ConvertTo-BootstrapSupportSafeObject -Value $Value[$key] -Name ([string]$key)
        }
        return $safe
    }
    if ($Value -is [System.Collections.IEnumerable] -and -not ($Value -is [string])) {
        $list = New-Object System.Collections.Generic.List[object]
        foreach ($item in @($Value)) { $list.Add((ConvertTo-BootstrapSupportSafeObject -Value $item -Name $Name)) }
        return @($list.ToArray())
    }
    if ($Value -is [psobject]) {
        $safeObject = [ordered]@{}
        foreach ($prop in @($Value.PSObject.Properties)) {
            $safeObject[[string]$prop.Name] = ConvertTo-BootstrapSupportSafeObject -Value $prop.Value -Name ([string]$prop.Name)
        }
        return $safeObject
    }
    return $Value
}

function Get-BootstrapNamedValue {
    param(
        [AllowNull()]$Object,
        [Parameter(Mandatory = $true)][string]$Name,
        [AllowNull()]$Default = $null
    )

    if ($null -eq $Object) { return $Default }
    try {
        if (Test-BootstrapMapContainsKey -Map $Object -Key $Name) { return $Object[$Name] }
        if ($Object.PSObject.Properties[$Name]) { return $Object.PSObject.Properties[$Name].Value }
    } catch {
        Write-Verbose $_.Exception.Message
    }
    return $Default
}

function New-BootstrapSupportBundle {
    param(
        [Parameter(Mandatory = $true)]$DoctorReport,
        [Parameter(Mandatory = $true)]$RepairPlan,
        [Parameter(Mandatory = $true)]$ResultPayload,
        [string]$DestinationPath = ''
    )

    $started = [Diagnostics.Stopwatch]::StartNew()
    $timestamp = $script:RunId
    $tempRoot = $env:TEMP
    if ([string]::IsNullOrWhiteSpace($tempRoot)) { $tempRoot = $env:TMPDIR }
    if ([string]::IsNullOrWhiteSpace($tempRoot)) { $tempRoot = $env:TMP }
    if ([string]::IsNullOrWhiteSpace($tempRoot)) { $tempRoot = [System.IO.Path]::GetTempPath() }
    if ([string]::IsNullOrWhiteSpace($tempRoot)) { $tempRoot = (Get-Location).Path }
    if ([string]::IsNullOrWhiteSpace($DestinationPath)) {
        $DestinationPath = Join-Path $tempRoot ("phasezero-support_{0}.zip" -f $timestamp)
    }
    $staging = Join-Path $tempRoot ("phasezero-support_{0}_{1}" -f $timestamp, ([Guid]::NewGuid().ToString('N')))
    $null = New-Item -Path $staging -ItemType Directory -Force
    $null = New-Item -Path (Join-Path $staging 'logs') -ItemType Directory -Force
    try {
        $deckReport = $null
        try {
            if ($DoctorReport -is [System.Collections.IDictionary] -and $DoctorReport.Contains('deck')) {
                $deckReport = $DoctorReport['deck']
            } elseif ($DoctorReport -and $DoctorReport.PSObject.Properties['deck']) {
                $deckReport = $DoctorReport.deck
            }
        } catch {
            $deckReport = $null
        }
        if ($null -eq $deckReport) { $deckReport = New-BootstrapSteamDeckDoctorReport }
        $githubAuth = $null
        try {
            if ($DoctorReport -is [System.Collections.IDictionary] -and $DoctorReport.Contains('githubCliAuth')) {
                $githubAuth = $DoctorReport['githubCliAuth']
            } elseif ($DoctorReport -and $DoctorReport.PSObject.Properties['githubCliAuth']) {
                $githubAuth = $DoctorReport.githubCliAuth
            }
        } catch {
            $githubAuth = $null
        }
        if ($null -eq $githubAuth) { $githubAuth = Get-BootstrapGithubCliAuthHealth }
        $secretsDoctor = $null
        try {
            if ($DoctorReport -is [System.Collections.IDictionary] -and $DoctorReport.Contains('secrets')) {
                $secretsDoctor = $DoctorReport['secrets']
            } elseif ($DoctorReport -and $DoctorReport.PSObject.Properties['secrets']) {
                $secretsDoctor = $DoctorReport.secrets
            }
        } catch {
            $secretsDoctor = $null
        }
        if ($null -eq $secretsDoctor) { $secretsDoctor = New-BootstrapSecretsDoctorReport }
        $aiUsagebarDoctor = $null
        try {
            if ($DoctorReport -is [System.Collections.IDictionary] -and $DoctorReport.Contains('aiUsagebar')) {
                $aiUsagebarDoctor = $DoctorReport['aiUsagebar']
            } elseif ($DoctorReport -and $DoctorReport.PSObject.Properties['aiUsagebar']) {
                $aiUsagebarDoctor = $DoctorReport.aiUsagebar
            }
        } catch {
            $aiUsagebarDoctor = $null
        }
        if ($null -eq $aiUsagebarDoctor) { $aiUsagebarDoctor = New-BootstrapAiUsagebarDoctorReport }
        $aiMemoryDoctor = $null
        try {
            if ($DoctorReport -is [System.Collections.IDictionary] -and $DoctorReport.Contains('aiMemory')) {
                $aiMemoryDoctor = $DoctorReport['aiMemory']
            } elseif ($DoctorReport -and $DoctorReport.PSObject.Properties['aiMemory']) {
                $aiMemoryDoctor = $DoctorReport.aiMemory
            }
        } catch {
            $aiMemoryDoctor = $null
        }
        if ($null -eq $aiMemoryDoctor) { $aiMemoryDoctor = New-BootstrapAiMemoryDoctorReport }
        $aionUiDoctor = $null
        try {
            if ($DoctorReport -is [System.Collections.IDictionary] -and $DoctorReport.Contains('aionui')) {
                $aionUiDoctor = $DoctorReport['aionui']
            } elseif ($DoctorReport -and $DoctorReport.PSObject.Properties['aionui']) {
                $aionUiDoctor = $DoctorReport.aionui
            }
        } catch {
            $aionUiDoctor = $null
        }
        if ($null -eq $aionUiDoctor) { $aionUiDoctor = Get-BootstrapAionUiDoctorReport }
        $aiProxyDoctor = $null
        try {
            if ($DoctorReport -is [System.Collections.IDictionary] -and $DoctorReport.Contains('aiProxies')) {
                $aiProxyDoctor = $DoctorReport['aiProxies']
            } elseif ($DoctorReport -and $DoctorReport.PSObject.Properties['aiProxies']) {
                $aiProxyDoctor = $DoctorReport.aiProxies
            }
        } catch {
            $aiProxyDoctor = $null
        }
        if ($null -eq $aiProxyDoctor) { $aiProxyDoctor = New-BootstrapAiProxySuiteDoctorReport }
        $aiConfigDoctor = $null
        try {
            if ($DoctorReport -is [System.Collections.IDictionary] -and $DoctorReport.Contains('aiConfig')) {
                $aiConfigDoctor = $DoctorReport['aiConfig']
            } elseif ($DoctorReport -and $DoctorReport.PSObject.Properties['aiConfig']) {
                $aiConfigDoctor = $DoctorReport.aiConfig
            }
        } catch {
            $aiConfigDoctor = $null
        }
        if ($null -eq $aiConfigDoctor) { $aiConfigDoctor = New-BootstrapAiConfigDoctorReport }
        $wslRepairDoctor = $null
        try {
            if ($DoctorReport -is [System.Collections.IDictionary] -and $DoctorReport.Contains('wslRepair')) {
                $wslRepairDoctor = $DoctorReport['wslRepair']
            } elseif ($DoctorReport -and $DoctorReport.PSObject.Properties['wslRepair']) {
                $wslRepairDoctor = $DoctorReport.wslRepair
            }
        } catch {
            $wslRepairDoctor = $null
        }
        if ($null -eq $wslRepairDoctor) { $wslRepairDoctor = New-BootstrapWslRepairDoctorReport }

        Write-BootstrapJsonFile -Path (Join-Path $staging 'doctor.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value $DoctorReport -Name 'doctor')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'repair-plan.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value $RepairPlan -Name 'repairPlan')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'result.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value $ResultPayload -Name 'result')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'secrets-doctor.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value $secretsDoctor -Name 'secretsDoctor')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'ai-usagebar.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value $aiUsagebarDoctor -Name 'aiUsagebar')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'ai-memory.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value $aiMemoryDoctor -Name 'aiMemory')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'aionui.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value $aionUiDoctor -Name 'aionui')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'ai-proxy-suite.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value $aiProxyDoctor -Name 'aiProxies')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'ai-config.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value $aiConfigDoctor -Name 'aiConfig')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'ide-targets.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value (Get-BootstrapNamedValue -Object $aiConfigDoctor -Name 'targets' -Default @()) -Name 'ideTargets')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'mcp-health.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value (Get-BootstrapNamedValue -Object $aiConfigDoctor -Name 'mcps' -Default ([ordered]@{})) -Name 'mcpHealth')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'wsl-repair.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value $wslRepairDoctor -Name 'wslRepair')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'deck-doctor.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value $deckReport -Name 'deckDoctor')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'deck-power.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value (Get-BootstrapNamedValue -Object $deckReport -Name 'power' -Default ([ordered]@{})) -Name 'deckPower')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'deck-display.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value (Get-BootstrapNamedValue -Object $deckReport -Name 'display' -Default ([ordered]@{})) -Name 'deckDisplay')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'deck-libraries.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value (Get-BootstrapNamedValue -Object $deckReport -Name 'libraries' -Default @()) -Name 'deckLibraries')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'github-auth.json') -Value (ConvertTo-BootstrapSupportSafeObject -Value $githubAuth -Name 'githubAuth')
        Write-BootstrapJsonFile -Path (Join-Path $staging 'psscriptanalyzer-summary.json') -Value (Get-BootstrapPSScriptAnalyzerSummary)
        Write-BootstrapJsonFile -Path (Join-Path $staging 'environment.json') -Value ([ordered]@{
            generatedAt = (Get-Date).ToString('o')
            osVersion = [Environment]::OSVersion.VersionString
            is64BitOperatingSystem = [Environment]::Is64BitOperatingSystem
            is64BitProcess = [Environment]::Is64BitProcess
            powershell = [string]$PSVersionTable.PSVersion
        })
        if (-not [string]::IsNullOrWhiteSpace($script:LogPath) -and (Test-Path -LiteralPath $script:LogPath)) {
            $logText = Microsoft.PowerShell.Management\Get-Content -LiteralPath $script:LogPath -Raw -Encoding utf8 -ErrorAction SilentlyContinue
            $safeLogText = [string](ConvertTo-BootstrapSupportSafeObject -Value $logText -Name 'log')
            $safeLogText | Set-Content -LiteralPath (Join-Path $staging 'logs\current.log') -Encoding utf8
        }
        if (Test-Path -LiteralPath $DestinationPath) { Remove-Item -LiteralPath $DestinationPath -Force }
        # CreateFromDirectory e deterministico (zipa todo o staging); evita o bug de wildcard do
        # Compress-Archive no PS 5.1, que omitia arquivos de forma intermitente (ex.: ai-proxy-suite.json).
        Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
        [System.IO.Compression.ZipFile]::CreateFromDirectory($staging, $DestinationPath)
        $fileInfo = Get-Item -LiteralPath $DestinationPath
        $includedFiles = @('doctor.json','repair-plan.json','result.json','secrets-doctor.json','ai-usagebar.json','ai-memory.json','aionui.json','ai-proxy-suite.json','ai-config.json','ide-targets.json','mcp-health.json','wsl-repair.json','deck-doctor.json','deck-power.json','deck-display.json','deck-libraries.json','github-auth.json','psscriptanalyzer-summary.json','environment.json','logs/current.log')
        $started.Stop()
        return [ordered]@{
            path = [string]$fileInfo.FullName
            sizeBytes = [long]$fileInfo.Length
            durationMs = [long]$started.ElapsedMilliseconds
            included = @($includedFiles)
            redaction = 'secret-keys-and-protected-envelope-redacted'
        }
    } finally {
        Remove-Item -LiteralPath $staging -Recurse -Force -ErrorAction SilentlyContinue
    }
}

function Get-BootstrapReleaseCommit {
    try {
        $git = Resolve-CommandPath -Name 'git'
        if ($git) {
            $commit = [string]((& $git -C $PSScriptRoot rev-parse HEAD 2>$null | Select-Object -First 1))
            if (-not [string]::IsNullOrWhiteSpace($commit)) { return $commit.Trim() }
        }
    } catch {
        Write-Verbose $_.Exception.Message
    }
    return 'unknown'
}

function Get-BootstrapReleaseVersion {
    param([string]$RequestedVersion = '')

    if (-not [string]::IsNullOrWhiteSpace($RequestedVersion)) { return $RequestedVersion.Trim() }
    $versionPath = Join-Path $PSScriptRoot 'version.json'
    if (Test-Path -LiteralPath $versionPath) {
        try {
            $versionJson = Microsoft.PowerShell.Management\Get-Content -LiteralPath $versionPath -Raw -Encoding utf8 | ConvertFrom-Json -ErrorAction Stop
            if ($versionJson.PSObject.Properties['version'] -and -not [string]::IsNullOrWhiteSpace([string]$versionJson.version)) {
                return ([string]$versionJson.version).Trim()
            }
        } catch {
            Write-Verbose $_.Exception.Message
        }
    }
    return '0.0.0'
}

function New-BootstrapUpgradeScriptText {
    return @'
param(
    [string]$InstallRoot = '',
    [switch]$WhatIf
)

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$packageRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
if ([string]::IsNullOrWhiteSpace($InstallRoot)) {
    $InstallRoot = Split-Path -Parent $packageRoot
}
if (-not (Test-Path -LiteralPath $InstallRoot)) {
    $null = New-Item -Path $InstallRoot -ItemType Directory -Force
}

$files = @('bootstrap-ui.ps1','bootstrap-ui.bat','install-cli.ps1','install-cli.bat','version.json','CHANGELOG.md')
foreach ($file in $files) {
    $source = Join-Path $packageRoot $file
    if (-not (Test-Path -LiteralPath $source)) { continue }
    $target = Join-Path $InstallRoot $file
    if ($WhatIf) {
        Write-Output ("Would copy {0} -> {1}" -f $source, $target)
        continue
    }
    Copy-Item -LiteralPath $source -Destination $target -Force
}

Write-Output ("PhaseZero upgrade package applied to {0}" -f $InstallRoot)
'@
}

function Assert-BootstrapReleaseTextSafe {
    param([Parameter(Mandatory = $true)][string]$Root)

    $forbidden = @('ghp_', 'sk-', 'sk-or-', 'protectedData')
    foreach ($file in @(Get-ChildItem -LiteralPath $Root -Recurse -File)) {
        $text = ''
        try { $text = Microsoft.PowerShell.Management\Get-Content -LiteralPath $file.FullName -Raw -Encoding utf8 -ErrorAction Stop } catch { $text = '' }
        foreach ($pattern in $forbidden) {
            if ($text -like ("*{0}*" -f $pattern)) {
                throw ("ReleasePack unsafe literal in {0}: {1}" -f $file.Name, $pattern)
            }
        }
    }
}

function New-BootstrapReleasePack {
    param(
        [string]$Version = '',
        [string]$DestinationRoot = ''
    )

    $started = [Diagnostics.Stopwatch]::StartNew()
    $resolvedVersion = Get-BootstrapReleaseVersion -RequestedVersion $Version
    if ($resolvedVersion -notmatch '^\d+\.\d+\.\d+([A-Za-z0-9\.\-_]+)?$') {
        throw "Release version invalida: $resolvedVersion"
    }
    if ([string]::IsNullOrWhiteSpace($DestinationRoot)) {
        $DestinationRoot = Join-Path $PSScriptRoot 'dist'
    }
    $null = New-Item -Path $DestinationRoot -ItemType Directory -Force
    $destinationInfo = Get-Item -LiteralPath $DestinationRoot
    $releaseName = "PhaseZero-v$resolvedVersion"
    $staging = Join-Path $destinationInfo.FullName $releaseName
    if (Test-Path -LiteralPath $staging) { Remove-Item -LiteralPath $staging -Recurse -Force }
    $null = New-Item -Path $staging -ItemType Directory -Force

    $commit = Get-BootstrapReleaseCommit
    $contract = Get-BootstrapUiContract
    $contractVersion = [string]$contract['schemaVersion']
    $builtAt = (Get-Date).ToUniversalTime().ToString('o')

    foreach ($fileName in @('bootstrap-ui.ps1','bootstrap-ui.bat','install-cli.ps1','install-cli.bat')) {
        $source = Join-Path $PSScriptRoot $fileName
        if (Test-Path -LiteralPath $source) {
            Copy-Item -LiteralPath $source -Destination (Join-Path $staging $fileName) -Force
        }
    }

    $versionPayload = [ordered]@{
        schema = 'https://phasezero.local/schemas/version.json'
        version = $resolvedVersion
        channel = 'local'
        commit = $commit
        date = $builtAt
        contractVersion = $contractVersion
        minimumPowerShellVersion = '5.1'
        minimumPesterVersion = '3.4.0'
    }
    $versionPath = Join-Path $staging 'version.json'
    Write-BootstrapJsonFile -Path $versionPath -Value $versionPayload

    $changelogPath = Join-Path $staging 'CHANGELOG.md'
    @(
        "# PhaseZero $resolvedVersion"
        ''
        ("- Commit: {0}" -f $commit)
        ("- Date: {0}" -f $builtAt)
        ("- UI contract: {0}" -f $contractVersion)
        '- Local support, diagnostic, repair planning, BAT/CLI and UI package.'
    ) | Set-Content -LiteralPath $changelogPath -Encoding utf8

    $upgradePath = Join-Path $staging 'upgrade.ps1'
    Set-Content -LiteralPath $upgradePath -Value (New-BootstrapUpgradeScriptText) -Encoding utf8

    Assert-BootstrapReleaseTextSafe -Root $staging

    $zipPath = Join-Path $destinationInfo.FullName ("{0}.zip" -f $releaseName)
    if (Test-Path -LiteralPath $zipPath) { Remove-Item -LiteralPath $zipPath -Force }
    # Determinismo: CreateFromDirectory evita o bug de wildcard do Compress-Archive (PS 5.1).
    Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
    [System.IO.Compression.ZipFile]::CreateFromDirectory($staging, $zipPath)

    $checksumsPath = Join-Path $destinationInfo.FullName 'SHA256SUMS.txt'
    $checksumRows = New-Object System.Collections.Generic.List[string]
    foreach ($artifact in @($zipPath, $changelogPath, $versionPath, $upgradePath)) {
        $hash = Get-BootstrapFileSha256 -Path $artifact
        $checksumRows.Add(("{0}  {1}" -f $hash, (Split-Path -Leaf $artifact)))
    }
    $checksumRows.ToArray() | Set-Content -LiteralPath $checksumsPath -Encoding ascii

    $started.Stop()
    return [ordered]@{
        schemaVersion = 1
        version = $resolvedVersion
        commit = $commit
        date = $builtAt
        contractVersion = $contractVersion
        durationMs = [long]$started.ElapsedMilliseconds
        zipPath = $zipPath
        checksumsPath = $checksumsPath
        changelogPath = $changelogPath
        versionJsonPath = $versionPath
        upgradePath = $upgradePath
    }
}

function Invoke-BootstrapReleasePackMode {
    Write-Log "Modo: ReleasePack"
    $pack = New-BootstrapReleasePack -Version $ReleaseVersion -DestinationRoot $ReleaseOutputDir
    if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
        Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value ([ordered]@{
            status = 'success'
            exitCode = 0
            mode = 'release-pack'
            generatedAt = (Get-Date).ToString('o')
            logPath = $script:LogPath
            resultPath = $script:ResultPath
            releasePack = $pack
        })
    }
    Write-Log ("ReleasePack: {0}" -f [string]$pack['zipPath'])
}

function Invoke-BootstrapDoctorMode {
    $scopes = Resolve-BootstrapDoctorScopes -Scopes $DoctorScope
    Write-Log ("Modo: Doctor (scopes={0})" -f (@($scopes) -join ','))
    $doctor = New-BootstrapDoctorReport -AuditTimeoutSeconds $AuditTimeoutSeconds -AuditComponentTimeoutSeconds $AuditComponentTimeoutSeconds -Scopes $scopes
    $repairPlan = New-BootstrapRepairPlan -DoctorReport $doctor
    $status = [string]$doctor['status']
    if ($status -eq 'error') { $status = 'warning' }
    Write-Log ("Doctor: status={0} checks={1} auditCritical={2} repairItems={3}" -f $status, @($doctor['checks']).Count, [int]$doctor['auditSummary'].critical, @($repairPlan['items']).Count)
    if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
        Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value ([ordered]@{
            status = $status
            exitCode = 0
            mode = 'doctor'
            generatedAt = (Get-Date).ToString('o')
            logPath = $script:LogPath
            resultPath = $script:ResultPath
            doctor = $doctor
            repairPlan = $repairPlan
        })
    }
    Write-Log "Log salvo em: $script:LogPath"
}

function Invoke-BootstrapSupportBundleMode {
    Write-Log "Modo: SupportBundle"
    $doctor = New-BootstrapDoctorReport -AuditTimeoutSeconds $AuditTimeoutSeconds -AuditComponentTimeoutSeconds $AuditComponentTimeoutSeconds
    $repairPlan = New-BootstrapRepairPlan -DoctorReport $doctor
    $status = [string]$doctor['status']
    if ($status -eq 'error') { $status = 'warning' }
    $payload = [ordered]@{
        status = $status
        exitCode = 0
        mode = 'support-bundle'
        generatedAt = (Get-Date).ToString('o')
        logPath = $script:LogPath
        resultPath = $script:ResultPath
        doctor = $doctor
        repairPlan = $repairPlan
    }
    $bundle = New-BootstrapSupportBundle -DoctorReport $doctor -RepairPlan $repairPlan -ResultPayload $payload
    $payload['supportBundle'] = $bundle
    if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
        Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value $payload
    }
    Write-Log ("Support bundle: {0}" -f [string]$bundle['path'])
}

function Invoke-BootstrapRepairPlanMode {
    param([string]$ExecutePath = '')

    if (-not [string]::IsNullOrWhiteSpace($ExecutePath)) {
        $plan = Read-BootstrapJsonFile -Path $ExecutePath
        $itemCount = 0
        try { $itemCount = @($plan['items']).Count } catch { $itemCount = 0 }
        if ($NonInteractive -or -not $Interactive) {
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value ([ordered]@{
                    status = 'blocked'
                    exitCode = 2
                    mode = 'repair-plan'
                    blockerKind = 'repair-plan-confirmation-required'
                    action = 'rerun-interactive'
                    error = 'Execucao de RepairPlan exige confirmacao manual interativa.'
                    howToFix = 'Abra a UI/painel Saude ou rode novamente em modo interativo e confirme cada lote.'
                    repairPlan = $plan
                })
            }
            Write-Log 'RepairPlan bloqueado: confirmacao manual obrigatoria.' 'WARN'
            return [pscustomobject]@{ ExitCode = 2; Status = 'blocked'; ItemCount = $itemCount }
        }
        $requiresAdminItems = @($plan['items'] | Where-Object { [bool]$_['requiresAdmin'] })
        if ($requiresAdminItems.Count -gt 0 -and -not (Test-IsAdmin)) {
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value ([ordered]@{
                    status = 'blocked'
                    exitCode = 2
                    mode = 'repair-plan'
                    blockerKind = 'repair-plan-admin-required'
                    action = 'rerun-elevated'
                    error = 'RepairPlan contem item que exige administrador.'
                    howToFix = 'Abra PowerShell como administrador/elevado e confirme o RepairPlan pela UI.'
                    repairPlan = $plan
                })
            }
            Write-Log 'RepairPlan bloqueado: item exige administrador.' 'WARN'
            return [pscustomobject]@{ ExitCode = 2; Status = 'blocked'; ItemCount = $itemCount }
        }
        Write-Log ("RepairPlan carregado: {0} item(ns). Execucao automatica ainda exige fluxo UI confirmado." -f $itemCount)
        if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
            Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value ([ordered]@{
                status = 'blocked'
                exitCode = 2
                mode = 'repair-plan'
                blockerKind = 'repair-plan-ui-required'
                error = 'Execucao detalhada da fila de reparo deve ser confirmada pela UI.'
                repairPlan = $plan
            })
        }
        return [pscustomobject]@{ ExitCode = 2; Status = 'blocked'; ItemCount = $itemCount }
    }

    # RepairPlan honra -DoctorScope: permite gerar um plano focado (ex.: agent-tools/tokens-memoria)
    # em vez do Doctor completo. Sem scope, mantem o comportamento legado ('all').
    $repairScopes = Resolve-BootstrapDoctorScopes -Scopes $DoctorScope
    $doctor = New-BootstrapDoctorReport -AuditTimeoutSeconds $AuditTimeoutSeconds -AuditComponentTimeoutSeconds $AuditComponentTimeoutSeconds -Scopes $repairScopes
    $repairPlan = New-BootstrapRepairPlan -DoctorReport $doctor
    if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
        Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value ([ordered]@{
            status = 'success'
            exitCode = 0
            mode = 'repair-plan'
            generatedAt = (Get-Date).ToString('o')
            scopes = @($repairScopes)
            doctor = $doctor
            repairPlan = $repairPlan
        })
    }
    Write-Log ("RepairPlan gerado (scopes={0}): {1} item(ns)." -f (@($repairScopes) -join ','), @($repairPlan['items']).Count)
    return [pscustomobject]@{ ExitCode = 0; Status = 'success'; ItemCount = @($repairPlan['items']).Count }
}

function Invoke-BootstrapProfileMode {
    if ($Interactive -and $NonInteractive) {
        throw 'Use apenas um modo de entrada: -Interactive ou -NonInteractive.'
    }

    $resolvedWorkspaceRoot = if ([string]::IsNullOrWhiteSpace($WorkspaceRoot)) {
        Get-BootstrapDefaultWorkspaceRoot
    } else {
        $WorkspaceRoot
    }

    if ($ListProfiles) {
        Show-BootstrapProfiles
        return
    }

    if ($ListHostHealthModes) {
        Show-BootstrapHostHealthModes
        return
    }

    if ($ListAppTuningCatalog) {
        Show-BootstrapAppTuningCatalog
        return
    }

    if ($ListApps) {
        Show-BootstrapApps
        return
    }

    if ($Rollback) {
        $rollbackResult = Invoke-BootstrapRollback -ChangesPath $ChangesPath -AggressiveRollback:$AggressiveRollback -DryRun:$DryRun
        if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
            Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value ([ordered]@{
                status = if ($DryRun) { 'planned' } else { 'success' }
                mode = 'rollback'
                dryRun = [bool]$DryRun
                generatedAt = (Get-Date).ToString('o')
                logPath = $script:LogPath
                resultPath = $script:ResultPath
                changesPath = $ChangesPath
                plannedActions = @($rollbackResult.plannedActions)
                message = if ($DryRun) { 'Rollback dry-run planejado; nenhuma mutacao executada.' } else { 'Rollback de tweaks de registro e autostart concluido (ver log).' }
            })
        }
        return
    }

    if ($Audit) {
        $selection = Get-BootstrapSelection
        $resolution = Resolve-BootstrapComponents -SelectedProfiles $selection.Profiles -SelectedComponents $selection.Components -ExcludedComponents $selection.Excludes
        $resolvedCloneBaseDir = Resolve-BootstrapCloneBaseDir -ExplicitCloneBaseDir $CloneBaseDir -ResolvedWorkspaceRoot $resolvedWorkspaceRoot -ResolvedComponents $resolution.ResolvedComponents
        $state = New-BootstrapState -Selection $selection -ResolvedWorkspaceRoot $resolvedWorkspaceRoot -ResolvedCloneBaseDir $resolvedCloneBaseDir
        $auditRows = @()
        $auditRecord = $null
        try {
            $auditRecord = Invoke-BootstrapAuditMode -Resolution $resolution -Repair:$Repair -State $state -TimeoutSeconds $AuditTimeoutSeconds -ComponentTimeoutSeconds $AuditComponentTimeoutSeconds
            if ($null -ne $auditRecord) {
                $auditRows = @($auditRecord)
            }
            try { $auditPhaseZero = Invoke-BootstrapPhaseZeroBaselineProbe } catch { }
        } catch {
            Write-Log ("Audit: execucao interrompida antes de concluir: {0}" -f $_.Exception.Message) 'ERROR'
            Write-BootstrapExceptionStackTrace -ErrorRecord $_
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                try {
                    Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{
                        mode = 'audit'
                        workspaceRoot = $resolvedWorkspaceRoot
                        cloneBaseDir = $resolvedCloneBaseDir
                        auditPartial = $true
                        note = 'Invoke-BootstrapAuditMode falhou; result.json gravado com erro para a UI nao ficar sem ficheiro.'
                    })
                } catch {
                    try {
                        Write-Log ("Audit: falha secundaria ao gravar result.json de erro: {0}" -f $_.Exception.Message) 'ERROR'
                    } catch {
                    }
                }
            }
            return
        }

        if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
            try {
                $summary = New-BootstrapAuditSeveritySummary -Rows $auditRows
                $status = if ([int]$summary.critical -gt 0) { 'warning' } else { 'success' }
                Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value ([ordered]@{
                    status = $status
                    mode = 'audit'
                    generatedAt = (Get-Date).ToString('o')
                    logPath = $script:LogPath
                    resultPath = $script:ResultPath
                    workspaceRoot = $resolvedWorkspaceRoot
                    cloneBaseDir = $resolvedCloneBaseDir
                    auditSummary = $summary
                    auditPhaseZero = $auditPhaseZero
                    auditResults = @($auditRows | ForEach-Object {
                        [ordered]@{
                            component = [string]$_.Component
                            status = [string]$_.Status
                            severity = [string]$_.Severity
                            critical = [bool]$_.Critical
                            detail = [string]$_.Detail
                            howToFix = [string]$_.HowToFix
                            durationMs = [long]$_.DurationMs
                            timedOut = [bool]$_.TimedOut
                            probeSource = [string]$_.ProbeSource
                        }
                    })
                })
            } catch {
                Write-Log ("Audit: falha ao serializar/gravar result.json (audit concluido em memoria): {0}" -f $_.Exception.Message) 'ERROR'
                Write-BootstrapExceptionStackTrace -ErrorRecord $_
                try {
                    $summary = New-BootstrapAuditSeveritySummary -Rows $auditRows
                    $fallback = [ordered]@{
                        status = 'warning'
                        mode = 'audit'
                        generatedAt = (Get-Date).ToString('o')
                        logPath = $script:LogPath
                        resultPath = $script:ResultPath
                        workspaceRoot = $resolvedWorkspaceRoot
                        cloneBaseDir = $resolvedCloneBaseDir
                        error = [string]$_.Exception.Message
                        howToFix = 'O audit terminou mas o JSON completo falhou; veja o log. Tente reduzir escopo ou atualizar o bootstrap.'
                        auditSummary = $summary
                        serializationFallback = $true
                    }
                    $utf8 = New-Object System.Text.UTF8Encoding($false)
                    [System.IO.File]::WriteAllText($script:ResultPath, ([string](ConvertTo-Json -InputObject $fallback -Depth 8)), $utf8)
                } catch {
                    Write-Log ("Audit: impossivel gravar result.json minimo: {0}" -f $_.Exception.Message) 'ERROR'
                }
            }
        }
        return
    }

    if ($ListComponents) {
        Show-BootstrapComponents
        return
    }

    $selection = Get-BootstrapSelection

    $completedFromCheckpoint = @()
    if ($Resume) {
        $checkpoint = Load-BootstrapCheckpoint
        if ($checkpoint) {
            Write-Log "Retomando instalacao a partir do checkpoint de $($checkpoint.Timestamp)..."
            $completedFromCheckpoint = @($checkpoint.CompletedComponents)
        } else {
            Write-Log "Nenhum checkpoint encontrado para retomar. Iniciando do zero." 'WARN'
        }
    }

    $resolution = Resolve-BootstrapComponents -SelectedProfiles $selection.Profiles -SelectedComponents $selection.Components -ExcludedComponents $selection.Excludes
    $resolvedCloneBaseDir = Resolve-BootstrapCloneBaseDir -ExplicitCloneBaseDir $CloneBaseDir -ResolvedWorkspaceRoot $resolvedWorkspaceRoot -ResolvedComponents $resolution.ResolvedComponents
    $usesSteamDeckFlow = Get-BootstrapUsesSteamDeckFlow -Selection $selection -Resolution $resolution
    $resolvedSteamDeckVersion = if ($usesSteamDeckFlow) { Get-BootstrapResolvedSteamDeckVersion -RequestedVersion $SteamDeckVersion } else { '' }
    $resolvedHostHealthMode = if ($selection.HostHealth) { $selection.HostHealth } else { Get-BootstrapDefaultHostHealthMode -Selection $selection -Resolution $resolution }
    $appTuningPlan = Resolve-BootstrapAppTuningSelection -Mode $selection.AppTuning -Categories $selection.AppTuningCategories -Items $selection.AppTuningItems -ExcludedItems $selection.ExcludedAppTuningItems -Selection $selection -Resolution $resolution
    $resolvedAppTuningMode = [string]$appTuningPlan.mode
    $previewData = Get-BootstrapPreviewData -SelectedProfiles $selection.Profiles -SelectedComponents $selection.Components -ExcludedComponents $selection.Excludes -RequestedSteamDeckVersion $SteamDeckVersion -RequestedHostHealthMode $resolvedHostHealthMode -RequestedAppTuningMode $selection.AppTuning -RequestedAppTuningCategories $selection.AppTuningCategories -RequestedAppTuningItems $selection.AppTuningItems -ExcludedAppTuningItems $selection.ExcludedAppTuningItems -RequestedWorkspaceRoot $resolvedWorkspaceRoot -ExplicitCloneBaseDir $resolvedCloneBaseDir

    Write-Log ("Inicio: {0}" -f $script:StartTime.ToString('s'))
    Write-Log "Log: $script:LogPath"
    Write-Log "Result: $script:ResultPath"
    Write-Log "Admin: $(Test-IsAdmin)"
    Write-Log ("Profiles selecionados: {0}" -f ($(if (@($selection.Profiles).Count -gt 0) { @($selection.Profiles) -join ', ' } else { '-' })))
    Write-Log ("Componentes selecionados: {0}" -f ($(if (@($selection.Components).Count -gt 0) { @($selection.Components) -join ', ' } else { '-' })))
    Write-Log ("Exclusoes: {0}" -f ($(if (@($selection.Excludes).Count -gt 0) { @($selection.Excludes) -join ', ' } else { '-' })))
    Write-Log ("Perfis expandidos: {0}" -f ($(if (@($resolution.ExpandedProfiles).Count -gt 0) { @($resolution.ExpandedProfiles) -join ', ' } else { '-' })))
    Write-Log ("Componentes resolvidos: {0}" -f ($(if (@($resolution.ResolvedComponents).Count -gt 0) { @($resolution.ResolvedComponents) -join ', ' } else { '-' })))
    Write-Log "WorkspaceRoot: $resolvedWorkspaceRoot"
    Write-Log "CloneBaseDir: $resolvedCloneBaseDir"
    Write-Log "HostHealth: $resolvedHostHealthMode"
    Write-Log "AppTuning: $resolvedAppTuningMode"
    # StrictMode: pipeline vazio vira $null — nunca usar .Count nesse resultado; materializar sempre com @( foreach ... ).
    $reqCats = @(
        foreach ($c in @($selection.AppTuningCategories)) {
            if (-not [string]::IsNullOrWhiteSpace([string]$c)) { [string]$c }
        }
    )
    $reqItems = @(
        foreach ($it in @($selection.AppTuningItems)) {
            if (-not [string]::IsNullOrWhiteSpace([string]$it)) { [string]$it }
        }
    )
    $exItems = @(
        foreach ($ex in @($selection.ExcludedAppTuningItems)) {
            if (-not [string]::IsNullOrWhiteSpace([string]$ex)) { [string]$ex }
        }
    )
    Write-Log ("AppTuning categorias (param): {0}" -f ($(if ($reqCats.Length -gt 0) { $reqCats -join ', ' } else { '-' })))
    Write-Log ("AppTuning itens (param): {0}" -f ($(if ($reqItems.Length -gt 0) { $reqItems -join ', ' } else { '-' })))
    Write-Log ("AppTuning exclusoes (param): {0}" -f ($(if ($exItems.Length -gt 0) { $exItems -join ', ' } else { '-' })))
    $planItemIds = @(
        foreach ($planItem in @($appTuningPlan.items)) {
            $planItemId = [string]$planItem.id
            if (-not [string]::IsNullOrWhiteSpace($planItemId)) { $planItemId }
        }
    )
    Write-Log ("AppTuning plano: {0} item(ns); ids: {1}" -f $planItemIds.Length, ($(if ($planItemIds.Length -gt 0) { $planItemIds -join ', ' } else { '-' })))
    $pendingPlan = @(
        foreach ($planItem in @($appTuningPlan.items)) {
            if ([string]$planItem.status -eq 'pending') { $planItem }
        }
    )
    Write-Log ("AppTuning itens com status=pending no plano inicial: {0}" -f $pendingPlan.Length)
    if ($reqItems -contains 'app-notepadpp' -and ($reqItems -notcontains 'notepadpp-defaults')) {
        Write-Log 'AppTuning: aviso — selecionado app-notepadpp sem notepadpp-defaults; instalacao via componente ocorre, mas plugins/UDLs padrao exigem o item Notepad++ defaults.' 'WARN'
    }
    if ($usesSteamDeckFlow) {
        Write-Log "Steam Deck version resolvida: $resolvedSteamDeckVersion"
    }

    if ($DryRun) {
        Show-BootstrapExecutionPlan -Selection $selection -Resolution $resolution -ResolvedWorkspaceRoot $resolvedWorkspaceRoot -ResolvedCloneBaseDir $resolvedCloneBaseDir -ResolvedSteamDeckVersion $resolvedSteamDeckVersion -ResolvedHostHealthMode $resolvedHostHealthMode -AppTuningPlan $appTuningPlan

        if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
            Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value ([ordered]@{
                status = 'success'
                generatedAt = (Get-Date).ToString('o')
                logPath = $script:LogPath
                resultPath = $script:ResultPath
                dryRun = $true
                workspaceRoot = $resolvedWorkspaceRoot
                cloneBaseDir = $resolvedCloneBaseDir
                usesSteamDeckFlow = $usesSteamDeckFlow
                resolvedSteamDeckVersion = $resolvedSteamDeckVersion
                resolvedHostHealthMode = $resolvedHostHealthMode
                resolvedAppTuningMode = $resolvedAppTuningMode
                selection = $selection
                resolution = $resolution
                reversibilitySummary = $previewData.ReversibilitySummary
                appTuningPlan = $appTuningPlan
            })
        }
        return
    }

    $state = New-BootstrapState -Selection $selection -ResolvedWorkspaceRoot $resolvedWorkspaceRoot -ResolvedCloneBaseDir $resolvedCloneBaseDir -RequestedSteamDeckVersion $SteamDeckVersion -ResolvedSteamDeckVersion $resolvedSteamDeckVersion -HostHealthMode $resolvedHostHealthMode -AppTuningMode $resolvedAppTuningMode -UsesSteamDeckFlow:$usesSteamDeckFlow -IsDryRun:$DryRun
    $state.EnableClaudeCodeProjectMcps = [bool]$ClaudeCodeProjectMcps
    $state.ChangeManifestPath = Get-BootstrapChangeManifestPath -State $state
    Save-BootstrapChangeManifest -State $state

    # Preencher componentes ja concluidos se estiver em modo Resume
    foreach ($comp in $completedFromCheckpoint) {
        $state.Completed[$comp] = @{ Status = 'Resumed'; Timestamp = (Get-Date).ToString('o') }
    }

    Invoke-BootstrapExecutionPreflight -State $state -ResolvedComponents $resolution.ResolvedComponents

    $successfullyCompleted = New-Object System.Collections.Generic.List[string]
    foreach ($comp in $completedFromCheckpoint) { $successfullyCompleted.Add($comp) }

    # Resiliencia por componente: falha local de um componente nao derruba o run inteiro.
    # Apenas bloqueios host-globais GENUINAMENTE fatais abortam: reboot pendente hostil a MSI
    # (nenhum fluxo winget/MSI pode concluir ate reiniciar), disco insuficiente e falha do
    # system-core (raiz de todas as dependencias).
    #
    # 'winget-msi-busy' NAO entra aqui de proposito: e contencao transitoria por-tentativa
    # (tipicamente um winget/msiexec residual da propria ghost-recovery segurando o lock por
    # alguns segundos). Abortar tudo por isso derrubava ~60 componentes seguintes - a maioria
    # npm/git/config/proxy/MCP que nem tocam winget/MSI. Tratado como bloqueio por-componente:
    # pula este e segue; o proximo componente winget reavalia o lock via Wait-BootstrapWingetMsiIdle.
    $failedComponents = New-Object System.Collections.Generic.List[string]
    $dependencySkippedComponents = New-Object System.Collections.Generic.List[string]
    $globalAbortBlockedKinds = @('pending-reboot-msi')
    $componentCatalogForLoop = Get-BootstrapComponentCatalog
    try {
        foreach ($componentName in $resolution.ResolvedComponents) {
            if ($state.Completed.ContainsKey($componentName)) {
                Write-Log "Componente ja concluido (skip): $componentName"
                $state.ComponentStatus[$componentName] = [ordered]@{ status = 'skipped'; timestamp = (Get-Date).ToString('o'); reason = 'already-completed' }
                continue
            }
            $unavailable = @($failedComponents.ToArray()) + @($dependencySkippedComponents.ToArray())
            $componentDefForLoop = $componentCatalogForLoop[$componentName]
            $failedDependencies = @()
            if ($componentDefForLoop -and $componentDefForLoop.DependsOn) {
                $failedDependencies = @($componentDefForLoop.DependsOn | Where-Object { $unavailable -contains [string]$_ })
            }
            if ($failedDependencies.Count -gt 0) {
                $depList = ($failedDependencies -join ', ')
                Write-Log ("Componente {0} pulado: dependencia(s) com falha nesta execucao ({1})." -f $componentName, $depList) 'WARN'
                $state.ComponentStatus[$componentName] = [ordered]@{ status = 'skipped'; timestamp = (Get-Date).ToString('o'); reason = 'dependency-failed'; dependencies = $failedDependencies }
                $dependencySkippedComponents.Add([string]$componentName)
                continue
            }
            $state.CurrentComponent = [string]$componentName
            $state.ComponentStatus[$componentName] = [ordered]@{ status = 'started'; timestamp = (Get-Date).ToString('o') }
            try {
                Invoke-BootstrapComponent -Name $componentName -State $state
            } catch {
                $blockedInfo = Get-BootstrapBlockedErrorInfo -ErrorRecord $_
                $isGlobalAbort = (
                    ($blockedInfo.IsBlocked -and ($globalAbortBlockedKinds -contains [string]$blockedInfo.Kind)) -or
                    ($_.Exception.Message -like '*Espaco em disco insuficiente*') -or
                    ($componentName -eq 'system-core')
                )
                if ($isGlobalAbort) { throw }
                if ($blockedInfo.IsBlocked) {
                    $state.ComponentStatus[$componentName] = [ordered]@{ status = 'blocked'; timestamp = (Get-Date).ToString('o'); error = $_.Exception.Message; blockerKind = [string]$blockedInfo.Kind; action = [string]$blockedInfo.Action; blockerReasons = @($blockedInfo.Reasons) }
                    Write-Log ("Componente {0} bloqueado ({1}); continuando com os demais. Detalhe: {2}" -f $componentName, [string]$blockedInfo.Kind, $_.Exception.Message) 'WARN'
                } else {
                    $state.ComponentStatus[$componentName] = [ordered]@{ status = 'failed'; timestamp = (Get-Date).ToString('o'); error = $_.Exception.Message }
                    Write-Log ("Componente {0} falhou; continuando com os demais. Detalhe: {1}" -f $componentName, $_.Exception.Message) 'WARN'
                }
                $state.Warnings.Add(("component-failed: {0}: {1}" -f $componentName, $_.Exception.Message))
                $failedComponents.Add([string]$componentName)
                $state.LastError = $_.Exception.Message
                Save-BootstrapChangeManifest -State $state
                continue
            }
            if ($state.Completed.ContainsKey($componentName)) {
                $state.ComponentStatus[$componentName] = [ordered]@{ status = 'completed'; timestamp = (Get-Date).ToString('o') }
                $successfullyCompleted.Add($componentName)
                Save-BootstrapCheckpoint -Selection $selection -CompletedComponents $successfullyCompleted.ToArray() -AppTuningResults $state.AppTuningResults -HostHealthResults $state.HostHealthResults
            } elseif (Test-BootstrapComponentSkipped -State $state -ComponentName $componentName) {
                Write-Log ("Componente pulado com aviso: {0}" -f $componentName) 'WARN'
            }
        }
        if ($failedComponents.Count -gt 0) {
            Write-Log ("Componentes com falha nesta execucao ({0}): {1}" -f $failedComponents.Count, ($failedComponents.ToArray() -join ', ')) 'WARN'
        }
        if ($dependencySkippedComponents.Count -gt 0) {
            Write-Log ("Componentes pulados por dependencia com falha ({0}): {1}" -f $dependencySkippedComponents.Count, ($dependencySkippedComponents.ToArray() -join ', ')) 'WARN'
        }
    } catch {
        $failedComponent = [string]$state.CurrentComponent
        $blockedInfo = Get-BootstrapBlockedErrorInfo -ErrorRecord $_
        if (-not [string]::IsNullOrWhiteSpace($failedComponent)) {
            if ($blockedInfo.IsBlocked) {
                $state.ComponentStatus[$failedComponent] = [ordered]@{ status = 'blocked'; timestamp = (Get-Date).ToString('o'); error = $_.Exception.Message; blockerKind = [string]$blockedInfo.Kind; action = [string]$blockedInfo.Action; blockerReasons = @($blockedInfo.Reasons) }
            } else {
                $state.ComponentStatus[$failedComponent] = [ordered]@{ status = 'failed'; timestamp = (Get-Date).ToString('o'); error = $_.Exception.Message }
            }
        }
        $state.LastError = $_.Exception.Message
        Save-BootstrapChangeManifest -State $state
        if ($blockedInfo.IsBlocked) {
            Write-Log ("Execucao bloqueada: {0}" -f $_.Exception.Message) 'WARN'
        } else {
            Write-Log ("Falha critica na execucao: {0}" -f $_.Exception.Message) 'ERROR'
        }
        if ($AutoRollback -and -not $blockedInfo.IsBlocked) {
            Invoke-BootstrapAutoRollback -State $state
        }
        if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
            Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{
                phase = 'component-loop'
                workspaceRoot = $resolvedWorkspaceRoot
                cloneBaseDir = $resolvedCloneBaseDir
                lastComponent = $failedComponent
                failedComponent = $failedComponent
                completedComponents = @($successfullyCompleted.ToArray())
                warnings = @($state.Warnings.ToArray())
                skippedComponents = @($state.SkippedComponents.ToArray())
                componentStatus = $state.ComponentStatus
                howToFix = $(if ($blockedInfo.IsBlocked -and [string]$blockedInfo.Action -eq 'restart-required') { 'Reinicie o Windows e execute novamente.' } else { 'Revise o log do componente, rode -Audit para diagnostico e use -Resume apos corrigir dependencias.' })
                changesPath = $state.ChangeManifestPath
                changesSummary = Get-BootstrapChangesSummary -State $state
                rollbackAvailable = ((@($state.Changes.ToArray()).Count -gt 0) -or (-not [string]::IsNullOrWhiteSpace([string]$state.ChangeManifestPath)))
            })
        }
        throw
    }

    try {
        $state.CurrentComponent = 'app-tuning'
        Invoke-BootstrapAppTuning -State $state -Plan $appTuningPlan
        $state.ComponentStatus['app-tuning'] = [ordered]@{ status = 'completed'; timestamp = (Get-Date).ToString('o') }
        $state.CurrentComponent = 'host-health'
        Invoke-BootstrapHostHealth -State $state -Mode $resolvedHostHealthMode
        $state.ComponentStatus['host-health'] = [ordered]@{ status = 'completed'; timestamp = (Get-Date).ToString('o') }
        $state.CurrentComponent = 'phasezero-post-config'
        $phaseZeroPostConfigResult = Invoke-BootstrapPhaseZeroPostConfig -State $state -DryRun:$DryRun
        $state.ComponentStatus['phasezero-post-config'] = [ordered]@{ status = 'completed'; timestamp = (Get-Date).ToString('o') }
    } catch {
        $failedComponent = [string]$state.CurrentComponent
        $state.ComponentStatus[$failedComponent] = [ordered]@{ status = 'failed'; timestamp = (Get-Date).ToString('o'); error = $_.Exception.Message }
        Save-BootstrapChangeManifest -State $state
        Write-Log ("Falha critica (AppTuning/HostHealth/PostConfig): {0}" -f $_.Exception.Message) 'ERROR'
        if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
            Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{
                phase = 'app-tuning-host-health'
                lastComponent = $failedComponent
                failedComponent = $failedComponent
                completedComponents = @($successfullyCompleted.ToArray())
                warnings = @($state.Warnings.ToArray())
                skippedComponents = @($state.SkippedComponents.ToArray())
                componentStatus = $state.ComponentStatus
                howToFix = 'Revise AppTuning/HostHealth no log; desative o modo correspondente ou execute como Administrador quando indicado.'
                changesPath = $state.ChangeManifestPath
                changesSummary = Get-BootstrapChangesSummary -State $state
                rollbackAvailable = (@($state.Changes.ToArray()).Count -gt 0)
            })
        }
        throw
    }

    if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
        $skippedComponents = @($state.SkippedComponents.ToArray())
        $resultWarnings = @($state.Warnings.ToArray())
        $resultFailedComponents = @($failedComponents.ToArray())
        $resultDependencySkipped = @($dependencySkippedComponents.ToArray())
        $resultStatus = if ($resultFailedComponents.Count -gt 0 -or $skippedComponents.Count -gt 0 -or $resultWarnings.Count -gt 0) { 'warning' } else { 'success' }
        Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value ([ordered]@{
            status = $resultStatus
            generatedAt = (Get-Date).ToString('o')
            logPath = $script:LogPath
            resultPath = $script:ResultPath
            workspaceRoot = $resolvedWorkspaceRoot
            cloneBaseDir = $resolvedCloneBaseDir
            secretsPath = $state.SecretsPath
            secretsSummary = $state.SecretsSummary
            usesSteamDeckFlow = $usesSteamDeckFlow
            resolvedSteamDeckVersion = $resolvedSteamDeckVersion
            resolvedHostHealthMode = $resolvedHostHealthMode
            resolvedAppTuningMode = $resolvedAppTuningMode
            selection = $selection
            resolution = $resolution
            appTuningPlan = $appTuningPlan
            appTuningReportRoot = $state.AppTuningReportRoot
            hostHealthReportRoot = $state.HostHealthReportRoot
            steamDeckSettingsPath = $state.SteamDeckSettingsPath
            steamDeckAutomationRoot = $state.SteamDeckAutomationRoot
            preflight = $state.PreflightSummary
            manualRequirements = @($state.ManualRequirements.ToArray())
            warnings = $resultWarnings
            skippedComponents = $skippedComponents
            failedComponents = $resultFailedComponents
            dependencySkippedComponents = $resultDependencySkipped
            completedComponents = @($successfullyCompleted.ToArray())
            componentStatus = $state.ComponentStatus
            changesPath = $state.ChangeManifestPath
            changesSummary = Get-BootstrapChangesSummary -State $state
            reversibilitySummary = $previewData.ReversibilitySummary
            rollbackAvailable = (@($state.Changes.ToArray()).Count -gt 0)
        })
    }

    Write-Log 'Resumo:'
    if (-not [string]::IsNullOrWhiteSpace($state.SecretsPath)) {
        Write-Log "bootstrap secrets: $($state.SecretsPath)"
    }
    Write-Log "CLAUDE_CODE_GIT_BASH_PATH: $([Environment]::GetEnvironmentVariable('CLAUDE_CODE_GIT_BASH_PATH','User'))"
    Write-BootstrapCommandSummary -Label 'git' -CommandName 'git' -Args @('--version')
    Write-BootstrapCommandSummary -Label 'node' -CommandName 'node' -Args @('-v')
    Write-BootstrapCommandSummary -Label 'npm' -CommandName 'npm' -Args @('--version')
    Write-BootstrapCommandSummary -Label 'java' -CommandName 'java' -Args @('-version')
    Write-BootstrapCommandSummary -Label 'dotnet' -CommandName 'dotnet' -Args @('--version')
    Write-BootstrapDotNetSdksSummary
    Write-BootstrapCommandSummary -Label 'magick' -CommandName 'magick' -Args @('-version')
    Write-BootstrapCommandSummary -Label '7z' -CommandName '7z' -Args @()
    Write-BootstrapCommandSummary -Label 'python' -CommandName 'python' -Args @('--version')
    Write-BootstrapCommandSummary -Label 'pip' -CommandName 'pip' -Args @('--version')
    Write-BootstrapCommandSummary -Label 'claude' -CommandName 'claude' -Args @('--version')
    Write-BootstrapCommandSummary -Label 'gh' -CommandName 'gh' -Args @('--version')
    # aider/goose so aparecem no resumo quando foram selecionados nesta execucao (evita WARN falso
    # "NAO ENCONTRADO" em perfis que nao os incluem).
    if ($state.Completed.ContainsKey('aider')) { Write-BootstrapCommandSummary -Label 'aider' -CommandName 'aider' -Args @('--version') }
    if ($state.Completed.ContainsKey('goose')) { Write-BootstrapCommandSummary -Label 'goose' -CommandName 'goose' -Args @('--version') }
    Write-BootstrapCommandSummary -Label 'wsl' -CommandName 'wsl.exe' -Args @('--version')

    $opencodeExe = Join-Path (Join-Path (Get-BootstrapUserHomePath) '.opencode\bin') 'opencode.exe'
    if (Test-Path $opencodeExe) {
        Write-Log "opencode: $(& $opencodeExe --version) ($opencodeExe)"
    } elseif ($opencodeCmd = Resolve-CommandPath -Name 'opencode') {
        $version = Invoke-NativeFirstLine -Exe $opencodeCmd -Args @('--version')
        if ([string]::IsNullOrWhiteSpace($version)) { $version = 'instalado' }
        Write-Log "opencode: $version ($opencodeCmd)"
    } else {
        Write-Log "opencode: NAO ENCONTRADO ($opencodeExe)" 'WARN'
    }

    if ($state.NodeInfo) {
        foreach ($tool in @(
            @{ Name = 'gemini'; Path = (Join-Path $state.NodeInfo.NpmBin 'gemini.cmd') },
            @{ Name = 'bonsai'; Path = (Join-Path $state.NodeInfo.NpmBin 'bonsai.cmd') },
            @{ Name = 'grok'; Path = (Join-Path $state.NodeInfo.NpmBin 'grok.cmd') },
            @{ Name = 'qwen'; Path = (Join-Path $state.NodeInfo.NpmBin 'qwen.cmd') },
            @{ Name = 'copilot'; Path = (Join-Path $state.NodeInfo.NpmBin 'copilot.cmd') },
            @{ Name = 'codex'; Path = (Join-Path $state.NodeInfo.NpmBin 'codex.cmd') },
            @{ Name = 'openclaw'; Path = (Join-Path $state.NodeInfo.NpmBin 'openclaw.cmd') },
            @{ Name = 'hermes'; Path = (Join-Path $state.NodeInfo.NpmBin 'hermes.cmd') },
            @{ Name = 'kilo'; Path = (Join-Path $state.NodeInfo.NpmBin 'kilo.cmd') }
        )) {
            if (Test-Path $tool.Path) {
                $version = Invoke-NativeFirstLine -Exe $tool.Path -Args @('--version')
                if ([string]::IsNullOrWhiteSpace($version)) { $version = 'instalado' }
                Write-Log ("{0}: {1} ({2})" -f $tool.Name, $version, $tool.Path)
            } else {
                Write-Log ("{0}: NAO ENCONTRADO ({1})" -f $tool.Name, $tool.Path) 'WARN'
            }
        }
    }

    $repoDir = Join-Path $resolvedCloneBaseDir 'gemini-cli'
    Write-Log "repo gemini-cli: $repoDir (exists=$(Test-Path $repoDir))"

    $elapsed = New-TimeSpan -Start $script:StartTime -End (Get-Date)
    Write-Log ("Concluido em {0:c}" -f $elapsed)
    Write-Log "Log salvo em: $script:LogPath"
}

function Set-BootstrapSecretsPreferredActiveCredentials {
    param(
        [Parameter(Mandatory = $true)]$SecretsData,
        [switch]$ForceFirstPassed,
        [switch]$OnlyWhenMissing
    )

    $normalized = Normalize-BootstrapSecretsData -Secrets $SecretsData

    foreach ($providerName in @($normalized.providers.Keys)) {
        $provider = ConvertTo-BootstrapHashtable -InputObject $normalized.providers[$providerName]
        if (-not ($provider -is [hashtable])) { continue }
        if (-not ($provider.ContainsKey('credentials') -and ($provider['credentials'] -is [hashtable]))) { continue }

        $shouldSelect = $ForceFirstPassed
        if ($OnlyWhenMissing -and [string]::IsNullOrWhiteSpace([string]$provider['activeCredential'])) {
            $shouldSelect = $true
        }
        if (-not $shouldSelect) { continue }

        $candidateIds = @()
        foreach ($credentialId in @($provider['rotationOrder'])) {
            $value = [string]$credentialId
            if ([string]::IsNullOrWhiteSpace($value)) { continue }
            if ($provider['credentials'].Contains($value)) {
                $candidateIds += @($value)
            }
        }
        foreach ($credentialId in $provider['credentials'].Keys) {
            if ($candidateIds -notcontains [string]$credentialId) {
                $candidateIds += @([string]$credentialId)
            }
        }

        $selected = ''
        foreach ($credentialId in $candidateIds) {
            $credential = ConvertTo-BootstrapHashtable -InputObject $provider['credentials'][$credentialId]
            if (-not ($credential -is [hashtable])) { continue }
            if (($credential.ContainsKey('validation')) -and ($credential['validation'] -is [hashtable]) -and ([string]$credential['validation']['state'] -eq 'passed')) {
                $selected = [string]$credentialId
                break
            }
        }

        if (-not [string]::IsNullOrWhiteSpace($selected)) {
            $provider['activeCredential'] = $selected
        } elseif ($ForceFirstPassed) {
            $provider['activeCredential'] = ''
        }

        $normalized.providers[$providerName] = Convert-BootstrapSecretsProviderDefinition -ProviderName ([string]$providerName) -ProviderData $provider
    }

    return $normalized
}

function Write-BootstrapSecretsList {
    param([Parameter(Mandatory = $true)]$SecretsData)

    foreach ($entry in @(Get-BootstrapSecretsListEntries -SecretsData $SecretsData)) {
        $line = '{0} | {1} | active={2} | state={3} | {4}' -f $entry.provider, $entry.id, $entry.active.ToString().ToLowerInvariant(), $entry.validationState, $entry.displayName
        Write-Output $line
    }
}

function Set-BootstrapApiCredential {
    param(
        [Parameter(Mandatory = $true)][string]$ProviderName,
        [string]$CredentialId = '',
        [string]$DisplayName = '',
        [string]$Secret = '',
        [hashtable]$Fields = @{},
        [switch]$Validate,
        [switch]$Activate
    )

    $providerKey = $ProviderName.ToLowerInvariant()
    $bundle = Get-BootstrapSecretsData
    $data = Normalize-BootstrapSecretsData -Secrets $bundle.Data
    $catalog = Get-BootstrapSecretsProviderCatalog
    if (-not $catalog.Contains($providerKey)) {
        throw "Provider desconhecido: $ProviderName"
    }

    $provider = ConvertTo-BootstrapHashtable -InputObject $data.providers[$providerKey]
    if (-not ($provider -is [hashtable])) {
        $provider = Get-BootstrapSecretsProviderDefinitionTemplate -ProviderName $providerKey
    }
    if (-not $provider.ContainsKey('credentials') -or -not ($provider['credentials'] -is [hashtable])) {
        $provider['credentials'] = [ordered]@{}
    }

    $isNew = [string]::IsNullOrWhiteSpace($CredentialId)
    if ($isNew) {
        if ([string]::IsNullOrWhiteSpace($Secret)) {
            throw 'Informe o segredo para criar a credencial.'
        }
        $CredentialId = New-BootstrapSecretCredentialId -ProviderName $providerKey -Label $(if ([string]::IsNullOrWhiteSpace($DisplayName)) { 'manual' } else { $DisplayName }) -ExistingIds @($provider['credentials'].Keys)
    } elseif (-not $provider['credentials'].Contains($CredentialId)) {
        throw "Credencial desconhecida para ${providerKey}: $CredentialId"
    }

    $credential = if ($isNew) {
        [ordered]@{
            displayName = if ([string]::IsNullOrWhiteSpace($DisplayName)) { 'Manual' } else { $DisplayName.Trim() }
            secret = $Secret.Trim()
            secretKind = [string]$catalog[$providerKey]['secretKind']
            validation = New-BootstrapSecretValidationState
        }
    } else {
        Normalize-BootstrapSecretCredential -ProviderName $providerKey -CredentialId $CredentialId -CredentialData $provider['credentials'][$CredentialId] -DefaultSecretKind ([string]$catalog[$providerKey]['secretKind'])
    }

    if (-not [string]::IsNullOrWhiteSpace($DisplayName)) {
        $credential['displayName'] = $DisplayName.Trim()
    }
    if (-not [string]::IsNullOrWhiteSpace($Secret)) {
        if ([string]$credential['secret'] -ne $Secret.Trim()) {
            $credential['secret'] = $Secret.Trim()
            $credential['validation'] = New-BootstrapSecretValidationState
        }
    }

    foreach ($fieldName in @('baseUrl', 'organizationId', 'projectRef', 'readOnly')) {
        if ($Fields.ContainsKey($fieldName)) {
            $fieldValue = [string]$Fields[$fieldName]
            if ([string]::IsNullOrWhiteSpace($fieldValue)) {
                if ($credential.Contains($fieldName)) { $credential.Remove($fieldName) | Out-Null }
            } else {
                $credential[$fieldName] = $fieldValue.Trim()
            }
        }
    }

    if ($Validate) {
        $credential['validation'] = Test-BootstrapSecretsProviderCredential -ProviderName $providerKey -ProviderDefinition $provider -CredentialId $CredentialId -Credential $credential
    }

    $provider['credentials'][$CredentialId] = $credential
    if (-not $provider.ContainsKey('rotationOrder') -or -not ($provider['rotationOrder'] -is [System.Collections.IEnumerable])) {
        $provider['rotationOrder'] = @()
    }
    if (@($provider['rotationOrder']) -notcontains $CredentialId) {
        $provider['rotationOrder'] = @($provider['rotationOrder']) + @($CredentialId)
    }
    if ($Activate -and [string]$credential['validation']['state'] -eq 'passed') {
        $provider['activeCredential'] = $CredentialId
    } elseif ([string]::IsNullOrWhiteSpace([string]$provider['activeCredential']) -and [string]$credential['validation']['state'] -eq 'passed') {
        $provider['activeCredential'] = $CredentialId
    }

    $data.providers[$providerKey] = Convert-BootstrapSecretsProviderDefinition -ProviderName $providerKey -ProviderData $provider
    Write-BootstrapJsonFile -Path $bundle.Path -Value $data
    return [ordered]@{
        path = $bundle.Path
        credentialId = $CredentialId
        inventory = Get-BootstrapApiInventory -SecretsData $data
    }
}

function Invoke-BootstrapApiCredentialValidation {
    param(
        [string]$ProviderName = '',
        [string]$CredentialId = '',
        [switch]$All
    )

    $bundle = Get-BootstrapSecretsData
    $data = $bundle.Data
    if ($All) {
        $data = Invoke-BootstrapSecretsValidation -SecretsData $data -ValidateAll
    } elseif (-not [string]::IsNullOrWhiteSpace($ProviderName) -and -not [string]::IsNullOrWhiteSpace($CredentialId)) {
        $providerKey = $ProviderName.ToLowerInvariant()
        $normalized = Normalize-BootstrapSecretsData -Secrets $data
        if (-not $normalized.providers.Contains($providerKey)) { throw "Provider desconhecido: $ProviderName" }
        $provider = ConvertTo-BootstrapHashtable -InputObject $normalized.providers[$providerKey]
        if (-not ($provider.ContainsKey('credentials') -and ($provider['credentials'] -is [hashtable]) -and $provider['credentials'].Contains($CredentialId))) {
            throw "Credencial desconhecida para ${providerKey}: $CredentialId"
        }
        $credential = ConvertTo-BootstrapHashtable -InputObject $provider['credentials'][$CredentialId]
        $provider['credentials'][$CredentialId]['validation'] = Test-BootstrapSecretsProviderCredential -ProviderName $providerKey -ProviderDefinition $provider -CredentialId $CredentialId -Credential $credential
        $normalized.providers[$providerKey] = Convert-BootstrapSecretsProviderDefinition -ProviderName $providerKey -ProviderData $provider
        $data = $normalized
    } else {
        $data = Invoke-BootstrapSecretsValidation -SecretsData $data
    }

    Write-BootstrapJsonFile -Path $bundle.Path -Value $data
    return [ordered]@{
        path = $bundle.Path
        inventory = Get-BootstrapApiInventory -SecretsData $data
    }
}

function Set-BootstrapApiActiveCredential {
    param(
        [Parameter(Mandatory = $true)][string]$ProviderName,
        [Parameter(Mandatory = $true)][string]$CredentialId
    )

    $bundle = Get-BootstrapSecretsData
    $data = Set-BootstrapSecretsActiveCredential -SecretsData $bundle.Data -ProviderName $ProviderName.ToLowerInvariant() -CredentialId $CredentialId
    Write-BootstrapJsonFile -Path $bundle.Path -Value $data
    return [ordered]@{
        path = $bundle.Path
        inventory = Get-BootstrapApiInventory -SecretsData $data
    }
}

function Import-BootstrapApiCredentialFile {
    param([Parameter(Mandatory = $true)][string]$Path)

    $bundle = Get-BootstrapSecretsData
    $text = Get-Content -Path $Path -Raw -Encoding utf8
    $data = Import-BootstrapSecretsText -Text $text -SecretsData $bundle.Data
    Write-BootstrapJsonFile -Path $bundle.Path -Value $data
    return [ordered]@{
        path = $bundle.Path
        inventory = Get-BootstrapApiInventory -SecretsData $data
    }
}

function Invoke-BootstrapApiApply {
    $state = New-BootstrapState -Selection @{} -ResolvedWorkspaceRoot (Get-Location).Path -ResolvedCloneBaseDir (Get-Location).Path -RequestedSteamDeckVersion 'Auto' -ResolvedSteamDeckVersion '' -HostHealthMode 'off' -UsesSteamDeckFlow:$false -IsDryRun:$false
    Ensure-BootstrapSecrets -State $state
    return $state.SecretsSummary
}

function Get-BootstrapRotationStaleProviders {
    param(
        [Parameter(Mandatory = $true)]$SecretsData,
        [int]$StaleHours = 24
    )
    $normalized = Normalize-BootstrapSecretsData -Secrets $SecretsData
    $stale = New-Object System.Collections.ArrayList
    $cutoff = (Get-Date).ToUniversalTime().AddHours(-1 * [Math]::Abs($StaleHours))
    foreach ($providerName in @($normalized.providers.Keys)) {
        $provider = ConvertTo-BootstrapHashtable -InputObject $normalized.providers[$providerName]
        if (-not ($provider -is [hashtable])) { continue }
        if (-not ($provider.ContainsKey('credentials') -and ($provider['credentials'] -is [hashtable]))) { continue }
        $activeId = [string]$provider['activeCredential']
        if ([string]::IsNullOrWhiteSpace($activeId)) { continue }
        if (-not $provider['credentials'].Contains($activeId)) { continue }
        $credential = ConvertTo-BootstrapHashtable -InputObject $provider['credentials'][$activeId]
        if (-not ($credential -is [hashtable])) { continue }
        $validation = ConvertTo-BootstrapHashtable -InputObject $credential['validation']
        if (-not ($validation -is [hashtable])) { $null = $stale.Add([string]$providerName); continue }
        $state = [string]$validation['state']
        if ($state -in @('failed', 'unknown')) { $null = $stale.Add([string]$providerName); continue }
        if ($state -eq 'passed') {
            $checkedAtRaw = [string]$validation['checkedAt']
            if ([string]::IsNullOrWhiteSpace($checkedAtRaw)) { $null = $stale.Add([string]$providerName); continue }
            $checkedAt = [DateTime]::MinValue
            $parsed = [DateTime]::TryParse($checkedAtRaw, [ref]$checkedAt)
            if (-not $parsed) { $null = $stale.Add([string]$providerName); continue }
            if ($checkedAt.ToUniversalTime() -lt $cutoff) { $null = $stale.Add([string]$providerName) }
        }
    }
    return ,@($stale.ToArray())
}

function Get-BootstrapRotationScheduledTaskName {
    return 'PhaseZero\BootstrapSecretsRotation'
}

function Get-BootstrapRotationScheduledTaskState {
    $taskName = Get-BootstrapRotationScheduledTaskName
    $exists = $false
    try {
        $existing = Get-ScheduledTask -TaskName (Split-Path $taskName -Leaf) -TaskPath ('\' + (Split-Path $taskName -Parent) + '\') -ErrorAction SilentlyContinue
        if ($existing) { $exists = $true }
    } catch {
        $exists = $false
    }
    return [ordered]@{ exists = $exists; taskName = $taskName }
}

function Register-BootstrapRotationScheduledTask {
    param(
        [Parameter(Mandatory = $true)][ValidateSet('none', 'daily', 'weekly')][string]$Schedule,
        [hashtable]$State = $null,
        [switch]$DryRun
    )
    $taskName = Get-BootstrapRotationScheduledTaskName
    $leaf = Split-Path $taskName -Leaf
    $folder = '\' + (Split-Path $taskName -Parent) + '\'
    if ($Schedule -eq 'none') {
        if ($DryRun) {
            return [ordered]@{ status = 'would-remove'; taskName = $taskName; schedule = 'none' }
        }
        try {
            $existing = Get-ScheduledTask -TaskName $leaf -TaskPath $folder -ErrorAction SilentlyContinue
            if ($existing) {
                Unregister-ScheduledTask -TaskName $leaf -TaskPath $folder -Confirm:$false -ErrorAction Stop
                if ($State -ne $null) {
                    try { Register-BootstrapChange -State $State -Type 'Task' -Target $taskName -OldValue 'present' -NewValue 'absent' -Operation 'unregister' -Component 'bootstrap-secrets-rotation' } catch { }
                }
                return [ordered]@{ status = 'removed'; taskName = $taskName; schedule = 'none' }
            }
            return [ordered]@{ status = 'absent'; taskName = $taskName; schedule = 'none' }
        } catch {
            return [ordered]@{ status = 'error'; taskName = $taskName; schedule = 'none'; message = [string]$_.Exception.Message }
        }
    }

    $time = '03:17'
    $argsLine = "-NoProfile -ExecutionPolicy Bypass -File `"$($PSCommandPath)`" -RotateSecrets -NonInteractive"
    if ($DryRun) {
        return [ordered]@{ status = 'would-register'; taskName = $taskName; schedule = $Schedule; time = $time; args = $argsLine }
    }
    try {
        $action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument $argsLine
        $trigger = if ($Schedule -eq 'daily') {
            New-ScheduledTaskTrigger -Daily -At $time
        } else {
            New-ScheduledTaskTrigger -Weekly -DaysOfWeek Sunday -At $time
        }
        $principal = New-ScheduledTaskPrincipal -UserId ([System.Security.Principal.WindowsIdentity]::GetCurrent().Name) -LogonType S4U -RunLevel Limited
        $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable -MultipleInstances IgnoreNew
        $existing = Get-ScheduledTask -TaskName $leaf -TaskPath $folder -ErrorAction SilentlyContinue
        $previous = if ($existing) { 'present' } else { 'absent' }
        Register-ScheduledTask -TaskName $leaf -TaskPath $folder -Action $action -Trigger $trigger -Principal $principal -Settings $settings -Force | Out-Null
        if ($State -ne $null) {
            try { Register-BootstrapChange -State $State -Type 'Task' -Target $taskName -OldValue $previous -NewValue ('schedule=' + $Schedule) -Operation 'register' -Component 'bootstrap-secrets-rotation' } catch { }
        }
        return [ordered]@{ status = 'registered'; taskName = $taskName; schedule = $Schedule; time = $time }
    } catch {
        return [ordered]@{ status = 'error'; taskName = $taskName; schedule = $Schedule; message = [string]$_.Exception.Message }
    }
}

function Invoke-BootstrapRotateSecretsMode {
    param(
        [string]$Provider = '',
        [int]$MaxItems = 10,
        [int]$TimeoutSeconds = 120,
        [string]$Schedule = '',
        [switch]$DryRun
    )

    $bundle = Get-BootstrapSecretsData
    $data = $bundle.Data
    $providerFilter = if (-not [string]::IsNullOrWhiteSpace($Provider)) { $Provider.ToLowerInvariant() } else { '' }

    $staleProviders = Get-BootstrapRotationStaleProviders -SecretsData $data -StaleHours 24
    if (-not [string]::IsNullOrWhiteSpace($providerFilter)) {
        $staleProviders = @($staleProviders | Where-Object { [string]$_ -eq $providerFilter })
    }
    $enqueued = New-Object System.Collections.ArrayList
    foreach ($providerName in $staleProviders) {
        $existingQueue = Get-BootstrapSecretRotationQueue -SecretsData $data -ProviderName $providerName
        $activeOpen = @($existingQueue | Where-Object { [string]$_['state'] -notin @('settled', 'failed') }).Count
        if ($activeOpen -gt 0) { continue }
        $result = Add-BootstrapSecretRotationItem -SecretsData $data -ProviderName $providerName -Trigger 'scheduled'
        $data = $result.Data
        $null = $enqueued.Add([ordered]@{ provider = $providerName; rotationId = [string]$result.Item['id'] })
    }
    $originalSnapshot = $null
    if ($enqueued.Count -gt 0) {
        if ($DryRun) {
            try { $originalSnapshot = Get-Content -LiteralPath $bundle.Path -Raw -Encoding UTF8 } catch { $originalSnapshot = $null }
        }
        Write-BootstrapJsonFile -Path $bundle.Path -Value $data
    }

    $processed = @()
    try {
        if (-not $DryRun) {
            $rotation = Invoke-BootstrapSecretRotation -ProviderName $providerFilter -MaxItems $MaxItems -TimeoutSeconds $TimeoutSeconds
            $processed = @($rotation.Processed)
        } else {
            $rotation = Invoke-BootstrapSecretRotation -ProviderName $providerFilter -MaxItems $MaxItems -TimeoutSeconds $TimeoutSeconds -DryRun
            $processed = @($rotation.Processed)
        }
    } finally {
        if ($DryRun -and $null -ne $originalSnapshot) {
            try { Set-Content -LiteralPath $bundle.Path -Value $originalSnapshot -Encoding UTF8 -NoNewline } catch { }
        }
    }

    $scheduleResult = $null
    if (-not [string]::IsNullOrWhiteSpace($Schedule)) {
        $scheduleResult = Register-BootstrapRotationScheduledTask -Schedule $Schedule -DryRun:$DryRun
    }

    $output = [ordered]@{
        manifestPath = $bundle.Path
        enqueued = @($enqueued)
        processedCount = $processed.Count
        processed = @($processed | ForEach-Object { [ordered]@{ id = [string]$_['id']; provider = [string]$_['provider']; state = [string]$_['state']; targetCredentialId = [string]$_['targetCredentialId']; attempts = [int]$_['attempts']; lastError = [string]$_['lastError'] } })
        schedule = $scheduleResult
        dryRun = [bool]$DryRun
    }
    return $output
}

function Invoke-BootstrapSecretsMode {
    $bundle = Get-BootstrapSecretsData
    $data = $bundle.Data
    $mutated = $false

    if (-not [string]::IsNullOrWhiteSpace($SecretsImportPath)) {
        $text = Get-Content -Path $SecretsImportPath -Raw -Encoding utf8
        $data = Import-BootstrapSecretsText -Text $text -SecretsData $data
        $data = Invoke-BootstrapSecretsValidation -SecretsData $data -ValidateAll
        $data = Set-BootstrapSecretsPreferredActiveCredentials -SecretsData $data -ForceFirstPassed
        $mutated = $true
    }

    if ($SecretsValidateAll) {
        $data = Invoke-BootstrapSecretsValidation -SecretsData $data -ValidateAll
        $data = Set-BootstrapSecretsPreferredActiveCredentials -SecretsData $data -OnlyWhenMissing
        $mutated = $true
    }

    if (-not [string]::IsNullOrWhiteSpace($SecretsActivateCredential)) {
        if ($SecretsActivateCredential -notmatch '^([a-z0-9]+)-') {
            throw "Nao foi possivel inferir o provider da credencial: $SecretsActivateCredential"
        }
        $providerName = [string]$matches[1]
        $data = Set-BootstrapSecretsActiveCredential -SecretsData $data -ProviderName $providerName -CredentialId $SecretsActivateCredential
        $mutated = $true
    }

    if (-not [string]::IsNullOrWhiteSpace($SecretsActivateProvider)) {
        $data = Move-BootstrapSecretsToNextCredential -SecretsData $data -ProviderName $SecretsActivateProvider.ToLowerInvariant()
        $mutated = $true
    }

    if ($mutated) {
        Write-BootstrapJsonFile -Path $bundle.Path -Value $data
        $state = New-BootstrapState -Selection @{} -ResolvedWorkspaceRoot (Get-Location).Path -ResolvedCloneBaseDir (Get-Location).Path -RequestedSteamDeckVersion 'Auto' -ResolvedSteamDeckVersion '' -HostHealthMode 'off' -UsesSteamDeckFlow:$false -IsDryRun:$false
        Ensure-BootstrapSecrets -State $state
        $data = (Read-BootstrapJsonFile -Path $bundle.Path)
    }

    if ($SecretsList) {
        Write-BootstrapSecretsList -SecretsData $data
    }
}

$invocationName = ''
try { $invocationName = [string]$MyInvocation.InvocationName } catch { $invocationName = '' }
$isDotSourced = ($invocationName -eq '.')

function Stop-BootstrapProcess {
    param([int]$Code)
    $global:LASTEXITCODE = $Code
    [Environment]::Exit($Code)
}

$useBootstrapSecretsMode = (
    $SecretsList -or
    $SecretsValidateAll -or
    [string]::IsNullOrWhiteSpace($SecretsImportPath) -eq $false -or
    [string]::IsNullOrWhiteSpace($SecretsActivateProvider) -eq $false -or
    [string]::IsNullOrWhiteSpace($SecretsActivateCredential) -eq $false
)

$useBootstrapRotateSecretsMode = (
    $RotateSecrets -or
    -not [string]::IsNullOrWhiteSpace($RotateSecretsSchedule)
)

$useBootstrapDoctorMode = $Doctor
$useBootstrapDriftCheckMode = $DriftCheck
$useBootstrapSupportBundleMode = $SupportBundle
$useBootstrapAiConfigDoctorMode = $AiConfigDoctor
$useBootstrapAiConfigSyncMode = $AiConfigSync
$useBootstrapRepairPlanMode = ($RepairPlan -or -not [string]::IsNullOrWhiteSpace($ExecuteRepairPlan))
$useBootstrapPartitionLabelsMode = ($PartitionLabels -or $ApplyPartitionLabels)
$useBootstrapReleasePackMode = $ReleasePack

$useBootstrapProfileMode = (
    -not $useBootstrapRotateSecretsMode -and
    -not $useBootstrapDriftCheckMode -and
    -not $useBootstrapSupportBundleMode -and
    -not $useBootstrapAiConfigDoctorMode -and
    -not $useBootstrapAiConfigSyncMode -and
    -not $useBootstrapRepairPlanMode -and
    -not $useBootstrapPartitionLabelsMode -and
    -not $useBootstrapReleasePackMode -and (
        $UiContractJson -or
        $ListProfiles -or
        $ListHostHealthModes -or
        $ListAppTuningCatalog -or
        $ListApps -or
        $ListComponents -or
        $DryRun -or
        $Interactive -or
        $NonInteractive -or
        $Rollback -or
        $Audit -or
        $Repair -or
        [string]::IsNullOrWhiteSpace($HostHealth) -eq $false -or
        [string]::IsNullOrWhiteSpace($AppTuning) -eq $false -or
        (@($AppTuningCategory).Count -gt 0) -or
        (@($AppTuningItem).Count -gt 0) -or
        (@($ExcludeAppTuningItem).Count -gt 0) -or
        (@($App).Count -gt 0) -or
        (@($Profile).Count -gt 0) -or
        (@($Component).Count -gt 0) -or
        (@($Exclude).Count -gt 0)
    )
)

if (-not $isDotSourced) {
    try {
    if ($UiContractJson) {
        (Get-BootstrapUiContract | ConvertTo-Json -Depth 12)
        return
    }

    if ($BootstrapUiLibraryMode) {
        return
    }

    if ($useBootstrapDoctorMode) {
        try {
            Invoke-BootstrapDoctorMode
            Stop-BootstrapProcess 0
        } catch {
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{ phase = 'doctor' })
            }
            Write-Log $_.Exception.Message 'ERROR'
            Write-Log "Log salvo em: $script:LogPath" 'ERROR'
            Stop-BootstrapProcess 1
        }
    }

    if ($useBootstrapDriftCheckMode) {
        try {
            $drift = Invoke-BootstrapDriftCheck
            if (-not $drift.baselineExisted) {
                Write-Log 'Drift: baseline criado nesta execucao (primeira vez). Sem comparacao.'
            } elseif ([int]$drift.regressionCount -eq 0) {
                Write-Log 'Drift: nenhuma regressao detectada desde o baseline.'
            } else {
                Write-Log ("Drift: {0} regressao(oes) detectada(s): {1}" -f [int]$drift.regressionCount, ((@($drift.regressions) | ForEach-Object { "{0} ({1}->{2})" -f $_.id, $_.from, $_.to }) -join ', ')) 'WARN'
            }
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                Write-BootstrapExecutionResultFile -Path $script:ResultPath -Value ([ordered]@{ status = 'success'; exitCode = 0; mode = 'drift-check'; drift = $drift })
            }
            Stop-BootstrapProcess 0
        } catch {
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{ phase = 'drift-check' })
            }
            Write-Log $_.Exception.Message 'ERROR'
            Write-Log "Log salvo em: $script:LogPath" 'ERROR'
            Stop-BootstrapProcess 1
        }
    }

    if ($useBootstrapSupportBundleMode) {
        try {
            Invoke-BootstrapSupportBundleMode
            Stop-BootstrapProcess 0
        } catch {
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{ phase = 'support-bundle' })
            }
            Write-Log $_.Exception.Message 'ERROR'
            Write-Log "Log salvo em: $script:LogPath" 'ERROR'
            Stop-BootstrapProcess 1
        }
    }

    if ($useBootstrapAiConfigDoctorMode) {
        try {
            Invoke-BootstrapAiConfigDoctorMode
            Stop-BootstrapProcess 0
        } catch {
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{ phase = 'ai-config-doctor' })
            }
            Write-Log $_.Exception.Message 'ERROR'
            Write-Log "Log salvo em: $script:LogPath" 'ERROR'
            Stop-BootstrapProcess 1
        }
    }

    if ($useBootstrapAiConfigSyncMode) {
        try {
            Invoke-BootstrapAiConfigSyncMode
            Stop-BootstrapProcess 0
        } catch {
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{ phase = 'ai-config-sync' })
            }
            Write-Log $_.Exception.Message 'ERROR'
            Write-Log "Log salvo em: $script:LogPath" 'ERROR'
            Stop-BootstrapProcess 1
        }
    }

    if ($useBootstrapRepairPlanMode) {
        try {
            $repairModeResult = Invoke-BootstrapRepairPlanMode -ExecutePath $ExecuteRepairPlan
            Stop-BootstrapProcess ([int]$repairModeResult.ExitCode)
        } catch {
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{ phase = 'repair-plan' })
            }
            Write-Log $_.Exception.Message 'ERROR'
            Write-Log "Log salvo em: $script:LogPath" 'ERROR'
            Stop-BootstrapProcess 1
        }
    }

    if ($useBootstrapReleasePackMode) {
        try {
            Invoke-BootstrapReleasePackMode
            Stop-BootstrapProcess 0
        } catch {
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{ phase = 'release-pack' })
            }
            Write-Log $_.Exception.Message 'ERROR'
            Write-Log "Log salvo em: $script:LogPath" 'ERROR'
            Stop-BootstrapProcess 1
        }
    }

    if ($useBootstrapPartitionLabelsMode) {
        try {
            $partitionLabelsModeResult = Invoke-BootstrapPartitionLabelsMode -Apply:$ApplyPartitionLabels -DryRun:$DryRun
            Stop-BootstrapProcess ([int]$partitionLabelsModeResult['exitCode'])
        } catch {
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{ phase = 'partition-labels' })
            }
            Write-Log $_.Exception.Message 'ERROR'
            Write-Log "Log salvo em: $script:LogPath" 'ERROR'
            Stop-BootstrapProcess 1
        }
    }

    if ($useBootstrapSecretsMode) {
        try {
            Invoke-BootstrapSecretsMode
            Stop-BootstrapProcess 0
        } catch {
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{ phase = 'secrets' })
            }
            Write-Log $_.Exception.Message 'ERROR'
            Write-Log "Log salvo em: $script:LogPath" 'ERROR'
            Stop-BootstrapProcess 1
        }
    }

    if ($useBootstrapRotateSecretsMode) {
        try {
            $rotateOutput = Invoke-BootstrapRotateSecretsMode -Provider $RotateSecretsProvider -MaxItems $RotateSecretsMaxItems -TimeoutSeconds $RotateSecretsTimeoutSeconds -Schedule $RotateSecretsSchedule -DryRun:$DryRun
            Write-Output (($rotateOutput | ConvertTo-Json -Depth 6 -Compress))
            Stop-BootstrapProcess 0
        } catch {
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{ phase = 'rotate-secrets' })
            }
            Write-Log $_.Exception.Message 'ERROR'
            Write-Log "Log salvo em: $script:LogPath" 'ERROR'
            Stop-BootstrapProcess 1
        }
    }

    if ($useBootstrapProfileMode) {
        try {
            Invoke-BootstrapProfileMode
            Stop-BootstrapProcess 0
        } catch {
            $blockedInfo = Get-BootstrapBlockedErrorInfo -ErrorRecord $_
            if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
                Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{ phase = 'Invoke-BootstrapProfileMode-outer' })
            }
            if ($blockedInfo.IsBlocked) {
                Write-Log $_.Exception.Message 'WARN'
                Write-Log "Log salvo em: $script:LogPath" 'WARN'
            } else {
                Write-Log $_.Exception.Message 'ERROR'
                Write-Log "Log salvo em: $script:LogPath" 'ERROR'
            }
            Stop-BootstrapProcess 1
        }
    }

    try {
        Write-Log "Início: $($script:StartTime.ToString('s'))"
        Write-Log "Log: $script:LogPath"
        Write-Log "Result: $script:ResultPath"
        Write-Log "Admin: $(Test-IsAdmin)"
        Ensure-ProxyEnvFromWinHttp

        $winget = Ensure-Winget
        Refresh-SessionPath

        $gitInfo = Ensure-GitAndBash -WingetPath $winget
        Refresh-SessionPath

        $nodeInfo = Ensure-NodeAndNpm -WingetPath $winget
        Refresh-SessionPath

        Ensure-WingetPackage -WingetPath $winget -Id 'EclipseAdoptium.Temurin.17.JDK' -DisplayName 'Java JDK (Temurin 17)' -ProbePaths @("$env:ProgramFiles\Eclipse Adoptium\jdk-17*\bin\java.exe", "${env:ProgramFiles(x86)}\Eclipse Adoptium\jdk-17*\bin\java.exe")
        Ensure-WingetPackage -WingetPath $winget -Id 'ImageMagick.ImageMagick' -DisplayName 'ImageMagick' -ProbePaths @("$env:ProgramFiles\ImageMagick-*\magick.exe", "$env:ProgramFiles\ImageMagick\magick.exe")
        Ensure-WingetPackage -WingetPath $winget -Id '7zip.7zip' -DisplayName '7-Zip' -AllowFailureWhenNotAdmin $true -ProbePaths @("$env:ProgramFiles\7-Zip\7z.exe", "${env:ProgramFiles(x86)}\7-Zip\7z.exe")
        $sevenZipDir = $null
        try { $sevenZipDir = Join-Path $env:ProgramFiles '7-Zip' } catch { $sevenZipDir = $null }
        if ($sevenZipDir -and (Test-Path $sevenZipDir)) {
            Ensure-PathUserContains -Dir $sevenZipDir
            Refresh-SessionPath
        }
        Ensure-Python -WingetPath $winget
        Refresh-SessionPath

        Ensure-OpenCode -BashPath $gitInfo.Bash
        Refresh-SessionPath

        Ensure-ClaudeCode -WingetPath $winget
        Refresh-SessionPath

        Ensure-WingetPackage -WingetPath $winget -Id 'GitHub.cli' -DisplayName 'GitHub CLI (gh)' -ProbePaths @("$env:ProgramFiles\GitHub CLI\gh.exe", "${env:LOCALAPPDATA}\Programs\GitHub CLI\gh.exe", "${env:LOCALAPPDATA}\Microsoft\WinGet\Links\gh.exe", "$env:ProgramFiles\WinGet\Links\gh.exe")
        Refresh-SessionPath

        Ensure-WingetPackage -WingetPath $winget -Id 'Google.Chrome' -DisplayName 'ChromeSetup (Google Chrome)' -AllowFailureWhenNotAdmin $true -ProbePaths @("$env:ProgramFiles\Google\Chrome\Application\chrome.exe", "${env:ProgramFiles(x86)}\Google\Chrome\Application\chrome.exe", "${env:LOCALAPPDATA}\Google\Chrome\Application\chrome.exe")
        Ensure-WingetPackage -WingetPath $winget -Id 'Notepad++.Notepad++' -DisplayName 'Notepad++' -AllowFailureWhenNotAdmin $true -ProbePaths @(Get-BootstrapNotepadPlusPlusProbePaths)
        Ensure-WingetPackage -WingetPath $winget -Id 'Anthropic.Claude' -DisplayName 'Claude Setup (Claude Desktop)' -AllowFailureWhenNotAdmin $true
        Ensure-WingetPackage -WingetPath $winget -Id 'Anysphere.Cursor' -DisplayName 'CursorUserSetup (Cursor)' -AllowFailureWhenNotAdmin $true
        Ensure-WingetPackage -WingetPath $winget -Id 'Codeium.Windsurf' -DisplayName 'WindsurfUserSetup (Windsurf)' -AllowFailureWhenNotAdmin $true
        Ensure-WingetPackage -WingetPath $winget -Id 'Warp.Warp' -DisplayName 'WarpSetup (Warp)' -AllowFailureWhenNotAdmin $true
        Ensure-WingetPackage -WingetPath $winget -Id 'ByteDance.Trae' -DisplayName 'Trae-Setup (Trae)' -AllowFailureWhenNotAdmin $true
        Ensure-WingetPackage -WingetPath $winget -Id 'SST.OpenCodeDesktop' -DisplayName 'opencode-desktop-windows (OpenCode Desktop)' -AllowFailureWhenNotAdmin $true
        Ensure-WingetPackage -WingetPath $winget -Id 'Microsoft.VisualStudioCode.Insiders' -DisplayName 'Visual Studio Code - Insiders' -AllowFailureWhenNotAdmin $true
        Ensure-WslUi -WingetPath $winget
        Ensure-WingetPackage -WingetPath $winget -Id 'Google.Antigravity' -DisplayName 'Antigravity.exe' -AllowFailureWhenNotAdmin $true
        Ensure-WingetPackage -WingetPath $winget -Id 'ZhipuAI.AutoClaw' -DisplayName 'autoclaw (AutoClaw)' -AllowFailureWhenNotAdmin $true
        Ensure-WingetPackage -WingetPath $winget -Id 'Perplexity.Comet' -DisplayName 'Perplexity (Comet)' -AllowFailureWhenNotAdmin $true
        Ensure-CodexInstaller -WingetPath $winget
        Refresh-SessionPath

        Ensure-NpmGlobalPackage -NpmCmd $nodeInfo.NpmCmd -Package '@google/gemini-cli' -DisplayName 'Gemini CLI (@google/gemini-cli)'
        Ensure-NpmGlobalPackage -NpmCmd $nodeInfo.NpmCmd -Package '@kilocode/cli' -DisplayName 'Kilo CLI (@kilocode/cli)'
        Ensure-NpmGlobalPackage -NpmCmd $nodeInfo.NpmCmd -Package '@bonsai-ai/cli' -DisplayName 'Bonsai CLI (@bonsai-ai/cli)'
        Ensure-NpmGlobalPackage -NpmCmd $nodeInfo.NpmCmd -Package '@vibe-kit/grok-cli' -DisplayName 'Grok CLI (@vibe-kit/grok-cli)'
        Ensure-NpmGlobalPackage -NpmCmd $nodeInfo.NpmCmd -Package '@qwen-code/qwen-code@latest' -DisplayName 'Qwen Code (@qwen-code/qwen-code)'
        Ensure-NpmGlobalPackage -NpmCmd $nodeInfo.NpmCmd -Package '@github/copilot' -DisplayName 'GitHub Copilot CLI (@github/copilot)'
        Ensure-NpmGlobalPackage -NpmCmd $nodeInfo.NpmCmd -Package '@openai/codex' -DisplayName 'OpenAI Codex CLI (@openai/codex)'
        Write-Log 'OpenClaw skipped: connection-grant-not-enforceable; no account grant is bound to each request.' 'WARN'
        Ensure-Hermes -State @{ NodeInfo = $nodeInfo; CloneBaseDir = $CloneBaseDir }
        Refresh-SessionPath

        Ensure-ClaudeCodeDefaults -GitBashPath $gitInfo.Bash
        Refresh-SessionPath

        Ensure-ClaudeHookConfigsHealthy -GitBashPath $gitInfo.Bash
        Refresh-SessionPath

        Ensure-Aider
        Refresh-SessionPath

        Ensure-Goose -BashPath $gitInfo.Bash
        Refresh-SessionPath

        $repoDir = Join-Path $CloneBaseDir 'gemini-cli'
        Ensure-RepoClone -GitExe $gitInfo.Git -RepoUrl 'https://github.com/heartyguy/gemini-cli' -TargetDir $repoDir

        $opencodeExe = Join-Path (Join-Path (Get-BootstrapUserHomePath) '.opencode\bin') 'opencode.exe'
        $geminiCmd = Join-Path $nodeInfo.NpmBin 'gemini.cmd'
        $kiloCmd = Join-Path $nodeInfo.NpmBin 'kilo.cmd'
        $bonsaiCmd = Join-Path $nodeInfo.NpmBin 'bonsai.cmd'
        $grokCmd = Join-Path $nodeInfo.NpmBin 'grok.cmd'
        $qwenCmd = Join-Path $nodeInfo.NpmBin 'qwen.cmd'
        $copilotCmd = Join-Path $nodeInfo.NpmBin 'copilot.cmd'
        $codexCmd = Join-Path $nodeInfo.NpmBin 'codex.cmd'
        $openclawCmd = Join-Path $nodeInfo.NpmBin 'openclaw.cmd'
        $hermesCmd = Join-Path $nodeInfo.NpmBin 'hermes.cmd'

        Write-Log 'Resumo:'
        Write-Log "CLAUDE_CODE_GIT_BASH_PATH: $([Environment]::GetEnvironmentVariable('CLAUDE_CODE_GIT_BASH_PATH','User'))"
        Write-Log "git: $(& $gitInfo.Git --version)"
        Write-Log "node: $(& $nodeInfo.Node -v)"
        Write-Log "npm: $(& $nodeInfo.NpmCmd --version)"
        $javaExe = Resolve-CommandPath -Name 'java'
        if ($javaExe) { Write-Log "java: $(Invoke-NativeFirstLine -Exe $javaExe -Args @('-version'))" } else { Write-Log 'java: NÃO ENCONTRADO' 'WARN' }
        $magickExe = Resolve-CommandPath -Name 'magick'
        if ($magickExe) { Write-Log "magick: $(Invoke-NativeFirstLine -Exe $magickExe -Args @('-version'))" } else { Write-Log 'magick: NÃO ENCONTRADO' 'WARN' }
        $sevenZipExe = Resolve-CommandPath -Name '7z'
        if ($sevenZipExe) { Write-Log "7z: $(Invoke-NativeFirstLine -Exe $sevenZipExe -Args @()) ($sevenZipExe)" } else { Write-Log '7z: NÃO ENCONTRADO' 'WARN' }
        $pythonExe = Resolve-CommandPath -Name 'python'
        if ($pythonExe) { Write-Log "python: $(Invoke-NativeFirstLine -Exe $pythonExe -Args @('--version')) ($pythonExe)" } else { Write-Log 'python: NÃO ENCONTRADO' 'WARN' }
        $pipExe = Resolve-CommandPath -Name 'pip'
        if ($pipExe) { Write-Log "pip: $(Invoke-NativeFirstLine -Exe $pipExe -Args @('--version')) ($pipExe)" } else { Write-Log 'pip: NÃO ENCONTRADO' 'WARN' }
        $claudeExe = Resolve-CommandPath -Name 'claude'
        if ($claudeExe) { Write-Log "claude: $(Invoke-NativeFirstLine -Exe $claudeExe -Args @('--version')) ($claudeExe)" } else { Write-Log 'claude: NÃO ENCONTRADO' 'WARN' }
        $ghExe = Resolve-CommandPath -Name 'gh'
        if ($ghExe) { Write-Log "gh: $(Invoke-NativeFirstLine -Exe $ghExe -Args @('--version')) ($ghExe)" } else { Write-Log 'gh: NÃO ENCONTRADO' 'WARN' }
        if (Test-Path $opencodeExe) { Write-Log "opencode: $(& $opencodeExe --version) ($opencodeExe)" } else { Write-Log "opencode: NÃO ENCONTRADO ($opencodeExe)" 'WARN' }
        if (Test-Path $geminiCmd) { Write-Log "gemini: $(& $geminiCmd --version) ($geminiCmd)" } else { Write-Log "gemini: NÃO ENCONTRADO ($geminiCmd)" 'WARN' }
        if (Test-Path $kiloCmd) { Write-Log "kilo: $(& $kiloCmd --version) ($kiloCmd)" } else { Write-Log "kilo: NÃO ENCONTRADO ($kiloCmd)" 'WARN' }
        if (Test-Path $bonsaiCmd) { Write-Log "bonsai: instalado ($bonsaiCmd)" } else { Write-Log "bonsai: NÃO ENCONTRADO ($bonsaiCmd)" 'WARN' }
        if (Test-Path $grokCmd) { Write-Log "grok: $(& $grokCmd --version) ($grokCmd)" } else { Write-Log "grok: NÃO ENCONTRADO ($grokCmd)" 'WARN' }
        if (Test-Path $qwenCmd) { Write-Log "qwen: $(Invoke-NativeFirstLine -Exe $qwenCmd -Args @('--version')) ($qwenCmd)" } else { Write-Log "qwen: NÃO ENCONTRADO ($qwenCmd)" 'WARN' }
        if (Test-Path $copilotCmd) { Write-Log "copilot: $(Invoke-NativeFirstLine -Exe $copilotCmd -Args @('--version')) ($copilotCmd)" } else { Write-Log "copilot: NÃO ENCONTRADO ($copilotCmd)" 'WARN' }
        if (Test-Path $codexCmd) { Write-Log "codex: $(Invoke-NativeFirstLine -Exe $codexCmd -Args @('--version')) ($codexCmd)" } else { Write-Log "codex: NÃO ENCONTRADO ($codexCmd)" 'WARN' }
        $codexPath = Resolve-CommandPath -Name 'codex'
        if ($codexPath) {
            $ext = ([IO.Path]::GetExtension($codexPath)).ToLowerInvariant()
            if (($ext -eq '.exe') -and (-not (Test-Path $codexCmd))) {
                Write-Log "codex (PATH) aponta para um .exe ($codexPath). Se o Codex Desktop estiver crashando, priorize o codex.cmd do npm para CLI e ajuste o config.toml do app." 'WARN'
            } else {
                Write-Log "codex (PATH): $codexPath"
            }
        }
        if (Test-Path $openclawCmd) { Write-Log "openclaw: detectado ($openclawCmd); uso bloqueado sem grant por requisição" 'WARN' } else { Write-Log "openclaw: NÃO ENCONTRADO ($openclawCmd)" 'WARN' }
        if (Test-Path $hermesCmd) { Write-Log "hermes: $(& $hermesCmd --version) ($hermesCmd)" } else { Write-Log "hermes: NÃO ENCONTRADO ($hermesCmd)" 'WARN' }
        $aiderExe = Resolve-CommandPath -Name 'aider'
        if ($aiderExe) { Write-Log "aider: $(Invoke-NativeFirstLine -Exe $aiderExe -Args @('--version')) ($aiderExe)" } else { Write-Log 'aider: NÃO ENCONTRADO' 'WARN' }
        $gooseExe = Resolve-CommandPath -Name 'goose'
        if ($gooseExe) { Write-Log "goose: $(Invoke-NativeFirstLine -Exe $gooseExe -Args @('--version')) ($gooseExe)" } else { Write-Log 'goose: NÃO ENCONTRADO' 'WARN' }
        $desktopWinget = @(
            @{ Name = 'ChromeSetup'; Id = 'Google.Chrome' },
            @{ Name = 'Notepad++'; Id = 'Notepad++.Notepad++' },
            @{ Name = 'Claude Setup'; Id = 'Anthropic.Claude' },
            @{ Name = 'CursorUserSetup'; Id = 'Anysphere.Cursor' },
            @{ Name = 'WindsurfUserSetup'; Id = 'Codeium.Windsurf' },
            @{ Name = 'WarpSetup'; Id = 'Warp.Warp' },
            @{ Name = 'Trae-Setup'; Id = 'ByteDance.Trae' },
            @{ Name = 'opencode-desktop-windows'; Id = 'SST.OpenCodeDesktop' },
            @{ Name = 'Visual Studio Code - Insiders'; Id = 'Microsoft.VisualStudioCode.Insiders' },
            @{ Name = 'WSL UI'; Id = 'OctasoftLtd.WSLUI' },
            @{ Name = 'Antigravity.exe'; Id = 'Google.Antigravity' },
            @{ Name = 'autoclaw'; Id = 'ZhipuAI.AutoClaw' },
            @{ Name = 'Perplexity'; Id = 'Perplexity.Comet' },
            @{ Name = 'Codex Installer'; Id = 'OpenAI.Codex' }
        )
        foreach ($app in $desktopWinget) {
            $ok = Test-WingetPackageInstalled -WingetPath $winget -Id $app.Id
            if ($ok) {
                Write-Log ("desktop: {0} (winget: {1})" -f $app.Name, $app.Id)
            } else {
                Write-Log ("desktop: {0} NÃO ENCONTRADO (winget: {1})" -f $app.Name, $app.Id) 'WARN'
            }
        }
        Write-Log "repo gemini-cli: $repoDir (exists=$(Test-Path $repoDir))"

        $elapsed = New-TimeSpan -Start $script:StartTime -End (Get-Date)
        Write-Log ("Concluído em {0:c}" -f $elapsed)
        Write-Log "Log salvo em: $script:LogPath"
    } catch {
        if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
            Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{ phase = 'legacy-bootstrap-flow' })
        }
        Write-Log $_.Exception.Message 'ERROR'
        Write-Log "Log salvo em: $script:LogPath" 'ERROR'
        Stop-BootstrapProcess 1
    }
    } catch {
        $blockedInfo = Get-BootstrapBlockedErrorInfo -ErrorRecord $_
        if (-not [string]::IsNullOrWhiteSpace($script:ResultPath)) {
            try { Write-BootstrapExecutionErrorResultFromRecord -Path $script:ResultPath -ErrorRecord $_ -Extra ([ordered]@{ phase = 'top-level' }) } catch { }
        }
        try {
            if ($blockedInfo.IsBlocked) {
                Write-Log $_.Exception.Message 'WARN'
                Write-Log "Log salvo em: $script:LogPath" 'WARN'
            } else {
                Write-Log $_.Exception.Message 'ERROR'
                Write-Log "Log salvo em: $script:LogPath" 'ERROR'
            }
        } catch { }
        Stop-BootstrapProcess 1
    }
}
